def _ensure_cobra():
    """Load cobra on first use. Returns True if available."""
    global HAS_COBRA, cobra, Model, Reaction, Metabolite
    if HAS_COBRA is None:
        try:
            import cobra as _cobra
            from cobra import Model as _M, Reaction as _R, Metabolite as _Me
            cobra = _cobra; Model = _M; Reaction = _R; Metabolite = _Me
            HAS_COBRA = True
        except Exception as _exc:
            biosim_log('warn', '_ensure_cobra: {}'.format(_exc))
            HAS_COBRA = False
    return HAS_COBRA


