def biosim_theme(key):
    """Get a structural colour for the current theme mode."""
    return BIOSIM_THEMES.get(BIOSIM_THEME_MODE, BIOSIM_THEMES['light']).get(key, '#000000')


def _hex_luminance(hex_color):
    """Rough perceived luminance 0..1 of a #rrggbb colour (for contrast choice)."""
    try:
        h = hex_color.lstrip('#')
        if len(h) == 3:
            h = ''.join( c * 2 for c in h)
        r = int(h[0:2], 16) / 255.0
        g = int(h[2:4], 16) / 255.0
        b = int(h[4:6], 16) / 255.0
        return 0.2126 * r + 0.7152 * g + 0.0722 * b
    except Exception:
        return 0.5


def readable_text_on(bg_hex):
    """Return a readable text colour (dark or light) for the given background.
    Dark text on light backgrounds, light text on dark backgrounds."""
    return '#101014' if _hex_luminance(bg_hex) > 0.55 else '#ffffff'


def style_button(btn, kind='normal'):
    """Apply the flat, modern button style (Ocean / Graphite-Neon) to a tk.Button.

    kind:
      'primary' — filled accent (main actions, e.g. Run)
      'accent2' — filled secondary accent (e.g. Analyse)
      'danger'  — filled danger (e.g. Delete / Reset-destructive)
      'normal'  — soft button: light bg, no grey border, themed text
      'ghost'   — flat, panel-coloured, minimal

    Removes the old grey Windows-style border (bd/highlight) across the board.
    """
    try:
        if kind == 'primary':
            bg = biosim_theme('accent'); fg = biosim_theme('accent_text')
            abg = bg
        elif kind == 'accent2':
            bg = biosim_theme('accent2'); fg = biosim_theme('accent2_text')
            abg = bg
        elif kind == 'danger':
            bg = biosim_theme('danger'); fg = biosim_theme('danger_text')
            abg = bg
        elif kind == 'ghost':
            bg = biosim_theme('panel'); fg = biosim_theme('text')
            abg = biosim_theme('panel2')
        else:  # normal
            bg = biosim_theme('btn_bg'); fg = biosim_theme('btn_text')
            abg = biosim_theme('panel2')
        btn.configure(
            bg=bg, fg=fg, activebackground=abg, activeforeground=fg,
            relief='flat', bd=0, highlightthickness=0,
            highlightbackground=bg, highlightcolor=bg,
            cursor='hand2',
        )
        # On macOS tk.Button bg is often ignored unless highlightbackground set.
        btn.configure(highlightbackground=bg)
    except Exception:
        pass
    return btn


# Preferred UI font (modern, non-"Windows"). On macOS Helvetica Neue reads clean.
BIOSIM_FONT = 'Helvetica Neue'
