def set_biosim_theme(mode):
    """Set the shared theme mode ('light' or 'dark'). Updates the module-level
    colour constants so existing code that reads BIOSIM_BG etc. also follows."""
    global BIOSIM_THEME_MODE, BIOSIM_BG, BIOSIM_PLOT_BG, BIOSIM_GRID
    global BIOSIM_SPINE, BIOSIM_TEXT, BIOSIM_MUTED
    if mode not in BIOSIM_THEMES:
        mode = 'light'
    BIOSIM_THEME_MODE = mode
    BIOSIM_BG = biosim_theme('bg')
    BIOSIM_PLOT_BG = biosim_theme('plot_bg')
    BIOSIM_GRID = biosim_theme('grid')
    BIOSIM_SPINE = biosim_theme('spine')
    BIOSIM_TEXT = biosim_theme('text')
    BIOSIM_MUTED = biosim_theme('text_dim')


# Module-level constants (updated by set_biosim_theme). Default = light.
BIOSIM_BG = '#f5f7fa'
BIOSIM_PLOT_BG = '#ffffff'
BIOSIM_GRID = '#eef1f5'
BIOSIM_SPINE = '#d0d7de'
BIOSIM_TEXT = '#1c2128'
BIOSIM_MUTED = '#57606a'


def style_biosim_axes(ax, title=None, xlabel=None, ylabel=None):
    """Apply the unified VIREON style to a matplotlib Axes. Call after plotting
    so every chart in the program looks like one product."""
    try:
        ax.set_facecolor(BIOSIM_PLOT_BG)
        if title:
            ax.set_title(title, color=BIOSIM_TEXT, fontsize=12, fontweight='bold')
        if xlabel:
            ax.set_xlabel(xlabel, color=BIOSIM_MUTED, fontsize=10)
        if ylabel:
            ax.set_ylabel(ylabel, color=BIOSIM_MUTED, fontsize=10)
        ax.tick_params(colors=BIOSIM_MUTED, labelsize=9)
        ax.grid(True, color=BIOSIM_GRID, linewidth=0.7, alpha=0.9)
        ax.set_axisbelow(True)
        for spine in ax.spines.values():
            spine.set_color(BIOSIM_SPINE)
        # Hide top/right spines for a cleaner look
        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
    except Exception as _exc:
        biosim_log('warn', 'style_biosim_axes: {}'.format(_exc))
    return ax


def new_biosim_figure(figsize=(7, 4.2)):
    """Create a matplotlib Figure pre-styled with the VIREON look.
    Returns (fig, ax)."""
    import matplotlib.pyplot as plt
    fig = plt.Figure(figsize=figsize, facecolor=BIOSIM_BG, dpi=100)
    ax = fig.add_subplot(111)
    style_biosim_axes(ax)
    return fig, ax


def export_figure_highres(fig, filepath, dpi=300):
    """Export any matplotlib figure to a high-resolution file (PNG/SVG/PDF)
    for publications or presentations. Format inferred from extension.
    Returns (success, message)."""
    try:
        ext = filepath.lower().rsplit('.', 1)[-1] if '.' in filepath else 'png'
        if ext == 'svg':
            fig.savefig(filepath, format='svg', bbox_inches='tight',
                        facecolor=fig.get_facecolor())
        elif ext == 'pdf':
            fig.savefig(filepath, format='pdf', bbox_inches='tight',
                        facecolor=fig.get_facecolor())
        else:
            fig.savefig(filepath, format='png', dpi=dpi, bbox_inches='tight',
                        facecolor=fig.get_facecolor())
        return True, 'Saved: ' + filepath
    except Exception as e:
        biosim_log('warn', 'export_figure_highres: {}'.format(e))
        return False, 'Export error: ' + str(e)[:100]


def add_chart_export_button(parent_widget, fig, lang='ru'):
    """Add a 'Save chart' button under a chart that exports it in high-res.
    Returns the button widget."""
    import tkinter as _tk
    from tkinter import filedialog as _fd, messagebox as _mb
    is_ru = (lang == 'ru')

    def do_export():
        fp = _fd.asksaveasfilename(
            defaultextension='.png',
            filetypes=[('PNG (300 dpi)', '*.png'), ('SVG vector', '*.svg'),
                       ('PDF', '*.pdf')])
        if not fp:
            return
        ok, msg = export_figure_highres(fig, fp)
        if ok:
            _mb.showinfo('VIREON', ('График сохранён:\n' if is_ru
                                    else 'Chart saved:\n') + fp)
        else:
            _mb.showerror('VIREON', msg)

    btn = _tk.Button(parent_widget,
                     text=('💾 Сохранить график (300 dpi)' if is_ru
                           else '💾 Save chart (300 dpi)'),
                     bg=biosim_theme('panel'), highlightbackground='#1a7f37', fg='#1a7f37',
                     relief='solid', bd=1, font=('Arial', 9, 'bold'),
                     cursor='hand2', command=do_export)
    return btn


def make_empty_state(parent_widget, icon, title, hint, lang='ru'):
    """Create a friendly 'empty state' panel shown when a section has no data
    yet. Gives the user a starting point. Returns the frame."""
    import tkinter as _tk
    frame = _tk.Frame(parent_widget, bg=BIOSIM_BG)
    _tk.Label(frame, text=icon, bg=BIOSIM_BG, fg=BIOSIM_MUTED,
              font=('Arial', 40)).pack(pady=(40, 8))
    _tk.Label(frame, text=title, bg=BIOSIM_BG, fg=BIOSIM_TEXT,
              font=('Arial', 13, 'bold')).pack(pady=2)
    _tk.Label(frame, text=hint, bg=BIOSIM_BG, fg=BIOSIM_MUTED,
              font=('Arial', 10), justify='center', wraplength=360).pack(pady=2)
    return frame


