# ─────────────────────────────────────────────────
# In-memory cache to avoid re-searching same queries
_SEARCH_CACHE = {}
_SEARCH_CACHE_MAX = 50


def fetch_disease_full_info(name, lang='en'):
    """Fetch comprehensive disease info from multiple sources.
    
    Returns dict with:
        summary_en, summary_ru: paragraph descriptions
        genes: list of associated genes
        proteins: list of protein names with functions
        organs: detected affected organs
        symptoms: list of symptoms
        synonyms: alternative names
        causes: etiology / causes
        treatment: treatment options summary
        category: disease category
        wikidata_id, omim_id: cross-references
    """
    info = {
        'name': name,
        'summary_en': '', 'summary_ru': '',
        'genes': [], 'proteins': [],
        'organs': [], 'symptoms': [], 'synonyms': [],
        'causes': '', 'treatment': '',
        'category': '', 'wikidata_id': '',
        'omim_id': '',
        'severity': 3,
    }
    
    # 1. Wikipedia EN summary (full extract)
    try:
        enc = urllib.parse.quote(name.replace(' ', '_'))
        wiki_url = ('https://en.wikipedia.org/w/api.php'
                     '?action=query&format=json&prop=extracts|categories|info|pageprops'
                     '&exintro=1&explaintext=1&inprop=url'
                     '&titles=' + enc + '&redirects=1')
        data = _get(wiki_url)
        if data:
            pages = data.get('query', {}).get('pages', {})
            for pid, page in pages.items():
                if pid == '-1':
                    continue
                extract = page.get('extract', '')
                if extract:
                    info['summary_en'] = extract[:2500]
                # Categories often give clues
                cats = page.get('categories', [])
                cat_strs = [c.get('title', '') for c in cats]
                # Pageprops for wikidata
                pp = page.get('pageprops', {})
                if 'wikibase_item' in pp:
                    info['wikidata_id'] = pp['wikibase_item']
                break
    except Exception as e:
        print('[INFO] wiki-en err:', e)
    
    # 2. Wikipedia RU summary (Russian text)
    try:
        ru_name = name
        # If we got the title from EN search, try Russian Wikipedia
        enc_ru = urllib.parse.quote(name.replace(' ', '_'))
        wiki_url_ru = ('https://ru.wikipedia.org/w/api.php'
                        '?action=query&format=json&prop=extracts'
                        '&exintro=1&explaintext=1'
                        '&titles=' + enc_ru + '&redirects=1')
        data_ru = _get(wiki_url_ru)
        if data_ru:
            pages = data_ru.get('query', {}).get('pages', {})
            for pid, page in pages.items():
                if pid == '-1':
                    continue
                extract = page.get('extract', '')
                if extract:
                    info['summary_ru'] = extract[:2500]
                break
        # If no RU page, try to find via langlinks from EN
        if not info['summary_ru'] and info.get('wikidata_id'):
            wd_url = ('https://en.wikipedia.org/w/api.php'
                       '?action=query&format=json&prop=langlinks'
                       '&lllang=ru&titles=' + urllib.parse.quote(name.replace(' ', '_')))
            wd_data = _get(wd_url)
            if wd_data:
                pages = wd_data.get('query', {}).get('pages', {})
                for pid, page in pages.items():
                    ll = page.get('langlinks', [])
                    if ll:
                        ru_title = ll[0].get('*', '')
                        if ru_title:
                            # Now fetch RU extract for that title
                            enc_ru2 = urllib.parse.quote(ru_title.replace(' ', '_'))
                            wiki_url_ru2 = ('https://ru.wikipedia.org/w/api.php'
                                              '?action=query&format=json&prop=extracts'
                                              '&exintro=1&explaintext=1'
                                              '&titles=' + enc_ru2 + '&redirects=1')
                            d2 = _get(wiki_url_ru2)
                            if d2:
                                p2 = d2.get('query', {}).get('pages', {})
                                for _, pg in p2.items():
                                    ex = pg.get('extract', '')
                                    if ex:
                                        info['summary_ru'] = ex[:2500]
                                        break
    except Exception as e:
        print('[INFO] wiki-ru err:', e)
    
    # 3. Genes from UniProt
    info['genes'] = fetch_disease_genes(name)
    
    # 4. Proteins from UniProt with descriptions
    try:
        enc = urllib.parse.quote(name)
        url = ('https://rest.uniprot.org/uniprotkb/search?query=cc_disease:%22{}%22'
                '+AND+organism_id:9606&format=json&size=10'
                '&fields=accession,protein_name,gene_names,cc_function').format(enc)
        data = _get(url)
        if data:
            for entry in data.get('results', [])[:10]:
                acc = entry.get('primaryAccession', '')
                prot_name = entry.get('proteinDescription', {})\
                    .get('recommendedName', {}).get('fullName', {}).get('value', '')
                if not prot_name:
                    prot_name = acc
                # Function from comments
                func = ''
                for comment in entry.get('comments', []):
                    if comment.get('commentType') == 'FUNCTION':
                        texts = comment.get('texts', [])
                        if texts:
                            func = texts[0].get('value', '')[:300]
                            break
                info['proteins'].append({
                    'accession': acc,
                    'name': prot_name,
                    'function': func,
                })
    except Exception as e:
        print('[INFO] proteins err:', e)
    
    # 5. Extract organs and symptoms from summary
    summary = (info['summary_en'] + ' ' + info['summary_ru'] + ' ' + name).lower()
    
    organ_keywords = {
        'Lungs / Лёгкие':       ['lung', 'pulmon', 'respirat', 'bronch',
                                      'лёг', 'лег', 'дыха', 'пульмон', 'бронх'],
        'Heart / Сердце':       ['heart', 'cardiac', 'cardio', 'myocard',
                                      'серд', 'миокард', 'кардио', 'инфаркт'],
        'Liver / Печень':       ['liver', 'hepatic', 'cirrhosis',
                                      'печен', 'цирроз', 'гепати'],
        'Kidneys / Почки':      ['kidney', 'renal', 'nephro',
                                      'почек', 'почк', 'нефро', 'нефрит'],
        'Brain / Мозг':         ['brain', 'cerebr', 'neuro', 'neural',
                                      'мозг', 'мозга', 'нейр', 'невро', 'мозговы'],
        'Pancreas / Поджелудочная': ['pancrea', 'diabet', 'insulin',
                                            'подж', 'диабет', 'инсулин'],
        'Skin / Кожа':          ['skin', 'derma', 'cutaneous',
                                      'кожи', 'кож', 'кожн', 'дерма'],
        'Bone / Кости':         ['bone', 'skeletal', 'osteo',
                                      'кост', 'остео'],
        'Blood / Кровь':        ['blood', 'hematol', 'anemia', 'leukemia',
                                      'кров', 'крови', 'гематол', 'лейкемия', 'анемия'],
        'Immune / Иммунитет':   ['immun', 'autoimmun', 'lymph',
                                      'иммун', 'аутоимм', 'лимфо'],
        'Eyes / Глаза':         ['eye', 'retina', 'ocular',
                                      'глаз', 'сетчат', 'окул'],
        'Stomach / Желудок':    ['stomach', 'gastric', 'gut',
                                      'желуд', 'гастрит', 'гастри'],
        'Intestine / Кишечник': ['intestin', 'colon', 'bowel',
                                      'кишеч', 'кишк', 'колон'],
        'Muscles / Мышцы':      ['muscle', 'myopath', 'muscular',
                                      'мышц', 'миопат'],
        'Joints / Суставы':     ['joint', 'arthriti', 'arthr',
                                      'сустав', 'артрит'],
        'Thyroid / Щитовидная': ['thyroid', 'goiter',
                                      'щитовид', 'тирео'],
    }
    for organ, keywords in organ_keywords.items():
        if any(kw in summary for kw in keywords):
            info['organs'].append(organ)
    
    # Symptom keywords
    symptom_patterns = {
        'Fever / Лихорадка': ['fever', 'pyrex', 'лихорад', 'температур'],
        'Pain / Боль': ['pain', 'ache', 'боль', 'болезнен'],
        'Fatigue / Усталость': ['fatigue', 'tired', 'устал', 'утомля'],
        'Inflammation / Воспаление': ['inflam', 'swell', 'воспал', 'отёк', 'отек'],
        'Cough / Кашель': ['cough', 'кашель'],
        'Bleeding / Кровотечение': ['bleed', 'hemorrh', 'кровотеч', 'кровоиз'],
        'Weight loss / Потеря веса': ['weight loss', 'wasting', 'потер веса', 'похудан'],
        'Nausea / Тошнота': ['nausea', 'vomit', 'тошнот', 'рвот'],
        'Headache / Головная боль': ['headache', 'голов'],
        'Confusion / Спутанность': ['confusion', 'delir', 'спутан', 'бред'],
        'Seizures / Судороги': ['seizur', 'convuls', 'судорог', 'припад'],
        'Rash / Сыпь': ['rash', 'eruption', 'сыпь', 'высыпан'],
    }
    for s, kw in symptom_patterns.items():
        if any(k in summary for k in kw):
            info['symptoms'].append(s)
    
    # Severity from keywords
    if any(w in summary for w in ['fatal', 'lethal', 'mortality', 'смертельн', 'фатальн', 'летальн']):
        info['severity'] = 5
    elif any(w in summary for w in ['cancer', 'malignant', 'tumor', 'рак', 'злокачест', 'опухоль']):
        info['severity'] = 5
    elif any(w in summary for w in ['chronic', 'хроническ']):
        info['severity'] = 4
    elif any(w in summary for w in ['acute', 'severe', 'остр', 'тяжёл', 'тяжел']):
        info['severity'] = 4
    elif any(w in summary for w in ['mild', 'лёгк', 'легк']):
        info['severity'] = 2
    
    # 6. OMIM cross-reference (via NCBI)
    try:
        enc = urllib.parse.quote(name)
        url = ('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
                '?db=omim&term=' + enc + '&retmax=1&retmode=json')
        data = _get(url)
        if data:
            ids = data.get('esearchresult', {}).get('idlist', [])
            if ids:
                info['omim_id'] = ids[0]
    except Exception as e:
        print('[INFO] omim err:', e)
    
    return info


