def search_diseases(query, local_db, max_res=80):
    """Search diseases from local DB + Wikipedia + EBI + PubMed (parallel).
    Cached to avoid duplicate network calls."""
    cache_key = query.strip().lower()
    if cache_key in _SEARCH_CACHE:
        print('[SEARCH] cache hit: ' + repr(cache_key))
        return list(_SEARCH_CACHE[cache_key])[:max_res]
    results = _search_impl(query, local_db, max_res)
    if len(_SEARCH_CACHE) >= _SEARCH_CACHE_MAX:
        try:
            del _SEARCH_CACHE[next(iter(_SEARCH_CACHE))]
        except Exception as _exc:
            biosim_log('warn', 'search_diseases: {}'.format(_exc))
            _SEARCH_CACHE.clear()
    _SEARCH_CACHE[cache_key] = list(results)
    return results


def _search_impl(query, local_db, max_res=80):
    """Parallel search: all APIs run at once, wait max 10 sec."""
    results = []
    seen = set()
    q_lower = query.lower().strip()
    print('\n[SEARCH] query=' + repr(query))

    # 1. Local DB (instant)
    for key, d in local_db.items():
        if q_lower in d['en'].lower() or q_lower in d['ru'].lower():
            if key not in seen:
                seen.add(key)
                results.append({
                    'key': key, 'en': d['en'], 'ru': d['ru'],
                    'src': 'local', 'genes': d['genes'], 'desc': d['desc_en']
                })
    print('[SEARCH] local DB: {} results'.format(len(results)))

    if len(query) < 2:
        return results

    has_cyrillic = any('\u0400' <= ch <= '\u04FF' for ch in query)
    en_query = query
    if has_cyrillic:
        for ru_word, en_word in DISEASE_TRANSLATIONS.items():
            if ru_word in q_lower:
                en_query = q_lower.replace(ru_word, en_word)
                break

    # Parallel API fetches
    api_results = {}

    def fetch_wiki_ru():
        try:
            enc = urllib.parse.quote(query)
            return _get('https://ru.wikipedia.org/w/api.php?action=opensearch&search={}&limit=15&format=json&namespace=0'.format(enc))
        except Exception as _exc:
            biosim_log('warn', 'fetch_wiki_ru: {}'.format(_exc))
            return None

    def fetch_wiki_en():
        try:
            enc = urllib.parse.quote(en_query)
            return _get('https://en.wikipedia.org/w/api.php?action=opensearch&search={}&limit=15&format=json&namespace=0'.format(enc))
        except Exception as _exc:
            biosim_log('warn', 'fetch_wiki_en: {}'.format(_exc))
            return None

    def fetch_ebi():
        try:
            enc = urllib.parse.quote(en_query)
            return _get('https://www.ebi.ac.uk/ols/api/search?q={}&ontology=mondo,doid&rows=20'.format(enc))
        except Exception as _exc:
            biosim_log('warn', 'fetch_ebi: {}'.format(_exc))
            return None

    def fetch_pubmed():
        try:
            enc = urllib.parse.quote(en_query)
            data = _get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&term={}&retmax=10&retmode=json&sort=relevance'.format(enc))
            if not data:
                return None
            pmids = data.get('esearchresult', {}).get('idlist', [])
            if not pmids:
                return None
            sdata = _get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi?db=pubmed&id={}&retmode=json'.format(','.join(pmids)))
            return {'pmids': pmids, 'summary': sdata}
        except Exception as _exc:
            biosim_log('warn', 'fetch_pubmed: {}'.format(_exc))
            return None

    tasks = [('wiki_ru', fetch_wiki_ru), ('wiki_en', fetch_wiki_en),
             ('ebi', fetch_ebi), ('pubmed', fetch_pubmed)]
    threads = []
    for key, func in tasks:
        def runner(k=key, f=func):
            api_results[k] = f()
        t = threading.Thread(target=runner, daemon=True)
        t.start()
        threads.append(t)
    for t in threads:
        t.join(timeout=10.0)

    # Process Wikipedia RU
    data = api_results.get('wiki_ru')
    if data and isinstance(data, list) and len(data) >= 4:
        for i, title in enumerate(data[1]):
            if not title or title.lower() in seen:
                continue
            if any(s in title for s in ['Список', 'Категория:', 'Файл:', 'Шаблон:']):
                continue
            seen.add(title.lower())
            desc = data[2][i] if i < len(data[2]) else ''
            results.append({'key': title, 'en': title, 'ru': title,
                            'src': 'Wiki-RU', 'genes': [], 'desc': desc[:200]})

    # Wikipedia EN
    data = api_results.get('wiki_en')
    if data and isinstance(data, list) and len(data) >= 4:
        for i, title in enumerate(data[1]):
            if not title or title.lower() in seen:
                continue
            if any(s in title for s in ['List of', 'Category:', 'File:', 'Template:']):
                continue
            seen.add(title.lower())
            desc = data[2][i] if i < len(data[2]) else ''
            results.append({'key': title, 'en': title, 'ru': title,
                            'src': 'Wiki-EN', 'genes': [], 'desc': desc[:200]})

    # EBI OLS
    data = api_results.get('ebi')
    if data:
        for doc in data.get('response', {}).get('docs', []):
            label = doc.get('label', '')
            if not label or label.lower() in seen:
                continue
            seen.add(label.lower())
            descs = doc.get('description', [])
            obo = doc.get('obo_id', '')
            results.append({'key': label, 'en': label, 'ru': label,
                            'src': obo.split(':')[0] if obo else 'EBI',
                            'genes': [], 'desc': descs[0][:200] if descs else ''})

    # PubMed
    pdata = api_results.get('pubmed')
    if pdata and pdata.get('summary'):
        sdata = pdata['summary']
        for pmid in pdata['pmids']:
            entry = sdata.get('result', {}).get(pmid, {})
            if not entry:
                continue
            title = entry.get('title', '')[:150]
            if not title:
                continue
            authors = entry.get('authors', [])
            year = entry.get('pubdate', '')[:4]
            journal = entry.get('source', '')
            key_str = 'pubmed:' + pmid
            if key_str.lower() in seen:
                continue
            seen.add(key_str.lower())
            first = authors[0].get('name', '') if authors else 'Unknown'
            desc = first + (' et al.' if len(authors) > 1 else '') + ' · ' + journal + ' · ' + year
            results.append({
                'key': key_str, 'en': title, 'ru': title,
                'src': 'PubMed', 'genes': [], 'desc': desc, 'pmid': pmid,
                'authors': ', '.join(a.get('name', '') for a in authors[:3]),
                'journal': journal, 'year': year,
                'url': 'https://pubmed.ncbi.nlm.nih.gov/' + pmid + '/',
            })

    print('[SEARCH] TOTAL: {} results'.format(len(results)))
    return results[:max_res]


def fetch_disease_genes(name):
    enc = urllib.parse.quote(name)
    url = 'https://rest.uniprot.org/uniprotkb/search?query=cc_disease:%22{}%22+AND+organism_id:9606&format=json&size=15&fields=gene_names'.format(enc)
    data = _get(url)
    genes = []
    if data:
        for entry in data.get('results', [])[:15]:
            for g in entry.get('genes', []):
                gn = g.get('geneName', {}).get('value', '')
                if gn and gn not in genes:
                    genes.append(gn)
    return genes[:12]


