# PUBCHEM
# ─────────────────────────────────────────────────
PC = 'https://pubchem.ncbi.nlm.nih.gov/rest/pug'

def detect_fmt(q):
    q = q.strip()
    if q.lower().startswith('inchi='):
        return 'inchi'
    if q.isdigit():
        return 'cid'
    smiles_chars = set('=#()[]/\\@+-.0123456789')
    if len(q) > 6 and sum(1 for c in q if c in smiles_chars) > 3:
        return 'smiles'
    return 'name'

def pc_cid(query, fmt):
    if fmt == 'cid':
        return int(query.strip())
    enc = urllib.parse.quote(query.strip())
    url = '{}/compound/{}/{}/cids/JSON'.format(PC, fmt, enc)
    d = _get(url)
    if d and 'IdentifierList' in d:
        cids = d['IdentifierList'].get('CID', [])
        return int(cids[0]) if cids else None
    return None

def pc_props(cid):
    fields = 'MolecularFormula,MolecularWeight,IsomericSMILES,IUPACName,XLogP,TPSA,HBondDonorCount,HBondAcceptorCount,RotatableBondCount'
    url = '{}/compound/cid/{}/property/{}/JSON'.format(PC, cid, fields)
    d = _get(url)
    if d and 'PropertyTable' in d:
        t = d['PropertyTable'].get('Properties', [])
        return t[0] if t else {}
    return {}

def pc_synonyms(cid):
    url = '{}/compound/cid/{}/synonyms/JSON'.format(PC, cid)
    d = _get(url)
    if d and 'InformationList' in d:
        infos = d['InformationList'].get('Information', [])
        if infos:
            return infos[0].get('Synonym', [])[:6]
    return []

def pc_desc(cid):
    url = '{}/compound/cid/{}/description/JSON'.format(PC, cid)
    d = _get(url)
    if d and 'InformationList' in d:
        for info in d['InformationList'].get('Information', []):
            desc = info.get('Description', '')
            if len(desc) > 50:
                return desc[:400]
    return ''


