# CHEMBL
# ─────────────────────────────────────────────────
CH = 'https://www.ebi.ac.uk/chembl/api/data'

def ch_id(name):
    enc = urllib.parse.quote(name)
    url = '{}/molecule/search?q={}&format=json&limit=1'.format(CH, enc)
    d = _get(url)
    if d:
        mols = d.get('molecules', [])
        if mols:
            return mols[0].get('molecule_chembl_id', '')
    return ''

def ch_targets(cid_str):
    if not cid_str:
        return []
    url = '{}/activity?molecule_chembl_id={}&pchembl_value__isnull=false&format=json&limit=25&order_by=-pchembl_value'.format(CH, cid_str)
    d = _get(url)
    if not d:
        return []
    seen = set()
    out = []
    for act in d.get('activities', []):
        name = act.get('target_pref_name', '') or ''
        org = act.get('target_organism', '') or ''
        atype = act.get('assay_type', '')
        pval = act.get('pchembl_value')
        if org and 'Homo sapiens' not in org:
            continue
        if atype not in ('B', 'F'):
            continue
        if not name or name in seen:
            continue
        seen.add(name)
        try:
            pv = float(pval) if pval else 0.0
        except (ValueError, TypeError) as _exc:
            biosim_log('warn', 'ch_targets: {}'.format(_exc))
            pv = 0.0
        out.append({
            'name': name, 'pchembl': pv,
            'ic50_nm': round(10 ** (9 - pv), 2) if pv > 0 else None
        })
    return out[:10]

def ch_admet(cid_str):
    if not cid_str:
        return {}
    url = '{}/molecule/{}?format=json'.format(CH, cid_str)
    d = _get(url)
    if not d:
        return {}
    p = d.get('molecule_properties', {}) or {}
    return {
        'qed': p.get('qed_weighted'),
        'psa': p.get('psa'),
        'ro5': p.get('num_ro5_violations'),
        'max_phase': d.get('max_phase'),
        'oral': d.get('oral'),
        'black_box': d.get('black_box_warning'),
        'first_approval': d.get('first_approval'),
    }

def ch_warnings(cid_str):
    if not cid_str:
        return []
    url = '{}/drug_warning?molecule_chembl_id={}&format=json'.format(CH, cid_str)
    d = _get(url)
    out = []
    if d:
        for w in d.get('drug_warnings', []):
            desc = w.get('description', '')
            if desc:
                out.append({'type': w.get('warning_type', ''), 'desc': desc[:200]})
    return out

def ch_drugs_for_target(target_name, max_drugs=8):
    enc = urllib.parse.quote(target_name)
    url = '{}/target/search?q={}&format=json&limit=3'.format(CH, enc)
    d = _get(url)
    if not d:
        return []
    targets = d.get('targets', [])
    if not targets:
        return []
    target_id = targets[0].get('target_chembl_id', '')
    if not target_id:
        return []
    url2 = '{}/activity?target_chembl_id={}&pchembl_value__gte=6&format=json&limit=30&order_by=-pchembl_value'.format(CH, target_id)
    d2 = _get(url2)
    if not d2:
        return []
    seen = set()
    drugs = []
    for act in d2.get('activities', []):
        mol_id = act.get('molecule_chembl_id', '')
        if not mol_id or mol_id in seen:
            continue
        seen.add(mol_id)
        try:
            pv = float(act.get('pchembl_value', 0))
        except (ValueError, TypeError) as _exc:
            biosim_log('warn', 'ch_drugs_for_target: {}'.format(_exc))
            pv = 0.0
        drugs.append({
            'chembl_id': mol_id,
            'mol_name': act.get('molecule_pref_name', '') or mol_id,
            'pchembl': pv,
            'ic50_nm': round(10 ** (9 - pv), 2) if pv > 0 else None,
        })
        if len(drugs) >= max_drugs:
            break
    return drugs


# ─────────────────────────────────────────────────
# UNIPROT
# ─────────────────────────────────────────────────
UP = 'https://rest.uniprot.org'

def up_search(name, max_r=3):
    q = urllib.parse.quote(name) + '+AND+organism_name:human'
    url = '{}/uniprotkb/search?query={}&format=json&size={}'.format(UP, q, max_r)
    d = _get(url)
    out = []
    if not d:
        return out
    for entry in d.get('results', []):
        acc = entry.get('primaryAccession', '')
        genes = entry.get('genes', [])
        gene = genes[0].get('geneName', {}).get('value', '') if genes else ''
        prot = entry.get('proteinDescription', {})
        rname = prot.get('recommendedName', {})
        fname = rname.get('fullName', {}).get('value', '') if rname else ''
        func = ''
        for c in entry.get('comments', []):
            if c.get('commentType') == 'FUNCTION':
                txts = c.get('texts', [])
                if txts:
                    func = txts[0].get('value', '')[:200]
                    break
        out.append({'acc': acc, 'gene': gene, 'name': fname, 'function': func})
    return out

def up_pathways(acc):
    url = '{}/uniprotkb/{}.json'.format(UP, acc)
    d = _get(url)
    pws = []
    if not d:
        return pws
    for c in d.get('comments', []):
        if c.get('commentType') in ('PATHWAY', 'SUBUNIT'):
            for t in c.get('texts', []):
                v = t.get('value', '')
                if v:
                    pws.append(v[:160])
    return pws[:5]

def up_gene_to_protein(gene_symbol):
    q = urllib.parse.quote('gene:{}+AND+organism_id:9606+AND+reviewed:true'.format(gene_symbol))
    url = '{}/uniprotkb/search?query={}&format=json&size=2'.format(UP, q)
    d = _get(url)
    if not d:
        return None
    results = d.get('results', [])
    if not results:
        return None
    entry = results[0]
    acc = entry.get('primaryAccession', '')
    prot = entry.get('proteinDescription', {})
    rname = prot.get('recommendedName', {})
    fname = rname.get('fullName', {}).get('value', '') if rname else ''
    func = ''
    for c in entry.get('comments', []):
        if c.get('commentType') == 'FUNCTION':
            txts = c.get('texts', [])
            if txts:
                func = txts[0].get('value', '')[:300]
                break
    seq = entry.get('sequence', {})
    return {
        'acc': acc, 'gene': gene_symbol, 'name': fname,
        'function': func, 'length': seq.get('length', 0),
        'mass': seq.get('molWeight', 0),
        'pathways': up_pathways(acc),
    }


