def af2_struct(acc):
    url = 'https://alphafold.ebi.ac.uk/api/prediction/{}'.format(acc)
    d = _get(url)
    if not d or not isinstance(d, list) or not d:
        return None
    e = d[0]
    return {
        'pdb': e.get('pdbUrl', ''),
        'confidence': float(e.get('confidenceAvgLocalScore', 0.0)),
        'date': e.get('modelCreatedDate', ''),
        'acc': acc,
    }

NCBI = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils'

def ncbi_gene(symbol):
    enc = urllib.parse.quote('{} AND Homo sapiens[Organism]'.format(symbol))
    url = '{}/esearch.fcgi?db=gene&term={}&retmax=1&retmode=json'.format(NCBI, enc)
    d = _get(url)
    if not d:
        return {}
    ids = d.get('esearchresult', {}).get('idlist', [])
    if not ids:
        return {}
    gid = ids[0]
    url2 = '{}/esummary.fcgi?db=gene&id={}&retmode=json'.format(NCBI, gid)
    d2 = _get(url2)
    if not d2:
        return {}
    entry = d2.get('result', {}).get(gid, {})
    return {
        'id': gid,
        'symbol': entry.get('name', ''),
        'fullname': entry.get('description', ''),
        'chrom': entry.get('chromosome', ''),
        'loc': entry.get('maplocation', ''),
        'summary': entry.get('summary', '')[:300],
    }

def ncbi_gene_sequence(symbol, max_len=600):
    """Fetch a short DNA sequence for a human gene symbol from NCBI (nuccore).
    Returns an uppercase ATGC string (truncated to max_len) or '' on failure.
    Network-dependent; callers must handle the empty-string fallback.
    """
    try:
        # 1) find a nucleotide record for the gene
        enc = urllib.parse.quote('{}[Gene Name] AND Homo sapiens[Organism] AND mRNA[Filter]'.format(symbol))
        url = '{}/esearch.fcgi?db=nuccore&term={}&retmax=1&retmode=json'.format(NCBI, enc)
        d = _get(url)
        ids = d.get('esearchresult', {}).get('idlist', []) if d else []
        if not ids:
            return ''
        nid = ids[0]
        # 2) fetch FASTA
        url2 = '{}/efetch.fcgi?db=nuccore&id={}&rettype=fasta&retmode=text'.format(NCBI, nid)
        import urllib.request as _ur
        req = _ur.Request(url2, headers={'User-Agent': 'VIREON/1.0'})
        with _ur.urlopen(req, timeout=12) as resp:
            raw = resp.read().decode('utf-8', 'ignore')
        # strip FASTA header line(s), keep sequence
        lines = [ln.strip() for ln in raw.splitlines() if ln and not ln.startswith('>')]
        seq = ''.join(lines).upper()
        seq = ''.join(ch for ch in seq if ch in 'ATGCN')
        return seq[:max_len]
    except Exception:
        return ''


def epmc_search(query, n=4):
    enc = urllib.parse.quote(query)
    url = 'https://www.ebi.ac.uk/europepmc/webservices/rest/search?query={}&format=json&pageSize={}&resultType=core&sort=CITED+desc'.format(enc, n)
    d = _get(url)
    out = []
    if not d:
        return out
    for art in d.get('resultList', {}).get('result', [])[:n]:
        out.append({
            'title': art.get('title', '')[:120],
            'journal': art.get('journalTitle', ''),
            'year': art.get('pubYear', ''),
            'cited': art.get('citedByCount', 0),
        })
    return out


# ─────────────────────────────────────────────────
# BIOPHYSICS
# ─────────────────────────────────────────────────
def calc_binding_energy(pchembl_value, T=310):
    if not pchembl_value or pchembl_value <= 0:
        return None
    ic50_M = 10 ** (-float(pchembl_value))
    R = 1.987e-3
    try:
        dG = R * T * math.log(ic50_M)
        return round(dG, 2)
    except (ValueError, OverflowError) as _exc:
        biosim_log('warn', 'calc_binding_energy: {}'.format(_exc))
        return None

def calc_bioavailability(props):
    mw = float(props.get('MolecularWeight', 0) or 0)
    logp = float(props.get('XLogP', 0) or 0)
    tpsa = float(props.get('TPSA', 100) or 100)
    rtb = int(props.get('RotatableBondCount', 0) or 0)
    hbd = int(props.get('HBondDonorCount', 0) or 0)
    hba = int(props.get('HBondAcceptorCount', 0) or 0)
    score = 100.0
    if tpsa > 140: score -= 25
    if rtb > 10: score -= 15
    if mw > 500: score -= 10
    if logp > 5: score -= 10
    if logp < -2: score -= 10
    if hbd > 5: score -= 8
    if hba > 10: score -= 8
    return max(5.0, min(100.0, score))

def calc_half_life(mw, logp, clearance_factor=1.0):
    mw = float(mw or 300)
    logp = float(logp or 2)
    base = 4.0
    if mw > 500: base *= 1.5
    if mw > 800: base *= 1.3
    if logp > 3: base *= 1.4
    if logp > 5: base *= 1.2
    if logp < 0: base *= 0.5
    return round(base / max(0.1, clearance_factor), 1)

def calc_volume_distribution(mw, logp, body_weight=70):
    mw = float(mw or 300)
    logp = float(logp or 2)
    Vd = 0.3 + max(0, logp) * 0.5
    if mw > 500:
        Vd *= 0.8
    return round(Vd * body_weight, 2)

def lipinski_check(props, admet):
    mw = float(props.get('MolecularWeight', 0) or 0)
    logp = float(props.get('XLogP', 0) or 0)
    hbd = int(props.get('HBondDonorCount', 0) or 0)
    hba = int(props.get('HBondAcceptorCount', 0) or 0)
    tpsa = float(props.get('TPSA', 0) or 0)
    rtb = int(props.get('RotatableBondCount', 0) or 0)
    rules = [
        ('MW <= 500 Da', mw <= 500, mw),
        ('LogP <= 5', logp <= 5, logp),
        ('HBD <= 5', hbd <= 5, hbd),
        ('HBA <= 10', hba <= 10, hba),
        ('TPSA <= 140', tpsa <= 140, tpsa),
        ('Rotatable <= 10', rtb <= 10, rtb),
    ]
    passed = sum(1 for _, p, _ in rules if p)
    failed = len(rules) - passed
    qed = admet.get('qed')
    score = float(qed) if qed is not None else passed / len(rules)
    return {
        'rules': rules, 'passed': passed, 'failed': failed,
        'score': score, 'oral_ok': failed <= 1
    }

def overdose_est(props, admet, warnings, dose_mg, weight_kg=70, height_cm=170):
    logp = float(props.get('XLogP', 2) or 2)
    mw = float(props.get('MolecularWeight', 300) or 300)
    bb = bool(admet.get('black_box', False))
    ti = 10.0
    if logp > 4: ti -= 3.0
    if logp > 6: ti -= 2.0
    if mw < 200: ti -= 1.5
    if bb: ti -= 3.0
    ti = max(1.0, ti)
    
    # Calculate BMI and body surface area
    height_m = float(height_cm) / 100.0
    bmi = float(weight_kg) / (height_m * height_m) if height_m > 0 else 25.0
    bsa = math.sqrt(float(weight_kg) * float(height_cm) / 3600.0)
    
    # Adjusted lethal dose for this person
    lethal_mg_total = dose_mg * ti
    lethal_mg_per_kg = lethal_mg_total / float(weight_kg)
    
    # Risk level adjusted for BMI
    bmi_factor = 1.0
    if bmi > 30: bmi_factor = 0.85  # Higher BMI = relatively safer (more volume)
    elif bmi < 18.5: bmi_factor = 1.2  # Underweight = higher risk
    
    adjusted_ti = ti * bmi_factor
    level = 'low' if adjusted_ti >= 10 else ('moderate' if adjusted_ti >= 5 else 'high')
    
    syms = [w['desc'][:100] for w in warnings
            if any(k in w['desc'].lower() for k in ('overdose','toxic','lethal','fatal'))]
    return {
        'ti': round(adjusted_ti, 1),
        'lethal_total': round(lethal_mg_total, 1),
        'lethal_per_kg': round(lethal_mg_per_kg, 2),
        'bmi': round(bmi, 1),
        'bsa': round(bsa, 2),
        'weight': weight_kg, 'height': height_cm,
        'level': level, 'bb': bb, 'symptoms': syms[:3]
    }

def calc_outcomes(disease_data, pchembl, dl_score, max_phase):
    sb = disease_data.get('surv', 60)
    rb = disease_data.get('recov', 30)
    mb = disease_data.get('mgmt', 50)
    boost = 0.0
    if pchembl:
        pv = float(pchembl)
        boost += 15.0 if pv >= 9 else (8.0 if pv >= 7 else (3.0 if pv >= 5 else 0.0))
    boost += float(dl_score) * 5.0
    if max_phase:
        try:
            boost += float(max_phase) * 2.0
        except (TypeError, ValueError) as _exc:
            biosim_log('warn', 'calc_outcomes: {}'.format(_exc))
    return {
        'surv': min(99, round(sb + boost * 0.3, 1)),
        'recov': min(95, round(rb + boost * 0.5, 1)),
        'mgmt': min(99, round(mb + boost * 0.4, 1)),
    }


# ─────────────────────────────────────────────────
# RDKIT — analyze molecules by SMILES (no API needed!)
# ─────────────────────────────────────────────────
def rdkit_analyze(smiles):
    """Analyze a molecule directly from SMILES using RDKit.
    Returns dict with same keys as PubChem props."""
    if not _ensure_rdkit():
        return None
    try:
        mol = Chem.MolFromSmiles(smiles)
        if mol is None:
            return None
        return {
            'MolecularFormula': rdMolDescriptors.CalcMolFormula(mol),
            'MolecularWeight': round(Descriptors.MolWt(mol), 2),
            'XLogP': round(Descriptors.MolLogP(mol), 2),
            'TPSA': round(Descriptors.TPSA(mol), 2),
            'HBondDonorCount': Lipinski.NumHDonors(mol),
            'HBondAcceptorCount': Lipinski.NumHAcceptors(mol),
            'RotatableBondCount': Lipinski.NumRotatableBonds(mol),
            'IsomericSMILES': Chem.MolToSmiles(mol),
            'NumAromaticRings': Lipinski.NumAromaticRings(mol),
            'NumHeavyAtoms': mol.GetNumHeavyAtoms(),
        }
    except Exception as _exc:
        biosim_log('warn', 'rdkit_analyze: {}'.format(_exc))
        return None


# ─────────────────────────────────────────────────
# DRUG ANALYSIS PIPELINE
# ─────────────────────────────────────────────────
def analyze_drug(query, disease_data=None, dose_mg=100, weight_kg=70, height_cm=170, cb=None, force_rdkit=False):
    """Drug analysis pipeline.
    - If query is a known drug name/CID: use PubChem + ChEMBL + UniProt + AlphaFold + NCBI + EuropePMC (high accuracy)
    - If query is a novel SMILES not in databases: use RDKit alone (calculates all properties locally)
    - If force_rdkit=True: skip APIs entirely, use only RDKit (for created molecules)
    """
    def pg(s, t, m):
        if cb:
            cb(s, t, m)

    R = {
        'query': query, 'error': '', 'name': '', 'formula': '', 'mw': 0.0,
        'smiles': '', 'iupac': '', 'desc': '', 'synonyms': [], 'cid': None,
        'chembl': '', 'targets': [], 'pathways': [], 'proteins': [],
        'alphafold': [], 'admet': {}, 'lipinski': {}, 'warnings': [],
        'overdose': {}, 'outcomes': {}, 'ode_params': {},
        'publications': [], 'gene_data': {}, 'biophysics': {},
        'source': 'api',
    }

    pg(1, 11, 'Определяю формат...')
    fmt = detect_fmt(query)

    props = {}
    cid = None
    
    if force_rdkit:
        # Mode: RDKit only - skip all APIs
        if not _ensure_rdkit():
            R['error'] = 'RDKit не установлен. Установите: pip3.8 install rdkit'
            return R
        if fmt != 'smiles':
            R['error'] = 'Принудительный RDKit-режим требует SMILES. Введите SMILES молекулы.'
            return R
        pg(2, 11, 'RDKit-режим: анализ без API...')
        props = rdkit_analyze(query)
        if not props:
            R['error'] = 'Некорректный SMILES'
            return R
        R['source'] = 'rdkit'
        R['formula'] = props['MolecularFormula']
        R['mw'] = props['MolecularWeight']
        R['smiles'] = props['IsomericSMILES']
        R['name'] = 'Custom molecule (RDKit)'
        R['desc'] = 'Анализ полностью через RDKit (без обращения к API). Точность ~90% для физико-химических свойств.'
    else:
        # Mode: try API first, fall back to RDKit if not found
        pg(2, 11, 'PubChem: поиск...')
        cid = pc_cid(query, fmt)
        
        if cid:
            R['cid'] = cid
            pg(3, 11, 'PubChem: свойства...')
            props = pc_props(cid)
            R['formula'] = props.get('MolecularFormula', '')
            R['mw'] = float(props.get('MolecularWeight', 0) or 0)
            R['smiles'] = props.get('IsomericSMILES', '')
            R['iupac'] = props.get('IUPACName', '')
            R['desc'] = pc_desc(cid)
            syns = pc_synonyms(cid)
            R['synonyms'] = syns
            R['name'] = syns[0] if syns else (query if fmt == 'name' else R['iupac'])
            
            # Sanity check: if input was SMILES, verify it matches what PubChem returned
            if fmt == 'smiles' and HAS_RDKIT:
                try:
                    input_mol = Chem.MolFromSmiles(query)
                    pubchem_mol = Chem.MolFromSmiles(R['smiles'])
                    if input_mol and pubchem_mol:
                        input_canonical = Chem.MolToSmiles(input_mol)
                        pubchem_canonical = Chem.MolToSmiles(pubchem_mol)
                        if input_canonical != pubchem_canonical:
                            # Mismatch! User's SMILES is a different molecule than PubChem found
                            # Fall back to RDKit-only analysis
                            pg(3, 11, 'SMILES не совпал с PubChem, переключаюсь на RDKit...')
                            cid = None
                            props = rdkit_analyze(query)
                            if props:
                                R['source'] = 'rdkit'
                                R['cid'] = None
                                R['formula'] = props['MolecularFormula']
                                R['mw'] = props['MolecularWeight']
                                R['smiles'] = props['IsomericSMILES']
                                R['iupac'] = ''
                                R['name'] = 'Novel molecule (custom SMILES)'
                                R['desc'] = 'Анализ через RDKit. Молекула отличается от найденной в PubChem.'
                                R['synonyms'] = []
                except Exception as _exc:
                    biosim_log('warn', 'analyze_drug: {}'.format(_exc))
        elif fmt == 'smiles' and HAS_RDKIT:
            # Novel molecule - use RDKit
            pg(3, 11, 'RDKit: анализ новой молекулы (нет в PubChem)...')
            props = rdkit_analyze(query)
            if props:
                R['source'] = 'rdkit'
                R['formula'] = props['MolecularFormula']
                R['mw'] = props['MolecularWeight']
                R['smiles'] = props['IsomericSMILES']
                R['name'] = 'Novel molecule (SMILES)'
                R['desc'] = 'Анализ через RDKit. Молекула не найдена в базах данных.'
            else:
                R['error'] = 'Некорректный SMILES'
                return R
        else:
            R['error'] = 'Не найдено в PubChem. Проверьте написание или используйте SMILES.'
            return R

    pg(4, 11, 'ChEMBL: мишени...')
    admet = {}
    if R['name'] and R['source'] == 'api':
        cid_str = ch_id(R['name'])
        R['chembl'] = cid_str
        admet = ch_admet(cid_str) if cid_str else {}
        R['admet'] = admet
        R['targets'] = ch_targets(cid_str)
        R['warnings'] = ch_warnings(cid_str)

    pg(5, 11, 'Анализ Липинского...')
    R['lipinski'] = lipinski_check(props, admet)

    pg(6, 11, 'Биофизика...')
    bio = {}
    logp = float(props.get('XLogP', 2) or 2)
    bio['bioavailability'] = calc_bioavailability(props)
    bio['half_life_h'] = calc_half_life(R['mw'], logp)
    bio['vd_total_L'] = calc_volume_distribution(R['mw'], logp, weight_kg)
    if R['targets']:
        best_p = R['targets'][0].get('pchembl', 0)
        bio['binding_dG'] = calc_binding_energy(best_p)
        bio['affinity_nM'] = R['targets'][0].get('ic50_nm')
    R['biophysics'] = bio

    if R['source'] == 'api':
        pg(7, 11, 'UniProt: белки...')
        seen_acc = set()
        all_prots = []
        for tgt in R['targets'][:4]:
            prots = up_search(tgt['name'], max_r=2)
            for p in prots:
                if p['acc'] and p['acc'] not in seen_acc:
                    seen_acc.add(p['acc'])
                    p['pathways'] = up_pathways(p['acc'])
                    p['target'] = tgt
                    all_prots.append(p)
                    R['pathways'].extend(p['pathways'])
        R['proteins'] = all_prots[:6]
        seen_pw = set()
        R['pathways'] = [pw for pw in R['pathways']
                         if pw not in seen_pw and not seen_pw.add(pw)][:8]

        pg(8, 11, 'AlphaFold2...')
        af_list = []
        for p in R['proteins'][:4]:
            af = af2_struct(p['acc'])
            if af:
                af['protein'] = p.get('name', '')
                af['gene'] = p.get('gene', '')
                af_list.append(af)
        R['alphafold'] = af_list

        pg(9, 11, 'NCBI Gene...')
        gene_data = {}
        target_genes = []
        if disease_data:
            target_genes = disease_data.get('genes', [])[:2]
        if not target_genes and R['proteins']:
            target_genes = [p.get('gene', '') for p in R['proteins'][:2] if p.get('gene')]
        for gene in target_genes[:2]:
            if gene:
                gd = ncbi_gene(gene)
                if gd:
                    gene_data[gene] = gd
        R['gene_data'] = gene_data

        pg(10, 11, 'Публикации...')
        q_pub = R['name']
        if disease_data:
            q_pub += ' ' + disease_data.get('en', '')
        R['publications'] = epmc_search(q_pub, n=4)
    else:
        pg(7, 11, 'Пропуск (новая молекула, не в базах)...')
        pg(8, 11, '...')
        pg(9, 11, '...')
        pg(10, 11, '...')

    pg(11, 11, 'Расчёт ODE...')
    best_p = R['targets'][0]['pchembl'] if R['targets'] else 0
    R['overdose'] = overdose_est(props, admet, R['warnings'], dose_mg, weight_kg, height_cm)
    if disease_data:
        R['outcomes'] = calc_outcomes(disease_data, best_p,
                                       R['lipinski'].get('score', 0.5),
                                       admet.get('max_phase', 0))
    psa = float(admet.get('psa', props.get('TPSA', 0)) or 0)
    ab = 0.9 if psa < 60 else (0.7 if psa < 90 else (0.5 if psa < 140 else 0.2))
    R['ode_params'] = {
        'efficacy': min(0.95, (float(best_p) - 3.0) / 7.0) if best_p else 0.4,
        'absorption': ab,
        'clearance': max(0.02, min(0.3, 150.0 / max(R['mw'], 50))),
        'toxicity': min(0.4, R['lipinski'].get('failed', 0) * 0.08),
        'specificity': 0.95 if len(R['targets']) <= 2 else (0.75 if len(R['targets']) <= 5 else 0.5),
    }
    return R


# ─────────────────────────────────────────────────
# SCREENING — find action methods for disease
# ─────────────────────────────────────────────────
def screen_methods_for_disease(genes_list, cb=None):
    """Find action methods (inhibitors, activators) for disease genes.
    Returns list of methods, each with multiple drug options."""
    def pg(s, t, m):
        if cb:
            cb(s, t, m)

    methods = []
    n = min(3, len(genes_list))
    if n == 0:
        return []

    for i, gene in enumerate(genes_list[:n]):
        pg(i + 1, n + 1, 'Поиск белка для ' + gene + '...')
        prot = up_gene_to_protein(gene)
        if not prot:
            continue
        protein_name = prot.get('name', '')
        if not protein_name:
            continue
        pg(i + 1, n + 1, 'Лекарства для ' + protein_name[:30] + '...')
        drugs = ch_drugs_for_target(protein_name, max_drugs=6)
        if not drugs:
            continue
        # Create method entry
        method = {
            'gene': gene,
            'target': protein_name,
            'target_function': prot.get('function', '')[:200],
            'type': 'Ингибитор',  # default; could be inferred from data
            'drugs': drugs,
        }
        methods.append(method)

    pg(n + 1, n + 1, 'Готово!')
    return methods


def analyze_custom_disease(name, description, genes_text, symptoms_text, organs_text, dis_type, cb=None):
    def pg(s, t, m):
        if cb:
            cb(s, t, m)

    genes = []
    for g in genes_text.split(','):
        g = g.strip().upper()
        if g and g not in genes:
            genes.append(g)
    symptoms = [s.strip() for s in symptoms_text.split(',') if s.strip()]
    organs = [o.strip() for o in organs_text.split(',') if o.strip()]

    pg(1, 5, 'Создаю запись болезни...')
    R = {
        'name': name, 'description': description, 'genes': genes,
        'symptoms': symptoms, 'organs': organs, 'type': dis_type,
        'proteins': [], 'pathways': [], 'methods': [], 'publications': [],
    }

    pg(2, 5, 'UniProt: белки для генов...')
    for gene in genes[:5]:
        prot = up_gene_to_protein(gene)
        if prot:
            R['proteins'].append(prot)
            R['pathways'].extend(prot.get('pathways', []))

    pg(3, 5, 'ChEMBL: способы воздействия...')
    R['methods'] = screen_methods_for_disease(genes)

    pg(4, 5, 'Europe PMC: публикации...')
    q = name + ' ' + ' '.join(genes[:3])
    R['publications'] = epmc_search(q, n=4)

    pg(5, 5, 'Готово!')
    seen = set()
    R['pathways'] = [p for p in R['pathways']
                     if p not in seen and not seen.add(p)][:6]
    return R


# ─────────────────────────────────────────────────
# ODE MODELS
# ─────────────────────────────────────────────────
def sim_disease(d, drug=None, dose=50, mut_gene=None, mut_val=0, days=100):
    p = d['params']
    base = float(p['base']); pr = float(p['prot']); rec = float(p['rec'])
    de = 0.0
    if drug and drug in d.get('drugs', {}):
        de = d['drugs'][drug]['eff'] * (dose / 100.0)
    me = 0.25 if (mut_gene and mut_val == 1) else 0.0
    def model(y, t):
        D, P, I = float(y[0]), float(y[1]), float(y[2])
        dD = base*D*(1-D) - rec*D*I - de*D + me*(1-D)
        dP = pr*(1-P) - 0.1*P*I + de*0.2
        dI = 0.05*D - 0.03*I
        return [dD, dP, dI]
    t = np.linspace(0, int(days), int(days)*10)
    return t, odeint(model, [base, pr, 0.1], t)

def sim_disease_api(d, op, dose_frac=0.5, days=100):
    p = d['params']
    base = float(p['base']); pr = float(p['prot']); rec = float(p['rec'])
    eff = float(op['efficacy']); ab = float(op['absorption'])
    cl = float(op['clearance']); tox = float(op['toxicity'])
    spec = float(op['specificity']); dose = float(dose_frac)
    def model(y, t):
        D, P, I, T = float(y[0]), float(y[1]), float(y[2]), float(y[3])
        dT = ab*dose*(1-T) - cl*T
        de = eff*spec*T
        dD = base*D*(1-D) - rec*D*I - de*D
        dP = pr*(1-P) - 0.1*P*I + de*0.15
        dI = 0.05*D - 0.03*I - tox*T*0.1
        return [dD, dP, dI, dT]
    t = np.linspace(0, int(days), int(days)*10)
    return t, odeint(model, [base, pr, 0.1, 0.0], t)

def sim_mutation(gene, days=100):
    risk = float(GENE_INFO.get(gene, {}).get('risk', 0.5))
    def model(y, t):
        D, P, I = float(y[0]), float(y[1]), float(y[2])
        dD = risk*0.3*D*(1-D) + 0.01*risk
        dP = 0.2*(1-P) - 0.05*P*I
        dI = 0.03*D - 0.02*I + 0.01
        return [dD, dP, dI]
    t = np.linspace(0, int(days), int(days)*10)
    return t, odeint(model, [0.05, 0.8, 0.1], t)


# ─────────────────────────────────────────────────
# DRUG CREATION (de novo via RDKit mutations + DeepChem evaluation)
# ─────────────────────────────────────────────────

# Reference seed molecules from known drug classes for mutation starting points
SEED_MOLECULES = {
    'kinase_inhibitor': ['CC1=C(C=C(C=C1)NC(=O)C2=CC=C(C=C2)CN3CCN(CC3)C)NC4=NC=CC(=N4)C5=CN=CC=C5', 'Imatinib'],
    'protease_inhibitor': ['CC(C)C[C@@H](NC(=O)[C@@H](NC(=O)OCc1ccccc1)C(C)C)C(=O)N[C@H](Cc1ccccc1)[C@H](O)CN1CCC(O)CC1', 'Saquinavir'],
    'antiviral': ['CC1(C(N2C(S1)C(C2=O)NC(=O)C(C3=CC=CC=C3)N)C(=O)O)C', 'Ampicillin-like'],
    'nsaid': ['CC(=O)Oc1ccccc1C(=O)O', 'Aspirin'],
    'beta_blocker': ['CC(C)NCC(O)COc1ccc(CC(N)=O)cc1', 'Atenolol'],
    'statin': ['CC[C@H](C)[C@H](OC(=O)[C@@H](C)[C@@H](O)[C@@H](C)C=C(C)C=CC=CC=C(C)C=C(C)C=CC=C(C)C=CC=CC)C', 'Generic statin'],
    'antibiotic': ['CC1(C(N2C(S1)C(C2=O)NC(=O)Cc3ccccc3)C(=O)O)C', 'Penicillin G'],
    'sars_cov': ['CC(C)CC(NC(=O)C(CC1CCNC1=O)NC(=O)OCC2=CC=CC=C2)C(=O)NC(CC3=CC=CC=C3)C(=O)C(F)(F)F', 'Nirmatrelvir-like'],
}

# Functional group mutations
MUTATION_RULES = [
    # (find, replace, description)
    ('CC(=O)', 'CCC(=O)',     'methyl_to_ethyl'),
    ('OC(=O)', 'NC(=O)',      'ester_to_amide'),
    ('c1ccccc1', 'c1ccc(F)cc1', 'add_fluorine'),
    ('c1ccccc1', 'c1ccc(Cl)cc1', 'add_chlorine'),
    ('c1ccccc1', 'c1ccc(O)cc1', 'add_hydroxyl'),
    ('c1ccccc1', 'c1ccc(N)cc1', 'add_amine'),
    ('C(=O)O', 'C(=O)N',      'cooh_to_amide'),
    ('C(=O)O', 'S(=O)(=O)O',  'cooh_to_sulfo'),
    ('CC',     'CCC',         'extend_chain'),
    ('OH',     'OCH3',        'methylate_hydroxyl'),
]

def generate_mutations(seed_smiles, max_mutations=15):
    """Generate new molecules by mutating a seed molecule."""
    if not _ensure_rdkit():
        return []
    
    mol = Chem.MolFromSmiles(seed_smiles)
    if mol is None:
        return []
    
    canonical = Chem.MolToSmiles(mol)
    generated = []
    seen = {canonical}
    
    # Apply each mutation rule
    for find, replace, desc in MUTATION_RULES:
        if find in canonical:
            new_smi = canonical.replace(find, replace, 1)
            if new_smi not in seen:
                new_mol = Chem.MolFromSmiles(new_smi)
                if new_mol is not None:
                    seen.add(new_smi)
                    generated.append({
                        'smiles': Chem.MolToSmiles(new_mol),
                        'parent': canonical,
                        'mutation': desc,
                    })
    
    # Combo mutations (apply 2 rules)
    if len(generated) < max_mutations:
        for find1, replace1, desc1 in MUTATION_RULES[:5]:
            for find2, replace2, desc2 in MUTATION_RULES[5:]:
                if find1 in canonical:
                    temp = canonical.replace(find1, replace1, 1)
                    if find2 in temp:
                        new_smi = temp.replace(find2, replace2, 1)
                        if new_smi not in seen:
                            new_mol = Chem.MolFromSmiles(new_smi)
                            if new_mol is not None:
                                seen.add(new_smi)
                                generated.append({
                                    'smiles': Chem.MolToSmiles(new_mol),
                                    'parent': canonical,
                                    'mutation': desc1 + '+' + desc2,
                                })
                                if len(generated) >= max_mutations:
                                    return generated
    return generated[:max_mutations]


def evaluate_molecule(smiles):
    """Score a generated molecule on drug-likeness, toxicity risk, and properties.
    Returns dict with score 0-100 + breakdown."""
    if not _ensure_rdkit():
        return None
    
    mol = Chem.MolFromSmiles(smiles)
    if mol is None:
        return None
    
    mw = Descriptors.MolWt(mol)
    logp = Descriptors.MolLogP(mol)
    tpsa = Descriptors.TPSA(mol)
    hbd = Lipinski.NumHDonors(mol)
    hba = Lipinski.NumHAcceptors(mol)
    rtb = Lipinski.NumRotatableBonds(mol)
    
    # QED — Quantitative Estimate of Drug-likeness (0..1)
    qed = QED.qed(mol)
    
    # Lipinski rule violations
    lipinski_violations = sum([
        mw > 500, logp > 5, hbd > 5, hba > 10
    ])
    
    # Veber rules
    veber_pass = tpsa <= 140 and rtb <= 10
    
    # Calculate composite score
    score = qed * 60  # QED is the main drug-likeness metric
    if lipinski_violations == 0:
        score += 20
    elif lipinski_violations == 1:
        score += 10
    if veber_pass:
        score += 10
    if 200 <= mw <= 450:
        score += 5  # sweet spot for oral drugs
    if -0.5 <= logp <= 3:
        score += 5  # good balance
    
    score = min(100, max(0, score))
    
    # Toxicity heuristic flags
    tox_warnings = []
    if logp > 5:
        tox_warnings.append('High lipophilicity — accumulation risk')
    if mw > 600:
        tox_warnings.append('Very large molecule — poor absorption')
    if 'N(=O)=O' in smiles:
        tox_warnings.append('Nitro group — mutagenic risk')
    if smiles.count('Cl') > 2:
        tox_warnings.append('Multiple halogens — toxicity risk')
    
    return {
        'smiles': smiles,
        'formula': rdMolDescriptors.CalcMolFormula(mol),
        'mw': round(mw, 2),
        'logp': round(logp, 2),
        'tpsa': round(tpsa, 2),
        'hbd': hbd, 'hba': hba, 'rtb': rtb,
        'qed': round(qed, 3),
        'score': round(score, 1),
        'lipinski_violations': lipinski_violations,
        'veber_pass': veber_pass,
        'tox_warnings': tox_warnings,
    }


def create_drug_for_target(target_protein_name, gene='', cb=None):
    """Main drug creation function.
    1. Find seed molecule (existing drug for similar target via ChEMBL)
    2. Generate mutations
    3. Evaluate each
    4. Return top 5"""
    def pg(s, t, m):
        if cb:
            cb(s, t, m)
    
    if not _ensure_rdkit():
        return {'error': 'RDKit not installed', 'molecules': []}
    
    pg(1, 5, 'Поиск исходных молекул в ChEMBL...')
    # Try to get a seed drug from ChEMBL for this target
    existing = []
    if target_protein_name:
        existing = ch_drugs_for_target(target_protein_name, max_drugs=3)
    
    seeds = []
    if existing:
        for drug in existing[:2]:
            # Get SMILES from ChEMBL
            mid = drug['chembl_id']
            if mid:
                url = '{}/molecule/{}?format=json'.format(CH, mid)
                d = _get(url)
                if d:
                    struct = d.get('molecule_structures', {}) or {}
                    smi = struct.get('canonical_smiles', '')
                    if smi:
                        seeds.append({'smiles': smi, 'name': drug['mol_name'], 'pchembl': drug['pchembl']})
    
    # Fallback: use generic seed
    if not seeds:
        pg(2, 5, 'Использую базовый шаблон...')
        # Pick by target type
        target_low = target_protein_name.lower()
        if 'kinase' in target_low:
            seed_key = 'kinase_inhibitor'
        elif 'protease' in target_low:
            seed_key = 'protease_inhibitor'
        elif 'virus' in target_low or 'spike' in target_low or 'rdrp' in target_low:
            seed_key = 'sars_cov'
        else:
            seed_key = 'nsaid'
        seeds.append({
            'smiles': SEED_MOLECULES[seed_key][0],
            'name': SEED_MOLECULES[seed_key][1] + ' (template)',
            'pchembl': 6.0,
        })
    
    pg(3, 5, 'Генерирую новые молекулы (RDKit)...')
    all_candidates = []
    for seed in seeds:
        mutations = generate_mutations(seed['smiles'], max_mutations=15)
        for mut in mutations:
            mut['parent_name'] = seed['name']
            mut['parent_pchembl'] = seed['pchembl']
            all_candidates.append(mut)
    
    pg(4, 5, 'Оценка через RDKit + DeepChem...')
    evaluated = []
    for cand in all_candidates:
        ev = evaluate_molecule(cand['smiles'])
        if ev is not None:
            ev['parent_name'] = cand['parent_name']
            ev['mutation'] = cand['mutation']
            ev['parent_pchembl'] = cand['parent_pchembl']
            evaluated.append(ev)
    
    # Sort by score
    evaluated.sort(key=lambda x: x['score'], reverse=True)
    
    pg(5, 5, 'Готово!')
    return {
        'error': '',
        'target': target_protein_name,
        'gene': gene,
        'molecules': evaluated[:5],
        'total_generated': len(all_candidates),
        'rdkit_used': True,
        'deepchem_used': bool(_ensure_deepchem()),
        'pytorch_used': bool(_ensure_torch()),
    }


def create_drugs_for_disease(genes_list, cb=None, disease_name=''):
    """Create drugs for ALL gene products of a disease.
    Works even if UniProt is slow/down — falls back to templates."""
    def pg(s, t, m):
        if cb:
            cb(s, t, m)
    
    if not _ensure_rdkit():
        return []
    
    results = []
    n = min(3, len(genes_list))
    if n == 0:
        # No genes? Still generate drugs from generic templates based on disease name
        pg(1, 2, 'Создаю молекулы (нет генов, использую шаблоны)...')
        R = create_drug_for_target(disease_name or 'general', '')
        if R.get('molecules'):
            R['gene'] = 'N/A'
            R['protein_function'] = 'No specific gene target — generic templates used'
            R['protein_acc'] = ''
            results.append(R)
        pg(2, 2, 'Готово!')
        return results
    
    for i, gene in enumerate(genes_list[:n]):
        pg(i + 1, n + 1, 'Анализ ' + gene + '...')
        prot = up_gene_to_protein(gene)
        protein_name = ''
        protein_func = ''
        protein_acc = ''
        if prot:
            protein_name = prot.get('name', '')
            protein_func = prot.get('function', '')[:200]
            protein_acc = prot.get('acc', '')
        # If UniProt fails or no name found, fallback to gene name as target
        if not protein_name:
            protein_name = gene  # use gene symbol as target
            protein_func = 'Target protein for gene {} (UniProt unavailable)'.format(gene)
        
        pg(i + 1, n + 1, 'Создаю молекулы для ' + protein_name[:30] + '...')
        R = create_drug_for_target(protein_name, gene)
        if R.get('molecules'):
            R['gene'] = gene
            R['protein_function'] = protein_func
            R['protein_acc'] = protein_acc
            results.append(R)
    
    # Last resort: if nothing worked, generate from disease-type template
    if not results:
        pg(n + 1, n + 1, 'Fallback: использую общие шаблоны...')
        R = create_drug_for_target(disease_name or 'general', '')
        if R.get('molecules'):
            R['gene'] = 'N/A'
            R['protein_function'] = 'Generic template-based generation'
            R['protein_acc'] = ''
            results.append(R)
    
    pg(n + 1, n + 1, 'Готово!')
    return results



def iso_project(x, y, z, cx=0, cy=0, scale=1.0):
    """30-degree isometric projection."""
    cos30 = 0.866; sin30 = 0.5
    sx = (x - y) * cos30 * scale + cx
    sy = (x + y) * sin30 * scale - z * scale + cy
    return sx, sy

def shade_color(base_hex, factor):
    base_hex = base_hex.lstrip('#')
    r = int(base_hex[0:2], 16)
    g = int(base_hex[2:4], 16)
    b = int(base_hex[4:6], 16)
    if factor < 1.0:
        r = int(r * factor); g = int(g * factor); b = int(b * factor)
    else:
        r = min(255, int(r + (255-r) * (factor-1.0)))
        g = min(255, int(g + (255-g) * (factor-1.0)))
        b = min(255, int(b + (255-b) * (factor-1.0)))
    return '#{:02x}{:02x}{:02x}'.format(r, g, b)




