def simple_translate_to_ru(text, max_len=2000):
    """Very simple dictionary-based EN RU translation.
    Best used as fallback when no Russian Wikipedia text available.
    """
    if not text:
        return ''
    # Use longest-match first
    sorted_terms = sorted(MEDICAL_TERMS_EN_RU.keys(), key=len, reverse=True)
    result = text[:max_len]
    for term in sorted_terms:
        # Case-insensitive replacement preserving rough position
        ru = MEDICAL_TERMS_EN_RU[term]
        # Use word boundary for short terms
        import re as _re
        if len(term) >= 4:
            pattern = _re.compile(r'\b' + _re.escape(term) + r'\b', _re.IGNORECASE)
            result = pattern.sub(ru, result)
    return result


