class Tooltip:
    """Lightweight tooltip that appears after hover delay.
    Usage: Tooltip(widget, 'Text to show on hover')
    Or:    Tooltip(widget, callable_returning_text)
    """
    _active_tooltip = None  # only one tooltip at a time

    def __init__(self, widget, text, delay=600, wraplength=280):
        self.widget = widget
        self.text = text
        self.delay = delay  # ms before tooltip appears
        self.wraplength = wraplength
        self.tip_window = None
        self._after_id = None
        widget.bind('<Enter>', self._schedule)
        widget.bind('<Leave>', self._unschedule)
        widget.bind('<ButtonPress>', self._unschedule)

    def _schedule(self, event=None):
        self._unschedule()
        self._after_id = self.widget.after(self.delay, self._show)

    def _unschedule(self, event=None):
        if self._after_id is not None:
            try:
                self.widget.after_cancel(self._after_id)
            except Exception as _exc:
                biosim_log('warn', '_unschedule: {}'.format(_exc))
            self._after_id = None
        self._hide()

    def _show(self):
        if self.tip_window:
            return
        try:
            x = self.widget.winfo_rootx() + 25
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 4
        except Exception as _exc:
            biosim_log('warn', '_show: {}'.format(_exc))
            return
        text = self.text() if callable(self.text) else self.text
        if not text:
            return
        if Tooltip._active_tooltip and Tooltip._active_tooltip.tip_window:
            try:
                Tooltip._active_tooltip.tip_window.destroy()
            except Exception as _exc:
                biosim_log('warn', '_show: {}'.format(_exc))
        self.tip_window = tk.Toplevel(self.widget)
        self.tip_window.wm_overrideredirect(True)
        self.tip_window.wm_geometry('+{}+{}'.format(x, y))
        # macOS quirk — make it a non-activating window
        try:
            self.tip_window.attributes('-topmost', True)
        except Exception as _exc:
            biosim_log('warn', '_show: {}'.format(_exc))
        frame = tk.Frame(self.tip_window, bg=biosim_theme('panel2'),
                          highlightthickness=1, highlightbackground='#0969da')
        frame.pack()
        tk.Label(frame, text=text, justify='left',
                  bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  font=('Arial', 9), wraplength=self.wraplength,
                  padx=8, pady=4).pack()
        Tooltip._active_tooltip = self

    def _hide(self):
        if self.tip_window:
            try:
                self.tip_window.destroy()
            except Exception as _exc:
                biosim_log('warn', '_hide: {}'.format(_exc))
            self.tip_window = None


def simpledialog_float(parent, prompt, initial=0.5, vmin=0.0, vmax=1.0):
    """Simple themed dialog for float input. Returns value or None."""
    result = [None]
    dlg = tk.Toplevel(parent)
    dlg.title(prompt[:30])
    dlg.geometry('360x150')
    dlg.configure(bg=biosim_theme('bg'))
    dlg.transient(parent)
    dlg.resizable(False, False)
    try:
        px = parent.winfo_rootx() + parent.winfo_width() // 2 - 180
        py = parent.winfo_rooty() + parent.winfo_height() // 2 - 75
        dlg.geometry('+{}+{}'.format(max(0, px), max(0, py)))
    except Exception as _exc:
        biosim_log('warn', 'simpledialog_float: {}'.format(_exc))
    tk.Label(dlg, text=prompt, bg=biosim_theme('bg'), fg=biosim_theme('text'),
              font=('Arial', 11)).pack(pady=12)
    var = tk.DoubleVar(value=initial)
    ent = tk.Entry(dlg, textvariable=var,
                    bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                    relief='flat', font=('Arial', 12, 'bold'),
                    highlightthickness=2, highlightbackground=biosim_theme('border'),
                    highlightcolor='#8250df', justify='center')
    ent.pack(fill='x', padx=20, pady=4, ipady=4)
    ent.select_range(0, 'end')
    ent.focus_set()

    def ok():
        try:
            v = float(var.get())
            result[0] = max(vmin, min(vmax, v))
        except Exception as _exc:
            biosim_log('warn', 'ok: {}'.format(_exc))
        dlg.destroy()

    def cancel():
        dlg.destroy()

    btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
    btn_row.pack(fill='x', padx=20, pady=10)
    tk.Button(btn_row, text='OK', bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
               font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
               command=ok).pack(side='left', fill='x', expand=True, padx=2)
    tk.Button(btn_row, text='Cancel', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
               font=('Arial', 10), cursor='hand2', pady=4,
               command=cancel).pack(side='right', padx=2)
    dlg.bind('<Return>', lambda e: ok())
    dlg.bind('<Escape>', lambda e: cancel())
    dlg.wait_window()
    return result[0]


# ═══════════════════════════════════════════════════
# REAL 3D RENDERING ENGINE (numpy-based, no OpenGL)
# Used by 3D Human, 3D Molecule, 3D Plasmid viewers.
# Pipeline:
#   1) Triangle mesh (vertices, faces, colors)
#   2) Apply rotation/translation matrices (model world)
#   3) Apply camera transform (world view space)
#   4) Lighting (Lambertian + ambient + optional specular)
#   5) Perspective projection (view screen)
#   6) Z-sort triangles back-to-front (painter's algorithm)
#   7) Draw filled polygons on Tk Canvas
# ═══════════════════════════════════════════════════

class Render3D:
    """Lightweight 3D scene renderer for Tkinter Canvas using painter's algorithm."""

    def __init__(self, canvas, width=600, height=500, bg_color='#f5f7fa'):
        self.canvas = canvas
        self.width = width
        self.height = height
        self.bg = bg_color
        # Camera
        self.cam_distance = 8.0       # how far camera is from origin
        self.fov = 60.0                # field of view in degrees
        self.rot_x = 0.2               # pitch (radians)
        self.rot_y = 0.4               # yaw   (radians)
        self.cam_target = np.array([0.0, 0.0, 0.0])
        # Lights — list of (direction, intensity, color_tuple)
        self.lights = [
            (np.array([0.6, 0.7, 0.8]), 0.8, (1.0, 1.0, 1.0)),  # main key light
            (np.array([-0.5, -0.3, 0.5]), 0.3, (0.8, 0.9, 1.0)),  # cool fill
        ]
        self.ambient = 0.25  # ambient light intensity
        # Triangle list — each: (v0, v1, v2, base_color_hex, optional_outline)
        self.triangles = []
        # Lines — each: (p0, p1, color, width)
        self.lines = []
        # Labels — each: (position, text, color, font_size)
        self.labels = []
        # Mouse drag state
        self._drag_start = None
        self._wheel_zoom_step = 0.5
        # Render flags
        self.show_wireframe = False
        self.outline_polys = True

    def add_triangle(self, v0, v1, v2, color, outline=None):
        """Add a triangle. Vertices are 3-element arrays."""
        self.triangles.append({
            'v': (np.array(v0, dtype=float),
                   np.array(v1, dtype=float),
                   np.array(v2, dtype=float)),
            'color': color,
            'outline': outline,
        })

    def add_quad(self, v0, v1, v2, v3, color, outline=None):
        """Add a quad as 2 triangles."""
        self.add_triangle(v0, v1, v2, color, outline)
        self.add_triangle(v0, v2, v3, color, outline)

    def add_sphere(self, center, radius, color, segments=12, rings=8):
        """Tesselated sphere mesh."""
        cx, cy, cz = center
        # Generate vertices in a grid
        verts = []
        for i in range(rings + 1):
            theta = math.pi * i / rings  # 0 to pi
            row = []
            for j in range(segments):
                phi = 2 * math.pi * j / segments
                x = cx + radius * math.sin(theta) * math.cos(phi)
                y = cy + radius * math.cos(theta)
                z = cz + radius * math.sin(theta) * math.sin(phi)
                row.append([x, y, z])
            verts.append(row)
        # Connect with triangles
        for i in range(rings):
            for j in range(segments):
                v0 = verts[i][j]
                v1 = verts[i + 1][j]
                v2 = verts[i + 1][(j + 1) % segments]
                v3 = verts[i][(j + 1) % segments]
                self.add_triangle(v0, v1, v2, color)
                self.add_triangle(v0, v2, v3, color)

    def add_cylinder(self, p1, p2, radius, color, segments=10, cap_color=None):
        """Cylinder mesh between two points."""
        p1 = np.array(p1, dtype=float); p2 = np.array(p2, dtype=float)
        axis = p2 - p1
        h = np.linalg.norm(axis)
        if h < 1e-6:
            return
        axis = axis / h
        # Pick a perpendicular vector
        up = np.array([0.0, 1.0, 0.0])
        if abs(np.dot(up, axis)) > 0.99:
            up = np.array([1.0, 0.0, 0.0])
        side1 = np.cross(axis, up); side1 /= np.linalg.norm(side1)
        side2 = np.cross(axis, side1)
        # Generate circle vertices
        ring_a = []  # at p1
        ring_b = []  # at p2
        for i in range(segments):
            t = 2 * math.pi * i / segments
            offset = radius * (math.cos(t) * side1 + math.sin(t) * side2)
            ring_a.append(p1 + offset)
            ring_b.append(p2 + offset)
        # Side faces
        for i in range(segments):
            a0 = ring_a[i]; a1 = ring_a[(i + 1) % segments]
            b0 = ring_b[i]; b1 = ring_b[(i + 1) % segments]
            self.add_triangle(a0, a1, b0, color)
            self.add_triangle(a1, b1, b0, color)
        # Caps
        cap_color = cap_color or color
        for i in range(segments - 1):
            self.add_triangle(p1, ring_a[i + 1], ring_a[i], cap_color)
            self.add_triangle(p2, ring_b[i], ring_b[i + 1], cap_color)

    def add_box(self, center, sx, sy, sz, color):
        """Axis-aligned box."""
        cx, cy, cz = center
        x0, x1 = cx - sx/2, cx + sx/2
        y0, y1 = cy - sy/2, cy + sy/2
        z0, z1 = cz - sz/2, cz + sz/2
        # 8 vertices of box
        V = [
            [x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0],  # back face
            [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1],  # front face
        ]
        # 6 faces (each = 2 triangles)
        faces = [
            (0, 1, 2, 3),  # back
            (4, 7, 6, 5),  # front
            (0, 4, 5, 1),  # bottom
            (3, 2, 6, 7),  # top
            (0, 3, 7, 4),  # left
            (1, 5, 6, 2),  # right
        ]
        for f in faces:
            self.add_quad(V[f[0]], V[f[1]], V[f[2]], V[f[3]], color)

    def add_torus(self, center, major_r, minor_r, color, segments_major=24, segments_minor=10):
        """Torus mesh (donut shape) for 3D plasmid."""
        cx, cy, cz = center
        verts = []
        for i in range(segments_major):
            u = 2 * math.pi * i / segments_major
            row = []
            for j in range(segments_minor):
                v = 2 * math.pi * j / segments_minor
                x = cx + (major_r + minor_r * math.cos(v)) * math.cos(u)
                z = cz + (major_r + minor_r * math.cos(v)) * math.sin(u)
                y = cy + minor_r * math.sin(v)
                row.append([x, y, z])
            verts.append(row)
        for i in range(segments_major):
            for j in range(segments_minor):
                v0 = verts[i][j]
                v1 = verts[(i + 1) % segments_major][j]
                v2 = verts[(i + 1) % segments_major][(j + 1) % segments_minor]
                v3 = verts[i][(j + 1) % segments_minor]
                self.add_triangle(v0, v1, v2, color)
                self.add_triangle(v0, v2, v3, color)

    def add_line(self, p1, p2, color='#ffffff', width=1):
        self.lines.append({
            'p': (np.array(p1, dtype=float), np.array(p2, dtype=float)),
            'color': color, 'width': width
        })

    def add_label(self, position, text, color='#1c2128', font_size=10):
        self.labels.append({
            'pos': np.array(position, dtype=float),
            'text': text, 'color': color, 'fs': font_size
        })

    def clear(self):
        self.triangles = []
        self.lines = []
        self.labels = []

    def _rotation_matrix(self):
        """Combined rotation matrix from current rot_x (pitch) and rot_y (yaw)."""
        cx, sx = math.cos(self.rot_x), math.sin(self.rot_x)
        cy, sy = math.cos(self.rot_y), math.sin(self.rot_y)
        Rx = np.array([[1, 0, 0], [0, cx, -sx], [0, sx, cx]])
        Ry = np.array([[cy, 0, sy], [0, 1, 0], [-sy, 0, cy]])
        return Ry @ Rx

    def _transform_vertex(self, v, R):
        """World view space (apply rotation, then translate camera)."""
        v_rot = R @ (v - self.cam_target)
        # Move forward along z
        v_rot[2] += self.cam_distance
        return v_rot

    def _project(self, v_view):
        """View screen. v_view is (x, y, z) in camera space."""
        z = v_view[2]
        if z < 0.1:
            z = 0.1
        f = self.height / (2 * math.tan(math.radians(self.fov) / 2))
        sx = self.width / 2 + (v_view[0] * f) / z
        sy = self.height / 2 - (v_view[1] * f) / z
        return sx, sy, z

    def _shade(self, normal, base_color):
        """Compute final color from lights and surface normal."""
        # Parse hex
        hx = base_color.lstrip('#')
        r0 = int(hx[0:2], 16) / 255.0
        g0 = int(hx[2:4], 16) / 255.0
        b0 = int(hx[4:6], 16) / 255.0
        # Start with ambient
        r = r0 * self.ambient
        g = g0 * self.ambient
        b = b0 * self.ambient
        # Add each light's contribution
        for light_dir, intensity, light_color in self.lights:
            ld = light_dir / np.linalg.norm(light_dir)
            cos_a = max(0.0, np.dot(normal, ld))
            r += r0 * cos_a * intensity * light_color[0]
            g += g0 * cos_a * intensity * light_color[1]
            b += b0 * cos_a * intensity * light_color[2]
        # Clamp
        r = max(0, min(1, r)); g = max(0, min(1, g)); b = max(0, min(1, b))
        return '#{:02x}{:02x}{:02x}'.format(int(r * 255), int(g * 255), int(b * 255))

    def render(self):
        """Main render: build a depth-sorted list and draw on canvas."""
        if not self.canvas:
            return
        self.canvas.delete('all')
        # Get canvas size
        w = self.canvas.winfo_width()
        h = self.canvas.winfo_height()
        if w > 1 and h > 1:
            self.width = w; self.height = h
        R = self._rotation_matrix()
        # Process each triangle
        prepared = []
        for tri in self.triangles:
            v0, v1, v2 = tri['v']
            v0v = self._transform_vertex(v0, R)
            v1v = self._transform_vertex(v1, R)
            v2v = self._transform_vertex(v2, R)
            # Backface culling
            edge1 = v1v - v0v
            edge2 = v2v - v0v
            normal = np.cross(edge1, edge2)
            n_len = np.linalg.norm(normal)
            if n_len < 1e-8:
                continue
            normal = normal / n_len
            # View-space depth (average z)
            avg_z = (v0v[2] + v1v[2] + v2v[2]) / 3
            if avg_z < 0.5:
                continue
            # Project
            p0 = self._project(v0v)
            p1 = self._project(v1v)
            p2 = self._project(v2v)
            # Determine shading using world normal (transformed)
            # Use the screen-space normal that already includes view rotation
            color = self._shade(-normal, tri['color'])
            prepared.append({
                'type': 'tri', 'z': avg_z,
                'pts': [p0[0], p0[1], p1[0], p1[1], p2[0], p2[1]],
                'color': color, 'outline': tri.get('outline'),
            })
        # Process lines
        for ln in self.lines:
            p1, p2 = ln['p']
            v1 = self._transform_vertex(p1, R)
            v2 = self._transform_vertex(p2, R)
            if v1[2] < 0.5 or v2[2] < 0.5:
                continue
            s1 = self._project(v1); s2 = self._project(v2)
            avg_z = (v1[2] + v2[2]) / 2
            prepared.append({
                'type': 'line', 'z': avg_z,
                'pts': [s1[0], s1[1], s2[0], s2[1]],
                'color': ln['color'], 'width': ln['width'],
            })
        # Process labels
        for lab in self.labels:
            v = self._transform_vertex(lab['pos'], R)
            if v[2] < 0.5:
                continue
            s = self._project(v)
            prepared.append({
                'type': 'label', 'z': v[2] - 0.01,  # always render labels on top
                'pos': (s[0], s[1]),
                'text': lab['text'], 'color': lab['color'], 'fs': lab['fs'],
            })
        # Z-sort back to front (painter's algorithm)
        prepared.sort(key=lambda x: -x['z'])
        # Draw all
        for item in prepared:
            if item['type'] == 'tri':
                outline = item.get('outline')
                if self.outline_polys and not outline:
                    outline = item['color']  # use same color for soft outline
                self.canvas.create_polygon(item['pts'], fill=item['color'],
                                              outline=outline if outline else '',
                                              width=1 if outline else 0)
            elif item['type'] == 'line':
                self.canvas.create_line(item['pts'], fill=item['color'],
                                           width=item['width'])
            elif item['type'] == 'label':
                self.canvas.create_text(item['pos'][0], item['pos'][1],
                                           text=item['text'], fill=item['color'],
                                           font=('Arial', item['fs'], 'bold'))

    def attach_mouse(self):
        """Bind mouse drag to rotate, wheel to zoom."""
        self.canvas.bind('<Button-1>', self._on_drag_start)
        self.canvas.bind('<B1-Motion>', self._on_drag)
        self.canvas.bind('<ButtonRelease-1>', self._on_drag_end)
        # macOS wheel and trackpad
        self.canvas.bind('<MouseWheel>', self._on_wheel)
        self.canvas.bind('<Button-4>', lambda e: self._zoom(1))
        self.canvas.bind('<Button-5>', lambda e: self._zoom(-1))

    def _on_drag_start(self, event):
        self._drag_start = (event.x, event.y)

    def _on_drag(self, event):
        if self._drag_start is None:
            return
        dx = event.x - self._drag_start[0]
        dy = event.y - self._drag_start[1]
        self.rot_y += dx * 0.01
        self.rot_x += dy * 0.01
        self.rot_x = max(-math.pi/2 + 0.01, min(math.pi/2 - 0.01, self.rot_x))
        self._drag_start = (event.x, event.y)
        self.render()

    def _on_drag_end(self, event):
        self._drag_start = None

    def _on_wheel(self, event):
        # macOS wheel delta is small
        delta = event.delta
        if delta > 0:
            self._zoom(1)
        else:
            self._zoom(-1)

    def _zoom(self, direction):
        self.cam_distance = max(2.0, min(50.0, self.cam_distance - direction * self._wheel_zoom_step))
        self.render()


class Human3DViewer:
    """True 3D human body with rotatable view, organ highlighting,
    breathing animation, and disease severity coloring.
    Uses Render3D engine — works on any Tkinter canvas.
    """

    # Realistic anatomy colors (slightly warm/cool)
    SKIN          = '#e8b89c'
    SKIN_LIGHT    = '#f4cfb4'
    BONE          = '#e8e0d0'
    MUSCLE        = '#c47b75'
    HEART         = '#c0392b'
    LUNG          = '#e88299'
    LIVER         = '#7a3a2a'
    KIDNEY        = '#a8483c'
    BRAIN         = '#e0a8b0'
    PANCREAS      = '#d49060'
    STOMACH       = '#c08060'
    INTESTINE     = '#b07060'
    SPLEEN        = '#883030'
    BLADDER       = '#d8c060'
    THYROID       = '#c08888'
    GALLBLADDER   = '#7a8030'

    # Anatomical landmarks (in local body coordinates, Y is up)
    # Used by click-detection and labels
    ORGAN_POSITIONS = {
        'brain':       (0, 4.8, 0.0),
        'eyes':        (0, 4.6, 0.4),
        'thyroid':     (0, 3.6, 0.25),
        'heart':       (-0.25, 2.7, 0.2),
        'lung_l':      (-0.7, 2.8, 0.0),
        'lung_r':      (0.7, 2.8, 0.0),
        'liver':       (0.5, 1.9, 0.15),
        'stomach':     (-0.3, 1.9, 0.15),
        'gallbladder': (0.55, 1.7, 0.15),
        'pancreas':    (0.0, 1.7, 0.0),
        'spleen':      (-0.65, 1.9, 0.0),
        'kidney_l':    (-0.55, 1.6, -0.3),
        'kidney_r':    (0.55, 1.6, -0.3),
        'intestine':   (0.0, 1.0, 0.15),
        'bladder':     (0.0, 0.4, 0.15),
    }

    def __init__(self, canvas, lang='ru'):
        self.canvas = canvas
        self.lang = lang
        self.renderer = Render3D(canvas, bg_color='#f5f7fa')
        self.highlight_organs = set()      # which organs to glow
        self.severity = 0.0                 # 0..1 disease severity
        self.severity_color = '#cf222e'     # base color for sick organs
        self.show_xray = False              # transparent body mode
        self.show_skeleton = False          # show bones
        self.breathing_phase = 0.0          # for animation
        self.animation_running = False
        self._after_id = None
        self._build_static_meshes()

    def _build_static_meshes(self):
        """Build the body geometry once. Animated parts are rebuilt every frame."""
        self.body_parts = {}  # cached meshes per organ

    def set_disease(self, organ_keys, severity, color='#cf222e'):
        """Highlight given organs with severity (0..1) and color."""
        self.highlight_organs = set(organ_keys or [])
        self.severity = max(0.0, min(1.0, severity))
        self.severity_color = color
        self.render()

    def clear_disease(self):
        self.highlight_organs = set()
        self.severity = 0.0
        self.render()

    def render(self):
        """Build all meshes from scratch, then render."""
        self.renderer.clear()
        # Build body in order from back to front; engine z-sorts anyway
        self._add_legs()
        self._add_torso()
        self._add_organs()
        self._add_arms()
        self._add_head()
        # Render
        self.renderer.render()

    def _organ_color(self, organ_key, base_color):
        """Apply disease severity coloring if this organ is highlighted."""
        if organ_key in self.highlight_organs and self.severity > 0:
            # Mix base color with severity color
            base = base_color.lstrip('#')
            sev = self.severity_color.lstrip('#')
            br = int(base[0:2], 16); bg = int(base[2:4], 16); bb = int(base[4:6], 16)
            sr = int(sev[0:2], 16); sg = int(sev[2:4], 16); sb = int(sev[4:6], 16)
            t = self.severity * 0.7
            r = int(br * (1 - t) + sr * t)
            g = int(bg * (1 - t) + sg * t)
            b = int(bb * (1 - t) + sb * t)
            return '#{:02x}{:02x}{:02x}'.format(r, g, b)
        return base_color

    def _add_head(self):
        # Skull as sphere
        head_y = 4.7
        self.renderer.add_sphere([0, head_y, 0], 0.55,
                                    self._organ_color('brain', self.SKIN),
                                    segments=14, rings=10)
        # Neck cylinder
        self.renderer.add_cylinder([0, head_y - 0.55, 0], [0, 3.4, 0],
                                      0.18, self.SKIN, segments=10)
        # Hair cap (slightly larger top half)
        for i in range(10):
            t = math.pi * i / 10
            r = 0.5 + 0.05 * math.sin(t)
            y = head_y + 0.3 + 0.2 * math.cos(t)
            self.renderer.add_sphere([0, y, -0.05], r * 0.4, '#3a2820',
                                        segments=10, rings=4)
            break  # one bigger sphere is enough
        self.renderer.add_sphere([0, head_y + 0.25, -0.05], 0.5,
                                    '#3a2820', segments=12, rings=4)

    def _add_torso(self):
        # Tapered torso = stack of ellipsoids
        # Shoulders (wide)
        for y, sx, sz in [(3.2, 1.4, 0.6), (2.8, 1.45, 0.65),
                            (2.0, 1.3, 0.6), (1.3, 1.15, 0.55), (0.7, 1.05, 0.5)]:
            # Approximate ellipsoid as sphere scaled — fake by adding box
            self._add_ellipsoid([0, y, 0], sx, 0.35, sz, self.SKIN)

    def _add_ellipsoid(self, center, sx, sy, sz, color):
        """Approximate ellipsoid by adjusting sphere coordinates."""
        cx, cy, cz = center
        segments = 12
        rings = 6
        verts = []
        for i in range(rings + 1):
            theta = math.pi * i / rings
            row = []
            for j in range(segments):
                phi = 2 * math.pi * j / segments
                x = cx + sx * math.sin(theta) * math.cos(phi)
                y = cy + sy * math.cos(theta)
                z = cz + sz * math.sin(theta) * math.sin(phi)
                row.append([x, y, z])
            verts.append(row)
        for i in range(rings):
            for j in range(segments):
                v0 = verts[i][j]
                v1 = verts[i + 1][j]
                v2 = verts[i + 1][(j + 1) % segments]
                v3 = verts[i][(j + 1) % segments]
                self.renderer.add_triangle(v0, v1, v2, color)
                self.renderer.add_triangle(v0, v2, v3, color)

    def _add_arms(self):
        for side in (-1, 1):
            sx = side * 1.4
            # Shoulder joint
            self.renderer.add_sphere([sx, 3.0, 0], 0.25, self.SKIN,
                                        segments=10, rings=6)
            # Upper arm
            self.renderer.add_cylinder([sx, 2.9, 0], [sx + side * 0.3, 1.8, 0.1],
                                          0.18, self.SKIN, segments=10)
            # Elbow
            self.renderer.add_sphere([sx + side * 0.3, 1.8, 0.1], 0.18,
                                        self.SKIN, segments=8, rings=5)
            # Forearm
            self.renderer.add_cylinder([sx + side * 0.3, 1.8, 0.1],
                                          [sx + side * 0.4, 0.85, 0.2],
                                          0.15, self.SKIN, segments=10)
            # Hand
            self.renderer.add_sphere([sx + side * 0.4, 0.75, 0.2], 0.18,
                                        self.SKIN, segments=8, rings=5)

    def _add_legs(self):
        for side in (-1, 1):
            sx = side * 0.4
            # Hip
            self.renderer.add_sphere([sx, 0.5, 0], 0.3, self.SKIN,
                                        segments=10, rings=6)
            # Thigh
            self.renderer.add_cylinder([sx, 0.5, 0], [sx * 0.8, -1.5, 0],
                                          0.28, self.SKIN, segments=10)
            # Knee
            self.renderer.add_sphere([sx * 0.8, -1.5, 0], 0.22,
                                        self.SKIN, segments=8, rings=5)
            # Shin
            self.renderer.add_cylinder([sx * 0.8, -1.5, 0],
                                          [sx * 0.7, -3.4, 0.1],
                                          0.18, self.SKIN, segments=10)
            # Foot
            self.renderer.add_box([sx * 0.7, -3.5, 0.3], 0.4, 0.2, 0.7, self.SKIN)

    def _add_organs(self):
        """Add internal organs. Visible regardless of body opacity."""
        if self.show_xray or self.highlight_organs:
            # Show organs explicitly if x-ray or any disease highlight
            self._add_heart()
            self._add_lungs()
            self._add_liver()
            self._add_kidneys()
            self._add_brain()
            self._add_stomach()
            self._add_pancreas()
            self._add_intestine()
            self._add_bladder()
            self._add_spleen()
            self._add_thyroid()
            self._add_gallbladder()

    def _add_heart(self):
        col = self._organ_color('heart', self.HEART)
        pos = self.ORGAN_POSITIONS['heart']
        self._add_ellipsoid(pos, 0.28, 0.32, 0.22, col)
        if 'heart' in self.highlight_organs:
            self.renderer.add_label([pos[0], pos[1] + 0.5, pos[2]],
                                       'Сердце' if self.lang == 'ru' else 'Heart',
                                       color='#ffeb3b', font_size=9)

    def _add_lungs(self):
        for key, side in [('lung_l', -1), ('lung_r', 1)]:
            col = self._organ_color(key if key in self.highlight_organs else 'lungs',
                                       self.LUNG)
            # use 'lungs' as alias
            if 'lungs' in self.highlight_organs:
                col = self._organ_color('lungs', self.LUNG)
            pos = self.ORGAN_POSITIONS[key]
            self._add_ellipsoid(pos, 0.4, 0.7, 0.3, col)

    def _add_liver(self):
        col = self._organ_color('liver', self.LIVER)
        pos = self.ORGAN_POSITIONS['liver']
        self._add_ellipsoid(pos, 0.55, 0.35, 0.3, col)

    def _add_kidneys(self):
        for key in ['kidney_l', 'kidney_r']:
            col = self._organ_color('kidneys' if 'kidneys' in self.highlight_organs else key,
                                       self.KIDNEY)
            pos = self.ORGAN_POSITIONS[key]
            self._add_ellipsoid(pos, 0.18, 0.3, 0.18, col)

    def _add_brain(self):
        if 'brain' in self.highlight_organs:
            col = self._organ_color('brain', self.BRAIN)
            pos = self.ORGAN_POSITIONS['brain']
            self._add_ellipsoid(pos, 0.45, 0.4, 0.4, col)

    def _add_stomach(self):
        col = self._organ_color('stomach', self.STOMACH)
        pos = self.ORGAN_POSITIONS['stomach']
        self._add_ellipsoid(pos, 0.3, 0.25, 0.2, col)

    def _add_pancreas(self):
        col = self._organ_color('pancreas', self.PANCREAS)
        pos = self.ORGAN_POSITIONS['pancreas']
        self._add_ellipsoid(pos, 0.4, 0.1, 0.12, col)

    def _add_intestine(self):
        col = self._organ_color('intestine', self.INTESTINE)
        pos = self.ORGAN_POSITIONS['intestine']
        # Coil-like: stack of small spheres in a spiral
        for i in range(8):
            a = i * math.pi / 4
            r = 0.4
            x = pos[0] + r * math.cos(a)
            y = pos[1] - 0.15 + 0.05 * i
            z = pos[2] + r * math.sin(a) * 0.3
            self.renderer.add_sphere([x, y, z], 0.15, col, segments=8, rings=4)

    def _add_bladder(self):
        col = self._organ_color('bladder', self.BLADDER)
        pos = self.ORGAN_POSITIONS['bladder']
        self._add_ellipsoid(pos, 0.25, 0.2, 0.2, col)

    def _add_spleen(self):
        col = self._organ_color('spleen', self.SPLEEN)
        pos = self.ORGAN_POSITIONS['spleen']
        self._add_ellipsoid(pos, 0.22, 0.25, 0.18, col)

    def _add_thyroid(self):
        col = self._organ_color('thyroid', self.THYROID)
        pos = self.ORGAN_POSITIONS['thyroid']
        self._add_ellipsoid(pos, 0.22, 0.1, 0.15, col)

    def _add_gallbladder(self):
        col = self._organ_color('gallbladder', self.GALLBLADDER)
        pos = self.ORGAN_POSITIONS['gallbladder']
        self._add_ellipsoid(pos, 0.1, 0.15, 0.08, col)

    def toggle_xray(self):
        self.show_xray = not self.show_xray
        # When xray, we'd want body translucent — approximation: just always show organs
        self.render()

    def start_animation(self):
        """Start subtle breathing animation."""
        if self.animation_running:
            return
        self.animation_running = True
        self._animate_step()

    def stop_animation(self):
        self.animation_running = False
        if self._after_id is not None:
            try:
                self.canvas.after_cancel(self._after_id)
            except Exception as _exc:
                biosim_log('warn', 'stop_animation: {}'.format(_exc))
            self._after_id = None

    def _animate_step(self):
        if not self.animation_running:
            return
        self.breathing_phase += 0.08
        # Subtle Y rotation drift (auto-rotate slowly)
        self.renderer.rot_y += 0.005
        self.render()
        self._after_id = self.canvas.after(80, self._animate_step)

    def attach_mouse(self):
        """Attach mouse drag rotation."""
        self.renderer.attach_mouse()


class Molecule3DViewer:
    """3D ball-and-stick molecule viewer.
    Generates 3D coordinates from SMILES via RDKit (if available),
    or uses a built-in library of common molecule structures.
    """

    # CPK-style element colors (standard in chemistry)
    ATOM_COLORS = {
        'H':  '#ffffff', 'C':  '#909090', 'N':  '#3050f8', 'O':  '#ff0d0d',
        'F':  '#90e050', 'P':  '#ff8000', 'S':  '#ffff30', 'Cl': '#1ff01f',
        'Br': '#a62929', 'I':  '#940094', 'Na': '#ab5cf2', 'Mg': '#8aff00',
        'Ca': '#3dff00', 'Fe': '#e06633', 'Zn': '#7d80b0', 'Cu': '#c88033',
        'K':  '#8f40d4',  'Mn': '#9c7ac7', 'B':  '#ffb5b5', 'Si': '#f0c8a0',
    }

    # Van der Waals radii (Angstrom) — scaled down for rendering
    ATOM_RADII = {
        'H':  0.20, 'C':  0.35, 'N':  0.34, 'O':  0.32, 'F':  0.30,
        'P':  0.40, 'S':  0.40, 'Cl': 0.38, 'Br': 0.43, 'I':  0.50,
        'Na': 0.45, 'Mg': 0.40, 'Ca': 0.50, 'Fe': 0.40, 'Zn': 0.45,
        'Cu': 0.45, 'K':  0.50, 'Mn': 0.42, 'B':  0.35, 'Si': 0.40,
    }

    # Built-in 3D structures for common molecules (when RDKit unavailable
    # or for very common ones) — list of (element, x, y, z) and bond list
    BUILTIN_MOLECULES = {
        'water': {
            'name': 'H₂O — Вода / Water',
            'atoms': [('O', 0.0, 0.0, 0.0),
                       ('H', 0.76, 0.59, 0.0),
                       ('H', -0.76, 0.59, 0.0)],
            'bonds': [(0, 1, 1), (0, 2, 1)],
        },
        'methane': {
            'name': 'CH₄ — Метан / Methane',
            'atoms': [('C', 0.0, 0.0, 0.0),
                       ('H', 0.63, 0.63, 0.63),
                       ('H', -0.63, -0.63, 0.63),
                       ('H', -0.63, 0.63, -0.63),
                       ('H', 0.63, -0.63, -0.63)],
            'bonds': [(0, 1, 1), (0, 2, 1), (0, 3, 1), (0, 4, 1)],
        },
        'glucose': {
            'name': 'Glucose / Глюкоза C₆H₁₂O₆',
            'smiles': 'OC[C@H]1OC(O)[C@H](O)[C@@H](O)[C@@H]1O',
        },
        'atp': {
            'name': 'ATP / АТФ',
            'smiles': 'C1=NC(=C2C(=N1)N(C=N2)[C@H]3[C@@H]([C@@H]([C@H](O3)COP(=O)(O)OP(=O)(O)OP(=O)(O)O)O)O)N',
        },
        'caffeine': {
            'name': 'Caffeine / Кофеин',
            'smiles': 'CN1C=NC2=C1C(=O)N(C(=O)N2C)C',
        },
        'co2': {
            'name': 'CO₂ — Углекислый газ',
            'atoms': [('C', 0.0, 0.0, 0.0),
                       ('O', 1.16, 0.0, 0.0),
                       ('O', -1.16, 0.0, 0.0)],
            'bonds': [(0, 1, 2), (0, 2, 2)],
        },
        'ethanol': {
            'name': 'Ethanol / Этанол C₂H₅OH',
            'smiles': 'CCO',
        },
        'iptg': {
            'name': 'IPTG (lac inducer)',
            'smiles': 'CC(C)SC1OC(CO)C(O)C(O)C1O',
        },
        'amp': {
            'name': 'AMP',
            'smiles': 'OC[C@H]1O[C@@H](N2C=NC3=C2N=CN=C3N)[C@H](O)[C@@H]1OP(O)(O)=O',
        },
        'nad': {
            'name': 'NAD+',
            'smiles': 'NC(=O)C1=CC=C[N+](=C1)C1OC(COP(O)(=O)OP(O)(=O)OCC2OC(N3C=NC4=C3N=CN=C4N)C(O)C2O)C(O)C1O',
        },
    }

    def __init__(self, canvas, lang='ru'):
        self.canvas = canvas
        self.lang = lang
        self.renderer = Render3D(canvas, bg_color='#f5f7fa')
        self.atoms = []         # list of (element, x, y, z)
        self.bonds = []         # list of (atom1_idx, atom2_idx, bond_order)
        self.molecule_name = ''
        self.show_hydrogens = True
        self.show_labels = False  # show element symbols on atoms

    def load_from_smiles(self, smiles, name=''):
        """Generate 3D coordinates from SMILES string using RDKit."""
        if not _ensure_rdkit():
            return False, 'RDKit не установлен' if self.lang == 'ru' else 'RDKit not installed'
        try:
            mol = Chem.MolFromSmiles(smiles)
            if mol is None:
                return False, 'Invalid SMILES'
            mol = Chem.AddHs(mol)
            # Generate 3D coords
            result = AllChem.EmbedMolecule(mol, randomSeed=42)
            if result == -1:
                # Try with random seed
                result = AllChem.EmbedMolecule(mol, useRandomCoords=True, randomSeed=123)
            if result == -1:
                return False, 'Could not generate 3D coordinates'
            # Optimize geometry
            try:
                AllChem.MMFFOptimizeMolecule(mol, maxIters=200)
            except Exception:
                try:
                    AllChem.UFFOptimizeMolecule(mol, maxIters=200)
                except Exception as _exc:
                    biosim_log('warn', 'load_from_smiles: {}'.format(_exc))
            # Extract atoms and bonds
            conf = mol.GetConformer()
            self.atoms = []
            for atom in mol.GetAtoms():
                pos = conf.GetAtomPosition(atom.GetIdx())
                self.atoms.append((atom.GetSymbol(), pos.x, pos.y, pos.z))
            self.bonds = []
            for bond in mol.GetBonds():
                self.bonds.append((bond.GetBeginAtomIdx(),
                                    bond.GetEndAtomIdx(),
                                    int(bond.GetBondTypeAsDouble())))
            self.molecule_name = name
            self._center_atoms()
            return True, 'Loaded {} atoms, {} bonds'.format(
                len(self.atoms), len(self.bonds))
        except Exception as e:
            biosim_log('warn', 'load_from_smiles: {}'.format(e))
            return False, 'RDKit error: ' + str(e)[:100]

    def load_builtin(self, key):
        """Load a built-in molecule by key."""
        if key not in self.BUILTIN_MOLECULES:
            return False, 'Unknown molecule: ' + key
        mol_data = self.BUILTIN_MOLECULES[key]
        if 'atoms' in mol_data:
            # Explicit atoms/bonds
            self.atoms = list(mol_data['atoms'])
            self.bonds = list(mol_data['bonds'])
            self.molecule_name = mol_data['name']
            self._center_atoms()
            return True, 'Loaded built-in: ' + mol_data['name']
        elif 'smiles' in mol_data:
            return self.load_from_smiles(mol_data['smiles'], mol_data['name'])
        return False, 'No structure data'

    def _center_atoms(self):
        """Center the molecule at origin."""
        if not self.atoms:
            return
        xs = [a[1] for a in self.atoms]
        ys = [a[2] for a in self.atoms]
        zs = [a[3] for a in self.atoms]
        cx = sum(xs) / len(xs); cy = sum(ys) / len(ys); cz = sum(zs) / len(zs)
        self.atoms = [(e, x - cx, y - cy, z - cz) for e, x, y, z in self.atoms]
        # Auto-scale camera distance
        max_dist = max(
            math.sqrt(a[1]**2 + a[2]**2 + a[3]**2) for a in self.atoms)
        self.renderer.cam_distance = max(5.0, max_dist * 4)

    def render(self):
        """Build mesh and render."""
        self.renderer.clear()
        if not self.atoms:
            return
        # Decide whether to show hydrogens
        show_atom = [True] * len(self.atoms)
        if not self.show_hydrogens:
            for i, (elem, x, y, z) in enumerate(self.atoms):
                if elem == 'H':
                    show_atom[i] = False
        # Draw atoms (sphere)
        for i, (elem, x, y, z) in enumerate(self.atoms):
            if not show_atom[i]:
                continue
            color = self.ATOM_COLORS.get(elem, '#ff00ff')  # magenta for unknown
            radius = self.ATOM_RADII.get(elem, 0.35)
            self.renderer.add_sphere([x, y, z], radius, color,
                                        segments=12, rings=8)
            # Label
            if self.show_labels:
                self.renderer.add_label([x, y + radius + 0.1, z], elem,
                                           color='#ffffff', font_size=11)
        # Draw bonds (cylinder)
        for a1, a2, order in self.bonds:
            if a1 >= len(self.atoms) or a2 >= len(self.atoms):
                continue
            if not show_atom[a1] or not show_atom[a2]:
                continue
            elem1, x1, y1, z1 = self.atoms[a1]
            elem2, x2, y2, z2 = self.atoms[a2]
            # Two half-bonds with each atom's color (more realistic)
            mid = [(x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2]
            color1 = self.ATOM_COLORS.get(elem1, '#909090')
            color2 = self.ATOM_COLORS.get(elem2, '#909090')
            bond_radius = 0.08 if order == 1 else 0.10
            # Single bond
            if order == 1:
                self.renderer.add_cylinder([x1, y1, z1], mid, bond_radius,
                                              color1, segments=8)
                self.renderer.add_cylinder(mid, [x2, y2, z2], bond_radius,
                                              color2, segments=8)
            elif order == 2:
                # Double bond — 2 parallel cylinders
                # Pick perpendicular direction
                dx = x2 - x1; dy = y2 - y1; dz = z2 - z1
                length = math.sqrt(dx*dx + dy*dy + dz*dz)
                if length > 0.001:
                    # Find a perpendicular vector
                    if abs(dy) < 0.9:
                        perp = (-dz, 0, dx)
                    else:
                        perp = (1, 0, 0)
                    plen = math.sqrt(perp[0]**2 + perp[1]**2 + perp[2]**2)
                    if plen > 0.001:
                        sep = 0.12
                        px = perp[0] / plen * sep
                        py = perp[1] / plen * sep
                        pz = perp[2] / plen * sep
                        for sign in (-1, 1):
                            mid_off = [mid[0] + px * sign, mid[1] + py * sign, mid[2] + pz * sign]
                            self.renderer.add_cylinder(
                                [x1 + px * sign, y1 + py * sign, z1 + pz * sign],
                                mid_off, bond_radius * 0.7, color1, segments=6)
                            self.renderer.add_cylinder(
                                mid_off,
                                [x2 + px * sign, y2 + py * sign, z2 + pz * sign],
                                bond_radius * 0.7, color2, segments=6)
            else:  # triple bond
                # 3 parallel cylinders — simplified as one thick + two thin
                self.renderer.add_cylinder([x1, y1, z1], mid, bond_radius * 1.5,
                                              color1, segments=8)
                self.renderer.add_cylinder(mid, [x2, y2, z2], bond_radius * 1.5,
                                              color2, segments=8)
        self.renderer.render()

    def attach_mouse(self):
        self.renderer.attach_mouse()

    @staticmethod
    def get_molecule_list(lang='ru'):
        """Return list of built-in molecules for UI dropdown."""
        return [(k, Molecule3DViewer.BUILTIN_MOLECULES[k]['name'])
                  for k in Molecule3DViewer.BUILTIN_MOLECULES]


class Open3DMoleculeWindow(tk.Toplevel):
    """Stand-alone 3D molecule viewer window. Opened from Properties dialog
    or from a menu. Supports built-in molecules, SMILES input, and PubChem name lookup.
    """

    def __init__(self, parent, lang='ru', initial_smiles=None, initial_name='Molecule'):
        super().__init__(parent)
        self.lang = lang
        self.title('3D Molecule Viewer — VIREON')
        self.geometry('820x720')
        self.configure(bg=biosim_theme('bg'))
        self.transient(parent)

        # Header
        header = tk.Frame(self, bg=biosim_theme('bg')); header.pack(fill='x', pady=8)
        tk.Label(header, text='3D Molecule Viewer',
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 16, 'bold')).pack()
        tk.Label(header,
                  text=('Перетаскивай мышью для вращения · колёсико для зума'
                        if lang == 'ru' else
                        'Drag mouse to rotate · wheel to zoom'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()

        # SMILES input row
        # Internet search by name (PubChem)
        search_row = tk.Frame(self, bg=biosim_theme('bg'))
        search_row.pack(fill='x', padx=14, pady=4)
        tk.Label(search_row, text=('Поиск:' if lang == 'ru' else 'Search:'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 10, 'bold')).pack(side='left', padx=4)
        self.mol_search_var = tk.StringVar()
        se = tk.Entry(search_row, textvariable=self.mol_search_var,
                       bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                       relief='flat', font=('Arial', 10),
                       highlightthickness=1, highlightbackground=biosim_theme('border'))
        se.pack(side='left', fill='x', expand=True, padx=4, ipady=3)
        se.bind('<Return>', lambda e: self._search_pubchem())
        tk.Button(search_row, text=('Найти в интернете' if lang == 'ru' else 'Search online'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 9, 'bold'), cursor='hand2',
                   command=self._search_pubchem).pack(side='left', padx=4)
        self.mol_search_status = tk.Label(self, text='', bg=biosim_theme('bg'),
                                           fg=biosim_theme('text_dim'), font=('Arial', 9))
        self.mol_search_status.pack(padx=14)

        smiles_row = tk.Frame(self, bg=biosim_theme('bg'))
        smiles_row.pack(fill='x', padx=14, pady=4)
        tk.Label(smiles_row, text='SMILES:',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(side='left', padx=4)
        self.smiles_var = tk.StringVar(value=initial_smiles or '')
        tk.Entry(smiles_row, textvariable=self.smiles_var,
                  bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                  relief='flat', font=('Courier', 10),
                  highlightthickness=1, highlightbackground=biosim_theme('border')
                  ).pack(side='left', fill='x', expand=True, padx=4, ipady=3)
        tk.Button(smiles_row, text='Загрузить' if lang == 'ru' else 'Load',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 9, 'bold'), cursor='hand2',
                   command=self._load_from_smiles).pack(side='left', padx=4)

        # Built-in molecules dropdown
        builtin_row = tk.Frame(self, bg=biosim_theme('bg'))
        builtin_row.pack(fill='x', padx=14, pady=4)
        tk.Label(builtin_row,
                  text='Готовые молекулы:' if lang == 'ru' else 'Built-in molecules:',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(side='left', padx=4)
        builtin_list = Molecule3DViewer.get_molecule_list(lang)
        self._builtin_keys = [k for k, _ in builtin_list]
        self.builtin_var = tk.StringVar()
        ttk_combo = ttk.Combobox(builtin_row, textvariable=self.builtin_var,
                                    values=[n for _, n in builtin_list],
                                    state='readonly', font=('Arial', 10))
        ttk_combo.pack(side='left', fill='x', expand=True, padx=4)
        ttk_combo.bind('<<ComboboxSelected>>', self._on_builtin_selected)
        self._builtin_combo = ttk_combo

        # Canvas
        self.canvas = tk.Canvas(self, bg=biosim_theme('bg'), highlightthickness=0,
                                  cursor='fleur')
        self.canvas.pack(fill='both', expand=True, padx=14, pady=4)

        # Viewer
        self.viewer = Molecule3DViewer(self.canvas, lang=lang)
        self.viewer.attach_mouse()

        # Info label below canvas
        self.info_lbl = tk.Label(self, text='',
                                    bg=biosim_theme('bg'), fg='#0550ae',
                                    font=('Arial', 10, 'italic'))
        self.info_lbl.pack(pady=4)

        # Control buttons
        ctrl = tk.Frame(self, bg=biosim_theme('bg')); ctrl.pack(fill='x', padx=14, pady=8)

        self.show_h_var = tk.BooleanVar(value=True)
        tk.Checkbutton(ctrl,
                        text='Показать H' if lang == 'ru' else 'Show H',
                        variable=self.show_h_var, command=self._toggle_h,
                        bg=biosim_theme('bg'), fg=biosim_theme('text'), selectcolor='#eef1f5',
                        activebackground='#f5f7fa', font=('Arial', 9)
                        ).pack(side='left', padx=4)

        self.show_lbl_var = tk.BooleanVar(value=False)
        tk.Checkbutton(ctrl,
                        text='Метки' if lang == 'ru' else 'Labels',
                        variable=self.show_lbl_var, command=self._toggle_labels,
                        bg=biosim_theme('bg'), fg=biosim_theme('text'), selectcolor='#eef1f5',
                        activebackground='#f5f7fa', font=('Arial', 9)
                        ).pack(side='left', padx=4)

        tk.Button(ctrl, text='⟲ ' + ('Сброс' if lang == 'ru' else 'Reset'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 9, 'bold'), cursor='hand2', pady=4,
                   command=self._reset_view).pack(side='left', padx=4)

        tk.Button(ctrl, text='Закрыть' if lang == 'ru' else 'Close',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=self.destroy).pack(side='right', padx=4)

        # Load initial structure
        if initial_smiles:
            self.after(150, self._load_from_smiles)
        else:
            # Default to glucose
            self.after(150, lambda: self._load_builtin_key('glucose'))

    def _search_pubchem(self):
        """Search PubChem for a molecule by name, then load its 3D structure."""
        is_ru = (self.lang == 'ru' if hasattr(self, 'lang') else True)
        query = self.mol_search_var.get().strip()
        if not query:
            return
        self.mol_search_status.config(text=('Поиск в PubChem...' if is_ru
                                             else 'Searching PubChem...'), fg='#9a6700')
        self.update()

        def worker():
            result = search_pubchem_molecule(query, max_results=1)
            def done():
                if result.get('error'):
                    self.mol_search_status.config(
                        text=('Ошибка: ' if is_ru else 'Error: ') + str(result['error'])
                        + ('  (нужен интернет)' if is_ru else '  (internet needed)'),
                        fg='#cf222e')
                    return
                results = result.get('results', [])
                if not results:
                    self.mol_search_status.config(
                        text=('Не найдено' if is_ru else 'Not found'), fg='#cf222e')
                    return
                mol = results[0]
                cid = mol['cid']
                self.mol_search_status.config(
                    text=('Загрузка 3D (CID {})...'.format(cid) if is_ru
                          else 'Loading 3D (CID {})...'.format(cid)), fg='#9a6700')
                self.update()

                def fetch_worker():
                    struct = fetch_pubchem_3d(cid)
                    def show():
                        if struct.get('error'):
                            self.mol_search_status.config(
                                text=('Ошибка 3D: ' if is_ru else '3D error: ')
                                + str(struct['error']), fg='#cf222e')
                            return
                        # Convert to viewer format and display
                        self._load_from_structure(struct, mol.get('formula', query))
                        self.mol_search_status.config(
                            text='{} — {} '.format(query, struct['n_atoms'])
                            + ('атомов' if is_ru else 'atoms'), fg='#1a7f37')
                    self.after(0, show)
                threading.Thread(target=fetch_worker, daemon=True).start()
            self.after(0, done)
        threading.Thread(target=worker, daemon=True).start()

    def _load_from_structure(self, struct, name='Molecule'):
        """Load a parsed structure (from PubChem) into the 3D viewer."""
        atoms = [(a['element'], a['x'], a['y'], a['z']) for a in struct['atoms']]
        bonds = [(b['a1'], b['a2'], b['order']) for b in struct['bonds']]
        try:
            self.viewer.atoms = atoms
            self.viewer.bonds = bonds
            if hasattr(self.viewer, '_center_atoms'):
                self.viewer._center_atoms()
            self.viewer.render()
        except Exception as e:
            biosim_log('error', 'load structure failed: ' + str(e))

    def _load_from_smiles(self):
        smiles = self.smiles_var.get().strip()
        if not smiles:
            return
        self.info_lbl.config(text='Загрузка...' if self.lang == 'ru' else 'Loading...',
                              fg='#9a6700')
        self.update()
        ok, msg = self.viewer.load_from_smiles(smiles, 'Custom SMILES')
        if ok:
            self.info_lbl.config(text='' + msg, fg='#1a7f37')
            self.viewer.render()
        else:
            self.info_lbl.config(text='' + msg, fg='#cf222e')

    def _on_builtin_selected(self, event=None):
        idx = self._builtin_combo.current()
        if idx < 0:
            return
        key = self._builtin_keys[idx]
        self._load_builtin_key(key)

    def _load_builtin_key(self, key):
        self.info_lbl.config(text='Загрузка...' if self.lang == 'ru' else 'Loading...',
                              fg='#9a6700')
        self.update()
        ok, msg = self.viewer.load_builtin(key)
        if ok:
            self.info_lbl.config(text='' + msg, fg='#1a7f37')
            # Also fill SMILES box if available
            mol_data = Molecule3DViewer.BUILTIN_MOLECULES.get(key, {})
            if 'smiles' in mol_data:
                self.smiles_var.set(mol_data['smiles'])
            self.viewer.render()
        else:
            self.info_lbl.config(text='' + msg, fg='#cf222e')

    def _toggle_h(self):
        self.viewer.show_hydrogens = self.show_h_var.get()
        self.viewer.render()

    def _toggle_labels(self):
        self.viewer.show_labels = self.show_lbl_var.get()
        self.viewer.render()

    def _reset_view(self):
        self.viewer.renderer.rot_x = 0.2
        self.viewer.renderer.rot_y = 0.4
        if self.viewer.atoms:
            self.viewer._center_atoms()
        self.viewer.render()


class Plasmid3DViewer:
    """3D circular plasmid viewer.
    Draws DNA as a torus (donut) with parts attached around the circumference.
    Each genetic part (promoter, RBS, CDS, terminator) is a 3D object.
    """

    # Part-to-color mapping (matches 2D constructor)
    PART_COLORS = {
        'promoter':       '#0969da',
        'rbs':            '#bc4c00',
        'cds':            '#1a7f37',
        'terminator':     '#cf222e',
        'binding_site':   '#8250df',
        'tag':            '#0550ae',
        'protein_circle': '#1a7f37',
        'protein_square': '#9a6700',
        'mrna':           '#0550ae',
        'small_mol':      '#8250df',
        'enzyme_diamond': '#9a6700',
    }

    # DNA backbone color
    DNA_COLOR_A = '#3a4a6a'   # phosphate backbone strand 1
    DNA_COLOR_B = '#4a5a7a'   # phosphate backbone strand 2

    def __init__(self, canvas, lang='ru'):
        self.canvas = canvas
        self.lang = lang
        self.renderer = Render3D(canvas, bg_color='#f5f7fa')
        # Plasmid geometry
        self.major_radius = 4.0    # torus main radius
        self.minor_radius = 0.18   # tube thickness
        self.parts = []             # list of {pos: 0..1 fraction around circle, name, icon, color, size}
        self.show_helix = True      # show DNA double-helix on backbone
        self.show_labels = True     # show part name labels

    def set_parts_from_chain(self, chain_node_ids, all_nodes):
        """Build parts from a chain of node IDs (constructor chain)."""
        node_map = {n['id']: n for n in all_nodes}
        self.parts = []
        if not chain_node_ids:
            return
        n_total = len(chain_node_ids)
        for i, nid in enumerate(chain_node_ids):
            if nid not in node_map:
                continue
            node = node_map[nid]
            icon = node.get('icon', 'cds')
            color = self.PART_COLORS.get(icon, node.get('color', '#57606a'))
            self.parts.append({
                'pos': i / max(1, n_total),
                'name': nid,
                'icon': icon,
                'color': color,
                'size': node.get('size', 1.0),
            })

    def set_parts_from_state(self, state):
        """Pick first chain, or all parts placed in DNA chain order if no chain."""
        chains = state.get('chains', [])
        if chains:
            self.set_parts_from_chain(chains[0], state['nodes'])
        else:
            # Use all nodes that are DNA-like (promoter/rbs/cds/terminator/binding_site)
            dna_icons = {'promoter', 'rbs', 'cds', 'terminator', 'binding_site', 'tag'}
            dna_nodes = [n for n in state['nodes'] if n.get('icon') in dna_icons]
            # Sort by x position
            dna_nodes.sort(key=lambda n: n.get('x', 0))
            self.set_parts_from_chain([n['id'] for n in dna_nodes], state['nodes'])

    def render(self):
        """Build the entire scene."""
        self.renderer.clear()
        # 1) Draw plasmid backbone torus
        self.renderer.add_torus([0, 0, 0], self.major_radius, self.minor_radius,
                                   self.DNA_COLOR_A,
                                   segments_major=48, segments_minor=8)
        # 2) Draw double helix overlay (two intertwined strands)
        if self.show_helix:
            self._add_double_helix()
        # 3) Draw each part as a 3D shape positioned around the torus
        for part in self.parts:
            self._add_part_3d(part)
        # 4) Render
        self.renderer.render()

    def _add_double_helix(self):
        """Add visible double-helix pattern: two thin spirals along the torus."""
        n_turns = 32  # how many helix twists around the entire plasmid
        steps = 192   # how many segments to draw
        for strand in (0, 1):  # two strands
            color = self.DNA_COLOR_A if strand == 0 else self.DNA_COLOR_B
            phase = strand * math.pi  # opposite phase for strand 2
            prev_point = None
            for i in range(steps + 1):
                u = 2 * math.pi * i / steps  # around the main circle
                v = 2 * math.pi * (i / steps) * n_turns + phase  # twist phase
                # Point on torus surface, offset slightly outward to be visible
                r_outer = self.major_radius + self.minor_radius * 1.2 * math.cos(v)
                y = self.minor_radius * 1.2 * math.sin(v)
                x = r_outer * math.cos(u)
                z = r_outer * math.sin(u)
                point = [x, y, z]
                if prev_point is not None:
                    self.renderer.add_line(prev_point, point, color=color, width=2)
                prev_point = point

    def _add_part_3d(self, part):
        """Add 3D representation of one genetic part at its position around the torus."""
        # Compute position on the torus
        u = 2 * math.pi * part['pos']  # angle around major circle
        cx = self.major_radius * math.cos(u)
        cy = 0
        cz = self.major_radius * math.sin(u)
        # Outward direction (away from torus center)
        nx = math.cos(u); nz = math.sin(u)
        # Up direction is +Y
        outward = np.array([nx, 0, nz])
        # Position the part slightly above the torus tube
        offset_outer = self.minor_radius * 2 + 0.15
        base_pos = np.array([cx + nx * offset_outer, cy, cz + nz * offset_outer])

        icon = part['icon']
        color = part['color']
        size = 0.45 * part.get('size', 1.0)

        if icon == 'promoter':
            # Bent arrow — represented as a cylinder pointing in tangent direction
            tangent = np.array([-nz, 0, nx])
            tip = base_pos + tangent * size * 1.5
            self.renderer.add_cylinder(base_pos.tolist(), tip.tolist(),
                                          size * 0.3, color, segments=8)
            # Vertical part of bent arrow
            base_pos_low = base_pos.copy(); base_pos_low[1] -= size * 0.5
            self.renderer.add_cylinder(base_pos_low.tolist(), base_pos.tolist(),
                                          size * 0.25, color, segments=8)
        elif icon == 'rbs':
            # Half-sphere (semicircle in 3D)
            self.renderer.add_sphere(base_pos.tolist(), size * 0.6,
                                        color, segments=10, rings=6)
        elif icon == 'cds':
            # Box-shaped arrow (long gene body)
            tangent = np.array([-nz, 0, nx])
            # Box centered along tangent
            center = base_pos + tangent * size * 0.4
            # Use a stretched box: long in tangent direction
            self._add_oriented_box(center, tangent, outward, np.array([0, 1, 0]),
                                     length=size * 1.5, width=size * 0.5,
                                     height=size * 0.5, color=color)
            # Arrowhead at tip
            tip = base_pos + tangent * size * 1.5
            self.renderer.add_sphere(tip.tolist(), size * 0.4, color,
                                        segments=8, rings=5)
        elif icon == 'terminator':
            # T-bar shape
            top = base_pos.copy(); top[1] += size * 0.7
            self.renderer.add_cylinder(base_pos.tolist(), top.tolist(),
                                          size * 0.2, color, segments=8)
            # Horizontal bar
            tangent = np.array([-nz, 0, nx])
            bar_l = top - tangent * size * 0.5
            bar_r = top + tangent * size * 0.5
            self.renderer.add_cylinder(bar_l.tolist(), bar_r.tolist(),
                                          size * 0.2, color, segments=8)
        elif icon == 'binding_site':
            # Striped box (cube) — represents operator
            self.renderer.add_box(base_pos.tolist(),
                                     size * 0.6, size * 0.5, size * 0.6, color)
        elif icon == 'tag':
            # Small sphere with label
            self.renderer.add_sphere(base_pos.tolist(), size * 0.4,
                                        color, segments=8, rings=5)
        else:
            # Default — sphere
            self.renderer.add_sphere(base_pos.tolist(), size * 0.5,
                                        color, segments=10, rings=6)

        # Add label above the part
        if self.show_labels:
            label_pos = base_pos + outward * 0.6 + np.array([0, size * 1.2, 0])
            self.renderer.add_label(label_pos.tolist(), part['name'][:10],
                                       color='#1c2128', font_size=9)

    def _add_oriented_box(self, center, dir_long, dir_width, dir_height,
                            length, width, height, color):
        """Add a box oriented along given direction vectors (length, width, height)."""
        cx, cy, cz = center
        # Normalize directions
        dl = dir_long / (np.linalg.norm(dir_long) + 1e-9)
        dw = dir_width / (np.linalg.norm(dir_width) + 1e-9)
        dh = dir_height / (np.linalg.norm(dir_height) + 1e-9)
        # 8 corners of box
        corners = []
        for sl in (-1, 1):
            for sw in (-1, 1):
                for sh in (-1, 1):
                    p = center + dl * (sl * length / 2) + dw * (sw * width / 2) + dh * (sh * height / 2)
                    corners.append(p.tolist())
        # Faces — same as add_box
        faces = [
            (0, 1, 3, 2),  # bottom
            (4, 6, 7, 5),  # top
            (0, 4, 5, 1),  # one side
            (2, 3, 7, 6),  # opposite side
            (0, 2, 6, 4),  # front
            (1, 5, 7, 3),  # back
        ]
        for f in faces:
            self.renderer.add_quad(corners[f[0]], corners[f[1]],
                                      corners[f[2]], corners[f[3]], color)

    def attach_mouse(self):
        self.renderer.attach_mouse()


class Open3DPlasmidWindow(tk.Toplevel):
    """Stand-alone 3D plasmid viewer window."""

    def __init__(self, parent, state, lang='ru'):
        super().__init__(parent)
        self.lang = lang
        self.title('3D Plasmid Viewer — VIREON')
        self.geometry('840x740')
        self.configure(bg=biosim_theme('bg'))
        self.transient(parent)

        # Header
        header = tk.Frame(self, bg=biosim_theme('bg')); header.pack(fill='x', pady=8)
        tk.Label(header, text='3D Plasmid Viewer',
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 16, 'bold')).pack()
        tk.Label(header,
                  text=('Перетаскивай мышью · колёсико для зума · круглая ДНК-плазмида с частями'
                        if lang == 'ru' else
                        'Drag to rotate · wheel to zoom · circular plasmid with parts'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()

        # Canvas
        self.canvas = tk.Canvas(self, bg=biosim_theme('bg'), highlightthickness=0,
                                  cursor='fleur')
        self.canvas.pack(fill='both', expand=True, padx=14, pady=4)

        # Viewer
        self.viewer = Plasmid3DViewer(self.canvas, lang=lang)
        self.viewer.set_parts_from_state(state)
        self.viewer.attach_mouse()

        # Info label
        n_parts = len(self.viewer.parts)
        self.info_lbl = tk.Label(self,
                                    text=('Частей в плазмиде: {}' if lang == 'ru'
                                          else 'Parts in plasmid: {}').format(n_parts),
                                    bg=biosim_theme('bg'), fg='#0550ae',
                                    font=('Arial', 10, 'italic'))
        self.info_lbl.pack(pady=4)

        # Control buttons
        ctrl = tk.Frame(self, bg=biosim_theme('bg')); ctrl.pack(fill='x', padx=14, pady=8)

        self.helix_var = tk.BooleanVar(value=True)
        tk.Checkbutton(ctrl,
                        text='Двойная спираль' if lang == 'ru' else 'Double helix',
                        variable=self.helix_var, command=self._toggle_helix,
                        bg=biosim_theme('bg'), fg=biosim_theme('text'), selectcolor='#eef1f5',
                        activebackground='#f5f7fa', font=('Arial', 9)
                        ).pack(side='left', padx=4)

        self.labels_var = tk.BooleanVar(value=True)
        tk.Checkbutton(ctrl,
                        text='Метки' if lang == 'ru' else 'Labels',
                        variable=self.labels_var, command=self._toggle_labels,
                        bg=biosim_theme('bg'), fg=biosim_theme('text'), selectcolor='#eef1f5',
                        activebackground='#f5f7fa', font=('Arial', 9)
                        ).pack(side='left', padx=4)

        self._rotating = False
        self._rotate_btn = tk.Button(ctrl, text='▶ Авто-вращение' if lang == 'ru' else '▶ Auto-rotate',
                                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                                       font=('Arial', 9, 'bold'), cursor='hand2', pady=4,
                                       command=self._toggle_rotate)
        self._rotate_btn.pack(side='left', padx=4)

        tk.Button(ctrl, text='⟲ ' + ('Сброс' if lang == 'ru' else 'Reset'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 9, 'bold'), cursor='hand2', pady=4,
                   command=self._reset_view).pack(side='left', padx=4)

        tk.Button(ctrl, text='Закрыть' if lang == 'ru' else 'Close',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=self._on_close).pack(side='right', padx=4)

        self._after_id = None
        # Initial render after canvas is shown
        self.after(150, self._initial_render)
        self.protocol('WM_DELETE_WINDOW', self._on_close)

    def _initial_render(self):
        self.viewer.renderer.cam_distance = 14.0
        self.viewer.renderer.rot_x = 0.6
        self.viewer.renderer.rot_y = 0.0
        self.viewer.render()

    def _toggle_helix(self):
        self.viewer.show_helix = self.helix_var.get()
        self.viewer.render()

    def _toggle_labels(self):
        self.viewer.show_labels = self.labels_var.get()
        self.viewer.render()

    def _toggle_rotate(self):
        self._rotating = not self._rotating
        if self._rotating:
            self._rotate_btn.config(text='■ Стоп' if self.lang == 'ru' else '■ Stop')
            self._rotate_step()
        else:
            self._rotate_btn.config(text='▶ Авто-вращение' if self.lang == 'ru' else '▶ Auto-rotate')

    def _rotate_step(self):
        if not self._rotating:
            return
        self.viewer.renderer.rot_y += 0.015
        self.viewer.render()
        self._after_id = self.after(60, self._rotate_step)

    def _reset_view(self):
        self.viewer.renderer.rot_x = 0.6
        self.viewer.renderer.rot_y = 0.0
        self.viewer.renderer.cam_distance = 14.0
        self.viewer.render()

    def _on_close(self):
        self._rotating = False
        if self._after_id is not None:
            try: self.after_cancel(self._after_id)
            except Exception as _exc:
                biosim_log('warn', '_on_close: {}'.format(_exc))
                pass
        self.destroy()


class AnatomyImageBody:
    """Human body shown as a real anatomical image with organ highlights.

    Drop-in replacement for Iso3DHuman / DaVinciBody. Loads 'body_organs.png'
    placed next to the program, displays it, and overlays glowing highlights
    on affected organs when a disease is selected.
    """

    # Organ highlight zones as fractions of the image (cx, cy, rx, ry)
    # Tuned for the 330x720 anatomical organ figure.
    ORGANS = {
        'Brain':    {'cx': 0.50, 'cy': 0.10, 'rx': 0.16, 'ry': 0.09, 'ru': 'Мозг'},
        'Lungs':    {'cx': 0.50, 'cy': 0.40, 'rx': 0.30, 'ry': 0.10, 'ru': 'Лёгкие'},
        'Heart':    {'cx': 0.50, 'cy': 0.43, 'rx': 0.13, 'ry': 0.07, 'ru': 'Сердце'},
        'Liver':    {'cx': 0.40, 'cy': 0.57, 'rx': 0.20, 'ry': 0.06, 'ru': 'Печень'},
        'Stomach':  {'cx': 0.60, 'cy': 0.58, 'rx': 0.14, 'ry': 0.06, 'ru': 'Желудок'},
        'Pancreas': {'cx': 0.52, 'cy': 0.62, 'rx': 0.16, 'ry': 0.03, 'ru': 'Поджелудочная'},
        'Kidneys':  {'cx': 0.50, 'cy': 0.63, 'rx': 0.32, 'ry': 0.04, 'ru': 'Почки'},
        'Intestine':{'cx': 0.50, 'cy': 0.78, 'rx': 0.28, 'ry': 0.12, 'ru': 'Кишечник'},
        'Spleen':   {'cx': 0.64, 'cy': 0.57, 'rx': 0.07, 'ry': 0.04, 'ru': 'Селезёнка'},
        'Bladder':  {'cx': 0.50, 'cy': 0.90, 'rx': 0.08, 'ry': 0.04, 'ru': 'Мочевой пузырь'},
    }

    ORGAN_ALIASES = {
        'мозг': 'Brain', 'brain': 'Brain', 'головной мозг': 'Brain',
        'лёгкие': 'Lungs', 'легкие': 'Lungs', 'lungs': 'Lungs', 'lung': 'Lungs',
        'сердце': 'Heart', 'heart': 'Heart',
        'печень': 'Liver', 'liver': 'Liver',
        'желудок': 'Stomach', 'stomach': 'Stomach',
        'поджелудочная': 'Pancreas', 'поджелудочная железа': 'Pancreas', 'pancreas': 'Pancreas',
        'почки': 'Kidneys', 'почка': 'Kidneys', 'kidneys': 'Kidneys', 'kidney': 'Kidneys',
        'кишечник': 'Intestine', 'intestine': 'Intestine', 'кишка': 'Intestine',
        'селезёнка': 'Spleen', 'селезенка': 'Spleen', 'spleen': 'Spleen',
        'мочевой пузырь': 'Bladder', 'bladder': 'Bladder',
        'кровь': 'Heart', 'blood': 'Heart',
        'мышцы': 'Muscle', 'muscle': 'Muscle',
    }

    _img_cache = None  # shared PIL image (loaded once)

    def __init__(self, canvas):
        self.c = canvas
        self.lang = 'ru'
        self._photo = None  # keep reference so Tk doesn't garbage-collect
        self._load_image()

    def _load_image(self):
        """Load the anatomy PNG once. Looks next to the program file."""
        if AnatomyImageBody._img_cache is not None:
            return
        try:
            from PIL import Image as _PILImage
            import os
            # Look for body_organs.png next to this module / the main script
            candidates = []
            try:
                here = os.path.dirname(os.path.abspath(__file__))
                candidates.append(os.path.join(here, 'body_organs.png'))
            except Exception as _exc:
                biosim_log('warn', '_load_image: {}'.format(_exc))
            # PyInstaller: распакованные данные лежат в sys._MEIPASS
            try:
                import sys as _sys
                _meipass = getattr(_sys, '_MEIPASS', None)
                if _meipass:
                    candidates.append(os.path.join(_meipass, 'body_organs.png'))
            except Exception as _exc:
                biosim_log('warn', '_load_image: {}'.format(_exc))
            candidates.append('body_organs.png')
            candidates.append(os.path.join(os.getcwd(), 'body_organs.png'))
            for path in candidates:
                if os.path.exists(path):
                    AnatomyImageBody._img_cache = _PILImage.open(path).convert('RGBA')
                    break
        except Exception as _exc:
            biosim_log('warn', '_load_image: {}'.format(_exc))
            AnatomyImageBody._img_cache = None

    def _box(self):
        w = self.c.winfo_width() or 700
        h = self.c.winfo_height() or 380
        return w, h

    def _resolve_organs(self, organ_list):
        out = set()
        for o in (organ_list or []):
            key = self.ORGAN_ALIASES.get(str(o).strip().lower())
            if key and key in self.ORGANS:
                out.add(key)
        return out

    # ── public API (compatible) ──
    def draw(self, highlight_organs=None, severity=0.0, severity_color=None):
        self._render(self._resolve_organs(highlight_organs), severity, severity_color)

    def draw_default(self, hint_text='Select a disease'):
        self._render(set(), 0.0, None, hint_text=hint_text)

    def draw_disease(self, dis_data, severity, lang='ru'):
        self.lang = lang
        organ_map = dis_data.get('organ_map') or dis_data.get('organs_ru') \
            or dis_data.get('organs_en') or []
        name = dis_data.get('ru', '') if lang == 'ru' else dis_data.get('en', '')
        self._render(self._resolve_organs(organ_map), severity, None,
                     title=name, show_severity=severity)

    def draw_mutation(self, gene, severity):
        self._render(set(), severity, None,
                     title=('Мутация: ' if self.lang == 'ru' else 'Mutation: ') + str(gene),
                     show_severity=severity)

    def draw_alphafold(self, af_list):
        pass

    def _sev_color(self, s):
        if s > 0.66:
            return '#ff3030'
        if s > 0.33:
            return '#bc4c00'
        return '#ffd700'

    # ── renderer ──
    def _render(self, highlight, severity, sev_color, hint_text=None,
                title=None, show_severity=None):
        c = self.c
        c.delete('all')
        w, h = self._box()
        if w < 50 or h < 50:
            self.c.after(120, lambda: self._render(highlight, severity, sev_color,
                                                   hint_text, title, show_severity))
            return

        img = AnatomyImageBody._img_cache
        if img is None:
            # Fallback: no image found — show a clear message on white
            c.create_rectangle(0, 0, w, h, fill='#ffffff', outline='')
            c.create_text(w // 2, h // 2 - 20,
                          text=('Картинка body_organs.png не найдена' if self.lang == 'ru'
                                else 'body_organs.png not found'),
                          fill='#cf222e', font=('Helvetica', 12, 'bold'))
            c.create_text(w // 2, h // 2 + 10,
                          text=('Положите body_organs.png рядом с программой'
                                if self.lang == 'ru' else
                                'Place body_organs.png next to the program'),
                          fill='#57606a', font=('Helvetica', 10))
            return

        # Fit image into canvas preserving aspect ratio
        from PIL import Image as _PILImage, ImageTk as _ImageTk, ImageDraw as _ImageDraw
        iw, ih = img.size
        scale = min(w / iw, h / ih) * 0.95
        new_w, new_h = max(1, int(iw * scale)), max(1, int(ih * scale))
        ox = (w - new_w) // 2  # offset to center
        oy = (h - new_h) // 2

        # Work on a copy so we can paint highlights onto the image
        composed = img.resize((new_w, new_h), _PILImage.LANCZOS).convert('RGBA')

        if highlight:
            overlay = _PILImage.new('RGBA', (new_w, new_h), (0, 0, 0, 0))
            draw = _ImageDraw.Draw(overlay)
            # Highlight color from severity
            hex_color = (sev_color or self._sev_color(severity)).lstrip('#')
            try:
                rgb = tuple(int(hex_color[i:i+2], 16) for i in (0, 2, 4))
            except Exception as _exc:
                biosim_log('warn', '_render: {}'.format(_exc))
                rgb = (255, 60, 60)
            for key in highlight:
                o = self.ORGANS[key]
                cx, cy = o['cx'] * new_w, o['cy'] * new_h
                rx, ry = o['rx'] * new_w, o['ry'] * new_h
                # Layered glow (outer faint inner strong)
                for ring, alpha in [(1.6, 50), (1.3, 80), (1.0, 120)]:
                    draw.ellipse([cx - rx * ring, cy - ry * ring,
                                  cx + rx * ring, cy + ry * ring],
                                 fill=rgb + (alpha,))
            composed = _PILImage.alpha_composite(composed, overlay)

        self._photo = _ImageTk.PhotoImage(composed)
        c.create_image(ox, oy, anchor='nw', image=self._photo)

        # Organ labels (drawn on canvas, on top)
        if highlight:
            glow = sev_color or self._sev_color(severity)
            for key in highlight:
                o = self.ORGANS[key]
                lx = ox + o['cx'] * new_w
                ly = oy + (o['cy'] - o['ry'] - 0.02) * new_h
                label = o['ru'] if self.lang == 'ru' else key
                # Shadow for readability
                c.create_text(lx + 1, ly + 1, text=label, fill='#000000',
                              font=('Arial', 10, 'bold'))
                c.create_text(lx, ly, text=label, fill=glow,
                              font=('Arial', 10, 'bold'))

        # Title
        if title:
            glow = sev_color or self._sev_color(severity or 0)
            c.create_text(w // 2, 14, text=title, fill=glow,
                          font=('Arial', 13, 'bold'))

        # Hint
        if hint_text:
            c.create_text(w // 2, h - 12, text=hint_text, fill='#57606a',
                          font=('Helvetica', 10, 'italic'))

        # Severity bar
        if show_severity is not None and show_severity > 0:
            glow = sev_color or self._sev_color(show_severity)
            bar_w = int(w * 0.25)
            bx = w // 2 - bar_w // 2
            by = h - 28
            c.create_rectangle(bx, by, bx + bar_w, by + 6,
                               outline='#57606a', width=1)
            c.create_rectangle(bx, by, bx + int(bar_w * min(1.0, show_severity)), by + 6,
                               fill=glow, outline='')
            c.create_text(w // 2, by - 9, text='{:.0f}%'.format(show_severity * 100),
                          fill=glow, font=('Arial', 10, 'bold'))



class DaVinciBody:
    """Anatomical 2D human body in the style of Leonardo da Vinci.

    Drop-in replacement for Iso3DHuman: same public methods
    (draw, draw_default, draw_disease, draw_mutation, draw_alphafold).
    Renders a sepia-toned anatomical figure with fine ink lines,
    Vitruvian circle, hatching, and glowing organ highlights.
    """

    # Da Vinci palette — aged parchment & sepia ink
    PARCHMENT = '#e8dcc0'
    PARCHMENT_DARK = '#d4c4a0'
    INK = '#3a2c1a'
    INK_LIGHT = '#6b5638'
    INK_FAINT = '#9b8763'
    SANGUINE = '#8b4a2f'      # red chalk Leonardo loved
    HIGHLIGHT = '#b5472f'

    # Organ anatomical positions (fractions of body box) + ink color
    ORGANS = {
        'Brain':    {'cx': 0.50, 'cy': 0.085, 'rx': 0.055, 'ry': 0.05,  'ru': 'Мозг'},
        'Lungs':    {'cx': 0.50, 'cy': 0.34,  'rx': 0.12,  'ry': 0.09,  'ru': 'Лёгкие'},
        'Heart':    {'cx': 0.535,'cy': 0.345, 'rx': 0.045, 'ry': 0.05,  'ru': 'Сердце'},
        'Liver':    {'cx': 0.45, 'cy': 0.45,  'rx': 0.10,  'ry': 0.055, 'ru': 'Печень'},
        'Stomach':  {'cx': 0.56, 'cy': 0.46,  'rx': 0.06,  'ry': 0.05,  'ru': 'Желудок'},
        'Pancreas': {'cx': 0.52, 'cy': 0.49,  'rx': 0.07,  'ry': 0.022, 'ru': 'Поджелудочная'},
        'Kidneys':  {'cx': 0.50, 'cy': 0.52,  'rx': 0.13,  'ry': 0.035, 'ru': 'Почки'},
        'Intestine':{'cx': 0.50, 'cy': 0.59,  'rx': 0.10,  'ry': 0.07,  'ru': 'Кишечник'},
        'Spleen':   {'cx': 0.605,'cy': 0.455, 'rx': 0.03,  'ry': 0.035, 'ru': 'Селезёнка'},
        'Bladder':  {'cx': 0.50, 'cy': 0.66,  'rx': 0.04,  'ry': 0.035, 'ru': 'Мочевой пузырь'},
    }

    # Synonyms canonical organ key (RU + EN)
    ORGAN_ALIASES = {
        'мозг': 'Brain', 'brain': 'Brain', 'головной мозг': 'Brain',
        'лёгкие': 'Lungs', 'легкие': 'Lungs', 'lungs': 'Lungs', 'lung': 'Lungs',
        'сердце': 'Heart', 'heart': 'Heart',
        'печень': 'Liver', 'liver': 'Liver',
        'желудок': 'Stomach', 'stomach': 'Stomach',
        'поджелудочная': 'Pancreas', 'поджелудочная железа': 'Pancreas',
        'pancreas': 'Pancreas',
        'почки': 'Kidneys', 'почка': 'Kidneys', 'kidneys': 'Kidneys', 'kidney': 'Kidneys',
        'кишечник': 'Intestine', 'intestine': 'Intestine', 'кишка': 'Intestine',
        'селезёнка': 'Spleen', 'селезенка': 'Spleen', 'spleen': 'Spleen',
        'мочевой пузырь': 'Bladder', 'bladder': 'Bladder',
        'кровь': 'Heart', 'blood': 'Heart',  # blood highlight heart/circulation
        'мышцы': 'Muscle', 'muscle': 'Muscle', 'muscles': 'Muscle',
    }

    def __init__(self, canvas):
        self.c = canvas
        self.lang = 'ru'
        self._t = 0.0  # animation phase for glow

    # ── geometry helpers ──
    def _box(self):
        w = self.c.winfo_width() or 700
        h = self.c.winfo_height() or 380
        return w, h

    def _resolve_organs(self, organ_list):
        """Map arbitrary organ names to canonical keys."""
        out = set()
        for o in (organ_list or []):
            key = self.ORGAN_ALIASES.get(str(o).strip().lower())
            if key and key in self.ORGANS:
                out.add(key)
        return out

    # ── public API (compatible with Iso3DHuman) ──
    def draw(self, highlight_organs=None, severity=0.0, severity_color=None):
        self._render(self._resolve_organs(highlight_organs), severity, severity_color)

    def draw_default(self, hint_text='Select a disease'):
        self._render(set(), 0.0, None, hint_text=hint_text)

    def draw_disease(self, dis_data, severity, lang='ru'):
        self.lang = lang
        organ_map = dis_data.get('organ_map') or dis_data.get('organs_ru') \
            or dis_data.get('organs_en') or []
        name = dis_data.get('ru', '') if lang == 'ru' else dis_data.get('en', '')
        self._render(self._resolve_organs(organ_map), severity, None,
                     title=name, show_severity=severity)

    def draw_mutation(self, gene, severity):
        self._render(set(), severity, None,
                     title=('Мутация: ' if self.lang == 'ru' else 'Mutation: ') + str(gene),
                     show_severity=severity)

    def draw_alphafold(self, af_list):
        # Keep the current figure; just note structures available
        w, h = self._box()
        self.c.create_text(w // 2, h - 8,
                            text='AlphaFold: ' + ', '.join(str(a) for a in (af_list or [])[:4]),
                            fill=self.INK_LIGHT, font=('Georgia', 9, 'italic'))

    # ── the masterpiece renderer ──
    def _render(self, highlight, severity, sev_color, hint_text=None,
                title=None, show_severity=None):
        c = self.c
        c.delete('all')
        w, h = self._box()
        if w < 50 or h < 50:
            self.c.after(100, lambda: self._render(highlight, severity, sev_color,
                                                    hint_text, title, show_severity))
            return

        # 1. Parchment background with subtle aged vignette
        c.create_rectangle(0, 0, w, h, fill=self.PARCHMENT, outline='')
        self._draw_parchment_texture(w, h)

        # 2. Vitruvian circle + square framing the figure
        cx, cy = w * 0.5, h * 0.5
        R = min(w, h) * 0.46
        c.create_oval(cx - R, cy - R, cx + R, cy + R,
                      outline=self.INK_FAINT, width=1)
        sq = R * 0.92
        c.create_rectangle(cx - sq, cy - sq, cx + sq, cy + sq,
                           outline=self.INK_FAINT, width=1)

        # 3. The anatomical figure (fine ink)
        self._draw_figure(w, h)

        # 4. Organs (faint anatomical sketch) + highlights
        self._draw_organs(w, h, highlight, severity, sev_color)

        # 5. Da Vinci touches: mirror-script notes, hatching, golden ratio marks
        self._draw_annotations(w, h, title, hint_text, highlight)

        # 6. Severity bar (if disease)
        if show_severity is not None and show_severity > 0:
            self._draw_severity(w, h, show_severity, sev_color)

    def _draw_parchment_texture(self, w, h):
        c = self.c
        # Aged corners (darker vignette) via faint diagonal strokes
        import random
        rnd = random.Random(42)  # deterministic texture
        for _ in range(60):
            x = rnd.uniform(0, w); y = rnd.uniform(0, h)
            ln = rnd.uniform(3, 9)
            c.create_line(x, y, x + ln, y + ln * 0.3,
                          fill=self.PARCHMENT_DARK, width=1)
        # Border frame
        c.create_rectangle(3, 3, w - 3, h - 3, outline=self.INK_FAINT, width=2)
        c.create_rectangle(7, 7, w - 7, h - 7, outline=self.INK_FAINT, width=1)

    def _draw_figure(self, w, h):
        """Draw the human figure with Leonardo's flowing ink line."""
        c = self.c
        ink = self.INK
        # Reference frame: head at top, feet near bottom
        cx = w * 0.5
        top = h * 0.04
        # Proportions (Vitruvian: 8 heads tall)
        head_r = h * 0.055

        def P(fx, fy):
            return (w * fx, h * fy)

        # ── Head (oval, slight 3/4 turn) ──
        hx, hy = cx, top + head_r
        c.create_oval(hx - head_r * 0.78, hy - head_r,
                      hx + head_r * 0.78, hy + head_r * 1.05,
                      outline=ink, width=2)
        # Facial guide lines (Leonardo's proportion studies)
        c.create_line(hx, hy - head_r, hx, hy + head_r,
                      fill=self.INK_FAINT, width=1)
        c.create_line(hx - head_r * 0.7, hy, hx + head_r * 0.7, hy,
                      fill=self.INK_FAINT, width=1)
        # Hair suggestion (flowing curls — Leonardo signature)
        for i in range(-3, 4):
            ox = i * head_r * 0.22
            c.create_arc(hx - head_r * 0.8 + ox, hy - head_r * 1.15,
                         hx - head_r * 0.3 + ox, hy - head_r * 0.5,
                         start=0, extent=180, style='arc',
                         outline=self.INK_LIGHT, width=1)

        # ── Neck ──
        neck_top = hy + head_r * 1.0
        neck_w = head_r * 0.45
        sh_y = neck_top + h * 0.04
        c.create_line(hx - neck_w, neck_top, hx - neck_w * 0.9, sh_y, fill=ink, width=2)
        c.create_line(hx + neck_w, neck_top, hx + neck_w * 0.9, sh_y, fill=ink, width=2)

        # ── Torso (shoulders waist hips) with flowing contour ──
        sh_w = w * 0.13
        waist_y = h * 0.52
        waist_w = w * 0.085
        hip_y = h * 0.60
        hip_w = w * 0.11
        # Left contour
        c.create_line(
            hx - neck_w * 0.9, sh_y,
            hx - sh_w, sh_y + h * 0.02,
            hx - sh_w * 0.95, h * 0.40,
            hx - waist_w, waist_y,
            hx - hip_w, hip_y,
            fill=ink, width=2, smooth=True)
        # Right contour
        c.create_line(
            hx + neck_w * 0.9, sh_y,
            hx + sh_w, sh_y + h * 0.02,
            hx + sh_w * 0.95, h * 0.40,
            hx + waist_w, waist_y,
            hx + hip_w, hip_y,
            fill=ink, width=2, smooth=True)
        # Collarbone + sternum hint
        c.create_line(hx - sh_w * 0.7, sh_y + h * 0.01, hx + sh_w * 0.7, sh_y + h * 0.01,
                      fill=self.INK_LIGHT, width=1, smooth=True)
        c.create_line(hx, sh_y + h * 0.02, hx, waist_y, fill=self.INK_FAINT, width=1)
        # Rib cage hatching (anatomical study feel)
        for i in range(4):
            ry = sh_y + h * 0.04 + i * h * 0.028
            rw = sh_w * (0.85 - i * 0.05)
            c.create_arc(hx - rw, ry - h * 0.03, hx + rw, ry + h * 0.03,
                         start=200, extent=140, style='arc',
                         outline=self.INK_FAINT, width=1)

        # ── Arms (Vitruvian: outstretched slightly) ──
        # Left arm
        c.create_line(
            hx - sh_w, sh_y + h * 0.02,
            hx - sh_w * 1.35, h * 0.42,
            hx - sh_w * 1.5, h * 0.56,
            fill=ink, width=2, smooth=True)
        # Right arm
        c.create_line(
            hx + sh_w, sh_y + h * 0.02,
            hx + sh_w * 1.35, h * 0.42,
            hx + sh_w * 1.5, h * 0.56,
            fill=ink, width=2, smooth=True)
        # Hands (suggested)
        for sx in (-1, 1):
            hxp = hx + sx * sh_w * 1.5
            hyp = h * 0.56
            c.create_oval(hxp - w * 0.012, hyp, hxp + w * 0.012, hyp + h * 0.035,
                          outline=ink, width=1)
            # Fingers
            for fi in range(4):
                fx = hxp - w * 0.01 + fi * w * 0.007
                c.create_line(fx, hyp + h * 0.03, fx, hyp + h * 0.05,
                              fill=self.INK_LIGHT, width=1)

        # ── Legs ──
        # Left leg
        c.create_line(
            hx - hip_w, hip_y,
            hx - w * 0.06, h * 0.74,
            hx - w * 0.05, h * 0.93,
            fill=ink, width=2, smooth=True)
        # Right leg
        c.create_line(
            hx + hip_w, hip_y,
            hx + w * 0.06, h * 0.74,
            hx + w * 0.05, h * 0.93,
            fill=ink, width=2, smooth=True)
        # Inner leg line
        c.create_line(hx, hip_y + h * 0.01, hx - w * 0.02, h * 0.92,
                      fill=self.INK_FAINT, width=1, smooth=True)
        c.create_line(hx, hip_y + h * 0.01, hx + w * 0.02, h * 0.92,
                      fill=self.INK_FAINT, width=1, smooth=True)
        # Feet
        for sx in (-1, 1):
            fxp = hx + sx * w * 0.05
            c.create_line(fxp, h * 0.93, fxp + sx * w * 0.04, h * 0.945,
                          fill=ink, width=2)

        # Muscle definition hatching (subtle, Leonardo's cross-hatch)
        self._hatch(hx - w * 0.04, h * 0.44, hx - w * 0.01, h * 0.50, 4)
        self._hatch(hx + w * 0.01, h * 0.44, hx + w * 0.04, h * 0.50, 4)

    def _hatch(self, x1, y1, x2, y2, n):
        """Fine parallel hatching lines (Leonardo's shading)."""
        c = self.c
        for i in range(n):
            f = i / max(1, n - 1)
            c.create_line(x1 + (x2 - x1) * f, y1,
                          x1 + (x2 - x1) * f - 4, y2,
                          fill=self.INK_FAINT, width=1)

    def _draw_organs(self, w, h, highlight, severity, sev_color):
        c = self.c
        glow = sev_color or self.HIGHLIGHT
        for key, o in self.ORGANS.items():
            ox, oy = w * o['cx'], h * o['cy']
            rx, ry = w * o['rx'], h * o['ry']
            is_hot = key in highlight
            if is_hot:
                # Glowing highlight — sanguine red chalk, layered halo
                for ring, alpha_w in [(2.2, 1), (1.7, 1), (1.3, 2), (1.0, 2)]:
                    c.create_oval(ox - rx * ring, oy - ry * ring,
                                  ox + rx * ring, oy + ry * ring,
                                  outline=glow, width=alpha_w)
                c.create_oval(ox - rx, oy - ry, ox + rx, oy + ry,
                              fill=glow, outline=self.SANGUINE, width=2,
                              stipple='gray50')
                # Organ name in sanguine
                label = o['ru'] if self.lang == 'ru' else key
                c.create_text(ox, oy - ry - 8, text=label,
                              fill=self.SANGUINE, font=('Georgia', 9, 'bold'))
            else:
                # Faint anatomical sketch (barely visible, like underdrawing)
                c.create_oval(ox - rx, oy - ry, ox + rx, oy + ry,
                              outline=self.INK_FAINT, width=1, dash=(2, 3))

    def _draw_annotations(self, w, h, title, hint_text, highlight):
        c = self.c
        # Title (top, elegant serif)
        if title:
            c.create_text(w * 0.5, h * 0.025, text=title,
                          fill=self.SANGUINE, font=('Georgia', 13, 'bold'))
        # Da Vinci "mirror writing" decorative notes (right margin)
        notes = ['HOMO', 'VITRVVIVS', 'ANATOMIA'] if not title else []
        for i, note in enumerate(notes):
            c.create_text(w * 0.93, h * 0.2 + i * h * 0.04, text=note,
                          fill=self.INK_FAINT, font=('Georgia', 8, 'italic'),
                          angle=180)
        # Hint
        if hint_text:
            c.create_text(w * 0.5, h * 0.97, text=hint_text,
                          fill=self.INK_LIGHT, font=('Georgia', 10, 'italic'))
        # Golden ratio marks (Leonardo's proportion obsession)
        phi = 0.618
        for fy in (phi * 0.5, phi):
            c.create_line(w * 0.04, h * fy, w * 0.065, h * fy,
                          fill=self.INK_FAINT, width=1)

    def _draw_severity(self, w, h, severity, sev_color):
        c = self.c
        glow = sev_color or self.HIGHLIGHT
        bar_w = w * 0.25
        bx = w * 0.5 - bar_w / 2
        by = h * 0.93
        c.create_rectangle(bx, by, bx + bar_w, by + 6,
                           outline=self.INK_LIGHT, width=1)
        c.create_rectangle(bx, by, bx + bar_w * min(1.0, severity), by + 6,
                           fill=glow, outline='')
        c.create_text(w * 0.5, by - 8,
                      text='{:.0f}%'.format(severity * 100),
                      fill=glow, font=('Georgia', 10, 'bold'))

    # Compatibility no-ops
    def _sev_color(self, s):
        if s > 0.66:
            return '#8b2f1f'
        if s > 0.33:
            return '#a85a2f'
        return '#8b6f2f'



class Iso3DHuman:
    # Freepik-style colors: warm pink skin, visible organs
    SKIN_BASE = '#ffb8a0'
    SKIN_DARK = '#e89880'
    SKIN_LIGHT = '#ffd0bc'
    ORGAN_HEART = '#e84855'
    ORGAN_LUNG = '#f4a8b8'
    ORGAN_LIVER = '#a05050'
    ORGAN_KIDNEY = '#c46868'
    ORGAN_PANCREAS = '#d49060'
    ORGAN_BRAIN = '#f0a0a8'
    HAIR = '#3a2a20'
    OUTLINE = '#5a3a30'

    def __init__(self, canvas):
        self.c = canvas
        self.cx = 0; self.cy = 0; self.scale = 1.0
        # Try to load human.png if it exists next to this script
        self.bg_image = None
        self.bg_photo = None
        if HAS_PIL:
            try:
                script_dir = os.path.dirname(os.path.abspath(__file__))
                png_path = os.path.join(script_dir, 'human.png')
                if os.path.exists(png_path):
                    self.bg_image = Image.open(png_path)
                    print('Loaded human.png as 3D background')
            except Exception as e:
                print('Could not load human.png:', e)

    def draw(self, highlight_organs=None, severity=0.0, severity_color='#1a7f37'):
        if highlight_organs is None:
            highlight_organs = []
        self.c.delete('all')
        w = self.c.winfo_width() or 700
        h = self.c.winfo_height() or 260
        self.cx = w // 2
        self.cy = h // 2 + 30
        self.scale = min(w / 12, h / 12) * 0.9

        # If we have a background image, use it instead of drawing the human
        if self.bg_image is not None and HAS_PIL:
            try:
                img = self.bg_image.copy()
                img.thumbnail((w - 20, h - 20), Image.LANCZOS)
                self.bg_photo = ImageTk.PhotoImage(img)
                self.c.create_image(w // 2, h // 2, image=self.bg_photo)
                # Overlay organ highlights on top
                self._overlay_organs(highlight_organs, severity_color, w, h)
                return
            except Exception as _exc:
                biosim_log('warn', 'draw: {}'.format(_exc))

        # Shadow at feet
        sh_x, sh_y = iso_project(0, 0, 0, self.cx, self.cy + 5 * self.scale, self.scale)
        self.c.create_oval(sh_x - 4*self.scale, sh_y - 1*self.scale,
                            sh_x + 4*self.scale, sh_y + 1*self.scale,
                            fill='#ffffff', outline='')

        # Draw from back to front
        self._draw_legs()
        self._draw_torso(highlight_organs, severity_color)
        self._draw_organs(highlight_organs, severity_color)
        self._draw_arms()
        self._draw_head(highlight_organs, severity_color)

    def _draw_legs(self):
        for lx in [-0.55, 0.55]:
            # Thigh
            x1, y1 = iso_project(lx, 0, 0.3, self.cx, self.cy, self.scale)
            x2, y2 = iso_project(lx, 0, 2.4, self.cx, self.cy, self.scale)
            self.c.create_line(x1, y1, x2, y2, fill=self.SKIN_BASE,
                                width=int(self.scale * 0.75), capstyle='round')
            # Calf shadow on right side
            self.c.create_line(x1+1, y1, x2+1, y2, fill=self.SKIN_DARK,
                                width=int(self.scale * 0.25), capstyle='round')
            # Foot
            fx, fy = iso_project(lx, 0.3, 0, self.cx, self.cy, self.scale)
            self.c.create_oval(fx-0.45*self.scale, fy-0.18*self.scale,
                                fx+0.45*self.scale, fy+0.18*self.scale,
                                fill=self.OUTLINE, outline='')

    def _draw_torso(self, highlight, sev_color):
        # Trapezoid torso shape
        pts = [
            iso_project(-1.2, 0, 2.4, self.cx, self.cy, self.scale),
            iso_project( 1.2, 0, 2.4, self.cx, self.cy, self.scale),
            iso_project( 1.4, 0, 4.0, self.cx, self.cy, self.scale),
            iso_project( 1.3, 0, 5.2, self.cx, self.cy, self.scale),
            iso_project(-1.3, 0, 5.2, self.cx, self.cy, self.scale),
            iso_project(-1.4, 0, 4.0, self.cx, self.cy, self.scale),
        ]
        # Main fill
        flat = []
        for p in pts:
            flat.append(p[0]); flat.append(p[1])
        self.c.create_polygon(flat, fill=self.SKIN_BASE, outline=self.OUTLINE, width=1)
        # Highlight on left side (light from upper-left)
        hp1 = iso_project(-1.1, -0.1, 4.5, self.cx, self.cy, self.scale)
        hp2 = iso_project(-0.3, -0.1, 4.8, self.cx, self.cy, self.scale)
        self.c.create_oval(hp1[0], hp1[1]-0.4*self.scale,
                            hp2[0]+0.4*self.scale, hp2[1]+0.3*self.scale,
                            fill=self.SKIN_LIGHT, outline='')
        # Shadow on right
        sp1 = iso_project(0.8, -0.1, 3.0, self.cx, self.cy, self.scale)
        sp2 = iso_project(1.3, -0.1, 4.5, self.cx, self.cy, self.scale)
        self.c.create_oval(sp1[0], sp1[1], sp2[0]+0.3*self.scale, sp2[1]+0.3*self.scale,
                            fill=self.SKIN_DARK, outline='')

    def _draw_organs(self, highlight, sev_color):
        organs = [
            ('Heart',    -0.4, -0.1, 4.5, 0.35, self.ORGAN_HEART),
            ('Lungs',     0.55, -0.1, 4.6, 0.45, self.ORGAN_LUNG),
            ('Liver',    -0.4, -0.1, 3.6, 0.5,  self.ORGAN_LIVER),
            ('Kidneys',   0.5, -0.1, 3.3, 0.32, self.ORGAN_KIDNEY),
            ('Pancreas',  0.0, -0.1, 3.0, 0.38, self.ORGAN_PANCREAS),
            ('Muscles',   0.0, -0.1, 4.0, 0.0, ''),  # marker only
        ]
        for name, x, y, z, r, base_col in organs:
            if r == 0:
                continue
            matched = any(name in h for h in highlight)
            if matched:
                col = sev_color
                outline = shade_color(sev_color, 0.5)
            else:
                col = base_col
                outline = shade_color(base_col, 0.6)
            sx, sy = iso_project(x, y, z, self.cx, self.cy, self.scale)
            rx = r * self.scale
            ry = r * self.scale * 0.75
            self.c.create_oval(sx-rx, sy-ry, sx+rx, sy+ry,
                                fill=col, outline=outline, width=1)
            if matched:
                light = shade_color(sev_color, 1.5)
                self.c.create_oval(sx-rx*0.4, sy-ry*0.6,
                                    sx-rx*0.05, sy-ry*0.2,
                                    fill=light, outline='')
                # Glow ring
                self.c.create_oval(sx-rx-3, sy-ry-3, sx+rx+3, sy+ry+3,
                                    outline=col, width=1)
            else:
                # Subtle highlight
                light = shade_color(base_col, 1.3)
                self.c.create_oval(sx-rx*0.3, sy-ry*0.5,
                                    sx-rx*0.05, sy-ry*0.15,
                                    fill=light, outline='')

    def _draw_arms(self):
        # Left arm (back)
        x1, y1 = iso_project(-1.3, 0.1, 5.0, self.cx, self.cy, self.scale)
        x2, y2 = iso_project(-2.1, 0.1, 3.3, self.cx, self.cy, self.scale)
        self.c.create_line(x1, y1, x2, y2, fill=self.SKIN_DARK,
                            width=int(self.scale*0.65), capstyle='round')
        self.c.create_oval(x2-0.3*self.scale, y2-0.3*self.scale,
                            x2+0.3*self.scale, y2+0.3*self.scale,
                            fill=self.SKIN_DARK, outline=self.OUTLINE)
        # Right arm (front, lit)
        x1, y1 = iso_project(1.3, 0.1, 5.0, self.cx, self.cy, self.scale)
        x2, y2 = iso_project(2.1, 0.1, 3.3, self.cx, self.cy, self.scale)
        self.c.create_line(x1, y1, x2, y2, fill=self.SKIN_BASE,
                            width=int(self.scale*0.65), capstyle='round')
        self.c.create_oval(x2-0.3*self.scale, y2-0.3*self.scale,
                            x2+0.3*self.scale, y2+0.3*self.scale,
                            fill=self.SKIN_BASE, outline=self.OUTLINE)
        self.c.create_oval(x2-0.18*self.scale, y2-0.25*self.scale,
                            x2-0.02*self.scale, y2-0.1*self.scale,
                            fill=self.SKIN_LIGHT, outline='')

    def _draw_head(self, highlight, sev_color):
        head_brain = any(k in ' '.join(highlight)
                          for k in ['Brain','Cortex','Hippo','Neuron'])
        sx, sy = iso_project(0, 0, 6.2, self.cx, self.cy, self.scale)
        r = 0.85 * self.scale
        # Head sphere
        head_col = sev_color if head_brain else self.SKIN_BASE
        self.c.create_oval(sx-r, sy-r*1.1, sx+r, sy+r,
                            fill=head_col, outline=self.OUTLINE, width=1)
        # Light side
        light_col = shade_color(head_col, 1.3)
        self.c.create_oval(sx-r*0.6, sy-r*0.95, sx-r*0.05, sy-r*0.3,
                            fill=light_col, outline='')
        # Hair (top portion)
        self.c.create_arc(sx-r*0.95, sy-r*1.15, sx+r*0.95, sy-r*0.2,
                           start=0, extent=180, fill=self.HAIR, outline='')
        # Brain inside if highlighted
        if head_brain:
            inner = shade_color(sev_color, 0.65)
            self.c.create_arc(sx-r*0.55, sy-r*0.6, sx+r*0.55, sy+r*0.2,
                               start=0, extent=180, fill=inner, outline='')
        # Eye dot
        self.c.create_oval(sx-r*0.15, sy-r*0.05, sx-r*0.05, sy+r*0.05,
                            fill=self.OUTLINE, outline='')
        # Neck
        np1 = iso_project(-0.25, 0, 5.2, self.cx, self.cy, self.scale)
        np2 = iso_project( 0.25, 0, 5.2, self.cx, self.cy, self.scale)
        np3 = iso_project( 0.25, 0, 5.7, self.cx, self.cy, self.scale)
        np4 = iso_project(-0.25, 0, 5.7, self.cx, self.cy, self.scale)
        self.c.create_polygon(np1[0], np1[1], np2[0], np2[1],
                               np3[0], np3[1], np4[0], np4[1],
                               fill=self.SKIN_DARK, outline=self.OUTLINE)

    def draw_default(self, hint_text='Select a disease'):
        self.draw(highlight_organs=[], severity=0.0, severity_color='#1a7f37')
        w = self.c.winfo_width() or 700
        self.c.create_text(w//2, 16, text=hint_text,
                            fill='#57606a', font=('Arial', 9, 'italic'))

    def draw_disease(self, dis_data, severity, lang='ru'):
        organ_map = dis_data.get('organ_map', [])
        sev_color = self._sev_color(severity)
        self.draw(highlight_organs=organ_map, severity=severity, severity_color=sev_color)
        w = self.c.winfo_width() or 700
        name = dis_data.get('ru', '') if lang == 'ru' else dis_data.get('en', '')
        self.c.create_text(10, 10, text=name, fill=sev_color,
                            font=('Arial', 10, 'bold'), anchor='nw')
        self.c.create_text(w-10, 10, text='{:.0f}%'.format(severity*100),
                            fill=sev_color, font=('Arial', 11, 'bold'), anchor='ne')
        # Severity bar at bottom
        bar_w = 160
        bar_x = w//2 - bar_w//2
        bar_y = (self.c.winfo_height() or 260) - 12
        self.c.create_rectangle(bar_x, bar_y-7, bar_x+bar_w, bar_y,
                                  fill='#eef1f5', outline='#d0d7de')
        self.c.create_rectangle(bar_x, bar_y-7, bar_x+int(bar_w*severity), bar_y,
                                  fill=sev_color, outline='')

    def draw_mutation(self, gene, severity):
        sev_color = self._sev_color(severity)
        self.draw(highlight_organs=[], severity=severity, severity_color=sev_color)
        random.seed(hash(gene) % 1000)
        for _ in range(12):
            xx = random.uniform(-1.0, 1.0)
            yy = random.uniform(-0.1, 0.1)
            zz = random.uniform(3.0, 5.0)
            sx, sy = iso_project(xx, yy, zz, self.cx, self.cy, self.scale)
            self.c.create_oval(sx-4, sy-4, sx+4, sy+4,
                                fill=sev_color, outline='#f5f7fa')
            self.c.create_oval(sx-7, sy-7, sx+7, sy+7,
                                outline=sev_color, width=1)
        w = self.c.winfo_width() or 700
        self.c.create_text(10, 10, text='Mutation: '+gene, fill=sev_color,
                            font=('Arial', 10, 'bold'), anchor='nw')
        self.c.create_text(w-10, 10, text='{:.0f}%'.format(severity*100),
                            fill=sev_color, font=('Arial', 11, 'bold'), anchor='ne')

    def draw_alphafold(self, af_list):
        self.c.delete('all')
        w = self.c.winfo_width() or 700
        h = self.c.winfo_height() or 260
        self.c.create_text(w//2, 14, text='AlphaFold2 Structure Confidence',
                            fill='#0969da', font=('Arial', 10, 'bold'))
        if not af_list:
            self.c.create_text(w//2, h//2, text='No AlphaFold data',
                                fill='#57606a', font=('Arial', 10))
            return
        bar_h = 28; gap = 10; start_y = 38
        max_bar_w = w - 180
        for i, af in enumerate(af_list[:5]):
            y = start_y + i * (bar_h + gap)
            conf = float(af.get('confidence', 0))
            col = '#1a7f37' if conf > 70 else ('#9a6700' if conf > 50 else '#cf222e')
            bw = int(max_bar_w * conf / 100.0)
            lbl = (af.get('gene','') or af.get('protein','') or af.get('acc',''))[:18]
            self.c.create_rectangle(15, y, 15+max_bar_w, y+bar_h,
                                      fill='#eef1f5', outline='#d0d7de')
            self.c.create_rectangle(15, y+2, 15+bw, y+bar_h-2, fill=col, outline='')
            light = shade_color(col, 1.3)
            self.c.create_rectangle(15, y+2, 15+bw, y+9, fill=light, outline='')
            self.c.create_text(20, y+bar_h//2, text=lbl,
                                fill='#f5f7fa', font=('Arial', 9, 'bold'), anchor='w')
            self.c.create_text(15+max_bar_w+10, y+bar_h//2,
                                text='{:.0f}%'.format(conf), fill=col,
                                font=('Arial', 9, 'bold'), anchor='w')

    def _overlay_organs(self, highlight, sev_color, w, h):
        """Draw colored highlight circles over a background image where organs are."""
        # Approximate organ positions on a typical anatomy image (relative coordinates)
        # x_frac, y_frac, name, radius_frac
        organ_positions = [
            ('Heart',    0.45, 0.40, 0.08),
            ('Lungs',    0.55, 0.38, 0.10),
            ('Liver',    0.45, 0.55, 0.10),
            ('Kidneys',  0.55, 0.58, 0.07),
            ('Pancreas', 0.50, 0.60, 0.08),
            ('Brain',    0.50, 0.10, 0.08),
            ('Cortex',   0.50, 0.08, 0.08),
            ('Hippo',    0.50, 0.12, 0.06),
            ('Muscles',  0.50, 0.45, 0.10),
        ]
        for name, xf, yf, rf in organ_positions:
            matched = any(name in hh for hh in highlight)
            if not matched:
                continue
            cx = int(w * xf)
            cy = int(h * yf)
            r = int(min(w, h) * rf)
            # Glow ring
            self.c.create_oval(cx - r - 4, cy - r - 4, cx + r + 4, cy + r + 4,
                                outline=sev_color, width=2)
            # Inner translucent (approximated with stipple)
            self.c.create_oval(cx - r, cy - r, cx + r, cy + r,
                                outline=sev_color, width=3)

    def _sev_color(self, s):
        if s < 0.25: return '#1a7f37'
        elif s < 0.5: return '#9a6700'
        elif s < 0.75: return '#bc4c00'
        return '#cf222e'


# ─────────────────────────────────────────────────
# 2.5D PROTEIN VIEWER (from AlphaFold PDB)
# ─────────────────────────────────────────────────
def parse_pdb_calpha(pdb_text):
    """Extract Cα atoms from PDB text. Returns list of (x, y, z, residue_index, bfactor)."""
    atoms = []
    for line in pdb_text.split('\n'):
        if line.startswith('ATOM') and len(line) > 60:
            try:
                atom_name = line[12:16].strip()
                if atom_name != 'CA':
                    continue
                x = float(line[30:38])
                y = float(line[38:46])
                z = float(line[46:54])
                res_id = int(line[22:26])
                bfactor = float(line[60:66]) if len(line) > 66 else 50.0
                atoms.append((x, y, z, res_id, bfactor))
            except (ValueError, IndexError) as _exc:
                biosim_log('warn', 'parse_pdb_calpha: {}'.format(_exc))
                continue
    return atoms


def fetch_pdb_for_uniprot(acc):
    """Fetch AlphaFold PDB for a UniProt accession."""
    url = 'https://alphafold.ebi.ac.uk/files/AF-{}-F1-model_v4.pdb'.format(acc)
    return _get_text(url)


class Protein3DViewer(tk.Toplevel):
    """3D protein structure viewer using matplotlib (works for everyone).

    Shows protein backbone (alpha-carbon trace) as a rotatable 3D ribbon.
    Includes search to fetch any protein from RCSB PDB over the internet.
    """
    def __init__(self, parent, uniprot_acc='', protein_name='Protein', gene=''):
        super().__init__(parent)
        self.title('3D: ' + protein_name)
        self.geometry('860x720')
        self.configure(bg=biosim_theme('bg'))
        self.parent = parent
        self.lang = getattr(parent, 'lang', 'ru')
        is_ru = (self.lang == 'ru')
        self.current_structure = None
        self.canvas_widget = None

        # Header
        top = tk.Frame(self, bg=biosim_theme('panel'), height=54)
        top.pack(fill='x'); top.pack_propagate(False)
        tk.Label(top, text=('3D Структура белка' if is_ru else '3D Protein Structure'),
                 font=('Arial', 14, 'bold'), bg=biosim_theme('panel'), fg='#0969da').pack(side='left', padx=14, pady=12)

        # Search bar
        search_frame = tk.Frame(self, bg=biosim_theme('bg'))
        search_frame.pack(fill='x', padx=12, pady=8)
        tk.Label(search_frame, text=('Поиск белка:' if is_ru else 'Search protein:'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text'), font=('Arial', 10)).pack(side='left')
        self.search_var = tk.StringVar(value=protein_name if protein_name != 'Protein' else 'insulin')
        search_entry = tk.Entry(search_frame, textvariable=self.search_var,
                                bg=biosim_theme('panel2'), fg=biosim_theme('text'), relief='flat',
                                font=('Arial', 11), width=30)
        search_entry.pack(side='left', padx=8, ipady=3)
        search_entry.bind('<Return>', lambda e: self._do_search())
        tk.Button(search_frame, text=('Найти' if is_ru else 'Search'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat', font=('Arial', 10, 'bold'),
                  cursor='hand2', padx=14, command=self._do_search).pack(side='left', padx=4)
        tk.Label(search_frame, text=('или PDB ID:' if is_ru else 'or PDB ID:'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9)).pack(side='left', padx=(12, 4))
        self.pdb_var = tk.StringVar()
        pdb_entry = tk.Entry(search_frame, textvariable=self.pdb_var, bg=biosim_theme('panel2'),
                             fg=biosim_theme('text'), relief='flat', font=('Courier', 11), width=8)
        pdb_entry.pack(side='left', ipady=3)
        pdb_entry.bind('<Return>', lambda e: self._load_pdb_id(self.pdb_var.get()))
        tk.Button(search_frame, text='→', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                  font=('Arial', 10, 'bold'), cursor='hand2', padx=10,
                  command=lambda: self._load_pdb_id(self.pdb_var.get())).pack(side='left', padx=4)

        # Results dropdown (populated after search)
        self.results_frame = tk.Frame(self, bg=biosim_theme('bg'))
        self.results_frame.pack(fill='x', padx=12)

        # Status
        self.status = tk.Label(self, text=('Введите название белка и нажмите Найти'
                                            if is_ru else 'Enter a protein name and click Search'),
                                bg=biosim_theme('bg'), fg='#9a6700', font=('Arial', 10))
        self.status.pack(pady=4)

        # 3D plot area
        self.plot_frame = tk.Frame(self, bg=biosim_theme('bg'))
        self.plot_frame.pack(fill='both', expand=True, padx=8, pady=4)

        # View controls
        ctrl = tk.Frame(self, bg=biosim_theme('panel'))
        ctrl.pack(fill='x', padx=8, pady=4)
        self.view_mode = tk.StringVar(value='backbone')
        tk.Label(ctrl, text=('Вид:' if is_ru else 'View:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=6)
        for val, lbl in [('backbone', 'Цепь' if is_ru else 'Backbone'),
                          ('cloud', 'Атомы' if is_ru else 'Atoms')]:
            tk.Radiobutton(ctrl, text=lbl, variable=self.view_mode, value=val,
                            bg=biosim_theme('panel'), fg='#0969da', selectcolor='#eef1f5',
                            font=('Arial', 9), command=self._redraw).pack(side='left', padx=4)
        tk.Label(ctrl, text=('Вращайте мышкой' if is_ru else 'Drag to rotate'),
                 bg=biosim_theme('panel'), fg='#1a7f37', font=('Arial', 9, 'italic')).pack(side='right', padx=10)

        # Auto-load if we have a name
        if uniprot_acc or (protein_name and protein_name != 'Protein'):
            self.after(300, self._do_search)

    def _do_search(self):
        is_ru = (self.lang == 'ru')
        query = self.search_var.get().strip()
        if not query:
            return
        self.status.config(text=('Поиск...' if is_ru else 'Searching...'), fg='#9a6700')
        self.update()

        def worker():
            result = search_pdb_protein(query, max_results=6)
            self.after(0, lambda: self._show_results(result))
        threading.Thread(target=worker, daemon=True).start()

    def _show_results(self, result):
        is_ru = (self.lang == 'ru')
        for w in self.results_frame.winfo_children():
            w.destroy()
        if result.get('error'):
            self.status.config(text=('Ошибка: ' if is_ru else 'Error: ') + str(result['error'])
                               + ('  (нужен интернет)' if is_ru else '  (internet needed)'),
                               fg='#cf222e')
            return
        results = result.get('results', [])
        if not results:
            self.status.config(text=('Ничего не найдено' if is_ru else 'Nothing found'), fg='#cf222e')
            return
        self.status.config(text=('Найдено структур: ' if is_ru else 'Found structures: ')
                           + str(len(results)) + ('  — выберите одну' if is_ru else '  — pick one'),
                           fg='#1a7f37')
        row = tk.Frame(self.results_frame, bg=biosim_theme('bg'))
        row.pack(fill='x', pady=4)
        for r in results:
            pdb_id = r['pdb_id']
            tk.Button(row, text=pdb_id, bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       font=('Courier', 11, 'bold'), cursor='hand2', padx=12, pady=4,
                       command=lambda p=pdb_id: self._load_pdb_id(p)).pack(side='left', padx=3)

    def _load_pdb_id(self, pdb_id):
        is_ru = (self.lang == 'ru')
        pdb_id = pdb_id.strip().upper()
        if not pdb_id:
            return
        self.status.config(text=('Загрузка ' if is_ru else 'Loading ') + pdb_id + '...', fg='#9a6700')
        self.update()

        def worker():
            struct = fetch_pdb_structure(pdb_id)
            self.after(0, lambda: self._on_structure_loaded(struct, pdb_id))
        threading.Thread(target=worker, daemon=True).start()

    def _on_structure_loaded(self, struct, pdb_id):
        is_ru = (self.lang == 'ru')
        if struct.get('error'):
            self.status.config(text=('Ошибка загрузки: ' if is_ru else 'Load error: ')
                               + str(struct['error']), fg='#cf222e')
            return
        self.current_structure = struct
        self.current_pdb_id = pdb_id
        self.status.config(text='{} — {} '.format(pdb_id, struct['n_residues'])
                           + ('остатков, цепи: ' if is_ru else 'residues, chains: ')
                           + ', '.join(struct['chains']), fg='#1a7f37')
        self._redraw()

    def _redraw(self):
        if not self.current_structure:
            return
        import matplotlib.pyplot as plt
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        from mpl_toolkits.mplot3d import Axes3D  # noqa
        if self.canvas_widget:
            self.canvas_widget.get_tk_widget().destroy()
        fig = plt.Figure(figsize=(8, 5), facecolor='#f5f7fa')
        ax = fig.add_subplot(111, projection='3d', facecolor='#f5f7fa')
        struct = self.current_structure

        if self.view_mode.get() == 'backbone':
            # Draw CA trace as connected ribbon, colored by chain
            chain_colors = {'A': '#0969da', 'B': '#1a7f37', 'C': '#9a6700',
                            'D': '#cf222e', 'E': '#8250df'}
            from collections import defaultdict
            by_chain = defaultdict(list)
            for ca in struct['ca_atoms']:
                by_chain[ca['chain']].append(ca)
            for chain, atoms in by_chain.items():
                xs = [a['x'] for a in atoms]
                ys = [a['y'] for a in atoms]
                zs = [a['z'] for a in atoms]
                color = chain_colors.get(chain, '#57606a')
                ax.plot(xs, ys, zs, color=color, lw=2.5, label='Chain ' + chain)
                # Mark start/end
                if xs:
                    ax.scatter([xs[0]], [ys[0]], [zs[0]], color='#1a7f37', s=40)
                    ax.scatter([xs[-1]], [ys[-1]], [zs[-1]], color='#cf222e', s=40)
            ax.legend(facecolor='#eef1f5', labelcolor='#1c2128', fontsize=8)
        else:
            # Atom cloud colored by element
            elem_colors = {'C': '#909090', 'N': '#3050f8', 'O': '#ff0d0d',
                           'S': '#ffff30', 'P': '#ff8000', 'H': '#ffffff'}
            xs, ys, zs, cs = [], [], [], []
            for a in struct['all_atoms']:
                xs.append(a['x']); ys.append(a['y']); zs.append(a['z'])
                cs.append(elem_colors.get(a['element'], '#ff80ff'))
            ax.scatter(xs, ys, zs, c=cs, s=12, alpha=0.7)

        ax.set_facecolor('#f5f7fa')
        ax.set_xlabel('X', color='#57606a'); ax.set_ylabel('Y', color='#57606a')
        ax.set_zlabel('Z', color='#57606a')
        ax.tick_params(colors='#57606a')
        ax.xaxis.pane.set_facecolor('#f5f7fa')
        ax.yaxis.pane.set_facecolor('#f5f7fa')
        ax.zaxis.pane.set_facecolor('#f5f7fa')
        ax.set_title(getattr(self, 'current_pdb_id', 'Protein'), color='#1c2128')

        cv = FigureCanvasTkAgg(fig, master=self.plot_frame)
        cv.draw()
        cv.get_tk_widget().pack(fill='both', expand=True)
        self.canvas_widget = cv


class DNAViewer(tk.Toplevel):
    """Show animated DNA double helix for a gene."""
    def __init__(self, parent, gene_symbol, gene_data=None):
        super().__init__(parent)
        self.title('DNA: ' + gene_symbol)
        self.geometry('600x650')
        self.configure(bg=biosim_theme('bg'))
        self.gene = gene_symbol
        self.gene_data = gene_data or {}
        self.rotation = 0.0
        self.animating = True

        top = tk.Frame(self, bg=biosim_theme('panel'), height=50)
        top.pack(fill='x')
        top.pack_propagate(False)
        tk.Label(top, text='2.5D DNA Double Helix', font=('Arial', 13, 'bold'),
                 bg=biosim_theme('panel'), fg='#0969da').pack(side='left', padx=12, pady=10)
        tk.Label(top, text='Gene: ' + gene_symbol, font=('Arial', 11),
                 bg=biosim_theme('panel'), fg='#1a7f37').pack(side='left', pady=10)

        self.canvas = tk.Canvas(self, bg=biosim_theme('bg'), highlightthickness=0, width=580, height=440)
        self.canvas.pack(padx=8, pady=6)

        info = tk.Frame(self, bg=biosim_theme('panel'))
        info.pack(fill='x', padx=8, pady=4)
        if gene_data:
            text = 'Chromosome: {}  Location: {}  Gene ID: {}'.format(
                gene_data.get('chrom', '?'),
                gene_data.get('loc', '?'),
                gene_data.get('id', '?'))
            tk.Label(info, text=text, bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                     font=('Arial', 9)).pack(anchor='w', padx=8, pady=4)
            if gene_data.get('fullname'):
                tk.Label(info, text=gene_data['fullname'][:80], bg=biosim_theme('panel'), fg=biosim_theme('text'),
                         font=('Arial', 10)).pack(anchor='w', padx=8, pady=2)
            if gene_data.get('summary'):
                tk.Label(info, text=gene_data['summary'][:200], bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                         font=('Arial', 9), wraplength=560, justify='left'
                         ).pack(anchor='w', padx=8, pady=4)

        ctrl = tk.Frame(self, bg=biosim_theme('bg'))
        ctrl.pack(fill='x', padx=8, pady=4)
        tk.Button(ctrl, text='Pause/Play', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                  relief='solid', bd=1, font=('Arial', 10), cursor='hand2',
                  command=self._toggle).pack(side='left', padx=4)

        self._animate()

    def _animate(self):
        if self.animating:
            self.rotation += 0.04
        self._render()
        self.after(50, self._animate)

    def _render(self):
        self.canvas.delete('all')
        w = 580; h = 440
        cx = w // 2
        # Helix parameters
        radius = 60
        height_step = 14
        n_pairs = 28
        bases = ['A', 'T', 'C', 'G']
        # Sequence-like coloring (pseudo-random based on gene name)
        random.seed(hash(self.gene) % 1000)
        sequence = [random.choice(bases) for _ in range(n_pairs)]
        base_colors = {'A': '#e84855', 'T': '#1a7f37', 'C': '#0969da', 'G': '#bc4c00'}
        complementary = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}

        # Draw from back to front (sort by z)
        positions = []
        for i in range(n_pairs):
            angle = i * 0.35 + self.rotation
            y = 30 + i * height_step
            x1 = cx + radius * math.cos(angle)
            x2 = cx + radius * math.cos(angle + math.pi)
            z1 = math.sin(angle)
            z2 = math.sin(angle + math.pi)
            positions.append((y, x1, z1, x2, z2, sequence[i]))

        # Draw backbones (continuous lines)
        prev_strand1 = None
        prev_strand2 = None
        for y, x1, z1, x2, z2, base in positions:
            if prev_strand1 is not None:
                d1 = (z1 + 1) / 2  # 0..1
                d2 = (prev_strand1[2] + 1) / 2
                avg_d = (d1 + d2) / 2
                col = self._depth_color('#0969da', avg_d)
                self.canvas.create_line(prev_strand1[0], prev_strand1[1], x1, y,
                                          fill=col, width=int(2 + avg_d * 2))
                d1 = (z2 + 1) / 2
                d2 = (prev_strand2[2] + 1) / 2
                avg_d = (d1 + d2) / 2
                col = self._depth_color('#8250df', avg_d)
                self.canvas.create_line(prev_strand2[0], prev_strand2[1], x2, y,
                                          fill=col, width=int(2 + avg_d * 2))
            prev_strand1 = (x1, y, z1)
            prev_strand2 = (x2, y, z2)

        # Draw base pairs (rungs of the ladder)
        for y, x1, z1, x2, z2, base in positions:
            depth = (max(z1, z2) + 1) / 2
            col = base_colors[base]
            col_dim = self._depth_color(col, 0.5 + depth * 0.5)
            self.canvas.create_line(x1, y, x2, y, fill=col_dim, width=1)
            # Letter labels at ends
            r = 4 + depth * 2
            self.canvas.create_oval(x1 - r, y - r, x1 + r, y + r,
                                      fill=col, outline='#f5f7fa')
            comp = complementary[base]
            comp_col = base_colors[comp]
            self.canvas.create_oval(x2 - r, y - r, x2 + r, y + r,
                                      fill=comp_col, outline='#f5f7fa')

        # Legend
        self.canvas.create_text(10, 10, anchor='nw',
                                 text='A (red)  T (green)  C (blue)  G (orange)',
                                 fill='#57606a', font=('Arial', 8))

    def _depth_color(self, hex_color, depth):
        h = hex_color.lstrip('#')
        r = int(h[0:2], 16); g = int(h[2:4], 16); b = int(h[4:6], 16)
        depth = max(0.3, min(1.0, depth))
        r = int(r * depth); g = int(g * depth); b = int(b * depth)
        return '#{:02x}{:02x}{:02x}'.format(r, g, b)

    def _toggle(self):
        self.animating = not self.animating


# ─────────────────────────────────────────────────
# 2.5D ORGAN VIEWER (with optional PNG from images/)
# ─────────────────────────────────────────────────
class OrganViewer(tk.Toplevel):
    """Show organ — uses PNG from images/<organ>.png if available, otherwise drawn."""
    ORGAN_COLORS = {
        'Heart':    '#e84855',
        'Lungs':    '#f4a8b8',
        'Liver':    '#a05050',
        'Kidneys':  '#c46868',
        'Pancreas': '#d49060',
        'Brain':    '#f0a0a8',
        'Muscles':  '#c87060',
        'Skin':     '#ffb8a0',
    }

    def __init__(self, parent, organ_name, disease_data=None, lang='ru'):
        super().__init__(parent)
        self.title('Organ: ' + organ_name)
        self.geometry('700x650')
        self.configure(bg=biosim_theme('bg'))
        self.organ = organ_name
        self.disease_data = disease_data
        self.lang = lang
        self.day = tk.IntVar(value=1)
        self.img = None
        self.photo = None

        top = tk.Frame(self, bg=biosim_theme('panel'), height=50)
        top.pack(fill='x')
        top.pack_propagate(False)
        tk.Label(top, text='2.5D Organ View', font=('Arial', 13, 'bold'),
                 bg=biosim_theme('panel'), fg='#0969da').pack(side='left', padx=12, pady=10)
        tk.Label(top, text=organ_name, font=('Arial', 12, 'bold'),
                 bg=biosim_theme('panel'), fg=self.ORGAN_COLORS.get(organ_name, '#1c2128')
                 ).pack(side='left', pady=10)

        # Try to load PNG
        if HAS_PIL:
            try:
                script_dir = os.path.dirname(os.path.abspath(__file__))
                png_path = os.path.join(script_dir, 'images', organ_name.lower() + '.png')
                if not os.path.exists(png_path):
                    # try alternate names
                    alt = os.path.join(script_dir, 'images', organ_name + '.png')
                    if os.path.exists(alt):
                        png_path = alt
                if os.path.exists(png_path):
                    self.img = Image.open(png_path)
            except Exception as _exc:
                biosim_log('warn', '__init__: {}'.format(_exc))

        self.canvas = tk.Canvas(self, bg=biosim_theme('bg'), highlightthickness=0, width=680, height=440)
        self.canvas.pack(padx=8, pady=6)

        if disease_data:
            dname = disease_data.get('ru' if lang == 'ru' else 'en', '')
            ctrl = tk.Frame(self, bg=biosim_theme('panel'))
            ctrl.pack(fill='x', padx=8, pady=4)
            tk.Label(ctrl, text='Disease: ' + dname,
                     bg=biosim_theme('panel'), fg='#cf222e',
                     font=('Arial', 10, 'bold')).pack(anchor='w', padx=8, pady=4)
            ds = tk.Frame(ctrl, bg=biosim_theme('panel'))
            ds.pack(fill='x', padx=8, pady=4)
            tk.Label(ds, text='Day:', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                     font=('Arial', 9)).pack(side='left')
            self.day_lbl = tk.Label(ds, text='1', bg=biosim_theme('panel'), fg='#0969da',
                                      font=('Arial', 10, 'bold'), width=4)
            self.day_lbl.pack(side='right')
            tk.Scale(ds, from_=1, to=365, orient='horizontal', variable=self.day,
                     bg=biosim_theme('panel'), fg=biosim_theme('text'), highlightthickness=0,
                     troughcolor='#eef1f5', activebackground='#1a7f37',
                     command=lambda v: (self.day_lbl.config(text=v), self._render())
                     ).pack(side='left', fill='x', expand=True)

        self._render()

    def _render(self):
        self.canvas.delete('all')
        w = 680; h = 440
        cx = w // 2; cy = h // 2

        # Calculate severity from day if disease is set
        severity = 0.0
        if self.disease_data:
            day = safe_int(self.day.get(), 0)
            base = self.disease_data.get('params', {}).get('base', 0.7)
            # Logistic growth approximation
            severity = base * (1 - math.exp(-day / 60.0))
            severity = min(1.0, max(0.0, severity))

        # Draw PNG image if available
        if self.img is not None and HAS_PIL:
            try:
                img = self.img.copy()
                img.thumbnail((w - 40, h - 60), Image.LANCZOS)
                self.photo = ImageTk.PhotoImage(img)
                self.canvas.create_image(cx, cy, image=self.photo)
                # Overlay severity tint
                if severity > 0:
                    sev_color = self._sev_color(severity)
                    iw, ih = img.size
                    self.canvas.create_oval(cx - iw // 3, cy - ih // 3,
                                              cx + iw // 3, cy + ih // 3,
                                              outline=sev_color, width=3)
            except Exception as _exc:
                biosim_log('warn', '_render: {}'.format(_exc))
                self._draw_default_organ(cx, cy, severity)
        else:
            self._draw_default_organ(cx, cy, severity)

        # Bottom info
        if self.disease_data:
            sev_color = self._sev_color(severity)
            sev_pct = int(severity * 100)
            label = 'Healthy' if severity < 0.25 else ('Mild' if severity < 0.5 else ('Severe' if severity < 0.75 else 'Critical'))
            self.canvas.create_text(cx, h - 20,
                                      text='Damage: {}%   {}'.format(sev_pct, label),
                                      fill=sev_color, font=('Arial', 12, 'bold'))
        if not self.img:
            self.canvas.create_text(cx, 20,
                                      text='Tip: Save a PNG to images/' + self.organ.lower() + '.png for a realistic view',
                                      fill='#484f58', font=('Arial', 9, 'italic'))

    def _draw_default_organ(self, cx, cy, severity):
        """Draw a stylized organ when no PNG is available."""
        col = self.ORGAN_COLORS.get(self.organ, '#c87060')
        if severity > 0:
            sev_col = self._sev_color(severity)
            # Blend
            blend = severity
            col = self._blend(col, sev_col, blend)

        # Different shape per organ
        if self.organ == 'Heart':
            self._draw_heart(cx, cy, col, 160)
        elif self.organ == 'Lungs':
            self._draw_lungs(cx, cy, col, 160)
        elif self.organ == 'Liver':
            self._draw_liver(cx, cy, col, 160)
        elif self.organ == 'Brain':
            self._draw_brain(cx, cy, col, 160)
        elif self.organ == 'Kidneys':
            self._draw_kidneys(cx, cy, col, 160)
        else:
            self.canvas.create_oval(cx - 120, cy - 80, cx + 120, cy + 80,
                                      fill=col, outline='#f5f7fa', width=2)
            self.canvas.create_text(cx, cy, text=self.organ, fill='white',
                                      font=('Arial', 16, 'bold'))

        # Damage markers if severity high
        if severity > 0.4:
            random.seed(int(severity * 100))
            n_marks = int(severity * 20)
            for _ in range(n_marks):
                mx = cx + random.uniform(-100, 100)
                my = cy + random.uniform(-60, 60)
                r = random.uniform(3, 8)
                dark = self._darken(col, 0.5)
                self.canvas.create_oval(mx - r, my - r, mx + r, my + r,
                                          fill=dark, outline='')

    def _draw_heart(self, cx, cy, col, size):
        # Stylized heart
        s = size / 160
        self.canvas.create_oval(cx - 70*s, cy - 60*s, cx - 10*s, cy + 10*s,
                                  fill=col, outline='#f5f7fa', width=2)
        self.canvas.create_oval(cx + 10*s, cy - 60*s, cx + 70*s, cy + 10*s,
                                  fill=col, outline='#f5f7fa', width=2)
        self.canvas.create_polygon(cx - 70*s, cy - 20*s, cx + 70*s, cy - 20*s,
                                     cx, cy + 80*s,
                                     fill=col, outline='#f5f7fa', width=2)

    def _draw_lungs(self, cx, cy, col, size):
        s = size / 160
        self.canvas.create_oval(cx - 100*s, cy - 80*s, cx - 20*s, cy + 80*s,
                                  fill=col, outline='#f5f7fa', width=2)
        self.canvas.create_oval(cx + 20*s, cy - 80*s, cx + 100*s, cy + 80*s,
                                  fill=col, outline='#f5f7fa', width=2)
        # Trachea
        self.canvas.create_line(cx, cy - 80*s, cx, cy - 100*s,
                                  fill='#57606a', width=int(8*s))

    def _draw_liver(self, cx, cy, col, size):
        s = size / 160
        points = [
            cx - 110*s, cy - 30*s,
            cx + 100*s, cy - 60*s,
            cx + 110*s, cy + 20*s,
            cx + 60*s, cy + 60*s,
            cx - 80*s, cy + 50*s,
            cx - 110*s, cy + 10*s,
        ]
        self.canvas.create_polygon(points, fill=col, outline='#f5f7fa', width=2,
                                     smooth=True)

    def _draw_brain(self, cx, cy, col, size):
        s = size / 160
        self.canvas.create_oval(cx - 100*s, cy - 70*s, cx + 100*s, cy + 70*s,
                                  fill=col, outline='#f5f7fa', width=2)
        # Folds
        for i in range(5):
            y = cy - 50 + i * 25
            self.canvas.create_arc(cx - 80, y, cx + 80, y + 20,
                                      start=0, extent=180, style='arc',
                                      outline=self._darken(col, 0.7), width=2)

    def _draw_kidneys(self, cx, cy, col, size):
        s = size / 160
        # Two bean shapes
        self.canvas.create_oval(cx - 90*s, cy - 60*s, cx - 20*s, cy + 60*s,
                                  fill=col, outline='#f5f7fa', width=2)
        self.canvas.create_oval(cx + 20*s, cy - 60*s, cx + 90*s, cy + 60*s,
                                  fill=col, outline='#f5f7fa', width=2)

    def _sev_color(self, s):
        if s < 0.25:   return '#1a7f37'
        elif s < 0.5:  return '#9a6700'
        elif s < 0.75: return '#bc4c00'
        return '#cf222e'

    def _blend(self, hex1, hex2, ratio):
        h1 = hex1.lstrip('#'); h2 = hex2.lstrip('#')
        r1 = int(h1[0:2], 16); g1 = int(h1[2:4], 16); b1 = int(h1[4:6], 16)
        r2 = int(h2[0:2], 16); g2 = int(h2[2:4], 16); b2 = int(h2[4:6], 16)
        r = int(r1 * (1 - ratio) + r2 * ratio)
        g = int(g1 * (1 - ratio) + g2 * ratio)
        b = int(b1 * (1 - ratio) + b2 * ratio)
        return '#{:02x}{:02x}{:02x}'.format(r, g, b)

    def _darken(self, hex_color, factor):
        h = hex_color.lstrip('#')
        r = int(int(h[0:2], 16) * factor)
        g = int(int(h[2:4], 16) * factor)
        b = int(int(h[4:6], 16) * factor)
        return '#{:02x}{:02x}{:02x}'.format(r, g, b)


