def part_provenance(part):
    """How trustworthy is a part's number? Returns (label_ru, label_en, colour)."""
    src = (part or {}).get('source', 'conventional')
    if src == 'measured':
        return ('измеренное значение', 'measured value', '#1a7f37')
    return ('условное значение, не измерение',
            'conventional value, not a measurement', '#9a6700')


def characterised_parts_by_kind(kind):
    """Named parts of one kind, strongest first."""
    items = [(k, v) for k, v in CHARACTERISED_PARTS.items()
             if v.get('kind') == kind]
    items.sort(key=lambda kv: -kv[1].get('strength', 0))
    return items


