def run_validation_suite(presets_to_test=None, verbose=False):
    """Run automated validation tests against reference results.
    
    Returns dict with:
        'passed': int, 'failed': int, 'total': int,
        'results': [{'preset': str, 'passed': bool, 'message': str}]
    """
    import copy
    results = []
    if presets_to_test is None:
        presets_to_test = list(VALIDATION_REFERENCES.keys())
    
    for preset_key in presets_to_test:
        if preset_key not in SCIENTIFIC_PRESETS:
            results.append({'preset': preset_key, 'passed': False,
                              'message': 'Preset not found'})
            continue
        if preset_key not in VALIDATION_REFERENCES:
            results.append({'preset': preset_key, 'passed': False,
                              'message': 'No reference data'})
            continue
        
        preset = SCIENTIFIC_PRESETS[preset_key]
        ref = VALIDATION_REFERENCES[preset_key]
        passed = True
        messages = []
        
        try:
            # Build state from preset
            state = {
                'nodes': copy.deepcopy(preset['nodes']),
                'edges': copy.deepcopy(preset['edges']),
                'init': copy.deepcopy(preset['init']),
            }
            
            # Run ODE simulation
            t, y, ids = run_ode_simulation(state['nodes'], state['edges'],
                                              state['init'], t_end=200)
            if t is None:
                results.append({'preset': preset_key, 'passed': False,
                                  'message': 'Simulation failed'})
                continue
            
            # Check expected steady state ranges
            if 'expected_steady_state' in ref:
                final = y[-int(len(t) * 0.1):].mean(axis=0)  # avg of last 10%
                for nid, range_spec in ref['expected_steady_state'].items():
                    if nid not in ids:
                        continue
                    idx = ids.index(nid)
                    val = float(final[idx])
                    if val < range_spec['min'] or val > range_spec['max']:
                        passed = False
                        messages.append(
                            '{} = {:.3f} outside [{}, {}]'.format(
                                nid, val, range_spec['min'], range_spec['max']))
            
            # Check expected behavior
            behavior = ref.get('expected_behavior')
            if behavior == 'oscillations':
                # Check for oscillations: count zero crossings of derivative
                if len(t) > 100:
                    y0 = y[:, 0]
                    y0_centered = y0 - y0.mean()
                    crossings = np.sum(np.diff(np.sign(y0_centered)) != 0)
                    if crossings < 4:
                        passed = False
                        messages.append('Expected oscillations, got only {} zero-crossings'.format(crossings))
            elif behavior == 'reaches_state':
                # Just check it didn't blow up
                final = y[-1]
                if np.any(np.isnan(final)) or np.any(np.isinf(final)):
                    passed = False
                    messages.append('Values exploded to inf/nan')
            
            msg = 'PASS' if passed else '; '.join(messages)
            results.append({'preset': preset_key, 'passed': passed, 'message': msg})
            
            if verbose:
                print('  {} {}: {}'.format('' if passed else '', preset_key, msg))
        except Exception as e:
            biosim_log('warn', 'run_validation_suite: {}'.format(e))
            results.append({'preset': preset_key, 'passed': False,
                              'message': 'Error: ' + str(e)[:80]})
    
    n_passed = sum(1 for r in results if r['passed'])
    return {
        'passed': n_passed,
        'failed': len(results) - n_passed,
        'total': len(results),
        'results': results,
    }




