def calculate_plasmid_metrics(parts_list, host_key):
    """Calculate plasmid metrics: total length, GC, copies, expression score."""
    if not parts_list:
        return {'total_bp': 0, 'n_parts': 0, 'promoters': 0, 'genes': 0,
                'copies_per_cell': 0, 'expression_score': 0, 'has_ori': False,
                'has_resistance': False, 'errors': ['Empty plasmid']}

    total_bp = 0
    promoters = []
    genes = []
    has_ori = False
    has_resistance = False
    ori_strength = 0
    rbs_strength = 50  # default if no RBS

    for p in parts_list:
        part = PLASMID_PARTS.get(p['part_key'])
        if not part:
            continue
        total_bp += part['length']
        if part['type'] == 'promoter':
            promoters.append(part)
        elif part['type'] == 'gene':
            genes.append(part)
        elif part['type'] == 'origin':
            has_ori = True
            ori_strength = part['strength']
        elif part['type'] == 'resistance':
            has_resistance = True
        elif part['type'] == 'rbs':
            rbs_strength = part['strength']

    # Host
    host = PLASMID_HOSTS.get(host_key, PLASMID_HOSTS['E_coli_DH5a'])
    expression_eff = host['expression_eff']

    # Copies per cell — based on origin strength (0..100 maps to ~5..700)
    if has_ori:
        copies_per_cell = int(5 + ori_strength * 7)
    else:
        copies_per_cell = 0

    # Expression score — promoter strength × RBS × host efficiency × gene presence
    if promoters and genes:
        avg_prom = sum(p['strength'] for p in promoters) / len(promoters)
        expression_score = (avg_prom * rbs_strength / 100.0) * expression_eff
    else:
        expression_score = 0

    # Errors / warnings
    errors = []
    if not has_ori:
        errors.append('No origin of replication — will not replicate')
    if not has_resistance:
        errors.append('No resistance marker — cannot select transformants')
    if not promoters and genes:
        errors.append('Gene without promoter — no expression')
    if promoters and not genes:
        errors.append('Promoter without gene')
    if total_bp > 15000:
        errors.append('Plasmid too large ({} bp) — low transformation efficiency'.format(total_bp))

    return {
        'total_bp': total_bp,
        'n_parts': len(parts_list),
        'promoters': len(promoters),
        'genes': len(genes),
        'copies_per_cell': copies_per_cell,
        'expression_score': round(expression_score, 1),
        'has_ori': has_ori,
        'has_resistance': has_resistance,
        'errors': errors,
        'host': host_key,
    }


