def calculate_metabolic_flux(organism_key, product_key, added_enzymes, knocked_out, substrate_g_per_h=10.0):
    """Calculate predicted product yield based on metabolic engineering.
    
    Returns dict with:
        - yield_g_per_g (productivity, g product / g substrate)
        - rate_g_per_h (production rate)
        - missing_enzymes (list of required but missing)
        - bottlenecks (list of bottleneck pathways)
        - warnings
    """
    org = METABOLIC_ORGANISMS.get(organism_key)
    prod = METABOLIC_PRODUCTS.get(product_key)
    if not org or not prod:
        return None
    
    # Check required genes
    required = set(prod['required_genes'])
    available = set(added_enzymes)
    # If organism natively makes this product, assume native enzymes available
    if organism_key in prod['native_in']:
        # Half of required enzymes are already there
        native_count = max(1, len(required) // 2)
        available.update(list(required)[:native_count])
    missing = required - available
    
    # Base theoretical yield
    base_yield = prod['industrial_yield_g_per_g_glucose']
    
    # Apply factors
    yield_factor = 1.0
    bottlenecks = []
    warnings = []
    
    # Missing enzymes — severe penalty
    if missing:
        yield_factor *= max(0.05, 1.0 - len(missing) / max(1, len(required)) * 0.85)
        bottlenecks.append('Missing {} required enzyme(s)'.format(len(missing)))
    
    # Bonus for added enzymes from the product pathway
    pathway_enzymes_added = sum(1 for e in added_enzymes
                                  if METABOLIC_ENZYMES.get(e, {}).get('effect') == 'product_' + product_key)
    if pathway_enzymes_added > 0:
        yield_factor *= (1.0 + 0.1 * pathway_enzymes_added)
    
    # Knockout of competing pathways — bonus
    competing_ko = sum(1 for e in knocked_out
                        if METABOLIC_ENZYMES.get(e, {}).get('effect') == 'knockout_competing')
    if competing_ko > 0:
        yield_factor *= (1.0 + 0.15 * competing_ko)
    else:
        if not missing:  # Only suggest if pathway is otherwise complete
            warnings.append('Knock out competing pathways for higher yield (pflB, ackA, adhE)')
    
    # Organism suitability
    if organism_key not in prod['native_in']:
        yield_factor *= 0.6  # heterologous expression is less efficient
        warnings.append('Heterologous production — 60% efficiency')
    
    # Glycolysis flux enzymes — increase substrate uptake
    glyc_boost = sum(1 for e in added_enzymes
                      if METABOLIC_ENZYMES.get(e, {}).get('effect') == 'flux_glycolysis')
    if glyc_boost > 0:
        yield_factor *= (1.0 + 0.05 * glyc_boost)
    
    # Final yield
    final_yield = base_yield * yield_factor
    # Production rate (g per hour) at given substrate uptake
    rate = final_yield * substrate_g_per_h * org['growth_rate']
    
    # Suggestions
    if missing:
        bottlenecks.extend(['Add: ' + e for e in missing])
    
    return {
        'yield_g_per_g': round(final_yield, 3),
        'theoretical_max': base_yield,
        'rate_g_per_h': round(rate, 2),
        'missing_enzymes': sorted(missing),
        'bottlenecks': bottlenecks,
        'warnings': warnings,
        'pathway_completeness': round(100.0 * (len(required) - len(missing)) / max(1, len(required)), 0),
    }


