def simulate_disease_effect(circuit_state, disease_key):
    """Simulate the effect of a synthetic biology circuit on a disease.

    Returns a dict:
      - therapeutic_score: 0..100 (how well it treats the disease)
      - direct_effect_ru/en: description of direct effect
      - side_effects: list of side effects with severity
      - warnings: list of warnings (overdose, toxicity, etc.)
      - produced_proteins: list of (gene_name, level) produced
    """
    disease = DISEASE_DATABASE.get(disease_key, DISEASE_DATABASE['none'])

    # Identify all genes produced by this circuit
    # A gene is "produced" if it's a CDS or protein with an assigned gene_symbol
    produced_genes = []
    for node in circuit_state.get('nodes', []):
        gsym = node.get('gene_symbol')
        if gsym:
            # Estimate production level (rough heuristic):
            # production rate × concentration × chain context
            base_level = node.get('production', 1.0) * circuit_state.get('init', {}).get(node['id'], 0.5)
            # If part of a chain (transcription unit), boost it
            for chain in circuit_state.get('chains', []):
                if node['id'] in chain:
                    # Check if chain has a promoter
                    chain_nodes_data = [
                        next((n for n in circuit_state['nodes'] if n['id'] == nid), None)
                        for nid in chain]
                    chain_nodes_data = [n for n in chain_nodes_data if n is not None]
                    has_promoter = any(n.get('icon') == 'promoter' for n in chain_nodes_data)
                    has_rbs = any(n.get('icon') == 'rbs' for n in chain_nodes_data)
                    has_term = any(n.get('icon') == 'terminator' for n in chain_nodes_data)
                    if has_promoter:
                        base_level *= 2.5
                    if has_rbs:
                        base_level *= 1.8
                    if has_term:
                        base_level *= 1.2  # terminator improves transcript stability
                    break
            produced_genes.append((gsym, round(base_level, 2)))

    # Score how well the circuit treats the disease
    therapeutic_score = 0
    warnings = []
    side_effects = []
    direct_effects_ru = []
    direct_effects_en = []

    if disease_key == 'none':
        # Healthy organism — circuit just adds metabolic load
        if produced_genes:
            direct_effects_ru.append('Здоровый организм. Схема добавляет метаболическую нагрузку.')
            direct_effects_en.append('Healthy organism. Circuit adds metabolic load.')
            if len(produced_genes) > 3:
                warnings.append({
                    'severity': 'medium',
                    'msg_ru': 'Слишком много экспрессии — может вызвать стресс клетки',
                    'msg_en': 'Too much expression — may cause cellular stress',
                })
        return {
            'therapeutic_score': 0,
            'direct_effects_ru': direct_effects_ru,
            'direct_effects_en': direct_effects_en,
            'side_effects': side_effects,
            'warnings': warnings,
            'produced_proteins': produced_genes,
            'disease_name_ru': disease['name_ru'],
            'disease_name_en': disease['name_en'],
        }

    therapeutic_set = set(g.upper() for g in disease['therapeutic_genes'])
    mutated_set = set(g.upper() for g in disease['mutated_genes'])
    overexp_set = set(g.upper() for g in disease['overexpression_dangerous'])
    underexp_set = set(g.upper() for g in disease['underexpression_dangerous'])

    for gname, level in produced_genes:
        gupper = gname.upper()
        # Therapeutic match
        match = None
        for tgene in therapeutic_set:
            if tgene in gupper or gupper in tgene:
                match = tgene
                break
        if match:
            # Score depends on level
            if level < 0.3:
                gain = 10
                direct_effects_ru.append(
                    '{} производится в малом количестве (уровень {:.2f}). Слабый эффект.'.format(gname, level))
                direct_effects_en.append(
                    '{} produced at low level ({:.2f}). Weak effect.'.format(gname, level))
            elif level < 2.0:
                gain = 35
                direct_effects_ru.append(
                    '{} производится в нормальном количестве (уровень {:.2f}). Хороший терапевтический эффект.'.format(gname, level))
                direct_effects_en.append(
                    '{} produced at therapeutic level ({:.2f}). Good therapeutic effect.'.format(gname, level))
            elif level < 5.0:
                gain = 40
                direct_effects_ru.append(
                    '{} в высокой концентрации ({:.2f}). Сильный эффект.'.format(gname, level))
                direct_effects_en.append(
                    '{} at high concentration ({:.2f}). Strong effect.'.format(gname, level))
            else:
                gain = 25  # too much can be bad
                direct_effects_ru.append(
                    '{} в очень высокой концентрации ({:.2f}). Эффект сильный, но риск побочки.'.format(gname, level))
                direct_effects_en.append(
                    '{} at very high concentration ({:.2f}). Strong but risky.'.format(gname, level))
                warnings.append({
                    'severity': 'medium',
                    'msg_ru': 'Слишком высокая экспрессия {} — повышает риск побочных эффектов'.format(gname),
                    'msg_en': 'Excessive {} expression — increased side effect risk'.format(gname),
                })
            therapeutic_score += gain

        # Dangerous overexpression check (only count once per gene)
        already_warned_overexp = False
        for dgene in overexp_set:
            if already_warned_overexp:
                break
            if dgene in gupper or gupper in dgene:
                already_warned_overexp = True
                # Only deduct heavily if the gene is overexpression-dangerous AND not therapeutic.
                # If it is therapeutic, overexpression should only add a warning, not flip the score negative.
                is_therapeutic = match is not None
                if level > 3.0:
                    severity_msg = 'ОПАСНО: гиперэкспрессия {} ({:.2f})'.format(gname, level)
                    severity_msg_en = 'DANGEROUS: {} overexpression ({:.2f})'.format(gname, level)
                    if not is_therapeutic:
                        severity_msg += ' — может ухудшить болезнь!'
                        severity_msg_en += ' may worsen disease!'
                        therapeutic_score -= 30
                    else:
                        severity_msg += ' — терапевтический, но в избытке опасен'
                        severity_msg_en += ' — therapeutic but dangerous in excess'
                        therapeutic_score -= 15  # smaller penalty since it does help
                    warnings.append({
                        'severity': 'high',
                        'msg_ru': severity_msg,
                        'msg_en': severity_msg_en,
                    })
                elif level > 1.5:
                    warnings.append({
                        'severity': 'medium',
                        'msg_ru': '{} в повышенной концентрации — нужна осторожность'.format(gname),
                        'msg_en': '{} elevated — caution required'.format(gname),
                    })
                    if not is_therapeutic:
                        therapeutic_score -= 10

    # Generic side effects from disease database
    for se_label in disease.get('side_effects', [])[:5]:
        side_effects.append({
            'severity': 'low',
            'msg': se_label,
        })

    # No therapeutic genes at all
    if therapeutic_score == 0 and produced_genes:
        direct_effects_ru.append('Произведённые белки не помогают при этой болезни.')
        direct_effects_en.append('Produced proteins do not help with this disease.')
    if not produced_genes:
        direct_effects_ru.append('Схема ничего не производит — нужно привязать гены к CDS.')
        direct_effects_en.append('Circuit produces nothing — assign genes to CDS first.')

    # Cap score
    therapeutic_score = max(-50, min(100, therapeutic_score))

    return {
        'therapeutic_score': therapeutic_score,
        'direct_effects_ru': direct_effects_ru,
        'direct_effects_en': direct_effects_en,
        'side_effects': side_effects,
        'warnings': warnings,
        'produced_proteins': produced_genes,
        'disease_name_ru': disease['name_ru'],
        'disease_name_en': disease['name_en'],
    }


# ─────────────────────────────────────────────────
# ADVANCED ANALYSIS FUNCTIONS (Category B from plan)
# ─────────────────────────────────────────────────

def _build_circuit_ode_system(nodes, edges, init_dict):
    """Build right-hand side function dy/dt = f(t, y) for the circuit.
    Returns (rhs_func, node_ids, y0_array) where y0 is initial concentrations.
    Hill equation for activation/repression edges.
    Input nodes (step/impulse/wave/etc.) are driven as functions of time.
    """
    if not nodes:
        return None, [], None
    node_ids = [n['id'] for n in nodes]
    n_nodes = len(node_ids)
    idx_map = {nid: i for i, nid in enumerate(node_ids)}
    # Pre-extract parameters. An RBS or terminator sitting next to a gene is a
    # modifier, not a species of its own: its measured strength scales the
    # partner gene's production. Without this the measured numbers would be
    # displayed but never enter the dynamics — exactly the kind of decorative
    # figure this project has been removing.
    prod = np.array([float(n.get('production', 1.0)) for n in nodes])
    deg = np.array([max(0.001, float(n.get('degradation', 0.1))) for n in nodes])
    # Type-specific attributes (set in the node properties dialog) feed the
    # dynamics so that editing them actually changes the simulation result:
    #   • promoter 'strength'  → overrides basal production of that promoter
    #   • promoter 'leakage'   → adds a small constant floor to production
    #   • RBS 'strength'       → scales the production of the gene it sits next to
    for i, n in enumerate(nodes):
        icon = n.get('icon', '')
        if icon == 'promoter':
            if 'strength' in n:
                prod[i] = float(n.get('strength', prod[i]))
            if 'leakage' in n:
                prod[i] = max(prod[i], float(n.get('leakage', 0.0)))
    # RBS strength scales neighbouring gene production (RBS is a modifier)
    _idx_tmp = {n['id']: i for i, n in enumerate(nodes)}
    for n in nodes:
        if n.get('icon') == 'rbs' and 'strength' in n:
            rbs_s = float(n.get('strength', 1.0))
            for e in edges:
                partner = None
                if e.get('from') == n['id']:
                    partner = e.get('to')
                elif e.get('to') == n['id']:
                    partner = e.get('from')
                if partner in _idx_tmp:
                    prod[_idx_tmp[partner]] *= max(0.0, rbs_s)
    for n in nodes:
        icon = n.get('icon')
        tr = n.get('translation_rate')
        te = n.get('termination_efficiency')
        if tr is None and te is None:
            continue
        # apply to every gene this modifier connects to
        for e in edges:
            partner = None
            if e.get('from') == n['id']:
                partner = e.get('to')
            elif e.get('to') == n['id']:
                partner = e.get('from')
            if partner in idx_map:
                pi = idx_map[partner]
                if tr is not None:
                    prod[pi] *= max(0.0, float(tr))
                if te is not None:
                    # a terminator lets through (1 - efficiency) of transcription
                    prod[pi] *= max(0.0, 1.0 - float(te))

    # Identify knockout marker nodes (∅). Any protein connected INTO a knockout
    # marker (protein → ∅) gets eliminated (driven to zero).
    knockout_marker_ids = set()
    for n in nodes:
        if n.get('part_key') == 'knockout_marker' or n.get('icon') == 'knockout' \
                or n.get('part_type') == 'knockout_marker' \
                or n.get('part_key') == 'knockout_protein' or n.get('is_knockout'):
            knockout_marker_ids.add(n['id'])
    knocked_out_idx = set()
    for e in edges:
        # protein → knockout_marker  means that protein is knocked out
        if e.get('to') in knockout_marker_ids and e.get('from') in idx_map:
            knocked_out_idx.add(idx_map[e['from']])
        # also support marker → protein direction for convenience
        if e.get('from') in knockout_marker_ids and e.get('to') in idx_map:
            knocked_out_idx.add(idx_map[e['to']])

    # Identify input-signal nodes — these are DRIVEN (set by a time function),
    # not governed by normal production/degradation.
    input_nodes = {}  # idx -> input_type
    for i, n in enumerate(nodes):
        itype = n.get('input_type')
        if itype:
            input_nodes[i] = {
                'type': itype,
                'amplitude': float(n.get('production', 1.0)) or 1.0,
                't_on': float(n.get('t_on', 20.0)),
                'period': float(n.get('period', 25.0)),
            }

    def input_signal(itype, params, t):
        """Compute value of an input signal at time t."""
        A = params['amplitude']
        t_on = params['t_on']
        period = params['period']
        if itype == 'step_input':
            return A if t >= t_on else 0.0
        elif itype == 'inv_step_input':
            return A if t < t_on else 0.0
        elif itype == 'impulse':
            return A if abs(t - t_on) < (period * 0.05 + 1.0) else 0.0
        elif itype == 'wave_input':
            return A * 0.5 * (1.0 + math.sin(2 * math.pi * t / max(1.0, period)))
        elif itype in ('global_param', 'new_event'):
            return A  # constant
        return A

    # Build edge list with parameters
    edge_list = []
    for e in edges:
        if e['from'] not in idx_map or e['to'] not in idx_map:
            continue
        edge_list.append({
            'from_idx': idx_map[e['from']],
            'to_idx': idx_map[e['to']],
            'type': e.get('type', 'activation'),
            'reaction': e.get('reaction', e.get('type', 'activation')),
            'strength': float(e.get('strength', 3.0)),
            'hill_n': float(e.get('hill_n', 2)),
            # Optional per-edge Hill half-threshold. When given, the activation/
            # repression Hill uses THIS value instead of the global K=1.0, so a
            # circuit can switch at, say, Y≈27 rather than Y≈1. Omitted → old
            # behaviour (K=1.0) is preserved exactly.
            'K': (float(e['K']) if e.get('K') is not None else None),
            # Kinetic parameters (biochemistry). Fall back to sensible defaults.
            'k': float(e.get('k', e.get('rate', 1.0))),        # mass-action rate
            'kcat': float(e.get('kcat', 1.0)),                  # enzyme turnover
            'km': float(e.get('km', 1.0)),                      # Michaelis constant
            'kf': float(e.get('kf', e.get('k', 1.0))),          # forward
            'kr': float(e.get('kr', 0.1)),                      # reverse
            'reversible': bool(e.get('reversible', False)),
            'custom_rate': e.get('custom_rate') or None,        # user formula (str)
            'enzyme_idx': idx_map.get(e.get('enzyme')) if e.get('enzyme') in idx_map else None,
        })

    # Detect whether the circuit is a repressor ring (e.g. repressilator).
    # Such topologies need a transcription→translation DELAY to oscillate.
    # We add a hidden mRNA layer ONLY when a pure repression cycle is present,
    # so existing toggle/activation behavior stays exactly the same.
    def _has_repression_cycle():
        # Build adjacency of repression edges
        rep_adj = {}
        for e in edge_list:
            if e['type'] == 'repression':
                rep_adj.setdefault(e['from_idx'], []).append(e['to_idx'])
        # DFS to find a cycle of length >= 3 using only repression edges
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {}
        def dfs(u, depth):
            color[u] = GRAY
            for v in rep_adj.get(u, []):
                if color.get(v, WHITE) == GRAY and depth >= 2:
                    return True
                if color.get(v, WHITE) == WHITE:
                    if dfs(v, depth + 1):
                        return True
            color[u] = BLACK
            return False
        for node in list(rep_adj.keys()):
            color = {}
            if dfs(node, 0):
                return True
        return False

    use_mrna = _has_repression_cycle()
    # mRNA maturation rate (1/delay). Lower = more delay = stronger oscillation.
    mrna_rate = 1.0

    def rhs(t, y):
        # For each node, compute its production from regulators
        # plus its degradation
        K = 1.0  # half-saturation constant
        # Start with basal production
        prod_rates = prod.copy()
        # Track knockout targets — these are forced toward zero
        knockout_targets = set(knocked_out_idx)  # node-based knockouts (∅ blocks)
        # When using the mRNA layer, the second half of y holds mRNA levels
        if use_mrna:
            protein = y[:n_nodes]
            mrna = y[n_nodes:2*n_nodes]
        else:
            protein = y
        # Apply edges
        # flux[i] accumulates net rate of change from biochemical reactions
        # (mass-action, Michaelis-Menten, binding, etc.) — these are TRUE
        # material flows that consume substrate and produce product, on top of
        # the regulatory (Hill) modulation of production handled below.
        flux = np.zeros(n_nodes)
        # Safe evaluation environment for custom rate laws
        def _eval_custom(expr, s, p):
            try:
                env = {'S': s, 'P': p, 's': s, 'p': p,
                       't': t, 'time': t,
                       'sin': math.sin, 'cos': math.cos, 'exp': math.exp,
                       'sqrt': math.sqrt, 'log': math.log, 'pow': pow,
                       'pi': math.pi}
                return float(eval(expr, {'__builtins__': {}}, env))
            except Exception:
                return 0.0

        for e in edge_list:
            src_y = max(0.0, protein[e['from_idx']])
            tgt = e['to_idx']
            src = e['from_idx']
            n_hill = e['hill_n']
            rxn = e.get('reaction', e['type'])

            # 1) Custom user-supplied rate law takes precedence for this edge
            if e.get('custom_rate'):
                v = _eval_custom(e['custom_rate'], src_y, max(0.0, protein[tgt]))
                flux[src] -= v
                flux[tgt] += v
                continue

            # 2) Regulatory edges modulate the TARGET's production (Hill)
            # Per-edge threshold K_e (defaults to the global K=1.0 when unset).
            K_e = e['K'] if e.get('K') is not None else K
            if e['type'] == 'activation' and rxn in ('activation', 'transcription',
                                                      'translation', 'production',
                                                      'direct_gene_regulation'):
                hill = (src_y ** n_hill) / (K_e ** n_hill + src_y ** n_hill + 1e-12)
                prod_rates[tgt] *= (1.0 + e['strength'] * hill)
                continue
            elif e['type'] == 'repression' or rxn == 'repression':
                leak = 0.02
                # With an explicit threshold, repress when src is ABOVE K_e
                # (half-max exactly at src = K_e); without one, keep the old
                # strength-scaled form so existing circuits are unchanged.
                if e.get('K') is not None:
                    hill = (K_e ** n_hill) / (K_e ** n_hill + src_y ** n_hill + 1e-12)
                else:
                    eff_src = e['strength'] * src_y
                    hill = (K ** n_hill) / (K ** n_hill + eff_src ** n_hill + 1e-12)
                prod_rates[tgt] *= (leak + (1.0 - leak) * hill)
                continue
            elif e['type'] == 'knockout' or rxn == 'knockout':
                knockout_targets.add(tgt)
                prod_rates[tgt] = 0.0
                continue

            # 3) True biochemical reactions — material flows S → P
            tgt_y = max(0.0, protein[tgt])
            if rxn in ('catalysis',):
                # Michaelis-Menten: v = kcat*[E]*[S]/(Km+[S]).
                # Enzyme = the edge source acts catalytically (not consumed);
                # substrate/product handled via a dedicated enzyme_idx if given.
                E = src_y
                S = tgt_y
                v = e['kcat'] * E * S / (e['km'] + S + 1e-12)
                # substrate consumed, product... in a simple 1-substrate view the
                # target IS the substrate being converted, so it decreases:
                flux[tgt] -= v
                continue
            elif rxn in ('conversion', 'transport', 'diffusion', 'secretion',
                          'cleavage', 'phosphorylation', 'dephosphorylation'):
                # Mass-action conversion S → P: v = k*[S]
                v = e['k'] * src_y
                if e.get('reversible'):
                    v -= e['kr'] * tgt_y
                flux[src] -= v
                flux[tgt] += v
                continue
            elif rxn in ('binding', 'complex_formation'):
                # A + B → complex; here treated as target accumulates, source
                # consumed proportionally to product of concentrations.
                v = e['kf'] * src_y * tgt_y
                if e.get('reversible'):
                    v -= e['kr'] * tgt_y
                flux[src] -= v
                flux[tgt] += v * 0.0  # complex node (if any) handled separately
                continue
            elif rxn in ('dissociation',):
                v = e['kf'] * src_y
                flux[src] -= v
                flux[tgt] += v
                continue
            elif rxn in ('degradation',):
                # extra degradation channel driven by source (e.g. protease)
                v = e['k'] * src_y
                flux[src] -= v
                continue
            else:
                # Unknown reaction: default to gentle activation so the edge
                # still "does something" rather than being silently ignored.
                hill = (src_y ** n_hill) / (K ** n_hill + src_y ** n_hill + 1e-12)
                prod_rates[tgt] *= (1.0 + e['strength'] * hill)
        # Zero out production for all knockout targets
        for tgt in knockout_targets:
            prod_rates[tgt] = 0.0

        if use_mrna:
            # Two-step: production drives mRNA; mRNA is translated to protein.
            # This delay is what enables sustained oscillations (repressilator).
            dmrna = prod_rates - mrna_rate * mrna
            dprot = mrna_rate * mrna - deg * protein + flux
            # Knockouts force both mRNA and protein to zero
            for tgt in knockout_targets:
                dprot[tgt] = -5.0 * protein[tgt]
                dmrna[tgt] = -5.0 * mrna[tgt]
            # Input nodes drive protein directly
            for i, params in input_nodes.items():
                target = input_signal(params['type'], params, t)
                dprot[i] = 10.0 * (target - protein[i])
                dmrna[i] = 0.0
            return np.concatenate([dprot, dmrna])
        else:
            dydt = prod_rates - deg * y + flux
            # Force knockout targets to disappear (strong negative drive to 0)
            for tgt in knockout_targets:
                dydt[tgt] = -5.0 * y[tgt]  # rapid decay to zero
            # Override input nodes: drive them toward their signal value
            for i, params in input_nodes.items():
                target = input_signal(params['type'], params, t)
                dydt[i] = 10.0 * (target - y[i])  # fast relaxation to signal value
            return dydt

    y0 = np.array([float(init_dict.get(nid, 0.5)) for nid in node_ids])
    # Inputs start at their t=0 signal value
    for i, params in input_nodes.items():
        y0[i] = input_signal(params['type'], params, 0.0)
    if use_mrna:
        # Extend state with mRNA initial values (start at protein level)
        y0 = np.concatenate([y0, y0.copy()])
    return rhs, node_ids, y0


def run_ode_simulation(nodes, edges, init_dict, t_end=100, events=None):
    """Run ODE simulation. Returns (t_array, y_array, node_ids) or (None, None, []) on failure.

    events: optional list of dicts {'trigger': 'A > 5', 'action': 'B = 0',
    'once': True}. Triggers are evaluated at each output step against current
    species values; when true, the action assignment is applied to the state.
    This implements TinkerCell-style discrete events."""
    rhs, node_ids, y0 = _build_circuit_ode_system(nodes, edges, init_dict)
    if rhs is None:
        return None, None, []
    try:
        from scipy.integrate import solve_ivp
        n = len(node_ids)
        # No events → single fast integration
        if not events:
            sol = solve_ivp(rhs, (0, t_end), y0, method='RK45', dense_output=False,
                             t_eval=np.linspace(0, t_end, 200), rtol=1e-4, atol=1e-6)
            if not sol.success:
                return None, None, node_ids
            y = sol.y.T
            if y.shape[1] > n:
                y = y[:, :n]
            return sol.t, y, node_ids

        # With events: integrate step-by-step so we can apply discrete changes
        idx = {nid: i for i, nid in enumerate(node_ids)}
        n_steps = 200
        t_grid = np.linspace(0, t_end, n_steps)
        y_out = np.zeros((n_steps, len(y0)))
        y_cur = np.array(y0, dtype=float)
        y_out[0] = y_cur
        fired = [False] * len(events)

        def _species_env(yv):
            env = {nid: float(yv[idx[nid]]) for nid in node_ids}
            env.update({'sin': math.sin, 'cos': math.cos, 'exp': math.exp,
                        'sqrt': math.sqrt, 'abs': abs, 'pi': math.pi})
            return env

        for k in range(1, n_steps):
            seg = solve_ivp(rhs, (t_grid[k - 1], t_grid[k]), y_cur,
                             method='RK45', rtol=1e-4, atol=1e-6)
            if not seg.success:
                return None, None, node_ids
            y_cur = seg.y[:, -1].copy()
            # Evaluate events at this time point
            env = _species_env(y_cur)
            env['t'] = t_grid[k]
            for ei, ev in enumerate(events):
                trig = ev.get('trigger', '')
                if not trig:
                    continue
                if ev.get('once', True) and fired[ei]:
                    continue
                try:
                    if bool(eval(trig, {'__builtins__': {}}, env)):
                        action = ev.get('action', '')
                        # action like "B = 0" or "B = A*2"
                        if '=' in action:
                            lhs, rhs_expr = action.split('=', 1)
                            lhs = lhs.strip()
                            val = float(eval(rhs_expr, {'__builtins__': {}}, env))
                            if lhs in idx:
                                y_cur[idx[lhs]] = val
                        fired[ei] = True
                except Exception:
                    pass
            y_out[k] = y_cur

        y = y_out
        if y.shape[1] > n:
            y = y[:, :n]
        return t_grid, y, node_ids
    except Exception as _exc:
        biosim_log('warn', 'run_ode_simulation: {}'.format(_exc))
        return None, None, node_ids


def run_gillespie_simulation(nodes, edges, init_dict, t_end=100, max_steps=20000, seed=None):
    """Exact stochastic simulation using Gillespie algorithm.
    Each reaction is a discrete event. Slower but shows noise.
    Returns (t_array, y_array, node_ids).
    
    If seed=None, a fresh seed is generated and tracked by SeedManager.
    If seed is given, it's recorded so the run can be reproduced.
    """
    if not nodes:
        return None, None, []
    # Generate and record seed
    if seed is None:
        seed = SeedManager.get_seed(context='gillespie')
    else:
        SeedManager.use_seed(seed, context='gillespie')
    rng = np.random.default_rng(seed)
    node_ids = [n['id'] for n in nodes]
    n_nodes = len(node_ids)
    idx_map = {nid: i for i, nid in enumerate(node_ids)}
    # Reactions: for each node, [production, degradation] = 2 reactions per node
    # Plus extra reactions for activation/repression scaling already in production
    prod = np.array([float(n.get('production', 1.0)) for n in nodes])
    deg = np.array([max(0.001, float(n.get('degradation', 0.1))) for n in nodes])
    # Scale counts: multiply concentration by a "molecule unit" factor to get integers
    SCALE = 50.0  # 1 unit concentration = 50 molecules
    y = np.array([max(0, int(round(init_dict.get(nid, 0.5) * SCALE))) for nid in node_ids])
    # Record trajectory
    t = 0.0
    t_record = [0.0]
    y_record = [y.copy() / SCALE]
    next_record_t = t_end / 200
    record_step = t_end / 200

    # Pre-extract edges
    edge_arr = []
    for e in edges:
        if e['from'] not in idx_map or e['to'] not in idx_map:
            continue
        edge_arr.append((idx_map[e['from']], idx_map[e['to']],
                          e.get('type', 'activation'),
                          float(e.get('strength', 3.0)),
                          float(e.get('hill_n', 2))))
    K = 1.0
    step_count = 0
    while t < t_end and step_count < max_steps:
        step_count += 1
        # Compute propensities
        # For each node: production_rate and degradation_rate
        prod_rates = prod * SCALE  # in molecules per unit time
        for fi, ti, etype, strength, n_hill in edge_arr:
            src_conc = y[fi] / SCALE
            if etype == 'activation':
                hill = (src_conc ** n_hill) / (K ** n_hill + src_conc ** n_hill + 1e-12)
                prod_rates[ti] *= (1.0 + strength * hill)
            elif etype == 'repression':
                hill = (K ** n_hill) / (K ** n_hill + src_conc ** n_hill + 1e-12)
                prod_rates[ti] *= max(0.05, hill / max(0.01, strength))
        deg_rates = deg * y  # degradation proportional to count
        all_rates = np.concatenate([prod_rates, deg_rates])
        total_rate = float(all_rates.sum())
        if total_rate <= 0:
            break
        # Time to next event (exponential)
        dt = -np.log(rng.random()) / total_rate
        t += dt
        if t > t_end:
            break
        # Pick reaction proportionally
        r = rng.random() * total_rate
        cum = 0.0
        chosen = -1
        for i, rate in enumerate(all_rates):
            cum += rate
            if cum >= r:
                chosen = i
                break
        if chosen < 0:
            break
        if chosen < n_nodes:
            # Production
            y[chosen] += 1
        else:
            # Degradation
            i = chosen - n_nodes
            if y[i] > 0:
                y[i] -= 1
        # Record sometimes
        if t >= next_record_t:
            t_record.append(t)
            y_record.append(y.copy() / SCALE)
            next_record_t += record_step
    # Final record
    if t_record[-1] < t_end:
        t_record.append(t_end)
        y_record.append(y.copy() / SCALE)
    return np.array(t_record), np.array(y_record), node_ids


def run_tau_leap_simulation(nodes, edges, init_dict, t_end=100, tau=0.05, seed=None):
    """Tau-leaping stochastic simulation. Approximate but faster than Gillespie.
    
    If seed=None, fresh seed generated and tracked.
    """
    if not nodes:
        return None, None, []
    if seed is None:
        seed = SeedManager.get_seed(context='tau_leap')
    else:
        SeedManager.use_seed(seed, context='tau_leap')
    rng = np.random.default_rng(seed)
    node_ids = [n['id'] for n in nodes]
    n_nodes = len(node_ids)
    idx_map = {nid: i for i, nid in enumerate(node_ids)}
    prod = np.array([float(n.get('production', 1.0)) for n in nodes])
    deg = np.array([max(0.001, float(n.get('degradation', 0.1))) for n in nodes])
    SCALE = 50.0
    y = np.array([max(0, int(round(init_dict.get(nid, 0.5) * SCALE))) for nid in node_ids],
                  dtype=float)
    edge_arr = []
    for e in edges:
        if e['from'] not in idx_map or e['to'] not in idx_map:
            continue
        edge_arr.append((idx_map[e['from']], idx_map[e['to']],
                          e.get('type', 'activation'),
                          float(e.get('strength', 3.0)),
                          float(e.get('hill_n', 2))))
    K = 1.0
    n_steps = int(t_end / tau) + 1
    t_record = np.linspace(0, t_end, n_steps)
    y_record = np.zeros((n_steps, n_nodes))
    y_record[0] = y / SCALE
    for step in range(1, n_steps):
        # Production rates
        prod_rates = prod * SCALE
        for fi, ti, etype, strength, n_hill in edge_arr:
            src_conc = y[fi] / SCALE
            if etype == 'activation':
                hill = (src_conc ** n_hill) / (K ** n_hill + src_conc ** n_hill + 1e-12)
                prod_rates[ti] *= (1.0 + strength * hill)
            elif etype == 'repression':
                hill = (K ** n_hill) / (K ** n_hill + src_conc ** n_hill + 1e-12)
                prod_rates[ti] *= max(0.05, hill / max(0.01, strength))
        deg_rates = deg * y
        # Number of events in tau via Poisson
        n_prod = rng.poisson(prod_rates * tau)
        n_deg = rng.poisson(deg_rates * tau)
        y = y + n_prod - n_deg
        y = np.maximum(y, 0)
        y_record[step] = y / SCALE
    return t_record, y_record, node_ids


def compute_steady_state(nodes, edges, init_dict):
    """Find steady state by integrating long-time ODE."""
    t, y, ids = run_ode_simulation(nodes, edges, init_dict, t_end=500)
    if t is None:
        return None, ids
    # Steady state = average of last 20%
    n = len(t)
    ss = y[int(n * 0.8):].mean(axis=0)
    return ss, ids


def compute_jacobian_at_ss(nodes, edges, init_dict, epsilon=1e-4):
    """Compute Jacobian matrix J[i,j] = df_i/dy_j at steady state."""
    rhs, node_ids, y0 = _build_circuit_ode_system(nodes, edges, init_dict)
    if rhs is None:
        return None, []
    ss, _ = compute_steady_state(nodes, edges, init_dict)
    if ss is None:
        return None, node_ids
    n = len(ss)
    J = np.zeros((n, n))
    for j in range(n):
        y_plus = ss.copy(); y_plus[j] += epsilon
        y_minus = ss.copy(); y_minus[j] = max(0, y_minus[j] - epsilon)
        f_plus = rhs(0, y_plus)
        f_minus = rhs(0, y_minus)
        J[:, j] = (f_plus - f_minus) / (2 * epsilon)
    return J, node_ids


def compute_eigenvalues(nodes, edges, init_dict):
    """Compute eigenvalues of Jacobian at steady state. Indicates stability."""
    J, ids = compute_jacobian_at_ss(nodes, edges, init_dict)
    if J is None:
        return None, [], ids
    try:
        eigs = np.linalg.eigvals(J)
        return eigs, J, ids
    except Exception as _exc:
        biosim_log('warn', 'compute_eigenvalues: {}'.format(_exc))
        return None, J, ids


def parameter_scan_1d(nodes, edges, init_dict, node_id, param_name, p_min, p_max, n_steps=20, t_end=100):
    """Scan one parameter (production/degradation/initial) for one node.
    Returns dict: { param_value: ss_array } and steady-state for each value.
    """
    import copy
    results = []  # list of (param_value, ss_dict)
    param_values = np.linspace(p_min, p_max, n_steps)
    for pv in param_values:
        # Create modified nodes
        nodes_mod = copy.deepcopy(nodes)
        init_mod = dict(init_dict)
        for n in nodes_mod:
            if n['id'] == node_id:
                if param_name == 'production':
                    n['production'] = pv
                elif param_name == 'degradation':
                    n['degradation'] = max(0.001, pv)
                elif param_name == 'initial':
                    init_mod[node_id] = pv
                break
        ss, ids = compute_steady_state(nodes_mod, edges, init_mod)
        if ss is not None:
            results.append((pv, dict(zip(ids, ss))))
        else:
            results.append((pv, None))
    return results, param_values


def parameter_scan_2d(nodes, edges, init_dict, node_a_id, param_a, node_b_id, param_b,
                       a_min, a_max, b_min, b_max, target_node, n_steps=15, t_end=80):
    """2D parameter scan. Returns 2D array of target_node steady-state."""
    import copy
    a_values = np.linspace(a_min, a_max, n_steps)
    b_values = np.linspace(b_min, b_max, n_steps)
    grid = np.zeros((n_steps, n_steps))
    for i, av in enumerate(a_values):
        for j, bv in enumerate(b_values):
            nodes_mod = copy.deepcopy(nodes)
            init_mod = dict(init_dict)
            for n in nodes_mod:
                if n['id'] == node_a_id:
                    if param_a == 'production':
                        n['production'] = av
                    elif param_a == 'degradation':
                        n['degradation'] = max(0.001, av)
                if n['id'] == node_b_id:
                    if param_b == 'production':
                        n['production'] = bv
                    elif param_b == 'degradation':
                        n['degradation'] = max(0.001, bv)
            ss, ids = compute_steady_state(nodes_mod, edges, init_mod)
            if ss is not None and target_node in ids:
                grid[i, j] = ss[ids.index(target_node)]
    return grid, a_values, b_values


def perturbation_knockouts(nodes, edges, init_dict, t_end=100):
    """Knock out each node and check the effect on others' steady state."""
    import copy
    ss_baseline, ids = compute_steady_state(nodes, edges, init_dict)
    if ss_baseline is None:
        return None, []
    results = []
    for ko_node in ids:
        # Knock out: set production to 0 and initial to 0
        nodes_mod = copy.deepcopy(nodes)
        init_mod = dict(init_dict)
        for n in nodes_mod:
            if n['id'] == ko_node:
                n['production'] = 0.0
                init_mod[ko_node] = 0.0
        ss_ko, _ = compute_steady_state(nodes_mod, edges, init_mod)
        if ss_ko is not None:
            # Effect = change for each other node
            effects = {}
            for i, nid in enumerate(ids):
                if nid != ko_node:
                    delta = ss_ko[i] - ss_baseline[i]
                    rel_change = delta / max(0.01, ss_baseline[i])
                    effects[nid] = (ss_ko[i], rel_change)
            results.append((ko_node, effects))
        else:
            results.append((ko_node, None))
    return results, ids


def metabolic_control_analysis(nodes, edges, init_dict, perturbation=0.05):
    """Metabolic Control Analysis (MCA) — like TinkerCell / PySCeS.

    Computes flux and concentration CONTROL COEFFICIENTS: how much each
    enzyme/gene's rate controls the steady-state level of every species.

    Control coefficient C = (dX/X) / (dp/p)  — fractional response of
    steady-state X to a fractional change in parameter p (production rate).

    Returns (results, ids) where results is a list of dicts:
      {'param_node': id, 'target': id, 'control_coef': value}
    A coefficient near 1 means that node strongly controls the target;
    near 0 means little control. Sum over a pathway ≈ 1 (summation theorem).
    """
    import copy
    ss_base, ids = compute_steady_state(nodes, edges, init_dict)
    if ss_base is None:
        return None, []
    results = []
    for n in nodes:
        nid = n['id']
        base_p = n.get('production', 1.0)
        if base_p <= 0:
            continue
        # Perturb production up and down
        nodes_plus = copy.deepcopy(nodes)
        nodes_minus = copy.deepcopy(nodes)
        for nn in nodes_plus:
            if nn['id'] == nid:
                nn['production'] = base_p * (1 + perturbation)
        for nn in nodes_minus:
            if nn['id'] == nid:
                nn['production'] = base_p * (1 - perturbation)
        ss_plus, _ = compute_steady_state(nodes_plus, edges, init_dict)
        ss_minus, _ = compute_steady_state(nodes_minus, edges, init_dict)
        if ss_plus is None or ss_minus is None:
            continue
        for i, tid in enumerate(ids):
            x_base = max(1e-6, ss_base[i])
            # Central-difference fractional response
            dx = (ss_plus[i] - ss_minus[i]) / x_base
            dp = 2 * perturbation
            cc = dx / dp
            results.append({'param_node': nid, 'target': tid,
                            'control_coef': float(cc)})
    return results, ids


def elasticity_coefficients(nodes, edges, init_dict, perturbation=0.05):
    """Elasticity coefficients — local sensitivity of each reaction rate to
    substrate concentration. ε = (dv/v)/(ds/s). Complements MCA.

    Returns list of dicts {'node': id, 'elasticity': value}.
    """
    import copy
    ss_base, ids = compute_steady_state(nodes, edges, init_dict)
    if ss_base is None:
        return None, []
    out = []
    idx = {nid: i for i, nid in enumerate(ids)}
    for n in nodes:
        nid = n['id']
        deg = n.get('degradation', 0.1)
        x = max(1e-6, ss_base[idx[nid]])
        # Rate of removal v = deg * x; elasticity wrt own concentration ~ 1
        # for linear degradation. For regulated production, estimate numerically.
        init_plus = dict(init_dict)
        init_plus[nid] = x * (1 + perturbation)
        ss_p, _ = compute_steady_state(nodes, edges, init_plus)
        if ss_p is None:
            continue
        v_base = deg * x
        v_new = deg * max(1e-6, ss_p[idx[nid]])
        eps = ((v_new - v_base) / max(1e-9, v_base)) / perturbation
        out.append({'node': nid, 'elasticity': float(eps)})
    return out


def conservation_analysis(nodes, edges):
    """Find conserved moieties (conservation laws) in the network.

    A conserved moiety is a combination of species whose total stays
    constant (e.g. enzyme + enzyme-substrate complex). Uses the null space
    of the transpose of the stoichiometry matrix.

    Returns list of conservation relations as readable strings.
    """
    try:
        N, node_ids, edge_labels = build_stoichiometry_matrix(nodes, edges)
        if N is None or N.size == 0:
            return []
        import numpy as _np
        # Conservation laws live in the left null space of N (null space of N^T)
        u, s, vh = _np.linalg.svd(N.T)
        tol = max(N.shape) * _np.finfo(float).eps * (s[0] if len(s) else 1)
        rank = int((s > tol).sum())
        left_null = u[:, rank:] if rank < u.shape[0] else _np.empty((u.shape[0], 0))
        laws = []
        for col in range(left_null.shape[1]):
            vec = left_null[:, col]
            # Normalize and round
            vec = vec / (_np.abs(vec[_np.abs(vec) > 1e-6][0]) if _np.any(_np.abs(vec) > 1e-6) else 1)
            terms = []
            for i, nid in enumerate(node_ids):
                c = vec[i]
                if abs(c) > 1e-6:
                    sign = '+' if c > 0 else '-'
                    coef = '' if abs(abs(c) - 1) < 1e-3 else f'{abs(c):.2f}·'
                    terms.append(f'{sign} {coef}{nid}')
            if terms:
                expr = ' '.join(terms).lstrip('+ ').strip()
                laws.append(expr + ' = const')
        return laws
    except Exception as _exc:
        biosim_log('warn', 'conservation_analysis: {}'.format(_exc))
        return []


def sensitivity_analysis(nodes, edges, init_dict, perturbation=0.1):
    """Compute local sensitivity: how target node SS changes when each parameter changes ±10%."""
    import copy
    ss_baseline, ids = compute_steady_state(nodes, edges, init_dict)
    if ss_baseline is None:
        return None, []
    sensitivities = []  # list of (param_name, target_id, sensitivity)
    for n in nodes:
        for param in ['production', 'degradation']:
            # +perturbation%
            nodes_plus = copy.deepcopy(nodes)
            nodes_minus = copy.deepcopy(nodes)
            for np_node in nodes_plus:
                if np_node['id'] == n['id']:
                    base_val = np_node.get(param, 1.0 if param == 'production' else 0.1)
                    np_node[param] = base_val * (1 + perturbation)
                    break
            for nm_node in nodes_minus:
                if nm_node['id'] == n['id']:
                    base_val = nm_node.get(param, 1.0 if param == 'production' else 0.1)
                    nm_node[param] = max(0.001, base_val * (1 - perturbation))
                    break
            ss_plus, _ = compute_steady_state(nodes_plus, edges, init_dict)
            ss_minus, _ = compute_steady_state(nodes_minus, edges, init_dict)
            if ss_plus is None or ss_minus is None:
                continue
            # Sensitivity = (ss_plus - ss_minus) / (2 * perturbation_fraction * ss_baseline)
            for i, target_id in enumerate(ids):
                denom = 2 * perturbation * max(0.01, ss_baseline[i])
                sens = (ss_plus[i] - ss_minus[i]) / denom
                sensitivities.append((n['id'], param, target_id, sens))
    return sensitivities, ids


def monte_carlo_random_params(nodes, edges, init_dict, n_samples=100, variation=0.5):
    """Random parameter Monte Carlo. Returns SS distribution for each node."""
    import copy
    rng = np.random.default_rng()
    # Get baseline ids
    _, ids = compute_steady_state(nodes, edges, init_dict)
    if not ids:
        return None, []
    n_nodes = len(ids)
    distributions = {nid: [] for nid in ids}
    for s in range(n_samples):
        nodes_mod = copy.deepcopy(nodes)
        for n in nodes_mod:
            # Vary production and degradation
            base_p = n.get('production', 1.0)
            base_d = n.get('degradation', 0.1)
            n['production'] = base_p * rng.uniform(1 - variation, 1 + variation)
            n['degradation'] = max(0.001, base_d * rng.uniform(1 - variation, 1 + variation))
        ss, _ = compute_steady_state(nodes_mod, edges, init_dict)
        if ss is not None:
            for i, nid in enumerate(ids):
                distributions[nid].append(float(ss[i]))
    return distributions, ids


def build_stoichiometry_matrix(nodes, edges):
    """Build simple stoichiometry matrix: N[i, j] for nodes×edges.
    +1 if edge produces node, -1 if consumes."""
    node_ids = [n['id'] for n in nodes]
    n_n = len(node_ids)
    n_e = len(edges)
    N = np.zeros((n_n, n_e))
    idx_map = {nid: i for i, nid in enumerate(node_ids)}
    for j, e in enumerate(edges):
        if e['from'] in idx_map:
            # Activation: source positively affects target (acts as catalyst, not consumed)
            # Repression: same source not consumed
            pass
        if e['to'] in idx_map:
            # Target produced or repressed
            if e.get('type') == 'activation':
                N[idx_map[e['to']], j] = 1
            elif e.get('type') == 'repression':
                N[idx_map[e['to']], j] = -1
            elif e.get('reaction') == 'conversion':
                N[idx_map[e['to']], j] = 1
                if e['from'] in idx_map:
                    N[idx_map[e['from']], j] = -1
    return N, node_ids


def compute_centrality(nodes, edges):
    """Compute degree centrality for each node."""
    node_ids = [n['id'] for n in nodes]
    in_deg = {nid: 0 for nid in node_ids}
    out_deg = {nid: 0 for nid in node_ids}
    for e in edges:
        if e['from'] in out_deg: out_deg[e['from']] += 1
        if e['to'] in in_deg: in_deg[e['to']] += 1
    total = {nid: in_deg.get(nid, 0) + out_deg.get(nid, 0) for nid in node_ids}
    return {'in_degree': in_deg, 'out_degree': out_deg, 'total_degree': total}


def generate_ode_equations_text(nodes, edges, lang='ru'):
    """Generate text representation of ODE equations (Hill form)."""
    lines = []
    title = 'Сгенерированные уравнения (Hill):' if lang == 'ru' else 'Generated equations (Hill):'
    lines.append(title)
    lines.append('-' * 50)
    if not nodes:
        lines.append('  (схема пуста)' if lang == 'ru' else '  (empty)')
        return '\n'.join(lines)
    node_ids = [n['id'] for n in nodes]
    for n in nodes:
        nid = n['id']
        prod = n.get('production', 1.0)
        deg = n.get('degradation', 0.1)
        # Find incoming edges
        in_edges = [e for e in edges if e['to'] == nid]
        prod_terms = ['{:.2f}'.format(prod)]
        for e in in_edges:
            src = e['from']
            strength = e.get('strength', 3.0)
            hill_n = e.get('hill_n', 2)
            if e.get('type') == 'activation':
                prod_terms.append('(1 + {:.2f}·{}^{}/(1+{}^{}))'.format(strength, src, hill_n, src, hill_n))
            elif e.get('type') == 'repression':
                prod_terms.append('1/(1+{}^{}·{:.2f})'.format(src, hill_n, strength))
        rhs_text = ' · '.join(prod_terms) + ' - {:.3f}·{}'.format(deg, nid)
        lines.append('  d{}/dt = {}'.format(nid, rhs_text))
    return '\n'.join(lines)


# ─────────────────────────────────────────────────
# FBA — FLUX BALANCE ANALYSIS (uses cobra)
# ─────────────────────────────────────────────────

def run_fba_on_model(model):
    """Run FBA optimization on a cobra Model. Returns (solution, fluxes_dict, info).
    `model` is a cobra.Model object."""
    if not _ensure_cobra():
        return None, None, 'cobra library not installed'
    try:
        sol = model.optimize()
        if sol.status != 'optimal':
            return None, None, 'No optimal solution (status: ' + sol.status + ')'
        fluxes = {rxn.id: float(sol.fluxes[rxn.id]) for rxn in model.reactions}
        return sol, fluxes, 'Optimal solution found'
    except Exception as e:
        biosim_log('warn', 'run_fba_on_model: {}'.format(e))
        return None, None, 'FBA error: ' + str(e)[:120]


def build_cobra_model_from_circuit(state, model_name='CircuitModel'):
    """Convert constructor circuit state into a cobra Model for FBA.
    Each node becomes a metabolite; each edge becomes a reaction.
    Adds objective: maximize first "product" or last node."""
    if not _ensure_cobra():
        return None, 'cobra not installed'
    try:
        model = Model(model_name)
        # Add metabolites
        metabolites = {}
        for n in state['nodes']:
            met = Metabolite(n['id'], compartment='c', name=n.get('id'))
            metabolites[n['id']] = met
        model.add_metabolites(list(metabolites.values()))
        # Add reactions
        for i, e in enumerate(state['edges']):
            if e['from'] not in metabolites or e['to'] not in metabolites:
                continue
            rxn = Reaction('r_' + str(i) + '_' + e['from'][:6] + '_to_' + e['to'][:6])
            rxn.lower_bound = 0; rxn.upper_bound = 1000
            stoich = {metabolites[e['from']]: -1, metabolites[e['to']]: 1}
            rxn.add_metabolites(stoich)
            model.add_reactions([rxn])
        # Add exchange reactions for inputs (substrates) and outputs (products)
        for n in state['nodes']:
            pdata = CIRCUIT_PARTS_CATALOG.get(n.get('part_key'), {})
            family = pdata.get('family', '')
            if 'Substrate' in family or 'Inducer' in family:
                rxn = Reaction('EX_' + n['id'])
                rxn.lower_bound = -10; rxn.upper_bound = 1000
                rxn.add_metabolites({metabolites[n['id']]: -1})
                model.add_reactions([rxn])
            elif 'Product' in family or 'Fluorescent' in family:
                rxn = Reaction('EX_' + n['id'])
                rxn.lower_bound = 0; rxn.upper_bound = 1000
                rxn.add_metabolites({metabolites[n['id']]: -1})
                model.add_reactions([rxn])
        # Set objective: maximize sum of product exchanges
        product_rxns = [r for r in model.reactions
                         if r.id.startswith('EX_') and r.upper_bound > 0 and r.lower_bound >= 0]
        if product_rxns:
            model.objective = product_rxns[0].id
        return model, 'OK'
    except Exception as e:
        biosim_log('warn', 'build_cobra_model_from_circuit: {}'.format(e))
        return None, 'Build error: ' + str(e)[:120]


# ─────────────────────────────────────────────────
# SBML — IMPORT/EXPORT (uses python-libsbml)
# ─────────────────────────────────────────────────

def export_circuit_to_sbml(state, filepath):
    """Export the constructor circuit state to an SBML L3V2 file."""
    if not _ensure_libsbml():
        return False, 'libsbml not installed'
    try:
        reader = libsbml.SBMLNamespaces(3, 2)
        doc = libsbml.SBMLDocument(reader)
        model = doc.createModel()
        model.setId('biosim_model')
        model.setName(state.get('name', 'VIREON Model'))
        # Compartment
        comp = model.createCompartment()
        comp.setId('cell')
        comp.setConstant(True)
        comp.setSize(1.0)
        # Species (nodes)
        for n in state['nodes']:
            sp = model.createSpecies()
            sp.setId(n['id'])
            sp.setName(n['id'])
            sp.setCompartment('cell')
            sp.setInitialConcentration(float(state.get('init', {}).get(n['id'], 0.5)))
            sp.setBoundaryCondition(False)
            sp.setHasOnlySubstanceUnits(False)
            sp.setConstant(False)
        # Reactions (edges)
        for i, e in enumerate(state['edges']):
            rxn = model.createReaction()
            rxn.setId('r' + str(i))
            rxn.setReversible(False)
            rxn.setFast(False)
            # Reactant
            sr = rxn.createReactant()
            sr.setSpecies(e['from'])
            sr.setStoichiometry(1)
            sr.setConstant(True)
            # Product
            sp_ref = rxn.createProduct()
            sp_ref.setSpecies(e['to'])
            sp_ref.setStoichiometry(1)
            sp_ref.setConstant(True)
            # Kinetic law: depends on type
            etype = e.get('type', 'activation')
            strength = float(e.get('strength', 3.0))
            hill = int(e.get('hill_n', 2))
            klaw = rxn.createKineticLaw()
            if etype == 'activation':
                formula_text = '{} * {}^{} / (1 + {}^{})'.format(
                    strength, e['from'], hill, e['from'], hill)
            else:  # repression
                formula_text = '{} / (1 + {}^{} * {})'.format(
                    strength, e['from'], hill, strength)
            math_ast = libsbml.parseL3Formula(formula_text)
            if math_ast is not None:
                klaw.setMath(math_ast)
        # Write to file
        writer = libsbml.SBMLWriter()
        writer.writeSBMLToFile(doc, filepath)
        return True, 'Saved to ' + filepath
    except Exception as e:
        biosim_log('warn', 'export_circuit_to_sbml: {}'.format(e))
        return False, 'SBML export error: ' + str(e)[:120]


def import_sbml_to_circuit(filepath):
    """Import SBML file and convert to constructor state.
    Returns (state_dict, message)."""
    if not _ensure_libsbml():
        return None, 'libsbml not installed'
    try:
        reader = libsbml.SBMLReader()
        doc = reader.readSBMLFromFile(filepath)
        if doc.getNumErrors() > 0:
            first_err = doc.getError(0).getMessage() if doc.getNumErrors() > 0 else ''
            return None, 'SBML parse error: ' + first_err[:120]
        model = doc.getModel()
        if model is None:
            return None, 'Empty SBML model'
        # Convert species nodes
        nodes = []
        init_dict = {}
        n_species = model.getNumSpecies()
        # Layout: simple grid
        cols = max(1, int(math.sqrt(n_species)))
        for i in range(n_species):
            sp = model.getSpecies(i)
            sp_id = sp.getId()
            init_conc = sp.getInitialConcentration() if sp.isSetInitialConcentration() else 0.5
            # Heuristic: assign part_key by name pattern
            sid_lower = sp_id.lower()
            if 'mrna' in sid_lower or 'rna' in sid_lower:
                pkey = 'mrna'; icon = 'mrna'; color = '#0550ae'
            elif 'promoter' in sid_lower or sid_lower.startswith('p_'):
                pkey = 'promoter_medium'; icon = 'promoter'; color = '#0969da'
            elif 'enzyme' in sid_lower or 'e_' in sid_lower:
                pkey = 'enzyme'; icon = 'protein_square'; color = '#9a6700'
            elif sid_lower in ('atp', 'adp', 'amp', 'nadh', 'nadph', 'iptg'):
                pkey = 'small_inducer'; icon = 'small_mol'; color = '#8250df'
            else:
                pkey = 'protein_generic'; icon = 'protein_circle'; color = '#57606a'
            row = i // cols; col = i % cols
            x = 100 + col * 90; y = 100 + row * 90
            nodes.append({
                'id': sp_id, 'x': x, 'y': y,
                'part_key': pkey, 'icon': icon, 'color': color,
                'production': 1.0, 'degradation': 0.1,
                'gene_symbol': None, 'sequence': None,
                'imported_from_sbml': True,
            })
            init_dict[sp_id] = float(init_conc)
        # Convert reactions edges
        edges = []
        for i in range(model.getNumReactions()):
            rxn = model.getReaction(i)
            # Take first reactant first product as the simplified edge
            if rxn.getNumReactants() == 0 or rxn.getNumProducts() == 0:
                continue
            src = rxn.getReactant(0).getSpecies()
            tgt = rxn.getProduct(0).getSpecies()
            # Determine type from kinetic law if possible
            edge_type = 'activation'
            edges.append({
                'from': src, 'to': tgt,
                'type': edge_type, 'reaction': 'conversion',
                'strength': 3.0, 'hill_n': 2,
            })
        state = {
            'name': model.getId() or 'Imported model',
            'description': 'Imported from SBML',
            'nodes': nodes, 'edges': edges, 'init': init_dict,
            'chains': [],
        }
        return state, 'Imported {} species, {} reactions'.format(len(nodes), len(edges))
    except Exception as e:
        biosim_log('warn', 'import_sbml_to_circuit: {}'.format(e))
        return None, 'Import error: ' + str(e)[:120]


# ─────────────────────────────────────────────────
# GENBANK LOADER (uses biopython)
# ─────────────────────────────────────────────────

def parse_genbank_to_circuit(filepath):
    """Parse a GenBank file and convert features to circuit state.
    Returns (state_dict, message).
    Recognized feature types: CDS, gene, promoter, terminator, RBS, regulatory.
    """
    if not _ensure_biopython():
        return None, 'biopython not installed'
    try:
        records = list(SeqIO.parse(filepath, 'genbank'))
        if not records:
            return None, 'No records found in GenBank file'
        record = records[0]
        organism = record.annotations.get('organism', 'Unknown')
        nodes = []
        init_dict = {}
        chains = []  # list of lists of node ids per chain
        # Process features
        feature_id = 1
        # Position-based ordering for chain detection
        cds_in_order = []
        for feat in record.features:
            ftype = feat.type.lower()
            if ftype not in ('cds', 'gene', 'promoter', 'terminator', 'rbs',
                              'regulatory', 'misc_feature', 'mat_peptide'):
                continue
            # Get qualifier name
            qualifiers = feat.qualifiers
            name = qualifiers.get('gene', qualifiers.get('product',
                       qualifiers.get('label', ['feat_' + str(feature_id)])))[0]
            name = ''.join(c if c.isalnum() or c == '_' else '_' for c in name)[:16]
            base_name = name
            cnt = 1
            taken = set(n['id'] for n in nodes)
            while name in taken:
                name = base_name + str(cnt); cnt += 1
            # Map type part_key + icon + color
            if ftype == 'cds':
                pkey = 'cds_generic'; icon = 'cds'; color = '#1a7f37'
            elif ftype == 'gene':
                pkey = 'cds_generic'; icon = 'cds'; color = '#1a7f37'
            elif ftype == 'promoter':
                pkey = 'promoter_medium'; icon = 'promoter'; color = '#0969da'
            elif ftype == 'terminator':
                pkey = 'terminator'; icon = 'terminator'; color = '#cf222e'
            elif ftype == 'rbs':
                pkey = 'rbs_strong'; icon = 'rbs'; color = '#bc4c00'
            elif ftype == 'regulatory':
                reg_class = qualifiers.get('regulatory_class', [''])[0].lower()
                if 'promoter' in reg_class:
                    pkey = 'promoter_medium'; icon = 'promoter'; color = '#0969da'
                elif 'terminator' in reg_class:
                    pkey = 'terminator'; icon = 'terminator'; color = '#cf222e'
                elif 'rbs' in reg_class or 'ribosome' in reg_class:
                    pkey = 'rbs_strong'; icon = 'rbs'; color = '#bc4c00'
                else:
                    pkey = 'operator'; icon = 'binding_site'; color = '#8250df'
            else:
                pkey = 'cds_generic'; icon = 'cds'; color = '#0550ae'

            # Position
            start = int(feat.location.start)
            end = int(feat.location.end)
            length = end - start
            # Get DNA sequence
            try:
                seq = str(feat.extract(record.seq))
            except Exception as _exc:
                biosim_log('warn', 'parse_genbank_to_circuit: {}'.format(_exc))
                seq = ''
            # Get protein translation if CDS
            protein_seq = ''
            if ftype == 'cds':
                trans_list = qualifiers.get('translation', [''])
                protein_seq = trans_list[0] if trans_list else ''

            new_node = {
                'id': name,
                'x': 100 + ((feature_id - 1) % 8) * 90,
                'y': 100 + ((feature_id - 1) // 8) * 100,
                'part_key': pkey,
                'icon': icon,
                'color': color,
                'production': 1.0,
                'degradation': 0.1,
                'gene_symbol': name if ftype in ('cds', 'gene') else None,
                'sequence': seq,
                'sequence_length': length,
                'protein_sequence': protein_seq if protein_seq else None,
                'genbank_position': (start, end),
                'genbank_type': ftype,
            }
            nodes.append(new_node)
            init_dict[name] = 0.5
            if ftype in ('promoter', 'rbs', 'cds', 'terminator', 'regulatory'):
                cds_in_order.append((start, name))
            feature_id += 1

        # Sort by position and build a chain
        cds_in_order.sort()
        if len(cds_in_order) >= 2:
            chain = [n for _, n in cds_in_order]
            chains.append(chain)
            # Also realign x coords for chain members
            x0, y0 = 100, 200
            for i, nid in enumerate(chain):
                for n in nodes:
                    if n['id'] == nid:
                        n['x'] = x0 + i * 65
                        n['y'] = y0
                        break

        state = {
            'name': record.id + ' — ' + organism,
            'description': record.description[:120],
            'nodes': nodes,
            'edges': [],  # no edges in GenBank
            'init': init_dict,
            'chains': chains,
            'imported_from_genbank': True,
            'genbank_length': len(record.seq),
        }
        return state, ('Imported {} features ({} bp total)'.format(
            len(nodes), len(record.seq)))
    except Exception as e:
        biosim_log('warn', 'parse_genbank_to_circuit: {}'.format(e))
        return None, 'GenBank parse error: ' + str(e)[:120]


def fetch_ncbi_gene_via_biopython(gene_name, organism='Homo sapiens'):
    """Search NCBI for a gene and return its DNA + protein sequence + metadata.
    Uses biopython Entrez. Returns (info_dict, message)."""
    if not _ensure_biopython():
        return None, 'biopython not installed'
    try:
        Entrez.email = 'biosim@example.com'  # required by NCBI
        # Search nucleotide
        query = '{}[Gene] AND {}[Organism]'.format(gene_name, organism)
        handle = Entrez.esearch(db='nucleotide', term=query, retmax=1)
        result = Entrez.read(handle)
        handle.close()
        if not result.get('IdList'):
            # Fallback to broader search
            query = '{}[Gene]'.format(gene_name)
            handle = Entrez.esearch(db='nucleotide', term=query, retmax=1)
            result = Entrez.read(handle)
            handle.close()
        if not result.get('IdList'):
            return None, 'Gene not found in NCBI'
        gid = result['IdList'][0]
        # Fetch fasta
        handle = Entrez.efetch(db='nucleotide', id=gid, rettype='fasta', retmode='text')
        fasta_text = handle.read()
        handle.close()
        lines = fasta_text.strip().split('\n')
        header = lines[0] if lines else '>Unknown'
        seq = ''.join(lines[1:]).upper()
        return {
            'gene': gene_name,
            'organism': organism,
            'ncbi_id': gid,
            'header': header[:120],
            'sequence': seq,
            'length': len(seq),
        }, 'Loaded {} bp'.format(len(seq))
    except Exception as e:
        biosim_log('warn', 'fetch_ncbi_gene_via_biopython: {}'.format(e))
        return None, 'NCBI fetch error: ' + str(e)[:120]


def fetch_pdb_structure_html(pdb_id):
    """Generate py3Dmol HTML to display a PDB structure.
    Returns (html_string, message)."""
    if not _ensure_py3dmol():
        return None, 'py3Dmol not installed'
    try:
        pdb_id = pdb_id.upper().strip()
        if len(pdb_id) != 4:
            return None, 'PDB ID must be 4 characters (e.g. 1CRN)'
        view = py3Dmol.view(query='pdb:' + pdb_id, width=600, height=500)
        view.setStyle({'cartoon': {'color': 'spectrum'}})
        view.setBackgroundColor('#f5f7fa')
        view.zoomTo()
        return view._make_html(), 'PDB {} loaded'.format(pdb_id)
    except Exception as e:
        biosim_log('warn', 'fetch_pdb_structure_html: {}'.format(e))
        return None, 'PDB fetch error: ' + str(e)[:120]


# ─────────────────────────────────────────────────
# WET-LAB DATA + STATISTICS (uses pandas, statsmodels)
# ─────────────────────────────────────────────────

def load_csv_data(filepath):
    """Load CSV or Excel file as a dict of columns.
    Returns (data_dict, message). First column should be 'time' or similar."""
    if not _ensure_pandas():
        return None, 'pandas not installed'
    try:
        if filepath.lower().endswith(('.xlsx', '.xls')):
            df = pd.read_excel(filepath)
        else:
            # Try common separators
            try:
                df = pd.read_csv(filepath)
            except Exception as _exc:
                biosim_log('warn', 'load_csv_data: {}'.format(_exc))
                df = pd.read_csv(filepath, sep=';')
        if df.empty:
            return None, 'Empty data file'
        # Convert to dict-of-columns
        columns = {}
        for col in df.columns:
            col_str = str(col)
            # Convert column to numeric if possible
            try:
                vals = pd.to_numeric(df[col], errors='coerce').dropna().tolist()
                if len(vals) > 0:
                    columns[col_str] = vals
            except Exception as _exc:
                biosim_log('warn', 'load_csv_data: {}'.format(_exc))
                columns[col_str] = df[col].tolist()
        return {
            'columns': columns,
            'n_rows': len(df),
            'col_names': list(df.columns.astype(str)),
        }, 'Loaded {} rows, {} columns'.format(len(df), len(df.columns))
    except Exception as e:
        biosim_log('warn', 'load_csv_data: {}'.format(e))
        return None, 'Data load error: ' + str(e)[:120]


def compare_data_with_simulation(t_sim, y_sim, sim_node_ids, exp_data):
    """Compute residuals/RMSE between experimental data and simulation.
    exp_data: dict with 'time' key and one or more column names matching node ids.
    Returns dict of {node_id: {'rmse': float, 'mae': float, 'r2': float, 'data_points': [(t, y_exp, y_sim)]}}.
    """
    if exp_data is None:
        return None
    columns = exp_data.get('columns', {})
    # Find time column (case-insensitive)
    time_col = None
    for cname in columns:
        if cname.lower() in ('time', 't', 'час', 'час.', 'hours', 'h', 'min', 'sec'):
            time_col = cname
            break
    if time_col is None:
        # First column assumed to be time
        time_col = list(columns.keys())[0] if columns else None
    if time_col is None:
        return None

    t_exp = np.array(columns[time_col], dtype=float)
    results = {}

    for col_name, values in columns.items():
        if col_name == time_col:
            continue
        # Find matching node in simulation by id match
        match_idx = None
        for i, nid in enumerate(sim_node_ids):
            if nid.lower() == col_name.lower() or nid.lower() in col_name.lower():
                match_idx = i
                break
        if match_idx is None:
            continue

        y_exp = np.array(values, dtype=float)
        # Interpolate simulation at experimental time points
        y_sim_at_t_exp = np.interp(t_exp, t_sim, y_sim[:, match_idx])
        residuals = y_exp - y_sim_at_t_exp
        rmse = float(np.sqrt(np.mean(residuals ** 2)))
        mae = float(np.mean(np.abs(residuals)))
        # R²
        ss_res = float(np.sum(residuals ** 2))
        ss_tot = float(np.sum((y_exp - y_exp.mean()) ** 2))
        r2 = 1.0 - ss_res / ss_tot if ss_tot > 1e-10 else 0.0
        results[col_name] = {
            'rmse': rmse, 'mae': mae, 'r2': r2,
            't_exp': t_exp.tolist(),
            'y_exp': y_exp.tolist(),
            'y_sim_at_t_exp': y_sim_at_t_exp.tolist(),
            'matched_node': sim_node_ids[match_idx],
        }
    return results


def run_t_test(group1, group2):
    """Independent t-test between two groups. Returns (t_stat, p_value, interpretation)."""
    if not _ensure_statsmodels():
        return None, None, 'statsmodels not installed'
    try:
        a = np.array(group1, dtype=float); b = np.array(group2, dtype=float)
        t_stat, p_val = scipy_stats.ttest_ind(a, b)
        if p_val < 0.001:
            interp = 'Очень значимое различие (p < 0.001) ***'
        elif p_val < 0.01:
            interp = 'Значимое различие (p < 0.01) **'
        elif p_val < 0.05:
            interp = 'Различие на грани значимости (p < 0.05) *'
        else:
            interp = 'Различий не обнаружено (p = {:.3f})'.format(p_val)
        return float(t_stat), float(p_val), interp
    except Exception as e:
        biosim_log('warn', 'run_t_test: {}'.format(e))
        return None, None, 'T-test error: ' + str(e)[:80]


def run_anova(*groups):
    """One-way ANOVA. Returns (f_stat, p_value, interpretation)."""
    if not _ensure_statsmodels():
        return None, None, 'statsmodels not installed'
    if len(groups) < 2:
        return None, None, 'ANOVA needs at least 2 groups'
    try:
        arrays = [np.array(g, dtype=float) for g in groups]
        f_stat, p_val = scipy_stats.f_oneway(*arrays)
        if p_val < 0.001:
            interp = 'Группы сильно различаются (p < 0.001) ***'
        elif p_val < 0.01:
            interp = 'Группы значимо различаются (p < 0.01) **'
        elif p_val < 0.05:
            interp = 'Различия на грани значимости (p < 0.05) *'
        else:
            interp = 'Группы статистически одинаковы (p = {:.3f})'.format(p_val)
        return float(f_stat), float(p_val), interp
    except Exception as e:
        biosim_log('warn', 'run_anova: {}'.format(e))
        return None, None, 'ANOVA error: ' + str(e)[:80]


def run_linear_regression(x_data, y_data):
    """Simple linear regression. Returns dict with slope, intercept, r2, p_value."""
    if not _ensure_statsmodels():
        return None
    try:
        x = np.array(x_data, dtype=float)
        y = np.array(y_data, dtype=float)
        X = sm.add_constant(x)
        model = sm.OLS(y, X).fit()
        return {
            'slope': float(model.params[1]),
            'intercept': float(model.params[0]),
            'r2': float(model.rsquared),
            'p_value': float(model.pvalues[1]),
            'summary': str(model.summary().tables[1]),
        }
    except Exception as e:
        biosim_log('warn', 'run_linear_regression: {}'.format(e))
        return None


