def export_to_jupyter_notebook(state, filepath, include_sim=True):
    """Export the current circuit + recent simulation as a runnable Jupyter notebook."""
    if not _ensure_nbformat():
        return False, 'nbformat not installed'
    try:
        nb = nbformat.v4.new_notebook()
        cells = []

        # Title cell
        title_md = '# VIREON Circuit: {}\n\n'.format(state.get('name', 'Untitled'))
        title_md += '_Exported from VIREON v{}_\n\n'.format(BIOSIM_VERSION)
        title_md += '**Description:** {}\n\n'.format(state.get('description', 'No description'))
        title_md += '## Circuit summary\n\n'
        title_md += '- Nodes: {}\n'.format(len(state.get('nodes', [])))
        title_md += '- Edges: {}\n'.format(len(state.get('edges', [])))
        title_md += '- Chains: {}\n'.format(len(state.get('chains', [])))
        cells.append(nbformat.v4.new_markdown_cell(title_md))

        # Imports cell
        imports_code = ('import numpy as np\n'
                         'import matplotlib.pyplot as plt\n'
                         'from scipy.integrate import solve_ivp\n'
                         '\n'
                         '# If you have cobra installed, you can also do FBA:\n'
                         '# import cobra\n'
                         '# from cobra import Model, Reaction, Metabolite\n')
        cells.append(nbformat.v4.new_code_cell(imports_code))

        # Circuit data cell
        cells.append(nbformat.v4.new_markdown_cell('## Circuit definition\n'))
        nodes_repr = '[\n'
        for n in state.get('nodes', []):
            nodes_repr += '    {{"id": {!r}, "production": {}, "degradation": {}, '.format(
                n['id'], n.get('production', 1.0), n.get('degradation', 0.1))
            if n.get('gene_symbol'):
                nodes_repr += '"gene_symbol": {!r}, '.format(n['gene_symbol'])
            nodes_repr += '}},\n'
        nodes_repr += ']'
        edges_repr = '[\n'
        for e in state.get('edges', []):
            edges_repr += '    {{"from": {!r}, "to": {!r}, "type": {!r}, "strength": {}, "hill_n": {}}},\n'.format(
                e['from'], e['to'], e.get('type', 'activation'),
                e.get('strength', 3.0), e.get('hill_n', 2))
        edges_repr += ']'
        init_repr = '{\n'
        for k, v in state.get('init', {}).items():
            init_repr += '    {!r}: {},\n'.format(k, v)
        init_repr += '}'

        data_code = 'nodes = {}\n\nedges = {}\n\ninit = {}\n'.format(
            nodes_repr, edges_repr, init_repr)
        cells.append(nbformat.v4.new_code_cell(data_code))

        # ODE function
        cells.append(nbformat.v4.new_markdown_cell('## ODE system (Hill kinetics)\n'))
        ode_code = ('def build_ode_system(nodes, edges, init):\n'
                     '    node_ids = [n["id"] for n in nodes]\n'
                     '    idx = {nid: i for i, nid in enumerate(node_ids)}\n'
                     '    prod = np.array([n.get("production", 1.0) for n in nodes])\n'
                     '    deg = np.array([max(0.001, n.get("degradation", 0.1)) for n in nodes])\n'
                     '    K = 1.0\n'
                     '    def rhs(t, y):\n'
                     '        prod_rates = prod.copy()\n'
                     '        for e in edges:\n'
                     '            if e["from"] not in idx or e["to"] not in idx:\n'
                     '                continue\n'
                     '            src = max(0, y[idx[e["from"]]])\n'
                     '            tgt = idx[e["to"]]\n'
                     '            n_hill = e.get("hill_n", 2)\n'
                     '            if e["type"] == "activation":\n'
                     '                hill = (src ** n_hill) / (K ** n_hill + src ** n_hill + 1e-12)\n'
                     '                prod_rates[tgt] *= (1 + e.get("strength", 3) * hill)\n'
                     '            else:  # repression\n'
                     '                hill = K ** n_hill / (K ** n_hill + src ** n_hill + 1e-12)\n'
                     '                prod_rates[tgt] *= max(0.05, hill / max(0.01, e.get("strength", 3)))\n'
                     '        return prod_rates - deg * y\n'
                     '    y0 = np.array([init.get(nid, 0.5) for nid in node_ids])\n'
                     '    return rhs, node_ids, y0\n')
        cells.append(nbformat.v4.new_code_cell(ode_code))

        # Run simulation cell
        cells.append(nbformat.v4.new_markdown_cell('## Run simulation\n'))
        sim_code = ('rhs, node_ids, y0 = build_ode_system(nodes, edges, init)\n'
                     't_end = 100\n'
                     'sol = solve_ivp(rhs, (0, t_end), y0, t_eval=np.linspace(0, t_end, 200))\n'
                     '\n'
                     'fig, ax = plt.subplots(figsize=(8, 4))\n'
                     'for i, nid in enumerate(node_ids):\n'
                     '    ax.plot(sol.t, sol.y[i], lw=1.6, label=nid)\n'
                     'ax.set_xlabel("time")\n'
                     'ax.set_ylabel("concentration")\n'
                     'ax.legend()\n'
                     'ax.grid(True, alpha=0.3)\n'
                     'plt.title("VIREON Circuit Simulation")\n'
                     'plt.show()\n')
        cells.append(nbformat.v4.new_code_cell(sim_code))

        # Reproducibility cell
        cells.append(nbformat.v4.new_markdown_cell(
            '## Reproducibility\n\n'
            '- VIREON version: {}\n'
            '- Numpy: `import numpy; numpy.__version__`\n'
            '- Scipy: `import scipy; scipy.__version__`\n\n'
            'Citation: {}\n'.format(BIOSIM_VERSION, BIOSIM_CITATION_TEXT)))

        nb['cells'] = cells
        with open(filepath, 'w', encoding='utf-8') as f:
            nbformat.write(nb, f)
        return True, 'Notebook saved to ' + filepath
    except Exception as e:
        biosim_log('warn', 'export_to_jupyter_notebook: {}'.format(e))
        return False, 'Notebook export error: ' + str(e)[:120]


def export_to_antimony(state, filepath=None):
    """Export circuit as Antimony-style text (human-readable model language,
    like TinkerCell uses). Returns the text; also writes to file if path given.

    Antimony is a compact text format: species, reactions with rate laws,
    and parameter assignments. Widely used in systems biology (Tellurium,
    PySCeS, COPASI can read it).
    """
    nodes = state.get('nodes', []) if isinstance(state, dict) else []
    edges = state.get('edges', []) if isinstance(state, dict) else []
    name = (state.get('name', 'circuit') or 'circuit').replace(' ', '_')

    L = []
    L.append('// Antimony model exported from VIREON')
    L.append('// ' + (state.get('description', '') or ''))
    L.append('model ' + name + '()')
    L.append('')
    # Species declarations
    L.append('  // Species (genes / proteins)')
    for n in nodes:
        nid = n.get('id', '?')
        init = n.get('initial', n.get('init', 0.0))
        L.append(f'  species {nid};')
    L.append('')
    # Reactions: production and degradation per node
    L.append('  // Reactions')
    for n in nodes:
        nid = n.get('id', '?')
        prod = n.get('production', 1.0)
        deg = n.get('degradation', 0.1)
        # Find regulators of this node
        regs = [e for e in edges if e.get('to') == nid]
        if regs:
            # Build a Hill-style production term
            terms = []
            for e in regs:
                src = e.get('from'); typ = e.get('type', 'activation')
                strength = e.get('strength', 3.0); hn = e.get('hill_n', 2)
                if typ == 'activation':
                    terms.append(f'({strength}*{src}^{hn}/(1+{src}^{hn}))')
                elif typ == 'repression':
                    terms.append(f'(1/(1+({strength}*{src})^{hn}))')
            rate = f'{prod}*' + '*'.join(terms) if terms else str(prod)
            L.append(f'  J_{nid}_prod: -> {nid}; {rate};')
        else:
            L.append(f'  J_{nid}_prod: -> {nid}; {prod};')
        L.append(f'  J_{nid}_deg: {nid} -> ; {deg}*{nid};')
    L.append('')
    # Initial values
    L.append('  // Initial concentrations')
    for n in nodes:
        nid = n.get('id', '?')
        init = n.get('initial', n.get('init', 0.0))
        L.append(f'  {nid} = {init};')
    L.append('')
    L.append('end')
    text = '\n'.join(L)
    if filepath:
        try:
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(text)
        except Exception as _exc:
            biosim_log('warn', 'export_to_antimony: {}'.format(_exc))
    return text


def import_from_antimony(text):
    """Parse an Antimony-style text model back into a circuit (nodes + edges).
    Reverse of export_to_antimony. Recognizes species declarations, reactions,
    and initial assignments. Returns a state dict {nodes, edges, init, name}.

    This lets users paste a text model (from COPASI/Tellurium/TinkerCell) and
    turn it into a visual circuit.
    """
    import re as _re
    nodes = {}
    edges = []
    init = {}
    name = 'imported'
    lines = (text or '').split('\n')
    # node layout helper
    def _ensure_node(nid):
        if nid not in nodes:
            idx = len(nodes)
            nodes[nid] = {
                'id': nid, 'type': 'gene',
                'x': 120 + (idx % 5) * 130,
                'y': 100 + (idx // 5) * 110,
                'production': 1.0, 'degradation': 0.1,
                'initial': 0.0,
            }
        return nodes[nid]

    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('//') or line.startswith('#'):
            continue
        # model name
        m = _re.match(r'model\s+(\w+)', line)
        if m:
            name = m.group(1)
            continue
        # species declaration:  species A;  or  species A, B, C;
        m = _re.match(r'species\s+(.+);', line)
        if m:
            for sp in m.group(1).split(','):
                sp = sp.strip()
                if sp:
                    _ensure_node(sp)
            continue
        # reaction:  J1: A -> B; rate;   or   -> B; rate;   or  A -> ; rate;
        m = _re.match(r'(?:\w+\s*:)?\s*([\w\s\+]*)->\s*([\w\s\+]*);\s*(.+);', line)
        if m:
            lhs = m.group(1).strip()
            rhs = m.group(2).strip()
            rate = m.group(3).strip()
            reactants = [r.strip() for r in lhs.split('+') if r.strip()]
            products = [p.strip() for p in rhs.split('+') if p.strip()]
            for p in products:
                _ensure_node(p)
            for r in reactants:
                _ensure_node(r)
            # Detect regulators in the rate law (species names that appear)
            for sp in list(nodes.keys()):
                if sp in rate and products:
                    for p in products:
                        if sp != p:
                            # repression if rate has 1/(1+...sp...)
                            etype = 'repression' if _re.search(
                                r'1\s*/\s*\(1', rate) and sp in rate else 'activation'
                            edges.append({'from': sp, 'to': p,
                                          'type': etype, 'strength': 3.0,
                                          'hill_n': 2})
            continue
        # initial value:  A = 5;
        m = _re.match(r'(\w+)\s*=\s*([\d.eE+-]+);', line)
        if m:
            nid = m.group(1)
            try:
                val = float(m.group(2))
                _ensure_node(nid)
                nodes[nid]['initial'] = val
                init[nid] = val
            except ValueError as _exc:
                biosim_log('warn', 'import_from_antimony: {}'.format(_exc))
            continue

    # Build init dict for any node not yet in it
    for nid, nd in nodes.items():
        if nid not in init:
            init[nid] = nd.get('initial', 0.0)

    return {
        'name': name,
        'description': 'Imported from Antimony',
        'nodes': list(nodes.values()),
        'edges': edges,
        'init': init,
    }


# Antibiotic resistance markers and their compatibility (for plasmid assembly)
ANTIBIOTIC_MARKERS = {
    'AmpR':  {'name_ru': 'Ампициллин', 'name_en': 'Ampicillin', 'gene': 'bla'},
    'KanR':  {'name_ru': 'Канамицин', 'name_en': 'Kanamycin', 'gene': 'aph'},
    'CmR':   {'name_ru': 'Хлорамфеникол', 'name_en': 'Chloramphenicol', 'gene': 'cat'},
    'TetR':  {'name_ru': 'Тетрациклин', 'name_en': 'Tetracycline', 'gene': 'tetA'},
    'SpecR': {'name_ru': 'Спектиномицин', 'name_en': 'Spectinomycin', 'gene': 'aadA'},
    'GenR':  {'name_ru': 'Гентамицин', 'name_en': 'Gentamicin', 'gene': 'aacC1'},
}

# Origin of replication compatibility groups (incompatible if same group)
ORI_GROUPS = {
    'pUC':     {'group': 'ColE1', 'copy': 'high (500-700)'},
    'pBR322':  {'group': 'ColE1', 'copy': 'medium (15-20)'},
    'p15A':    {'group': 'p15A',  'copy': 'medium (10-12)'},
    'pSC101':  {'group': 'pSC101','copy': 'low (5)'},
    'pBBR1':   {'group': 'pBBR1', 'copy': 'medium (broad host)'},
}


def check_plasmid_compatibility(markers, oris):
    """Check whether a set of plasmids can coexist in the same cell.

    Plasmids with the SAME origin group are incompatible (compete for
    replication). Plasmids need DIFFERENT antibiotic markers to be selected
    together. Like SnapGene / TinkerCell plasmid checks.

    Returns a dict with compatibility status and warnings.
    """
    warnings = []
    ok = True
    # Check antibiotic markers — duplicates mean you can't select both
    seen_markers = {}
    for m in markers:
        seen_markers[m] = seen_markers.get(m, 0) + 1
    for m, count in seen_markers.items():
        if count > 1:
            ok = False
            warnings.append('Маркер {} повторяется {} раз — нельзя отобрать '
                            'обе плазмиды'.format(m, count))
    # Check origin compatibility — same group = incompatible
    groups = {}
    for o in oris:
        g = ORI_GROUPS.get(o, {}).get('group', o)
        groups.setdefault(g, []).append(o)
    for g, oris_in in groups.items():
        if len(oris_in) > 1:
            ok = False
            warnings.append('Origin-группа {} используется {} плазмидами — '
                            'они несовместимы'.format(g, len(oris_in)))
    return {
        'compatible': ok,
        'warnings': warnings,
        'n_markers': len(seen_markers),
        'n_ori_groups': len(groups),
    }


def calculate_pops_rips(node, edges, nodes_by_id):
    """Calculate PoPS (Polymerase per Second) and RiPS (Ribosomes per Second)
    for a gene — standard synthetic biology flux units.

    PoPS = transcription flux (promoter activity)
    RiPS = translation flux (depends on RBS strength)

    These let you compose parts predictably (BioBrick standard).
    """
    nid = node.get('id')
    base_prod = node.get('production', 1.0)
    # Find activating/repressing inputs
    activators = [e for e in edges if e.get('to') == nid and e.get('type') == 'activation']
    repressors = [e for e in edges if e.get('to') == nid and e.get('type') == 'repression']
    # PoPS: promoter output, modulated by regulators
    pops = base_prod
    for e in activators:
        pops *= (1 + e.get('strength', 1.0) * 0.3)
    for e in repressors:
        pops /= (1 + e.get('strength', 1.0) * 0.3)
    # RiPS: translation, depends on RBS strength (use node's rbs_strength or default)
    rbs_strength = node.get('rbs_strength', 1.0)
    rips = pops * rbs_strength
    return {
        'node': nid,
        'PoPS': round(pops, 3),
        'RiPS': round(rips, 3),
        'rbs_strength': rbs_strength,
    }


def export_to_python_script(state, filepath):
    """Export the current circuit as a standalone Python script."""
    try:
        lines = []
        lines.append('"""')
        lines.append('VIREON Circuit: {}'.format(state.get('name', 'Untitled')))
        lines.append('')
        lines.append('Description: {}'.format(state.get('description', 'No description')))
        lines.append('')
        lines.append('Generated by VIREON v{} — synthetic biology platform'.format(BIOSIM_VERSION))
        lines.append('"""')
        lines.append('')
        lines.append('import numpy as np')
        lines.append('import matplotlib.pyplot as plt')
        lines.append('from scipy.integrate import solve_ivp')
        lines.append('')
        lines.append('# ── Circuit definition ──')
        lines.append('nodes = [')
        for n in state.get('nodes', []):
            line = '    {{"id": {!r}, "production": {}, "degradation": {}'.format(
                n['id'], n.get('production', 1.0), n.get('degradation', 0.1))
            if n.get('gene_symbol'):
                line += ', "gene_symbol": {!r}'.format(n['gene_symbol'])
            line += '},'
            lines.append(line)
        lines.append(']')
        lines.append('')
        lines.append('edges = [')
        for e in state.get('edges', []):
            lines.append('    {{"from": {!r}, "to": {!r}, "type": {!r}, "strength": {}, "hill_n": {}}},'.format(
                e['from'], e['to'], e.get('type', 'activation'),
                e.get('strength', 3.0), e.get('hill_n', 2)))
        lines.append(']')
        lines.append('')
        lines.append('init = {')
        for k, v in state.get('init', {}).items():
            lines.append('    {!r}: {},'.format(k, v))
        lines.append('}')
        lines.append('')
        lines.append('# ── ODE system (Hill kinetics) ──')
        lines.append('def build_rhs(nodes, edges, init):')
        lines.append('    node_ids = [n["id"] for n in nodes]')
        lines.append('    idx = {nid: i for i, nid in enumerate(node_ids)}')
        lines.append('    prod = np.array([n.get("production", 1.0) for n in nodes])')
        lines.append('    deg = np.array([max(0.001, n.get("degradation", 0.1)) for n in nodes])')
        lines.append('    K = 1.0')
        lines.append('    def rhs(t, y):')
        lines.append('        rates = prod.copy()')
        lines.append('        for e in edges:')
        lines.append('            if e["from"] not in idx or e["to"] not in idx:')
        lines.append('                continue')
        lines.append('            src = max(0, y[idx[e["from"]]])')
        lines.append('            tgt = idx[e["to"]]')
        lines.append('            nh = e.get("hill_n", 2)')
        lines.append('            if e["type"] == "activation":')
        lines.append('                h = src**nh / (K**nh + src**nh + 1e-12)')
        lines.append('                rates[tgt] *= (1 + e.get("strength", 3) * h)')
        lines.append('            else:')
        lines.append('                h = K**nh / (K**nh + src**nh + 1e-12)')
        lines.append('                rates[tgt] *= max(0.05, h / max(0.01, e.get("strength", 3)))')
        lines.append('        return rates - deg * y')
        lines.append('    y0 = np.array([init.get(nid, 0.5) for nid in node_ids])')
        lines.append('    return rhs, node_ids, y0')
        lines.append('')
        lines.append('')
        lines.append('# ── Run simulation ──')
        lines.append('if __name__ == "__main__":')
        lines.append('    rhs, node_ids, y0 = build_rhs(nodes, edges, init)')
        lines.append('    t_end = 100')
        lines.append('    sol = solve_ivp(rhs, (0, t_end), y0, t_eval=np.linspace(0, t_end, 200))')
        lines.append('')
        lines.append('    fig, ax = plt.subplots(figsize=(8, 4))')
        lines.append('    for i, nid in enumerate(node_ids):')
        lines.append('        ax.plot(sol.t, sol.y[i], lw=1.6, label=nid)')
        lines.append('    ax.set_xlabel("time")')
        lines.append('    ax.set_ylabel("concentration")')
        lines.append('    ax.legend()')
        lines.append('    ax.grid(True, alpha=0.3)')
        lines.append('    plt.title("VIREON Circuit Simulation")')
        lines.append('    plt.show()')
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write('\n'.join(lines))
        return True, 'Python script saved to ' + filepath
    except Exception as e:
        biosim_log('warn', 'export_to_python_script: {}'.format(e))
        return False, 'Script export error: ' + str(e)[:120]


def export_to_sbol(state, filepath):
    """Export circuit as SBOL2 file."""
    if not _ensure_sbol():
        return False, 'sbol2 not installed'
    try:
        doc = sbol2.Document()
        sbol2.setHomespace('http://biosim.example.org')
        # Create ComponentDefinitions for each node
        for n in state.get('nodes', []):
            try:
                cd = sbol2.ComponentDefinition(n['id'], sbol2.BIOPAX_DNA)
                cd.name = n.get('gene_symbol') or n['id']
                cd.description = 'Auto-exported from VIREON'
                # Add role based on icon
                icon = n.get('icon', '')
                if icon == 'promoter':
                    cd.roles = [sbol2.SO_PROMOTER]
                elif icon == 'cds':
                    cd.roles = [sbol2.SO_CDS]
                elif icon == 'rbs':
                    cd.roles = [sbol2.SO_RBS]
                elif icon == 'terminator':
                    cd.roles = [sbol2.SO_TERMINATOR]
                # Add sequence if available
                if n.get('sequence'):
                    seq = sbol2.Sequence(n['id'] + '_seq', n['sequence'])
                    doc.addSequence(seq)
                    cd.sequences = [seq]
                doc.addComponentDefinition(cd)
            except Exception as _exc:
                biosim_log('warn', 'export_to_sbol: {}'.format(_exc))
                continue
        # Module for chains
        for i, chain in enumerate(state.get('chains', [])):
            if len(chain) < 2:
                continue
            try:
                mod_id = 'chain_{}'.format(i)
                mod_cd = sbol2.ComponentDefinition(mod_id, sbol2.BIOPAX_DNA)
                mod_cd.description = 'Transcription unit: {}'.format(' '.join(chain))
                doc.addComponentDefinition(mod_cd)
            except Exception as _exc:
                biosim_log('warn', 'export_to_sbol: {}'.format(_exc))
                continue
        doc.write(filepath)
        return True, 'SBOL saved to ' + filepath
    except Exception as e:
        biosim_log('warn', 'export_to_sbol: {}'.format(e))
        return False, 'SBOL export error: ' + str(e)[:120]


def save_simulation_to_hdf5(state, t, y, node_ids, filepath, simulation_type='ode'):
    """Save full simulation trajectory to HDF5."""
    if not _ensure_h5py():
        return False, 'h5py not installed'
    try:
        with h5py.File(filepath, 'w') as f:
            # Metadata
            f.attrs['biosim_version'] = BIOSIM_VERSION
            f.attrs['circuit_name'] = state.get('name', 'Untitled')
            f.attrs['simulation_type'] = simulation_type
            f.attrs['n_nodes'] = len(state.get('nodes', []))
            f.attrs['n_edges'] = len(state.get('edges', []))
            f.attrs['t_end'] = float(t[-1]) if len(t) > 0 else 0
            # Trajectory data
            grp = f.create_group('simulation')
            grp.create_dataset('time', data=t)
            grp.create_dataset('y', data=y)
            grp.create_dataset('node_ids',
                                data=np.array([nid.encode('utf-8') for nid in node_ids]))
            # Circuit structure
            cgrp = f.create_group('circuit')
            cgrp.create_dataset('nodes_json',
                                  data=np.array([json.dumps(n).encode('utf-8')
                                                  for n in state.get('nodes', [])]))
            cgrp.create_dataset('edges_json',
                                  data=np.array([json.dumps(e).encode('utf-8')
                                                  for e in state.get('edges', [])]))
        return True, 'Saved HDF5: ' + filepath
    except Exception as e:
        biosim_log('warn', 'save_simulation_to_hdf5: {}'.format(e))
        return False, 'HDF5 save error: ' + str(e)[:120]


# ═══════════════════════════════════════════════════
# PROJECT SAVE/LOAD (.biosim format)
# Native file format — full JSON of all state including
# circuits, simulations history, wet-lab data, version.
# ═══════════════════════════════════════════════════

BIOSIM_FILE_VERSION = '1.0'

# Logging system — keeps in-memory logs and writes to disk
_BIOSIM_LOG = []  # list of (timestamp, level, message)
_BIOSIM_LOG_MAX = 500

def biosim_log(level, message):
    """Add a log message. level = 'info' | 'warn' | 'error' | 'success'."""
    import datetime
    ts = datetime.datetime.now().strftime('%H:%M:%S')
    _BIOSIM_LOG.append((ts, level, str(message)))
    if len(_BIOSIM_LOG) > _BIOSIM_LOG_MAX:
        _BIOSIM_LOG.pop(0)
    # Also print to console for debugging
    try:
        print('[{}] {}: {}'.format(ts, level.upper(), message))
    except Exception as _exc:
        biosim_log('warn', 'biosim_log: {}'.format(_exc))


def get_biosim_log_text():
    """Return the full log as formatted text."""
    lines = []
    for ts, level, msg in _BIOSIM_LOG:
        prefix = {'info': '·', 'warn': '', 'error': '', 'success': ''}.get(level, '·')
        lines.append('[{}] {} {}'.format(ts, prefix, msg))
    return '\n'.join(lines)


def get_biosim_dir():
    """Get/create the ~/.biosim directory for autosaves and logs."""
    home = os.path.expanduser('~')
    bsdir = os.path.join(home, '.biosim')
    try:
        os.makedirs(bsdir, exist_ok=True)
    except Exception as _exc:
        biosim_log('warn', 'get_biosim_dir: {}'.format(_exc))
    return bsdir


def get_environment_info():
    """Capture current Python environment for reproducibility.
    Returns dict with versions of Python and key libraries.
    """
    import sys, platform
    env = {
        'python_version': sys.version.split()[0],
        'platform': platform.platform(),
        'biosim_version': BIOSIM_VERSION if 'BIOSIM_VERSION' in globals() else '5.0',
        'biosim_file_version': BIOSIM_FILE_VERSION,
        'captured_at': __import__('datetime').datetime.now().isoformat(),
        'libraries': {},
    }
    # Capture versions of key libraries
    lib_modules = {
        'numpy': 'numpy',
        'scipy': 'scipy',
        'matplotlib': 'matplotlib',
        'pandas': 'pandas',
        'networkx': 'networkx',
        'rdkit': 'rdkit',
        'cobra': 'cobra',
        'libsbml': 'libsbml',
        'biopython': 'Bio',
        'sbol2': 'sbol2',
        'h5py': 'h5py',
        'sklearn': 'sklearn',
        'plotly': 'plotly',
        'statsmodels': 'statsmodels',
        'tellurium': 'tellurium',
    }
    for name, module_name in lib_modules.items():
        try:
            mod = __import__(module_name)
            version = getattr(mod, '__version__', None) or getattr(mod, 'VERSION', '?')
            env['libraries'][name] = str(version)
        except ImportError as _exc:
            biosim_log('warn', 'get_environment_info: {}'.format(_exc))
            env['libraries'][name] = 'not installed'
        except Exception as _exc:
            biosim_log('warn', 'get_environment_info: {}'.format(_exc))
            env['libraries'][name] = 'unknown'
    return env


# Global seed manager for reproducible stochastic simulations
class SeedManager:
    """Manages random seeds for reproducible stochastic simulations.
    
    Usage:
        seed = SeedManager.get_seed()  # get fresh seed
        SeedManager.use_seed(42)       # set specific seed
        np.random.seed(seed)           # apply
    """
    _seed_history = []  # list of (timestamp, seed, context)
    _max_history = 200

    @classmethod
    def get_seed(cls, context=''):
        """Generate a new random seed and record it."""
        import datetime
        seed = int(np.random.randint(0, 2**31 - 1))
        ts = datetime.datetime.now().isoformat()
        cls._seed_history.append((ts, seed, context))
        if len(cls._seed_history) > cls._max_history:
            cls._seed_history.pop(0)
        return seed

    @classmethod
    def use_seed(cls, seed, context=''):
        """Use a specific seed and record."""
        import datetime
        seed = int(seed) & 0x7FFFFFFF
        ts = datetime.datetime.now().isoformat()
        cls._seed_history.append((ts, seed, context))
        if len(cls._seed_history) > cls._max_history:
            cls._seed_history.pop(0)
        return seed

    @classmethod
    def get_history(cls):
        return list(cls._seed_history)

    @classmethod
    def clear(cls):
        cls._seed_history.clear()


def export_combine_archive(state, filepath, extra_data=None, include_data=True):
    """Export project as COMBINE archive (.omex) — standard format for
    publishing biological models (combinedformat.org).
    
    Archive contains:
    - manifest.xml (COMBINE manifest)
    - model.xml (SBML)
    - simulation.sedml (SED-ML experiment description)
    - data/*.csv (experimental data if any)
    - README.md (auto-generated documentation)
    - metadata.json (environment, seeds, biosim project)
    """
    import zipfile
    import datetime
    try:
        # 1. Generate SBML
        sbml_text, sbml_msg = export_circuit_to_sbml(state)
        if sbml_text is None:
            return False, 'SBML export failed: ' + sbml_msg
        
        # 2. Generate SED-ML
        sedml_text = generate_sedml_for_circuit(state)
        
        # 3. Generate README
        readme_text = generate_project_readme(state, extra_data)
        
        # 4. Manifest XML
        manifest_lines = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<omexManifest xmlns="http://identifiers.org/combine.specifications/omex-manifest">',
            '  <content location="." format="http://identifiers.org/combine.specifications/omex"/>',
            '  <content location="./model.xml" format="http://identifiers.org/combine.specifications/sbml" master="true"/>',
            '  <content location="./simulation.sedml" format="http://identifiers.org/combine.specifications/sed-ml"/>',
            '  <content location="./README.md" format="http://purl.org/NET/mediatypes/text/markdown"/>',
            '  <content location="./metadata.json" format="http://purl.org/NET/mediatypes/application/json"/>',
        ]
        
        # 5. Metadata
        metadata = {
            'biosim_project': {
                'name': state.get('name', 'Untitled'),
                'description': state.get('description', ''),
                'n_nodes': len(state.get('nodes', [])),
                'n_edges': len(state.get('edges', [])),
                'created': datetime.datetime.now().isoformat(),
            },
            'environment': get_environment_info(),
            'seed_history': SeedManager.get_history()[-20:],
            'simulation_history': (extra_data or {}).get('simulation_history', [])[-10:],
        }
        
        # 6. Optional experimental data
        data_files = {}
        if include_data and state.get('wetlab_data'):
            try:
                wd = state['wetlab_data']
                cols = wd.get('col_names', [])
                if cols:
                    csv_lines = [','.join(cols)]
                    n_rows = len(wd['columns'].get(cols[0], []))
                    for i in range(n_rows):
                        row = [str(wd['columns'][c][i]) for c in cols]
                        csv_lines.append(','.join(row))
                    data_files['data/experimental_data.csv'] = '\n'.join(csv_lines)
                    manifest_lines.append(
                        '  <content location="./data/experimental_data.csv" '
                        'format="http://purl.org/NET/mediatypes/text/csv"/>')
            except Exception as _exc:
                biosim_log('warn', 'export_combine_archive: {}'.format(_exc))
        
        # Close manifest
        manifest_lines.append('</omexManifest>')
        manifest_xml = '\n'.join(manifest_lines)
        
        # 7. Write archive
        with zipfile.ZipFile(filepath, 'w', zipfile.ZIP_DEFLATED) as zf:
            zf.writestr('manifest.xml', manifest_xml)
            zf.writestr('model.xml', sbml_text)
            zf.writestr('simulation.sedml', sedml_text)
            zf.writestr('README.md', readme_text)
            zf.writestr('metadata.json', json.dumps(metadata, indent=2, ensure_ascii=False))
            for fname, content in data_files.items():
                zf.writestr(fname, content)
        
        biosim_log('success', 'COMBINE archive written: ' + filepath)
        return True, 'COMBINE archive (.omex) saved: {} files'.format(
            5 + len(data_files))
    except Exception as e:
        biosim_log('error', 'COMBINE export failed: ' + str(e))
        return False, 'COMBINE error: ' + str(e)[:120]


def generate_sedml_for_circuit(state, sim_time=100, n_points=200):
    """Generate SED-ML XML describing simulation experiments for this circuit.
    
    SED-ML is a standard for describing simulations independent of model format.
    Includes: simulation, task, dataGenerator, plot for each node.
    """
    nodes = state.get('nodes', [])
    name = state.get('name', 'Untitled')
    
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<sedML xmlns="http://sed-ml.org/sed-ml/level1/version4" level="1" version="4">',
        '  <listOfSimulations>',
        '    <uniformTimeCourse id="sim1" initialTime="0" outputStartTime="0" ',
        '                          outputEndTime="{}" numberOfPoints="{}">'.format(
            sim_time, n_points),
        '      <algorithm kisaoID="KISAO:0000019"/>',  # CVODE
        '    </uniformTimeCourse>',
        '  </listOfSimulations>',
        '  <listOfModels>',
        '    <model id="model1" language="urn:sedml:language:sbml" source="model.xml"/>',
        '  </listOfModels>',
        '  <listOfTasks>',
        '    <task id="task1" modelReference="model1" simulationReference="sim1"/>',
        '  </listOfTasks>',
        '  <listOfDataGenerators>',
        '    <dataGenerator id="time_dg" name="time">',
        '      <listOfVariables>',
        '        <variable id="time_v" symbol="urn:sedml:symbol:time" taskReference="task1"/>',
        '      </listOfVariables>',
        '      <math xmlns="http://www.w3.org/1998/Math/MathML">',
        '        <ci>time_v</ci>',
        '      </math>',
        '    </dataGenerator>',
    ]
    
    # Data generator for each species
    for node in nodes:
        nid = node['id']
        safe_id = ''.join(c if c.isalnum() or c == '_' else '_' for c in nid)
        lines.extend([
            '    <dataGenerator id="{}_dg" name="{}">'.format(safe_id, nid),
            '      <listOfVariables>',
            '        <variable id="{}_v" target="/sbml:sbml/sbml:model/sbml:listOfSpecies/sbml:species[@id=\'{}\']" taskReference="task1"/>'.format(
                safe_id, safe_id),
            '      </listOfVariables>',
            '      <math xmlns="http://www.w3.org/1998/Math/MathML">',
            '        <ci>{}_v</ci>'.format(safe_id),
            '      </math>',
            '    </dataGenerator>',
        ])
    
    lines.append('  </listOfDataGenerators>')
    
    # Plot
    lines.extend([
        '  <listOfOutputs>',
        '    <plot2D id="plot_all" name="{} — all species over time">'.format(name),
        '      <listOfCurves>',
    ])
    for node in nodes:
        nid = node['id']
        safe_id = ''.join(c if c.isalnum() or c == '_' else '_' for c in nid)
        lines.append(
            '        <curve id="curve_{}" name="{}" xDataReference="time_dg" yDataReference="{}_dg" logX="false" logY="false"/>'.format(
                safe_id, nid, safe_id))
    lines.extend([
        '      </listOfCurves>',
        '    </plot2D>',
        '  </listOfOutputs>',
        '</sedML>',
    ])
    
    return '\n'.join(lines)


def generate_project_readme(state, extra_data=None):
    """Auto-generate Markdown README documenting the project.
    Includes: description, model structure, parameters, references, citation.
    """
    import datetime
    nodes = state.get('nodes', [])
    edges = state.get('edges', [])
    name = state.get('name', 'Untitled')
    desc = state.get('description', '')
    
    lines = [
        '# {}'.format(name),
        '',
        '> Auto-generated by **VIREON** {}'.format(
            BIOSIM_VERSION if 'BIOSIM_VERSION' in globals() else '5.0'),
        '> Generated on: {}'.format(datetime.datetime.now().strftime('%Y-%m-%d %H:%M')),
        '',
    ]
    if desc:
        lines.extend(['## Description', '', desc, ''])
    
    lines.extend([
        '## Model Structure',
        '',
        '- **{}** species (nodes)'.format(len(nodes)),
        '- **{}** reactions (edges)'.format(len(edges)),
        '',
        '### Species',
        '',
        '| ID | Production | Degradation | Initial |',
        '|---|---|---|---|',
    ])
    init = state.get('init', {})
    for n in nodes:
        nid = n['id']
        prod = n.get('production', '?')
        deg = n.get('degradation', '?')
        ic = init.get(nid, '?')
        lines.append('| {} | {} | {} | {} |'.format(nid, prod, deg, ic))
    
    lines.extend(['', '### Reactions', '',
                   '| From | To | Type | Strength | Hill n |',
                   '|---|---|---|---|---|'])
    for e in edges:
        lines.append('| {} | {} | {} | {} | {} |'.format(
            e.get('from', '?'), e.get('to', '?'), e.get('type', '?'),
            e.get('strength', '?'), e.get('hill_n', '?')))
    
    # Simulation history
    sim_history = (extra_data or {}).get('simulation_history', [])
    if sim_history:
        lines.extend(['', '## Simulation History', ''])
        for s in sim_history[-5:]:
            lines.append('- {} · disease={} · score={}'.format(
                s.get('timestamp', '?')[:19],
                s.get('disease_label', s.get('disease', '?')),
                s.get('therapeutic_score', '?')))
    
    # Environment
    env = get_environment_info()
    lines.extend([
        '',
        '## Reproducibility',
        '',
        '### Environment',
        '',
        '- **Python**: {}'.format(env['python_version']),
        '- **Platform**: {}'.format(env['platform']),
        '- **VIREON**: {}'.format(env['biosim_version']),
        '',
        '### Library Versions',
        '',
    ])
    for lib, ver in sorted(env['libraries'].items()):
        if ver != 'not installed':
            lines.append('- `{}`: {}'.format(lib, ver))
    
    # Citation
    lines.extend([
        '',
        '## How to Cite',
        '',
        '```',
        'VIREON: A platform for systems and synthetic biology modeling.',
        'Generated model: {}'.format(name),
        'Date: {}'.format(datetime.datetime.now().strftime('%Y-%m-%d')),
        '```',
        '',
        '## How to Use',
        '',
        '1. Open `model.xml` (SBML) in any SBML-compatible tool',
        '   (COPASI, CellDesigner, VIREON)',
        '2. Or load `simulation.sedml` for the exact experiment description',
        '3. Experimental data (if included) is in `data/`',
        '',
        '---',
        '',
        '*This file was auto-generated by VIREON. See https://biosim.example for more.*',
    ])
    
    return '\n'.join(lines)


