def detect_motifs(state):
    """Detect known biological motifs in the circuit.
    
    Returns list of dicts:
        [{'type': str, 'nodes': [ids], 'confidence': 0-1, 'description': str}]
    
    Motifs detected:
        - feedback_loop_positive (ABA)
        - feedback_loop_negative (A⊣B⊣A or AB⊣A)
        - toggle_switch (A⊣B and B⊣A)
        - repressilator (A⊣B⊣C⊣A)
        - feedforward_loop (ABC and AC)
        - feedforward_loop_incoherent (ABC, A⊣C)
        - signaling_cascade (ABCD, all activation)
        - dimerization (X + Y XY)
        - autoregulation_pos (AA)
        - autoregulation_neg (A⊣A)
    """
    nodes = state.get('nodes', [])
    edges = state.get('edges', [])
    if not nodes or not edges:
        return []
    
    # Build adjacency: out_edges[node] = [(target, type)]
    out_edges = {n['id']: [] for n in nodes}
    in_edges = {n['id']: [] for n in nodes}
    for e in edges:
        s, t = e.get('from'), e.get('to')
        etype = e.get('type', 'activation')
        if s in out_edges and t in in_edges:
            out_edges[s].append((t, etype))
            in_edges[t].append((s, etype))
    
    motifs = []
    
    # 1. Autoregulation (self-loops)
    for n in nodes:
        nid = n['id']
        for tgt, etype in out_edges[nid]:
            if tgt == nid:
                kind = 'autoregulation_pos' if etype == 'activation' else 'autoregulation_neg'
                motifs.append({
                    'type': kind,
                    'nodes': [nid],
                    'confidence': 1.0,
                    'description': '{} regulates itself ({})'.format(nid,
                        'positively' if etype == 'activation' else 'negatively'),
                })
    
    # 2. Toggle Switch (A⊣B and B⊣A)
    for n1 in nodes:
        for n2 in nodes:
            if n1['id'] >= n2['id']:
                continue
            a, b = n1['id'], n2['id']
            has_ab_rep = any(t == b and et == 'repression' for t, et in out_edges[a])
            has_ba_rep = any(t == a and et == 'repression' for t, et in out_edges[b])
            if has_ab_rep and has_ba_rep:
                motifs.append({
                    'type': 'toggle_switch',
                    'nodes': [a, b],
                    'confidence': 1.0,
                    'description': 'Toggle Switch: {} ⊣ {} ⊣ {} (mutual repression — bistable memory)'.format(a, b, a),
                })
    
    # 3. Negative feedback loop (2-node)
    for n1 in nodes:
        for n2 in nodes:
            if n1['id'] >= n2['id']:
                continue
            a, b = n1['id'], n2['id']
            edges_ab = [(t, et) for t, et in out_edges[a] if t == b]
            edges_ba = [(t, et) for t, et in out_edges[b] if t == a]
            if edges_ab and edges_ba:
                # Count repressions in loop
                n_reps = sum(1 for _, et in edges_ab if et == 'repression') + \
                         sum(1 for _, et in edges_ba if et == 'repression')
                if n_reps == 1:
                    # Negative feedback (one inhibition)
                    motifs.append({
                        'type': 'feedback_loop_negative',
                        'nodes': [a, b],
                        'confidence': 0.9,
                        'description': 'Negative feedback: {} {} (creates oscillations or damped response)'.format(a, b),
                    })
                elif n_reps == 0:
                    # Positive feedback (all activation)
                    motifs.append({
                        'type': 'feedback_loop_positive',
                        'nodes': [a, b],
                        'confidence': 0.9,
                        'description': 'Positive feedback: {} {} (amplification, can create bistability)'.format(a, b),
                    })
    
    # 4. Repressilator (3-node negative cycle)
    if len(nodes) >= 3:
        for n1 in nodes:
            for n2 in nodes:
                if n2['id'] == n1['id']: continue
                for n3 in nodes:
                    if n3['id'] in (n1['id'], n2['id']): continue
                    a, b, c = n1['id'], n2['id'], n3['id']
                    if a > b or a > c:  # canonical order — A is smallest
                        continue
                    ab_rep = any(t == b and et == 'repression' for t, et in out_edges[a])
                    bc_rep = any(t == c and et == 'repression' for t, et in out_edges[b])
                    ca_rep = any(t == a and et == 'repression' for t, et in out_edges[c])
                    if ab_rep and bc_rep and ca_rep:
                        motifs.append({
                            'type': 'repressilator',
                            'nodes': [a, b, c],
                            'confidence': 1.0,
                            'description': 'Repressilator: {} ⊣ {} ⊣ {} ⊣ {} (creates oscillations, Elowitz 2000)'.format(a, b, c, a),
                        })
    
    # 5. Feedforward Loop (FFL)
    for a_node in nodes:
        a = a_node['id']
        for b_t, b_et in out_edges[a]:
            for c_t, c_et in out_edges[b_t]:
                if c_t == a or c_t == b_t:
                    continue
                # Does A also directly go to C?
                direct_to_c = [(t, et) for t, et in out_edges[a] if t == c_t]
                if direct_to_c:
                    direct_et = direct_to_c[0][1]
                    # Check coherence: signs along both paths should match
                    indirect_sign = 1 if (b_et == 'activation') == (c_et == 'activation') else -1
                    direct_sign = 1 if direct_et == 'activation' else -1
                    is_coherent = (indirect_sign == direct_sign)
                    motifs.append({
                        'type': 'feedforward_loop' if is_coherent else 'feedforward_loop_incoherent',
                        'nodes': [a, b_t, c_t],
                        'confidence': 0.95,
                        'description': '{} FFL: {} {} {}, {} {} ({})'.format(
                            'Coherent' if is_coherent else 'Incoherent',
                            a, b_t, c_t, a, c_t,
                            'sign-sensitive filter' if is_coherent else 'pulse generator'),
                    })
    
    # 6. Signaling cascade (linear ABCD, all activation)
    def find_chains(start, current, visited, depth):
        if depth >= 4:
            return [list(visited) + [current]]
        chains = []
        for t, et in out_edges[current]:
            if t in visited or et != 'activation':
                continue
            visited.add(current)
            chains.extend(find_chains(start, t, visited, depth + 1))
            visited.discard(current)
        if len(visited) >= 3:
            chains.append(list(visited) + [current])
        return chains
    
    seen_cascades = set()
    for n in nodes:
        chains = find_chains(n['id'], n['id'], set(), 0)
        for chain in chains:
            if len(chain) >= 4:
                key = tuple(chain)
                if key in seen_cascades:
                    continue
                seen_cascades.add(key)
                motifs.append({
                    'type': 'signaling_cascade',
                    'nodes': list(chain),
                    'confidence': 0.85,
                    'description': 'Signaling cascade: {} (amplifies signal at each step)'.format(
                        ' '.join(chain)),
                })
    
    # Deduplicate motifs (same type + same node set)
    seen = set()
    unique_motifs = []
    for m in motifs:
        key = (m['type'], tuple(sorted(m['nodes'])))
        if key in seen:
            continue
        seen.add(key)
        unique_motifs.append(m)
    
    return unique_motifs


def explain_circuit(state, lang='ru'):
    """Generate a human-readable English/Russian explanation of what the circuit does.
    Uses detected motifs + structure analysis.
    """
    nodes = state.get('nodes', [])
    edges = state.get('edges', [])
    
    if not nodes:
        return ('Схема пустая. Добавь узлы чтобы начать.'
                 if lang == 'ru' else
                 'Circuit is empty. Add nodes to begin.')
    
    n_nodes = len(nodes)
    n_edges = len(edges)
    motifs = detect_motifs(state)
    
    # Count by icon type
    icon_counts = {}
    for n in nodes:
        icon = n.get('icon', 'unknown')
        icon_counts[icon] = icon_counts.get(icon, 0) + 1
    
    # Count edge types
    n_activations = sum(1 for e in edges if e.get('type') == 'activation')
    n_repressions = sum(1 for e in edges if e.get('type') == 'repression')
    
    parts = []
    
    # Header
    name = state.get('name', '')
    if name and name != 'Untitled':
        parts.append('### {}'.format(name))
    
    # Structure overview
    if lang == 'ru':
        parts.append('**Состав схемы:**')
        parts.append('- Всего {} узлов и {} связей'.format(n_nodes, n_edges))
        if n_activations:
            parts.append('- {} активаций ()'.format(n_activations))
        if n_repressions:
            parts.append('- {} репрессий (⊣)'.format(n_repressions))
    else:
        parts.append('**Circuit composition:**')
        parts.append('- {} nodes, {} edges total'.format(n_nodes, n_edges))
        if n_activations:
            parts.append('- {} activations ()'.format(n_activations))
        if n_repressions:
            parts.append('- {} repressions (⊣)'.format(n_repressions))
    
    # Element types
    icon_names_ru = {
        'promoter': 'промоторов', 'rbs': 'RBS', 'cds': 'генов',
        'terminator': 'терминаторов', 'protein_circle': 'белков',
        'protein_square': 'комплексов', 'mrna': 'мРНК',
        'small_mol': 'малых молекул', 'binding_site': 'операторов',
    }
    icon_names_en = {
        'promoter': 'promoters', 'rbs': 'RBSs', 'cds': 'genes',
        'terminator': 'terminators', 'protein_circle': 'proteins',
        'protein_square': 'complexes', 'mrna': 'mRNAs',
        'small_mol': 'small molecules', 'binding_site': 'operators',
    }
    names = icon_names_ru if lang == 'ru' else icon_names_en
    type_parts = []
    for icon, count in sorted(icon_counts.items(), key=lambda x: -x[1])[:5]:
        if icon in names:
            type_parts.append('{} {}'.format(count, names[icon]))
    if type_parts:
        if lang == 'ru':
            parts.append('- Элементы: ' + ', '.join(type_parts))
        else:
            parts.append('- Elements: ' + ', '.join(type_parts))
    
    # Motifs section
    if motifs:
        parts.append('')
        parts.append('**Найденные мотивы:**' if lang == 'ru' else '**Detected motifs:**')
        # Filter to most interesting (avoid spamming all FFLs)
        interesting = []
        seen_types = set()
        priority = ['repressilator', 'toggle_switch', 'feedback_loop_negative',
                     'feedback_loop_positive', 'feedforward_loop_incoherent',
                     'feedforward_loop', 'signaling_cascade',
                     'autoregulation_neg', 'autoregulation_pos']
        for ptype in priority:
            for m in motifs:
                if m['type'] == ptype:
                    interesting.append(m)
                    seen_types.add(ptype)
                    break
        # Add unique types not in priority
        for m in motifs:
            if m['type'] not in seen_types:
                interesting.append(m)
                seen_types.add(m['type'])
        for m in interesting[:8]:  # top 8
            parts.append('- ' + m['description'])
    
    # Predicted behavior
    parts.append('')
    parts.append('**Прогноз поведения:**' if lang == 'ru' else '**Predicted behavior:**')
    
    behaviors = []
    motif_types = set(m['type'] for m in motifs)
    
    if 'repressilator' in motif_types:
        behaviors.append('' + ('Колебания в районе периода ~150 минут (Elowitz model)'
                                    if lang == 'ru' else
                                    'Oscillations with period ~150 min (Elowitz model)'))
    if 'toggle_switch' in motif_types:
        behaviors.append('' + ('Бистабильность — 2 устойчивых состояния (память)'
                                    if lang == 'ru' else
                                    'Bistability — 2 stable states (memory)'))
    if 'feedback_loop_negative' in motif_types and 'repressilator' not in motif_types:
        behaviors.append('〰 ' + ('Возможны затухающие колебания или гомеостаз'
                                    if lang == 'ru' else
                                    'Possible damped oscillations or homeostasis'))
    if 'feedback_loop_positive' in motif_types:
        behaviors.append('' + ('Усиление сигнала, возможна бистабильность'
                                    if lang == 'ru' else
                                    'Signal amplification, possible bistability'))
    if 'feedforward_loop_incoherent' in motif_types:
        behaviors.append('' + ('Pulse generator — short pulse on input change'
                                    if lang == 'en' else
                                    'Pulse-генератор — короткий импульс при изменении входа'))
    if 'signaling_cascade' in motif_types:
        behaviors.append('' + ('Усиление сигнала по каскаду'
                                    if lang == 'ru' else
                                    'Signal amplification along cascade'))
    if not behaviors:
        if n_repressions == 0 and n_activations > 0:
            behaviors.append('' + ('Монотонная активация — сигнал распространяется по сети'
                                        if lang == 'ru' else
                                        'Monotonic activation — signal flows through network'))
        else:
            behaviors.append('' + ('Сложная динамика — рекомендую запустить bifurcation анализ'
                                        if lang == 'ru' else
                                        'Complex dynamics — recommend running bifurcation analysis'))
    parts.extend(behaviors)
    
    # Recommendations
    parts.append('')
    parts.append('**Рекомендации:**' if lang == 'ru' else '**Recommendations:**')
    
    recs = []
    if n_edges == 0:
        recs.append('• ' + ('Добавь связи между узлами'
                              if lang == 'ru' else 'Add connections between nodes'))
    if 'cds' in icon_counts and 'terminator' not in icon_counts:
        recs.append('• ' + ('Добавь терминаторы после генов'
                              if lang == 'ru' else 'Add terminators after genes'))
    if 'cds' in icon_counts and 'promoter' not in icon_counts:
        recs.append('• ' + ('Добавь промоторы перед генами'
                              if lang == 'ru' else 'Add promoters before genes'))
    if n_nodes >= 3 and len(motifs) > 0:
        recs.append('• ' + ('Запусти Bifurcation анализ для поиска bistability'
                              if lang == 'ru' else
                              'Run Bifurcation analysis to look for bistability'))
    if n_repressions >= 2:
        recs.append('• ' + ('Запусти Phase Portrait 2D для визуализации динамики'
                              if lang == 'ru' else
                              'Run Phase Portrait 2D to visualize dynamics'))
    if not recs:
        recs.append('• ' + ('Схема выглядит хорошо — запусти симуляцию!'
                              if lang == 'ru' else
                              'Circuit looks good — run a simulation!'))
    parts.extend(recs)
    
    return '\n'.join(parts)


def detect_circuit_issues(state, lang='ru'):
    """Find problems in the circuit (validation).
    
    Returns list of dicts:
        [{'severity': 'error'|'warn'|'info', 'message': str, 'node': str or None}]
    """
    nodes = state.get('nodes', [])
    edges = state.get('edges', [])
    issues = []
    
    if not nodes:
        return issues
    
    node_ids = {n['id'] for n in nodes}
    
    # Build edge sets
    edges_from = {nid: [] for nid in node_ids}
    edges_to = {nid: [] for nid in node_ids}
    for e in edges:
        if e.get('from') in edges_from:
            edges_from[e['from']].append(e)
        if e.get('to') in edges_to:
            edges_to[e['to']].append(e)
    
    # 1. Isolated nodes (no in or out edges)
    for n in nodes:
        nid = n['id']
        if not edges_from[nid] and not edges_to[nid]:
            issues.append({
                'severity': 'warn',
                'message': ('Узел "{}" изолирован — не связан с другими'.format(nid)
                            if lang == 'ru' else
                            'Node "{}" is isolated — not connected to anything'.format(nid)),
                'node': nid,
            })
    
    # 2. Genes without promoters
    icons = {n['id']: n.get('icon', '') for n in nodes}
    for n in nodes:
        if n.get('icon') == 'cds':
            # CDS should have an upstream promoter (an activation edge from a promoter node)
            has_promoter = any(
                icons.get(e.get('from')) == 'promoter'
                for e in edges_to[n['id']])
            if not has_promoter:
                issues.append({
                    'severity': 'info',
                    'message': ('Ген "{}" не имеет промотора'.format(n['id'])
                                if lang == 'ru' else
                                'Gene "{}" has no promoter'.format(n['id'])),
                    'node': n['id'],
                })
    
    # 3. CDS without terminator (less critical)
    has_any_terminator = any(n.get('icon') == 'terminator' for n in nodes)
    has_any_cds = any(n.get('icon') == 'cds' for n in nodes)
    if has_any_cds and not has_any_terminator:
        issues.append({
            'severity': 'info',
            'message': ('В схеме нет терминаторов'
                        if lang == 'ru' else
                        'Circuit has no terminators'),
            'node': None,
        })
    
    # 4. Parameter sanity check
    for n in nodes:
        prod = n.get('production', 1.0)
        deg = n.get('degradation', 0.1)
        if isinstance(prod, (int, float)) and prod < 0:
            issues.append({
                'severity': 'error',
                'message': ('Отрицательная production у "{}"'.format(n['id'])
                            if lang == 'ru' else
                            'Negative production for "{}"'.format(n['id'])),
                'node': n['id'],
            })
        if isinstance(deg, (int, float)) and deg <= 0:
            issues.append({
                'severity': 'warn',
                'message': ('Degradation ≤ 0 у "{}" — концентрация не упадёт'.format(n['id'])
                            if lang == 'ru' else
                            'Degradation ≤ 0 for "{}" — concentration won\'t decay'.format(n['id'])),
                'node': n['id'],
            })
        if isinstance(prod, (int, float)) and isinstance(deg, (int, float)):
            if prod > 0 and deg > 0:
                ss_value = prod / deg
                if ss_value > 1000:
                    issues.append({
                        'severity': 'warn',
                        'message': ('Очень высокий steady-state у "{}" ({:.0f}) — проверь параметры'.format(n['id'], ss_value)
                                    if lang == 'ru' else
                                    'Very high steady-state for "{}" ({:.0f}) — check parameters'.format(n['id'], ss_value)),
                        'node': n['id'],
                    })
    
    # 5. Hill coefficient sanity
    for e in edges:
        hill = e.get('hill_n', 2)
        if isinstance(hill, (int, float)):
            if hill < 1:
                issues.append({
                    'severity': 'warn',
                    'message': ('Hill n < 1 в связи {}{} — нефизично'.format(
                                    e.get('from', '?'), e.get('to', '?'))
                                if lang == 'ru' else
                                'Hill n < 1 in edge {}{} — non-physical'.format(
                                    e.get('from', '?'), e.get('to', '?'))),
                    'node': None,
                })
            elif hill > 10:
                issues.append({
                    'severity': 'info',
                    'message': ('Очень высокий Hill n ({}) — экстремальный switch'.format(hill)
                                if lang == 'ru' else
                                'Very high Hill n ({}) — extreme switch'.format(hill)),
                    'node': None,
                })
    
    # 6. Missing initial conditions
    init = state.get('init', {})
    for n in nodes:
        if n['id'] not in init:
            issues.append({
                'severity': 'info',
                'message': ('Нет начального значения для "{}"'.format(n['id'])
                            if lang == 'ru' else
                            'No initial value for "{}"'.format(n['id'])),
                'node': n['id'],
            })
    
    return issues


def suggest_next_connections(state, focus_node=None, lang='ru'):
    """Suggest likely next connections based on circuit patterns.
    
    Returns list of dicts:
        [{'from': id, 'to': id, 'type': str, 'reason': str, 'confidence': 0-1}]
    """
    nodes = state.get('nodes', [])
    edges = state.get('edges', [])
    suggestions = []
    
    if len(nodes) < 2:
        return suggestions
    
    icons = {n['id']: n.get('icon', '') for n in nodes}
    existing_pairs = {(e.get('from'), e.get('to')) for e in edges}
    
    # Suggestion 1: promoter adjacent gene/RBS
    for n in nodes:
        if n.get('icon') == 'promoter':
            pid = n['id']
            # Find any RBS or CDS without already being connected
            for n2 in nodes:
                if n2['id'] == pid:
                    continue
                if n2.get('icon') in ('rbs', 'cds'):
                    if (pid, n2['id']) not in existing_pairs:
                        suggestions.append({
                            'from': pid, 'to': n2['id'],
                            'type': 'activation',
                            'reason': ('Промотор обычно активирует RBS/ген'
                                        if lang == 'ru' else
                                        'Promoter usually activates RBS/gene'),
                            'confidence': 0.8 if n2.get('icon') == 'rbs' else 0.6,
                        })
                        break  # only one suggestion per promoter
    
    # Suggestion 2: gene next gene in cascade (mRNA protein)
    for n in nodes:
        if n.get('icon') == 'mrna':
            mid = n['id']
            for n2 in nodes:
                if n2['id'] == mid:
                    continue
                if n2.get('icon') in ('protein_circle', 'protein_square', 'cds'):
                    if (mid, n2['id']) not in existing_pairs:
                        suggestions.append({
                            'from': mid, 'to': n2['id'],
                            'type': 'activation',
                            'reason': ('Translation: мРНК белок'
                                        if lang == 'ru' else
                                        'Translation: mRNA protein'),
                            'confidence': 0.7,
                        })
                        break
    
    # Suggestion 3: complete a toggle switch (if there's A⊣B without B⊣A)
    for e in edges:
        if e.get('type') == 'repression':
            a, b = e.get('from'), e.get('to')
            if (b, a) not in existing_pairs:
                # Suggest reverse repression to make toggle
                suggestions.append({
                    'from': b, 'to': a,
                    'type': 'repression',
                    'reason': ('Замкнёт toggle switch для bistability'
                                if lang == 'ru' else
                                'Would close toggle switch for bistability'),
                    'confidence': 0.6,
                })
    
    # Suggestion 4: complete a repressilator (3-cycle of repressions)
    rep_edges = [(e.get('from'), e.get('to')) for e in edges if e.get('type') == 'repression']
    if len(rep_edges) >= 2:
        for e1 in rep_edges:
            for e2 in rep_edges:
                if e1 == e2:
                    continue
                a, b = e1
                b2, c = e2
                if b == b2 and a != c:
                    # Have A⊣B⊣C, suggest C⊣A
                    if (c, a) not in existing_pairs:
                        suggestions.append({
                            'from': c, 'to': a,
                            'type': 'repression',
                            'reason': ('Замкнёт repressilator для колебаний'
                                        if lang == 'ru' else
                                        'Would close repressilator for oscillations'),
                            'confidence': 0.85,
                        })
    
    # Filter by focus_node if requested
    if focus_node:
        suggestions = [s for s in suggestions
                         if s['from'] == focus_node or s['to'] == focus_node]
    
    # Sort by confidence and limit
    suggestions.sort(key=lambda x: -x['confidence'])
    return suggestions[:5]


def search_biomodels(query, max_results=20):
    """Search the EBI BioModels database via REST API.
    Returns list of {id, name, format, organism} or empty list on error.
    """
    try:
        import urllib.request, urllib.parse
        # BioModels REST endpoint
        url = 'https://www.ebi.ac.uk/biomodels/search?query=' + urllib.parse.quote(query) + \
              '&numResults=' + str(max_results) + '&format=json'
        req = urllib.request.Request(url, headers={'Accept': 'application/json'})
        with urllib.request.urlopen(req, timeout=20) as resp:
            data = json.loads(resp.read().decode('utf-8'))
        models = []
        for item in data.get('models', [])[:max_results]:
            models.append({
                'id': item.get('id', '?'),
                'name': item.get('name', 'Untitled')[:80],
                'format': item.get('format', '?'),
                'submitter': item.get('submitter', '?'),
                'submission_date': item.get('submissionDate', '?')[:10],
                'publication_id': item.get('publicationId', '?'),
            })
        return models, 'Found {} models'.format(len(models))
    except Exception as e:
        biosim_log('error', 'BioModels search failed: ' + str(e))
        return [], 'Search error: ' + str(e)[:100]


def download_biomodel_sbml(model_id):
    """Download a BioModel as SBML XML text."""
    try:
        import urllib.request
        url = 'https://www.ebi.ac.uk/biomodels/model/download/' + model_id + '.xml'
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req, timeout=30) as resp:
            xml_text = resp.read().decode('utf-8')
        biosim_log('success', 'Downloaded BioModel ' + model_id)
        return xml_text, 'OK'
    except Exception as e:
        biosim_log('error', 'BioModel download failed: ' + str(e))
        return None, 'Download error: ' + str(e)[:120]


def bifurcation_analysis(state, param_node, param_type, p_min, p_max,
                            n_steps=40, target_nodes=None):
    """Compute bifurcation diagram.
    For each parameter value, find ALL stable states (by integrating from multiple initial conditions).
    Returns dict { node_id: [(param_value, [steady_states])] }.
    """
    import copy
    if target_nodes is None:
        target_nodes = [n['id'] for n in state['nodes']]
    p_values = np.linspace(p_min, p_max, n_steps)
    results = {tn: [] for tn in target_nodes}
    # Try multiple initial conditions to find all stable states
    init_multipliers = [0.1, 0.5, 1.0, 2.0, 5.0]
    for pv in p_values:
        ss_set = {tn: set() for tn in target_nodes}
        for mult in init_multipliers:
            state_copy = copy.deepcopy(state)
            for n in state_copy['nodes']:
                if n['id'] == param_node:
                    if param_type == 'production':
                        n['production'] = float(pv)
                    elif param_type == 'degradation':
                        n['degradation'] = max(0.001, float(pv))
            # Vary initial conditions to find different attractors
            init_mod = dict(state_copy['init'])
            for k in init_mod:
                init_mod[k] = float(init_mod[k]) * mult
            ss, ids = compute_steady_state(state_copy['nodes'],
                                              state_copy['edges'],
                                              init_mod)
            if ss is not None:
                for i, nid in enumerate(ids):
                    if nid in target_nodes:
                        # Round to detect duplicates
                        ss_set[nid].add(round(float(ss[i]), 3))
        for tn in target_nodes:
            results[tn].append((float(pv), sorted(ss_set[tn])))
    return results, p_values


def classify_steady_state(jacobian_matrix):
    """Classify a steady state by analyzing eigenvalues of Jacobian.
    
    Returns dict with:
        type: 'stable_node' | 'stable_spiral' | 'unstable_node' | 'unstable_spiral' |
              'saddle' | 'center' | 'degenerate'
        eigenvalues: list of complex eigenvalues
        max_real: largest real part (stability indicator)
        has_oscillations: True if eigenvalues have non-zero imaginary parts
        is_stable: True if all real parts are negative
    """
    if jacobian_matrix is None:
        return {'type': 'unknown', 'eigenvalues': [], 'max_real': 0,
                 'has_oscillations': False, 'is_stable': False}
    try:
        eigenvalues = np.linalg.eigvals(jacobian_matrix)
        real_parts = eigenvalues.real
        imag_parts = eigenvalues.imag
        max_real = float(np.max(real_parts))
        min_real = float(np.min(real_parts))
        has_oscillations = bool(np.any(np.abs(imag_parts) > 1e-9))
        is_stable = max_real < -1e-9
        
        # Classification
        eps = 1e-9
        if max_real < -eps:
            # All real parts negative — stable
            if has_oscillations:
                state_type = 'stable_spiral'
            else:
                state_type = 'stable_node'
        elif max_real > eps and min_real < -eps:
            # Mix of positive and negative — saddle
            state_type = 'saddle'
        elif max_real > eps:
            # All positive — unstable
            if has_oscillations:
                state_type = 'unstable_spiral'
            else:
                state_type = 'unstable_node'
        elif abs(max_real) < eps:
            # Real parts near zero — center or degenerate (Hopf candidate)
            if has_oscillations:
                state_type = 'center'  # potential Hopf
            else:
                state_type = 'degenerate'
        else:
            state_type = 'unknown'
        
        return {
            'type': state_type,
            'eigenvalues': eigenvalues.tolist(),
            'max_real': max_real,
            'has_oscillations': has_oscillations,
            'is_stable': is_stable,
        }
    except Exception as _exc:
        biosim_log('warn', 'classify_steady_state: {}'.format(_exc))
        return {'type': 'error', 'eigenvalues': [], 'max_real': 0,
                 'has_oscillations': False, 'is_stable': False}


def detect_bifurcation_type(prev_class, curr_class):
    """Detect type of bifurcation between two parameter values.
    
    Returns string: 'saddle_node' | 'hopf' | 'pitchfork' | None
    """
    if prev_class is None or curr_class is None:
        return None
    
    prev_stable = prev_class.get('is_stable', False)
    curr_stable = curr_class.get('is_stable', False)
    prev_osc = prev_class.get('has_oscillations', False)
    curr_osc = curr_class.get('has_oscillations', False)
    
    # Stability change without oscillation change Saddle-node or transcritical
    if prev_stable != curr_stable:
        # If we crossed zero in real parts of non-oscillating eigenvalues
        if prev_osc == curr_osc and not curr_osc:
            return 'saddle_node'
        # If oscillation pattern changed too Hopf
        if prev_osc != curr_osc:
            return 'hopf'
    
    # Stability didn't change but oscillation behavior did Hopf (subcritical/supercritical)
    if prev_osc != curr_osc:
        return 'hopf'
    
    return None


def bifurcation_with_classification(state, param_node, param_type, p_min, p_max,
                                       n_steps=40, target_nodes=None):
    """Enhanced bifurcation analysis with stability classification at each point.
    
    Returns:
        results: { node_id: [(param_value, steady_state, class_info)] }
        bifurcations: list of detected bifurcations with parameter values
        p_values: array of parameter values used
    """
    import copy
    if target_nodes is None:
        target_nodes = [n['id'] for n in state['nodes']]
    
    p_values = np.linspace(p_min, p_max, n_steps)
    results = {tn: [] for tn in target_nodes}
    bifurcations = []
    prev_class = None
    
    for pv in p_values:
        state_copy = copy.deepcopy(state)
        for n in state_copy['nodes']:
            if n['id'] == param_node:
                if param_type == 'production':
                    n['production'] = float(pv)
                elif param_type == 'degradation':
                    n['degradation'] = max(0.001, float(pv))
                break
        
        # Find steady state(s) by trying multiple initial conditions
        init_multipliers = [0.1, 0.5, 1.0, 2.0, 5.0]
        states_found = []
        for mult in init_multipliers:
            init_mod = {k: float(v) * mult for k, v in state_copy['init'].items()}
            ss, ids = compute_steady_state(state_copy['nodes'],
                                              state_copy['edges'], init_mod)
            if ss is not None:
                # Round to detect duplicates
                rounded = tuple(round(float(x), 3) for x in ss)
                if rounded not in [tuple(round(float(x), 3) for x in s[0]) for s in states_found]:
                    states_found.append((ss, ids))
        
        # Compute Jacobian for the first state found
        primary_class = None
        if states_found:
            ss, ids = states_found[0]
            ss_dict = {ids[i]: ss[i] for i in range(len(ids))}
            jac_result = compute_jacobian_at_ss(state_copy['nodes'], state_copy['edges'],
                                                    ss_dict)
            # Handle both tuple and single return
            if isinstance(jac_result, tuple):
                jac = jac_result[0]
            else:
                jac = jac_result
            if jac is not None:
                primary_class = classify_steady_state(jac)
        
        # Save results for target nodes
        for tn in target_nodes:
            point_data = []
            for ss, ids in states_found:
                if tn in ids:
                    idx = ids.index(tn)
                    point_data.append(float(ss[idx]))
            results[tn].append((float(pv), point_data, primary_class))
        
        # Detect bifurcation transition
        if prev_class is not None and primary_class is not None:
            bif_type = detect_bifurcation_type(prev_class, primary_class)
            if bif_type:
                bifurcations.append({
                    'param_value': float(pv),
                    'type': bif_type,
                    'prev_state': prev_class.get('type'),
                    'curr_state': primary_class.get('type'),
                })
        
        prev_class = primary_class
    
    return results, bifurcations, p_values


def compute_phase_portrait_2d(state, var_x, var_y, x_range=(0, 5), y_range=(0, 5),
                                n_grid=15, n_trajectories=8):
    """Compute 2D phase portrait: vector field + sample trajectories.
    
    Returns:
        grid: dict with 'X', 'Y', 'U', 'V' arrays for quiver plot
        trajectories: list of (t, x_arr, y_arr) for each trajectory
        nullclines: dict with 'x' for dX/dt=0 curve and 'y' for dY/dt=0 curve
    """
    try:
        node_ids = [n['id'] for n in state['nodes']]
        if var_x not in node_ids or var_y not in node_ids:
            return None, 'Variables not in model'
        
        # Build ODE system
        ode_func, ode_node_ids, _ = _build_circuit_ode_system(
            state['nodes'], state['edges'], state.get('init', {}))
        ix = node_ids.index(var_x)
        iy = node_ids.index(var_y)
        
        # Get baseline values for other variables (use initial conditions)
        baseline = [float(state['init'].get(nid, 0.5)) for nid in node_ids]
        
        # Build grid
        x_grid = np.linspace(x_range[0], x_range[1], n_grid)
        y_grid = np.linspace(y_range[0], y_range[1], n_grid)
        X, Y = np.meshgrid(x_grid, y_grid)
        U = np.zeros_like(X)
        V = np.zeros_like(Y)
        
        for i in range(n_grid):
            for j in range(n_grid):
                y_state = list(baseline)
                y_state[ix] = X[i, j]
                y_state[iy] = Y[i, j]
                try:
                    dydt = ode_func(0, y_state)
                    U[i, j] = float(dydt[ix])
                    V[i, j] = float(dydt[iy])
                except Exception as _exc:
                    biosim_log('warn', 'compute_phase_portrait_2d: {}'.format(_exc))
        
        # Normalize for nicer arrows
        magnitudes = np.sqrt(U**2 + V**2) + 1e-9
        U_norm = U / magnitudes
        V_norm = V / magnitudes
        
        # Sample trajectories
        trajectories = []
        starts = [
            (x_range[0] + 0.1, y_range[0] + 0.1),
            (x_range[0] + 0.1, y_range[1] - 0.1),
            (x_range[1] - 0.1, y_range[0] + 0.1),
            (x_range[1] - 0.1, y_range[1] - 0.1),
            (sum(x_range)/2, y_range[0] + 0.1),
            (sum(x_range)/2, y_range[1] - 0.1),
            (x_range[0] + 0.1, sum(y_range)/2),
            (x_range[1] - 0.1, sum(y_range)/2),
        ]
        for sx, sy in starts[:n_trajectories]:
            init_copy = list(baseline)
            init_copy[ix] = sx
            init_copy[iy] = sy
            try:
                from scipy.integrate import solve_ivp
                sol = solve_ivp(ode_func, (0, 50), init_copy,
                                   t_eval=np.linspace(0, 50, 100),
                                   method='LSODA', rtol=1e-6, atol=1e-9)
                if sol.success:
                    trajectories.append((sol.t, sol.y[ix], sol.y[iy]))
            except Exception as _exc:
                biosim_log('warn', 'compute_phase_portrait_2d: {}'.format(_exc))
                continue
        
        # Compute nullclines (approximate by finding where U=0 or V=0)
        # X-nullcline: dX/dt = 0
        nullx = []
        for i in range(n_grid):
            row_signs = np.sign(U[i, :])
            for j in range(n_grid - 1):
                if row_signs[j] != row_signs[j + 1] and row_signs[j] != 0:
                    # Crossing
                    t = abs(U[i, j]) / (abs(U[i, j]) + abs(U[i, j+1]) + 1e-12)
                    x_cross = x_grid[j] + t * (x_grid[j+1] - x_grid[j])
                    nullx.append((x_cross, y_grid[i]))
        nully = []
        for j in range(n_grid):
            col_signs = np.sign(V[:, j])
            for i in range(n_grid - 1):
                if col_signs[i] != col_signs[i + 1] and col_signs[i] != 0:
                    t = abs(V[i, j]) / (abs(V[i, j]) + abs(V[i+1, j]) + 1e-12)
                    y_cross = y_grid[i] + t * (y_grid[i+1] - y_grid[i])
                    nully.append((x_grid[j], y_cross))
        
        return {
            'X': X, 'Y': Y, 'U': U_norm, 'V': V_norm,
            'U_raw': U, 'V_raw': V,
            'trajectories': trajectories,
            'nullclines_x': nullx,
            'nullclines_y': nully,
            'var_x': var_x, 'var_y': var_y,
        }, 'OK'
    except Exception as e:
        biosim_log('warn', 'compute_phase_portrait_2d: {}'.format(e))
        return None, 'Phase portrait error: ' + str(e)[:120]


def estimate_lyapunov_exponent(state, t_end=200, perturbation=1e-7):
    """Estimate the largest Lyapunov exponent by running 2 trajectories
    that start very close to each other and measuring their divergence rate.
    
    Returns lambda (largest Lyapunov exponent):
        > 0  chaotic
        ≈ 0  quasi-periodic / periodic
        < 0  converging to stable point
    """
    try:
        nodes = state['nodes']
        edges = state['edges']
        init = state['init']
        
        node_ids = [n['id'] for n in nodes]
        y0 = np.array([float(init.get(nid, 0.5)) for nid in node_ids])
        
        # Second trajectory perturbed slightly
        y0_perturbed = y0.copy()
        y0_perturbed[0] += perturbation
        
        ode_func, _, _ = _build_circuit_ode_system(nodes, edges, init)
        from scipy.integrate import solve_ivp
        
        # Run both trajectories with renormalization
        t_step = 1.0
        n_renormalize = int(t_end / t_step)
        log_sum = 0.0
        y_a = y0.copy()
        y_b = y0_perturbed.copy()
        d0 = perturbation
        
        for _ in range(n_renormalize):
            sol_a = solve_ivp(ode_func, (0, t_step), y_a,
                                 t_eval=[t_step], method='LSODA',
                                 rtol=1e-8, atol=1e-11)
            sol_b = solve_ivp(ode_func, (0, t_step), y_b,
                                 t_eval=[t_step], method='LSODA',
                                 rtol=1e-8, atol=1e-11)
            if not (sol_a.success and sol_b.success):
                break
            y_a = sol_a.y[:, -1]
            y_b = sol_b.y[:, -1]
            
            # Compute current divergence
            d = np.linalg.norm(y_b - y_a)
            if d < 1e-15:
                continue
            
            log_sum += np.log(d / d0)
            
            # Renormalize: pull b back to distance d0 from a
            y_b = y_a + (y_b - y_a) * (d0 / d)
        
        lyap = log_sum / (n_renormalize * t_step)
        return float(lyap), 'OK'
    except Exception as e:
        biosim_log('warn', 'estimate_lyapunov_exponent: {}'.format(e))
        return None, 'Lyapunov error: ' + str(e)[:120]



# ─────────────────────────────────────────────────────────────────────
# ORGANISM → COBRA MODEL
# The organism designer had its own resource-allocation model, which answers
# "does this fit in the cell" but not "what flux can actually be sustained".
# Building a real stoichiometric model lets the whole constraint-based toolkit
# already present in this file — FVA, pFBA, essential reactions, OptKnock,
# production envelopes, MOMA — apply to a designed organism.
#
# The network is a hand-built core model (~30 reactions: glycolysis, pentose
# phosphate, TCA, oxidative phosphorylation, a lumped biomass demand). It is
# NOT genome-scale, and every result should be read as an order-of-magnitude
# check rather than a prediction. A real genome-scale model can be downloaded
# separately (see download_bigg_model below).
# ─────────────────────────────────────────────────────────────────────

