def pam_matches(seq_window, pam_pattern):
    if len(seq_window) < len(pam_pattern):
        return False
    iupac = {'A':'A','C':'C','G':'G','T':'T','N':'ACGT','R':'AG','Y':'CT',
             'V':'ACG','W':'AT','S':'CG','K':'GT','M':'AC','B':'CGT','D':'AGT','H':'ACT'}
    for i, p in enumerate(pam_pattern):
        c = seq_window[i].upper()
        if c not in iupac.get(p, p):
            return False
    return True






def score_guide(guide):
    if not guide or len(guide) < 18:
        return 0
    score = 100.0
    gc = gc_content(guide)
    if gc < 30 or gc > 70:
        score -= 20
    elif gc < 40 or gc > 60:
        score -= 8
    for nt in 'ACGT':
        if nt * 4 in guide:
            score -= 15
        if nt * 5 in guide:
            score -= 10
    if len(guide) >= 4:
        last_four = guide[-4:]
        score -= 5 * last_four.count('T')
    if guide[0] == 'G':
        score += 5
    return max(0, min(100, round(score, 1)))


def find_crispr_targets(sequence, enzyme='SpCas9', max_sites=100):
    enz = CRISPR_ENZYMES.get(enzyme)
    if not enz:
        return []
    pam = enz['pam']
    guide_len = enz['guide_len']
    pam_len = len(pam)
    sequence = sequence.upper()
    results = []
    for i in range(guide_len, len(sequence) - pam_len + 1):
        window = sequence[i:i + pam_len]
        if pam_matches(window, pam):
            guide = sequence[i - guide_len:i]
            if 'N' in guide:
                continue
            results.append({
                'position': i - guide_len, 'strand': '+',
                'guide': guide, 'pam': window,
                'gc': gc_content(guide), 'score': score_guide(guide),
            })
    rc = reverse_complement(sequence)
    for i in range(guide_len, len(rc) - pam_len + 1):
        window = rc[i:i + pam_len]
        if pam_matches(window, pam):
            guide = rc[i - guide_len:i]
            if 'N' in guide:
                continue
            orig_pos = len(sequence) - (i - guide_len) - guide_len
            results.append({
                'position': orig_pos, 'strand': '-',
                'guide': guide, 'pam': window,
                'gc': gc_content(guide), 'score': score_guide(guide),
            })
    results.sort(key=lambda r: r['score'], reverse=True)
    return results[:max_sites]


def calc_off_targets(guide, full_sequence, max_mismatches=3):
    if not guide or not full_sequence:
        return {'count_0mm': 0, 'count_1mm': 0, 'count_2mm': 0, 'count_3mm': 0}
    guide_up = guide.upper()
    seq_up = full_sequence.upper()
    glen = len(guide_up)
    counts = {0: 0, 1: 0, 2: 0, 3: 0}
    for strand_seq in [seq_up, reverse_complement(seq_up)]:
        for i in range(len(strand_seq) - glen + 1):
            window = strand_seq[i:i + glen]
            if 'N' in window:
                continue
            mm = sum(1 for a, b in zip(guide_up, window) if a != b)
            if mm <= max_mismatches:
                counts[mm] = counts.get(mm, 0) + 1
    if counts[0] > 0:
        counts[0] -= 1
    return {'count_0mm': counts[0], 'count_1mm': counts[1],
            'count_2mm': counts[2], 'count_3mm': counts[3]}


def find_off_target_sites(guide, full_sequence, max_mismatches=4, limit=200):
    """Locate potential off-target sites and return their actual sequences.

    calc_off_targets only counted sites, which is not enough to judge risk: a
    site with four mismatches spread across the 5' end is nearly harmless,
    while three mismatches next to the PAM can still be cut efficiently. The
    sequences are needed so CFD can weight each one by position.
    """
    if not guide or not full_sequence:
        return []
    g = guide.upper()
    seq = full_sequence.upper()
    glen = len(g)
    hits = []
    for strand, strand_seq in (('+', seq), ('-', reverse_complement(seq))):
        for i in range(len(strand_seq) - glen + 1):
            window = strand_seq[i:i + glen]
            if 'N' in window:
                continue
            mm = 0
            for a, b in zip(g, window):
                if a != b:
                    mm += 1
                    if mm > max_mismatches:
                        break
            if mm <= max_mismatches:
                hits.append({'seq': window, 'mismatches': mm, 'strand': strand,
                             'position': i})
                if len(hits) >= limit:
                    return hits
    return hits


def guide_specificity_score(guide, full_sequence, max_mismatches=4):
    """Aggregate specificity of a guide, in the style of CRISPOR/MIT.

    Every off-target site is scored with CFD (how likely it is to actually be
    cut) and the totals are combined as 100/(1+sum). A guide with many easily
    cut off-targets scores low even if its on-target efficiency is excellent.

    Returns the score, the worst individual off-target, and the counts by
    mismatch number.
    """
    sites = find_off_target_sites(guide, full_sequence, max_mismatches)
    g = (guide or '').upper()
    total = 0.0
    worst = None
    counts = {0: 0, 1: 0, 2: 0, 3: 0, 4: 0}
    seen_perfect = False
    for site in sites:
        mm = site['mismatches']
        if mm == 0 and not seen_perfect:
            seen_perfect = True          # this is the on-target itself
            continue
        counts[mm] = counts.get(mm, 0) + 1
        try:
            cfd = cfd_off_target_score(g, site['seq'])
        except Exception as exc:
            biosim_log('warn', 'guide_specificity_score cfd: {}'.format(exc))
            cfd = 0.0
        total += cfd
        if worst is None or cfd > worst['cfd']:
            worst = {'cfd': cfd, 'seq': site['seq'], 'mismatches': mm,
                     'strand': site['strand'], 'position': site['position']}
    score = 100.0 / (1.0 + total) if total > 0 else 100.0
    return {'specificity': round(score, 1), 'worst': worst,
            'counts': counts, 'n_sites': len(sites),
            'cfd_sum': round(total, 3)}


def apply_crispr_edit(sequence, position, edit_type='knockout', insert_seq='', strand='+'):
    sequence = sequence.upper()
    if position < 0 or position >= len(sequence):
        return sequence, 'Position out of range'
    if edit_type == 'knockout':
        return sequence[:position] + 'A' + sequence[position:], 'Inserted A (frameshift knockout)'
    elif edit_type == 'deletion':
        start = max(0, position - 5)
        end = min(len(sequence), position + 5)
        return sequence[:start] + sequence[end:], 'Deleted 10 nt around cut'
    elif edit_type == 'insertion':
        if not insert_seq:
            insert_seq = 'ATG'
        return sequence[:position] + insert_seq.upper() + sequence[position:], 'Inserted {} nt'.format(len(insert_seq))
    elif edit_type == 'substitution':
        if not insert_seq:
            insert_seq = 'A'
        repl_len = len(insert_seq)
        return sequence[:position] + insert_seq.upper() + sequence[position + repl_len:], 'Substituted {} nt'.format(repl_len)
    return sequence, 'Unknown edit type'


def fetch_gene_sequence_ncbi(gene_symbol, species='Homo sapiens'):
    enc = urllib.parse.quote('{}[Gene Name] AND {}[Organism]'.format(gene_symbol, species))
    url = '{}/esearch.fcgi?db=nuccore&term={}&retmax=1&retmode=json'.format(NCBI, enc)
    data = _get(url)
    if not data:
        return None, None
    ids = data.get('esearchresult', {}).get('idlist', [])
    if not ids:
        return None, None
    nuc_id = ids[0]
    summary_url = '{}/esummary.fcgi?db=nuccore&id={}&retmode=json'.format(NCBI, nuc_id)
    summary = _get(summary_url)
    info = {}
    if summary:
        entry = summary.get('result', {}).get(nuc_id, {})
        info = {'title': entry.get('title', ''), 'length': entry.get('slen', 0),
                'accession': entry.get('accessionversion', ''),
                'organism': species, 'gene': gene_symbol}
    fasta_url = '{}/efetch.fcgi?db=nuccore&id={}&rettype=fasta&retmode=text&seq_start=1&seq_stop=5000'.format(NCBI, nuc_id)
    fasta = _get_text(fasta_url)
    if not fasta:
        return None, info
    lines = fasta.strip().split('\n')
    seq_lines = [l.strip() for l in lines if not l.startswith('>')]
    return ''.join(seq_lines), info




# ─────────────────────────────────────────────────────────────────────
# REFERENCE SEQUENCE RETRIEVAL
# The disease workspace used to invent a gene sequence with random.choice,
# then design guides against that noise and report efficiency scores for it.
# Everything below fetches the real coding sequence by RefSeq accession and
# caches it on disk. If the sequence cannot be obtained, the caller is told
# so — no sequence is ever fabricated.
# ─────────────────────────────────────────────────────────────────────

_REFSEQ_MEM_CACHE = {}


def _refseq_cache_dir():
    d = os.path.join(get_biosim_dir(), 'refseq_cache')
    try:
        os.makedirs(d, exist_ok=True)
    except Exception as exc:
        biosim_log('warn', 'refseq cache dir: {}'.format(exc))
    return d


def _refseq_cache_path(gene):
    safe = ''.join(c for c in str(gene) if c.isalnum() or c in '._-')
    return os.path.join(_refseq_cache_dir(), safe + '.json')


def load_cached_reference(gene):
    """Return a previously downloaded reference, or None."""
    if gene in _REFSEQ_MEM_CACHE:
        return _REFSEQ_MEM_CACHE[gene]
    path = _refseq_cache_path(gene)
    try:
        if os.path.exists(path):
            with open(path, 'r') as fh:
                data = json.load(fh)
            if data.get('sequence'):
                _REFSEQ_MEM_CACHE[gene] = data
                return data
    except Exception as exc:
        biosim_log('warn', 'refseq cache read {}: {}'.format(gene, exc))
    return None


def _save_cached_reference(gene, data):
    try:
        with open(_refseq_cache_path(gene), 'w') as fh:
            json.dump(data, fh)
        _REFSEQ_MEM_CACHE[gene] = data
    except Exception as exc:
        biosim_log('warn', 'refseq cache write {}: {}'.format(gene, exc))


def fetch_reference_cds(gene, force=False):
    """Download the coding sequence of a disease gene from NCBI.

    Returns {'sequence', 'accession', 'gene', 'source', 'error'}. On failure
    'sequence' is empty and 'error' explains why — the caller must show that
    rather than substituting something made up.
    """
    if not force:
        cached = load_cached_reference(gene)
        if cached:
            return cached

    info = DISEASE_GENE_REFSEQ.get(gene)
    if not info:
        return {'sequence': '', 'accession': '', 'gene': gene, 'source': '',
                'error': 'Для гена {} нет референсной записи в базе'.format(gene)}

    acc = info['refseq']
    # fasta_cds_na gives the coding sequence only, so CDS coordinates such as
    # c.20A>T index directly into it.
    url = ('{}/efetch.fcgi?db=nuccore&id={}&rettype=fasta_cds_na&retmode=text'
           .format(NCBI, acc))
    text = _get_text(url)
    if not text or '>' not in text:
        # Fall back to the full mRNA record.
        url2 = ('{}/efetch.fcgi?db=nuccore&id={}&rettype=fasta&retmode=text'
                .format(NCBI, acc))
        text = _get_text(url2)
        if not text or '>' not in text:
            return {'sequence': '', 'accession': acc, 'gene': gene,
                    'source': 'NCBI',
                    'error': 'Не удалось загрузить {} из NCBI. '
                             'Проверьте подключение к интернету.'.format(acc)}

    blocks = [b for b in text.split('>') if b.strip()]
    header, seq = '', ''
    for b in blocks:
        lines = b.strip().split('\n')
        candidate = ''.join(l.strip() for l in lines[1:])
        candidate = ''.join(c for c in candidate.upper() if c in 'ACGTN')
        if len(candidate) > len(seq):
            header, seq = lines[0], candidate
    if not seq:
        return {'sequence': '', 'accession': acc, 'gene': gene, 'source': 'NCBI',
                'error': 'Запись {} получена, но последовательность пуста'.format(acc)}

    data = {'sequence': seq, 'accession': acc, 'gene': gene, 'source': 'NCBI',
            'header': header[:200], 'length': len(seq), 'error': None}
    _save_cached_reference(gene, data)
    biosim_log('info', 'reference CDS loaded: {} {} ({} bp)'.format(
        gene, acc, len(seq)))
    return data


def reference_variant_sequence(gene):
    """Build the patient (mutant) sequence from the reference plus the known
    pathogenic variant, so the user starts from the diseased allele exactly
    as a real project would.

    Returns (mutant_sequence, reference_sequence, note). If the variant cannot
    be applied precisely (repeat expansions, inversions, whole-exon deletions),
    the reference is returned unchanged together with an explanation, instead
    of pretending an edit site exists.
    """
    ref = fetch_reference_cds(gene)
    if ref.get('error') or not ref.get('sequence'):
        return '', '', ref.get('error') or 'Референс недоступен'

    seq = ref['sequence']
    info = DISEASE_GENE_REFSEQ.get(gene, {})
    vt = info.get('variant_type')
    pos = info.get('cds_pos')
    ref_b = info.get('ref_base') or ''
    alt_b = info.get('alt_base') or ''

    if vt == 'point' and pos and pos <= len(seq):
        i = pos - 1
        if seq[i] == ref_b:
            mutant = seq[:i] + alt_b + seq[i + 1:]
            return mutant, seq, ('Патогенный вариант {} внесён в позицию {}'
                                 .format(info.get('variant', ''), pos))
        return seq, seq, ('В позиции {} референса стоит {}, а не {} — '
                          'нумерация записи отличается, вариант не внесён'
                          .format(pos, seq[i], ref_b))
    if vt == 'deletion' and pos and ref_b:
        i = pos - 1
        if seq[i:i + len(ref_b)] == ref_b:
            mutant = seq[:i] + seq[i + len(ref_b):]
            return mutant, seq, ('Делеция {} внесена в позицию {}'
                                 .format(ref_b, pos))
        return seq, seq, ('Ожидалось {} в позиции {} — не совпало, '
                          'делеция не внесена'.format(ref_b, pos))
    if vt == 'insertion' and pos and alt_b:
        i = pos - 1
        mutant = seq[:i] + alt_b + seq[i:]
        return mutant, seq, ('Дупликация {} внесена в позицию {}'
                             .format(alt_b, pos))

    reason = {
        'repeat': 'Расширение повторов не моделируется на уровне CDS — '
                  'показан нормальный референс',
        'inversion': 'Инверсия затрагивает интрон и не видна в CDS — '
                     'показан нормальный референс',
        'exon_deletion': 'Делеция экзона зависит от пациента — '
                         'показан полный референс',
        'heterogeneous': 'У этого гена много разных мутаций — '
                         'показан нормальный референс',
        'target_only': 'Это терапевтическая мишень, а не мутантный ген — '
                       'показан нормальный референс',
    }.get(vt, 'Вариант не внесён')
    return seq, seq, reason


AA_TO_CODON_HUMAN = {
    'A':'GCC','R':'CGG','N':'AAC','D':'GAC','C':'TGC','E':'GAG','Q':'CAG',
    'G':'GGC','H':'CAC','I':'ATC','L':'CTG','K':'AAG','M':'ATG','F':'TTC',
    'P':'CCC','S':'AGC','T':'ACC','W':'TGG','Y':'TAC','V':'GTG','*':'TAA',
}

def back_translate_protein(aa_seq):
    aa_seq = aa_seq.upper().replace(' ', '').replace('\n', '')
    dna = ''
    for aa in aa_seq:
        if aa in AA_TO_CODON_HUMAN:
            dna += AA_TO_CODON_HUMAN[aa]
        elif aa.isalpha():
            dna += 'NNN'
    return dna

def is_protein_sequence(seq):
    seq = seq.upper().replace(' ', '').replace('\n', '')
    if not seq:
        return False
    dna_chars = set('ACGTN')
    non_dna = sum(1 for c in seq if c.isalpha() and c not in dna_chars)
    return non_dna > len(seq) * 0.1


