class Toast:
    """Toast notification - small message that appears at bottom and fades out.
    Replaces messagebox for non-critical messages.
    
    Usage:
        Toast.show(parent, 'Saved successfully', level='success')
    
    Levels:
        'info' (blue), 'success' (green), 'warn' (yellow), 'error' (red)
    """
    _active_toasts = []  # stack of currently visible toasts
    _next_id = 0

    LEVEL_STYLES = {
        'info':    {'bg': '#0969da', 'fg': 'white',     'icon': 'ℹ'},
        'success': {'bg': '#1a7f37', 'fg': 'white',     'icon': ''},
        'warn':    {'bg': '#9e6a03', 'fg': 'white',     'icon': ''},
        'error':   {'bg': '#cf222e', 'fg': 'white',     'icon': ''},
    }

    @classmethod
    def show(cls, parent, message, level='info', duration=3000, action=None, action_label=None):
        """Show a toast. Returns the toast window.
        
        action: optional callable to invoke when action button is clicked
        action_label: text for action button (e.g. 'Undo', 'View')
        duration: ms before auto-dismiss (0 = no auto-dismiss)
        """
        try:
            # Find top-level window
            top = parent.winfo_toplevel()
        except Exception as _exc:
            biosim_log('warn', 'show: {}'.format(_exc))
            return None
        
        style = cls.LEVEL_STYLES.get(level, cls.LEVEL_STYLES['info'])
        
        # Position: bottom-right of parent
        toast = tk.Toplevel(top)
        toast.wm_overrideredirect(True)
        toast.configure(bg=style['bg'])
        toast.attributes('-topmost', True)
        
        # Content
        frame = tk.Frame(toast, bg=style['bg'])
        frame.pack(padx=2, pady=2)
        
        # Icon + message
        tk.Label(frame, text=style['icon'], bg=style['bg'], fg=style['fg'],
                  font=('Arial', 14, 'bold')).pack(side='left', padx=(12, 6), pady=8)
        tk.Label(frame, text=message, bg=style['bg'], fg=style['fg'],
                  font=('Arial', 10), wraplength=350,
                  justify='left').pack(side='left', padx=(0, 10), pady=8)
        
        # Optional action button
        if action and action_label:
            def do_action():
                try: action()
                except Exception as _exc:
                    biosim_log('warn', 'do_action: {}'.format(_exc))
                    pass
                cls._dismiss_toast(toast)
            tk.Button(frame, text=action_label,
                       bg=style['bg'], fg=style['fg'],
                       relief='flat', cursor='hand2',
                       font=('Arial', 9, 'bold', 'underline'),
                       activebackground=style['bg'],
                       activeforeground='#ffffff',
                       command=do_action).pack(side='left', padx=(0, 8))
        
        # Close X
        tk.Label(frame, text='', bg=style['bg'], fg=style['fg'],
                  font=('Arial', 9), cursor='hand2'
                  ).pack(side='left', padx=(0, 10))
        
        # Make whole toast clickable to dismiss
        def dismiss(e=None):
            cls._dismiss_toast(toast)
        toast.bind('<Button-1>', dismiss)
        for w in [frame] + list(frame.winfo_children()):
            try: w.bind('<Button-1>', dismiss)
            except Exception as _exc:
                biosim_log('warn', 'show: {}'.format(_exc))
                pass
        
        # Position at bottom-center of parent window
        try:
            top.update_idletasks()
            toast.update_idletasks()
            pw = top.winfo_width()
            ph = top.winfo_height()
            px = top.winfo_rootx()
            py = top.winfo_rooty()
            tw = toast.winfo_width()
            th = toast.winfo_height()
            
            # Stack from bottom, offset by number of active toasts
            stack_offset = sum(t.winfo_height() + 8 for t in cls._active_toasts
                                 if t.winfo_exists()) if cls._active_toasts else 0
            
            x = px + (pw - tw) // 2
            y = py + ph - th - 30 - stack_offset
            toast.geometry('+{}+{}'.format(max(0, x), max(0, y)))
        except Exception as _exc:
            biosim_log('warn', 'show: {}'.format(_exc))
        
        cls._active_toasts.append(toast)
        
        # Auto-dismiss
        if duration > 0:
            toast.after(duration, lambda: cls._dismiss_toast(toast))
        
        return toast

    @classmethod
    def _dismiss_toast(cls, toast):
        try:
            if toast in cls._active_toasts:
                cls._active_toasts.remove(toast)
        except Exception as _exc:
            biosim_log('warn', '_dismiss_toast: {}'.format(_exc))
            pass
        try:
            toast.destroy()
        except Exception as _exc:
            biosim_log('warn', '_dismiss_toast: {}'.format(_exc))
            pass


class CircuitAnimator:
    """Real-time animation engine for circuit visualization during simulation.
    
    Features:
        - Molecules flow as dots along edges
        - Nodes pulse/glow proportional to concentration
        - Color intensity reflects current state
        - Play/Pause/Speed controls
        - Optional GIF recording
    
    Usage:
        animator = CircuitAnimator(canvas, state, time_array, y_array, node_ids)
        animator.start()
        # ... user clicks pause/play, changes speed
        animator.stop()
    """

    def __init__(self, canvas, state, t_array, y_array, node_ids,
                  node_positions=None, on_complete=None):
        self.canvas = canvas
        self.state = state
        self.t = np.asarray(t_array)
        self.y = np.asarray(y_array)
        self.node_ids = list(node_ids)
        self.on_complete = on_complete
        self.node_positions = node_positions or {
            n['id']: (n.get('x', 200), n.get('y', 200))
            for n in state.get('nodes', [])
        }
        # Animation state
        self.current_step = 0
        self.playing = False
        self.speed = 1.0  # frames per call (1.0 = normal)
        self.frame_delay = 60  # ms between frames
        self.particle_count = 4  # particles per edge
        self._after_id = None
        self._particles = []  # list of (edge, position 0-1, color, size)
        # Drawing IDs for cleanup
        self._anim_items = []
        # Min/max for scaling colors
        self._y_min = float(self.y.min()) if self.y.size else 0
        self._y_max = float(self.y.max()) if self.y.size else 1
        if self._y_max - self._y_min < 1e-9:
            self._y_max = self._y_min + 1.0
        # GIF recording
        self.recording = False
        self.recorded_frames = []

    def start(self):
        """Start playback from current step."""
        self.playing = True
        self._tick()

    def stop(self):
        """Pause playback."""
        self.playing = False
        if self._after_id is not None:
            try: self.canvas.after_cancel(self._after_id)
            except Exception as _exc:
                biosim_log('warn', 'stop: {}'.format(_exc))
                pass
            self._after_id = None

    def reset(self):
        """Reset to beginning."""
        self.stop()
        self.current_step = 0
        self._particles = []
        self._draw_frame()

    def set_speed(self, speed):
        """Set playback speed (0.5 = slow, 1.0 = normal, 4.0 = fast)."""
        self.speed = max(0.1, min(10.0, speed))

    def jump_to(self, step):
        """Jump to specific step in the simulation."""
        self.current_step = max(0, min(len(self.t) - 1, step))
        self._draw_frame()

    def _tick(self):
        """One animation frame."""
        if not self.playing:
            return
        # Advance time
        step_increment = max(1, int(self.speed))
        self.current_step += step_increment
        if self.current_step >= len(self.t):
            self.current_step = len(self.t) - 1
            self.playing = False
            if self.on_complete:
                try: self.on_complete()
                except Exception as _exc:
                    biosim_log('warn', '_tick: {}'.format(_exc))
                    pass
            return
        # Update particles (flow along edges)
        self._update_particles()
        # Draw
        self._draw_frame()
        # Schedule next
        self._after_id = self.canvas.after(self.frame_delay, self._tick)

    def _update_particles(self):
        """Move existing particles along edges, spawn new ones."""
        # Move existing particles forward
        new_particles = []
        for p in self._particles:
            edge, pos, color, size = p
            pos += 0.04 * self.speed
            if pos < 1.0:
                new_particles.append((edge, pos, color, size))
        self._particles = new_particles
        # Spawn new particles based on edge activity
        edges = self.state.get('edges', [])
        for e in edges:
            from_id = e.get('from')
            to_id = e.get('to')
            if from_id not in self.node_ids:
                continue
            from_idx = self.node_ids.index(from_id)
            # Concentration of source determines particle spawn rate
            conc = float(self.y[self.current_step, from_idx])
            spawn_prob = (conc - self._y_min) / (self._y_max - self._y_min) * 0.4
            if np.random.random() < spawn_prob:
                etype = e.get('type', 'activation')
                color = '#1a7f37' if etype == 'activation' else '#cf222e'
                size = 4 + int(spawn_prob * 6)
                self._particles.append((e, 0.0, color, size))

    def _draw_frame(self):
        """Redraw all animation overlays."""
        # Clear previous animation overlays
        for item in self._anim_items:
            try: self.canvas.delete(item)
            except Exception as _exc:
                biosim_log('warn', '_draw_frame: {}'.format(_exc))
                pass
        self._anim_items = []
        # Draw glow on each node based on concentration
        for i, nid in enumerate(self.node_ids):
            if nid not in self.node_positions:
                continue
            x, y = self.node_positions[nid]
            conc = float(self.y[self.current_step, i])
            # Normalize 0-1
            normalized = (conc - self._y_min) / (self._y_max - self._y_min)
            normalized = max(0, min(1, normalized))
            # Glow radius and color
            glow_r = 25 + int(normalized * 25)
            # Color: low = blue (cold), mid = yellow, high = red (hot)
            r = int(60 + normalized * 195)
            g = int(150 + (1 - abs(normalized - 0.5) * 2) * 80)
            b = int(255 - normalized * 200)
            color = '#{:02x}{:02x}{:02x}'.format(r, g, b)
            # Outer glow (semi-transparent simulated via outline)
            for glow_step in range(3):
                gr = glow_r - glow_step * 6
                if gr > 0:
                    item = self.canvas.create_oval(
                        x - gr, y - gr, x + gr, y + gr,
                        outline=color, width=2 - glow_step,
                        fill='')
                    self._anim_items.append(item)
            # Concentration label
            label = self.canvas.create_text(
                x, y - glow_r - 12,
                text='{:.2f}'.format(conc),
                fill=color, font=('Arial', 9, 'bold'))
            self._anim_items.append(label)
        # Draw particles flowing along edges
        for edge, pos, color, size in self._particles:
            from_id = edge.get('from')
            to_id = edge.get('to')
            if from_id not in self.node_positions or to_id not in self.node_positions:
                continue
            x1, y1 = self.node_positions[from_id]
            x2, y2 = self.node_positions[to_id]
            px = x1 + (x2 - x1) * pos
            py = y1 + (y2 - y1) * pos
            # Particle as glowing dot
            item = self.canvas.create_oval(
                px - size, py - size, px + size, py + size,
                fill=color, outline='#ffffff', width=1)
            self._anim_items.append(item)
        # Time label
        t_now = float(self.t[self.current_step])
        t_max = float(self.t[-1])
        time_item = self.canvas.create_text(
            10, 10,
            text='⏱  t = {:.2f} / {:.2f}'.format(t_now, t_max),
            anchor='nw',
            fill='#1a7f37', font=('Courier', 11, 'bold'))
        self._anim_items.append(time_item)
        # Step indicator
        step_item = self.canvas.create_text(
            10, 28,
            text='⏯  step {} / {}'.format(self.current_step + 1, len(self.t)),
            anchor='nw',
            fill='#57606a', font=('Courier', 9))
        self._anim_items.append(step_item)
        # Record frame if requested
        if self.recording:
            self._capture_frame()

    def _capture_frame(self):
        """Capture current canvas state as PostScript for GIF assembly."""
        try:
            ps = self.canvas.postscript(colormode='color')
            self.recorded_frames.append(ps)
        except Exception as _exc:
            biosim_log('warn', '_capture_frame: {}'.format(_exc))

    def start_recording(self):
        """Start recording frames for GIF export."""
        self.recording = True
        self.recorded_frames = []

    def save_recording(self, filepath):
        """Save recorded frames as GIF (requires PIL + Ghostscript)."""
        if not self.recorded_frames:
            return False, 'No frames recorded'
        try:
            from PIL import Image
            import tempfile, io
            images = []
            for ps_data in self.recorded_frames:
                fd, tmp_ps = tempfile.mkstemp(suffix='.ps')
                with os.fdopen(fd, 'w', encoding='utf-8') as f:
                    f.write(ps_data)
                img = Image.open(tmp_ps)
                img.load()
                images.append(img.convert('RGB'))
                os.remove(tmp_ps)
            if images:
                images[0].save(filepath, save_all=True,
                                 append_images=images[1:],
                                 duration=100, loop=0,
                                 optimize=True)
                return True, 'Saved {} frames'.format(len(images))
            return False, 'No frames to save'
        except ImportError as _exc:
            biosim_log('warn', 'save_recording: {}'.format(_exc))
            return False, 'PIL not installed'
        except Exception as e:
            biosim_log('warn', 'save_recording: {}'.format(e))
            return False, 'Error: ' + str(e)[:80]

    def clear(self):
        """Remove all animation overlays."""
        for item in self._anim_items:
            try: self.canvas.delete(item)
            except Exception as _exc:
                biosim_log('warn', 'clear: {}'.format(_exc))
                pass
        self._anim_items = []
        self._particles = []


class HelpWindow(tk.Toplevel):
    """Context-sensitive help window. Shows glossary entries with formatted text.
    
    Usage:
        HelpWindow(parent, lang='ru', topic='hill_n')  # specific topic
        HelpWindow(parent, lang='ru')                    # full glossary
    """

    def __init__(self, parent, lang='ru', topic=None):
        super().__init__(parent)
        self.lang = lang if lang in ('ru', 'en') else 'en'
        self.title('' + ('Справка VIREON' if self.lang == 'ru' else 'VIREON Help'))
        self.geometry('820x600')
        self.configure(bg=biosim_theme('bg'))
        self.transient(parent)
        self.current_topic = topic

        # Header
        header = tk.Frame(self, bg=biosim_theme('bg'))
        header.pack(fill='x', pady=8)
        tk.Label(header,
                  text=('Справка VIREON' if self.lang == 'ru' else 'VIREON Help'),
                  bg=biosim_theme('bg'), fg='#0550ae',
                  font=('Arial', 16, 'bold')).pack()
        tk.Label(header,
                  text=('Объяснения всех терминов и параметров'
                        if self.lang == 'ru' else
                        'Explanations of all terms and parameters'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()

        # Search row
        search_row = tk.Frame(self, bg=biosim_theme('bg'))
        search_row.pack(fill='x', padx=14, pady=4)
        tk.Label(search_row,
                  text=('Поиск:' if self.lang == 'ru' else 'Search:'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        self.search_var = tk.StringVar()
        self.search_var.trace('w', lambda *a: self._update_topic_list())
        tk.Entry(search_row, textvariable=self.search_var,
                  bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                  relief='flat', font=('Arial', 10),
                  highlightthickness=1, highlightbackground=biosim_theme('border')
                  ).pack(side='left', fill='x', expand=True, padx=4, ipady=3)

        # Main split: topic list (left) + content (right)
        main = tk.Frame(self, bg=biosim_theme('bg'))
        main.pack(fill='both', expand=True, padx=14, pady=4)

        # Topics list on left
        list_frame = tk.Frame(main, bg=biosim_theme('panel'), width=220)
        list_frame.pack(side='left', fill='y', padx=(0, 6))
        list_frame.pack_propagate(False)

        tk.Label(list_frame,
                  text=('Темы' if self.lang == 'ru' else 'Topics'),
                  bg=biosim_theme('panel'), fg='#1a7f37',
                  font=('Arial', 10, 'bold')).pack(pady=(8, 4))

        list_canv = tk.Canvas(list_frame, bg=biosim_theme('panel'), highlightthickness=0)
        list_sb = tk.Scrollbar(list_frame, orient='vertical', command=list_canv.yview)
        list_canv.configure(yscrollcommand=list_sb.set)
        list_canv.pack(side='left', fill='both', expand=True)
        list_sb.pack(side='right', fill='y')
        self.list_inner = tk.Frame(list_canv, bg=biosim_theme('panel'))
        self.list_inner.bind('<Configure>',
                                lambda e: list_canv.configure(scrollregion=list_canv.bbox('all')))
        list_canv.create_window((0, 0), window=self.list_inner,
                                   anchor='nw', width=200)

        # Content area on right
        content_frame = tk.Frame(main, bg=biosim_theme('bg'))
        content_frame.pack(side='right', fill='both', expand=True)
        self.content_txt = scrolledtext.ScrolledText(
            content_frame, bg=biosim_theme('panel'), fg=biosim_theme('text'),
            font=('Arial', 11), relief='flat',
            wrap='word', highlightthickness=0,
            padx=14, pady=10)
        self.content_txt.pack(fill='both', expand=True)

        # Configure tags for formatting
        self.content_txt.tag_config('h1', foreground='#0550ae',
                                       font=('Arial', 16, 'bold'),
                                       spacing3=8)
        self.content_txt.tag_config('h2', foreground='#1a7f37',
                                       font=('Arial', 12, 'bold'),
                                       spacing1=8, spacing3=4)
        self.content_txt.tag_config('symbol', foreground='#8250df',
                                       font=('Courier', 13, 'bold'))
        self.content_txt.tag_config('units', foreground='#9a6700',
                                       font=('Courier', 10))
        self.content_txt.tag_config('range', foreground='#8250df',
                                       font=('Courier', 10))
        self.content_txt.tag_config('eq', foreground='#bc4c00',
                                       font=('Courier', 11, 'bold'))
        self.content_txt.tag_config('desc', foreground=biosim_theme('text'),
                                       font=('Arial', 11), spacing1=4)
        self.content_txt.tag_config('section', foreground=biosim_theme('text_dim'),
                                        font=('Arial', 10, 'bold'),
                                        spacing1=10, spacing3=2)

        # Close button
        tk.Button(self, text='Закрыть' if self.lang == 'ru' else 'Close',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=self.destroy
                   ).pack(fill='x', padx=14, pady=(4, 10))

        self._update_topic_list()
        if topic:
            self._show_topic(topic)
        else:
            self._show_overview()

    def _update_topic_list(self):
        """Refresh the left topic list (filtered by search)."""
        for w in self.list_inner.winfo_children():
            w.destroy()

        q = self.search_var.get().lower().strip()

        # Categories
        categories = [
            ('Parameters' if self.lang == 'en' else 'Параметры',
              ['production', 'degradation', 'strength', 'hill_n']),
            ('DNA parts' if self.lang == 'en' else 'ДНК элементы',
              ['promoter', 'rbs', 'cds', 'terminator', 'binding_site']),
            ('Regulation' if self.lang == 'en' else 'Регуляция',
              ['repression', 'activation']),
            ('Methods' if self.lang == 'en' else 'Методы',
              ['ode_simulation', 'gillespie', 'tau_leap', 'steady_state',
                'bifurcation', 'fba', 'fva', 'parameter_fitting',
                'sensitivity', 'gene_knockout']),
            ('Motifs' if self.lang == 'en' else 'Мотивы',
              ['toggle_switch', 'repressilator', 'feedforward_loop']),
            ('CRISPR' if self.lang == 'en' else 'CRISPR',
              ['crispr_guides', 'crispr_efficiency', 'crispr_donor',
               'crispr_indels', 'crispr_organisms']),
            ('Metabolism' if self.lang == 'en' else 'Метаболизм',
              ['metabolic_pathways', 'pathway_yield', 'pathway_bottleneck']),
            ('Tools' if self.lang == 'en' else 'Инструменты',
              ['circuit_modules', 'dna_generation', 'knockout_element']),
        ]

        for cat_name, keys in categories:
            visible_keys = []
            for k in keys:
                if k not in BIOSIM_GLOSSARY:
                    continue
                entry = BIOSIM_GLOSSARY[k]
                name = entry.get('name_ru' if self.lang == 'ru' else 'name_en', k)
                if q and q not in name.lower() and q not in k.lower():
                    if q not in entry.get('description_ru' if self.lang == 'ru'
                                              else 'description_en', '').lower():
                        continue
                visible_keys.append(k)

            if not visible_keys:
                continue

            tk.Label(self.list_inner, text=cat_name,
                      bg=biosim_theme('panel'), fg='#0550ae',
                      font=('Arial', 9, 'bold'),
                      anchor='w').pack(fill='x', padx=8, pady=(8, 2))

            for k in visible_keys:
                entry = BIOSIM_GLOSSARY[k]
                name = entry.get('name_ru' if self.lang == 'ru' else 'name_en', k)
                btn = tk.Label(self.list_inner, text='  · ' + name[:28],
                                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                 font=('Arial', 9), anchor='w', cursor='hand2')
                btn.pack(fill='x', padx=4)
                btn.bind('<Button-1>', lambda e, key=k: self._show_topic(key))
                btn.bind('<Enter>', lambda e, b=btn: b.config(fg='#0969da'))
                btn.bind('<Leave>', lambda e, b=btn: b.config(fg=biosim_theme('text')))

    def _show_overview(self):
        """Show overview when no specific topic selected."""
        self.content_txt.config(state='normal')
        self.content_txt.delete('1.0', 'end')
        if self.lang == 'ru':
            self.content_txt.insert('end', 'Справка VIREON\n', 'h1')
            self.content_txt.insert('end',
                '\nВыбери тему слева чтобы прочитать про неё.\n\n', 'desc')
            self.content_txt.insert('end', 'Что есть в справке:\n', 'section')
            self.content_txt.insert('end',
                '• Параметры — что значит production, hill_n, и т.д.\n'
                '• ДНК элементы — промоторы, RBS, CDS, терминаторы\n'
                '• Регуляция — активация, репрессия\n'
                '• Методы — ODE, Gillespie, FBA, bifurcation\n'
                '• Мотивы — toggle switch, repressilator, FFL\n'
                '• CRISPR — гайды, эффективность, донор, indel, организмы\n'
                '• Метаболизм — пути, выход продукта, узкие места\n'
                '• Инструменты — модули, генерация ДНК, нокаут\n\n', 'desc')
            self.content_txt.insert('end', 'Горячие клавиши:\n', 'section')
            self.content_txt.insert('end',
                '• F1 на любом узле справка про этот тип\n'
                '• Ctrl+F поиск узлов\n'
                '• Ctrl+S сохранить\n'
                '• Ctrl+Z отменить\n'
                '• Ctrl+L консоль логов\n', 'desc')
        else:
            self.content_txt.insert('end', 'VIREON Help\n', 'h1')
            self.content_txt.insert('end',
                '\nSelect a topic on the left to read about it.\n\n', 'desc')
            self.content_txt.insert('end', 'What\'s in the help:\n', 'section')
            self.content_txt.insert('end',
                '• Parameters — what production, hill_n etc. mean\n'
                '• DNA parts — promoters, RBS, CDS, terminators\n'
                '• Regulation — activation, repression\n'
                '• Methods — ODE, Gillespie, FBA, bifurcation\n'
                '• Motifs — toggle switch, repressilator, FFL\n'
                '• CRISPR — guides, efficiency, donor, indels, organisms\n'
                '• Metabolism — pathways, yield, bottlenecks\n'
                '• Tools — modules, DNA generation, knockout\n\n', 'desc')
            self.content_txt.insert('end', 'Hotkeys:\n', 'section')
            self.content_txt.insert('end',
                '• F1 on any node help about that type\n'
                '• Ctrl+F find nodes\n'
                '• Ctrl+S save\n'
                '• Ctrl+Z undo\n'
                '• Ctrl+L log console\n', 'desc')
        self.content_txt.config(state='disabled')

    def _show_topic(self, topic_key):
        """Display a specific glossary entry."""
        entry = BIOSIM_GLOSSARY.get(topic_key)
        if not entry:
            self._show_overview()
            return
        self.current_topic = topic_key
        self.content_txt.config(state='normal')
        self.content_txt.delete('1.0', 'end')

        name = entry.get('name_ru' if self.lang == 'ru' else 'name_en', topic_key)
        self.content_txt.insert('end', name + '\n', 'h1')

        if 'symbol' in entry:
            self.content_txt.insert('end',
                ('Символ: ' if self.lang == 'ru' else 'Symbol: '), 'section')
            self.content_txt.insert('end', entry['symbol'] + '\n', 'symbol')

        if 'units' in entry:
            label = 'Единицы: ' if self.lang == 'ru' else 'Units: '
            units = entry['units' if self.lang == 'ru' else 'units_en']
            self.content_txt.insert('end', label, 'section')
            self.content_txt.insert('end', units + '\n', 'units')

        if 'typical_range' in entry:
            label = 'Типичный диапазон: ' if self.lang == 'ru' else 'Typical range: '
            self.content_txt.insert('end', label, 'section')
            self.content_txt.insert('end', entry['typical_range'] + '\n', 'range')

        if 'equation' in entry:
            self.content_txt.insert('end',
                '\nУравнение:\n' if self.lang == 'ru' else '\nEquation:\n', 'section')
            self.content_txt.insert('end',
                '    ' + entry['equation'] + '\n', 'eq')

        # Description
        self.content_txt.insert('end',
            '\nОписание\n' if self.lang == 'ru' else '\nDescription\n', 'h2')
        desc = entry.get('description_ru' if self.lang == 'ru' else 'description_en', '')
        self.content_txt.insert('end', desc + '\n', 'desc')

        self.content_txt.config(state='disabled')


def get_node_help_topic(node):
    """Map a node to its glossary topic based on icon."""
    icon_to_topic = {
        'promoter': 'promoter',
        'rbs': 'rbs',
        'cds': 'cds',
        'terminator': 'terminator',
        'binding_site': 'binding_site',
        'tag': 'cds',
    }
    return icon_to_topic.get(node.get('icon', ''), None)


