    def _t(self, key):
        """Get translation for current language."""
        return self.TR.get(self.lang, self.TR['en']).get(key, key)

    def __init__(self, parent, lang='ru'):
        super().__init__(parent)
        self.lang = lang if lang in ('ru', 'en') else 'en'
        self.title(self._t('title'))
        self.geometry('1100x720')
        self.configure(bg=biosim_theme('bg'))
        self.minsize(900, 600)
        self.history = {'constructor': [], 'crispr': [], 'metabolic': [],
                        'circuit': [], 'plasmid': []}
        self.future = {'constructor': [], 'crispr': [], 'metabolic': [],
                       'circuit': [], 'plasmid': []}
        self.current_state = {'constructor': None, 'crispr': None, 'metabolic': None,
                              'circuit': None, 'plasmid': None}
        # Multi-canvas support for the constructor. The tools, library and
        # toolbar always operate on current_state['constructor'], which is kept
        # pointing at whichever canvas is active — so none of the ~126 existing
        # constructor functions need to change. The full list lives here, and
        # switching canvases just saves the active one back and swaps the
        # pointer. (Same idea as TinkerCell's allNetworks + currentNetwork.)
        self._cons_canvases = []       # list of constructor-state dicts
        self._cons_active_canvas = 0   # index into _cons_canvases
        self.active_tab = 'constructor'
        # ─── Project save/load state ───
        self._current_project_path = None
        self._redo_stack = {'constructor': []}
        self._simulation_history = []
        # ─── Onboarding state ───
        self._onboarding_step = 0
        self._onboarding_active = False
        self._build_toolbar()
        self._build_tabs()
        biosim_log('info', 'VIREON Constructor opened')
        # Start auto-save every 5 minutes
        self._schedule_autosave()
        # Save on close
        self.protocol('WM_DELETE_WINDOW', self._on_close_synbio)
        # Show welcome screen overlay on first launch (after 200ms so UI renders first)
        self.after(200, self._maybe_show_welcome)

    def _maybe_show_welcome(self):
        """Welcome screen is NOT shown automatically on startup — it used to
        pop up over the tabs and block the Metabolism/Organism sections. The
        welcome screen is still available on demand via the 'Главная' / 'Home'
        button in the toolbar."""
        return

    def _schedule_autosave(self):
        """Periodically save current state to ~/.biosim/autosave.biosim."""
        try:
            state = self.current_state.get('constructor')
            if state and state.get('nodes'):
                autosave_project(self.current_state,
                                  extra_data={'simulation_history':
                                              getattr(self, '_simulation_history', [])})
                biosim_log('info', 'Auto-saved')
                # Pulse the autosave indicator briefly
                try:
                    self._sb_autosave.config(fg='#0969da')
                    self.after(800, lambda: self._sb_autosave.config(fg='#1a7f37'))
                except Exception as _exc:
                    biosim_log('warn', '_schedule_autosave: {}'.format(_exc))
                    pass
        except Exception as e:
            biosim_log('error', 'Autosave failed: ' + str(e))
        # Schedule next autosave (5 minutes = 300000 ms)
        self.after(300000, self._schedule_autosave)

    def _on_close_synbio(self):
        """Save autosave before closing."""
        try:
            autosave_project(self.current_state,
                              extra_data={'simulation_history':
                                          getattr(self, '_simulation_history', [])})
            biosim_log('info', 'Auto-saved on close')
        except Exception as _exc:
            biosim_log('warn', '_on_close_synbio: {}'.format(_exc))
        self.destroy()

    def _build_toolbar(self):
        bar = tk.Frame(self, bg=biosim_theme('panel'), height=44)
        bar.pack(fill='x'); bar.pack_propagate(False)
        tk.Label(bar, text=self._t('header'), font=('Arial', 13, 'bold'),
                 bg=biosim_theme('panel'), fg='#8250df').pack(side='left', padx=14, pady=8)
        btns = tk.Frame(bar, bg=biosim_theme('panel'))
        btns.pack(side='right', padx=10, pady=6)
        for label_key, fg, cmd in [
            ('back', '#1c2128', self._on_back),
            ('forward', '#1c2128', self._on_forward),
            ('history', '#0550ae', self._on_history),
            ('save', '#1a7f37', self._on_save),
            ('load', '#9a6700', self._on_load),
        ]:
            tk.Button(btns, text=self._t(label_key), bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=fg, relief='solid', bd=1,
                      font=('Arial', 10, 'bold'), cursor='hand2',
                      padx=10, pady=4, command=cmd).pack(side='left', padx=2)

    def _build_tabs(self):
        tabs_row = tk.Frame(self, bg=biosim_theme('bg'), height=42)
        tabs_row.pack(fill='x'); tabs_row.pack_propagate(False)
        self.tab_buttons = {}
        for tab_id, label_key, color in [
            ('constructor', 'tab_constructor', '#0969da'),
            ('crispr', 'tab_crispr', '#cf222e'),
            ('metabolic', 'tab_metabolic', '#9a6700'),
            ('organism', 'tab_organism', '#1a7f37'),
        ]:
            btn = tk.Button(tabs_row, text=self._t(label_key), bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color,
                            relief='flat', font=('Arial', 11, 'bold'), cursor='hand2',
                            padx=20, pady=8,
                            command=lambda tid=tab_id: self._switch_tab(tid))
            btn.pack(side='left', padx=2, pady=4)
            self.tab_buttons[tab_id] = (btn, color)
        self.content = tk.Frame(self, bg=biosim_theme('bg'))
        self.content.pack(fill='both', expand=True, padx=6, pady=(0, 6))
        self.tab_frames = {}
        self.tab_frames['constructor'] = self._build_constructor_tab()
        self.tab_frames['crispr'] = self._build_crispr_tab()
        self.tab_frames['metabolic'] = self._build_metabolic_tab()
        self.tab_frames['organism'] = self._build_organism_tab()
        self._switch_tab('constructor')


    def _switch_tab(self, tab_id):
        # Guard: unknown tab id — do nothing rather than crash / blank the UI.
        if tab_id not in self.tab_frames:
            biosim_log('warn', '_switch_tab: unknown tab {}'.format(tab_id))
            return
        self.active_tab = tab_id
        # Hide every tab, then show the requested one. Wrapped so that a
        # failure while showing a heavy tab (e.g. a matplotlib canvas) can
        # never leave every tab hidden and the window unresponsive.
        try:
            for fr in self.tab_frames.values():
                fr.pack_forget()
            self.tab_frames[tab_id].pack(fill='both', expand=True)
        except Exception as _exc:
            biosim_log('error', '_switch_tab show {}: {}'.format(tab_id, _exc))
            # Last resort: make sure *some* frame is visible again.
            try:
                self.tab_frames[tab_id].pack(fill='both', expand=True)
            except Exception:
                pass
        # Recolour the tab buttons to reflect the active tab.
        try:
            for tid, (btn, color) in self.tab_buttons.items():
                if tid == tab_id:
                    btn.config(bg=color, fg='#f5f7fa')
                else:
                    btn.config(bg=biosim_theme('panel'), fg=color)
        except Exception as _exc:
            biosim_log('warn', '_switch_tab recolor: {}'.format(_exc))
        # Apply flat modern style to this tab's buttons (idempotent, deferred).
        try:
            self.after(60, lambda: self._restyle_buttons(self.tab_frames[tab_id]))
        except Exception:
            pass

