    def _link_to_molbio(self, target_tab=None, sequence=None):
        """Open the MolBio window (closing focus handoff). Optionally pass a
        sequence to analyze. Works via the main application."""
        is_ru = (self.lang == 'ru')
        app = self.master
        try:
            # Ask the main app to open MolBio
            if hasattr(app, '_open_molbio'):
                app._open_molbio()
                # Pass sequence if MolBio supports it
                mw = getattr(app, '_molbio_window', None)
                if mw is not None and sequence and hasattr(mw, 'load_external_sequence'):
                    mw.load_external_sequence(sequence, target_tab)
                # Lift MolBio above SynBio
                if mw is not None:
                    mw.lift(); mw.focus_force()
        except Exception as e:
            messagebox.showerror('VIREON', 'MolBio: ' + str(e)[:80])

    def load_external_crispr_sequence(self, sequence):
        """Receive a sequence from another section (e.g. MolBio) and load it
        into the CRISPR workspace, ready to scan for guide RNAs."""
        try:
            seq = ''.join(c for c in (sequence or '').upper() if c in 'ATGCUN')
            if not seq:
                return
            self.current_state['crispr']['sequence'] = seq
            self.current_state['crispr']['name'] = 'From MolBio'
            self.current_state['crispr']['targets'] = []
            self.current_state['crispr']['selected_target'] = None
            try:
                self._crispr_render_sequence()
            except Exception as _exc:
                biosim_log('warn', 'load_external_crispr_sequence: {}'.format(_exc))
            try:
                self._crispr_scan()
            except Exception as _exc:
                biosim_log('warn', 'load_external_crispr_sequence: {}'.format(_exc))
            is_ru = (self.lang == 'ru')
            messagebox.showinfo('VIREON',
                ('Последовательность загружена из MolBio ({} нт).\n'
                 'Гайды найдены автоматически — смотрите карту.'.format(len(seq))
                 if is_ru else
                 'Sequence loaded from MolBio ({} nt).\n'
                 'Guides scanned automatically — see the map.'.format(len(seq))))
        except Exception as _exc:
            biosim_log('warn', 'load_external_crispr_sequence: {}'.format(_exc))

    def load_external_constructor_sequence(self, sequence):
        """Receive a sequence from MolBio and store it in the constructor as a
        new gene part / imported sequence."""
        try:
            seq = ''.join(c for c in (sequence or '').upper() if c in 'ATGCUN')
            if not seq:
                return
            state = self.current_state.setdefault('constructor', {
                'name': 'New project', 'description': '', 'nodes': [], 'edges': [], 'init': {}})
            state['imported_sequence'] = seq
            # Add a gene node carrying this sequence
            idx = len(state.get('nodes', []))
            node = {
                'id': 'gene_{}'.format(idx + 1), 'type': 'gene',
                'x': 150 + (idx % 5) * 130, 'y': 120 + (idx // 5) * 110,
                'production': 1.0, 'degradation': 0.1, 'initial': 0.0,
                'sequence': seq,
            }
            state.setdefault('nodes', []).append(node)
            state.setdefault('init', {})[node['id']] = 0.0
            try:
                self._cons_refresh()
            except Exception as _exc:
                biosim_log('warn', 'load_external_constructor_sequence: {}'.format(_exc))
            is_ru = (self.lang == 'ru')
            messagebox.showinfo('VIREON',
                ('Последовательность из MolBio ({} нт) добавлена как ген\n'
                 'в конструктор.'.format(len(seq))
                 if is_ru else
                 'Sequence from MolBio ({} nt) added as a gene\n'
                 'in the constructor.'.format(len(seq))))
        except Exception as _exc:
            biosim_log('warn', 'load_external_constructor_sequence: {}'.format(_exc))

    # ════════════════════════════════════════════════
    # TRANSFER HUB — one big button per section with all
    # forward + backward (sync) transfers in a popup menu.
    # ════════════════════════════════════════════════
    def _make_transfer_hub(self, parent, section):
        """Create ONE big 'Transfer / Sync' button that opens a menu with all
        possible transfers FROM this section TO others, plus sync-back options.
        `section` is 'constructor', 'crispr', or 'metabolic'.
        """
        is_ru = (self.lang == 'ru')
        btn = tk.Button(parent,
                        text=('🔗 Перенос / Синхронизация ▾' if is_ru
                              else '🔗 Transfer / Sync ▾'),
                        bg='#8250df', highlightbackground='#8250df', fg='white',
                        relief='flat', font=('Arial', 9, 'bold'), cursor='hand2',
                        pady=4)

        def show_menu():
            menu = tk.Menu(self, tearoff=0)
            links = self._get_section_links(section)
            # Forward transfers
            fwd = [l for l in links if l[0] == 'forward']
            back = [l for l in links if l[0] == 'back']
            if fwd:
                menu.add_command(label=('— Перенести в: —' if is_ru else '— Send to: —'),
                                 state='disabled')
                for _, label, cb in fwd:
                    menu.add_command(label='   ' + label, command=cb)
            if back:
                menu.add_separator()
                menu.add_command(label=('— Синхронизировать обратно: —' if is_ru
                                        else '— Sync back from: —'), state='disabled')
                for _, label, cb in back:
                    menu.add_command(label='   ' + label, command=cb)
            try:
                x = btn.winfo_rootx()
                y = btn.winfo_rooty() + btn.winfo_height()
                menu.tk_popup(x, y)
            finally:
                menu.grab_release()

        btn.config(command=show_menu)
        return btn

    def _get_section_links(self, section):
        """Return list of (direction, label, callback) for a section's hub.
        direction is 'forward' or 'back'."""
        is_ru = (self.lang == 'ru')
        L = []
        if section == 'crispr':
            L.append(('forward',
                ('Метаболизм (эффект нокаута)' if is_ru else 'Metabolism (knockout effect)'),
                self._link_crispr_to_metabolic))
            L.append(('forward',
                ('MolBio (анализ последовательности)' if is_ru else 'MolBio (sequence analysis)'),
                lambda: self._link_to_molbio('sequence',
                          self.current_state['crispr'].get('sequence', ''))))
            L.append(('back',
                ('MolBio → взять последовательность' if is_ru else 'MolBio → pull sequence'),
                self._sync_crispr_from_molbio))
        elif section == 'metabolic':
            L.append(('forward',
                ('CRISPR (нокаут гена фермента)' if is_ru else 'CRISPR (knock out enzyme gene)'),
                self._link_metabolic_to_crispr))
            L.append(('forward',
                ('Конструктор (импорт пути)' if is_ru else 'Constructor (import pathway)'),
                self._link_metabolic_to_constructor))
            L.append(('forward',
                ('Синт. организм (проектировать клетку)' if is_ru else 'Synth. organism (design cell)'),
                lambda: self._switch_tab('organism')))
        elif section == 'constructor':
            L.append(('forward',
                ('Метаболизм (FBA схемы)' if is_ru else 'Metabolism (FBA of circuit)'),
                self._link_constructor_to_metabolic))
            L.append(('forward',
                ('CRISPR (гайды для гена)' if is_ru else 'CRISPR (guides for gene)'),
                self._link_constructor_to_crispr))
            L.append(('forward',
                ('MolBio (последовательность схемы)' if is_ru else 'MolBio (circuit sequence)'),
                self._link_constructor_to_molbio))
            L.append(('forward',
                ('Синт. организм (гены как задача)' if is_ru else 'Synth. organism (genes as task)'),
                lambda: self._switch_tab('organism')))
            L.append(('back',
                ('MolBio → обновить схему' if is_ru else 'MolBio → update circuit'),
                self._sync_constructor_from_molbio))
        elif section == 'organism':
            L.append(('forward',
                ('Конструктор (собрать гены схемой)' if is_ru else 'Constructor (build genes as circuit)'),
                self._link_organism_to_constructor))
            L.append(('forward',
                ('Метаболизм (проверить рост FBA)' if is_ru else 'Metabolism (check growth via FBA)'),
                self._link_organism_to_metabolic))
            L.append(('forward',
                ('CRISPR (гайды для генов задачи)' if is_ru else 'CRISPR (guides for task genes)'),
                self._link_organism_to_crispr))
        return L

    def _link_metabolic_to_constructor(self):
        """Import the current metabolic pathway as a circuit in Constructor."""
        is_ru = (self.lang == 'ru')
        self._switch_tab('constructor')
        messagebox.showinfo('VIREON',
            ('Открыт Конструктор.\n\nЗдесь можно построить генную схему '
             'для ферментов метаболического пути.'
             if is_ru else
             'Switched to Constructor.\n\nHere you can build a genetic circuit '
             'for the metabolic pathway enzymes.'))

    def _link_organism_to_constructor(self):
        """From Synthetic Organism: build the task genes as a circuit — now
        transfers the ACTUAL gene sequences via the bridge."""
        is_ru = (self.lang == 'ru')
        design = getattr(self, '_org_last_design', None)
        if not design or not design.get('tasks'):
            self._switch_tab('constructor')
            messagebox.showinfo('VIREON',
                ('Сначала выберите задачи организма.' if is_ru
                 else 'Select organism tasks first.'))
            return
        # Bridge: organism genes → real DNA sequence
        combined, gene_map = organism_genes_to_sequence(design)
        self._switch_tab('constructor')
        # Load each gene as a node in the constructor
        try:
            self.load_external_constructor_sequence(combined)
        except Exception as _exc:
            biosim_log('warn', '_link_organism_to_constructor: {}'.format(_exc))
        messagebox.showinfo('VIREON',
            ('Гены организма перенесены в Конструктор:\n{} генов, {} нт ДНК.\n'
             'Теперь можно собрать из них схему.'.format(len(gene_map), len(combined))
             if is_ru else
             'Organism genes sent to Constructor:\n{} genes, {} bp DNA.\n'
             'Now you can build a circuit from them.'.format(len(gene_map), len(combined))))

    def _link_organism_to_metabolic(self):
        """From Synthetic Organism: check viability/growth via FBA — now
        transfers the organism's tasks as real metabolic reactions."""
        is_ru = (self.lang == 'ru')
        design = getattr(self, '_org_last_design', None)
        self._switch_tab('metabolic')
        if design and design.get('tasks'):
            # Bridge: organism tasks → metabolic reactions
            reactions = organism_tasks_to_reactions(design)
            self._org_metabolic_reactions = reactions
            messagebox.showinfo('VIREON',
                ('Задачи организма переведены в {} метаболических реакций.\n'
                 'Проверьте через FBA рост и выход продукта.'.format(len(reactions))
                 if is_ru else
                 'Organism tasks converted to {} metabolic reactions.\n'
                 'Use FBA to check growth and product yield.'.format(len(reactions))))
        else:
            messagebox.showinfo('VIREON',
                ('Открыт Метаболизм.\n\nВыберите задачи организма для анализа.'
                 if is_ru else
                 'Switched to Metabolism.\n\nSelect organism tasks to analyze.'))

    def _link_organism_to_crispr(self):
        """From Synthetic Organism: design guides for the task genes — now
        transfers the ACTUAL gene sequences via the bridge."""
        is_ru = (self.lang == 'ru')
        design = getattr(self, '_org_last_design', None)
        if not design or not design.get('tasks'):
            self._switch_tab('crispr')
            messagebox.showinfo('VIREON',
                ('Сначала выберите задачи организма.' if is_ru
                 else 'Select organism tasks first.'))
            return
        # Bridge: organism genes → real DNA sequence
        combined, gene_map = organism_genes_to_sequence(design)
        self._switch_tab('crispr')
        try:
            self.load_external_crispr_sequence(combined)
        except Exception as _exc:
            biosim_log('warn', '_link_organism_to_crispr: {}'.format(_exc))
        # (load_external_crispr_sequence already shows a message + auto-scans)

    def _link_constructor_to_molbio(self):
        """Send the circuit's DNA sequence to MolBio."""
        state = self.current_state.get('constructor', {})
        # Generate a DNA sequence from the circuit if possible
        seq = ''
        try:
            result = generate_dna_from_circuit(state.get('nodes', []), state.get('edges', []))
            if isinstance(result, dict):
                seq = result.get('sequence', '') or ''
        except Exception as _exc:
            biosim_log('warn', '_link_constructor_to_molbio: {}'.format(_exc))
        if not seq:
            # Fallback: concatenate any node sequences
            for n in state.get('nodes', []):
                seq += n.get('sequence', '')
        self._link_to_molbio('sequence', seq)
        # Remember we sent from constructor (for sync-back)
        self._last_molbio_source = 'constructor'

    def _sync_crispr_from_molbio(self):
        """Pull the (possibly edited) sequence from MolBio back into CRISPR."""
        is_ru = (self.lang == 'ru')
        app = self.master
        mw = getattr(app, '_molbio_window', None)
        if mw is None or not hasattr(mw, 'get_current_sequence'):
            messagebox.showinfo('VIREON',
                ('Сначала откройте MolBio и загрузите последовательность.'
                 if is_ru else 'Open MolBio and load a sequence first.'))
            return
        seq = mw.get_current_sequence()
        if seq:
            self.load_external_crispr_sequence(seq)

    def _sync_constructor_from_molbio(self):
        """Pull edited sequence from MolBio and update the constructor.
        Tries to re-import as Antimony or annotate; here we notify and store."""
        is_ru = (self.lang == 'ru')
        app = self.master
        mw = getattr(app, '_molbio_window', None)
        if mw is None or not hasattr(mw, 'get_current_sequence'):
            messagebox.showinfo('VIREON',
                ('Сначала откройте MolBio и загрузите последовательность.'
                 if is_ru else 'Open MolBio and load a sequence first.'))
            return
        seq = mw.get_current_sequence()
        if not seq:
            return
        # Store the edited sequence on the constructor state for reference
        self.current_state['constructor']['imported_sequence'] = seq
        messagebox.showinfo('VIREON',
            ('Последовательность ({} нт) получена из MolBio и сохранена\n'
             'в схеме. Используйте «Импорт → Antimony» или генерацию ДНК\n'
             'чтобы построить схему из неё.'.format(len(seq))
             if is_ru else
             'Sequence ({} nt) pulled from MolBio and stored in the\n'
             'circuit. Use "Import → Antimony" or DNA generation to\n'
             'build a circuit from it.'.format(len(seq))))

    # ── GENE CIRCUITS TAB ──
    # ════════════════════════════════════════════════
    # CONSTRUCTOR TAB (replaces Circuit + Plasmid)
    # Single workspace with category buttons at top.
    # ════════════════════════════════════════════════
    def _build_constructor_tab(self):
        """Constructor: simple TinkerCell-like workspace.
        Top: category buttons (Elements / Proteins / Molecules / Connections / Compartments)
        Below top: parts panel showing parts in selected category
        Center: canvas with cartoon icons
        Right: info + simulation
        """
        f = tk.Frame(self.content, bg=biosim_theme('bg'))

        # Initialize state. On the very first build we seed the canvas list with
        # a single canvas; on later rebuilds (e.g. language switch) we keep the
        # canvases the user already has and just re-point current_state at the
        # active one. This makes the multi-canvas layer invisible to the ~126
        # existing constructor functions, which all go through
        # current_state['constructor'].
        if not self._cons_canvases:
            self._cons_canvases = [{
                'name': 'Холст 1' if self.lang == 'ru' else 'Canvas 1',
                'description': '', 'nodes': [], 'edges': [], 'init': {},
            }]
            self._cons_active_canvas = 0
        self._cons_active_canvas = max(
            0, min(self._cons_active_canvas, len(self._cons_canvases) - 1))
        self.current_state['constructor'] = self._cons_canvases[self._cons_active_canvas]

        # State for selection
        self._cons_selected_category = None
        self._cons_selected_part = None
        self._cons_selected_reaction = None
        # Reaction-template mode (1-to-1 / 2-to-1 insert menu)
        self._cons_selected_reaction_template_group = None
        self._cons_reaction_template_popup = None
        self._cons_template_dismiss_id = None
        self._cons_template_click_world = (0, 0)
        # Merged Regulation section
        self._cons_selected_regulation_button = None
        self._cons_regulation_popup = None
        self._cons_regulation_dismiss_id = None
        self._cons_regulation_click_world = (0, 0)
        self._cons_connect_source = None
        # For multi-source/multi-target reactions (X-to-Y)
        self._cons_conn_sources = None
        self._cons_conn_targets = None
        self._cons_drag_node = None
        self._cons_drag_offset = (0, 0)
        # Multi-selection
        self._cons_selected_nodes = set()      # ids of currently selected nodes
        self._cons_rubber_start = None         # (x, y) where rubber-band started
        self._cons_rubber_rect_id = None
        self._cons_multi_drag = False          # are we dragging multiple at once
        self._cons_multi_drag_offsets = {}     # node_id -> (offx, offy) at drag start

        # ──── TOP BAR: arrow button + 10 category buttons ────
        cat_bar = tk.Frame(f, bg=biosim_theme('bg'), height=44)
        cat_bar.pack(fill='x', pady=(0, 4))
        cat_bar.pack_propagate(False)

        # Arrow / select tool button (FIRST, before categories)
        self._cons_arrow_btn = tk.Button(cat_bar,
                                          text=self._t('tool_arrow'),
                                          bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                                          font=('Arial', 10, 'bold'), cursor='hand2',
                                          padx=8, pady=2,
                                          command=self._cons_set_arrow_tool)
        self._cons_arrow_btn.pack(side='left', fill='x', expand=False, padx=2, pady=2)

        self._cons_cat_buttons = {}
        categories = [
            ('elements',     'cat_elements',     '#0969da', '▭'),
            ('proteins',     'cat_proteins',     '#1a7f37', '●'),
            ('molecules',    'cat_molecules',    '#8250df', '◆'),
            ('regulation',   'cat_regulation',   '#cf222e', '⊣'),
            ('reactions',    'cat_reactions',    '#0550ae', ''),
            ('inputs',       'cat_inputs',       '#9a6700', ''),
            ('outputs',      'cat_outputs',      '#1a7f37', ''),
            ('modules',      'cat_modules',      '#8250df', '◫'),
            ('wetlab',       'cat_wetlab',       '#8250df', ''),
            ('compartments', 'cat_compartments', '#8250df', ''),
        ]
        for cat_key, label_key, color, icon in categories:
            label_text = ('{} {}'.format(icon, self._t(label_key)) if icon
                          else self._t(label_key))
            btn = tk.Button(cat_bar,
                             text=label_text,
                             bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                             font=('Arial', 10, 'bold'), cursor='hand2',
                             padx=8, pady=2,
                             command=lambda k=cat_key: self._cons_select_category(k))
            btn.pack(side='left', fill='x', expand=True, padx=2, pady=2)
            self._cons_cat_buttons[cat_key] = (btn, color)

        # ── Transfer/Sync hub (Constructor ↔ all sections) ──
        clb = self._make_transfer_hub(cat_bar, 'constructor')
        if clb:
            clb.pack(side='right', fill='y', padx=4, pady=4)

        # ──── PARTS PANEL (under top bar) ────
        # Contains buttons for the parts/reactions in current category
        parts_panel = tk.LabelFrame(f, text='', bg=biosim_theme('panel'),
                                      fg='#0969da', font=('Arial', 10, 'bold'),
                                      relief='flat', height=72)
        parts_panel.pack(fill='x', pady=(0, 4))
        parts_panel.pack_propagate(False)

        # Left scroll arrow
        def _scroll_parts(amount):
            self._cons_parts_canvas.xview_scroll(amount, 'units')
        left_arrow = tk.Button(parts_panel, text='◀', bg='#0969da', fg='white',
                                relief='flat', font=('Arial', 12, 'bold'),
                                cursor='hand2', width=2, bd=0,
                                activebackground='#0a5cc4',
                                command=lambda: _scroll_parts(-6))
        left_arrow.pack(side='left', fill='y', padx=(2, 0), pady=6)

        # Right scroll arrow
        right_arrow = tk.Button(parts_panel, text='▶', bg='#0969da', fg='white',
                                 relief='flat', font=('Arial', 12, 'bold'),
                                 cursor='hand2', width=2, bd=0,
                                 activebackground='#0a5cc4',
                                 command=lambda: _scroll_parts(6))
        right_arrow.pack(side='right', fill='y', padx=(0, 2), pady=6)

        # Scrollable horizontal container for part buttons
        self._cons_parts_canvas = tk.Canvas(parts_panel, bg=biosim_theme('panel'),
                                              highlightthickness=0, height=54)
        parts_scroll = tk.Scrollbar(parts_panel, orient='horizontal',
                                      command=self._cons_parts_canvas.xview)
        self._cons_parts_frame = tk.Frame(self._cons_parts_canvas, bg=biosim_theme('panel'))
        self._cons_parts_canvas.create_window((0, 0), window=self._cons_parts_frame,
                                                 anchor='nw')
        self._cons_parts_canvas.configure(xscrollcommand=parts_scroll.set)
        self._cons_parts_frame.bind('<Configure>',
            lambda e: self._cons_parts_canvas.configure(
                scrollregion=self._cons_parts_canvas.bbox('all')))
        self._cons_parts_canvas.pack(side='top', fill='x', expand=True, padx=4, pady=(4, 0))
        parts_scroll.pack(side='bottom', fill='x', padx=36)

        # Mouse-wheel horizontal scroll over the parts strip (all platforms)
        def _parts_wheel(event):
            if getattr(event, 'num', None) == 4:
                self._cons_parts_canvas.xview_scroll(-3, 'units')
            elif getattr(event, 'num', None) == 5:
                self._cons_parts_canvas.xview_scroll(3, 'units')
            else:
                self._cons_parts_canvas.xview_scroll(
                    -1 * int(event.delta / 40 or (1 if event.delta > 0 else -1)), 'units')
            return 'break'
        for _w in (self._cons_parts_canvas, self._cons_parts_frame):
            _w.bind('<MouseWheel>', _parts_wheel)
            _w.bind('<Shift-MouseWheel>', _parts_wheel)
            _w.bind('<Button-4>', _parts_wheel)
            _w.bind('<Button-5>', _parts_wheel)

        # Initial hint in parts panel
        tk.Label(self._cons_parts_frame,
                  text=self._t('cons_no_part_selected'),
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 11, 'italic')
                  ).pack(padx=20, pady=20)

        # ──── MIDDLE: canvas (center) + right panel ────
        middle = tk.Frame(f, bg=biosim_theme('bg'))
        middle.pack(fill='both', expand=True)

        # Canvas area
        canvas_area = tk.Frame(middle, bg=biosim_theme('bg'))
        canvas_area.pack(side='left', fill='both', expand=True, padx=(0, 4))

        # Status bar above canvas
        self._cons_status_lbl = tk.Label(canvas_area,
                                          text=self._t('cons_canvas_hint'),
                                          bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                                          font=('Arial', 10, 'italic'),
                                          height=2, anchor='w')
        self._cons_status_lbl.pack(fill='x', pady=(0, 2))

        # View switcher (Cartoon / Linear SBOL / Circular)
        view_bar = tk.Frame(canvas_area, bg=biosim_theme('bg'))
        view_bar.pack(fill='x', pady=(0, 2))
        self.cons_view_mode = tk.StringVar(value='cartoon')
        for vkey, vlabel_key, vcolor in [
            ('cartoon', 'view_cartoon', '#0969da'),
            ('linear', 'view_linear_sbol', '#1a7f37'),
            ('circular', 'view_circular', '#8250df'),
        ]:
            tk.Radiobutton(view_bar, text=self._t(vlabel_key),
                            variable=self.cons_view_mode, value=vkey,
                            bg=biosim_theme('bg'), fg=vcolor, selectcolor='#eef1f5',
                            activebackground='#f5f7fa',
                            font=('Arial', 10, 'bold'),
                            command=self._cons_refresh
                            ).pack(side='left', padx=8)
        # 3D plasmid button — opens a separate 3D window
        tk.Button(view_bar, text='3D',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', padx=10,
                   command=self._cons_open_3d_plasmid
                   ).pack(side='left', padx=12)

        # Canvas switcher bar (just below the view switcher, above the canvas).
        # The tools above and the library on the left never change — this only
        # swaps which canvas they act on.
        self._cons_canvas_bar = tk.Frame(canvas_area, bg=biosim_theme('bg'))
        self._cons_canvas_bar.pack(fill='x', pady=(0, 2))
        self._cons_render_canvas_bar()

        # Canvas
        canvas_frame = tk.LabelFrame(canvas_area, text='', bg=biosim_theme('panel'),
                                       fg='#0969da', font=('Arial', 11, 'bold'),
                                       relief='flat')
        canvas_frame.pack(fill='both', expand=True)
        # Module navigation breadcrumb (empty at top level; shows path inside modules)
        self._cons_breadcrumb_lbl = tk.Label(
            canvas_frame, text='', bg=biosim_theme('panel'), fg='#8250df',
            font=('Arial', 9, 'bold'), cursor='hand2', anchor='w')
        self._cons_breadcrumb_lbl.pack(fill='x', padx=6, pady=(2, 0))
        self._cons_breadcrumb_lbl.bind(
            '<Button-1>', lambda e: self._cons_exit_module())
        # Canvas + scrollbars in a grid so we get right & bottom scroll bars.
        canvas_holder = tk.Frame(canvas_frame, bg=biosim_theme('panel'))
        canvas_holder.pack(fill='both', expand=True, padx=4, pady=4)
        canvas_holder.grid_rowconfigure(0, weight=1)
        canvas_holder.grid_columnconfigure(0, weight=1)
        self.cons_canvas = tk.Canvas(canvas_holder, bg=biosim_theme('bg'),
                                       highlightthickness=0, cursor='arrow')
        self.cons_canvas.grid(row=0, column=0, sticky='nsew')
        self._cons_vsb = tk.Scrollbar(canvas_holder, orient='vertical',
                                       command=self._cons_scroll_y)
        self._cons_vsb.grid(row=0, column=1, sticky='ns')
        self._cons_hsb = tk.Scrollbar(canvas_holder, orient='horizontal',
                                       command=self._cons_scroll_x)
        self._cons_hsb.grid(row=1, column=0, sticky='ew')
        # Floating zoom controls (+/−/reset) in the corner of the canvas.
        zoom_bar = tk.Frame(canvas_holder, bg=biosim_theme('panel2'),
                            highlightthickness=1, highlightbackground=biosim_theme('border'))
        zoom_bar.place(in_=self.cons_canvas, relx=1.0, rely=1.0, x=-8, y=-8,
                       anchor='se')
        for txt, cmd, w in [('−', self._cons_zoom_out, 3),
                            ('⟲', self._cons_zoom_reset, 3),
                            ('+', self._cons_zoom_in, 3)]:
            tk.Button(zoom_bar, text=txt, command=cmd, width=w,
                      bg=biosim_theme('btn_bg'), fg=biosim_theme('btn_text'),
                      relief='flat', bd=0, highlightthickness=0,
                      font=('Helvetica', 13, 'bold'), cursor='hand2'
                      ).pack(side='left', padx=1, pady=1)
        self.cons_canvas.bind('<Button-1>', self._cons_canvas_click)
        self.cons_canvas.bind('<Double-Button-1>', self._cons_canvas_double_click)
        self.cons_canvas.bind('<Control-Button-1>', self._cons_canvas_ctrl_click)
        self.cons_canvas.bind('<B1-Motion>', self._cons_canvas_drag)
        self.cons_canvas.bind('<ButtonRelease-1>', self._cons_canvas_release)
        self.cons_canvas.bind('<Button-3>', self._cons_canvas_right_click)
        # On Mac Button-2 might also be right-click
        self.cons_canvas.bind('<Button-2>', self._cons_canvas_right_click)
        # Delete key for removing selected
        self.cons_canvas.bind('<Key-Delete>', lambda e: self._cons_delete_selected())
        self.cons_canvas.bind('<Key-BackSpace>', lambda e: self._cons_delete_selected())
        self.cons_canvas.bind('<Key-Escape>', lambda e: self._cons_deselect_all())
        # F1 — context help
        self.bind_all('<F1>', lambda e: self._cons_show_context_help())
        # File / Undo shortcuts (use both Ctrl and Cmd for macOS compat)
        self.bind_all('<Control-s>', lambda e: self._project_save())
        self.bind_all('<Command-s>', lambda e: self._project_save())
        self.bind_all('<Control-o>', lambda e: self._project_open())
        self.bind_all('<Command-o>', lambda e: self._project_open())
        self.bind_all('<Control-n>', lambda e: self._project_new())
        self.bind_all('<Command-n>', lambda e: self._project_new())
        self.bind_all('<Control-z>', lambda e: self._project_undo())
        self.bind_all('<Command-z>', lambda e: self._project_undo())
        self.bind_all('<Control-y>', lambda e: self._project_redo())
        self.bind_all('<Command-y>', lambda e: self._project_redo())
        self.bind_all('<Control-Shift-Z>', lambda e: self._project_redo())
        # Copy / Cut / Paste (within and between schemas)
        self.bind_all('<Control-c>', lambda e: self._cons_copy_selected())
        self.bind_all('<Command-c>', lambda e: self._cons_copy_selected())
        self.bind_all('<Control-x>', lambda e: self._cons_cut_selected())
        self.bind_all('<Command-x>', lambda e: self._cons_cut_selected())
        self.bind_all('<Control-v>', lambda e: self._cons_paste_clipboard())
        self.bind_all('<Command-v>', lambda e: self._cons_paste_clipboard())
        self.bind_all('<Control-l>', lambda e: self._open_log_console())
        self.bind_all('<Command-l>', lambda e: self._open_log_console())
        self.bind_all('<Control-t>', lambda e: self._cons_open_text_mode())
        self.bind_all('<Command-t>', lambda e: self._cons_open_text_mode())
        self.bind_all('<Control-f>', lambda e: self._cons_find_dialog())
        self.bind_all('<Command-f>', lambda e: self._cons_find_dialog())
        self.bind_all('<Control-m>', lambda e: self._cons_open_animation())
        self.bind_all('<Command-m>', lambda e: self._cons_open_animation())
        self.bind_all('<Control-h>', lambda e: self._cons_open_manual())
        self.bind_all('<Command-h>', lambda e: self._cons_open_manual())
        # Layout shortcuts: Ctrl+Shift+L spring layout, Ctrl+Shift+F zoom-to-fit
        self.bind_all('<Control-L>', lambda e: self._cons_auto_layout('spring'))
        self.bind_all('<Command-L>', lambda e: self._cons_auto_layout('spring'))
        self.bind_all('<Control-F>', lambda e: self._cons_zoom_to_fit())
        self.bind_all('<Command-F>', lambda e: self._cons_zoom_to_fit())
        # Make canvas focusable for keyboard
        self.cons_canvas.bind('<Enter>', lambda e: self.cons_canvas.focus_set())
        self.cons_canvas.config(takefocus=1)

        # ── Real canvas zoom & pan (world↔screen transform) ──
        # Node coordinates are stored in WORLD space. The canvas view is a
        # scale + translation of that world. Clicks are converted screen→world;
        # drawing is done in world space then scaled/moved as a final step.
        self._cons_scale = 1.0
        self._cons_pan_x = 0.0
        self._cons_pan_y = 0.0
        self._cons_panning = False
        self._cons_pan_start = None
        # Mouse wheel to zoom (Windows/Mac use <MouseWheel>, Linux <Button-4/5>)
        self.cons_canvas.bind('<MouseWheel>', self._cons_on_mousewheel)
        self.cons_canvas.bind('<Button-4>', self._cons_on_mousewheel)
        self.cons_canvas.bind('<Button-5>', self._cons_on_mousewheel)
        # Middle-button drag OR space+drag to pan
        self.cons_canvas.bind('<Button-2>', self._cons_pan_start_evt, add='+')
        self.cons_canvas.bind('<B2-Motion>', self._cons_pan_move_evt)
        self.cons_canvas.bind('<ButtonRelease-2>', self._cons_pan_end_evt)
        # Zoom hotkeys
        self.bind_all('<Control-equal>', lambda e: self._cons_zoom_by(1.2))
        self.bind_all('<Control-plus>', lambda e: self._cons_zoom_by(1.2))
        self.bind_all('<Control-minus>', lambda e: self._cons_zoom_by(1 / 1.2))
        self.bind_all('<Control-0>', lambda e: self._cons_zoom_reset())

        # ──── RIGHT panel ────
        right = tk.Frame(middle, bg=biosim_theme('bg'), width=260)
        right.pack(side='right', fill='y'); right.pack_propagate(False)

        # Action buttons
        actions_frame = tk.LabelFrame(right, text='', bg=biosim_theme('panel'),
                                        fg='#0969da', font=('Arial', 10, 'bold'),
                                        relief='flat')
        actions_frame.pack(fill='x', pady=(0, 4))

        # ── File toolbar: New / Open / Save / Undo / Redo / Log ──
        file_row = tk.Frame(actions_frame, bg=biosim_theme('panel'))
        file_row.pack(fill='x', padx=4, pady=(4, 2))
        btn_new = tk.Button(file_row, text='+ Новый', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                              font=('Arial', 11, 'bold'), cursor='hand2', pady=2, width=3,
                              command=self._project_new)
        btn_new.pack(side='left', padx=1)
        Tooltip(btn_new, 'New project (Ctrl+N)' if self.lang == 'en' else
                          'Новый проект (Ctrl+N)')
        btn_open = tk.Button(file_row, text='Открыть', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                               font=('Arial', 11, 'bold'), cursor='hand2', pady=2, width=3,
                               command=self._project_open)
        btn_open.pack(side='left', padx=1)
        Tooltip(btn_open, 'Open .biosim project (Ctrl+O)' if self.lang == 'en' else
                           'Открыть проект .biosim (Ctrl+O)')
        btn_save = tk.Button(file_row, text='Сохранить', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                               font=('Arial', 11, 'bold'), cursor='hand2', pady=2, width=3,
                               command=self._project_save)
        btn_save.pack(side='left', padx=1)
        Tooltip(btn_save, 'Save project (Ctrl+S)' if self.lang == 'en' else
                           'Сохранить проект (Ctrl+S)')
        btn_undo = tk.Button(file_row, text='⟲', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                               font=('Arial', 14, 'bold'), cursor='hand2', pady=0, width=3,
                               command=self._project_undo)
        btn_undo.pack(side='left', padx=1)
        Tooltip(btn_undo, 'Undo last action (Ctrl+Z)' if self.lang == 'en' else
                           'Отменить (Ctrl+Z)')
        btn_redo = tk.Button(file_row, text='⟳', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                               font=('Arial', 14, 'bold'), cursor='hand2', pady=0, width=3,
                               command=self._project_redo)
        btn_redo.pack(side='left', padx=1)
        Tooltip(btn_redo, 'Redo (Ctrl+Y)' if self.lang == 'en' else
                           'Повторить (Ctrl+Y)')
        btn_log = tk.Button(file_row, text='Лог', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                              font=('Arial', 11, 'bold'), cursor='hand2', pady=2, width=3,
                              command=self._open_log_console)
        btn_log.pack(side='left', padx=1)
        Tooltip(btn_log, 'Show log console (Ctrl+L)' if self.lang == 'en' else
                          'Открыть лог (Ctrl+L)')
        # Settings — three-dots menu (drawn glyph, not text)
        settings_holder = tk.Frame(file_row, bg=biosim_theme('panel'),
                                   highlightbackground='#1c2128', highlightthickness=1,
                                   cursor='hand2')
        settings_holder.pack(side='left', padx=1)
        settings_glyph = self._make_glyph_canvas(settings_holder, 'settings',
                                                 '#57606a', size=26)
        settings_glyph.pack(padx=4, pady=2)
        for w in (settings_holder, settings_glyph):
            w.bind('<Button-1>', lambda e: self._cons_open_settings_menu())
        Tooltip(settings_holder, 'Settings' if self.lang == 'en' else 'Настройки')
        tk.Label(actions_frame, text='New · Open · Save · Undo · Redo · Log · ⋮',
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 7, 'italic')).pack(pady=(0, 2))

        # ── Main actions: assign genes, simulate, clear ──
        tk.Button(actions_frame, text=self._t('cons_assign_genes'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=self._cons_assign_genes_dialog
                   ).pack(fill='x', padx=4, pady=(4, 2))

        # Disease selector (above Run button)
        tk.Label(actions_frame, text=self._t('cons_disease_dropdown'),
                  bg=biosim_theme('panel'), fg='#cf222e',
                  font=('Arial', 9, 'bold')).pack(anchor='w', padx=4, pady=(4, 0))
        self.cons_disease_var = tk.StringVar(value='none')
        disease_options = []
        for dkey, dval in DISEASE_DATABASE.items():
            label = dval['name_ru'] if self.lang == 'ru' else dval['name_en']
            disease_options.append((dkey, label))
        self._cons_disease_options = disease_options
        disease_combo_values = [lbl for _, lbl in disease_options]
        self.cons_disease_combo = ttk.Combobox(actions_frame,
                                                 values=disease_combo_values,
                                                 state='readonly', font=('Arial', 9))
        self.cons_disease_combo.current(0)
        self.cons_disease_combo.pack(fill='x', padx=4, pady=2)
        # Choosing a disease builds its gene-therapy construct on the canvas
        # (with NCBI sequences), instead of opening a separate info window.
        self.cons_disease_combo.bind('<<ComboboxSelected>>',
                                      self._cons_on_disease_selected)

        tk.Button(actions_frame, text=self._t('cons_run_sim'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=self._cons_run_ode
                   ).pack(fill='x', padx=4, pady=4)
        tk.Button(actions_frame, text=self._t('cons_clear'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2',
                   command=self._cons_clear).pack(fill='x', padx=4, pady=(2, 6))

        # ── SynBio tools (moved here from the global Science menu) ──
        def _call_master(method_name):
            app = self.master
            fn = getattr(app, method_name, None)
            if callable(fn):
                fn()
        tk.Button(actions_frame,
                  text=('🧬 SynBio инструменты' if self.lang == 'ru' else '🧬 SynBio Tools'),
                  bg=biosim_theme('panel'), highlightbackground='#1c2128',
                  fg=biosim_theme('text'), relief='solid', bd=1,
                  font=('Arial', 10, 'bold'), cursor='hand2', anchor='w', padx=10, pady=4,
                  command=lambda: _call_master('_open_synbio_tools')
                  ).pack(fill='x', padx=4, pady=2)
        tk.Button(actions_frame,
                  text=('🧬 SynBio PRO+ (цепи, осцилляторы)' if self.lang == 'ru'
                        else '🧬 SynBio PRO+ (circuits)'),
                  bg=biosim_theme('panel'), highlightbackground='#1c2128',
                  fg=biosim_theme('text'), relief='solid', bd=1,
                  font=('Arial', 10, 'bold'), cursor='hand2', anchor='w', padx=10, pady=4,
                  command=lambda: _call_master('_open_synbio_advanced')
                  ).pack(fill='x', padx=4, pady=2)

        # ── Separator ──
        tk.Frame(actions_frame, bg='#d0d7de', height=1).pack(fill='x', padx=8, pady=4)

        # ── 4 grouped menu buttons ──
