    def _restyle_buttons(self, root):
        """Recursively apply the flat modern style to every tk.Button under
        `root`, removing the old grey Windows-style borders. Buttons already
        carrying an accent fill (primary/secondary action colours) are detected
        by their current background and mapped to the themed accent, so main
        actions stay coloured while the rest become clean soft buttons.

        Also switches label/button fonts from Arial to the modern UI font.
        """
        accent_like = {'#1a7f37', '#0b7a4b', '#0d9488', '#1a7f37', '#0550ae',
                       '#0969da', '#2f81f7', '#0891b2'}
        danger_like = {'#cf222e', '#d1242f', '#a40e26'}
        def walk(w):
            for c in w.winfo_children():
                cls = c.__class__.__name__
                try:
                    if cls == 'Button':
                        cur = str(c.cget('bg')).lower()
                        txt = str(c.cget('text'))
                        # Heuristic: coloured action buttons → keep as accent.
                        if cur in danger_like:
                            style_button(c, 'danger')
                        elif cur in accent_like:
                            style_button(c, 'primary')
                        else:
                            style_button(c, 'normal')
                        # modern font, preserve size/weight
                        try:
                            fnt = c.cget('font')
                            if 'Arial' in str(fnt):
                                c.configure(font=(BIOSIM_FONT_FALLBACK, 10))
                        except Exception:
                            pass
                except Exception:
                    pass
                walk(c)
        try:
            walk(root)
        except Exception:
            pass

    def _build_global_statusbar(self, parent):
        """Build a comprehensive status bar showing project state, 
        sim count, recent action, progress, etc."""
        bar = tk.Frame(parent, bg=biosim_theme('panel'), height=24)
        bar.pack(side='bottom', fill='x')
        bar.pack_propagate(False)
        
        # Project name (left)
        self._sb_project = tk.Label(bar, text='Untitled',
                                       bg=biosim_theme('panel'), fg='#0550ae',
                                       font=('Arial', 9, 'bold'),
                                       anchor='w', padx=8)
        self._sb_project.pack(side='left')
        
        # Separator
        tk.Frame(bar, bg='#d0d7de', width=1).pack(side='left', fill='y', padx=2)
        
        # Nodes / edges count
        self._sb_counts = tk.Label(bar, text='0 узлов · 0 связей' if self.lang == 'ru'
                                      else '0 nodes · 0 edges',
                                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                                      font=('Arial', 9), padx=8)
        self._sb_counts.pack(side='left')
        
        tk.Frame(bar, bg='#d0d7de', width=1).pack(side='left', fill='y', padx=2)
        
        # Simulation count
        self._sb_sims = tk.Label(bar, text='▶ 0' ,
                                    bg=biosim_theme('panel'), fg='#1a7f37',
                                    font=('Arial', 9), padx=8)
        self._sb_sims.pack(side='left')
        Tooltip(self._sb_sims, 'Запущено симуляций (в этой сессии)' if self.lang == 'ru'
                                else 'Simulations run (this session)')
        
        tk.Frame(bar, bg='#d0d7de', width=1).pack(side='left', fill='y', padx=2)
        
        # Last action / message (middle, expandable)
        self._sb_message = tk.Label(bar, text='Готов · ' + ('двойной клик на категорию '
                                                              'чтобы добавить элемент' if self.lang == 'ru'
                                                              else 'double-click category to add element'),
                                       bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                       font=('Arial', 9), anchor='w', padx=8)
        self._sb_message.pack(side='left', fill='x', expand=True)
        
        # Progress bar (hidden by default)
        self._sb_progress = ttk.Progressbar(bar, mode='indeterminate',
                                                length=120)
        # Don't pack — appears on demand
        
        # Right side: auto-save indicator
        self._sb_autosave = tk.Label(bar, text='auto',
                                         bg=biosim_theme('panel'), fg='#1a7f37',
                                         font=('Arial', 8), padx=6)
        self._sb_autosave.pack(side='right')
        Tooltip(self._sb_autosave, 'Auto-save включен · сохранение каждые 5 минут'
                                      if self.lang == 'ru' else
                                      'Auto-save enabled · every 5 minutes')
        
        # Lang indicator
        tk.Frame(bar, bg='#d0d7de', width=1).pack(side='right', fill='y', padx=2)
        lang_lbl = tk.Label(bar, text=self.lang.upper(),
                              bg=biosim_theme('panel'), fg='#8250df',
                              font=('Arial', 8, 'bold'), padx=8)
        lang_lbl.pack(side='right')

    def update_statusbar(self):
        """Refresh status bar values from current state."""
        if not hasattr(self, '_sb_project'):
            return
        try:
            # Project name
            path = getattr(self, '_current_project_path', None)
            if path:
                name = os.path.basename(path)
                self._sb_project.config(text='' + name, fg='#0550ae')
            else:
                self._sb_project.config(text='Untitled', fg=biosim_theme('text_dim'))
            
            # Counts
            state = self.current_state.get('constructor', {}) or {}
            n_nodes = len(state.get('nodes', []))
            n_edges = len(state.get('edges', []))
            if self.lang == 'ru':
                txt = '{} узлов · {} связей'.format(n_nodes, n_edges)
            else:
                txt = '{} nodes · {} edges'.format(n_nodes, n_edges)
            self._sb_counts.config(text=txt)
            
            # Sims
            n_sims = len(getattr(self, '_simulation_history', []))
            self._sb_sims.config(text='▶ {}'.format(n_sims))
        except Exception as _exc:
            biosim_log('warn', 'update_statusbar: {}'.format(_exc))

    def sb_message(self, text, level='info'):
        """Update status bar middle message. level: info/success/warn/error."""
        if not hasattr(self, '_sb_message'):
            return
        colors = {'info': '#1c2128', 'success': '#1a7f37',
                   'warn': '#9a6700', 'error': '#cf222e'}
        try:
            self._sb_message.config(text=text, fg=colors.get(level, '#1c2128'))
        except Exception as _exc:
            biosim_log('warn', 'sb_message: {}'.format(_exc))

    def sb_progress_start(self):
        """Show indeterminate progress bar."""
        if not hasattr(self, '_sb_progress'):
            return
        try:
            self._sb_progress.pack(side='right', padx=4, pady=2, before=self._sb_autosave)
            self._sb_progress.start(60)
        except Exception as _exc:
            biosim_log('warn', 'sb_progress_start: {}'.format(_exc))

    def sb_progress_stop(self):
        """Hide progress bar."""
        if not hasattr(self, '_sb_progress'):
            return
        try:
            self._sb_progress.stop()
            self._sb_progress.pack_forget()
        except Exception as _exc:
            biosim_log('warn', 'sb_progress_stop: {}'.format(_exc))

    def toast(self, message, level='info', duration=3000, action=None, action_label=None):
        """Shortcut to show a toast for this window."""
        Toast.show(self, message, level=level, duration=duration,
                    action=action, action_label=action_label)

    def _cons_select_category(self, cat_key):
        """Top button: choose a category. Show parts in panel below."""
        self._cons_selected_category = cat_key
        self._cons_selected_part = None
        self._cons_selected_reaction = None
        self._cons_selected_reaction_template_group = None
        self._cons_close_reaction_template_popup()
        self._cons_selected_regulation_button = None
        self._cons_close_regulation_popup()
        self._cons_connect_source = None
        # Update button styles
        for ck, (btn, color) in self._cons_cat_buttons.items():
            if ck == cat_key:
                btn.config(bg=color, fg='#f5f7fa')
            else:
                btn.config(bg=biosim_theme('panel2'), fg=color)
        # Refresh parts panel
        self._cons_render_parts_panel()
        self._cons_status_lbl.config(text=self._t('cons_canvas_hint'))

    def _cons_render_parts_panel(self):
        """Render the horizontal parts panel based on selected category."""
        for w in self._cons_parts_frame.winfo_children():
            w.destroy()
        cat = self._cons_selected_category
        if cat is None:
            tk.Label(self._cons_parts_frame,
                      text=self._t('cons_no_part_selected'),
                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 11, 'italic')).pack(padx=20, pady=20)
            return

        # ── Regulation: merged section with 8 grouped buttons ──
        if cat == 'regulation':
            for b in CIRCUIT_REGULATION_BUTTONS:
                name = b['name_ru'] if self.lang == 'ru' else b['name_en']
                color = b.get('color', '#0969da')
                glyph = b.get('glyph', 'activation')
                self._cons_make_part_button(
                    self._cons_parts_frame, glyph, color, name,
                    lambda k=b['key']: self._cons_select_regulation_button(k))
            return

        # ── Connections / Reactions: from CIRCUIT_REACTIONS ──
        if cat in ('connections', 'reactions'):
            # Filter reactions by category
            if cat == 'connections':
                # Basic connections: classic transcription/translation/binding/etc.
                rxn_keys = ['transcription', 'translation', 'activation', 'repression',
                             'binding', 'conversion', 'cleavage', 'degradation',
                             'transport', 'production', 'complex_formation',
                             'dissociation', 'secretion', 'diffusion',
                             'biochemical_reaction', 'pops', 'rips']
            else:  # reactions = stoichiometries
                rxn_keys = ['rxn_1_to_1', 'rxn_2_to_1', 'rxn_3_to_1',
                             'rxn_1_to_2', 'rxn_2_to_2', 'rxn_3_to_2',
                             'rxn_1_to_3', 'rxn_2_to_3', 'rxn_3_to_3']
            # Map reaction keys to drawn glyphs where we have one
            rxn_glyph = {
                'activation': 'activation', 'repression': 'repression',
                'degradation': 'degradation', 'knockout': 'degradation',
            }
            # Stoichiometry buttons that open a TEMPLATE popup instead of the
            # plain connect-mode. Only 1-to-1 and 2-to-1 have templates; the
            # rest keep their original behaviour.
            template_group_for = {'rxn_1_to_1': '1_to_1', 'rxn_2_to_1': '2_to_1'}
            for rkey in rxn_keys:
                rdata = CIRCUIT_REACTIONS.get(rkey)
                if not rdata:
                    continue
                name = rdata['name_ru'] if self.lang == 'ru' else rdata['name_en']
                color = rdata['color']
                # 1-to-1 / 2-to-1 → template popup
                if rkey in template_group_for:
                    grp = template_group_for[rkey]
                    icon = self._reaction_icon_char(rdata['arrow'])
                    btn = tk.Frame(self._cons_parts_frame, bg=biosim_theme('panel'))
                    btn.pack(side='left', padx=3, pady=2)
                    b = tk.Button(btn, text='{} {}'.format(icon, name[:14]),
                                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                                   font=('Arial', 9, 'bold'), cursor='hand2',
                                   padx=6, pady=2,
                                   command=lambda g=grp: self._cons_select_reaction_template_group(g))
                    b.pack()
                    continue
                if rkey in rxn_glyph:
                    # Draw a real glyph icon
                    self._cons_make_part_button(
                        self._cons_parts_frame, rxn_glyph[rkey], color, name,
                        lambda k=rkey: self._cons_select_reaction(k))
                else:
                    # Keep text arrow for reactions without a dedicated glyph
                    icon = self._reaction_icon_char(rdata['arrow'])
                    btn = tk.Frame(self._cons_parts_frame, bg=biosim_theme('panel'))
                    btn.pack(side='left', padx=3, pady=2)
                    b = tk.Button(btn, text='{} {}'.format(icon, name[:14]),
                                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                                   font=('Arial', 9, 'bold'), cursor='hand2',
                                   padx=6, pady=2,
                                   command=lambda k=rkey: self._cons_select_reaction(k))
                    b.pack()
            return

        # ── Inputs ──
        if cat == 'inputs':
            for ikey, idata in CIRCUIT_INPUTS.items():
                name = idata['name_ru'] if self.lang == 'ru' else idata['name_en']
                color = idata['color']
                # Use simple character for icon
                icon_char = {'event': '◇', 'param': '#', 'step': '⌐', 'inv_step': '¬',
                              'impulse': '|', 'wave': '∿'}.get(idata['icon'], '◇')
                btn = tk.Frame(self._cons_parts_frame, bg=biosim_theme('panel'))
                btn.pack(side='left', padx=3, pady=2)
                b = tk.Button(btn, text='{} {}'.format(icon_char, name[:14]),
                               bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                               font=('Arial', 9, 'bold'), cursor='hand2',
                               padx=6, pady=2,
                               command=lambda k=ikey: self._cons_select_input(k))
                b.pack()
            return

        # ── Outputs / reporters ──
        if cat == 'outputs':
            for okey, odata in CIRCUIT_OUTPUTS.items():
                name = odata['name_ru'] if self.lang == 'ru' else odata['name_en']
                color = odata['color']
                icon_char = {'glow': '', 'conc': '◉', 'thresh': '⎍', 'ratio': '÷',
                              'rate': '∂', 'integ': '∫'}.get(odata['icon'], '')
                btn = tk.Frame(self._cons_parts_frame, bg=biosim_theme('panel'))
                btn.pack(side='left', padx=3, pady=2)
                b = tk.Button(btn, text='{} {}'.format(icon_char, name[:14]),
                               bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                               font=('Arial', 9, 'bold'), cursor='hand2',
                               padx=6, pady=2,
                               command=lambda k=okey: self._cons_select_output(k))
                b.pack()
            return

        # ── Modules ──
        if cat == 'modules':
            for mkey, mdata in CIRCUIT_MODULES.items():
                name = mdata['name_ru'] if self.lang == 'ru' else mdata['name_en']
                color = mdata['color']
                btn = tk.Frame(self._cons_parts_frame, bg=biosim_theme('panel'))
                btn.pack(side='left', padx=3, pady=2)
                b = tk.Button(btn, text='◫ {}'.format(name[:14]),
                               bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                               font=('Arial', 9, 'bold'), cursor='hand2',
                               padx=6, pady=2,
                               command=lambda k=mkey: self._cons_load_module(k))
                b.pack()
            return

        # ── Wet-lab ──
        if cat == 'wetlab':
            for wkey, wdata in CIRCUIT_WETLAB.items():
                name = wdata['name_ru'] if self.lang == 'ru' else wdata['name_en']
                color = wdata['color']
                btn = tk.Frame(self._cons_parts_frame, bg=biosim_theme('panel'))
                btn.pack(side='left', padx=3, pady=2)
                b = tk.Button(btn, text='⊟ {}'.format(name[:14]),
                               bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                               font=('Arial', 9, 'bold'), cursor='hand2',
                               padx=6, pady=2,
                               command=lambda k=wkey: self._cons_select_wetlab(k))
                b.pack()
            return

        # ── Parts (elements, proteins, molecules, compartments) ──
        cat_to_family = {
            'elements':     'Genes',
            'proteins':     'Proteins',
            'molecules':    'Small molecules',
            'compartments': 'Compartments',
        }
        target_family = cat_to_family.get(cat)
        if target_family:
            for pkey, pdata in CIRCUIT_PARTS_CATALOG.items():
                if not pdata['family'].startswith(target_family):
                    continue
                name = pdata['name_ru'] if self.lang == 'ru' else pdata['name_en']
                color = pdata['color']
                # Draw a real SBOL glyph icon on the button
                self._cons_make_part_button(
                    self._cons_parts_frame, pdata.get('icon', 'cds'), color, name,
                    lambda k=pkey: self._cons_select_part(k))
        # Update scrollregion after redraw
        self._cons_parts_frame.update_idletasks()
        self._cons_parts_canvas.configure(
            scrollregion=self._cons_parts_canvas.bbox('all'))

    def _make_glyph_canvas(self, parent, glyph, color, size=34):
        """Draw an SBOL-style genetic-part glyph on a small Canvas, so part
        buttons show a real drawn icon instead of a text symbol. Returns the
        Canvas widget. `glyph` maps to a drawing routine.

        The original artwork was designed for size=34; `s` scales every offset
        so the same glyph can be drawn smaller (compact palette buttons) without
        spilling over the canvas edge. Line width scales too but never below 1.
        """
        cv = tk.Canvas(parent, width=size, height=size, bg=biosim_theme('panel'),
                       highlightthickness=0)
        w = size
        m = w / 2  # midpoint
        s = size / 34.0  # scale factor relative to the original 34px design
        lw = max(1, int(round(3 * s)))  # scaled line width
        # Each glyph drawn with simple primitives (SBOL Visual conventions)
        if glyph == 'promoter':
            cv.create_line(m-11*s, m+9*s, m-11*s, m-7*s, fill=color, width=lw)
            cv.create_line(m-11*s, m-7*s, m+8*s, m-7*s, fill=color, width=lw)
            cv.create_polygon(m+6*s, m-11*s, m+6*s, m-3*s, m+13*s, m-7*s, fill=color)
        elif glyph == 'rbs':
            cv.create_arc(m-11*s, m-4*s, m+11*s, m+18*s, start=0, extent=180,
                          fill=color, outline=color)
        elif glyph == 'cds':
            cv.create_polygon(m-12*s, m-7*s, m+3*s, m-7*s, m+12*s, m,
                              m+3*s, m+7*s, m-12*s, m+7*s, fill=color)
        elif glyph == 'terminator':
            cv.create_line(m, m-10*s, m, m+10*s, fill=color, width=lw)
            cv.create_line(m-10*s, m-10*s, m+10*s, m-10*s, fill=color, width=lw)
        elif glyph in ('binding_site', 'operator'):
            cv.create_rectangle(m-11*s, m-7*s, m+11*s, m+7*s, outline=color, width=lw)
        elif glyph == 'tag':
            cv.create_oval(m-8*s, m-8*s, m+8*s, m+8*s, outline=color, width=lw)
            cv.create_text(m, m, text='T', fill=color,
                           font=('Arial', max(6, int(round(9 * s))), 'bold'))
        elif glyph == 'activation':
            cv.create_line(m-12*s, m, m+8*s, m, fill=color, width=lw)
            cv.create_polygon(m+6*s, m-5*s, m+6*s, m+5*s, m+13*s, m, fill=color)
        elif glyph == 'repression':
            cv.create_line(m-12*s, m, m+10*s, m, fill=color, width=lw)
            cv.create_line(m+10*s, m-8*s, m+10*s, m+8*s, fill=color, width=lw)
        elif glyph == 'degradation':
            cv.create_oval(m-11*s, m-11*s, m+11*s, m+11*s, outline=color, width=lw)
            cv.create_line(m-5*s, m-5*s, m+5*s, m+5*s, fill=color, width=lw)
            cv.create_line(m-5*s, m+5*s, m+5*s, m-5*s, fill=color, width=lw)
        elif glyph == 'event':
            cv.create_polygon(m, m-11*s, m+11*s, m, m, m+11*s, m-11*s, m,
                              outline=color, width=lw, fill='')
        elif glyph == 'protein':
            cv.create_oval(m-10*s, m-7*s, m+10*s, m+7*s, outline=color, width=lw)
        elif glyph == 'molecule':
            cv.create_oval(m-6*s, m-6*s, m+6*s, m+6*s, fill=color, outline=color)
        elif glyph == 'settings':
            for dy in (-8*s, 0, 8*s):
                cv.create_oval(m-3*s, m+dy-3*s, m+3*s, m+dy+3*s, fill=color, outline=color)
        else:
            # Default: small filled circle
            cv.create_oval(m-7*s, m-7*s, m+7*s, m+7*s, fill=color, outline=color)
        return cv

    def _cons_make_part_button(self, parent, glyph, color, name, command):
        """Create a compact part button: a small drawn SBOL glyph on the LEFT
        and the name on the RIGHT, on a single row so the button stays low
        (matches the compact text buttons), instead of a tall icon-over-text.
        """
        btn = tk.Frame(parent, bg=biosim_theme('panel'), highlightbackground='#1c2128',
                       highlightthickness=1, cursor='hand2')
        btn.pack(side='left', padx=3, pady=2)
        gc = self._make_glyph_canvas(btn, glyph, color, size=18)
        gc.pack(side='left', padx=(4, 2), pady=2)
        lbl = tk.Label(btn, text=name[:14], bg=biosim_theme('panel'), fg=color,
                       font=('Arial', 9, 'bold'), cursor='hand2')
        lbl.pack(side='left', padx=(0, 6), pady=2)
        for w in (btn, gc, lbl):
            w.bind('<Button-1>', lambda e, c=command: c())
        return btn

    def _cons_set_arrow_tool(self):
        """Reset to normal arrow/select mode."""
        self._cons_selected_part = None
        self._cons_selected_reaction = None
        self._cons_selected_reaction_template_group = None
        self._cons_close_reaction_template_popup()
        self._cons_selected_regulation_button = None
        self._cons_close_regulation_popup()
        self._cons_connect_source = None
        # Reset category buttons
        for ck, (btn, color) in self._cons_cat_buttons.items():
            btn.config(bg=biosim_theme('panel2'), fg=color)
        self._cons_selected_category = None
        # Clear parts panel
        for w in self._cons_parts_frame.winfo_children():
            w.destroy()
        tk.Label(self._cons_parts_frame,
                  text=self._t('tool_arrow_hint'),
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 11, 'italic')).pack(padx=20, pady=20)
        # Reset cursor
        try:
            self.cons_canvas.config(cursor='arrow')
        except Exception as _exc:
            biosim_log('warn', '_cons_set_arrow_tool: {}'.format(_exc))
        self._cons_status_lbl.config(text=self._t('cons_canvas_hint'))

    def _cons_select_part(self, part_key):
        """User chose a part — arm placement on canvas."""
        self._cons_selected_part = part_key
        self._cons_selected_reaction = None
        self._cons_selected_reaction_template_group = None
        self._cons_close_reaction_template_popup()
        self._cons_selected_regulation_button = None
        self._cons_close_regulation_popup()
        self._cons_connect_source = None
        pdata = CIRCUIT_PARTS_CATALOG.get(part_key, {})
        name = pdata.get('name_ru' if self.lang == 'ru' else 'name_en', part_key)
        # Special hint for binding sites
        if pdata.get('icon') == 'binding_site':
            hint = (' · Поставь между промотором и геном, потом соедини с белком через "Связывание"'
                     if self.lang == 'ru'
                     else ' · Place between promoter and gene, then connect to TF via Binding')
        else:
            hint = ' · ' + ('Кликни на холсте' if self.lang == 'ru' else 'Click canvas')
        self._cons_status_lbl.config(
            text=self._t('cons_selected_part') + ' ' + name + hint)
        try:
            self.cons_canvas.config(cursor='plus')
        except Exception as _exc:
            biosim_log('warn', '_cons_select_part: {}'.format(_exc))

    def _cons_select_reaction(self, rxn_key):
        """User chose a reaction — switch to connect mode."""
        self._cons_selected_reaction = rxn_key
        self._cons_selected_part = None
        self._cons_selected_reaction_template_group = None
        self._cons_close_reaction_template_popup()
        self._cons_selected_regulation_button = None
        self._cons_close_regulation_popup()
        self._cons_connect_source = None
        # Reset multi-source/target buffers
        self._cons_conn_sources = None
        self._cons_conn_targets = None
        rdata = CIRCUIT_REACTIONS.get(rxn_key, {})
        name = rdata.get('name_ru' if self.lang == 'ru' else 'name_en', rxn_key)
        # Custom hint for X-to-Y reactions
        stoich = rdata.get('stoichiometry')
        if stoich is not None and (stoich[0] > 1 or stoich[1] > 1):
            n_src, n_tgt = stoich
            if self.lang == 'ru':
                hint = ' · Выбери {} источник(ов), потом {} цель(ей)'.format(n_src, n_tgt)
            else:
                hint = ' · Pick {} source(s), then {} target(s)'.format(n_src, n_tgt)
        else:
            hint = ' · ' + ('Кликни источник' if self.lang == 'ru' else 'Click source')
        self._cons_status_lbl.config(
            text=self._t('cons_selected_rxn') + ' ' + name + hint)
        try:
            self.cons_canvas.config(cursor='crosshair')
        except Exception as _exc:
            biosim_log('warn', '_cons_select_reaction: {}'.format(_exc))

    def _cons_select_reaction_template_group(self, group_key):
        """User picked a stoichiometry button that has templates ('1 to 1' or
        '2 to 1'). Arm template mode: the next left-click on the canvas opens a
        popup of concrete templates to drop at that spot.
        """
        self._cons_selected_reaction_template_group = group_key
        self._cons_selected_reaction = None
        self._cons_selected_part = None
        self._cons_connect_source = None
        self._cons_conn_sources = None
        self._cons_conn_targets = None
        hint = (' · Кликни на холст — покажу варианты'
                if self.lang == 'ru'
                else ' · Click the canvas — I will show variants')
        label = '1 → 1' if group_key == '1_to_1' else '2 → 1'
        try:
            self._cons_status_lbl.config(
                text=(('Реакция ' if self.lang == 'ru' else 'Reaction ')
                      + label + hint))
        except Exception:
            pass
        try:
            self.cons_canvas.config(cursor='crosshair')
        except Exception as _exc:
            biosim_log('warn', '_cons_select_reaction_template_group: {}'.format(_exc))

    def _cons_select_output(self, output_key):
        """User chose an output/reporter — arm placement as special node."""
        odata = CIRCUIT_OUTPUTS.get(output_key)
        if not odata:
            return
        self._cons_selected_part = '__output__' + output_key
        self._cons_selected_reaction = None
        name = odata['name_ru'] if self.lang == 'ru' else odata['name_en']
        self._cons_status_lbl.config(
            text=self._t('cons_selected_part') + ' ' + name + ' · ' + (
                'Кликни на холсте' if self.lang == 'ru' else 'Click canvas'))
        try:
            self.cons_canvas.config(cursor='plus')
        except Exception as _exc:
            biosim_log('warn', '_cons_select_output: {}'.format(_exc))

    def _cons_select_input(self, input_key):
        """User chose an input signal — arm placement as special node."""
        idata = CIRCUIT_INPUTS.get(input_key)
        if not idata:
            return
        # Treat input as a special "node" with extra type marker
        self._cons_selected_part = '__input__' + input_key
        self._cons_selected_reaction = None
        name = idata['name_ru'] if self.lang == 'ru' else idata['name_en']
        self._cons_status_lbl.config(
            text=self._t('cons_selected_part') + ' ' + name + ' · ' + (
                'Кликни на холсте' if self.lang == 'ru' else 'Click canvas'))
        try:
            self.cons_canvas.config(cursor='plus')
        except Exception as _exc:
            biosim_log('warn', '_cons_select_input: {}'.format(_exc))

    def _cons_load_module(self, module_key):
        """Load a ready-made module preset into the constructor."""
        # Map module to existing preset or generate
        preset_map = {
            'oscillator': 'repressilator',
            'toggle_switch': 'toggle_switch',
            'incoherent_ff': 'feedforward',
            'coherent_ff': 'feedforward',
            'new_module': 'empty',
        }
        preset_key = preset_map.get(module_key, 'empty')
        # Use existing preset loader; for new modules, just clear
        if preset_key == 'empty':
            self._save_history('constructor')
            self.current_state['constructor'] = {
                'name': CIRCUIT_MODULES[module_key]['name_ru'] if self.lang == 'ru' else CIRCUIT_MODULES[module_key]['name_en'],
                'description': '',
                'nodes': [], 'edges': [], 'init': {}, 'chains': [],
            }
            self._cons_refresh()
        else:
            # Load preset (existing function from circuit code)
            preset = GENE_CIRCUIT_PRESETS.get(preset_key)
            if not preset:
                return
            self._save_history('constructor')
            # Copy preset nodes + assign icons
            nodes = []
            for n in preset['nodes']:
                n_copy = dict(n)
                if 'icon' not in n_copy:
                    n_copy['icon'] = 'protein_circle'
                if 'color' not in n_copy:
                    colors = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df', '#bc4c00']
                    idx = (ord(n['id'][0].upper()) - 65) % len(colors)
                    n_copy['color'] = colors[idx]
                nodes.append(n_copy)
            self.current_state['constructor'] = {
                'name': preset['name'], 'description': preset['description'],
                'nodes': nodes,
                'edges': [dict(e) for e in preset['edges']],
                'init': dict(preset['init']),
                'chains': [],
            }
            self._cons_refresh()
        self._cons_status_lbl.config(
            text=('Загружен модуль' if self.lang == 'ru' else 'Module loaded'))

    def _cons_select_wetlab(self, wetlab_key):
        """Open wet-lab data loader dialog."""
        wdata = CIRCUIT_WETLAB.get(wetlab_key)
        if not wdata:
            return
        # For 'data' and 'fluor_data' — load CSV/Excel
        if wetlab_key in ('data', 'fluor_data'):
            self._cons_load_wetlab_data()
        elif wetlab_key in ('microscope', 'fluor_microscope'):
            # Real microscope image loader
            self._cons_load_microscope_image(
                is_fluorescent=(wetlab_key == 'fluor_microscope'))
        else:
            name = wdata['name_ru'] if self.lang == 'ru' else wdata['name_en']
            self.toast('Unknown wetlab type: ' + str(name), level='warn')

    def _cons_load_microscope_image(self, is_fluorescent=False):
        """Load and analyze microscope image with quantification."""
        try:
            from PIL import Image, ImageTk
        except ImportError as _exc:
            biosim_log('warn', '_cons_load_microscope_image: {}'.format(_exc))
            self.toast('Pillow (PIL) not installed' if self.lang == 'en'
                        else 'Pillow (PIL) не установлен', level='error')
            return
        
        from tkinter import filedialog
        filepath = filedialog.askopenfilename(
            title='Open microscope image' if self.lang == 'en'
                  else 'Открыть микроскопическое изображение',
            filetypes=[('Image files', '*.tif *.tiff *.png *.jpg *.jpeg *.bmp'),
                        ('All files', '*.*')])
        if not filepath:
            return
        
        try:
            img = Image.open(filepath)
            # Convert to RGB or grayscale as needed
            if img.mode not in ('RGB', 'RGBA', 'L'):
                img = img.convert('RGB')
        except Exception as e:
            biosim_log('warn', '_cons_load_microscope_image: {}'.format(e))
            self.toast('Cannot open image: ' + str(e)[:60], level='error')
            return
        
        # Build dialog
        dlg = tk.Toplevel(self)
        title = 'Fluorescence Microscope' if is_fluorescent else 'Microscope'
        dlg.title(title)
        dlg.geometry('960x720')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        
        # Header
        tk.Label(dlg, text=title,
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=(10, 4))
        tk.Label(dlg, text=os.path.basename(filepath),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()
        
        # Main split: image left, controls/results right
        main = tk.Frame(dlg, bg=biosim_theme('bg'))
        main.pack(fill='both', expand=True, padx=10, pady=8)
        
        # Image area (left)
        img_frame = tk.Frame(main, bg=biosim_theme('panel'),
                                highlightthickness=2,
                                highlightbackground=biosim_theme('border'))
        img_frame.pack(side='left', fill='both', expand=True, padx=(0, 6))
        img_canvas = tk.Canvas(img_frame, bg=biosim_theme('bg'), highlightthickness=0)
        img_canvas.pack(fill='both', expand=True)
        
        # Resize image to fit (max 600x600)
        max_dim = 600
        w, h = img.size
        scale = min(max_dim / w, max_dim / h, 1.0)
        new_w, new_h = int(w * scale), int(h * scale)
        img_display = img.resize((new_w, new_h), Image.LANCZOS)
        photo = ImageTk.PhotoImage(img_display)
        img_canvas.image = photo  # keep reference!
        img_canvas.create_image(new_w // 2 + 10, new_h // 2 + 10,
                                   image=photo)
        
        # Controls and info (right)
        ctrl_frame = tk.Frame(main, bg=biosim_theme('bg'), width=300)
        ctrl_frame.pack(side='right', fill='y')
        ctrl_frame.pack_propagate(False)
        
        # Image info
        info_frame = tk.LabelFrame(ctrl_frame,
                                      text=' ' + ('Изображение' if self.lang == 'ru'
                                                       else 'Image info') + ' ',
                                      bg=biosim_theme('bg'), fg='#0550ae',
                                      font=('Arial', 10, 'bold'), relief='flat')
        info_frame.pack(fill='x', pady=4)
        info_text = (
            'Размер: {}×{}\n'.format(w, h) +
            'Режим: {}\n'.format(img.mode) +
            'Формат: {}\n'.format(img.format or '?')
        ) if self.lang == 'ru' else (
            'Size: {}×{}\n'.format(w, h) +
            'Mode: {}\n'.format(img.mode) +
            'Format: {}\n'.format(img.format or '?')
        )
        tk.Label(info_frame, text=info_text, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                  font=('Courier', 9), anchor='w', justify='left'
                  ).pack(padx=8, pady=4, anchor='w')
        
        # Compute statistics
        stats_frame = tk.LabelFrame(ctrl_frame,
                                       text=' ' + ('Статистика' if self.lang == 'ru'
                                                        else 'Statistics') + ' ',
                                       bg=biosim_theme('bg'), fg='#1a7f37',
                                       font=('Arial', 10, 'bold'), relief='flat')
        stats_frame.pack(fill='x', pady=4)
        
        try:
            arr = np.array(img.convert('L'))  # grayscale for stats
            stats_text = (
                'Среднее: {:.2f}\n'.format(arr.mean()) +
                'Медиана: {:.1f}\n'.format(np.median(arr)) +
                'Std: {:.2f}\n'.format(arr.std()) +
                'Минимум: {}\n'.format(arr.min()) +
                'Максимум: {}\n'.format(arr.max())
            ) if self.lang == 'ru' else (
                'Mean: {:.2f}\n'.format(arr.mean()) +
                'Median: {:.1f}\n'.format(np.median(arr)) +
                'Std: {:.2f}\n'.format(arr.std()) +
                'Min: {}\n'.format(arr.min()) +
                'Max: {}\n'.format(arr.max())
            )
            tk.Label(stats_frame, text=stats_text, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                      font=('Courier', 9), anchor='w', justify='left'
                      ).pack(padx=8, pady=4, anchor='w')
        except Exception as e:
            biosim_log('warn', '_cons_load_microscope_image: {}'.format(e))
            tk.Label(stats_frame, text='Error: ' + str(e)[:40],
                      bg=biosim_theme('bg'), fg='#cf222e', font=('Arial', 9)
                      ).pack(padx=8, pady=4)
        
        # Fluorescence-specific: cell counting / intensity quantification
        if is_fluorescent:
            fluor_frame = tk.LabelFrame(ctrl_frame,
                                            text=' ' + ('Флуоресценция' if self.lang == 'ru'
                                                            else 'Fluorescence') + ' ',
                                            bg=biosim_theme('bg'), fg='#9a6700',
                                            font=('Arial', 10, 'bold'), relief='flat')
            fluor_frame.pack(fill='x', pady=4)
            
            # Threshold slider for "positive" pixels
            threshold_var = tk.IntVar(value=128)
            result_lbl = tk.Label(fluor_frame, text='', bg=biosim_theme('bg'), fg=biosim_theme('text'),
                                     font=('Courier', 9), anchor='w', justify='left')
            result_lbl.pack(padx=8, pady=2, anchor='w')
            
            def update_threshold(*a):
                try:
                    arr_l = np.array(img.convert('L'))
                    th = threshold_var.get()
                    n_above = int(np.sum(arr_l > th))
                    pct = 100 * n_above / arr_l.size
                    mean_above = float(arr_l[arr_l > th].mean()) if n_above > 0 else 0
                    txt = (
                        'Порог: {}\n'.format(th) +
                        '>порога: {} пикс ({:.2f}%)\n'.format(n_above, pct) +
                        'Среднее: {:.2f}\n'.format(mean_above) +
                        'Total intensity: {:.0f}\n'.format(float(arr_l.sum()))
                    ) if self.lang == 'ru' else (
                        'Threshold: {}\n'.format(th) +
                        '>threshold: {} px ({:.2f}%)\n'.format(n_above, pct) +
                        'Mean: {:.2f}\n'.format(mean_above) +
                        'Total intensity: {:.0f}\n'.format(float(arr_l.sum()))
                    )
                    result_lbl.config(text=txt)
                except Exception as _exc:
                    biosim_log('warn', 'update_threshold: {}'.format(_exc))
            
            tk.Label(fluor_frame, text=('Порог (0-255):' if self.lang == 'ru'
                                          else 'Threshold (0-255):'),
                      bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                      font=('Arial', 9)).pack(anchor='w', padx=8)
            tk.Scale(fluor_frame, from_=0, to=255, orient='horizontal',
                      variable=threshold_var, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                      highlightthickness=0, troughcolor='#eef1f5',
                      activebackground='#9a6700', command=update_threshold
                      ).pack(fill='x', padx=8)
            update_threshold()
        
        # Histogram button
        def show_histogram():
            try:
                fig, ax = plt.subplots(figsize=(6, 3.5), facecolor='#f5f7fa')
                ax.set_facecolor('#ffffff')
                arr_l = np.array(img.convert('L'))
                ax.hist(arr_l.ravel(), bins=64, color='#1a7f37', alpha=0.8,
                          edgecolor='#f5f7fa')
                ax.set_xlabel('Pixel intensity', color='#1c2128')
                ax.set_ylabel('Count', color='#1c2128')
                ax.set_title('Intensity histogram', color='#0550ae')
                ax.tick_params(colors='#57606a')
                for sp in ax.spines.values(): sp.set_color('#d0d7de')
                
                hdlg = tk.Toplevel(dlg)
                hdlg.title('Histogram')
                hdlg.geometry('640x400')
                hdlg.configure(bg=biosim_theme('bg'))
                cv = FigureCanvasTkAgg(fig, master=hdlg)
                cv.get_tk_widget().pack(fill='both', expand=True)
            except Exception as e:
                biosim_log('warn', 'show_histogram: {}'.format(e))
                self.toast('Histogram error: ' + str(e)[:50], level='error')
        
        tk.Button(ctrl_frame, text=('Гистограмма' if self.lang == 'ru'
                                              else 'Histogram'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=show_histogram).pack(fill='x', pady=4)
        
        # Save data to wetlab_data
        def attach_to_project():
            try:
                arr_l = np.array(img.convert('L'))
                # Store key metrics as wetlab data
                state = self.current_state['constructor']
                if state is None:
                    return
                if 'wetlab_images' not in state:
                    state['wetlab_images'] = []
                state['wetlab_images'].append({
                    'filename': os.path.basename(filepath),
                    'path': filepath,
                    'type': 'fluorescent' if is_fluorescent else 'brightfield',
                    'width': w, 'height': h,
                    'mean_intensity': float(arr_l.mean()),
                    'total_intensity': float(arr_l.sum()),
                    'std_intensity': float(arr_l.std()),
                })
                self.toast('Image data attached to project',
                            level='success', duration=2000)
            except Exception as e:
                biosim_log('warn', 'attach_to_project: {}'.format(e))
                self.toast('Error: ' + str(e)[:50], level='error')
        
        tk.Button(ctrl_frame, text=('Прикрепить к проекту' if self.lang == 'ru'
                                              else 'Attach to project'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=attach_to_project).pack(fill='x', pady=4)
        
        tk.Button(ctrl_frame, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy).pack(fill='x', pady=4)
        
        biosim_log('success', 'Microscope image loaded: ' + filepath)

    def _cons_load_wetlab_data(self):
        """Open file dialog and load CSV/Excel data."""
        if not _ensure_pandas():
            messagebox.showwarning('VIREON', self._t('pandas_not_installed'))
            return
        from tkinter import filedialog
        filepath = filedialog.askopenfilename(
            title=self._t('wetlab_load_title'),
            filetypes=[('Data files', '*.csv *.tsv *.xlsx *.xls'),
                        ('CSV files', '*.csv'),
                        ('Excel files', '*.xlsx *.xls'),
                        ('All files', '*.*')])
        if not filepath:
            return
        data, msg = load_csv_data(filepath)
        if data is None:
            messagebox.showerror('VIREON', msg)
            return
        # Save to constructor state
        state = self.current_state['constructor']
        if state is None:
            state = {'name': 'Untitled', 'description': '', 'nodes': [], 'edges': [],
                      'init': {}, 'chains': []}
            self.current_state['constructor'] = state
        state['wetlab_data'] = data
        state['wetlab_filename'] = os.path.basename(filepath)
        # Show preview
        self._cons_show_wetlab_preview(data, filepath)

    def _cons_show_wetlab_preview(self, data, filepath):
        """Show preview of loaded data with action buttons."""
        dlg = tk.Toplevel(self)
        dlg.title(self._t('wetlab_loaded'))
        dlg.geometry('720x580')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('wetlab_loaded') + ' ' + os.path.basename(filepath),
                  bg=biosim_theme('bg'), fg='#9a6700',
                  font=('Arial', 13, 'bold')).pack(pady=(10, 4))

        info = '{} {}  ·  {} {}'.format(
            self._t('wetlab_rows'), data['n_rows'],
            self._t('wetlab_columns'), len(data['col_names']))
        tk.Label(dlg, text=info, bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(pady=2)

        # Preview text
        preview_frame = tk.LabelFrame(dlg, text=self._t('wetlab_columns'),
                                        bg=biosim_theme('panel'), fg='#0550ae',
                                        font=('Arial', 10, 'bold'), relief='flat')
        preview_frame.pack(fill='both', expand=True, padx=10, pady=4)
        txt = scrolledtext.ScrolledText(preview_frame, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                                          font=('Courier', 9), relief='flat',
                                          wrap='none', highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=4, pady=4)
        # Header
        col_names = data['col_names']
        txt.insert('end', ' | '.join('{:>12}'.format(c[:12]) for c in col_names) + '\n')
        txt.insert('end', '-' * (15 * len(col_names)) + '\n')
        # Rows (up to first 30)
        cols = data['columns']
        max_rows = min(30, data['n_rows'])
        for i in range(max_rows):
            row = []
            for c in col_names:
                vals = cols.get(c, [])
                if i < len(vals):
                    v = vals[i]
                    if isinstance(v, float):
                        row.append('{:>12.4f}'.format(v))
                    else:
                        row.append('{:>12}'.format(str(v)[:12]))
                else:
                    row.append('{:>12}'.format(''))
            txt.insert('end', ' | '.join(row) + '\n')
        if data['n_rows'] > max_rows:
            txt.insert('end', '\n... and {} more rows\n'.format(data['n_rows'] - max_rows))
        txt.config(state='disabled')

        # Action buttons
        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=10, pady=8)
        tk.Button(btn_row, text='' + self._t('wetlab_compare'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=lambda: (dlg.destroy(), self._cons_compare_data_with_sim())
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text='' + self._t('wetlab_plot'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=lambda: (dlg.destroy(), self._cons_plot_wetlab_data())
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text='Σ ' + self._t('wetlab_stats'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=lambda: (dlg.destroy(), self._cons_stats_dialog())
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy).pack(side='right', padx=2)

    def _cons_plot_wetlab_data(self):
        """Plot loaded data — each column as a line."""
        state = self.current_state['constructor']
        data = state.get('wetlab_data') if state else None
        if data is None:
            messagebox.showinfo('VIREON', self._t('wetlab_no_data'))
            return
        plot_dlg = tk.Toplevel(self)
        plot_dlg.title(self._t('wetlab_plot'))
        plot_dlg.geometry('780x540')
        plot_dlg.configure(bg=biosim_theme('bg'))
        fig, ax = plt.subplots(figsize=(7.5, 4.5), facecolor='#f5f7fa')
        ax.set_facecolor('#ffffff')
        ax.tick_params(colors='#57606a')
        for sp in ax.spines.values(): sp.set_color('#d0d7de')
        # Find time column
        time_col = None
        for cname in data['col_names']:
            if cname.lower() in ('time', 't', 'час', 'hours', 'h'):
                time_col = cname; break
        if time_col is None and data['col_names']:
            time_col = data['col_names'][0]
        t_vals = data['columns'].get(time_col, list(range(data['n_rows'])))
        colors_list = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df', '#bc4c00', '#0550ae']
        ci = 0
        for cname in data['col_names']:
            if cname == time_col:
                continue
            vals = data['columns'].get(cname)
            if not vals:
                continue
            n = min(len(t_vals), len(vals))
            ax.plot(t_vals[:n], vals[:n],
                     color=colors_list[ci % len(colors_list)],
                     marker='o', markersize=4, lw=1.4, label=cname[:14])
            ci += 1
        ax.set_xlabel(time_col, color='#57606a')
        ax.set_ylabel('value', color='#57606a')
        ax.set_title('Wet-lab data: ' + state.get('wetlab_filename', ''),
                      color='#1c2128', fontsize=10)
        ax.legend(facecolor='#eef1f5', edgecolor='#d0d7de', labelcolor='#1c2128', fontsize=8)
        ax.grid(True, color='#eef1f5', lw=0.5)
        cv = FigureCanvasTkAgg(fig, master=plot_dlg)
        cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
        tk.Button(plot_dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11), cursor='hand2',
                   command=plot_dlg.destroy).pack(fill='x', padx=12, pady=8)

    def _cons_compare_data_with_sim(self):
        """Compare loaded experimental data with ODE simulation of the model."""
        state = self.current_state['constructor']
        data = state.get('wetlab_data') if state else None
        if data is None:
            messagebox.showinfo('VIREON', self._t('wetlab_no_data'))
            return
        if not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return
        # Determine simulation end time from data
        time_col = None
        for cname in data['col_names']:
            if cname.lower() in ('time', 't', 'час', 'hours', 'h'):
                time_col = cname; break
        if time_col is None:
            time_col = data['col_names'][0]
        t_max = float(max(data['columns'][time_col])) if data['columns'].get(time_col) else 100
        # Run ODE
        t_sim, y_sim, ids = run_ode_simulation(state['nodes'], state['edges'],
                                                  state['init'], t_end=t_max * 1.1)
        if t_sim is None:
            messagebox.showerror('VIREON', self._t('adv_failed'))
            return
        # Compare
        comparison = compare_data_with_simulation(t_sim, y_sim, ids, data)
        if not comparison:
            messagebox.showinfo('VIREON', self._t('wetlab_no_match'))
            return
        # Show plot with both curves + statistics
        plot_dlg = tk.Toplevel(self)
        plot_dlg.title(self._t('wetlab_compare'))
        plot_dlg.geometry('800x680')
        plot_dlg.configure(bg=biosim_theme('bg'))
        tk.Label(plot_dlg, text='' + self._t('wetlab_compare'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=8)

        # Plot
        n_curves = len(comparison)
        fig, ax = plt.subplots(figsize=(7.5, 4), facecolor='#f5f7fa')
        ax.set_facecolor('#ffffff')
        ax.tick_params(colors='#57606a')
        for sp in ax.spines.values(): sp.set_color('#d0d7de')
        colors_list = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df']
        ci = 0
        for col_name, info in comparison.items():
            c = colors_list[ci % len(colors_list)]
            # Simulation curve
            i_node = ids.index(info['matched_node'])
            ax.plot(t_sim, y_sim[:, i_node], color=c, lw=1.6,
                     label='{} sim'.format(col_name[:8]), alpha=0.8)
            # Experimental points
            ax.scatter(info['t_exp'], info['y_exp'], color=c, s=40,
                        edgecolor='white', linewidth=1, zorder=5,
                        label='{} exp'.format(col_name[:8]))
            ci += 1
        ax.set_xlabel('time', color='#57606a')
        ax.set_ylabel('concentration', color='#57606a')
        ax.legend(facecolor='#eef1f5', edgecolor='#d0d7de', labelcolor='#1c2128',
                   fontsize=8, ncol=2)
        ax.grid(True, color='#eef1f5', lw=0.5)
        cv = FigureCanvasTkAgg(fig, master=plot_dlg)
        cv.get_tk_widget().pack(fill='x', padx=10, pady=4)

        # Statistics
        stat_frame = tk.LabelFrame(plot_dlg, text=self._t('compare_stats'),
                                     bg=biosim_theme('panel'), fg='#1a7f37',
                                     font=('Arial', 10, 'bold'), relief='flat')
        stat_frame.pack(fill='both', expand=True, padx=10, pady=4)
        stat_txt = scrolledtext.ScrolledText(stat_frame, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                                                font=('Courier', 10), relief='flat',
                                                wrap='word', highlightthickness=0)
        stat_txt.pack(fill='both', expand=True, padx=4, pady=4)
        stat_txt.insert('end', '{:>12} {:>10} {:>10} {:>10}\n'.format(
            'Column', 'RMSE', 'MAE', 'R²'))
        stat_txt.insert('end', '-' * 50 + '\n')
        for col_name, info in comparison.items():
            stat_txt.insert('end', '{:>12} {:>10.4f} {:>10.4f} {:>10.4f}\n'.format(
                col_name[:12], info['rmse'], info['mae'], info['r2']))
        # Interpret R²
        avg_r2 = np.mean([info['r2'] for info in comparison.values()])
        stat_txt.insert('end', '\n')
        if avg_r2 > 0.9:
            interp = ('Отличное соответствие модели и данных!' if self.lang == 'ru'
                       else 'Excellent model-data agreement!')
            tag_col = '#1a7f37'
        elif avg_r2 > 0.7:
            interp = ('Хорошее соответствие.' if self.lang == 'ru'
                       else 'Good agreement.')
            tag_col = '#0969da'
        elif avg_r2 > 0.4:
            interp = ('Среднее соответствие — модель нуждается в улучшении.'
                       if self.lang == 'ru'
                       else 'Moderate agreement — model needs tuning.')
            tag_col = '#9a6700'
        else:
            interp = ('Слабое соответствие — модель плохо описывает данные.'
                       if self.lang == 'ru'
                       else 'Poor agreement — model does not fit data.')
            tag_col = '#cf222e'
        stat_txt.tag_config('interp', foreground=tag_col, font=('Arial', 11, 'bold'))
        stat_txt.insert('end', interp + '\n', 'interp')
        stat_txt.config(state='disabled')

        tk.Button(plot_dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11), cursor='hand2',
                   command=plot_dlg.destroy).pack(fill='x', padx=12, pady=6)

    def _cons_stats_dialog(self):
        """Open statistics dialog: t-test, ANOVA, regression on loaded data."""
        if not _ensure_statsmodels():
            messagebox.showwarning('VIREON', self._t('statsmodels_not_installed'))
            return
        state = self.current_state['constructor']
        data = state.get('wetlab_data') if state else None
        if data is None:
            messagebox.showinfo('VIREON', self._t('wetlab_no_data'))
            return

        dlg = tk.Toplevel(self)
        dlg.title(self._t('wetlab_stats'))
        dlg.geometry('580x520')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='Σ ' + self._t('wetlab_stats'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 14, 'bold')).pack(pady=(10, 6))

        # Column selectors (numeric columns only)
        numeric_cols = [c for c in data['col_names']
                          if data['columns'].get(c) and
                          all(isinstance(v, (int, float)) for v in data['columns'][c][:5])]

        if len(numeric_cols) < 2:
            tk.Label(dlg, text='Нужно минимум 2 числовых колонки' if self.lang == 'ru'
                       else 'Need at least 2 numeric columns',
                       bg=biosim_theme('bg'), fg='#cf222e',
                       font=('Arial', 11)).pack(pady=20)
            tk.Button(dlg, text=self._t('close_btn'), bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                       command=dlg.destroy).pack(pady=8)
            return

        # T-test section
        tt_frame = tk.LabelFrame(dlg, text=self._t('stats_t_test'),
                                   bg=biosim_theme('panel'), fg='#1a7f37',
                                   font=('Arial', 10, 'bold'), relief='flat')
        tt_frame.pack(fill='x', padx=12, pady=4)
        row1 = tk.Frame(tt_frame, bg=biosim_theme('panel')); row1.pack(fill='x', padx=4, pady=2)
        tk.Label(row1, text=self._t('pick_data_g1'), bg=biosim_theme('panel'), fg=biosim_theme('text_dim')).pack(side='left')
        g1_var = tk.StringVar(value=numeric_cols[0])
        ttk.Combobox(row1, textvariable=g1_var, values=numeric_cols,
                      state='readonly', width=14).pack(side='left', padx=4)
        tk.Label(row1, text=self._t('pick_data_g2'), bg=biosim_theme('panel'), fg=biosim_theme('text_dim')).pack(side='left', padx=(10, 0))
        g2_var = tk.StringVar(value=numeric_cols[1])
        ttk.Combobox(row1, textvariable=g2_var, values=numeric_cols,
                      state='readonly', width=14).pack(side='left', padx=4)

        tt_result = tk.Label(tt_frame, text='', bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                font=('Arial', 9), wraplength=540, justify='left')
        tt_result.pack(fill='x', padx=4, pady=4)

        def do_t_test():
            g1 = data['columns'].get(g1_var.get(), [])
            g2 = data['columns'].get(g2_var.get(), [])
            t, p, interp = run_t_test(g1, g2)
            if t is None:
                tt_result.config(text=interp, fg='#cf222e')
            else:
                tt_result.config(text='{}: {:.4f}  ·  {}: {:.4f}\n{}'.format(
                    self._t('stats_t_stat'), t, self._t('stats_p_value'), p, interp),
                    fg='#1a7f37' if p < 0.05 else '#1c2128')

        tk.Button(tt_frame, text=self._t('adv_run'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 9, 'bold'), cursor='hand2', pady=2,
                   command=do_t_test).pack(fill='x', padx=4, pady=2)

        # Linear regression section
        reg_frame = tk.LabelFrame(dlg, text=self._t('stats_regression'),
                                    bg=biosim_theme('panel'), fg='#0969da',
                                    font=('Arial', 10, 'bold'), relief='flat')
        reg_frame.pack(fill='x', padx=12, pady=4)
        row2 = tk.Frame(reg_frame, bg=biosim_theme('panel')); row2.pack(fill='x', padx=4, pady=2)
        tk.Label(row2, text=self._t('pick_data_x'), bg=biosim_theme('panel'), fg=biosim_theme('text_dim')).pack(side='left')
        x_var = tk.StringVar(value=numeric_cols[0])
        ttk.Combobox(row2, textvariable=x_var, values=numeric_cols,
                      state='readonly', width=14).pack(side='left', padx=4)
        tk.Label(row2, text=self._t('pick_data_y'), bg=biosim_theme('panel'), fg=biosim_theme('text_dim')).pack(side='left', padx=(10, 0))
        y_var = tk.StringVar(value=numeric_cols[1])
        ttk.Combobox(row2, textvariable=y_var, values=numeric_cols,
                      state='readonly', width=14).pack(side='left', padx=4)

        reg_result = tk.Label(reg_frame, text='', bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                 font=('Courier', 9), wraplength=540, justify='left')
        reg_result.pack(fill='x', padx=4, pady=4)

        def do_regression():
            xs = data['columns'].get(x_var.get(), [])
            ys = data['columns'].get(y_var.get(), [])
            n_min = min(len(xs), len(ys))
            if n_min < 3:
                reg_result.config(text='Not enough data', fg='#cf222e')
                return
            result = run_linear_regression(xs[:n_min], ys[:n_min])
            if result is None:
                reg_result.config(text='Regression failed', fg='#cf222e')
            else:
                msg = 'y = {:.4f}·x + {:.4f}\n{} {:.4f}  ·  {} {:.4f}'.format(
                    result['slope'], result['intercept'],
                    self._t('stats_r2'), result['r2'],
                    self._t('stats_p_value'), result['p_value'])
                reg_result.config(text=msg,
                    fg='#1a7f37' if result['r2'] > 0.5 else '#9a6700')

        tk.Button(reg_frame, text=self._t('adv_run'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 9, 'bold'), cursor='hand2', pady=2,
                   command=do_regression).pack(fill='x', padx=4, pady=2)

        # ANOVA: select up to 4 columns
        anova_frame = tk.LabelFrame(dlg, text=self._t('stats_anova'),
                                      bg=biosim_theme('panel'), fg='#9a6700',
                                      font=('Arial', 10, 'bold'), relief='flat')
        anova_frame.pack(fill='x', padx=12, pady=4)
        tk.Label(anova_frame,
                  text='Auto-run on all numeric columns' if self.lang == 'en'
                  else 'Авто на всех числовых колонках',
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'), font=('Arial', 9, 'italic')).pack(padx=4, pady=2)
        anova_result = tk.Label(anova_frame, text='', bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                  font=('Arial', 9), wraplength=540, justify='left')
        anova_result.pack(fill='x', padx=4, pady=4)

        def do_anova():
            groups = [data['columns'][c] for c in numeric_cols[:4]
                       if c in data['columns']]
            f, p, interp = run_anova(*groups)
            if f is None:
                anova_result.config(text=interp, fg='#cf222e')
            else:
                anova_result.config(text='{} {:.4f}  ·  {} {:.4f}\n{}'.format(
                    self._t('stats_f_stat'), f, self._t('stats_p_value'), p, interp),
                    fg='#9a6700')

        tk.Button(anova_frame, text=self._t('adv_run'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 9, 'bold'), cursor='hand2', pady=2,
                   command=do_anova).pack(fill='x', padx=4, pady=2)

        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy).pack(fill='x', padx=12, pady=8)

    def _cons_canvas_click(self, event):
        """Handle left click. Behavior depends on mode."""
        state = self.current_state['constructor']
        if state is None:
            return

        # Mode: a Regulation button is armed → open its popup at the cursor.
        #  • Empty canvas → popup with link/template entries.
        #  • Existing node → fall back to the button's first link (classic mode).
        rbtn = getattr(self, '_cons_selected_regulation_button', None)
        if rbtn is not None:
            _wxr, _wyr = self._s2w(event.x, event.y)
            if self._cons_find_node_at(_wxr, _wyr) is None:
                self._cons_regulation_click_world = (_wxr, _wyr)
                sx = self.cons_canvas.winfo_rootx() + event.x
                sy = self.cons_canvas.winfo_rooty() + event.y
                self._cons_show_regulation_popup(sx, sy, rbtn)
                return
            # Clicked a node → use the button's first link entry as connect mode.
            self._cons_selected_regulation_button = None
            for b in CIRCUIT_REGULATION_BUTTONS:
                if b['key'] == rbtn:
                    for en in b['entries']:
                        if en['kind'] == 'link':
                            self._cons_selected_reaction = en['value']
                            break
                    break

        # Mode: a reaction TEMPLATE group is armed (1-to-1 / 2-to-1).
        #  • Click on EMPTY canvas → open the template popup (create parts+edge).
        #  • Click on an EXISTING node → fall back to the classic connect mode
        #    for that stoichiometry, so the old way of wiring two existing nodes
        #    still works exactly as before.
        grp = getattr(self, '_cons_selected_reaction_template_group', None)
        if grp is not None:
            _wx0, _wy0 = self._s2w(event.x, event.y)
            if self._cons_find_node_at(_wx0, _wy0) is None:
                # Empty spot → template popup
                self._cons_template_click_world = (_wx0, _wy0)
                sx = self.cons_canvas.winfo_rootx() + event.x
                sy = self.cons_canvas.winfo_rooty() + event.y
                self._cons_show_reaction_template_popup(sx, sy, grp)
                return
            # Clicked an existing node → switch to classic connect mode for the
            # matching stoichiometry reaction, then let the normal handler run.
            self._cons_selected_reaction_template_group = None
            self._cons_selected_reaction = ('rxn_1_to_1' if grp == '1_to_1'
                                            else 'rxn_2_to_1')

        # Convert screen→world so zoom/pan don't break hit-testing.
        # We shadow event.x/event.y with world coords for the rest of this handler.
        _wx, _wy = self._s2w(event.x, event.y)
        event = _EvtProxy(event, _wx, _wy)

        # Mode: placing a part
        if self._cons_selected_part is not None:
            self._cons_place_part(event.x, event.y, self._cons_selected_part)
            self._cons_selected_part = None
            try:
                self.cons_canvas.config(cursor='arrow')
            except Exception as _exc:
                biosim_log('warn', '_cons_canvas_click: {}'.format(_exc))
            self._cons_status_lbl.config(text=self._t('cons_canvas_hint'))
            return

        clicked_node = self._cons_find_node_at(event.x, event.y)

        # Mode: connection
        if self._cons_selected_reaction is not None:
            if clicked_node is None:
                return
            rxn = self._cons_selected_reaction
            rxn_data = CIRCUIT_REACTIONS.get(rxn, {})
            stoich = rxn_data.get('stoichiometry')

            # Multi-step collection for X-to-Y reactions (e.g. (2, 1) = 2 sources 1 target)
            if stoich is not None and (stoich[0] > 1 or stoich[1] > 1):
                n_src_needed, n_tgt_needed = stoich
                # Initialize buffers if first click
                if not hasattr(self, '_cons_conn_sources') or self._cons_conn_sources is None:
                    self._cons_conn_sources = []
                    self._cons_conn_targets = []

                # If we haven't picked all sources yet add to sources
                if len(self._cons_conn_sources) < n_src_needed:
                    if clicked_node in self._cons_conn_sources:
                        self._cons_status_lbl.config(
                            text='Уже выбран — выбери другой' if self.lang == 'ru'
                                  else 'Already picked — choose another', fg='#cf222e')
                        return
                    self._cons_conn_sources.append(clicked_node)
                    if len(self._cons_conn_sources) < n_src_needed:
                        # Need more sources
                        self._cons_status_lbl.config(
                            text=self._t('stoich_n_sources_picked').format(
                                len(self._cons_conn_sources), n_src_needed),
                            fg='#1a7f37')
                    else:
                        # Sources done — now ask for targets
                        self._cons_status_lbl.config(
                            text=self._t('pick_targets') + ' (' +
                                  str(n_tgt_needed) + ')', fg='#9a6700')
                    return
                # Now collecting targets
                if len(self._cons_conn_targets) < n_tgt_needed:
                    if clicked_node in self._cons_conn_targets:
                        self._cons_status_lbl.config(
                            text='Уже выбран' if self.lang == 'ru' else 'Already picked',
                            fg='#cf222e')
                        return
                    self._cons_conn_targets.append(clicked_node)
                    if len(self._cons_conn_targets) < n_tgt_needed:
                        self._cons_status_lbl.config(
                            text=self._t('stoich_n_targets_picked').format(
                                len(self._cons_conn_targets), n_tgt_needed),
                            fg='#1a7f37')
                        return

                # All collected — create multi-source/multi-target edge(s)
                self._save_history('constructor')
                edge_type = 'activation'
                # Create a "hub" virtual point in the middle by storing sources/targets list
                # We model this as ONE edge entry with `sources` and `targets` lists
                state['edges'].append({
                    'from': self._cons_conn_sources[0],
                    'to': self._cons_conn_targets[0],
                    'sources': list(self._cons_conn_sources),
                    'targets': list(self._cons_conn_targets),
                    'type': edge_type, 'reaction': rxn,
                    'strength': 3.0, 'hill_n': 2,
                    'stoich_src': len(self._cons_conn_sources),
                    'stoich_tgt': len(self._cons_conn_targets),
                })
                self._cons_conn_sources = None
                self._cons_conn_targets = None
                self._cons_refresh()
                self._cons_status_lbl.config(
                    text=self._t('rxn_completed') + ' · ' + (
                        'кликни источник' if self.lang == 'ru' else 'click source'),
                    fg='#1a7f37')
                return

            # Standard 1-to-1: pick source, then target
            if self._cons_connect_source is None:
                self._cons_connect_source = clicked_node
                self._cons_status_lbl.config(
                    text=self._t('cons_source_set') + ' ' + clicked_node + ' · ' +
                         self._t('cons_click_target'))
            else:
                src = self._cons_connect_source
                tgt = clicked_node
                self._cons_connect_source = None
                if any(e['from'] == src and e['to'] == tgt and e.get('reaction') == rxn
                        for e in state['edges']):
                    self._cons_status_lbl.config(text=self._t('conn_exists'))
                    return
                # Soft validation (TinkerCell-style family rules): warn on
                # clearly-wrong pairings but let the user proceed if they insist.
                src_node = next((n for n in state['nodes'] if n['id'] == src), None)
                tgt_node = next((n for n in state['nodes'] if n['id'] == tgt), None)
                ok_valid, vmsg = self._cons_connection_is_valid(rxn, src_node, tgt_node)
                if not ok_valid:
                    proceed = messagebox.askyesno(
                        'VIREON',
                        vmsg + ('\n\nВсё равно соединить?' if self.lang == 'ru'
                                 else '\n\nConnect anyway?'))
                    if not proceed:
                        self._cons_status_lbl.config(
                            text=('Отменено' if self.lang == 'ru' else 'Cancelled'),
                            fg='#9a6700')
                        return
                # TinkerCell "which did you mean?": if the user picked a generic
                # connection but a more specific one fits these part types, offer it.
                if rxn in ('activation', 'repression', 'rxn_1_to_1', 'binding',
                            'direct_gene_regulation'):
                    suggestion = self._cons_suggest_connection(src_node, tgt_node)
                    if suggestion and suggestion != rxn:
                        sug_name = (CIRCUIT_REACTIONS.get(suggestion, {})
                                    .get('name_ru' if self.lang == 'ru' else 'name_en',
                                         suggestion))
                        cur_name = (CIRCUIT_REACTIONS.get(rxn, {})
                                    .get('name_ru' if self.lang == 'ru' else 'name_en',
                                         rxn))
                        use_specific = messagebox.askyesno(
                            'VIREON',
                            ('Судя по типам частей, точнее подойдёт связь '
                             '«{}» вместо «{}».\n\nИспользовать «{}»?'
                             .format(sug_name, cur_name, sug_name))
                            if self.lang == 'ru' else
                            ('Based on the part types, "{}" fits better than "{}".'
                             '\n\nUse "{}"?'.format(sug_name, cur_name, sug_name)))
                        if use_specific:
                            rxn = suggestion
                edge_type = 'repression' if rxn == 'repression' else 'activation'
                self._save_history('constructor')
                state['edges'].append({
                    'from': src, 'to': tgt,
                    'type': edge_type, 'reaction': rxn,
                    'strength': 3.0, 'hill_n': 2,
                })
                self._cons_refresh()
                self._cons_status_lbl.config(
                    text=('Связь добавлена · кликни источник' if self.lang == 'ru'
                          else 'Connection added · click source'))
            return

        # Normal mode: click on node or empty area
        if clicked_node is not None:
            # Click on a node
            if clicked_node in self._cons_selected_nodes and len(self._cons_selected_nodes) > 1:
                # Click on already-selected node when multiple selected start multi-drag
                self._cons_multi_drag = True
                self._cons_multi_drag_offsets = {}
                for n in state['nodes']:
                    if n['id'] in self._cons_selected_nodes:
                        self._cons_multi_drag_offsets[n['id']] = (event.x - n['x'], event.y - n['y'])
                self._cons_drag_node = clicked_node
                return
            # Click on different node select just this one
            self._cons_selected_nodes = {clicked_node}
            self._cons_drag_node = clicked_node
            for n in state['nodes']:
                if n['id'] == clicked_node:
                    self._cons_drag_offset = (event.x - n['x'], event.y - n['y'])
                    break
            self._cons_refresh()
        else:
            # Click on empty area start rubber band selection
            self._cons_rubber_start = (event.x, event.y)
            self._cons_selected_nodes = set()
            self._cons_drag_node = None
            self._cons_refresh()

    def _cons_canvas_ctrl_click(self, event):
        """Ctrl+click — toggle node in selection set."""
        _wx, _wy = self._s2w(event.x, event.y)
        event = _EvtProxy(event, _wx, _wy)
        clicked_node = self._cons_find_node_at(event.x, event.y)
        if clicked_node is None:
            return
        if clicked_node in self._cons_selected_nodes:
            self._cons_selected_nodes.remove(clicked_node)
        else:
            self._cons_selected_nodes.add(clicked_node)
        self._cons_refresh()
        self._cons_status_lbl.config(
            text=self._t('selected_count') + ' ' + str(len(self._cons_selected_nodes)))

    def _cons_canvas_drag(self, event):
        """Drag — move single node, multi-nodes, or draw rubber band."""
        state = self.current_state['constructor']
        _wx, _wy = self._s2w(event.x, event.y)
        event = _EvtProxy(event, _wx, _wy)
        # Multi-drag
        if self._cons_multi_drag:
            for n in state['nodes']:
                if n['id'] in self._cons_multi_drag_offsets:
                    ox, oy = self._cons_multi_drag_offsets[n['id']]
                    n['x'] = event.x - ox
                    n['y'] = event.y - oy
            self._cons_draw_diagram()
            return
        # Single drag
        if self._cons_drag_node is not None:
            ox, oy = self._cons_drag_offset
            for n in state['nodes']:
                if n['id'] == self._cons_drag_node:
                    n['x'] = event.x - ox
                    n['y'] = event.y - oy
                    break
            self._cons_draw_diagram()
            return
        # Rubber band
        if self._cons_rubber_start is not None:
            sx, sy = self._cons_rubber_start
            x0, y0 = min(sx, event.x), min(sy, event.y)
            x1, y1 = max(sx, event.x), max(sy, event.y)
            # Remove previous rect
            if self._cons_rubber_rect_id is not None:
                try:
                    self.cons_canvas.delete(self._cons_rubber_rect_id)
                except Exception as _exc:
                    biosim_log('warn', '_cons_canvas_drag: {}'.format(_exc))
            # world→screen for on-screen rectangle
            sx0, sy0 = self._w2s(x0, y0)
            sx1, sy1 = self._w2s(x1, y1)
            self._cons_rubber_rect_id = self.cons_canvas.create_rectangle(
                sx0, sy0, sx1, sy1, outline='#0969da', width=1, dash=(4, 2))

    def _cons_canvas_release(self, event):
        """Mouse released — finalize drag or rubber band."""
        state = self.current_state['constructor']
        _wx, _wy = self._s2w(event.x, event.y)
        event = _EvtProxy(event, _wx, _wy)

        # Multi-drag finished
        if self._cons_multi_drag:
            self._cons_multi_drag = False
            self._cons_multi_drag_offsets = {}
            self._cons_drag_node = None
            # Try snap each
            for n in state['nodes']:
                if n['id'] in self._cons_selected_nodes:
                    self._cons_remove_from_chains(n['id'])
                    self._cons_try_snap(n)
            self._save_history('constructor')
            self._cons_refresh()
            return

        # Single drag
        if self._cons_drag_node is not None:
            for n in state['nodes']:
                if n['id'] == self._cons_drag_node:
                    self._cons_remove_from_chains(n['id'])
                    self._cons_try_snap(n)
                    # Check if dropped inside a cell
                    self._cons_check_compartment(n)
                    break
            self._save_history('constructor')
            self._cons_drag_node = None
            self._cons_refresh()
            return

        # Rubber band
        if self._cons_rubber_start is not None:
            sx, sy = self._cons_rubber_start
            x0, y0 = min(sx, event.x), min(sy, event.y)
            x1, y1 = max(sx, event.x), max(sy, event.y)
            # Find nodes inside rectangle
            inside = set()
            for n in state['nodes']:
                if x0 <= n['x'] <= x1 and y0 <= n['y'] <= y1:
                    inside.add(n['id'])
            self._cons_selected_nodes = inside
            self._cons_rubber_start = None
            if self._cons_rubber_rect_id is not None:
                try:
                    self.cons_canvas.delete(self._cons_rubber_rect_id)
                except Exception as _exc:
                    biosim_log('warn', '_cons_canvas_release: {}'.format(_exc))
                self._cons_rubber_rect_id = None
            self._cons_refresh()
            if inside:
                self._cons_status_lbl.config(
                    text=self._t('selected_count') + ' ' + str(len(inside)))
            else:
                self._cons_status_lbl.config(text=self._t('right_click_hint'))

    def _cons_canvas_right_click(self, event):
        """Right click — show context menu (not delete)."""
        _wx, _wy = self._s2w(event.x, event.y)
        event = _EvtProxy(event, _wx, _wy)
        # First check if clicked on edge
        edge_idx = self._cons_find_edge_at(event.x, event.y, max_dist=8)
        clicked_node = self._cons_find_node_at(event.x, event.y)
        # If clicked on edge (and not on a node) — show edge menu
        if edge_idx is not None and clicked_node is None:
            menu = tk.Menu(self.cons_canvas, tearoff=0, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                            activebackground='#0969da', activeforeground='white',
                            font=('Arial', 10))
            menu.add_command(label='' + self._t('edge_edit_title'),
                              command=lambda: self._cons_open_edge_editor(edge_idx))
            menu.add_separator()
            def delete_this_edge():
                state = self.current_state['constructor']
                self._save_history('constructor')
                if edge_idx < len(state['edges']):
                    del state['edges'][edge_idx]
                self._cons_refresh()
            menu.add_command(label='' + self._t('edge_delete'),
                              command=delete_this_edge)
            try:
                menu.tk_popup(event.x_root, event.y_root)
            finally:
                menu.grab_release()
            return

        # If clicked on a node not yet selected, select it first
        if clicked_node is not None and clicked_node not in self._cons_selected_nodes:
            self._cons_selected_nodes = {clicked_node}
            self._cons_refresh()
        # Build and show menu
        menu = tk.Menu(self.cons_canvas, tearoff=0, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                        activebackground='#0969da', activeforeground='white',
                        font=('Arial', 10))
        n_sel = len(self._cons_selected_nodes)
        if n_sel == 1:
            # Single-node menu
            menu.add_command(label=self._t('ctx_properties'),
                              command=self._cons_open_properties)
            menu.add_command(label='' + self._t('quick_rename'),
                              command=lambda: self._cons_quick_rename_node(
                                  next(iter(self._cons_selected_nodes))))
            # Size submenu
            size_menu = tk.Menu(menu, tearoff=0, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                                  activebackground='#0969da', activeforeground='white')
            size_menu.add_command(label=self._t('ctx_size_small'),
                                    command=lambda: self._cons_set_size(0.7))
            size_menu.add_command(label=self._t('ctx_size_medium'),
                                    command=lambda: self._cons_set_size(1.0))
            size_menu.add_command(label=self._t('ctx_size_large'),
                                    command=lambda: self._cons_set_size(1.5))
            menu.add_cascade(label=self._t('ctx_resize'), menu=size_menu)
            menu.add_command(label=self._t('ctx_duplicate'),
                              command=self._cons_duplicate_selected)
            menu.add_command(
                label=('Копировать  Ctrl+C' if self.lang == 'ru' else 'Copy  Ctrl+C'),
                command=self._cons_copy_selected)
            menu.add_command(
                label=('Вырезать  Ctrl+X' if self.lang == 'ru' else 'Cut  Ctrl+X'),
                command=self._cons_cut_selected)
            # ── Type-specific actions ("what this element can do") ──
            self._cons_add_type_actions(menu,
                                        next(iter(self._cons_selected_nodes)))
            menu.add_separator()
            menu.add_command(label=self._t('ctx_delete'),
                              command=self._cons_delete_selected)
        elif n_sel > 1:
            # Multi-node menu
            menu.add_command(label='{} {}'.format(
                self._t('selected_count'), n_sel))
            menu.add_separator()
            # Size submenu for all
            size_menu = tk.Menu(menu, tearoff=0, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                                  activebackground='#0969da', activeforeground='white')
            size_menu.add_command(label=self._t('ctx_size_small'),
                                    command=lambda: self._cons_set_size_all(0.7))
            size_menu.add_command(label=self._t('ctx_size_medium'),
                                    command=lambda: self._cons_set_size_all(1.0))
            size_menu.add_command(label=self._t('ctx_size_large'),
                                    command=lambda: self._cons_set_size_all(1.5))
            menu.add_cascade(label=self._t('ctx_resize'), menu=size_menu)
            menu.add_command(label=self._t('ctx_duplicate'),
                              command=self._cons_duplicate_selected)
            menu.add_command(label=self._t('ctx_group_into_cell'),
                              command=self._cons_group_into_cell)
            menu.add_command(
                label=('📦 Свернуть в модуль' if self.lang == 'ru'
                       else '📦 Group into module'),
                command=self._cons_group_into_module)
            menu.add_command(
                label=('Копировать  Ctrl+C' if self.lang == 'ru' else 'Copy  Ctrl+C'),
                command=self._cons_copy_selected)
            menu.add_command(
                label=('Вырезать  Ctrl+X' if self.lang == 'ru' else 'Cut  Ctrl+X'),
                command=self._cons_cut_selected)
            menu.add_separator()
            menu.add_command(label=self._t('ctx_delete_all'),
                              command=self._cons_delete_selected)
        else:
            # Empty area menu
            menu.add_command(label=self._t('ctx_select_all'),
                              command=self._cons_select_all)
            if SynBioWindow._clipboard and SynBioWindow._clipboard.get('nodes'):
                menu.add_command(
                    label=('Вставить сюда  Ctrl+V' if self.lang == 'ru'
                           else 'Paste here  Ctrl+V'),
                    command=lambda ex=event.x, ey=event.y:
                        self._cons_paste_at(ex, ey))
        # Always show this option
        if n_sel > 0:
            menu.add_command(label=self._t('ctx_deselect'),
                              command=self._cons_deselect_all)
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    # ══════════════════════════════════════════════════════════════════
    # ZOOM & PAN — world↔screen coordinate transform
    # ══════════════════════════════════════════════════════════════════
    def _cons_add_type_actions(self, menu, node_id):
        """Add context-menu actions specific to the node's biological type —
        the TinkerCell idea that each family exposes its own operations."""
        state = self.current_state['constructor']
        node = next((n for n in state['nodes'] if n['id'] == node_id), None)
        if node is None:
            return
        ntype = self._cons_node_type(node)
        is_ru = (self.lang == 'ru')
        added = False

        def sep_once():
            nonlocal added
            if not added:
                menu.add_separator()
                added = True

        if ntype == 'promoter':
            sep_once()
            menu.add_command(
                label=('▶ Прикрепить ген (транскрипция)' if is_ru
                       else '▶ Attach gene (transcription)'),
                command=lambda: self._cons_start_typed_connection(node_id, 'transcription'))
            menu.add_command(
                label=('⚡ PoPS к следующей ДНК-части' if is_ru
                       else '⚡ PoPS to next DNA part'),
                command=lambda: self._cons_start_typed_connection(node_id, 'pops'))
        elif ntype == 'rbs':
            sep_once()
            menu.add_command(
                label=('▶ Связать с CDS (трансляция)' if is_ru
                       else '▶ Link to CDS (translation)'),
                command=lambda: self._cons_start_typed_connection(node_id, 'translation'))
        elif ntype in ('cds', 'dna_other'):
            sep_once()
            menu.add_command(
                label=('🧬 Транскрибировать → мРНК' if is_ru
                       else '🧬 Transcribe → mRNA'),
                command=lambda: self._cons_start_typed_connection(node_id, 'transcription'))
        elif ntype == 'tf':
            sep_once()
            menu.add_command(
                label=('🟢 Активировать промотор' if is_ru
                       else '🟢 Activate a promoter'),
                command=lambda: self._cons_start_typed_connection(node_id, 'activation'))
            menu.add_command(
                label=('🔴 Репрессировать промотор' if is_ru
                       else '🔴 Repress a promoter'),
                command=lambda: self._cons_start_typed_connection(node_id, 'repression'))
        elif ntype == 'enzyme':
            sep_once()
            menu.add_command(
                label=('⚗ Создать реакцию с субстратом' if is_ru
                       else '⚗ Create reaction with substrate'),
                command=lambda: self._cons_start_typed_connection(node_id, 'catalysis'))
            menu.add_command(
                label=('P Фосфорилировать белок' if is_ru
                       else 'P Phosphorylate a protein'),
                command=lambda: self._cons_start_typed_connection(node_id, 'phosphorylation'))
        elif ntype in ('protein',):
            sep_once()
            menu.add_command(
                label=('🔗 Связать в комплекс' if is_ru
                       else '🔗 Bind into complex'),
                command=lambda: self._cons_start_typed_connection(node_id, 'complex_formation'))
            menu.add_command(
                label=('🗑 Деградировать' if is_ru else '🗑 Degrade'),
                command=lambda: self._cons_start_typed_connection(node_id, 'degradation'))
        elif ntype in ('molecule', 'phosphate', 'rna', 'mrna'):
            sep_once()
            menu.add_command(
                label=('🔄 Превращение в другую молекулу' if is_ru
                       else '🔄 Convert to another molecule'),
                command=lambda: self._cons_start_typed_connection(node_id, 'conversion'))
            menu.add_command(
                label=('🔗 Связывание' if is_ru else '🔗 Binding'),
                command=lambda: self._cons_start_typed_connection(node_id, 'binding'))

        # 3D view for molecule-like nodes
        if ntype in ('molecule', 'phosphate', 'mrna', 'rna', 'protein', 'enzyme'):
            sep_once()
            menu.add_command(
                label=('🧊 3D-вид молекулы' if is_ru else '🧊 3D molecule view'),
                command=lambda: self._open_3d_molecule_for_node(node))

        # Decorators submenu (visual badges that travel with the node)
        sep_once()
        dec_menu = tk.Menu(menu, tearoff=0, bg=biosim_theme('panel2'),
                            fg=biosim_theme('text'), activebackground='#0969da',
                            activeforeground='white')
        badges = [
            ('Ⓟ', '#8250df', 'Фосфорилирован' if is_ru else 'Phosphorylated'),
            ('★', '#9a6700', 'Важный' if is_ru else 'Key'),
            ('⚠', '#cf222e', 'Внимание' if is_ru else 'Warning'),
            ('✓', '#1a7f37', 'Проверен' if is_ru else 'Validated'),
            ('∅', '#57606a', 'Нокаут' if is_ru else 'Knockout'),
            ('◆', '#0969da', 'Метка' if is_ru else 'Tag'),
        ]
        for sym, col, lbl in badges:
            dec_menu.add_command(
                label='{}  {}'.format(sym, lbl),
                command=lambda s=sym, c=col: self._cons_add_decorator(node_id, s, c))
        menu.add_cascade(
            label=('🏷 Добавить значок' if is_ru else '🏷 Add decorator'),
            menu=dec_menu)
        if node.get('decorators'):
            menu.add_command(
                label=('✕ Убрать значки' if is_ru else '✕ Clear decorators'),
                command=lambda: self._cons_clear_decorators(node_id))

    def _cons_add_decorator(self, node_id, symbol, color):
        """Attach a visual badge to a node. Multiple badges fan out around it."""
        state = self.current_state['constructor']
        node = next((n for n in state['nodes'] if n['id'] == node_id), None)
        if node is None:
            return
        self._save_history('constructor')
        decs = node.setdefault('decorators', [])
        # Fan new badges around the top-right of the node
        import math as _m
        i = len(decs)
        angle = -_m.pi / 4 + i * (_m.pi / 6)
        node['decorators'].append({
            'symbol': symbol, 'color': color,
            'dx': 20 * _m.cos(angle), 'dy': 20 * _m.sin(angle),
        })
        self._cons_refresh()

    def _cons_clear_decorators(self, node_id):
        state = self.current_state['constructor']
        node = next((n for n in state['nodes'] if n['id'] == node_id), None)
        if node is None:
            return
        self._save_history('constructor')
        node.pop('decorators', None)
        self._cons_refresh()

    def _cons_start_typed_connection(self, source_id, reaction_key):
        """Begin drawing a connection of a specific reaction type from the given
        source node. The user then clicks the target node. Reuses the existing
        connection machinery by pre-selecting the reaction and source."""
        self._cons_selected_reaction = reaction_key
        self._cons_connect_source = source_id
        rname = (CIRCUIT_REACTIONS.get(reaction_key, {})
                 .get('name_ru' if self.lang == 'ru' else 'name_en', reaction_key))
        try:
            self._cons_status_lbl.config(
                text=(('{}: кликни целевой элемент'.format(rname)) if self.lang == 'ru'
                      else ('{}: click the target element'.format(rname))),
                fg='#0969da')
        except Exception:
            pass

    # ══════════════════════════════════════════════════════════════════
    # ZOOM & PAN — world↔screen coordinate transform
    # (helpers below)
    # ══════════════════════════════════════════════════════════════════
    def _s2w(self, sx, sy):
        """Screen (event) coords → world coords."""
        sc = getattr(self, '_cons_scale', 1.0) or 1.0
        return ((sx - self._cons_pan_x) / sc, (sy - self._cons_pan_y) / sc)

    def _w2s(self, wx, wy):
        """World coords → screen coords."""
        sc = getattr(self, '_cons_scale', 1.0) or 1.0
        return (wx * sc + self._cons_pan_x, wy * sc + self._cons_pan_y)

    def _cons_apply_view_transform(self):
        """After the diagram is drawn in world space, scale+move everything on
        the canvas to reflect the current zoom/pan. Called at end of draw."""
        try:
            c = self.cons_canvas
            sc = getattr(self, '_cons_scale', 1.0) or 1.0
            if abs(sc - 1.0) > 1e-6:
                c.scale('all', 0, 0, sc, sc)
            px = getattr(self, '_cons_pan_x', 0.0)
            py = getattr(self, '_cons_pan_y', 0.0)
            if abs(px) > 1e-6 or abs(py) > 1e-6:
                c.move('all', px, py)
        except Exception as _exc:
            biosim_log('warn', '_cons_apply_view_transform: {}'.format(_exc))

    def _cons_on_mousewheel(self, event):
        """Zoom centered on the cursor."""
        # Determine zoom direction (cross-platform)
        if getattr(event, 'num', None) == 4:
            factor = 1.1
        elif getattr(event, 'num', None) == 5:
            factor = 1 / 1.1
        else:
            factor = 1.1 if event.delta > 0 else 1 / 1.1
        self._cons_zoom_by(factor, cx=event.x, cy=event.y)
        return 'break'

    def _cons_zoom_by(self, factor, cx=None, cy=None):
        """Multiply zoom by factor, keeping the point (cx,cy) fixed on screen.
        If cx/cy are None, zoom around the canvas center."""
        c = self.cons_canvas
        if cx is None:
            cx = (c.winfo_width() or 600) / 2
        if cy is None:
            cy = (c.winfo_height() or 400) / 2
        old = getattr(self, '_cons_scale', 1.0) or 1.0
        new = max(0.2, min(5.0, old * factor))
        if abs(new - old) < 1e-6:
            return
        # Keep world point under cursor fixed: world_pt stays same on screen
        wx, wy = self._s2w(cx, cy)
        self._cons_scale = new
        # After changing scale, solve pan so that _w2s(wx,wy) == (cx,cy)
        self._cons_pan_x = cx - wx * new
        self._cons_pan_y = cy - wy * new
        self._cons_refresh()
        self._update_zoom_label()

    def _cons_zoom_reset(self):
        """Reset zoom to 100% and pan to origin."""
        self._cons_scale = 1.0
        self._cons_pan_x = 0.0
        self._cons_pan_y = 0.0
        self._cons_refresh()
        self._update_zoom_label()

    def _cons_zoom_in(self):
        """Zoom-in button (+): zoom around the canvas centre."""
        self._cons_zoom_by(1.2)

    def _cons_zoom_out(self):
        """Zoom-out button (−): zoom around the canvas centre."""
        self._cons_zoom_by(1 / 1.2)

    def _cons_scroll_x(self, *args):
        """Horizontal scrollbar → pan the world left/right.
        args come from the Scrollbar: ('moveto', frac) or ('scroll', n, what)."""
        try:
            if not args:
                return
            if args[0] == 'moveto':
                frac = float(args[1])
                # map 0..1 over the world extent to pan
                self._cons_pan_to_fraction(xfrac=frac)
            elif args[0] == 'scroll':
                step = int(args[1]) * 40
                self._cons_pan_x -= step
                self._cons_refresh()
        except Exception:
            pass

    def _cons_scroll_y(self, *args):
        """Vertical scrollbar → pan the world up/down."""
        try:
            if not args:
                return
            if args[0] == 'moveto':
                frac = float(args[1])
                self._cons_pan_to_fraction(yfrac=frac)
            elif args[0] == 'scroll':
                step = int(args[1]) * 40
                self._cons_pan_y -= step
                self._cons_refresh()
        except Exception:
            pass

    def _cons_world_bounds(self):
        """Bounding box of all nodes in world coords (with margin)."""
        state = self.current_state.get('constructor')
        if not state or not state.get('nodes'):
            return (0, 0, 1000, 700)
        xs = [n['x'] for n in state['nodes']]
        ys = [n['y'] for n in state['nodes']]
        m = 120
        return (min(xs) - m, min(ys) - m, max(xs) + m, max(ys) + m)

    def _cons_pan_to_fraction(self, xfrac=None, yfrac=None):
        """Set pan so that the given fraction of the world extent is at the
        top-left of the viewport (drives the scrollbars)."""
        x0, y0, x1, y1 = self._cons_world_bounds()
        sc = getattr(self, '_cons_scale', 1.0) or 1.0
        c = self.cons_canvas
        vw = c.winfo_width() or 600
        vh = c.winfo_height() or 400
        world_w = (x1 - x0) * sc
        world_h = (y1 - y0) * sc
        if xfrac is not None:
            # pan_x positions world origin; move so xfrac of extra width is shown
            extra = max(0, world_w - vw)
            self._cons_pan_x = -x0 * sc - xfrac * extra
        if yfrac is not None:
            extra = max(0, world_h - vh)
            self._cons_pan_y = -y0 * sc - yfrac * extra
        self._cons_refresh()

    def _cons_update_scrollbars(self):
        """Sync the scrollbar thumbs to the current pan/zoom and world size."""
        vsb = getattr(self, '_cons_vsb', None)
        hsb = getattr(self, '_cons_hsb', None)
        if not vsb or not hsb:
            return
        try:
            x0, y0, x1, y1 = self._cons_world_bounds()
            sc = getattr(self, '_cons_scale', 1.0) or 1.0
            c = self.cons_canvas
            vw = c.winfo_width() or 600
            vh = c.winfo_height() or 400
            world_w = max(1, (x1 - x0) * sc)
            world_h = max(1, (y1 - y0) * sc)
            # visible fraction
            fxw = min(1.0, vw / world_w)
            fyh = min(1.0, vh / world_h)
            # current left/top fraction
            left = (-self._cons_pan_x - x0 * sc)
            top = (-self._cons_pan_y - y0 * sc)
            extra_w = max(1, world_w - vw)
            extra_h = max(1, world_h - vh)
            lo_x = min(max(0.0, left / extra_w), 1.0) if world_w > vw else 0.0
            lo_y = min(max(0.0, top / extra_h), 1.0) if world_h > vh else 0.0
            hsb.set(lo_x, min(1.0, lo_x + fxw))
            vsb.set(lo_y, min(1.0, lo_y + fyh))
        except Exception:
            pass

    def _update_zoom_label(self):
        """Update the zoom % indicator if present."""
        try:
            pct = int(round((getattr(self, '_cons_scale', 1.0) or 1.0) * 100))
            if hasattr(self, '_cons_zoom_lbl') and self._cons_zoom_lbl:
                self._cons_zoom_lbl.config(text='{}%'.format(pct))
        except Exception:
            pass

    def _cons_pan_start_evt(self, event):
        self._cons_panning = True
        self._cons_pan_start = (event.x, event.y,
                                 self._cons_pan_x, self._cons_pan_y)
        try:
            self.cons_canvas.config(cursor='fleur')
        except Exception:
            pass
        return 'break'

    def _cons_pan_move_evt(self, event):
        if not getattr(self, '_cons_panning', False) or not self._cons_pan_start:
            return
        sx0, sy0, px0, py0 = self._cons_pan_start
        self._cons_pan_x = px0 + (event.x - sx0)
        self._cons_pan_y = py0 + (event.y - sy0)
        self._cons_refresh()
        return 'break'

    def _cons_pan_end_evt(self, event):
        self._cons_panning = False
        self._cons_pan_start = None
        try:
            self.cons_canvas.config(cursor='arrow')
        except Exception:
            pass
        return 'break'

    def _cons_find_node_at(self, x, y):
        state = self.current_state['constructor']
        if state is None:
            return None
        # Reverse order so top (last-drawn) takes priority
        for n in reversed(state['nodes']):
            size_factor = n.get('size', 1.0)
            r = int(30 * size_factor)
            dx = x - n['x']; dy = y - n['y']
            if dx * dx + dy * dy <= r * r:
                return n['id']
        return None

    def _cons_find_edge_at(self, x, y, max_dist=10):
        """Find an edge close to (x,y). Returns index in state['edges'] or None."""
        state = self.current_state['constructor']
        if state is None:
            return None
        pos = {n['id']: (n['x'], n['y']) for n in state['nodes']}
        best_idx = None
        best_d = max_dist
        for i, e in enumerate(state['edges']):
            # Multi-source/target edge?
            sources = e.get('sources')
            targets = e.get('targets')
            if sources and targets and (len(sources) > 1 or len(targets) > 1):
                # Compute hub position
                src_pos = [pos[s] for s in sources if s in pos]
                tgt_pos = [pos[t] for t in targets if t in pos]
                if not src_pos or not tgt_pos:
                    continue
                all_x = [p[0] for p in src_pos] + [p[0] for p in tgt_pos]
                all_y = [p[1] for p in src_pos] + [p[1] for p in tgt_pos]
                hub_x = sum(all_x) / len(all_x)
                hub_y = sum(all_y) / len(all_y)
                # Check distance to each branch (sourcehub, hubtarget)
                for sx_, sy_ in src_pos:
                    d = self._dist_to_segment(x, y, sx_, sy_, hub_x, hub_y)
                    if d < best_d:
                        best_d = d; best_idx = i
                for tx_, ty_ in tgt_pos:
                    d = self._dist_to_segment(x, y, hub_x, hub_y, tx_, ty_)
                    if d < best_d:
                        best_d = d; best_idx = i
                continue
            # Standard 1-to-1
            if e['from'] not in pos or e['to'] not in pos:
                continue
            x1, y1 = pos[e['from']]
            x2, y2 = pos[e['to']]
            d = self._dist_to_segment(x, y, x1, y1, x2, y2)
            if d < best_d:
                best_d = d
                best_idx = i
        return best_idx

    def _dist_to_segment(self, px, py, x1, y1, x2, y2):
        """Distance from point to line segment."""
        dx = x2 - x1; dy = y2 - y1
        seg_len_sq = dx * dx + dy * dy
        if seg_len_sq < 1:
            return float('inf')
        t = max(0, min(1, ((px - x1) * dx + (py - y1) * dy) / seg_len_sq))
        proj_x = x1 + t * dx; proj_y = y1 + t * dy
        return math.sqrt((px - proj_x) ** 2 + (py - proj_y) ** 2)

    def _cons_canvas_double_click(self, event):
        """Double-click: enter a module sub-schema, quick-rename a node, or edit
        an edge."""
        _wx, _wy = self._s2w(event.x, event.y)
        event = _EvtProxy(event, _wx, _wy)
        # Try node first
        clicked_node = self._cons_find_node_at(event.x, event.y)
        if clicked_node is not None:
            state = self.current_state['constructor']
            node = next((n for n in state['nodes'] if n['id'] == clicked_node), None)
            # If it's a module container → step INTO its sub-schema
            if node is not None and self._cons_is_module(node):
                self._cons_enter_module(node)
                return
            self._cons_quick_rename_node(clicked_node)
            return
        # Try edge
        edge_idx = self._cons_find_edge_at(event.x, event.y)
        if edge_idx is not None:
            self._cons_open_edge_editor(edge_idx)

    def _cons_is_module(self, node):
        """A node is a module container if it carries a sub-schema or a module
        icon/part_key."""
        if node.get('submodel') is not None:
            return True
        icon = node.get('icon', '') or ''
        pk = node.get('part_key', '') or ''
        return icon.startswith('module') or pk in CIRCUIT_MODULES or pk == 'new_module'

    def _cons_enter_module(self, node):
        """Step into a module: show its sub-schema on the canvas. The parent
        schema is pushed onto a navigation stack so we can step back out."""
        # Ensure the module has a sub-schema to edit
        sub = node.get('submodel')
        if sub is None:
            sub = {'name': node.get('id', 'module'),
                   'description': 'Sub-schema of ' + node.get('id', 'module'),
                   'nodes': [], 'edges': [], 'init': {}, 'chains': []}
            node['submodel'] = sub
        # Push current state + which node we entered
        if not hasattr(self, '_module_stack'):
            self._module_stack = []
        self._module_stack.append({
            'state': self.current_state['constructor'],
            'node_id': node.get('id'),
        })
        # Swap the active constructor state to the sub-schema
        self.current_state['constructor'] = sub
        self._cons_zoom_reset()
        self._cons_selected_nodes = set()
        self._cons_refresh()
        self._update_breadcrumb()
        try:
            self._cons_status_lbl.config(
                text=('Вошли в модуль «{}» · дважды кликни пусто или ← чтобы выйти'
                      .format(node.get('id')) if self.lang == 'ru'
                      else 'Entered module "{}" · use ← to go back'
                      .format(node.get('id'))), fg='#8250df')
        except Exception:
            pass

    def _cons_exit_module(self):
        """Step back out to the parent schema."""
        if not getattr(self, '_module_stack', None):
            return
        frame = self._module_stack.pop()
        self.current_state['constructor'] = frame['state']
        self._cons_zoom_reset()
        self._cons_selected_nodes = set()
        self._cons_refresh()
        self._update_breadcrumb()
        try:
            self._cons_status_lbl.config(
                text=('Вышли из модуля' if self.lang == 'ru'
                      else 'Exited module'), fg='#1a7f37')
        except Exception:
            pass

    def _update_breadcrumb(self):
        """Update the module navigation breadcrumb label if present."""
        try:
            if not hasattr(self, '_cons_breadcrumb_lbl') or self._cons_breadcrumb_lbl is None:
                return
            stack = getattr(self, '_module_stack', [])
            if not stack:
                self._cons_breadcrumb_lbl.config(text='')
            else:
                path = ' / '.join(['⌂'] + [f['node_id'] for f in stack])
                back = ('  ← Выйти' if self.lang == 'ru' else '  ← Back')
                self._cons_breadcrumb_lbl.config(text=path + back)
        except Exception:
            pass

    def _cons_quick_rename_node(self, node_id):
        """Show small inline dialog to rename a node (without losing tab focus)."""
        state = self.current_state['constructor']
        node = next((n for n in state['nodes'] if n['id'] == node_id), None)
        if node is None:
            return

        # Custom Toplevel dialog (does NOT use simpledialog which switches tabs)
        dlg = tk.Toplevel(self)
        dlg.title(self._t('quick_rename'))
        dlg.geometry('360x150')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        dlg.resizable(False, False)

        # Center on parent
        try:
            px = self.winfo_rootx() + self.winfo_width() // 2 - 180
            py = self.winfo_rooty() + self.winfo_height() // 2 - 75
            dlg.geometry('+{}+{}'.format(max(0, px), max(0, py)))
        except Exception as _exc:
            biosim_log('warn', '_cons_quick_rename_node: {}'.format(_exc))

        tk.Label(dlg, text='' + self._t('quick_rename'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 13, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=self._t('enter_new_name'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(pady=2)

        name_var = tk.StringVar(value=node_id)
        ent = tk.Entry(dlg, textvariable=name_var,
                        bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                        relief='flat', font=('Arial', 12, 'bold'),
                        highlightthickness=2, highlightbackground=biosim_theme('border'),
                        highlightcolor='#8250df', justify='center')
        ent.pack(fill='x', padx=20, pady=4, ipady=4)
        ent.select_range(0, 'end')
        ent.focus_set()

        def do_rename():
            new_name = name_var.get().strip()
            if not new_name or new_name == node_id:
                dlg.destroy()
                return
            # Check uniqueness
            if any(n['id'] == new_name for n in state['nodes']):
                messagebox.showinfo('VIREON',
                    ('Имя занято' if self.lang == 'ru' else 'Name already taken'),
                    parent=dlg)
                return
            self._save_history('constructor')
            old_id = node_id
            node['id'] = new_name
            # Update init dict
            if old_id in state['init']:
                state['init'][new_name] = state['init'].pop(old_id)
            # Update edges (single and multi-source)
            for e in state['edges']:
                if e.get('from') == old_id: e['from'] = new_name
                if e.get('to') == old_id: e['to'] = new_name
                # Multi-source/target lists
                if 'sources' in e:
                    e['sources'] = [new_name if s == old_id else s for s in e['sources']]
                if 'targets' in e:
                    e['targets'] = [new_name if t == old_id else t for t in e['targets']]
            # Update chains
            for ch in state.get('chains', []):
                for i, nid in enumerate(ch):
                    if nid == old_id: ch[i] = new_name
            # Update compartments
            for nx in state['nodes']:
                if nx.get('icon') == 'cell':
                    nx['contains'] = [new_name if c == old_id else c
                                       for c in nx.get('contains', [])]
            # Update selection
            if old_id in self._cons_selected_nodes:
                self._cons_selected_nodes.remove(old_id)
                self._cons_selected_nodes.add(new_name)
            self._cons_refresh()
            dlg.destroy()

        def cancel():
            dlg.destroy()

        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=20, pady=10)
        tk.Button(btn_row, text=self._t('prop_save'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=do_rename
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('cancel'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=cancel
                   ).pack(side='right', padx=2)

        # Bind Enter to save, Escape to cancel
        dlg.bind('<Return>', lambda e: do_rename())
        dlg.bind('<Escape>', lambda e: cancel())

    def _cons_open_edge_editor(self, edge_idx):
        """Open dialog to edit/delete an edge."""
        state = self.current_state['constructor']
        if edge_idx >= len(state['edges']):
            return
        edge = state['edges'][edge_idx]
        rxn = edge.get('reaction', edge.get('type', 'activation'))
        rxn_data = CIRCUIT_REACTIONS.get(rxn, {})

        dlg = tk.Toplevel(self)
        dlg.title(self._t('edge_edit_title'))
        dlg.geometry('480x720')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        rxn_name = rxn_data.get('name_ru' if self.lang == 'ru' else 'name_en', rxn)
        tk.Label(dlg, text='' + self._t('edge_edit_title'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=rxn_name,
                  bg=biosim_theme('bg'), fg=rxn_data.get('color', '#1c2128'),
                  font=('Arial', 11, 'bold')).pack(pady=(0, 8))

        # Source / target labels
        info_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        info_frame.pack(fill='x', padx=14, pady=4)
        # Multi-source/target?
        sources = edge.get('sources')
        targets = edge.get('targets')
        if sources and targets and (len(sources) > 1 or len(targets) > 1):
            src_str = ' + '.join(sources)
            tgt_str = ' + '.join(targets)
            tk.Label(info_frame, text=self._t('edge_from') + ' ' + src_str,
                      bg=biosim_theme('bg'), fg='#1a7f37',
                      font=('Arial', 11, 'bold')).pack(side='left', padx=4)
            tk.Label(info_frame, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                      font=('Arial', 14)).pack(side='left', padx=8)
            tk.Label(info_frame, text=self._t('edge_to') + ' ' + tgt_str,
                      bg=biosim_theme('bg'), fg='#cf222e',
                      font=('Arial', 11, 'bold')).pack(side='left', padx=4)
        else:
            tk.Label(info_frame, text=self._t('edge_from') + ' ' + edge['from'],
                      bg=biosim_theme('bg'), fg='#1a7f37',
                      font=('Arial', 11, 'bold')).pack(side='left', padx=4)
            tk.Label(info_frame, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                      font=('Arial', 14)).pack(side='left', padx=8)
            tk.Label(info_frame, text=self._t('edge_to') + ' ' + edge['to'],
                      bg=biosim_theme('bg'), fg='#cf222e',
                      font=('Arial', 11, 'bold')).pack(side='left', padx=4)

        # Stoichiometry editor (visible only for rxn_X_to_Y)
        stoich = rxn_data.get('stoichiometry')
        stoich_vars = {}
        if stoich is not None:
            n_src, n_tgt = stoich
            stoich_frame = tk.LabelFrame(dlg, text=self._t('edge_stoich_title'),
                                            bg=biosim_theme('panel'), fg='#9a6700',
                                            font=('Arial', 10, 'bold'), relief='flat')
            stoich_frame.pack(fill='x', padx=14, pady=6)
            row = tk.Frame(stoich_frame, bg=biosim_theme('panel'))
            row.pack(padx=8, pady=8)
            # Build "(N) X + (N) Y (N) Z" with editable boxes
            # For now we treat single from/to but allow stoichiometry coefficients
            # Source side
            src_n_var = tk.StringVar(value=str(edge.get('stoich_src', 1)))
            tk.Label(row, text='(', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 14, 'bold')).pack(side='left')
            ent_src = tk.Entry(row, textvariable=src_n_var, width=3,
                                bg=biosim_theme('bg'), fg='#1a7f37', insertbackground='#1a7f37',
                                relief='flat', font=('Courier', 14, 'bold'),
                                justify='center')
            ent_src.pack(side='left', padx=2)
            tk.Label(row, text=')', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 14, 'bold')).pack(side='left')
            tk.Label(row, text=' ' + edge['from'][:8], bg=biosim_theme('panel'), fg='#1a7f37',
                      font=('Arial', 12, 'bold')).pack(side='left')
            tk.Label(row, text='   ', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 16)).pack(side='left')
            tgt_n_var = tk.StringVar(value=str(edge.get('stoich_tgt', 1)))
            tk.Label(row, text='(', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 14, 'bold')).pack(side='left')
            ent_tgt = tk.Entry(row, textvariable=tgt_n_var, width=3,
                                bg=biosim_theme('bg'), fg='#cf222e', insertbackground='#cf222e',
                                relief='flat', font=('Courier', 14, 'bold'),
                                justify='center')
            ent_tgt.pack(side='left', padx=2)
            tk.Label(row, text=')', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 14, 'bold')).pack(side='left')
            tk.Label(row, text=' ' + edge['to'][:8], bg=biosim_theme('panel'), fg='#cf222e',
                      font=('Arial', 12, 'bold')).pack(side='left')
            stoich_vars['src'] = src_n_var
            stoich_vars['tgt'] = tgt_n_var
            # Explanation
            tk.Label(stoich_frame,
                      text=('Изменяй числа в скобках' if self.lang == 'ru'
                             else 'Edit the numbers in parentheses'),
                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 9, 'italic')).pack(padx=8, pady=(0, 8))

        # Strength editor with +/- buttons
        strength_var = tk.DoubleVar(value=float(edge.get('strength', 3.0)))
        self._add_plus_minus_widget(dlg, self._t('edge_strength'), strength_var,
                                       step=0.5, vmin=0.0, vmax=20.0,
                                       help_topic='strength')

        # Hill n editor with +/- buttons
        hill_var = tk.IntVar(value=int(edge.get('hill_n', 2)))
        self._add_plus_minus_widget(dlg, self._t('edge_hill_n'), hill_var,
                                       step=1, vmin=1, vmax=10, is_int=True,
                                       help_topic='hill_n')

        # Type selector (activation / repression)
        type_frame = tk.LabelFrame(dlg, text=self._t('edge_type_label'),
                                     bg=biosim_theme('panel'), fg='#0550ae',
                                     font=('Arial', 10, 'bold'), relief='flat')
        type_frame.pack(fill='x', padx=14, pady=4)
        type_var = tk.StringVar(value=edge.get('type', 'activation'))
        row_t = tk.Frame(type_frame, bg=biosim_theme('panel'))
        row_t.pack(padx=8, pady=6)
        tk.Radiobutton(row_t, text=self._t('activate'),
                        variable=type_var, value='activation',
                        bg=biosim_theme('panel'), fg='#1a7f37', selectcolor='#eef1f5',
                        activebackground='#ffffff',
                        font=('Arial', 10)).pack(side='left', padx=8)
        tk.Radiobutton(row_t, text=self._t('repress'),
                        variable=type_var, value='repression',
                        bg=biosim_theme('panel'), fg='#cf222e', selectcolor='#eef1f5',
                        activebackground='#ffffff',
                        font=('Arial', 10)).pack(side='left', padx=8)

        # ── Kinetics section: real biochemistry parameters ──
        is_ru = (self.lang == 'ru')
        kin_frame = tk.LabelFrame(
            dlg, text=('Кинетика реакции' if is_ru else 'Reaction kinetics'),
            bg=biosim_theme('panel'), fg='#8250df',
            font=('Arial', 10, 'bold'), relief='flat')
        kin_frame.pack(fill='x', padx=14, pady=6)

        # Which kinetic params are relevant depends on the reaction
        rxn_key = edge.get('reaction', edge.get('type', 'activation'))
        k_var = tk.DoubleVar(value=float(edge.get('k', edge.get('rate', 1.0))))
        kcat_var = tk.DoubleVar(value=float(edge.get('kcat', 1.0)))
        km_var = tk.DoubleVar(value=float(edge.get('km', 1.0)))
        kr_var = tk.DoubleVar(value=float(edge.get('kr', 0.1)))
        rev_var = tk.BooleanVar(value=bool(edge.get('reversible', False)))

        def _kin_row(label, var):
            r = tk.Frame(kin_frame, bg=biosim_theme('panel'))
            r.pack(fill='x', padx=8, pady=2)
            tk.Label(r, text=label, bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 9), width=26, anchor='w').pack(side='left')
            tk.Entry(r, textvariable=var, width=10, bg=biosim_theme('bg'),
                      fg=biosim_theme('text'), relief='flat', font=('Consolas', 10),
                      justify='center', highlightthickness=1,
                      highlightbackground=biosim_theme('border')).pack(side='left', padx=4)

        if rxn_key in ('catalysis',):
            _kin_row(('kcat (число оборотов, 1/с)' if is_ru else 'kcat (turnover, 1/s)'), kcat_var)
            _kin_row(('Km (конст. Михаэлиса)' if is_ru else 'Km (Michaelis const)'), km_var)
        elif rxn_key in ('binding', 'complex_formation', 'dissociation'):
            _kin_row(('kf (прямая, ассоциация)' if is_ru else 'kf (forward, assoc.)'), k_var)
            _kin_row(('kr (обратная, диссоциация)' if is_ru else 'kr (reverse, dissoc.)'), kr_var)
        else:
            _kin_row(('k (константа скорости)' if is_ru else 'k (rate constant)'), k_var)
            _kin_row(('kr (обратная)' if is_ru else 'kr (reverse)'), kr_var)

        tk.Checkbutton(kin_frame,
                        text=('↔ Обратимая реакция' if is_ru else '↔ Reversible reaction'),
                        variable=rev_var, bg=biosim_theme('panel'), fg='#0969da',
                        selectcolor='#eef1f5', activebackground='#ffffff',
                        font=('Arial', 9)).pack(anchor='w', padx=8, pady=(2, 4))

        # Custom rate law (overrides everything if non-empty)
        cr_frame = tk.LabelFrame(
            dlg, text=('Своя формула скорости (необязательно)' if is_ru
                       else 'Custom rate law (optional)'),
            bg=biosim_theme('panel'), fg='#bc4c00',
            font=('Arial', 10, 'bold'), relief='flat')
        cr_frame.pack(fill='x', padx=14, pady=6)
        tk.Label(cr_frame,
                  text=('Переменные: S=источник, P=цель, t=время. '
                        'Функции: sin, cos, exp, sqrt, log.\n'
                        'Пример:  0.5*S*S/(1+P)   — переопределяет кинетику выше.'
                        if is_ru else
                        'Variables: S=source, P=target, t=time. '
                        'Funcs: sin, cos, exp, sqrt, log.\n'
                        'Example:  0.5*S*S/(1+P)   — overrides the kinetics above.'),
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 8), justify='left').pack(anchor='w', padx=8, pady=(2, 2))
        custom_var = tk.StringVar(value=str(edge.get('custom_rate', '') or ''))
        tk.Entry(cr_frame, textvariable=custom_var, bg=biosim_theme('bg'),
                  fg='#bc4c00', relief='flat', font=('Consolas', 11),
                  highlightthickness=1, highlightbackground='#bc4c00'
                  ).pack(fill='x', padx=8, pady=(0, 6), ipady=3)

        # Buttons
        def save_edits():
            self._save_history('constructor')
            edge['type'] = type_var.get()
            edge['strength'] = safe_float(strength_var.get(), 1.0)
            edge['hill_n'] = safe_int(hill_var.get(), 2)
            # Kinetics
            edge['k'] = safe_float(k_var.get(), 1.0)
            edge['kcat'] = safe_float(kcat_var.get(), 1.0)
            edge['km'] = safe_float(km_var.get(), 1.0)
            edge['kr'] = safe_float(kr_var.get(), 0.1)
            edge['reversible'] = bool(rev_var.get())
            # Custom rate law — validate before saving
            cr = custom_var.get().strip()
            if cr:
                try:
                    test_env = {'S': 1.0, 'P': 1.0, 's': 1.0, 'p': 1.0, 't': 0.0,
                                'time': 0.0, 'sin': math.sin, 'cos': math.cos,
                                'exp': math.exp, 'sqrt': math.sqrt, 'log': math.log,
                                'pow': pow, 'pi': math.pi}
                    float(eval(cr, {'__builtins__': {}}, test_env))
                    edge['custom_rate'] = cr
                except Exception as ex:
                    messagebox.showerror(
                        'VIREON',
                        ('Ошибка в формуле: {}\nПример правильной: 0.5*S/(1+P)'
                         .format(ex) if self.lang == 'ru' else
                         'Formula error: {}\nValid example: 0.5*S/(1+P)'.format(ex)))
                    return
            else:
                edge.pop('custom_rate', None)
            if 'src' in stoich_vars:
                try:
                    edge['stoich_src'] = int(stoich_vars['src'].get() or 1)
                    edge['stoich_tgt'] = int(stoich_vars['tgt'].get() or 1)
                except Exception as _exc:
                    biosim_log('warn', 'save_edits: {}'.format(_exc))
            self._cons_refresh()
            self._cons_status_lbl.config(text=self._t('edge_renamed_ok'))
            dlg.destroy()

        def delete_edge():
            self._save_history('constructor')
            del state['edges'][edge_idx]
            self._cons_refresh()
            self._cons_status_lbl.config(
                text='Связь удалена' if self.lang == 'ru' else 'Connection deleted')
            dlg.destroy()

        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=10)
        tk.Button(btn_row, text=self._t('prop_save'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=4,
                   command=save_edits
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text='' + self._t('edge_delete'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=delete_edge
                   ).pack(side='left', padx=2)
        tk.Button(btn_row, text=self._t('cancel'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy
                   ).pack(side='right', padx=2)

    def _add_plus_minus_widget(self, parent, label, var, step=0.1, vmin=0.0, vmax=10.0,
                                  is_int=False, help_topic=None):
        """Add a [-] [entry] [+] [slider] widget for editing a numeric value.
        If help_topic given, label will include a ⓘ button linking to glossary."""
        frame = tk.LabelFrame(parent, text=label, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                font=('Arial', 10, 'bold'), relief='flat')
        frame.pack(fill='x', padx=14, pady=4)
        # Optional help icon row inside frame
        if help_topic:
            help_row = tk.Frame(frame, bg=biosim_theme('panel'))
            help_row.pack(fill='x', padx=8, pady=(2, 0))
            help_lbl = tk.Label(help_row, text='ⓘ ' + ('Что это значит?' if self.lang == 'ru'
                                                          else 'What does this mean?'),
                                  bg=biosim_theme('panel'), fg='#0969da',
                                  font=('Arial', 8, 'italic'),
                                  cursor='hand2')
            help_lbl.pack(side='left')
            help_lbl.bind('<Button-1>',
                            lambda e, t=help_topic: HelpWindow(parent, lang=self.lang, topic=t))
        row = tk.Frame(frame, bg=biosim_theme('panel'))
        row.pack(fill='x', padx=8, pady=4)

        def decrement():
            try:
                v = float(var.get()) - step
                v = max(vmin, v)
                if is_int:
                    var.set(int(round(v)))
                else:
                    var.set(round(v, 3))
            except Exception as _exc:
                biosim_log('warn', 'decrement: {}'.format(_exc))

        def increment():
            try:
                v = float(var.get()) + step
                v = min(vmax, v)
                if is_int:
                    var.set(int(round(v)))
                else:
                    var.set(round(v, 3))
            except Exception as _exc:
                biosim_log('warn', 'increment: {}'.format(_exc))

        tk.Button(row, text='−', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 14, 'bold'), cursor='hand2',
                   width=3, command=decrement).pack(side='left', padx=2)
        ent = tk.Entry(row, textvariable=var, width=8,
                        bg=biosim_theme('bg'), fg=biosim_theme('text'), insertbackground='#1c2128',
                        relief='flat', font=('Courier', 12, 'bold'),
                        justify='center', highlightthickness=1,
                        highlightbackground=biosim_theme('border'))
        ent.pack(side='left', padx=4, ipady=3)
        tk.Button(row, text='+', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 14, 'bold'), cursor='hand2',
                   width=3, command=increment).pack(side='left', padx=2)
        # Slider
        slider = tk.Scale(row, from_=vmin, to=vmax, resolution=step,
                           orient='horizontal', variable=var,
                           bg=biosim_theme('panel'), fg=biosim_theme('text'), highlightthickness=0,
                           troughcolor='#eef1f5', activebackground='#8250df',
                           showvalue=False, length=200)
        slider.pack(side='left', fill='x', expand=True, padx=8)
        return frame

    # ── Context menu actions ──

    def _cons_select_all(self):
        """Select all nodes."""
        state = self.current_state['constructor']
        if state is None:
            return
        self._cons_selected_nodes = set(n['id'] for n in state['nodes'])
        self._cons_refresh()
        self._cons_status_lbl.config(
            text=self._t('selected_count') + ' ' + str(len(self._cons_selected_nodes)))

    def _cons_deselect_all(self):
        """Clear selection."""
        self._cons_selected_nodes = set()
        self._cons_refresh()
        self._cons_status_lbl.config(text=self._t('right_click_hint'))

    def _cons_delete_selected(self):
        """Delete all selected nodes and their edges/chains."""
        if not self._cons_selected_nodes:
            return
        state = self.current_state['constructor']
        self._save_history('constructor')
        to_delete = set(self._cons_selected_nodes)
        state['nodes'] = [n for n in state['nodes'] if n['id'] not in to_delete]
        state['edges'] = [e for e in state['edges']
                           if e['from'] not in to_delete and e['to'] not in to_delete]
        for nid in to_delete:
            if nid in state['init']:
                del state['init'][nid]
            self._cons_remove_from_chains(nid)
        # Also remove from any compartment 'contains' lists
        for n in state['nodes']:
            if n.get('icon') == 'cell':
                n['contains'] = [c for c in n.get('contains', []) if c not in to_delete]
        self._cons_selected_nodes = set()
        self._cons_refresh()

    def _cons_set_size(self, factor):
        """Set size of single selected node."""
        if not self._cons_selected_nodes:
            return
        state = self.current_state['constructor']
        self._save_history('constructor')
        for n in state['nodes']:
            if n['id'] in self._cons_selected_nodes:
                n['size'] = factor
                break  # only first
        self._cons_refresh()

    def _cons_set_size_all(self, factor):
        """Set size of all selected nodes."""
        if not self._cons_selected_nodes:
            return
        state = self.current_state['constructor']
        self._save_history('constructor')
        for n in state['nodes']:
            if n['id'] in self._cons_selected_nodes:
                n['size'] = factor
        self._cons_refresh()

    def _cons_duplicate_selected(self):
        """Duplicate selected nodes with an offset."""
        if not self._cons_selected_nodes:
            return
        state = self.current_state['constructor']
        self._save_history('constructor')
        import copy
        new_ids = set()
        existing_ids = set(n['id'] for n in state['nodes'])
        for n in list(state['nodes']):
            if n['id'] in self._cons_selected_nodes:
                new_n = copy.deepcopy(n)
                # Generate new unique id
                base = n['id']
                counter = 1
                new_id = base + '_copy'
                while new_id in existing_ids:
                    new_id = base + '_copy' + str(counter)
                    counter += 1
                new_n['id'] = new_id
                new_n['x'] = n['x'] + 50
                new_n['y'] = n['y'] + 50
                # Don't inherit chain membership
                state['nodes'].append(new_n)
                state['init'][new_id] = state['init'].get(n['id'], 0.5)
                existing_ids.add(new_id)
                new_ids.add(new_id)
        # Select the new duplicates
        self._cons_selected_nodes = new_ids
        self._cons_refresh()

    # ══════════════════════════════════════════════════════════════════
    # COPY / CUT / PASTE  (works within a schema AND between schemas/windows)
    # ══════════════════════════════════════════════════════════════════
    # Shared clipboard lives on the class so copying in one SynBioWindow and
    # pasting in another works. Stores a deep copy of selected nodes + the
    # edges that connect two selected nodes.
    _clipboard = None   # dict: {'nodes': [...], 'edges': [...], 'init': {...}}

    def _cons_copy_selected(self, cut=False):
        """Copy selected nodes (and internal edges) into the shared clipboard."""
        state = self.current_state.get('constructor')
        if not state or not self._cons_selected_nodes:
            self._cons_status_lbl.config(
                text=('Ничего не выделено' if self.lang == 'ru'
                      else 'Nothing selected'), fg='#9a6700')
            return
        import copy
        sel = set(self._cons_selected_nodes)
        nodes = [copy.deepcopy(n) for n in state['nodes'] if n['id'] in sel]
        # Only edges whose both ends are inside the selection
        edges = []
        for e in state['edges']:
            frm = e.get('from'); to = e.get('to')
            srcs = e.get('sources'); tgts = e.get('targets')
            if srcs and tgts:
                if all(s in sel for s in srcs) and all(t in sel for t in tgts):
                    edges.append(copy.deepcopy(e))
            elif frm in sel and to in sel:
                edges.append(copy.deepcopy(e))
        init = {n['id']: state.get('init', {}).get(n['id'], 0.5) for n in nodes}
        SynBioWindow._clipboard = {'nodes': nodes, 'edges': edges, 'init': init}
        n_cnt = len(nodes)
        if cut:
            self._cons_delete_selected()
            self._cons_status_lbl.config(
                text=('Вырезано узлов: {}'.format(n_cnt) if self.lang == 'ru'
                      else 'Cut {} node(s)'.format(n_cnt)), fg='#1a7f37')
        else:
            self._cons_status_lbl.config(
                text=('Скопировано узлов: {}'.format(n_cnt) if self.lang == 'ru'
                      else 'Copied {} node(s)'.format(n_cnt)), fg='#1a7f37')

    def _cons_cut_selected(self):
        self._cons_copy_selected(cut=True)

    def _cons_paste_clipboard(self, dx=40, dy=40):
        """Paste clipboard contents into the current schema with an offset.
        Node ids are remapped to stay unique; internal edges are rewired."""
        clip = SynBioWindow._clipboard
        if not clip or not clip.get('nodes'):
            self._cons_status_lbl.config(
                text=('Буфер пуст' if self.lang == 'ru' else 'Clipboard is empty'),
                fg='#9a6700')
            return
        state = self.current_state.get('constructor')
        if state is None:
            return
        import copy
        self._save_history('constructor')
        existing_ids = set(n['id'] for n in state['nodes'])
        id_map = {}   # old id -> new id
        new_ids = set()
        for on in clip['nodes']:
            n = copy.deepcopy(on)
            old_id = n['id']
            base = old_id
            new_id = base + '_p'
            counter = 1
            while new_id in existing_ids:
                new_id = base + '_p' + str(counter)
                counter += 1
            n['id'] = new_id
            n['x'] = n.get('x', 100) + dx
            n['y'] = n.get('y', 100) + dy
            # Drop stale container/chain membership — it references old ids
            n.pop('contains', None)
            n.pop('chain_prev', None)
            n.pop('chain_next', None)
            id_map[old_id] = new_id
            existing_ids.add(new_id)
            new_ids.add(new_id)
            state['nodes'].append(n)
            state['init'][new_id] = clip.get('init', {}).get(old_id, 0.5)
        # Rewire edges using id_map (only ends that were copied)
        for oe in clip['edges']:
            e = copy.deepcopy(oe)
            if e.get('sources') and e.get('targets'):
                if not all(s in id_map for s in e['sources']):
                    continue
                if not all(t in id_map for t in e['targets']):
                    continue
                e['sources'] = [id_map[s] for s in e['sources']]
                e['targets'] = [id_map[t] for t in e['targets']]
                e['from'] = e['sources'][0]
                e['to'] = e['targets'][0]
            else:
                if e.get('from') not in id_map or e.get('to') not in id_map:
                    continue
                e['from'] = id_map[e['from']]
                e['to'] = id_map[e['to']]
            state['edges'].append(e)
        self._cons_selected_nodes = new_ids
        self._cons_refresh()
        self._cons_status_lbl.config(
            text=('Вставлено узлов: {}'.format(len(new_ids)) if self.lang == 'ru'
                  else 'Pasted {} node(s)'.format(len(new_ids))), fg='#1a7f37')

    def _cons_paste_at(self, x, y):
        """Paste so the clipboard's top-left corner lands near (x, y)."""
        clip = SynBioWindow._clipboard
        if not clip or not clip.get('nodes'):
            return
        xs = [n.get('x', 0) for n in clip['nodes']]
        ys = [n.get('y', 0) for n in clip['nodes']]
        minx, miny = min(xs), min(ys)
        self._cons_paste_clipboard(dx=x - minx, dy=y - miny)

    # ══════════════════════════════════════════════════════════════════
    # LAYOUT / ALIGN / ZOOM TOOLS (inspired by TinkerCell auto-layout)
    # ══════════════════════════════════════════════════════════════════

    def _cons_auto_layout(self, style='spring'):
        """Automatically arrange nodes on the canvas.

        style='spring'   → force-directed (Fruchterman-Reingold style): edges
                            pull connected nodes together, all nodes repel each
                            other. Good for general circuits.
        style='circular' → place all nodes evenly on a circle.
        style='grid'     → arrange nodes in a neat grid.

        Works on the whole circuit (or only the selected nodes if 2+ selected).
        Pure-Python, so no networkx dependency is required.
        """
        state = self.current_state['constructor']
        if state is None or not state['nodes']:
            return
        # Which nodes to lay out
        sel = self._cons_selected_nodes
        if sel and len(sel) >= 2:
            nodes = [n for n in state['nodes'] if n['id'] in sel]
        else:
            nodes = list(state['nodes'])
        if len(nodes) < 2:
            return
        self._save_history('constructor')

        # Canvas area to lay out within
        try:
            W = max(400, int(self.cons_canvas.winfo_width()))
            H = max(300, int(self.cons_canvas.winfo_height()))
        except Exception:
            W, H = 800, 600
        cx, cy = W / 2.0, H / 2.0
        margin = 60

        import math as _m
        ids = [n['id'] for n in nodes]

        if style == 'circular':
            R = max(80, min(W, H) / 2.0 - margin)
            for i, n in enumerate(nodes):
                ang = 2 * _m.pi * i / len(nodes)
                n['x'] = cx + R * _m.cos(ang)
                n['y'] = cy + R * _m.sin(ang)

        elif style == 'grid':
            cols = int(_m.ceil(_m.sqrt(len(nodes))))
            gap_x = (W - 2 * margin) / max(1, cols)
            rows = int(_m.ceil(len(nodes) / cols))
            gap_y = (H - 2 * margin) / max(1, rows)
            for i, n in enumerate(nodes):
                r, c = divmod(i, cols)
                n['x'] = margin + gap_x * (c + 0.5)
                n['y'] = margin + gap_y * (r + 0.5)

        else:  # spring / force-directed
            # Build adjacency from edges
            idset = set(ids)
            adj = {i: set() for i in ids}
            for e in state['edges']:
                a, b = e.get('from'), e.get('to')
                if a in idset and b in idset and a != b:
                    adj[a].add(b)
                    adj[b].add(a)
            # Initialise positions on a circle (stable start)
            pos = {}
            R0 = max(80, min(W, H) / 2.0 - margin)
            for i, nid in enumerate(ids):
                ang = 2 * _m.pi * i / len(ids)
                pos[nid] = [cx + R0 * _m.cos(ang), cy + R0 * _m.sin(ang)]
            k = max(40.0, (min(W, H) - 2 * margin) / max(1, _m.sqrt(len(ids))))
            # Iterate
            for step in range(60):
                disp = {nid: [0.0, 0.0] for nid in ids}
                # Repulsion between every pair
                for i in range(len(ids)):
                    for j in range(i + 1, len(ids)):
                        a, b = ids[i], ids[j]
                        dx = pos[a][0] - pos[b][0]
                        dy = pos[a][1] - pos[b][1]
                        dist = _m.hypot(dx, dy) or 0.01
                        force = (k * k) / dist
                        ux, uy = dx / dist, dy / dist
                        disp[a][0] += ux * force; disp[a][1] += uy * force
                        disp[b][0] -= ux * force; disp[b][1] -= uy * force
                # Attraction along edges
                for a in ids:
                    for b in adj[a]:
                        if a < b:
                            dx = pos[a][0] - pos[b][0]
                            dy = pos[a][1] - pos[b][1]
                            dist = _m.hypot(dx, dy) or 0.01
                            force = (dist * dist) / k
                            ux, uy = dx / dist, dy / dist
                            disp[a][0] -= ux * force; disp[a][1] -= uy * force
                            disp[b][0] += ux * force; disp[b][1] += uy * force
                # Apply with cooling
                temp = k * (1.0 - step / 60.0)
                for nid in ids:
                    dxy = _m.hypot(disp[nid][0], disp[nid][1]) or 0.01
                    lim = min(dxy, temp)
                    pos[nid][0] += disp[nid][0] / dxy * lim
                    pos[nid][1] += disp[nid][1] / dxy * lim
                    # Keep inside canvas
                    pos[nid][0] = min(W - margin, max(margin, pos[nid][0]))
                    pos[nid][1] = min(H - margin, max(margin, pos[nid][1]))
            for n in nodes:
                n['x'], n['y'] = pos[n['id']][0], pos[n['id']][1]

        self._cons_refresh()
        try:
            self._cons_status_lbl.config(
                text=('Схема расставлена' if self.lang == 'ru' else 'Layout applied'),
                fg='#1a7f37')
        except Exception:
            pass

    def _cons_align(self, how):
        """Align selected nodes. how = 'left'|'right'|'top'|'bottom'|
        'center_h'|'center_v'. Needs 2+ selected nodes."""
        state = self.current_state['constructor']
        if state is None:
            return
        sel = [n for n in state['nodes'] if n['id'] in self._cons_selected_nodes]
        if len(sel) < 2:
            try:
                self._cons_status_lbl.config(
                    text=('Выдели 2+ узла' if self.lang == 'ru' else 'Select 2+ nodes'),
                    fg='#cf222e')
            except Exception:
                pass
            return
        self._save_history('constructor')
        xs = [n['x'] for n in sel]
        ys = [n['y'] for n in sel]
        if how == 'left':
            v = min(xs); [n.__setitem__('x', v) for n in sel]
        elif how == 'right':
            v = max(xs); [n.__setitem__('x', v) for n in sel]
        elif how == 'top':
            v = min(ys); [n.__setitem__('y', v) for n in sel]
        elif how == 'bottom':
            v = max(ys); [n.__setitem__('y', v) for n in sel]
        elif how == 'center_h':  # same vertical center line (align x)
            v = sum(xs) / len(xs); [n.__setitem__('x', v) for n in sel]
        elif how == 'center_v':  # same horizontal center line (align y)
            v = sum(ys) / len(ys); [n.__setitem__('y', v) for n in sel]
        self._cons_refresh()

    def _cons_distribute(self, axis='h'):
        """Evenly space selected nodes along axis 'h' (x) or 'v' (y).
        Needs 3+ selected nodes."""
        state = self.current_state['constructor']
        if state is None:
            return
        sel = [n for n in state['nodes'] if n['id'] in self._cons_selected_nodes]
        if len(sel) < 3:
            try:
                self._cons_status_lbl.config(
                    text=('Выдели 3+ узла' if self.lang == 'ru' else 'Select 3+ nodes'),
                    fg='#cf222e')
            except Exception:
                pass
            return
        self._save_history('constructor')
        key = 'x' if axis == 'h' else 'y'
        sel.sort(key=lambda n: n[key])
        lo, hi = sel[0][key], sel[-1][key]
        step = (hi - lo) / (len(sel) - 1)
        for i, n in enumerate(sel):
            n[key] = lo + step * i
        self._cons_refresh()

    def _cons_zoom_to_fit(self):
        """Fit the whole circuit in the visible canvas using the view transform
        (scale + pan) — node coordinates are NOT modified, so it's reversible
        with Ctrl+0."""
        state = self.current_state['constructor']
        if state is None or not state['nodes']:
            return
        nodes = state['nodes']
        xs = [n['x'] for n in nodes]
        ys = [n['y'] for n in nodes]
        minx, maxx = min(xs), max(xs)
        miny, maxy = min(ys), max(ys)
        bw = (maxx - minx) or 1.0
        bh = (maxy - miny) or 1.0
        try:
            W = max(400, int(self.cons_canvas.winfo_width()))
            H = max(300, int(self.cons_canvas.winfo_height()))
        except Exception:
            W, H = 800, 600
        margin = 70
        scale = min((W - 2 * margin) / bw, (H - 2 * margin) / bh)
        scale = max(0.2, min(scale, 3.0))
        self._cons_scale = scale
        # Center the bounding box in the view
        cx_world = (minx + maxx) / 2.0
        cy_world = (miny + maxy) / 2.0
        self._cons_pan_x = W / 2.0 - cx_world * scale
        self._cons_pan_y = H / 2.0 - cy_world * scale
        self._cons_refresh()
        self._update_zoom_label()
        try:
            self._cons_status_lbl.config(
                text=('Вписано в экран' if self.lang == 'ru' else 'Zoomed to fit'),
                fg='#1a7f37')
        except Exception:
            pass

    def _cons_connection_is_valid(self, rxn_key, source_node, target_node):
        """Soft validation of a connection (TinkerCell-style family rules).

        Returns (ok, message). ok=False only for clearly wrong pairings; the
        caller may still allow it (soft warning) so experimentation isn't
        blocked. `source_node`/`target_node` are node dicts.
        """
        if not source_node or not target_node:
            return True, ''
        is_ru = (self.lang == 'ru')
        s_icon = source_node.get('icon', '')
        t_icon = target_node.get('icon', '')
        s_type = self._cons_node_type(source_node)
        t_type = self._cons_node_type(target_node)

        # A knockout marker should not be a source of regulation
        if s_icon == 'knockout':
            return False, ('Нокаут не может быть источником регуляции'
                            if is_ru
                            else 'A knockout marker cannot regulate anything')
        # Reporters/outputs are measured, they don't usually regulate others
        if s_icon == 'output_reporter' and rxn_key in ('activation', 'repression'):
            return False, ('Репортёр обычно не регулирует другие узлы'
                            if is_ru
                            else 'A reporter usually does not regulate other nodes')

        # ── Type-based rules (mirror TinkerCell connection families) ──
        # Transcription regulation: a TF/protein/small-molecule acts on a
        # promoter or operator — NOT on two bare molecules.
        if rxn_key in ('activation', 'repression', 'direct_gene_regulation'):
            if t_type not in ('promoter', 'operator', 'cds', 'dna_other',
                              'tf', 'protein', 'molecule', 'mrna', 'rna',
                              'enzyme', 'output'):
                if t_type == 'input':
                    return False, ('Нельзя регулировать входной сигнал'
                                    if is_ru
                                    else 'Cannot regulate an input signal')
            # Ideal target of transcription regulation is a promoter/operator
            if t_type in ('molecule', 'phosphate') and s_type in ('molecule', 'phosphate'):
                return False, ('Регуляция транскрипции соединяет фактор с '
                               'промотором/оператором, а не две молекулы'
                               if is_ru else
                               'Transcription regulation connects a factor to a '
                               'promoter/operator, not two molecules')
        # Transcription: promoter → mRNA/CDS
        if rxn_key == 'transcription':
            if s_type not in ('promoter', 'cds', 'dna_other', 'operator'):
                return False, ('Транскрипция начинается с промотора/гена'
                               if is_ru else
                               'Transcription should start from a promoter/gene')
        # Translation: mRNA/RBS → protein
        if rxn_key == 'translation':
            if s_type not in ('mrna', 'rbs', 'rna', 'cds'):
                return False, ('Трансляция идёт с мРНК (через RBS) в белок'
                               if is_ru else
                               'Translation goes from mRNA (via RBS) to protein')
        # Catalysis: an enzyme catalyses; source should be enzyme/protein
        if rxn_key == 'catalysis':
            if s_type not in ('enzyme', 'protein', 'tf'):
                return False, ('Катализатором должен быть фермент/белок'
                               if is_ru else
                               'The catalyst should be an enzyme/protein')
        # Phosphorylation: needs a protein target
        if rxn_key in ('phosphorylation', 'dephosphorylation'):
            if t_type not in ('protein', 'tf', 'enzyme'):
                return False, ('Фосфорилируется обычно белок'
                               if is_ru else
                               'Phosphorylation usually targets a protein')
        # PoPS / RiPS flow between DNA/mRNA parts
        if rxn_key in ('pops',):
            if s_type not in ('promoter', 'operator', 'rbs', 'cds', 'dna_other',
                              'terminator') or \
               t_type not in ('promoter', 'operator', 'rbs', 'cds', 'dna_other',
                              'terminator'):
                return False, ('PoPS течёт между ДНК-частями (промотор→RBS→CDS→…)'
                               if is_ru else
                               'PoPS flows between DNA parts (promoter→RBS→CDS→…)')
        if rxn_key in ('rips',):
            if s_type not in ('rbs', 'mrna', 'cds', 'rna') or \
               t_type not in ('rbs', 'mrna', 'cds', 'rna'):
                return False, ('RiPS течёт вдоль мРНК (RBS→CDS)'
                               if is_ru else
                               'RiPS flows along mRNA (RBS→CDS)')
        # Self-loops for regulation are allowed (autoregulation), so no block.
        return True, ''

    def _cons_suggest_connection(self, source_node, target_node):
        """TinkerCell 'which did you mean?' helper: given two nodes, return the
        most-specific reaction key that best fits their types, or None.
        Used to auto-suggest a better connection when the user picks a generic
        one between well-typed parts."""
        if not source_node or not target_node:
            return None
        s = self._cons_node_type(source_node)
        t = self._cons_node_type(target_node)
        # TF/protein → promoter/operator  ⇒ activation or repression
        if s in ('tf', 'protein', 'molecule') and t in ('promoter', 'operator'):
            role = source_node.get('tf_role') or source_node.get('regulation')
            if role == 'activator':
                return 'activation'
            if role == 'repressor':
                return 'repression'
            return 'direct_gene_regulation'
        # promoter → CDS/mRNA ⇒ transcription (or PoPS along DNA)
        if s == 'promoter' and t in ('cds', 'dna_other', 'mrna'):
            return 'transcription'
        if s in ('promoter', 'operator', 'rbs', 'cds') and t in ('rbs', 'cds', 'terminator', 'operator'):
            return 'pops'
        # mRNA/RBS → protein ⇒ translation
        if s in ('mrna', 'rbs', 'rna') and t in ('protein', 'tf', 'enzyme'):
            return 'translation'
        # enzyme + substrate(molecule) ⇒ catalysis
        if s == 'enzyme' and t in ('molecule', 'phosphate'):
            return 'catalysis'
        # molecule + molecule ⇒ biochemical/binding
        if s in ('molecule', 'phosphate') and t in ('molecule', 'phosphate'):
            return 'biochemical_reaction'
        return None

    # Canonical biological order of DNA parts along a construct (5'→3').
    # Lower number = earlier on the strand. Used to line parts up on a plasmid.
    _DNA_PART_ORDER = {
        'origin':          0,   # ori
        'insulator':       1,
        'promoter':        2,
        'binding_site':    3,   # operator / activator / repressor site
        'operator':        3,
        'rbs':             4,
        'riboswitch':      4,
        'cds':             5,   # coding sequence
        'sgrna':           5,
        'tag':             6,   # degradation tag
        'terminator':      7,
        'spacer':          8,
        'scar':            8,
    }

    def _cons_is_dna_part(self, node):
        """True if the node is a DNA/genetic part (belongs on a plasmid)."""
        pdata = CIRCUIT_PARTS_CATALOG.get(node.get('part_key'), {})
        fam = pdata.get('family', '')
        return fam.startswith('Genes')

    def _cons_node_type(self, node):
        """Classify a node into a coarse type used for type-specific properties
        and connection logic. Returns one of:
        'promoter','rbs','cds','terminator','operator','dna_other',
        'tf','enzyme','protein','molecule','phosphate','mrna','rna',
        'compartment','input','output','other'.
        Mirrors TinkerCell's family-based attribute system."""
        icon = node.get('icon', '')
        pk = node.get('part_key', '') or ''
        pdata = CIRCUIT_PARTS_CATALOG.get(pk, {})
        fam = pdata.get('family', '')
        # Inputs / outputs are prefixed part_keys
        if pk.startswith('__input__') or node.get('input_type'):
            return 'input'
        if pk.startswith('__output__') or node.get('output_type'):
            return 'output'
        # DNA parts by icon/family
        if icon == 'promoter' or 'Promoter' in fam:
            return 'promoter'
        if icon == 'rbs' or 'RBS' in fam:
            return 'rbs'
        if icon == 'terminator' or 'Terminator' in fam or 'Tags' in fam:
            return 'terminator'
        if icon in ('binding_site', 'operator') or 'Binding sites' in fam:
            return 'operator'
        if 'Cassette' in fam:
            return 'cds'
        if icon == 'cds' or 'CDS' in fam or 'sgRNA' in fam:
            return 'cds'
        if fam.startswith('Genes'):
            return 'dna_other'
        # Proteins
        if 'Transcription factors' in fam:
            return 'tf'
        if 'Enzyme' in fam or icon == 'enzyme_diamond':
            return 'enzyme'
        if fam.startswith('Proteins'):
            return 'protein'
        # Small molecules / RNA
        if 'Phosphate' in fam or pk == 'phosphate':
            return 'phosphate'
        if icon == 'mrna' or fam.endswith('mRNA'):
            return 'mrna'
        if 'RNA' in fam:
            return 'rna'
        if fam.startswith('Small molecules'):
            return 'molecule'
        # Compartments
        if icon in ('cell', 'membrane') or fam.startswith('Compartments'):
            return 'compartment'
        return 'other'

    # Human-readable type labels
    _NODE_TYPE_LABELS = {
        'promoter':    ('Промотор', 'Promoter'),
        'rbs':         ('RBS (сайт связывания рибосомы)', 'RBS'),
        'cds':         ('Кодирующая последовательность', 'Coding sequence'),
        'terminator':  ('Терминатор', 'Terminator'),
        'operator':    ('Оператор / сайт связывания', 'Operator / binding site'),
        'dna_other':   ('ДНК-элемент', 'DNA element'),
        'tf':          ('Фактор транскрипции', 'Transcription factor'),
        'enzyme':      ('Фермент', 'Enzyme'),
        'protein':     ('Белок', 'Protein'),
        'molecule':    ('Малая молекула', 'Small molecule'),
        'phosphate':   ('Фосфат', 'Phosphate'),
        'mrna':        ('мРНК', 'mRNA'),
        'rna':         ('РНК', 'RNA'),
        'compartment': ('Компартмент', 'Compartment'),
        'input':       ('Вход (сигнал)', 'Input (signal)'),
        'output':      ('Выход (репортёр)', 'Output (reporter)'),
        'other':       ('Элемент', 'Element'),
    }

    def _cons_type_label(self, node_type):
        ru, en = self._NODE_TYPE_LABELS.get(node_type, ('Элемент', 'Element'))
        return ru if self.lang == 'ru' else en

    def _cons_dna_sort_key(self, node):
        """Sort key for a DNA part: (biological order, current x)."""
        icon = node.get('icon', '')
        pdata = CIRCUIT_PARTS_CATALOG.get(node.get('part_key'), {})
        fam = pdata.get('family', '')
        # Derive an order bucket from icon first, then family subtype
        order = self._DNA_PART_ORDER.get(icon)
        if order is None:
            sub = fam.split('/')[-1].lower()
            for key, val in self._DNA_PART_ORDER.items():
                if key in sub:
                    order = val
                    break
        if order is None:
            order = 5   # unknown → treat like a CDS in the middle
        return (order, node.get('x', 0))

    def _cons_align_dna_on_plasmid(self):
        """Line up DNA parts neatly in 5'→3' order.
        - In 'circular' view: distribute parts evenly around a circle.
        - Otherwise: lay them out left→right on one horizontal line.
        Works on the selected DNA parts, or on all DNA parts if none selected."""
        state = self.current_state['constructor']
        if state is None or not state['nodes']:
            return
        sel = self._cons_selected_nodes
        if sel and len(sel) >= 2:
            dna = [n for n in state['nodes']
                   if n['id'] in sel and self._cons_is_dna_part(n)]
        else:
            dna = [n for n in state['nodes'] if self._cons_is_dna_part(n)]
        if len(dna) < 2:
            try:
                self._cons_status_lbl.config(
                    text=('Нужно 2+ ДНК-части (промотор, RBS, CDS…)'
                          if self.lang == 'ru'
                          else 'Need 2+ DNA parts (promoter, RBS, CDS…)'),
                    fg='#cf222e')
            except Exception:
                pass
            return
        self._save_history('constructor')
        dna.sort(key=self._cons_dna_sort_key)

        try:
            W = max(400, int(self.cons_canvas.winfo_width()))
            H = max(300, int(self.cons_canvas.winfo_height()))
        except Exception:
            W, H = 800, 600

        view = getattr(self, 'cons_view_mode', None)
        mode = view.get() if view is not None else 'cartoon'

        import math as _m
        if mode == 'circular':
            # Evenly around a circle, in biological order (clockwise from top)
            cx, cy = W / 2.0, H / 2.0
            R = max(90, min(W, H) / 2.0 - 80)
            n = len(dna)
            for i, node in enumerate(dna):
                ang = -_m.pi / 2 + 2 * _m.pi * i / n
                node['x'] = cx + R * _m.cos(ang)
                node['y'] = cy + R * _m.sin(ang)
        else:
            # Straight horizontal line, evenly spaced
            step = 90
            total_w = step * (len(dna) - 1)
            start_x = max(70, (W - total_w) / 2.0)
            y = H / 2.0
            for i, node in enumerate(dna):
                node['x'] = start_x + i * step
                node['y'] = y

        self._cons_refresh()
        try:
            self._cons_status_lbl.config(
                text=('ДНК-части выровнены (5′→3′): {}'.format(len(dna))
                      if self.lang == 'ru'
                      else 'DNA parts aligned (5′→3′): {}'.format(len(dna))),
                fg='#1a7f37')
        except Exception:
            pass

    def _cons_open_model_menu(self):
        """Popup surfacing the model 'power tools' that were previously buried in
        context menus: text mode, live sliders, Python console, plus a function
        finder (searchbox) and a hotkeys cheat-sheet."""
        is_ru = (self.lang == 'ru')
        menu = tk.Toplevel(self)
        menu.title('Модель' if is_ru else 'Model')
        menu.geometry('360x520')
        menu.configure(bg=biosim_theme('bg'))
        menu.transient(self)
        try:
            menu.grab_set()
        except Exception:
            pass

        tk.Label(menu, text=('🧪 Инструменты модели' if is_ru else '🧪 Model tools'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 13, 'bold')).pack(pady=(10, 4))

        # ── Function finder (search) ──
        search_var = tk.StringVar()
        sf = tk.Frame(menu, bg=biosim_theme('bg'))
        sf.pack(fill='x', padx=14, pady=(0, 6))
        tk.Label(sf, text='🔎', bg=biosim_theme('bg'),
                  font=('Arial', 12)).pack(side='left')
        search_entry = tk.Entry(sf, textvariable=search_var, bg=biosim_theme('panel2'),
                                 fg=biosim_theme('text'), relief='flat', font=('Arial', 11),
                                 highlightthickness=1, highlightbackground='#8250df')
        search_entry.pack(side='left', fill='x', expand=True, padx=6, ipady=3)
        search_entry.focus_set()

        # Registry of all actions the finder can jump to
        def act(fn):
            return lambda: (menu.destroy(), fn())
        actions = [
            (('Текстовый режим Antimony (текст ⇄ схема)' if is_ru
              else 'Antimony text mode'), '📝', act(self._cons_open_text_mode)),
            (('Живые параметры (слайдеры)' if is_ru
              else 'Live parameters (sliders)'), '🎚', act(self._cons_open_live_sliders)),
            (('Python-консоль' if is_ru else 'Python console'), '🐍',
             act(self._cons_open_python_console)),
            (('Показать уравнения модели' if is_ru else 'Show model equations'), '∑',
             act(self._cons_show_equations)),
            (('Выровнять ДНК-части (5′→3′)' if is_ru else 'Align DNA parts'), '🧬',
             act(self._cons_align_dna_on_plasmid)),
            (('Вписать в экран' if is_ru else 'Zoom to fit'), '⤢',
             act(self._cons_zoom_to_fit)),
            (('Сбросить масштаб (100%)' if is_ru else 'Reset zoom'), '↺',
             act(self._cons_zoom_reset)),
            (('Мини-карта вкл/выкл' if is_ru else 'Toggle minimap'), '🗺',
             act(self._cons_toggle_minimap)),
            (('Автораскладка схемы' if is_ru else 'Auto-layout'), '🕸',
             act(self._cons_open_layout_menu)),
            (('Запустить симуляцию' if is_ru else 'Run simulation'), '▶',
             act(self._cons_simulate)),
            (('События (сделай X при условии)' if is_ru
              else 'Events (do X when condition)'), '⚡',
             act(self._cons_open_events_manager)),
            (('Шпаргалка горячих клавиш' if is_ru else 'Hotkeys cheat-sheet'), '⌨',
             act(self._cons_show_hotkeys)),
        ]

        list_frame = tk.Frame(menu, bg=biosim_theme('bg'))
        list_frame.pack(fill='both', expand=True, padx=10, pady=4)

        def render(filter_text=''):
            for w in list_frame.winfo_children():
                w.destroy()
            ft = filter_text.lower().strip()
            shown = 0
            for label, icon, fn in actions:
                if ft and ft not in label.lower():
                    continue
                shown += 1
                b = tk.Button(list_frame, text='  {}  {}'.format(icon, label),
                               bg=biosim_theme('panel'), fg=biosim_theme('text'),
                               relief='flat', font=('Arial', 10), cursor='hand2',
                               anchor='w', pady=6, command=fn,
                               activebackground='#8250df', activeforeground='white')
                b.pack(fill='x', pady=1)
            if shown == 0:
                tk.Label(list_frame, text=('Ничего не найдено' if is_ru
                                            else 'Nothing found'),
                          bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                          font=('Arial', 10, 'italic')).pack(pady=20)

        render()
        try:
            search_var.trace_add('write', lambda *a: render(search_var.get()))
        except AttributeError:
            search_var.trace('w', lambda *a: render(search_var.get()))
        # Enter runs the first visible match
        def run_first(_=None):
            ft = search_var.get().lower().strip()
            for label, icon, fn in actions:
                if not ft or ft in label.lower():
                    fn()
                    return
        search_entry.bind('<Return>', run_first)

    def _cons_open_events_manager(self):
        """Manage discrete events: 'when <trigger> then <action>'. Events fire
        during simulation (e.g. 'A > 5' → 'B = 0'). TinkerCell-style events."""
        is_ru = (self.lang == 'ru')
        state = self.current_state['constructor']
        if state is None:
            return
        events = state.setdefault('events', [])
        node_ids = [n['id'] for n in state['nodes']]

        dlg = tk.Toplevel(self)
        dlg.title('События' if is_ru else 'Events')
        dlg.geometry('540x500')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text=('⚡ События модели' if is_ru else '⚡ Model events'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 13, 'bold')).pack(pady=(10, 2))
        tk.Label(dlg, text=('Когда УСЛОВИЕ станет истинным — выполнить ДЕЙСТВИЕ.\n'
                            'Условие: A > 5   ·   Действие: B = 0   (или B = A*2)\n'
                            'Доступны имена узлов и t (время).'
                            if is_ru else
                            'When CONDITION becomes true → run ACTION.\n'
                            'Condition: A > 5   ·   Action: B = 0   (or B = A*2)\n'
                            'Node names and t (time) are available.'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 8), justify='left').pack(padx=14, pady=(0, 6))
        if node_ids:
            tk.Label(dlg, text=('Узлы: ' if is_ru else 'Nodes: ') + ', '.join(node_ids[:12]),
                      bg=biosim_theme('bg'), fg='#0969da',
                      font=('Consolas', 8)).pack(padx=14, pady=(0, 4))

        list_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        list_frame.pack(fill='both', expand=True, padx=14, pady=4)

        def refresh_list():
            for w in list_frame.winfo_children():
                w.destroy()
            if not events:
                tk.Label(list_frame, text=('Событий пока нет' if is_ru else 'No events yet'),
                          bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                          font=('Arial', 10, 'italic')).pack(pady=20)
                return
            for i, ev in enumerate(events):
                row = tk.Frame(list_frame, bg=biosim_theme('panel'))
                row.pack(fill='x', pady=2)
                txt = 'когда  {}   →   {}'.format(ev.get('trigger', ''), ev.get('action', '')) \
                    if is_ru else \
                    'when  {}   →   {}'.format(ev.get('trigger', ''), ev.get('action', ''))
                tk.Label(row, text='⚡', bg=biosim_theme('panel'), fg='#9a6700',
                          font=('Arial', 11)).pack(side='left', padx=4)
                tk.Label(row, text=txt, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                          font=('Consolas', 10), anchor='w').pack(side='left', fill='x', expand=True)
                tk.Button(row, text='✕', bg='#cf222e', fg='white', relief='flat',
                           font=('Arial', 9, 'bold'), cursor='hand2', bd=0,
                           command=lambda idx=i: (events.pop(idx), refresh_list())
                           ).pack(side='right', padx=4)

        refresh_list()

        # Add-new row
        add_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        add_frame.pack(fill='x', padx=14, pady=(4, 2))
        tk.Label(add_frame, text=('Условие:' if is_ru else 'Condition:'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9)).grid(row=0, column=0, sticky='w')
        trig_var = tk.StringVar()
        tk.Entry(add_frame, textvariable=trig_var, bg=biosim_theme('panel2'),
                  fg=biosim_theme('text'), relief='flat', font=('Consolas', 10),
                  width=18, highlightthickness=1,
                  highlightbackground='#8250df').grid(row=0, column=1, padx=4, pady=2)
        tk.Label(add_frame, text=('Действие:' if is_ru else 'Action:'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9)).grid(row=0, column=2, sticky='w')
        act_var = tk.StringVar()
        tk.Entry(add_frame, textvariable=act_var, bg=biosim_theme('panel2'),
                  fg=biosim_theme('text'), relief='flat', font=('Consolas', 10),
                  width=18, highlightthickness=1,
                  highlightbackground='#8250df').grid(row=0, column=3, padx=4, pady=2)

        def add_event():
            trig = trig_var.get().strip()
            action = act_var.get().strip()
            if not trig or not action:
                return
            # Validate with dummy env
            try:
                env = {nid: 1.0 for nid in node_ids}
                env['t'] = 0.0
                eval(trig, {'__builtins__': {}}, env)
            except Exception as ex:
                messagebox.showerror('VIREON',
                                     ('Ошибка в условии: {}'.format(ex) if is_ru
                                      else 'Condition error: {}'.format(ex)))
                return
            events.append({'trigger': trig, 'action': action, 'once': True})
            trig_var.set(''); act_var.set('')
            refresh_list()

        tk.Button(dlg, text=('➕ Добавить событие' if is_ru else '➕ Add event'),
                   bg='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=5,
                   command=add_event).pack(fill='x', padx=14, pady=(2, 4))
        tk.Label(dlg, text=('События применяются при следующей симуляции'
                            if is_ru else 'Events apply on the next simulation'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 8, 'italic')).pack(pady=(0, 8))

