    def _cons_toggle_grid(self):
        """Show or hide the alignment grid on the constructor canvas.

        The settings menu offered this entry only when the method existed, so
        until now the option simply never appeared.
        """
        self._cons_show_grid = not getattr(self, '_cons_show_grid', False)
        try:
            self._cons_draw_diagram()
        except Exception as exc:
            biosim_log('warn', '_cons_toggle_grid redraw: {}'.format(exc))
        try:
            Toast(self, ('Сетка включена' if self._cons_show_grid else
                         'Сетка выключена') if self.lang == 'ru' else
                        ('Grid on' if self._cons_show_grid else 'Grid off'))
        except Exception as exc:
            biosim_log('info', '_cons_toggle_grid toast: {}'.format(exc))

    def _cons_draw_grid_background(self):
        """Draw the grid underneath everything else, if it is switched on."""
        if not getattr(self, '_cons_show_grid', False):
            return
        c = getattr(self, 'cons_canvas', None)
        if c is None:
            return
        w = c.winfo_width() or 800
        h = c.winfo_height() or 500
        step = 25
        col = biosim_theme('border')
        for x in range(0, int(w) + step, step):
            c.create_line(x, 0, x, h, fill=col, tags='grid')
        for y in range(0, int(h) + step, step):
            c.create_line(0, y, w, y, fill=col, tags='grid')
        c.tag_lower('grid')

    def _cons_toggle_language(self):
        """Switch this window between Russian and English and rebuild it."""
        self.lang = 'en' if self.lang == 'ru' else 'ru'
        try:
            self.title(self._t('title'))
        except Exception as exc:
            biosim_log('info', '_cons_toggle_language title: {}'.format(exc))
        try:
            self._build_tabs()
        except Exception as exc:
            biosim_log('error', '_cons_toggle_language rebuild: {}'.format(exc))

    def _cons_open_settings_menu(self):
        """Three-dots settings popup — quick access to existing options."""
        is_ru = (self.lang == 'ru')
        menu = tk.Menu(self, tearoff=0)
        # Language toggle
        menu.add_command(
            label=('Язык: Русский / English' if is_ru else 'Language: English / Русский'),
            command=lambda: self._cons_toggle_language() if hasattr(self, '_cons_toggle_language') else None)
        menu.add_separator()
        # Grid / snap toggles if they exist
        if hasattr(self, '_cons_toggle_grid'):
            menu.add_command(label=('Показать/скрыть сетку' if is_ru else 'Toggle grid'),
                             command=self._cons_toggle_grid)
        # Manual / help
        if hasattr(self, '_cons_open_manual'):
            menu.add_command(label=('Инструкция' if is_ru else 'Manual'),
                             command=self._cons_open_manual)
        # Log console
        if hasattr(self, '_open_log_console'):
            menu.add_command(label=('Лог-консоль' if is_ru else 'Log console'),
                             command=self._open_log_console)
        menu.add_separator()
        menu.add_command(label=('О программе' if is_ru else 'About'),
                         command=lambda: messagebox.showinfo('VIREON',
                             'VIREON — SynBio Constructor\n' +
                             ('Единый инструмент синтетической биологии' if is_ru
                              else 'All-in-one synthetic biology tool')))
        try:
            x = self.winfo_pointerx(); y = self.winfo_pointery()
            menu.tk_popup(x, y)
        finally:
            menu.grab_release()

