        sb = tk.Scrollbar(container, orient='vertical', command=canv.yview)
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')
        inner = tk.Frame(canv, bg=biosim_theme('bg'))
        inner.bind('<Configure>',
                    lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=inner, anchor='nw', width=600)

        # Enable mouse wheel scrolling (important — categories can be below the fold!)
        def _on_mousewheel(event):
            # Cross-platform: Windows/Mac use event.delta, Linux uses Button-4/5
            if event.delta:
                canv.yview_scroll(-1 * int(event.delta / 120), 'units')
            elif event.num == 4:
                canv.yview_scroll(-1, 'units')
            elif event.num == 5:
                canv.yview_scroll(1, 'units')
        canv.bind_all('<MouseWheel>', _on_mousewheel)
        canv.bind_all('<Button-4>', _on_mousewheel)
        canv.bind_all('<Button-5>', _on_mousewheel)
        # Unbind when window closes to avoid affecting other windows
        menu.bind('<Destroy>', lambda e: (canv.unbind_all('<MouseWheel>'),
                                           canv.unbind_all('<Button-4>'),
                                           canv.unbind_all('<Button-5>')) if e.widget == menu else None)

        # Build each category as collapsible section
