    def _cons_export_pdf_report(self):
        """Export a professional PDF report of the circuit + last simulation."""
        from tkinter import filedialog
        filepath = filedialog.asksaveasfilename(
            defaultextension='.pdf',
            filetypes=[('PDF report', '*.pdf'), ('All files', '*.*')])
        if not filepath:
            return
        state = self.current_state['constructor']
        # Use last simulation if available, else run a quick one
        t = y = None; node_ids = []
        try:
            t, y, node_ids = run_ode_simulation(state['nodes'], state['edges'],
                                                 state['init'], t_end=100)
        except Exception as _exc:
            biosim_log('warn', '_cons_export_pdf_report: {}'.format(_exc))
        ok, msg = export_simulation_to_pdf_report(
            state, t, y, node_ids, filepath,
            title=state.get('name', 'Circuit'), lang=self.lang)
        if ok:
            messagebox.showinfo('VIREON', self._t('export_done') + '\n' + msg)
        else:
            messagebox.showerror('VIREON', self._t('export_failed') + ' ' + msg)

    def _cons_export_sbol_file(self):
        """Export current state to SBOL file."""
