    def _show_tour_step(self):
        """Show current onboarding step as a floating bubble."""
        if not hasattr(self, '_tour_step') or self._tour_step >= len(self._tour_steps):
            return
        step = self._tour_steps[self._tour_step]
        # Close previous bubble
        if hasattr(self, '_tour_bubble') and self._tour_bubble is not None:
            try: self._tour_bubble.destroy()
            except Exception as _exc:
                biosim_log('warn', '_show_tour_step: {}'.format(_exc))
                pass
        bubble = tk.Toplevel(self)
        self._tour_bubble = bubble
        bubble.title('VIREON Tour')
        bubble.geometry('480x320')
        bubble.configure(bg=biosim_theme('bg'))
        bubble.transient(self)
        bubble.resizable(False, False)
        # Position
        try:
            self.update_idletasks()
            if step['pos'] == 'center':
                x = self.winfo_rootx() + self.winfo_width() // 2 - 240
                y = self.winfo_rooty() + self.winfo_height() // 2 - 160
            elif step['pos'] == 'right':
                x = self.winfo_rootx() + self.winfo_width() - 500
                y = self.winfo_rooty() + 100
            else:
                x = self.winfo_rootx() + self.winfo_width() // 2 - 240
                y = self.winfo_rooty() + 100
            bubble.geometry('+{}+{}'.format(max(0, x), max(0, y)))
        except Exception as _exc:
            biosim_log('warn', '_show_tour_step: {}'.format(_exc))

        # Border accent
        outer = tk.Frame(bubble, bg='#0969da')
        outer.pack(fill='both', expand=True, padx=0, pady=0)
        inner = tk.Frame(outer, bg=biosim_theme('bg'))
        inner.pack(fill='both', expand=True, padx=3, pady=3)

        # Title
        tk.Label(inner, text=step['title'],
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 15, 'bold')).pack(pady=(20, 10))

        # Text
        tk.Label(inner, text=step['text'],
                  bg=biosim_theme('bg'), fg=biosim_theme('text'),
                  font=('Arial', 11), wraplength=420,
                  justify='center').pack(pady=10, padx=20)

        # Step indicator
        step_lbl = '{} / {}'.format(self._tour_step + 1, len(self._tour_steps))
        tk.Label(inner, text=step_lbl,
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9, 'italic')).pack(pady=4)

        # Buttons
        btn_row = tk.Frame(inner, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=20, pady=14)

        if self._tour_step > 0:
            tk.Button(btn_row, text=('Назад' if self.lang == 'ru' else 'Back'),
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       font=('Arial', 10, 'bold'), cursor='hand2',
                       padx=14, pady=6,
                       command=self._tour_prev).pack(side='left')

        tk.Button(btn_row, text=('Закрыть' if self.lang == 'ru' else 'Close'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2',
                   padx=14, pady=6,
                   command=self._tour_close).pack(side='left', padx=8)

        if self._tour_step < len(self._tour_steps) - 1:
            tk.Button(btn_row, text=('Далее' if self.lang == 'ru' else 'Next') + ' ',
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       font=('Arial', 10, 'bold'), cursor='hand2',
                       padx=18, pady=6,
                       command=self._tour_next).pack(side='right')
        else:
            tk.Button(btn_row, text=('Готово' if self.lang == 'ru' else 'Done'),
                       bg='#1a7f37', highlightbackground='#1a7f37', fg='#f5f7fa', relief='flat',
                       font=('Arial', 10, 'bold'), cursor='hand2',
                       padx=18, pady=6,
                       command=self._tour_close).pack(side='right')

    def _tour_next(self):
        self._tour_step += 1
        self._show_tour_step()

    def _tour_prev(self):
        self._tour_step = max(0, self._tour_step - 1)
        self._show_tour_step()

    def _tour_close(self):
        if hasattr(self, '_tour_bubble') and self._tour_bubble is not None:
            try: self._tour_bubble.destroy()
            except Exception as _exc:
                biosim_log('warn', '_tour_close: {}'.format(_exc))
                pass
        self._tour_bubble = None

    def _cons_open_manual(self):
        """Open user manual (shared with main window)."""
        dlg = tk.Toplevel(self)
        dlg.title('' + ('Инструкция пользования' if self.lang == 'ru'
                              else 'User Manual'))
        dlg.geometry('900x700')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        # ─── Top bar ───
        top = tk.Frame(dlg, bg=biosim_theme('panel'), height=50)
        top.pack(fill='x')
        top.pack_propagate(False)
        tk.Label(top, text='VIREON — ' + ('Инструкция' if self.lang == 'ru' else 'Manual'),
                  bg=biosim_theme('panel'), fg='#0969da',
                  font=('Arial', 16, 'bold')).pack(side='left', padx=14, pady=10)
        tk.Label(top, text='v 5.0',
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(side='left', pady=14)

        # ─── Two columns: TOC + content ───
        main = tk.Frame(dlg, bg=biosim_theme('bg'))
        main.pack(fill='both', expand=True)

        toc_frame = tk.Frame(main, bg=biosim_theme('panel'), width=210)
        toc_frame.pack(side='left', fill='y')
        toc_frame.pack_propagate(False)
        tk.Label(toc_frame, text=('Содержание' if self.lang == 'ru'
                                              else 'Contents'),
                  bg=biosim_theme('panel'), fg='#1a7f37',
                  font=('Arial', 11, 'bold'),
                  padx=14, pady=10).pack(anchor='w')

        content_outer = tk.Frame(main, bg=biosim_theme('bg'))
        content_outer.pack(side='right', fill='both', expand=True)
        content_sb = tk.Scrollbar(content_outer)
        content_sb.pack(side='right', fill='y')
        content = tk.Text(content_outer, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                            font=('Arial', 11), relief='flat',
                            wrap='word', padx=24, pady=16,
                            yscrollcommand=content_sb.set,
                            cursor='arrow')
        content.pack(side='left', fill='both', expand=True)
        content_sb.config(command=content.yview)

        # Tags
        content.tag_config('h1', foreground='#0969da',
                              font=('Arial', 18, 'bold'),
                              spacing1=10, spacing3=8)
        content.tag_config('h3', foreground='#9a6700',
                              font=('Arial', 12, 'bold'),
                              spacing1=8, spacing3=4)
        content.tag_config('body', foreground=biosim_theme('text'),
                              font=('Arial', 11))
        content.tag_config('code', foreground='#bc4c00',
                              font=('Courier', 10),
                              background='#ffffff')
        content.tag_config('step', foreground='#1a7f37',
                              font=('Arial', 11),
                              lmargin1=20, lmargin2=20)
        content.tag_config('warn', foreground='#cf222e',
                              font=('Arial', 11),
                              lmargin1=20, lmargin2=20)
        content.tag_config('tip', foreground='#8250df',
                              font=('Arial', 11, 'italic'),
                              lmargin1=20, lmargin2=20)

        is_ru = (self.lang == 'ru')
        sections = self._synbio_manual_sections(is_ru)

        def show_section(key):
            content.config(state='normal')
            content.delete('1.0', 'end')
            if key in sections:
                for tag, text in sections[key]:
                    content.insert('end', text + '\n', tag)
            content.config(state='disabled')

        # TOC buttons (focused on SynBio features)
        toc_items = [
            ('intro',      '' + ('О Constructor' if is_ru else 'About Constructor')),
            ('quickstart', '' + ('Быстрый старт' if is_ru else 'Quick start')),
            ('parts',      '' + ('Части и узлы' if is_ru else 'Parts & nodes')),
            ('presets',    '' + ('Пресеты' if is_ru else 'Presets')),
            ('simulation', '▶' + ('Симуляция' if is_ru else 'Simulation')),
            ('analysis',   '' + ('Анализ' if is_ru else 'Analysis')),
            ('ai_motifs',  'AI Copilot'),
            ('animation',  '' + ('Анимация' if is_ru else 'Animation')),
            ('fitting',    '' + ('Подгонка' if is_ru else 'Fitting')),
            ('export',     '' + ('Экспорт' if is_ru else 'Export')),
            ('tutorials',  '' + ('Туториалы' if is_ru else 'Tutorials')),
            ('hotkeys',    '⌨' + ('Клавиши' if is_ru else 'Hotkeys')),
            ('faq',        'FAQ'),
        ]

        for key, label in toc_items:
            tk.Button(toc_frame, text=label,
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       font=('Arial', 10), cursor='hand2',
                       anchor='w', padx=14, pady=6,
                       command=lambda k=key: show_section(k)
                       ).pack(fill='x', padx=4, pady=1)

        # Bottom
        bottom = tk.Frame(dlg, bg=biosim_theme('bg'))
        bottom.pack(fill='x', padx=14, pady=8)

        def export_manual():
            from tkinter import filedialog
            filepath = filedialog.asksaveasfilename(
                title='Save SynBio manual',
                defaultextension='.md',
                initialfile='SynBio_Manual.md',
                filetypes=[('Markdown', '*.md'), ('HTML', '*.html')])
            if not filepath:
                return
            try:
                if filepath.endswith('.html'):
                    text = self._synbio_manual_html(is_ru)
                else:
                    text = self._synbio_manual_markdown(is_ru)
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(text)
                self.toast('Saved · ' + filepath, level='success', duration=2500)
            except Exception as e:
                biosim_log('warn', 'export_manual: {}'.format(e))
                self.toast('Save error: ' + str(e)[:60], level='error')

        tk.Button(bottom, text=('Экспорт MD/HTML' if is_ru else 'Export MD/HTML'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   padx=12, pady=4, command=export_manual
                   ).pack(side='left', padx=2)

        tk.Button(bottom, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2',
                   padx=12, pady=4,
                   command=dlg.destroy).pack(side='right', padx=2)

        show_section('intro')

