    def _synbio_manual_markdown(self, is_ru):
        """Convert SynBio manual to markdown."""
        sections = self._synbio_manual_sections(is_ru)
        out = ['# SynBio Constructor — ' + ('Руководство' if is_ru else 'Manual'),
                '', '*v 5.0*', '']
        order = ['intro', 'quickstart', 'parts', 'presets', 'simulation',
                  'analysis', 'ai_motifs', 'animation', 'fitting',
                  'export', 'tutorials', 'hotkeys', 'faq']
        for key in order:
            if key not in sections:
                continue
            for tag, text in sections[key]:
                if tag == 'h1':
                    out.append('\n## ' + text + '\n')
                elif tag == 'h3':
                    out.append('\n### ' + text + '\n')
                elif tag == 'code':
                    out.append('```\n' + text + '\n```')
                elif tag == 'step':
                    out.append('> ' + text.replace('\n', '\n> '))
                elif tag == 'warn':
                    out.append('> ' + text)
                elif tag == 'tip':
                    out.append('> ' + text)
                else:
                    out.append(text)
                out.append('')
        return '\n'.join(out)

    def _synbio_manual_html(self, is_ru):
        """Convert SynBio manual to HTML."""
        sections = self._synbio_manual_sections(is_ru)
        css = ('body { background:#f5f7fa; color:#1c2128; font-family:Arial,sans-serif; '
                'max-width:900px; margin:0 auto; padding:30px; line-height:1.7; } '
                'h1 { color:#0969da; border-bottom:2px solid #d0d7de; } '
                'h2 { color:#1a7f37; margin-top:30px; } '
                'h3 { color:#9a6700; } '
                'code { background:#ffffff; padding:3px 8px; border-radius:4px; color:#bc4c00; '
                'font-family:Monaco,monospace; } '
                'pre { background:#ffffff; padding:14px; border-radius:6px; overflow-x:auto; '
                'border-left:4px solid #0969da; } '
                'blockquote { border-left:4px solid #8250df; padding:8px 16px; '
                'background:#ffffff; margin:14px 0; } '
                '.tip { background:#1f2d1f; border-left:4px solid #1a7f37; padding:12px; '
                'border-radius:4px; margin:12px 0; color:#b3ffcc; }')
        out = ['<!DOCTYPE html><html><head><meta charset="UTF-8">',
                '<title>SynBio Manual</title>',
                '<style>' + css + '</style></head><body>',
                '<h1>SynBio Constructor — ' + ('Руководство' if is_ru else 'Manual') + '</h1>',
                '<p><em>v 5.0</em></p>']
        order = ['intro', 'quickstart', 'parts', 'presets', 'simulation',
                  'analysis', 'ai_motifs', 'animation', 'fitting',
                  'export', 'tutorials', 'hotkeys', 'faq']
        for key in order:
            if key not in sections:
                continue
            for tag, text in sections[key]:
                if tag == 'h1':
                    out.append('<h2>' + text + '</h2>')
                elif tag == 'h3':
                    out.append('<h3>' + text + '</h3>')
                elif tag == 'code':
                    out.append('<pre><code>' + text + '</code></pre>')
                elif tag == 'step':
                    out.append('<blockquote>' + text.replace('\n', '<br>') + '</blockquote>')
                elif tag == 'tip':
                    out.append('<div class="tip">' + text.replace('\n', '<br>') + '</div>')
                else:
                    out.append('<p>' + text.replace('\n', '<br>') + '</p>')
        out.append('</body></html>')
        return '\n'.join(out)

