    def _cons_import_genbank(self):
        """Open file dialog and import GenBank file."""
        if not _ensure_biopython():
            messagebox.showwarning('VIREON', self._t('biopython_not_installed'))
            return
        from tkinter import filedialog
        filepath = filedialog.askopenfilename(
            title=self._t('genbank_import_title'),
            filetypes=[('GenBank files', '*.gb *.gbk *.genbank'), ('All files', '*.*')])
        if not filepath:
            return
        new_state, msg = parse_genbank_to_circuit(filepath)
        if new_state is None:
            messagebox.showerror('VIREON', msg)
            return
        self._save_history('constructor')
        self.current_state['constructor'] = new_state
        self._cons_refresh()
        # Detailed info dialog
        info_msg = '{}\n\n{}: {}\n{}: {}'.format(
            self._t('genbank_imported'),
            self._t('genbank_features'), len(new_state['nodes']),
            self._t('genbank_size'), new_state.get('genbank_length', 0))
        messagebox.showinfo('VIREON', info_msg + '\n\n' + msg)

    def _cons_ncbi_search_dialog(self):
        """Open NCBI gene search dialog."""
        if not _ensure_biopython():
            messagebox.showwarning('VIREON', self._t('biopython_not_installed'))
            return

        dlg = tk.Toplevel(self)
        dlg.title(self._t('ncbi_search_title'))
        dlg.geometry('640x540')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('ncbi_search_title'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 8))

        # Gene name input
        tk.Label(dlg, text=self._t('ncbi_gene_name'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(anchor='w', padx=14)
        name_var = tk.StringVar(value='TP53')
        tk.Entry(dlg, textvariable=name_var, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  insertbackground='#1c2128', relief='flat', font=('Arial', 11),
                  highlightthickness=1, highlightbackground=biosim_theme('border')
                  ).pack(fill='x', padx=14, pady=(2, 8), ipady=3)

        # Organism input
        tk.Label(dlg, text=self._t('ncbi_organism'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(anchor='w', padx=14)
        org_var = tk.StringVar(value='Homo sapiens')
        org_combo = ttk.Combobox(dlg, textvariable=org_var,
                                   values=['Homo sapiens', 'Escherichia coli',
                                            'Saccharomyces cerevisiae', 'Mus musculus',
                                            'Drosophila melanogaster', 'Bacillus subtilis',
                                            'Arabidopsis thaliana'],
                                   font=('Arial', 10))
        org_combo.pack(fill='x', padx=14, pady=(2, 8))

        # Status
        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                                font=('Arial', 10, 'italic'))
        status_lbl.pack(padx=14, pady=4)

        # Result text
        result_frame = tk.LabelFrame(dlg, text='', bg=biosim_theme('panel'),
                                       fg='#1a7f37', font=('Arial', 10, 'bold'),
                                       relief='flat')
        result_frame.pack(fill='both', expand=True, padx=14, pady=4)
        result_txt = scrolledtext.ScrolledText(result_frame, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                                                  font=('Courier', 9), relief='flat',
                                                  wrap='word', highlightthickness=0)
        result_txt.pack(fill='both', expand=True, padx=4, pady=4)

        # Hold the loaded sequence
        loaded_data = {'sequence': '', 'info': None}

        def do_search():
            gname = name_var.get().strip()
            org = org_var.get().strip()
            if not gname:
                status_lbl.config(text='Введи имя гена' if self.lang == 'ru' else 'Enter gene name',
                                   fg='#cf222e')
                return
            status_lbl.config(text=self._t('ncbi_searching'), fg='#9a6700')
            dlg.update()

            def worker():
                info, msg = fetch_ncbi_gene_via_biopython(gname, org)
                def done():
                    if info is None:
                        status_lbl.config(text=msg, fg='#cf222e')
                        result_txt.delete('1.0', 'end')
                    else:
                        loaded_data['sequence'] = info['sequence']
                        loaded_data['info'] = info
                        status_lbl.config(text=self._t('ncbi_loaded').format(
                            info['length'], info['organism']), fg='#1a7f37')
                        result_txt.delete('1.0', 'end')
                        result_txt.insert('end', 'Gene: {}\n'.format(info['gene']))
                        result_txt.insert('end', 'Organism: {}\n'.format(info['organism']))
                        result_txt.insert('end', 'NCBI ID: {}\n'.format(info['ncbi_id']))
                        result_txt.insert('end', 'Length: {} bp\n\n'.format(info['length']))
                        result_txt.insert('end', info['header'] + '\n\n')
                        seq = info['sequence']
                        # Format in 60-char lines
                        for i in range(0, min(len(seq), 3000), 60):
                            result_txt.insert('end', seq[i:i+60] + '\n')
                        if len(seq) > 3000:
                            result_txt.insert('end', '\n... and {} more bp\n'.format(len(seq) - 3000))
                self.after(0, done)
            threading.Thread(target=worker, daemon=True).start()

        def copy_to_clipboard():
            seq = loaded_data.get('sequence', '')
            if seq:
                self.clipboard_clear()
                self.clipboard_append(seq)
                status_lbl.config(text='Copied!' if self.lang == 'en' else 'Скопировано!',
                                   fg='#1a7f37')

        # Buttons
        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=8)
        tk.Button(btn_row, text=self._t('ncbi_search'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=4,
                   command=do_search).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('ncbi_copy_to_clipboard'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=copy_to_clipboard).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy).pack(side='right', padx=2)

    def _cons_open_3d_molecule(self):
        """Open the 3D Molecule Viewer window (from Tools menu)."""
        Open3DMoleculeWindow(self, lang=self.lang)

    def _cons_open_preset_library(self):
        """Show library of classical biology pathways."""
        dlg = tk.Toplevel(self)
        dlg.title(self._t('preset_lib_title'))
        dlg.geometry('760x600')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('preset_lib_title'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 16, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=self._t('preset_lib_subtitle'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(pady=(0, 8))

        # Scrollable list
        list_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        list_frame.pack(fill='both', expand=True, padx=14, pady=4)
        canv = tk.Canvas(list_frame, bg=biosim_theme('bg'), highlightthickness=0)
        sb = tk.Scrollbar(list_frame, orient='vertical', command=canv.yview)
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')
        inner = tk.Frame(canv, bg=biosim_theme('bg'))
        inner.bind('<Configure>',
                    lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=inner, anchor='nw', width=720)

        def load_preset(key):
            import copy
            preset = SCIENTIFIC_PRESETS.get(key)
            if not preset:
                return
            self._save_history('constructor')
            # Build state from preset
            new_state = {
                'name': preset.get('name_ru' if self.lang == 'ru' else 'name_en', key),
                'description': preset.get('desc_ru' if self.lang == 'ru' else 'desc_en', ''),
                'nodes': copy.deepcopy(preset['nodes']),
                'edges': copy.deepcopy(preset['edges']),
                'init': copy.deepcopy(preset['init']),
                'chains': [],
            }
            self.current_state['constructor'] = new_state
            self._cons_refresh()
            biosim_log('success', 'Loaded preset: ' + key)
            dlg.destroy()
            self._cons_status_lbl.config(
                text=(preset.get('name_ru' if self.lang == 'ru' else 'name_en')),
                fg='#1a7f37')

        # List each preset as a card
        colors = ['#0969da', '#1a7f37', '#9a6700', '#cf222e', '#8250df',
                   '#0969da', '#0550ae', '#8250df', '#bc4c00', '#c0c0c0']
        for i, (pkey, pdata) in enumerate(SCIENTIFIC_PRESETS.items()):
            color = colors[i % len(colors)]
            card = tk.Frame(inner, bg=biosim_theme('panel'), highlightthickness=1,
                              highlightbackground=color)
            card.pack(fill='x', padx=2, pady=4)
            # Title
            name = pdata.get('name_ru' if self.lang == 'ru' else 'name_en', pkey)
            tk.Label(card, text=name, bg=biosim_theme('panel'), fg=color,
                      font=('Arial', 12, 'bold'),
                      anchor='w').pack(fill='x', padx=10, pady=(6, 0))
            # Description
            desc = pdata.get('desc_ru' if self.lang == 'ru' else 'desc_en', '')
            tk.Label(card, text=desc, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                      font=('Arial', 9), wraplength=600,
                      anchor='w', justify='left').pack(fill='x', padx=10, pady=(2, 2))
            # Meta row
            meta = tk.Frame(card, bg=biosim_theme('panel'))
            meta.pack(fill='x', padx=10, pady=(2, 6))
            tk.Label(meta, text=self._t('preset_organism') + ' ' + pdata.get('organism', '?'),
                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'), font=('Arial', 9)).pack(side='left')
            tk.Label(meta, text='  ·  ' + self._t('preset_reference') + ' ' +
                      pdata.get('reference', '?'),
                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'), font=('Arial', 9, 'italic')).pack(side='left')
            tk.Label(meta, text='  ·  ' + str(len(pdata['nodes'])) + ' nodes, ' +
                      str(len(pdata['edges'])) + ' edges',
                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'), font=('Arial', 9)).pack(side='left')
            # Load button
            tk.Button(card, text='' + self._t('preset_load'),
                       bg=color, fg='white', relief='flat',
                       font=('Arial', 9, 'bold'), cursor='hand2', pady=3, padx=14,
                       command=lambda k=pkey: load_preset(k)
                       ).pack(side='right', padx=10, pady=(0, 6))

        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy
                   ).pack(fill='x', padx=14, pady=(4, 10))

    def _cons_open_fitting_dialog(self):
        """Parameter fitting to experimental data."""
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return
        if not state.get('wetlab_data'):
            messagebox.showwarning('VIREON', self._t('fit_no_data'))
            return

        dlg = tk.Toplevel(self)
        dlg.title(self._t('fit_title'))
        dlg.geometry('640x600')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('fit_title'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=self._t('fit_pick_params'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(pady=4)

        # Build checkbox list of fittable params
        scroll = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                              height=15, relief='flat',
                                              font=('Courier', 9), highlightthickness=0)
        params_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        params_frame.pack(fill='both', expand=True, padx=14, pady=4)

        canv = tk.Canvas(params_frame, bg=biosim_theme('bg'), highlightthickness=0)
        sb = tk.Scrollbar(params_frame, orient='vertical', command=canv.yview)
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')
        param_box = tk.Frame(canv, bg=biosim_theme('bg'))
        param_box.bind('<Configure>',
                        lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=param_box, anchor='nw', width=600)

        # Params: production and degradation of each node, strength of each edge
        param_vars = []
        for n in state['nodes']:
            for ptype, color in [('production', '#1a7f37'), ('degradation', '#cf222e')]:
                v = tk.BooleanVar(value=False)
                cb_frame = tk.Frame(param_box, bg=biosim_theme('panel'))
                cb_frame.pack(fill='x', pady=1, padx=2)
                tk.Checkbutton(cb_frame, variable=v,
                                bg=biosim_theme('panel'), activebackground='#ffffff',
                                selectcolor='#eef1f5').pack(side='left')
                tk.Label(cb_frame,
                          text='{:>12} · {:11} = {:.3f}'.format(
                              n['id'][:12], ptype, n.get(ptype, 1.0)),
                          bg=biosim_theme('panel'), fg=color, font=('Courier', 10)
                          ).pack(side='left')
                param_vars.append({
                    'var': v, 'type': ptype, 'node': n['id'],
                    'initial': n.get(ptype, 1.0),
                })
        # Edge strengths
        for i, e in enumerate(state['edges']):
            v = tk.BooleanVar(value=False)
            cb_frame = tk.Frame(param_box, bg=biosim_theme('panel'))
            cb_frame.pack(fill='x', pady=1, padx=2)
            tk.Checkbutton(cb_frame, variable=v,
                            bg=biosim_theme('panel'), activebackground='#ffffff',
                            selectcolor='#eef1f5').pack(side='left')
            tk.Label(cb_frame,
                      text='Edge {:>2}: {} {} · strength = {:.2f}'.format(
                          i, e['from'][:8], e['to'][:8], e.get('strength', 3.0)),
                      bg=biosim_theme('panel'), fg='#8250df', font=('Courier', 10)
                      ).pack(side='left')
            param_vars.append({
                'var': v, 'type': 'strength', 'edge_idx': i,
                'initial': e.get('strength', 3.0),
            })

        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg='#9a6700',
                                font=('Arial', 10, 'italic'))
        status_lbl.pack(pady=4)

        def run_fit():
            selected = [p for p in param_vars if p['var'].get()]
            if not selected:
                status_lbl.config(text='Выбери хотя бы 1 параметр' if self.lang == 'ru'
                                    else 'Pick at least 1 parameter', fg='#cf222e')
                return
            if len(selected) > 10:
                status_lbl.config(text='Максимум 10 параметров', fg='#cf222e')
                return
            status_lbl.config(text=self._t('fit_running'), fg='#9a6700')
            dlg.update()
            biosim_log('info', 'Starting parameter fit with {} params'.format(len(selected)))
            fitted, residual, msg = fit_parameters_to_data(
                state, state['wetlab_data'], selected, t_end=100)
            if fitted is None:
                status_lbl.config(text='' + msg, fg='#cf222e')
                return
            # Show results in new window
            self._cons_show_fit_results(fitted, residual, msg, dlg, selected)

        tk.Button(dlg, text='▶ ' + self._t('adv_run'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=run_fit
                   ).pack(fill='x', padx=14, pady=8)
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy
                   ).pack(fill='x', padx=14, pady=(0, 10))

    def _cons_show_fit_results(self, fitted, residual, msg, parent_dlg, selected_params):
        """Show fitting results with quality metrics and advanced analysis options."""
        rdlg = tk.Toplevel(parent_dlg)
        rdlg.title(self._t('fit_done'))
        rdlg.geometry('820x680')
        rdlg.configure(bg=biosim_theme('bg'))
        rdlg.transient(parent_dlg)

        tk.Label(rdlg, text='' + self._t('fit_done'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 14, 'bold')).pack(pady=(10, 4))
        tk.Label(rdlg, text=msg, bg=biosim_theme('bg'), fg='#0550ae',
                  font=('Arial', 10, 'italic')).pack(pady=2)

        # Compute quality metrics
        state = self.current_state['constructor']
        exp_data = state.get('wetlab_data', {})
        metrics = None
        try:
            # Run simulation with fitted params
            import copy
            sc = copy.deepcopy(state)
            for fp in fitted:
                if fp['type'] in ('production', 'degradation'):
                    for n in sc['nodes']:
                        if n['id'] == fp['node']:
                            n[fp['type']] = fp['fitted_value']
                            break
                elif fp['type'] == 'strength':
                    if 0 <= fp['edge_idx'] < len(sc['edges']):
                        sc['edges'][fp['edge_idx']]['strength'] = fp['fitted_value']
            
            # Get experimental data for metrics
            time_col = None
            for cname in exp_data.get('col_names', []):
                if cname.lower() in ('time', 't', 'час', 'hours', 'h'):
                    time_col = cname; break
            if time_col is None and exp_data.get('col_names'):
                time_col = exp_data['col_names'][0]
            
            if time_col:
                t_exp = np.array(exp_data['columns'][time_col], dtype=float)
                t_sim, y_sim, ids = run_ode_simulation(
                    sc['nodes'], sc['edges'], sc['init'],
                    t_end=max(100, float(t_exp[-1] * 1.1)))
                
                if t_sim is not None:
                    # Aggregate all matched data
                    all_exp = []
                    all_model = []
                    for col in exp_data['col_names']:
                        if col == time_col:
                            continue
                        for nid in ids:
                            if col.lower() == nid.lower() or col.lower() in nid.lower():
                                y_exp = np.array(exp_data['columns'][col], dtype=float)
                                i_node = ids.index(nid)
                                y_sim_at_t = np.interp(t_exp, t_sim, y_sim[:, i_node])
                                all_exp.extend(y_exp.tolist())
                                all_model.extend(y_sim_at_t.tolist())
                                break
                    if all_exp:
                        metrics = compute_fit_quality_metrics(
                            all_model, all_exp, len(fitted))
        except Exception as _exc:
            biosim_log('warn', '_cons_show_fit_results: {}'.format(_exc))

        # ── Quality metrics card ──
        if metrics:
            metrics_frame = tk.LabelFrame(rdlg,
                text=('Метрики качества подгонки' if self.lang == 'ru'
                              else 'Fit Quality Metrics'),
                bg=biosim_theme('bg'), fg='#0969da',
                font=('Arial', 11, 'bold'), relief='flat')
            metrics_frame.pack(fill='x', padx=14, pady=4)
            
            grid = tk.Frame(metrics_frame, bg=biosim_theme('bg'))
            grid.pack(padx=10, pady=6)
            
            # R² with color
            r2 = metrics['r_squared']
            r2_color = '#1a7f37' if r2 > 0.9 else ('#9a6700' if r2 > 0.7 else '#cf222e')
            r2_quality = ('отлично' if self.lang == 'ru' else 'excellent') if r2 > 0.95 \
                          else (('хорошо' if self.lang == 'ru' else 'good') if r2 > 0.8 \
                                 else ('плохо' if self.lang == 'ru' else 'poor'))
            
            def metric_row(row, label, value, fmt, color, info=''):
                tk.Label(grid, text=label, bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                          font=('Arial', 10), anchor='e', width=14).grid(row=row, column=0, padx=4, sticky='e')
                tk.Label(grid, text=fmt.format(value), bg=biosim_theme('bg'), fg=color,
                          font=('Courier', 11, 'bold'), anchor='w').grid(row=row, column=1, padx=4, sticky='w')
                tk.Label(grid, text=info, bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                          font=('Arial', 9, 'italic')).grid(row=row, column=2, padx=4, sticky='w')
            
            metric_row(0, 'R² (fit):', r2, '{:.4f}', r2_color, '' + r2_quality)
            metric_row(1, 'Adjusted R²:', metrics['adjusted_r2'], '{:.4f}', r2_color, 
                         '(penalizes params)')
            metric_row(2, 'RMSE:', metrics['rmse'], '{:.4f}', '#1c2128',
                         'lower = better')
            metric_row(3, 'MAE:', metrics['mae'], '{:.4f}', '#1c2128', '')
            metric_row(4, 'χ²:', metrics['chi_squared'], '{:.2f}', '#1c2128', '')
            metric_row(5, 'AIC:', metrics['aic'], '{:.2f}', '#8250df',
                         'compare models, lower better')
            metric_row(6, 'BIC:', metrics['bic'], '{:.2f}', '#8250df',
                         'Bayesian alternative')
            metric_row(7, 'N data points:', metrics['n_data'], '{}', '#1c2128', '')

        # Parameter results table
        params_frame = tk.LabelFrame(rdlg,
            text=('Подогнанные параметры' if self.lang == 'ru'
                          else 'Fitted Parameters'),
            bg=biosim_theme('bg'), fg='#1a7f37',
            font=('Arial', 11, 'bold'), relief='flat')
        params_frame.pack(fill='both', expand=True, padx=14, pady=4)
        
        txt = scrolledtext.ScrolledText(params_frame, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 10), relief='flat',
                                          highlightthickness=0, height=10)
        txt.pack(fill='both', expand=True, padx=4, pady=4)
        txt.insert('end', '{:>20} {:>10} {:>10} {:>12}\n'.format(
            'Parameter', self._t('fit_initial'), self._t('fit_fitted'),
            self._t('fit_change') + ' %'))
        txt.insert('end', '─' * 60 + '\n')
        for p in fitted:
            label = p['node'] if p['type'] != 'strength' else 'edge_' + str(p['edge_idx'])
            label += '·' + p['type'][:8]
            change_str = '{:+.1f}%'.format(p['change_percent'])
            line = '{:>20} {:>10.4f} {:>10.4f} {:>12}\n'.format(
                label[:20], p['initial_value'], p['fitted_value'], change_str)
            txt.insert('end', line)
        txt.config(state='disabled')

        def apply_fit():
            state = self.current_state['constructor']
            self._save_history('constructor')
            for p in fitted:
                if p['type'] in ('production', 'degradation'):
                    for n in state['nodes']:
                        if n['id'] == p['node']:
                            n[p['type']] = p['fitted_value']
                            break
                elif p['type'] == 'strength':
                    if 0 <= p['edge_idx'] < len(state['edges']):
                        state['edges'][p['edge_idx']]['strength'] = p['fitted_value']
            self._cons_refresh()
            biosim_log('success', 'Applied fitted parameters')
            self.toast('Fitted parameters applied', level='success')
            rdlg.destroy()
            parent_dlg.destroy()

        def run_identifiability():
            self.toast('Running identifiability analysis (may take 30-60 sec)...',
                        level='info', duration=2000)
            self.sb_progress_start()
            rdlg.update()
            try:
                results = identifiability_analysis(state, exp_data, selected_params)
            except Exception as e:
                biosim_log('warn', 'run_identifiability: {}'.format(e))
                self.sb_progress_stop()
                self.toast('Error: ' + str(e)[:80], level='error')
                return
            self.sb_progress_stop()
            if results is None:
                self.toast('Identifiability analysis failed', level='error')
                return
            self._show_identifiability_results(results, rdlg)

        def run_sobol():
            self.toast('Computing Sobol indices (may take 30 sec)...',
                        level='info', duration=2000)
            self.sb_progress_start()
            rdlg.update()
            try:
                results = sobol_sensitivity_indices(state, selected_params,
                                                       n_samples=40)
            except Exception as e:
                biosim_log('warn', 'run_sobol: {}'.format(e))
                self.sb_progress_stop()
                self.toast('Error: ' + str(e)[:80], level='error')
                return
            self.sb_progress_stop()
            if results is None:
                self.toast('Sobol failed', level='error')
                return
            self._show_sobol_results(results, rdlg)

        def run_bootstrap():
            self.toast('Running bootstrap (may take 1-2 min)...',
                        level='info', duration=3000)
            self.sb_progress_start()
            rdlg.update()
            try:
                results = bootstrap_fit_confidence(state, exp_data, selected_params,
                                                       n_bootstrap=15)
            except Exception as e:
                biosim_log('warn', 'run_bootstrap: {}'.format(e))
                self.sb_progress_stop()
                self.toast('Error: ' + str(e)[:80], level='error')
                return
            self.sb_progress_stop()
            if results is None:
                self.toast('Bootstrap failed', level='error')
                return
            self._show_bootstrap_results(results, rdlg)

        # ── Advanced analysis buttons ──
        adv_frame = tk.LabelFrame(rdlg,
            text=('Глубокий анализ' if self.lang == 'ru'
                          else 'Advanced Analysis'),
            bg=biosim_theme('bg'), fg='#8250df',
            font=('Arial', 10, 'bold'), relief='flat')
        adv_frame.pack(fill='x', padx=14, pady=4)
        
        adv_btns = tk.Frame(adv_frame, bg=biosim_theme('bg'))
        adv_btns.pack(pady=6)
        
        tk.Button(adv_btns, text='Identifiability',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   padx=12, pady=4, command=run_identifiability
                   ).pack(side='left', padx=3)
        Tooltip(adv_btns.winfo_children()[-1],
                'Проверить можно ли однозначно определить параметры'
                if self.lang == 'ru' else
                'Check if parameters can be uniquely determined')
        
        tk.Button(adv_btns, text='Sobol indices',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   padx=12, pady=4, command=run_sobol
                   ).pack(side='left', padx=3)
        Tooltip(adv_btns.winfo_children()[-1],
                'Глобальные индексы чувствительности по параметрам'
                if self.lang == 'ru' else
                'Global sensitivity indices for parameters')
        
        tk.Button(adv_btns, text='Bootstrap CI',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   padx=12, pady=4, command=run_bootstrap
                   ).pack(side='left', padx=3)
        Tooltip(adv_btns.winfo_children()[-1],
                '95% доверительные интервалы через bootstrap'
                if self.lang == 'ru' else
                '95% confidence intervals via bootstrap')

        # ── Apply / Close buttons ──
        btn_row = tk.Frame(rdlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=8)
        tk.Button(btn_row, text='Применить' if self.lang == 'ru' else 'Apply',
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=apply_fit
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=rdlg.destroy
                   ).pack(side='right', padx=2)

    def _show_identifiability_results(self, results, parent_dlg):
        """Show identifiability analysis results."""
        dlg = tk.Toplevel(parent_dlg)
        dlg.title('Identifiability Analysis')
        dlg.geometry('700x440')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(parent_dlg)
        
        tk.Label(dlg, text=('Анализ идентифицируемости' if self.lang == 'ru'
                                      else 'Identifiability Analysis'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text='Можно ли однозначно определить каждый параметр из данных?'
                  if self.lang == 'ru' else
                  'Can each parameter be uniquely determined from data?',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(pady=2)
        
        # Results table
        txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 10), relief='flat',
                                          highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=14, pady=8)
        
        n_identifiable = sum(1 for r in results if r['identifiable'])
        summary = '{}/{} parameters identifiable\n\n'.format(n_identifiable, len(results))
        txt.insert('end', summary, 'h2')
        txt.tag_config('h2', foreground='#1a7f37', font=('Arial', 11, 'bold'))
        
        txt.insert('end', '{:>22} {:>12} {:>12} {}\n'.format(
            'Parameter', 'Value', 'Status', 'Notes'))
        txt.insert('end', '─' * 70 + '\n')
        for r in results:
            status = 'IDENT.' if r['identifiable'] else 'NOT IDENT.'
            color_tag = 'ok' if r['identifiable'] else 'bad'
            txt.insert('end', '{:>22} {:>12.4f} '.format(
                r['name'][:22], r['fitted_value']))
            txt.insert('end', '{:>12} '.format(status), color_tag)
            txt.insert('end', '{}\n'.format(r['reason'][:25]))
        txt.tag_config('ok', foreground='#1a7f37', font=('Courier', 10, 'bold'))
        txt.tag_config('bad', foreground='#cf222e', font=('Courier', 10, 'bold'))
        txt.config(state='disabled')
        
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _show_sobol_results(self, results, parent_dlg):
        """Show Sobol sensitivity indices."""
        dlg = tk.Toplevel(parent_dlg)
        dlg.title('Sobol Indices')
        dlg.geometry('720x520')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(parent_dlg)
        
        tk.Label(dlg, text=('Индексы чувствительности (Sobol)' if self.lang == 'ru'
                                      else 'Sobol Sensitivity Indices'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text='S1 = первый порядок · ST = общий (с взаимодействиями)'
                  if self.lang == 'ru' else
                  'S1 = first-order · ST = total (with interactions)',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(pady=2)
        
        # Bar chart with matplotlib
        fig, ax = plt.subplots(figsize=(8, 4), facecolor='#f5f7fa')
        ax.set_facecolor('#ffffff')
        ax.tick_params(colors='#57606a')
        for sp in ax.spines.values(): sp.set_color('#d0d7de')
        
        names = list(results.keys())
        s1_vals = [results[n]['S1'] for n in names]
        st_vals = [results[n]['ST'] for n in names]
        
        x_pos = np.arange(len(names))
        width = 0.35
        ax.bar(x_pos - width/2, s1_vals, width, label='S1 (first-order)',
                color='#1a7f37', alpha=0.8)
        ax.bar(x_pos + width/2, st_vals, width, label='ST (total)',
                color='#0969da', alpha=0.8)
        ax.set_xticks(x_pos)
        ax.set_xticklabels([n[:15] for n in names], rotation=30, ha='right',
                              color='#1c2128')
        ax.set_ylabel('Sensitivity', color='#1c2128')
        ax.set_title('Global Sensitivity Indices', color='#1c2128')
        ax.set_ylim(0, 1.1)
        ax.legend(facecolor='#ffffff', edgecolor='#d0d7de',
                    labelcolor='#1c2128')
        ax.grid(True, color='#eef1f5', lw=0.5, axis='y')
        
        cv = FigureCanvasTkAgg(fig, master=dlg)
        cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
        
        # Text summary
        txt_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        txt_frame.pack(fill='x', padx=14, pady=4)
        for name in names:
            r = results[name]
            interaction = 'STRONG INTERACTIONS' if r['interactions'] > 0.1 else ''
            interp = 'CRITICAL' if r['ST'] > 0.5 else ('IMPORTANT' if r['ST'] > 0.2 else 'minor')
            line = '  • {}: S1={:.3f}, ST={:.3f}   {} {}'.format(
                name[:20], r['S1'], r['ST'], interp, interaction)
            tk.Label(txt_frame, text=line, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                      font=('Courier', 9), anchor='w').pack(anchor='w')
        
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _show_bootstrap_results(self, results, parent_dlg):
        """Show bootstrap confidence intervals."""
        dlg = tk.Toplevel(parent_dlg)
        dlg.title('Bootstrap CI')
        dlg.geometry('720x500')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(parent_dlg)
        
        tk.Label(dlg, text=('Bootstrap 95% доверительные интервалы' if self.lang == 'ru'
                                      else 'Bootstrap 95% Confidence Intervals'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text='Подгонка повторена на ресэмплированных данных'
                  if self.lang == 'ru' else
                  'Fit repeated on resampled data',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(pady=2)
        
        txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 10), relief='flat',
                                          highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=14, pady=8)
        
        txt.insert('end', '{:>22} {:>10} {:>10} {:>10} {:>10} {:>8}\n'.format(
            'Parameter', 'Mean', 'StDev', 'CI 2.5%', 'CI 97.5%', 'N'))
        txt.insert('end', '─' * 80 + '\n')
        for name, r in results.items():
            cv = r['std'] / max(r['mean'], 1e-9)  # coefficient of variation
            quality = '' if cv < 0.2 else ('!' if cv < 0.5 else '')
            txt.insert('end', '{} {:>22} {:>10.4f} {:>10.4f} {:>10.4f} {:>10.4f} {:>6}\n'.format(
                quality, name[:22], r['mean'], r['std'],
                r['ci_low'], r['ci_high'], r['n_samples']))
        txt.config(state='disabled')
        
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

