    def _cons_open_disease_search(self):
        """Search diseases treatable by synthetic biology + suggest gene circuits."""
        is_ru = (self.lang == 'ru')
        win = tk.Toplevel(self)
        win.title('' + ('Болезни для генной терапии' if is_ru else 'Diseases for gene therapy'))
        win.geometry('720x680')
        win.configure(bg=biosim_theme('bg'))
        win.transient(self)

        tk.Label(win, text=('Болезни, которые можно лечить синтетической биологией'
                                       if is_ru else 'Diseases treatable by synthetic biology'),
                  bg=biosim_theme('bg'), fg='#0969da', font=('Arial', 13, 'bold')).pack(pady=(12, 4))
        tk.Label(win, text=('Найди болезнь увидь подход построй генную цепь'
                              if is_ru else 'Find a disease see approach build a gene circuit'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9)).pack()

        # Search box
        search_frame = tk.Frame(win, bg=biosim_theme('bg'))
        search_frame.pack(fill='x', padx=16, pady=8)
        tk.Label(search_frame, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 12)).pack(side='left')
        search_var = tk.StringVar()
        search_entry = tk.Entry(search_frame, textvariable=search_var, bg=biosim_theme('panel2'),
                                 fg=biosim_theme('text'), relief='flat', font=('Arial', 11))
        search_entry.pack(side='left', fill='x', expand=True, padx=6, ipady=5)
        search_entry.focus_set()

        # Filter buttons
        filter_var = tk.StringVar(value='all')
        filt_frame = tk.Frame(win, bg=biosim_theme('bg'))
        filt_frame.pack(fill='x', padx=16, pady=(0, 6))
        tk.Label(filt_frame, text=('Показать:' if is_ru else 'Show:'), bg=biosim_theme('bg'),
                  fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left')
        for val, lbl in [('all', 'Все' if is_ru else 'All'),
                          ('high', '' + ('Высокая' if is_ru else 'High')),
                          ('medium', '' + ('Средняя' if is_ru else 'Medium'))]:
            tk.Radiobutton(filt_frame, text=lbl, variable=filter_var, value=val,
                            bg=biosim_theme('bg'), fg='#0969da', selectcolor='#eef1f5',
                            font=('Arial', 8), command=lambda: refresh()).pack(side='left', padx=4)

        # Results list (scrollable)
        list_container = tk.Frame(win, bg=biosim_theme('bg'))
        list_container.pack(fill='both', expand=True, padx=16, pady=6)
        canv = tk.Canvas(list_container, bg=biosim_theme('bg'), highlightthickness=0)
        sb = tk.Scrollbar(list_container, orient='vertical', command=canv.yview)
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')
        results_inner = tk.Frame(canv, bg=biosim_theme('bg'))
        results_inner.bind('<Configure>',
                            lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=results_inner, anchor='nw', width=660)

        # Mouse wheel scroll
        def _wheel(event):
            if event.delta:
                canv.yview_scroll(-1 * int(event.delta / 120), 'units')
            elif event.num == 4:
                canv.yview_scroll(-1, 'units')
            elif event.num == 5:
                canv.yview_scroll(1, 'units')
        canv.bind_all('<MouseWheel>', _wheel)
        canv.bind_all('<Button-4>', _wheel)
        canv.bind_all('<Button-5>', _wheel)
        win.bind('<Destroy>', lambda e: (canv.unbind_all('<MouseWheel>'),
                                          canv.unbind_all('<Button-4>'),
                                          canv.unbind_all('<Button-5>')) if e.widget == win else None)

        # Pre-classify all diseases from the main DB
        classified = []
        for dkey, dval in DB.items():
            rel = classify_synbio_relevance(dval)
            name = dval.get('ru' if is_ru else 'en', dkey)
            classified.append({'key': dkey, 'name': name, 'data': dval, 'rel': rel})
        # Sort by relevance score (high first)
        classified.sort(key=lambda x: -x['rel']['score'])

        cat_colors = {'high': '#1a7f37', 'medium': '#9a6700', 'low': '#57606a'}
        cat_icons = {'high': '', 'medium': '', 'low': ''}

        def refresh():
            for w in results_inner.winfo_children():
                w.destroy()
            query = search_var.get().lower().strip()
            filt = filter_var.get()
            shown = 0
            for item in classified:
                # Filter by category
                if filt != 'all' and item['rel']['category'] != filt:
                    continue
                # Filter by search query
                if query and query not in item['name'].lower():
                    # also search genes
                    genes_str = ' '.join(item['data'].get('genes', [])).lower()
                    if query not in genes_str:
                        continue
                # Skip low relevance unless searching specifically
                if filt == 'all' and item['rel']['category'] == 'low' and not query:
                    continue
                shown += 1
                self._cons_make_disease_card(results_inner, item, is_ru,
                                              cat_colors, cat_icons, win)
            if shown == 0:
                tk.Label(results_inner, text=('Ничего не найдено' if is_ru else 'Nothing found'),
                          bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 10)).pack(pady=20)

        search_var.trace('w', lambda *a: refresh())
        refresh()

    def _cons_make_disease_card(self, parent, item, is_ru, cat_colors, cat_icons, win):
        """Create a clickable disease card in the search results."""
        rel = item['rel']
        color = cat_colors[rel['category']]
        card = tk.Frame(parent, bg=biosim_theme('panel'), highlightthickness=1,
                        highlightbackground=color)
        card.pack(fill='x', pady=4, padx=2)

        # Header row
        header = tk.Frame(card, bg=biosim_theme('panel'))
        header.pack(fill='x', padx=10, pady=(8, 2))
        tk.Label(header, text=cat_icons[rel['category']] + ' ' + item['name'],
                  bg=biosim_theme('panel'), fg=color, font=('Arial', 11, 'bold')).pack(side='left')
        genes = item['data'].get('genes', [])
        if genes:
            tk.Label(header, text='  ' + ', '.join(genes[:4]),
                      bg=biosim_theme('panel'), fg=biosim_theme('text_dim'), font=('Courier', 8)).pack(side='left')

        # Approaches
        if rel['approaches']:
            appr_text = ' · '.join(synbio_approach_description(a, 'ru' if is_ru else 'en')
                                    for a in rel['approaches'][:2])
            tk.Label(card, text='' + appr_text, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                      font=('Arial', 8), wraplength=600, justify='left').pack(anchor='w', padx=10, pady=2)

        # Build circuit button
        if rel['synbio_applicable']:
            tk.Button(card, text=('Построить генную цепь для лечения'
                                    if is_ru else 'Build gene circuit to treat'),
                       bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                       font=('Arial', 9, 'bold'), cursor='hand2', pady=3,
                       command=lambda: self._cons_build_circuit_for_disease(item, win)
                       ).pack(fill='x', padx=10, pady=(2, 8))

    def _cons_build_circuit_for_disease(self, item, search_win):
        """Build a suggested gene circuit on the canvas for this disease."""
        is_ru = (self.lang == 'ru')
        suggestion = build_gene_circuit_suggestion(item['data'], 'ru' if is_ru else 'en')
        if not suggestion.get('applicable'):
            return

        # Show confirmation with circuit details
        detail = tk.Toplevel(search_win)
        detail.title('' + ('Генная цепь' if is_ru else 'Gene circuit'))
        detail.geometry('560x480')
        detail.configure(bg=biosim_theme('bg'))
        detail.transient(search_win)

        tk.Label(detail, text=('Предлагаемая генная цепь для:' if is_ru else 'Suggested gene circuit for:'),
                  bg=biosim_theme('bg'), fg='#1a7f37', font=('Arial', 12, 'bold')).pack(pady=(14, 2))
        tk.Label(detail, text=item['name'], bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 13, 'bold')).pack()

        tk.Label(detail, text=suggestion['description'], bg=biosim_theme('bg'), fg=biosim_theme('text'),
                  font=('Arial', 10), wraplength=500, justify='center').pack(pady=10)

        # Circuit diagram
        circuit_frame = tk.Frame(detail, bg=biosim_theme('panel'), highlightthickness=1,
                                  highlightbackground=biosim_theme('border'))
        circuit_frame.pack(fill='x', padx=20, pady=10)
        tk.Label(circuit_frame, text=('Схема цепи:' if is_ru else 'Circuit design:'),
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'), font=('Arial', 9, 'bold')).pack(anchor='w', padx=10, pady=(8, 4))
        node_colors = {'promoter': '#9a6700', 'rbs': '#0550ae',
                       'cds': '#1a7f37', 'terminator': '#cf222e'}
        for node in suggestion['circuit_nodes']:
            row = tk.Frame(circuit_frame, bg=biosim_theme('panel'))
            row.pack(fill='x', padx=14, pady=2)
            c = node_colors.get(node['type'], '#1c2128')
            tk.Label(row, text='▸', bg=biosim_theme('panel'), fg=c, font=('Arial', 11)).pack(side='left')
            tk.Label(row, text=node['type'].upper(), bg=biosim_theme('panel'), fg=c,
                      font=('Courier', 9, 'bold'), width=11, anchor='w').pack(side='left')
            tk.Label(row, text=node['name'], bg=biosim_theme('panel'), fg=biosim_theme('text'),
                      font=('Arial', 9)).pack(side='left')
        tk.Label(circuit_frame, text='', bg=biosim_theme('panel')).pack(pady=2)

        # Approaches explanation
        appr_frame = tk.Frame(detail, bg=biosim_theme('bg'))
        appr_frame.pack(fill='x', padx=20)
        tk.Label(appr_frame, text=('Подходы синтетической биологии:' if is_ru else 'SynBio approaches:'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9, 'bold')).pack(anchor='w')
        for a in suggestion['approaches']:
            tk.Label(appr_frame, text='  • ' + synbio_approach_description(a, 'ru' if is_ru else 'en'),
                      bg=biosim_theme('bg'), fg=biosim_theme('text'), font=('Arial', 9)).pack(anchor='w')

        # Build button — actually place on canvas
        def do_build():
            self._cons_place_suggested_circuit(suggestion)
            detail.destroy()
            search_win.destroy()
            try:
                self.sb_message(('Генная цепь построена на холсте!'
                                  if is_ru else 'Gene circuit built on canvas!'), 'success')
            except Exception as _exc:
                biosim_log('warn', 'do_build: {}'.format(_exc))

        tk.Button(detail, text=('Построить на холсте' if is_ru else 'Build on canvas'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat', font=('Arial', 11, 'bold'),
                   cursor='hand2', pady=6, command=do_build).pack(fill='x', padx=20, pady=12)

    def _cons_place_suggested_circuit(self, suggestion):
        """Place the suggested circuit nodes on the SynBio canvas."""
        try:
            state = self.current_state['constructor']
            if state is None:
                return
            if 'nodes' not in state:
                state['nodes'] = []
            if 'edges' not in state:
                state['edges'] = []
            if 'init' not in state:
                state['init'] = {}

            existing_ids = set(n['id'] for n in state['nodes'])
            x_start = 120
            y = 160
            spacing = 140
            new_node_ids = []
            for i, node in enumerate(suggestion['circuit_nodes']):
                # Generate unique id
                base = node['type'] + '_' + str(i + 1)
                new_id = base
                counter = 1
                while new_id in existing_ids:
                    new_id = base + '_' + str(counter)
                    counter += 1
                existing_ids.add(new_id)
                new_node = {
                    'id': new_id,
                    'type': 'gene',  # constructor uses 'gene' type for nodes
                    'label': node['name'],
                    'part_type': node['type'],
                    'x': x_start + i * spacing,
                    'y': y,
                    'production': 1.0,
                    'degradation': 0.1,
                }
                state['nodes'].append(new_node)
                state['init'][new_id] = 0.5
                new_node_ids.append(new_id)
            # Connect them in sequence (activation edges)
            for i in range(len(new_node_ids) - 1):
                state['edges'].append({
                    'from': new_node_ids[i],
                    'to': new_node_ids[i + 1],
                    'type': 'activation',
                    'strength': 1.0,
                    'hill_n': 2,
                })
            # Re-render
            self._cons_refresh()
        except Exception as _exc:
            biosim_log('warn', '_cons_place_suggested_circuit: {}'.format(_exc))


    def _cons_delegate_to_main(self, method_name):
        """Walk up the widget tree to find MainApp and call its method."""
        root = self.master
        while root is not None and not hasattr(root, method_name):
            root = getattr(root, 'master', None)
        if root is not None and hasattr(root, method_name):
            getattr(root, method_name)()
        else:
            # Last resort: use the Tk root
            try:
                import tkinter as tk
                r = self._root()
                if hasattr(r, method_name):
                    getattr(r, method_name)()
            except Exception as _exc:
                biosim_log('warn', '_cons_delegate_to_main: {}'.format(_exc))


    def _cons_open_biomodels_search(self):
        """Search EBI BioModels database online."""
        dlg = tk.Toplevel(self)
        dlg.title(self._t('biomodels_title'))
        dlg.geometry('780x600')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('biomodels_title'),
                  bg=biosim_theme('bg'), fg='#0550ae',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text='EBI BioModels Database · 50,000+ моделей' if self.lang == 'ru'
                  else 'EBI BioModels Database · 50,000+ published models',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()

        # Search row
        search_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        search_row.pack(fill='x', padx=14, pady=8)
        tk.Label(search_row, text=self._t('biomodels_search'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        q_var = tk.StringVar(value='repressilator')
        tk.Entry(search_row, textvariable=q_var,
                  bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                  relief='flat', font=('Arial', 11),
                  highlightthickness=1, highlightbackground=biosim_theme('border')
                  ).pack(side='left', fill='x', expand=True, padx=4, ipady=3)

        results_data = []  # list of dicts

        def do_search():
            q = q_var.get().strip()
            if not q:
                return
            status_lbl.config(text=self._t('biomodels_searching'), fg='#9a6700')
            dlg.update()
            def worker():
                models, msg = search_biomodels(q, max_results=20)
                def update_ui():
                    status_lbl.config(text=msg, fg='#1a7f37' if models else '#cf222e')
                    results_txt.config(state='normal')
                    results_txt.delete('1.0', 'end')
                    results_data.clear()
                    results_data.extend(models)
                    if not models:
                        results_txt.insert('end', 'Нет результатов' if self.lang == 'ru'
                                            else 'No results')
                    else:
                        for i, m in enumerate(models):
                            results_txt.insert('end',
                                '{:>2}. {:<14} {:<40}\n'.format(
                                    i + 1, m['id'][:14], m['name'][:40]))
                            results_txt.insert('end',
                                '    {} · {} · {}\n\n'.format(
                                    m['format'], m['submitter'][:20], m['submission_date']))
                    results_txt.config(state='disabled')
                self.after(0, update_ui)
            threading.Thread(target=worker, daemon=True).start()

        tk.Button(search_row, text=self._t('ncbi_search'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   command=do_search).pack(side='left', padx=4)

        # Status
        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                                font=('Arial', 10, 'italic'))
        status_lbl.pack()

        # Results area
        results_txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                                  height=18, font=('Courier', 9),
                                                  relief='flat', highlightthickness=0)
        results_txt.pack(fill='both', expand=True, padx=14, pady=4)
        results_txt.config(state='disabled')

        # Download row
        dl_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        dl_row.pack(fill='x', padx=14, pady=4)
        tk.Label(dl_row, text='№:' if self.lang == 'ru' else '#:',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        id_var = tk.StringVar(value='1')
        tk.Entry(dl_row, textvariable=id_var, width=4,
                  bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                  relief='flat', font=('Arial', 10),
                  justify='center', highlightthickness=1,
                  highlightbackground=biosim_theme('border')).pack(side='left', padx=4)

        def do_download():
            try:
                idx = int(id_var.get()) - 1
                if idx < 0 or idx >= len(results_data):
                    status_lbl.config(text='Invalid number', fg='#cf222e')
                    return
            except Exception as _exc:
                biosim_log('warn', 'do_download: {}'.format(_exc))
                return
            m = results_data[idx]
            status_lbl.config(text='Loading ' + m['id'] + '...', fg='#9a6700')
            dlg.update()
            def worker():
                xml_text, msg = download_biomodel_sbml(m['id'])
                if xml_text is None:
                    self.after(0, lambda: status_lbl.config(text=msg, fg='#cf222e'))
                    return
                # Save to temp file then import
                import tempfile
                fd, fp = tempfile.mkstemp(suffix='.xml', prefix=m['id'] + '_')
                with os.fdopen(fd, 'w') as f:
                    f.write(xml_text)
                # Import as state
                new_state, msg2 = import_sbml_to_circuit(fp)
                def update_ui():
                    if new_state is None:
                        status_lbl.config(text='Import error: ' + msg2, fg='#cf222e')
                        return
                    self._save_history('constructor')
                    self.current_state['constructor'] = new_state
                    self._cons_refresh()
                    status_lbl.config(text='Loaded ' + m['id'], fg='#1a7f37')
                    biosim_log('success', 'Loaded BioModel ' + m['id'])
                    dlg.destroy()
                self.after(0, update_ui)
            threading.Thread(target=worker, daemon=True).start()

        tk.Button(dl_row, text=self._t('biomodels_download'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='#f5f7fa', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   command=do_download).pack(side='left', padx=4)
        tk.Button(dl_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2',
                   command=dlg.destroy).pack(side='right', padx=4)

    def _cons_open_tutorials(self):
        """Open Tutorial Projects browser — 20 step-by-step learning projects."""
        dlg = tk.Toplevel(self)
        dlg.title('' + ('Учебные проекты' if self.lang == 'ru' else 'Tutorial Projects'))
        dlg.geometry('900x700')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        # Header
        tk.Label(dlg, text=('20 Учебных проектов' if self.lang == 'ru'
                                      else '20 Tutorial Projects'),
                  bg=biosim_theme('bg'), fg='#9a6700',
                  font=('Arial', 16, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=('Пошаговые упражнения от простого к сложному'
                              if self.lang == 'ru' else
                              'Step-by-step exercises from basic to expert'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(pady=(0, 8))

        # Difficulty filter
        filter_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        filter_row.pack(fill='x', padx=14, pady=4)
        tk.Label(filter_row, text=('Сложность:' if self.lang == 'ru' else 'Difficulty:'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(side='left')

        difficulty_var = tk.StringVar(value='all')
        diff_options = [
            ('all', 'Все' if self.lang == 'ru' else 'All', '#1c2128'),
            ('beginner', '' + ('Начинающий' if self.lang == 'ru' else 'Beginner'), '#1a7f37'),
            ('intermediate', '' + ('Средний' if self.lang == 'ru' else 'Intermediate'), '#9a6700'),
            ('advanced', '' + ('Продвинутый' if self.lang == 'ru' else 'Advanced'), '#bc4c00'),
            ('expert', '' + ('Эксперт' if self.lang == 'ru' else 'Expert'), '#cf222e'),
        ]

        # Tutorials list (scrollable)
        list_container = tk.Frame(dlg, bg=biosim_theme('bg'))
        list_container.pack(fill='both', expand=True, padx=14, pady=8)
        list_canv = tk.Canvas(list_container, bg=biosim_theme('bg'), highlightthickness=0)
        list_sb = tk.Scrollbar(list_container, orient='vertical', command=list_canv.yview)
        list_canv.configure(yscrollcommand=list_sb.set)
        list_canv.pack(side='left', fill='both', expand=True)
        list_sb.pack(side='right', fill='y')
        list_inner = tk.Frame(list_canv, bg=biosim_theme('bg'))
        list_inner.bind('<Configure>',
                         lambda e: list_canv.configure(scrollregion=list_canv.bbox('all')))
        list_canv.create_window((0, 0), window=list_inner, anchor='nw', width=830)

        def render_tutorials():
            # Clear
            for w in list_inner.winfo_children():
                w.destroy()
            sel_diff = difficulty_var.get()
            for tut_key, tut in TUTORIAL_PROJECTS.items():
                if sel_diff != 'all' and tut['difficulty'] != sel_diff:
                    continue

                # Difficulty color
                diff_color = {'beginner': '#1a7f37', 'intermediate': '#9a6700',
                                'advanced': '#bc4c00', 'expert': '#cf222e'}[tut['difficulty']]
                diff_icon = {'beginner': '', 'intermediate': '',
                              'advanced': '', 'expert': ''}[tut['difficulty']]

                card = tk.Frame(list_inner, bg=biosim_theme('panel'),
                                  highlightthickness=2,
                                  highlightbackground='#eef1f5')
                card.pack(fill='x', padx=4, pady=4)

                # Header row
                head = tk.Frame(card, bg=biosim_theme('panel'))
                head.pack(fill='x', padx=12, pady=(10, 4))
                tk.Label(head, text=tut['name_' + self.lang],
                          bg=biosim_theme('panel'), fg='#0550ae',
                          font=('Arial', 12, 'bold')).pack(side='left')
                tk.Label(head, text='  ' + diff_icon + ' ' + tut['difficulty'],
                          bg=biosim_theme('panel'), fg=diff_color,
                          font=('Arial', 9, 'bold')).pack(side='left', padx=4)
                tk.Label(head, text='⏱  {} min'.format(tut['time_minutes']),
                          bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                          font=('Arial', 9)).pack(side='right')

                # Description
                tk.Label(card, text=tut['desc_' + self.lang],
                          bg=biosim_theme('panel'), fg=biosim_theme('text'),
                          font=('Arial', 10), wraplength=780,
                          justify='left').pack(anchor='w', padx=12, pady=2)

                # Learning objectives
                learning = tut['learning_' + self.lang]
                if learning:
                    tk.Label(card,
                              text=('Чему научишься: ' if self.lang == 'ru'
                                    else 'You\'ll learn: ') + ' · '.join(learning),
                              bg=biosim_theme('panel'), fg='#1a7f37',
                              font=('Arial', 9, 'italic'),
                              wraplength=780, justify='left'
                              ).pack(anchor='w', padx=12, pady=2)

                # Load button
                btn_row = tk.Frame(card, bg=biosim_theme('panel'))
                btn_row.pack(fill='x', padx=12, pady=(2, 10))

                def make_load(t_key, t_data):
                    def load():
                        try:
                            self._save_history('constructor')
                            # Use preset or full state
                            if t_data.get('preset_key') and t_data['preset_key'] in SCIENTIFIC_PRESETS:
                                preset = SCIENTIFIC_PRESETS[t_data['preset_key']]
                                import copy
                                new_state = {
                                    'name': preset.get('name_ru' if self.lang == 'ru' else 'name_en',
                                                          t_data['name_' + self.lang]),
                                    'description': preset.get('description_ru' if self.lang == 'ru'
                                                                else 'description_en', ''),
                                    'nodes': copy.deepcopy(preset['nodes']),
                                    'edges': copy.deepcopy(preset['edges']),
                                    'init': copy.deepcopy(preset['init']),
                                    'chains': [],
                                }
                            elif t_data.get('state'):
                                import copy
                                new_state = copy.deepcopy(t_data['state'])
                            else:
                                self.toast('Tutorial state missing', level='warn')
                                return
                            self.current_state['constructor'] = new_state
                            self._cons_refresh()
                            self.toast('' + t_data['name_' + self.lang],
                                        level='success', duration=2500)
                            # Show experiments dialog
                            self._show_tutorial_experiments(t_key, t_data)
                            dlg.destroy()
                        except Exception as e:
                            biosim_log('warn', 'load: {}'.format(e))
                            self.toast('Error: ' + str(e)[:80], level='error')

                    return load

                tk.Button(btn_row,
                           text='▶ ' + ('Загрузить и начать' if self.lang == 'ru'
                                          else 'Load and start'),
                           bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                           font=('Arial', 10, 'bold'), cursor='hand2',
                           padx=18, pady=4,
                           command=make_load(tut_key, tut)
                           ).pack(side='left')

        # Difficulty filter buttons
        for diff_key, diff_label, diff_color in diff_options:
            def make_select(d):
                return lambda: (difficulty_var.set(d), render_tutorials())
            tk.Button(filter_row, text=diff_label,
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=diff_color, relief='solid', bd=1,
                       font=('Arial', 9, 'bold'), cursor='hand2',
                       padx=10, pady=3,
                       command=make_select(diff_key)
                       ).pack(side='left', padx=2)

        render_tutorials()

        # Close button
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=6,
                   command=dlg.destroy
                   ).pack(fill='x', padx=14, pady=8)

    def _show_tutorial_experiments(self, tut_key, tut):
        """Show small dialog with suggested experiments for a tutorial."""
        dlg = tk.Toplevel(self)
        dlg.title('' + tut['name_' + self.lang])
        dlg.geometry('640x500')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + tut['name_' + self.lang],
                  bg=biosim_theme('bg'), fg='#9a6700',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))

        tk.Label(dlg, text=tut['desc_' + self.lang],
                  bg=biosim_theme('bg'), fg=biosim_theme('text'),
                  font=('Arial', 10), wraplength=580).pack(pady=4)

        # Experiments list
        exp_frame = tk.LabelFrame(dlg,
                                     text='  ' + ('Что попробовать:'
                                                    if self.lang == 'ru'
                                                    else 'Try these experiments:') + '  ',
                                     bg=biosim_theme('bg'), fg='#1a7f37',
                                     font=('Arial', 11, 'bold'),
                                     relief='flat')
        exp_frame.pack(fill='both', expand=True, padx=14, pady=8)

        for i, exp in enumerate(tut['suggested_experiments_' + self.lang], 1):
            row = tk.Frame(exp_frame, bg=biosim_theme('bg'))
            row.pack(fill='x', padx=8, pady=4)
            tk.Label(row, text=str(i) + '.', bg=biosim_theme('bg'), fg='#0969da',
                      font=('Arial', 11, 'bold'),
                      width=3).pack(side='left', anchor='nw')
            tk.Label(row, text=exp, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                      font=('Arial', 10), wraplength=540,
                      justify='left', anchor='w').pack(side='left', fill='x', expand=True)

        tk.Button(dlg, text=('Понятно, начинаю' if self.lang == 'ru'
                                      else 'Got it, let me try'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=dlg.destroy
                   ).pack(fill='x', padx=14, pady=10)

    def _cons_open_validation_suite(self):
        """Run validation suite and show pass/fail report."""
        dlg = tk.Toplevel(self)
        dlg.title('' + ('Тесты валидации' if self.lang == 'ru' else 'Validation Suite'))
        dlg.geometry('780x600')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text=('Валидация движка' if self.lang == 'ru'
                                       else 'Validation Suite'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 15, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=('Проверяет что симуляция даёт известные правильные результаты'
                              if self.lang == 'ru' else
                              'Verifies simulation produces known correct results'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack(pady=(0, 6))

        # Run button + status
        status_lbl = tk.Label(dlg, text=('Готов к запуску' if self.lang == 'ru'
                                            else 'Ready to run'),
                                 bg=biosim_theme('bg'), fg='#9a6700',
                                 font=('Arial', 10, 'italic'))
        status_lbl.pack(pady=4)

        # Results area (scrollable)
        result_container = tk.Frame(dlg, bg=biosim_theme('bg'))
        result_container.pack(fill='both', expand=True, padx=14, pady=4)
        result_sb = tk.Scrollbar(result_container)
        result_sb.pack(side='right', fill='y')
        result_txt = tk.Text(result_container, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                font=('Courier', 10), relief='flat',
                                wrap='word', highlightthickness=0,
                                padx=12, pady=10,
                                yscrollcommand=result_sb.set)
        result_txt.pack(side='left', fill='both', expand=True)
        result_sb.config(command=result_txt.yview)

        result_txt.tag_config('pass', foreground='#1a7f37',
                                 font=('Courier', 10, 'bold'))
        result_txt.tag_config('fail', foreground='#cf222e',
                                 font=('Courier', 10, 'bold'))
        result_txt.tag_config('h1', foreground='#0550ae',
                                 font=('Arial', 12, 'bold'))

        result_txt.insert('end', ('Нажми "▶ Запустить" чтобы проверить'
                                      if self.lang == 'ru' else
                                      'Click "▶ Run" to test')
                            + ' {} '.format(len(VALIDATION_REFERENCES))
                            + ('эталонных пресетов\n' if self.lang == 'ru'
                                else 'reference presets\n'))
        result_txt.config(state='disabled')

        def run_tests():
            run_btn.config(state='disabled')
            status_lbl.config(text=('Запускаю тесты...' if self.lang == 'ru'
                                       else 'Running tests...'),
                                fg='#0969da')
            self.sb_progress_start()
            dlg.update()

            try:
                summary = run_validation_suite(verbose=False)
            except Exception as e:
                biosim_log('warn', 'run_tests: {}'.format(e))
                self.sb_progress_stop()
                run_btn.config(state='normal')
                status_lbl.config(text='Error: ' + str(e)[:60], fg='#cf222e')
                return

            self.sb_progress_stop()

            # Display results
            result_txt.config(state='normal')
            result_txt.delete('1.0', 'end')
            result_txt.insert('end', '═' * 60 + '\n')
            summary_line = '  {}/{} passed   {} failed\n'.format(
                summary['passed'], summary['total'], summary['failed'])
            tag = 'pass' if summary['failed'] == 0 else 'fail'
            result_txt.insert('end', summary_line, tag)
            result_txt.insert('end', '═' * 60 + '\n\n')

            for r in summary['results']:
                if r['passed']:
                    result_txt.insert('end', 'PASS  ', 'pass')
                else:
                    result_txt.insert('end', 'FAIL  ', 'fail')
                result_txt.insert('end', '{:25}  '.format(r['preset']))
                result_txt.insert('end', r['message'] + '\n')

            result_txt.config(state='disabled')

            if summary['failed'] == 0:
                status_lbl.config(text=('Все тесты пройдены!'
                                                  if self.lang == 'ru' else
                                                  'All tests passed!'),
                                    fg='#1a7f37')
                self.toast('All {} validation tests passed!'.format(summary['total']),
                            level='success', duration=3000)
            else:
                status_lbl.config(text='{} тестов провалено'.format(summary['failed'])
                                    if self.lang == 'ru' else
                                    '{} tests failed'.format(summary['failed']),
                                    fg='#9a6700')

            run_btn.config(state='normal')
            biosim_log('info', 'Validation suite: {}/{} passed'.format(
                summary['passed'], summary['total']))

        # Buttons
        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=8)
        run_btn = tk.Button(btn_row, text='▶ ' + ('Запустить тесты'
                                                       if self.lang == 'ru'
                                                       else 'Run tests'),
                               bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                               font=('Arial', 11, 'bold'), cursor='hand2',
                               padx=20, pady=6, command=run_tests)
        run_btn.pack(side='left', padx=2)

        tk.Button(btn_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=6, padx=14,
                   command=dlg.destroy).pack(side='right', padx=2)


    def _cons_open_phase_portrait(self):
        """2D Phase portrait dialog — vector field + nullclines + trajectories."""
        state = self.current_state['constructor']
        if not state or len(state.get('nodes', [])) < 2:
            self.toast('Need at least 2 nodes' if self.lang == 'en'
                        else 'Нужно как минимум 2 узла', level='warn')
            return

        dlg = tk.Toplevel(self)
        dlg.title('Phase Portrait 2D')
        dlg.geometry('500x420')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='Phase Portrait 2D',
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg,
                  text='Векторное поле + траектории + nullclines'
                       if self.lang == 'ru' else
                       'Vector field + trajectories + nullclines',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()

        node_ids = [n['id'] for n in state['nodes']]

        # X axis variable
        row_x = tk.Frame(dlg, bg=biosim_theme('bg')); row_x.pack(fill='x', padx=14, pady=4)
        tk.Label(row_x, text='X axis:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        x_var = tk.StringVar(value=node_ids[0])
        ttk.Combobox(row_x, textvariable=x_var, values=node_ids,
                      state='readonly', width=18).pack(side='left')

        # Y axis variable
        row_y = tk.Frame(dlg, bg=biosim_theme('bg')); row_y.pack(fill='x', padx=14, pady=4)
        tk.Label(row_y, text='Y axis:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        y_var = tk.StringVar(value=node_ids[1] if len(node_ids) > 1 else node_ids[0])
        ttk.Combobox(row_y, textvariable=y_var, values=node_ids,
                      state='readonly', width=18).pack(side='left')

        # X range
        rx = tk.Frame(dlg, bg=biosim_theme('bg')); rx.pack(fill='x', padx=14, pady=4)
        tk.Label(rx, text='X range:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        x_min = tk.DoubleVar(value=0.0); x_max = tk.DoubleVar(value=5.0)
        tk.Entry(rx, textvariable=x_min, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=2)
        tk.Label(rx, text=' to ', bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        tk.Entry(rx, textvariable=x_max, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=2)

        # Y range
        ry = tk.Frame(dlg, bg=biosim_theme('bg')); ry.pack(fill='x', padx=14, pady=4)
        tk.Label(ry, text='Y range:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        y_min = tk.DoubleVar(value=0.0); y_max = tk.DoubleVar(value=5.0)
        tk.Entry(ry, textvariable=y_min, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=2)
        tk.Label(ry, text=' to ', bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        tk.Entry(ry, textvariable=y_max, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=2)

        # Grid density
        rg = tk.Frame(dlg, bg=biosim_theme('bg')); rg.pack(fill='x', padx=14, pady=4)
        tk.Label(rg, text='Grid density:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        grid_var = tk.IntVar(value=15)
        tk.Scale(rg, from_=5, to=30, orient='horizontal', variable=grid_var,
                  bg=biosim_theme('bg'), fg=biosim_theme('text'), highlightthickness=0,
                  troughcolor='#eef1f5', activebackground='#0969da',
                  length=180).pack(side='left', padx=4)

        # Show options
        opts = tk.Frame(dlg, bg=biosim_theme('bg')); opts.pack(fill='x', padx=14, pady=4)
        show_traj = tk.BooleanVar(value=True)
        show_null = tk.BooleanVar(value=True)
        tk.Checkbutton(opts, text='Trajectories' if self.lang == 'en' else 'Траектории',
                        variable=show_traj,
                        bg=biosim_theme('bg'), fg='#1a7f37',
                        selectcolor='#eef1f5',
                        activebackground='#f5f7fa').pack(side='left', padx=8)
        tk.Checkbutton(opts, text='Nullclines' if self.lang == 'en' else 'Изоклины',
                        variable=show_null,
                        bg=biosim_theme('bg'), fg='#bc4c00',
                        selectcolor='#eef1f5',
                        activebackground='#f5f7fa').pack(side='left', padx=8)

        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg='#9a6700',
                                font=('Arial', 10, 'italic'))
        status_lbl.pack(pady=4)

        def run_phase():
            if x_var.get() == y_var.get():
                status_lbl.config(text='Pick different X and Y variables', fg='#cf222e')
                return
            status_lbl.config(text='Computing...', fg='#9a6700')
            self.sb_progress_start()
            dlg.update()
            try:
                result, msg = compute_phase_portrait_2d(
                    state, x_var.get(), y_var.get(),
                    x_range=(float(x_min.get()), float(x_max.get())),
                    y_range=(float(y_min.get()), float(y_max.get())),
                    n_grid=int(grid_var.get()))
            except Exception as e:
                biosim_log('warn', 'run_phase: {}'.format(e))
                self.sb_progress_stop()
                status_lbl.config(text='Error: ' + str(e)[:80], fg='#cf222e')
                return
            self.sb_progress_stop()
            if result is None:
                status_lbl.config(text='' + msg, fg='#cf222e')
                return
            # Plot
            plot_dlg = tk.Toplevel(dlg)
            plot_dlg.title('Phase Portrait: {} vs {}'.format(
                x_var.get(), y_var.get()))
            plot_dlg.geometry('760x680')
            plot_dlg.configure(bg=biosim_theme('bg'))
            fig, ax = plt.subplots(figsize=(7, 6.2), facecolor='#f5f7fa')
            ax.set_facecolor('#ffffff')
            ax.tick_params(colors='#57606a')
            for sp in ax.spines.values(): sp.set_color('#d0d7de')

            # Vector field
            ax.quiver(result['X'], result['Y'], result['U'], result['V'],
                       color='#57606a', scale=30, width=0.0025, alpha=0.6)

            # Nullclines
            if show_null.get():
                if result['nullclines_x']:
                    nx = np.array(result['nullclines_x'])
                    ax.scatter(nx[:, 0], nx[:, 1], color='#bc4c00', s=12,
                                label='dX/dt = 0', alpha=0.7)
                if result['nullclines_y']:
                    ny = np.array(result['nullclines_y'])
                    ax.scatter(ny[:, 0], ny[:, 1], color='#0969da', s=12,
                                label='dY/dt = 0', alpha=0.7)

            # Trajectories
            if show_traj.get():
                for t, x_arr, y_arr in result['trajectories']:
                    ax.plot(x_arr, y_arr, color='#1a7f37', alpha=0.5,
                             linewidth=1.2)
                    # Mark start point
                    ax.scatter(x_arr[0], y_arr[0], color='#1a7f37', s=30,
                                zorder=5, edgecolor='white', linewidth=0.5)
                    # Mark end (arrow tip)
                    ax.annotate('', xy=(x_arr[-1], y_arr[-1]),
                                  xytext=(x_arr[-2], y_arr[-2]),
                                  arrowprops=dict(arrowstyle='->',
                                                    color='#1a7f37'))

            ax.set_xlabel(x_var.get(), color='#1c2128')
            ax.set_ylabel(y_var.get(), color='#1c2128')
            ax.set_title('Phase Portrait', color='#1c2128', fontsize=12)
            ax.grid(True, color='#eef1f5', lw=0.5)
            if show_null.get():
                leg = ax.legend(loc='best', facecolor='#ffffff',
                                  edgecolor='#d0d7de', labelcolor='#1c2128',
                                  framealpha=0.9, fontsize=9)
            cv = FigureCanvasTkAgg(fig, master=plot_dlg)
            cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
            tk.Button(plot_dlg, text=self._t('close_btn'),
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       command=plot_dlg.destroy).pack(fill='x', padx=12, pady=6)
            self.toast('Phase portrait computed', level='success')

        tk.Button(dlg, text='▶ ' + self._t('adv_run'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=run_phase
                   ).pack(fill='x', padx=14, pady=10)
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=(0, 10))

    def _cons_open_animation(self):
        """Animated real-time visualization of circuit dynamics."""
        state = self.current_state['constructor']
        if not state or not state.get('nodes'):
            self.toast('Сначала создай схему' if self.lang == 'ru'
                        else 'Build a circuit first', level='warn')
            return
        
        # Run ODE simulation first
        self.sb_progress_start()
        self.update()
        try:
            t, y, ids = run_ode_simulation(state['nodes'], state['edges'],
                                              state.get('init', {}), t_end=100)
        except Exception as e:
            biosim_log('warn', '_cons_open_animation: {}'.format(e))
            self.sb_progress_stop()
            self.toast('ODE error: ' + str(e)[:80], level='error')
            return
        self.sb_progress_stop()
        
        if t is None:
            self.toast('Simulation failed', level='error')
            return
        
        # Build dialog window
        dlg = tk.Toplevel(self)
        dlg.title('Real-time Animation')
        dlg.geometry('960x720')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        
        # Header
        header = tk.Frame(dlg, bg=biosim_theme('bg'))
        header.pack(fill='x', pady=8)
        tk.Label(header, text='Real-time Circuit Animation',
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 16, 'bold')).pack()
        tk.Label(header,
                  text=('Молекулы текут по связям · узлы пульсируют по концентрации'
                        if self.lang == 'ru' else
                        'Molecules flow along edges · nodes pulse by concentration'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10, 'italic')).pack()
        
        # Canvas (copy of constructor canvas)
        canvas_frame = tk.Frame(dlg, bg=biosim_theme('bg'),
                                  highlightthickness=2, highlightbackground=biosim_theme('border'))
        canvas_frame.pack(fill='both', expand=True, padx=12, pady=4)
        canvas = tk.Canvas(canvas_frame, bg=biosim_theme('bg'), highlightthickness=0)
        canvas.pack(fill='both', expand=True)
        
        # Draw circuit static elements (edges + node icons)
        # Use the existing canvas drawing routines but on this canvas
        # For simplicity, just draw nodes as labeled circles + edges as lines
        for e in state.get('edges', []):
            n1 = next((n for n in state['nodes'] if n['id'] == e.get('from')), None)
            n2 = next((n for n in state['nodes'] if n['id'] == e.get('to')), None)
            if n1 and n2:
                x1, y1 = n1.get('x', 200), n1.get('y', 200)
                x2, y2 = n2.get('x', 200), n2.get('y', 200)
                etype = e.get('type', 'activation')
                color = '#444' if etype == 'activation' else '#553333'
                canvas.create_line(x1, y1, x2, y2, fill=color, width=2,
                                      arrow='last' if etype == 'activation' else None)
                if etype == 'repression':
                    # Bar at end
                    dx, dy = x2 - x1, y2 - y1
                    d = max(1, (dx*dx + dy*dy) ** 0.5)
                    ux, uy = dx / d, dy / d
                    bar_x = x2 - ux * 15
                    bar_y = y2 - uy * 15
                    canvas.create_line(bar_x - uy * 8, bar_y + ux * 8,
                                          bar_x + uy * 8, bar_y - ux * 8,
                                          fill=color, width=3)
        for n in state.get('nodes', []):
            x, y = n.get('x', 200), n.get('y', 200)
            canvas.create_oval(x - 18, y - 18, x + 18, y + 18,
                                  fill='#ffffff', outline='#d0d7de', width=2)
            canvas.create_text(x, y, text=n['id'][:6],
                                  fill='#1c2128', font=('Arial', 9, 'bold'))
        
        # Create animator
        animator = CircuitAnimator(canvas, state, t, y, ids)
        
        # Controls panel
        ctrl_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        ctrl_frame.pack(fill='x', padx=12, pady=8)
        
        # Play/Pause button
        def toggle_play():
            if animator.playing:
                animator.stop()
                play_btn.config(text='▶ ' + ('Воспроизвести' if self.lang == 'ru'
                                              else 'Play'))
            else:
                animator.start()
                play_btn.config(text='⏸ ' + ('Пауза' if self.lang == 'ru'
                                              else 'Pause'))
        
        play_btn = tk.Button(ctrl_frame, text='▶ ' + ('Воспроизвести' if self.lang == 'ru'
                                                        else 'Play'),
                                bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                                font=('Arial', 11, 'bold'), cursor='hand2',
                                padx=20, pady=6, command=toggle_play)
        play_btn.pack(side='left', padx=4)
        
        # Reset button
        def do_reset():
            animator.reset()
            play_btn.config(text='▶ ' + ('Воспроизвести' if self.lang == 'ru'
                                          else 'Play'))
        tk.Button(ctrl_frame, text='⏮ ' + ('Сброс' if self.lang == 'ru' else 'Reset'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   padx=12, pady=6,
                   command=do_reset).pack(side='left', padx=2)
        
        # Speed slider
        tk.Label(ctrl_frame, text='Speed:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(side='left', padx=(20, 4))
        speed_var = tk.DoubleVar(value=1.0)
        def on_speed_change(v):
            animator.set_speed(float(v))
        speed_scale = tk.Scale(ctrl_frame, from_=0.5, to=5.0, resolution=0.5,
                                  orient='horizontal', variable=speed_var,
                                  bg=biosim_theme('bg'), fg=biosim_theme('text'),
                                  highlightthickness=0, troughcolor='#eef1f5',
                                  activebackground='#1a7f37',
                                  length=160, command=on_speed_change)
        speed_scale.pack(side='left', padx=4)
        
        # Time scrubber (jump to step)
        tk.Label(ctrl_frame, text='Time:', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(side='left', padx=(20, 4))
        step_var = tk.IntVar(value=0)
        def on_step_change(v):
            animator.jump_to(int(float(v)))
        step_scale = tk.Scale(ctrl_frame, from_=0, to=len(t) - 1,
                                 orient='horizontal', variable=step_var,
                                 bg=biosim_theme('bg'), fg=biosim_theme('text'),
                                 highlightthickness=0, troughcolor='#eef1f5',
                                 activebackground='#0969da',
                                 length=200, command=on_step_change,
                                 showvalue=False)
        step_scale.pack(side='left', padx=4)
        
        # Recording button (optional GIF capture)
        recording_state = [False]
        def toggle_recording():
            if recording_state[0]:
                # Stop and save
                animator.recording = False
                recording_state[0] = False
                rec_btn.config(text='⏺ ' + ('Запись GIF' if self.lang == 'ru' else 'Record GIF'),
                                fg='#9a6700')
                # Save dialog
                from tkinter import filedialog
                filepath = filedialog.asksaveasfilename(
                    defaultextension='.gif',
                    filetypes=[('GIF files', '*.gif')])
                if filepath:
                    self.sb_progress_start()
                    dlg.update()
                    ok, msg = animator.save_recording(filepath)
                    self.sb_progress_stop()
                    if ok:
                        self.toast('' + msg, level='success')
                    else:
                        self.toast('' + msg, level='warn')
            else:
                animator.start_recording()
                recording_state[0] = True
                rec_btn.config(text='⏹ ' + ('Стоп' if self.lang == 'ru' else 'Stop'),
                                fg='#cf222e')
                self.toast('Recording started', level='info', duration=1500)
        
        rec_btn = tk.Button(ctrl_frame, text='⏺ ' + ('Запись GIF' if self.lang == 'ru'
                                                       else 'Record GIF'),
                               bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                               font=('Arial', 10, 'bold'), cursor='hand2',
                               padx=12, pady=6, command=toggle_recording)
        rec_btn.pack(side='left', padx=12)
        
        # Close button
        def on_close():
            animator.stop()
            animator.clear()
            dlg.destroy()
        tk.Button(ctrl_frame, text=('Закрыть' if self.lang == 'ru' else 'Close'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2',
                   padx=12, pady=6,
                   command=on_close).pack(side='right', padx=2)
        dlg.protocol('WM_DELETE_WINDOW', on_close)
        
        # Initial frame
        animator._draw_frame()
        
        # Legend below controls
        legend_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        legend_frame.pack(fill='x', padx=12, pady=4)
        tk.Label(legend_frame,
                  text=('зелёные частицы = активация · красные = репрессия · '
                        'свечение узла = концентрация'
                        if self.lang == 'ru' else
                        'green particles = activation · red = repression · '
                        'node glow = concentration'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9, 'italic')).pack()

    def _cons_compute_lyapunov(self):
        """Estimate Lyapunov exponent to detect chaos."""
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            self.toast('No model', level='warn')
            return

        self.toast('Computing Lyapunov exponent...', level='info', duration=2000)
        self.sb_progress_start()
        self.update()
        try:
            lyap, msg = estimate_lyapunov_exponent(state, t_end=150)
        except Exception as e:
            biosim_log('warn', '_cons_compute_lyapunov: {}'.format(e))
            self.sb_progress_stop()
            self.toast('Error: ' + str(e)[:80], level='error')
            return
        self.sb_progress_stop()
        if lyap is None:
            self.toast(msg, level='error')
            return

        # Show result with interpretation
        dlg = tk.Toplevel(self)
        dlg.title('λ Lyapunov Exponent')
        dlg.geometry('480x360')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='λ Lyapunov Exponent',
                  bg=biosim_theme('bg'), fg='#bc4c00',
                  font=('Arial', 15, 'bold')).pack(pady=(16, 8))

        # Value
        tk.Label(dlg, text='λ = {:.5f}'.format(lyap),
                  bg=biosim_theme('bg'), fg='#0550ae',
                  font=('Courier', 20, 'bold')).pack(pady=8)

        # Interpretation
        if lyap > 0.01:
            verdict = 'CHAOTIC' if self.lang == 'en' else 'ХАОС'
            color = '#cf222e'
            explanation = ('Trajectories diverge exponentially.\n'
                            'System is sensitive to initial conditions.'
                            if self.lang == 'en' else
                            'Траектории расходятся экспоненциально.\n'
                            'Система чувствительна к начальным условиям.')
        elif lyap > -0.01:
            verdict = '~ NEUTRAL' if self.lang == 'en' else '~ НЕЙТРАЛЬНОЕ'
            color = '#9a6700'
            explanation = ('Near-zero exponent.\n'
                            'Periodic or quasi-periodic behavior.'
                            if self.lang == 'en' else
                            'Близко к нулю.\n'
                            'Периодическое или квази-периодическое поведение.')
        else:
            verdict = 'STABLE' if self.lang == 'en' else 'УСТОЙЧИВО'
            color = '#1a7f37'
            explanation = ('Negative exponent.\n'
                            'Trajectories converge to stable point.'
                            if self.lang == 'en' else
                            'Отрицательный показатель.\n'
                            'Траектории сходятся к устойчивой точке.')

        tk.Label(dlg, text=verdict,
                  bg=biosim_theme('bg'), fg=color,
                  font=('Arial', 16, 'bold')).pack(pady=8)
        tk.Label(dlg, text=explanation,
                  bg=biosim_theme('bg'), fg=biosim_theme('text'),
                  font=('Arial', 10), justify='center').pack(pady=4)

        tk.Label(dlg, text='λ > 0  хаос' if self.lang == 'ru' else 'λ > 0  chaos',
                  bg=biosim_theme('bg'), fg='#cf222e', font=('Arial', 9)).pack()
        tk.Label(dlg, text='λ ≈ 0  quasi-periodic',
                  bg=biosim_theme('bg'), fg='#9a6700', font=('Arial', 9)).pack()
        tk.Label(dlg, text='λ < 0  stable' if self.lang == 'en' else 'λ < 0  устойчиво',
                  bg=biosim_theme('bg'), fg='#1a7f37', font=('Arial', 9)).pack()

        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=14)
        biosim_log('success', 'Lyapunov exponent: {:.5f}'.format(lyap))

    def _cons_open_bifurcation_dialog(self):
        """Bifurcation analysis dialog."""
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return

        dlg = tk.Toplevel(self)
        dlg.title(self._t('bifurc_title'))
        dlg.geometry('540x420')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('bifurc_title'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 8))

        node_ids = [n['id'] for n in state['nodes']]

        # Parameter selectors
        row1 = tk.Frame(dlg, bg=biosim_theme('bg')); row1.pack(fill='x', padx=14, pady=4)
        tk.Label(row1, text=self._t('bifurc_node'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        node_var = tk.StringVar(value=node_ids[0])
        ttk.Combobox(row1, textvariable=node_var, values=node_ids,
                      state='readonly', width=18).pack(side='left', padx=4)

        row2 = tk.Frame(dlg, bg=biosim_theme('bg')); row2.pack(fill='x', padx=14, pady=4)
        tk.Label(row2, text=self._t('bifurc_param'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  width=14, anchor='w').pack(side='left')
        param_var = tk.StringVar(value='production')
        ttk.Combobox(row2, textvariable=param_var,
                      values=['production', 'degradation'],
                      state='readonly', width=18).pack(side='left', padx=4)

        row3 = tk.Frame(dlg, bg=biosim_theme('bg')); row3.pack(fill='x', padx=14, pady=4)
        tk.Label(row3, text=self._t('adv_range_min'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        min_var = tk.DoubleVar(value=0.1)
        tk.Entry(row3, textvariable=min_var, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=4)
        tk.Label(row3, text=self._t('adv_range_max'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left', padx=(8, 0))
        max_var = tk.DoubleVar(value=10.0)
        tk.Entry(row3, textvariable=max_var, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=4)
        tk.Label(row3, text=self._t('adv_steps'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left', padx=(8, 0))
        steps_var = tk.IntVar(value=30)
        tk.Entry(row3, textvariable=steps_var, width=4, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  relief='flat').pack(side='left', padx=4)

        tk.Label(dlg, text=self._t('bifurc_target'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(anchor='w', padx=14, pady=(8, 0))
        target_var = tk.StringVar(value=node_ids[0])
        ttk.Combobox(dlg, textvariable=target_var, values=node_ids,
                      state='readonly').pack(fill='x', padx=14)

        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg='#9a6700',
                                font=('Arial', 10, 'italic'))
        status_lbl.pack(pady=4)

        def run_bifurc():
            status_lbl.config(text=self._t('bifurc_running'), fg='#9a6700')
            dlg.update()
            try:
                results, bifurcations, p_values = bifurcation_with_classification(
                    state, node_var.get(), param_var.get(),
                    float(min_var.get()), float(max_var.get()),
                    n_steps=int(steps_var.get()),
                    target_nodes=[target_var.get()])
            except Exception as e:
                biosim_log('warn', 'run_bifurc: {}'.format(e))
                status_lbl.config(text='Error: ' + str(e)[:80], fg='#cf222e')
                return
            # Plot
            plot_dlg = tk.Toplevel(dlg)
            plot_dlg.title(self._t('bifurc_title'))
            plot_dlg.geometry('900x600')
            plot_dlg.configure(bg=biosim_theme('bg'))
            fig, ax = plt.subplots(figsize=(8, 4.5), facecolor='#f5f7fa')
            ax.set_facecolor('#ffffff')
            ax.tick_params(colors='#57606a')
            for sp in ax.spines.values(): sp.set_color('#d0d7de')
            target = target_var.get()
            # Color points by stability type
            type_colors = {
                'stable_node':    '#1a7f37',
                'stable_spiral':  '#0969da',
                'unstable_node':  '#cf222e',
                'unstable_spiral':'#bc4c00',
                'saddle':         '#9a6700',
                'center':         '#8250df',
                'degenerate':     '#57606a',
            }
            # Group by stability type
            by_type = {}
            for pv, ss_list, class_info in results[target]:
                t = class_info.get('type', 'unknown') if class_info else 'unknown'
                for ss_val in ss_list:
                    by_type.setdefault(t, ([], []))
                    by_type[t][0].append(pv)
                    by_type[t][1].append(ss_val)
            for t, (xs, ys) in by_type.items():
                col = type_colors.get(t, '#8250df')
                ax.scatter(xs, ys, color=col, s=20, alpha=0.8, label=t)
            
            # Mark bifurcations
            for bif in bifurcations:
                col = {'hopf': '#bc4c00', 'saddle_node': '#9a6700'}.get(bif['type'], '#8250df')
                ax.axvline(bif['param_value'], color=col, linestyle='--', alpha=0.5,
                            linewidth=1.5)
                ax.annotate(bif['type'].upper(), xy=(bif['param_value'], 0),
                              xytext=(bif['param_value'], -0.05),
                              color=col, fontsize=9,
                              ha='center', xycoords=('data', 'axes fraction'))
            
            ax.set_xlabel(node_var.get() + ' ' + param_var.get(), color='#57606a')
            ax.set_ylabel(target + ' steady-state', color='#57606a')
            ax.set_title('Bifurcation: {} vs {}'.format(target,
                node_var.get() + '.' + param_var.get()), color='#1c2128')
            ax.grid(True, color='#eef1f5', lw=0.5)
            leg = ax.legend(loc='best', facecolor='#ffffff',
                              edgecolor='#d0d7de', labelcolor='#1c2128',
                              framealpha=0.9, fontsize=9)
            cv = FigureCanvasTkAgg(fig, master=plot_dlg)
            cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
            
            # Bifurcations report below plot
            if bifurcations:
                report_frame = tk.LabelFrame(plot_dlg,
                                                text='Detected bifurcations' if self.lang == 'en'
                                                      else 'Найдены бифуркации',
                                                bg=biosim_theme('panel'), fg='#bc4c00',
                                                font=('Arial', 10, 'bold'), relief='flat')
                report_frame.pack(fill='x', padx=10, pady=4)
                for bif in bifurcations:
                    txt = '  • {} at {} = {:.3f}   ({} {})'.format(
                        bif['type'].replace('_', ' ').upper(),
                        node_var.get() + '.' + param_var.get(),
                        bif['param_value'],
                        bif['prev_state'], bif['curr_state'])
                    tk.Label(report_frame, text=txt, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                              font=('Courier', 9), anchor='w').pack(anchor='w', padx=8)
            
            tk.Button(plot_dlg, text=self._t('close_btn'),
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       command=plot_dlg.destroy).pack(fill='x', padx=12, pady=6)
            self.toast('Bifurcation done · {} bifurcations found'.format(len(bifurcations)),
                        level='success')
            biosim_log('success', 'Bifurcation analysis complete: {} bifurcations'.format(len(bifurcations)))

        tk.Button(dlg, text='▶ ' + self._t('adv_run'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=run_bifurc
                   ).pack(fill='x', padx=14, pady=10)
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=(0, 10))

    def _cons_run_fva_dialog(self):
        """FVA dialog — runs FVA on cobra model."""
        if not _ensure_cobra():
            messagebox.showwarning('VIREON', self._t('cobra_not_installed'))
            return
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return

        # Build cobra model
        model, msg = build_cobra_model_from_circuit(state)
        if model is None:
            messagebox.showerror('VIREON', msg)
            return
        # Show fraction selector
        fraction = simpledialog_float(self, self._t('fva_fraction'),
                                         initial=0.9, vmin=0.0, vmax=1.0)
        if fraction is None:
            return
        biosim_log('info', 'Running FVA with fraction=' + str(fraction))
        fva_result, msg = run_flux_variability_analysis(model, fraction_of_optimum=fraction)
        if fva_result is None:
            messagebox.showerror('VIREON', msg)
            return
        # Display
        dlg = tk.Toplevel(self)
        dlg.title(self._t('fva_title'))
        dlg.geometry('700x500')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text='' + self._t('fva_title'),
                  bg=biosim_theme('bg'), fg='#bc4c00',
                  font=('Arial', 14, 'bold')).pack(pady=10)
        tk.Label(dlg, text=msg, bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 10)).pack()
        txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 9), relief='flat',
                                          highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=14, pady=8)
        txt.insert('end', '{:>30} {:>12} {:>12} {:>10}\n'.format(
            'Reaction', 'Min flux', 'Max flux', 'Range'))
        txt.insert('end', '─' * 70 + '\n')
        for rid, (lo, hi) in sorted(fva_result.items(),
                                       key=lambda x: -(x[1][1] - x[1][0])):
            txt.insert('end', '{:>30} {:>12.4f} {:>12.4f} {:>10.4f}\n'.format(
                rid[:30], lo, hi, hi - lo))
        txt.config(state='disabled')
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _cons_show_cobra_text(self, title, color, header_msg, body_text):
        """Helper: show a COBRA result in a scrollable text dialog."""
        dlg = tk.Toplevel(self)
        dlg.title(title)
        dlg.geometry('720x520')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text=title, bg=biosim_theme('bg'), fg=color,
                  font=('Arial', 14, 'bold')).pack(pady=10)
        if header_msg:
            tk.Label(dlg, text=header_msg, bg=biosim_theme('bg'), fg='#1a7f37',
                      font=('Arial', 10)).pack()
        txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 9), relief='flat',
                                          highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=14, pady=8)
        txt.insert('end', body_text)
        txt.config(state='disabled')
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                   relief='solid', bd=1, command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _cons_get_cobra_model(self):
        """Helper: validate cobra + build model from current circuit."""
        if not _ensure_cobra():
            messagebox.showwarning('VIREON', self._t('cobra_not_installed'))
            return None
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return None
        model, msg = build_cobra_model_from_circuit(state)
        if model is None:
            messagebox.showerror('VIREON', msg)
            return None
        return model

    def _cons_run_pfba(self):
        """pFBA — parsimonious FBA (optimal growth, minimal enzyme work)."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        result, msg = run_parsimonious_fba(model)
        if result is None:
            messagebox.showerror('VIREON', msg)
            return
        body = ('Целевое значение (рост): {:.4f}\n'.format(result['objective_value'])
                if ru else 'Objective (growth): {:.4f}\n'.format(result['objective_value']))
        body += ('Суммарный поток: {:.2f}\n\n'.format(result['total_flux'])
                 if ru else 'Total flux: {:.2f}\n\n'.format(result['total_flux']))
        body += ('Самые активные реакции:\n' if ru else 'Most active reactions:\n')
        body += '─' * 50 + '\n'
        for rid, flux in result['top_active']:
            body += '{:>34} {:>12.4f}\n'.format(rid[:34], flux)
        title = 'pFBA — экономный FBA' if ru else 'pFBA — parsimonious FBA'
        self._cons_show_cobra_text(title, '#1a7f37', msg, body)

    def _cons_run_essential_genes(self):
        """Find all essential genes by knocking out each one."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        # Warn this may be slow
        result, msg = find_essential_genes(model)
        if result is None:
            messagebox.showerror('VIREON', msg)
            return
        body = ('Базовый рост: {:.4f}\n'.format(result['baseline'])
                if ru else 'Baseline growth: {:.4f}\n'.format(result['baseline']))
        body += ('Эссенциальных генов: {} из {}\n\n'.format(
                    result['n_essential'], result['n_total'])
                 if ru else 'Essential genes: {} of {}\n\n'.format(
                    result['n_essential'], result['n_total']))
        body += ('{:>20} {:>12} {:>10}\n'.format(
            ('Ген' if ru else 'Gene'), ('Рост' if ru else 'Growth'),
            ('Критич.' if ru else 'Essential')))
        body += '─' * 46 + '\n'
        for r in result['results'][:40]:
            mark = '★' if r['essential'] else ''
            body += '{:>20} {:>12.4f} {:>10}\n'.format(
                r['gene'][:20], r['growth_rate'], mark)
        title = 'Эссенциальные гены' if ru else 'Essential Genes'
        self._cons_show_cobra_text(title, '#cf222e', msg, body)

    def _cons_run_robustness(self):
        """Robustness analysis — vary one reaction, watch growth."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        # Let user pick a reaction
        rxn_ids = [r.id for r in model.reactions]
        if not rxn_ids:
            return
        choice = simpledialog.askstring(
            'VIREON',
            ('Реакция для анализа устойчивости:\n' + ', '.join(rxn_ids[:20])
             if ru else 'Reaction for robustness:\n' + ', '.join(rxn_ids[:20])),
            initialvalue=rxn_ids[0])
        if not choice or choice not in rxn_ids:
            return
        points, msg = robustness_analysis(model, choice)
        if points is None:
            messagebox.showerror('VIREON', msg)
            return
        # Plot it
        plot_dlg = tk.Toplevel(self)
        plot_dlg.title('Robustness')
        plot_dlg.geometry('760x520')
        plot_dlg.configure(bg=biosim_theme('bg'))
        fig, ax = plt.subplots(figsize=(7, 4.5), facecolor='#f5f7fa')
        ax.set_facecolor('#ffffff')
        xs = [p[0] for p in points]; ys = [p[1] for p in points]
        ax.plot(xs, ys, '-o', color='#0969da', markersize=4)
        ax.set_xlabel((choice + ' поток') if ru else (choice + ' flux'), color='#57606a')
        ax.set_ylabel('Рост' if ru else 'Growth rate', color='#57606a')
        ax.set_title(('Устойчивость: ' if ru else 'Robustness: ') + choice, color='#1c2128')
        ax.grid(True, color='#eef1f5', lw=0.5)
        ax.tick_params(colors='#57606a')
        for sp in ax.spines.values(): sp.set_color('#d0d7de')
        canvas = FigureCanvasTkAgg(fig, master=plot_dlg)
        canvas.draw()
        canvas.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=10)
        add_chart_export_button(plot_dlg, fig, self.lang).pack(fill='x', padx=14, pady=(0, 4))
        tk.Button(plot_dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                   relief='solid', bd=1, command=plot_dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _cons_run_optknock(self):
        """OptKnock — suggest knockouts that boost product formation."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        rxn_ids = [r.id for r in model.reactions]
        choice = simpledialog.askstring(
            'VIREON',
            ('Целевой продукт (реакция):\n' + ', '.join(rxn_ids[:20])
             if ru else 'Target product (reaction):\n' + ', '.join(rxn_ids[:20])),
            initialvalue=rxn_ids[0])
        if not choice or choice not in rxn_ids:
            return
        result, msg = optknock_suggest(model, choice)
        if result is None:
            messagebox.showerror('VIREON', msg)
            return
        body = ('Базовый рост: {:.4f}\n'.format(result['base_growth'])
                if ru else 'Base growth: {:.4f}\n'.format(result['base_growth']))
        body += ('Базовый продукт: {:.4f}\n\n'.format(result['base_product'])
                 if ru else 'Base product: {:.4f}\n\n'.format(result['base_product']))
        if result['suggestions']:
            body += ('Рекомендованные нокауты (↑ продукт):\n' if ru
                     else 'Suggested knockouts (↑ product):\n')
            body += '{:>26} {:>10} {:>12}\n'.format(
                ('Нокаут' if ru else 'Knockout'),
                ('Рост' if ru else 'Growth'),
                ('Продукт' if ru else 'Product'))
            body += '─' * 50 + '\n'
            for s in result['suggestions']:
                body += '{:>26} {:>10.4f} {:>12.4f}\n'.format(
                    s['knockout'][:26], s['growth_rate'], s['product_flux'])
        else:
            body += ('Не найдено нокаутов которые увеличат продукт.\n' if ru
                     else 'No knockouts found that boost product.\n')
        title = 'OptKnock — биотех-дизайн' if ru else 'OptKnock — strain design'
        self._cons_show_cobra_text(title, '#bc4c00', msg, body)

    def _cons_run_phase_plane(self):
        """Phase plane: vary 2 reactions, plot growth surface."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        rxn_ids = [r.id for r in model.reactions]
        r1 = simpledialog.askstring('VIREON',
            ('Реакция 1 (субстрат):\n' + ', '.join(rxn_ids[:15]) if ru
             else 'Reaction 1 (substrate):\n' + ', '.join(rxn_ids[:15])),
            initialvalue=rxn_ids[0])
        if not r1 or r1 not in rxn_ids:
            return
        r2 = simpledialog.askstring('VIREON',
            ('Реакция 2 (субстрат):' if ru else 'Reaction 2 (substrate):'),
            initialvalue=rxn_ids[1] if len(rxn_ids) > 1 else rxn_ids[0])
        if not r2 or r2 not in rxn_ids:
            return
        grid, msg = phase_plane_analysis(model, r1, r2)
        if grid is None:
            messagebox.showerror('VIREON', msg)
            return
        # 3D surface plot
        dlg = tk.Toplevel(self); dlg.title('Phase Plane'); dlg.geometry('760x600')
        dlg.configure(bg=biosim_theme('bg'))
        try:
            from mpl_toolkits.mplot3d import Axes3D  # noqa
            fig = plt.Figure(figsize=(7, 5.5), facecolor='#f5f7fa')
            ax = fig.add_subplot(111, projection='3d')
            xs = [g[0] for g in grid]; ys = [g[1] for g in grid]; zs = [g[2] for g in grid]
            ax.plot_trisurf(xs, ys, zs, cmap='viridis', alpha=0.85)
            ax.set_xlabel(r1[:12]); ax.set_ylabel(r2[:12])
            ax.set_zlabel('Рост' if ru else 'Growth')
            ax.set_title('Phenotype Phase Plane', color='#1c2128')
            canvas = FigureCanvasTkAgg(fig, master=dlg); canvas.draw()
            canvas.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=10)
            add_chart_export_button(dlg, fig, self.lang).pack(fill='x', padx=14, pady=(0, 4))
        except Exception as e:
            biosim_log('warn', '_cons_run_phase_plane: {}'.format(e))
            tk.Label(dlg, text='Plot error: ' + str(e)[:80],
                      bg=biosim_theme('bg'), fg='#cf222e').pack(pady=20)
        tk.Button(dlg, text=self._t('close_btn'), bg=biosim_theme('panel'),
                   highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _cons_run_dynamic_fba(self):
        """Dynamic FBA: growth over time as substrate depletes."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        rxn_ids = [r.id for r in model.reactions]
        # Find substrate (uptake) and biomass reactions
        sub = simpledialog.askstring('VIREON',
            ('Реакция субстрата (поглощение):\n' + ', '.join(rxn_ids[:15]) if ru
             else 'Substrate reaction (uptake):\n' + ', '.join(rxn_ids[:15])),
            initialvalue=rxn_ids[0])
        if not sub or sub not in rxn_ids:
            return
        biomass = None
        for r in model.reactions:
            if r.objective_coefficient != 0:
                biomass = r.id; break
        traj, msg = dynamic_fba(model, sub, biomass or rxn_ids[0])
        if traj is None:
            messagebox.showerror('VIREON', msg)
            return
        # Plot biomass + substrate over time
        dlg = tk.Toplevel(self); dlg.title('Dynamic FBA'); dlg.geometry('760x520')
        dlg.configure(bg=biosim_theme('bg'))
        fig, ax = new_biosim_figure(figsize=(7, 4.5))
        ts = [p[0] for p in traj]; bio = [p[1] for p in traj]; subc = [p[2] for p in traj]
        ax.plot(ts, bio, '-o', color=BIOSIM_COLORS['green'], label=('Биомасса' if ru else 'Biomass'), markersize=4)
        style_biosim_axes(ax, xlabel=('Время' if ru else 'Time'),
                          ylabel=('Биомасса' if ru else 'Biomass'))
        ax2 = ax.twinx()
        ax2.plot(ts, subc, '-s', color='#bc4c00', label=('Субстрат' if ru else 'Substrate'), markersize=4)
        ax2.set_ylabel(('Субстрат' if ru else 'Substrate'), color='#bc4c00')
        ax.set_title('Dynamic FBA', color='#1c2128')
        ax.grid(alpha=0.2)
        for s in ax.spines.values(): s.set_color('#d0d7de')
        canvas = FigureCanvasTkAgg(fig, master=dlg); canvas.draw()
        canvas.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=10)
        add_chart_export_button(dlg, fig, self.lang).pack(fill='x', padx=14, pady=(0, 4))
        tk.Button(dlg, text=self._t('close_btn'), bg=biosim_theme('panel'),
                   highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _cons_run_moma(self):
        """MOMA — minimal metabolic adjustment after a knockout."""
        model = self._cons_get_cobra_model()
        if model is None:
            return
        ru = (self.lang == 'ru')
        rxn_ids = [r.id for r in model.reactions]
        ko = simpledialog.askstring('VIREON',
            ('Реакция для нокаута:\n' + ', '.join(rxn_ids[:15]) if ru
             else 'Reaction to knock out:\n' + ', '.join(rxn_ids[:15])),
            initialvalue=rxn_ids[0])
        if not ko or ko not in rxn_ids:
            return
        result, msg = moma_analysis(model, ko)
        if result is None:
            messagebox.showerror('VIREON', msg)
            return
        body = ('Метод: {}\n'.format(result['method'])
                if ru else 'Method: {}\n'.format(result['method']))
        body += ('Рост дикого типа: {:.4f}\n'.format(result['wt_growth'])
                 if ru else 'Wild-type growth: {:.4f}\n'.format(result['wt_growth']))
        body += ('Рост после нокаута: {:.4f}\n'.format(result['ko_growth'])
                 if ru else 'Knockout growth: {:.4f}\n'.format(result['ko_growth']))
        body += ('Отношение: {:.1%}\n'.format(result['growth_ratio'])
                 if ru else 'Ratio: {:.1%}\n'.format(result['growth_ratio']))
        title = 'MOMA — после нокаута' if ru else 'MOMA — after knockout'
        self._cons_show_cobra_text(title, '#cf222e', msg, body)

    def _cons_build_pathway(self):
        """Real metabolic pathway builder — define your OWN reactions
        (substrate → intermediate → product) and see the pathway you built,
        with mass-balance checking. Fixes the 'illusion of building' problem:
        here you truly construct a new pathway reaction by reaction."""
        is_ru = (self.lang == 'ru')
        dlg = tk.Toplevel(self)
        dlg.title('Собрать метаболический путь' if is_ru else 'Build Metabolic Pathway')
        dlg.geometry('720x600')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text=('Собери свой метаболический путь' if is_ru
                            else 'Build Your Metabolic Pathway'),
                 bg=biosim_theme('bg'), fg='#1a7f37',
                 font=('Arial', 14, 'bold')).pack(pady=(12, 2))
        tk.Label(dlg, text=('Добавляй реакции: субстрат → продукт. '
                            'Путь строится по-настоящему, шаг за шагом.' if is_ru else
                            'Add reactions: substrate → product. '
                            'The pathway is truly built, step by step.'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 9)).pack()

        # Pathway storage
        if not hasattr(self, '_custom_pathway'):
            self._custom_pathway = []

        # Input row: substrate, product, enzyme
        input_frame = tk.LabelFrame(dlg, text=('Новая реакция' if is_ru else 'New reaction'),
                                     bg=biosim_theme('panel'), fg='#0969da',
                                     font=('Arial', 11, 'bold'), relief='flat')
        input_frame.pack(fill='x', padx=14, pady=8)
        row = tk.Frame(input_frame, bg=biosim_theme('panel'))
        row.pack(fill='x', padx=8, pady=8)
        tk.Label(row, text=('Субстрат:' if is_ru else 'Substrate:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left')
        sub_var = tk.StringVar(value='glucose')
        tk.Entry(row, textvariable=sub_var, width=10, bg=biosim_theme('panel2'),
                 fg=biosim_theme('text'), relief='flat').pack(side='left', padx=4)
        tk.Label(row, text='→', bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 12, 'bold')).pack(side='left', padx=2)
        tk.Label(row, text=('Продукт:' if is_ru else 'Product:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left')
        prod_var = tk.StringVar(value='pyruvate')
        tk.Entry(row, textvariable=prod_var, width=10, bg=biosim_theme('panel2'),
                 fg=biosim_theme('text'), relief='flat').pack(side='left', padx=4)
        tk.Label(row, text=('Фермент:' if is_ru else 'Enzyme:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left')
        enz_var = tk.StringVar(value='')
        tk.Entry(row, textvariable=enz_var, width=8, bg=biosim_theme('panel2'),
                 fg=biosim_theme('text'), relief='flat').pack(side='left', padx=4)

        # Pathway display
        path_display = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'),
                                                 fg=biosim_theme('text'), font=('Courier', 10),
                                                 height=12, relief='flat', state='disabled')
        path_display.pack(fill='both', expand=True, padx=14, pady=8)

        def redraw_pathway():
            path_display.config(state='normal'); path_display.delete('1.0', 'end')
            path_display.tag_config('h', foreground='#1a7f37', font=('Courier', 10, 'bold'))
            path_display.tag_config('arrow', foreground='#8250df')
            path_display.tag_config('warn', foreground='#cf222e')
            if not self._custom_pathway:
                path_display.insert('end', ('Путь пока пуст. Добавьте реакции.\n'
                                            if is_ru else 'Pathway is empty. Add reactions.\n'))
            else:
                path_display.insert('end', ('ВАШ ПУТЬ:\n\n' if is_ru else 'YOUR PATHWAY:\n\n'), 'h')
                # Track metabolites for mass-balance check
                produced = set()
                consumed = set()
                for i, rxn in enumerate(self._custom_pathway, 1):
                    path_display.insert('end', '{}. {} '.format(i, rxn['substrate']))
                    path_display.insert('end', '──[{}]──> '.format(rxn['enzyme'] or '?'), 'arrow')
                    path_display.insert('end', '{}\n'.format(rxn['product']))
                    produced.add(rxn['product']); consumed.add(rxn['substrate'])
                # Mass-balance hints: intermediates that are made but never used
                path_display.insert('end', '\n')
                dead_ends = produced - consumed
                final_products = dead_ends
                if final_products:
                    path_display.insert('end', ('Конечные продукты: ' if is_ru
                                                else 'Final products: ') +
                                        ', '.join(final_products) + '\n', 'h')
                # Check for gaps (substrate never produced and not glucose/external)
                inputs = consumed - produced
                if inputs:
                    path_display.insert('end', ('Входные вещества: ' if is_ru
                                                else 'Inputs needed: ') +
                                        ', '.join(inputs) + '\n')
            path_display.config(state='disabled')

        def add_reaction():
            sub = sub_var.get().strip()
            prod = prod_var.get().strip()
            if sub and prod:
                self._custom_pathway.append({
                    'substrate': sub, 'product': prod, 'enzyme': enz_var.get().strip()})
                # Auto-suggest next substrate = this product
                sub_var.set(prod)
                prod_var.set('')
                enz_var.set('')
                redraw_pathway()

        def clear_pathway():
            self._custom_pathway = []
            redraw_pathway()

        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=8)
        tk.Button(btn_row, text=('➕ Добавить реакцию' if is_ru else '➕ Add reaction'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                  relief='flat', font=('Arial', 10, 'bold'), cursor='hand2',
                  command=add_reaction).pack(side='left', padx=(0, 6))
        tk.Button(btn_row, text=('Очистить' if is_ru else 'Clear'),
                  bg=biosim_theme('panel'), highlightbackground='#cf222e', fg='#cf222e',
                  relief='solid', bd=1, font=('Arial', 10, 'bold'), cursor='hand2',
                  command=clear_pathway).pack(side='left')
        tk.Label(btn_row, text=('Совет: продукт одной реакции = субстрат следующей'
                                if is_ru else 'Tip: one reaction\'s product = next substrate'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 8, 'italic')).pack(side='right')

        redraw_pathway()

    def _cons_run_ko_dialog(self):
        """Gene knockout dialog."""
        if not _ensure_cobra():
            messagebox.showwarning('VIREON', self._t('cobra_not_installed'))
            return
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            return
        # Build model
        model, msg = build_cobra_model_from_circuit(state)
        if model is None:
            messagebox.showerror('VIREON', msg)
            return
        # Get all reaction IDs
        rxn_ids = [r.id for r in model.reactions if not r.id.startswith('EX_')]
        if not rxn_ids:
            messagebox.showinfo('VIREON', 'Нет реакций для нокаута'
                                  if self.lang == 'ru' else 'No reactions to knock out')
            return
        biosim_log('info', 'Running gene knockout simulation')
        results, msg = gene_knockout_simulation(model, rxn_ids)
        if results is None:
            messagebox.showerror('VIREON', msg)
            return
        # Display
        dlg = tk.Toplevel(self)
        dlg.title(self._t('ko_title'))
        dlg.geometry('640x500')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text='' + self._t('ko_title'),
                  bg=biosim_theme('bg'), fg='#cf222e',
                  font=('Arial', 14, 'bold')).pack(pady=10)
        tk.Label(dlg, text=msg, bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 10)).pack()
        txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 9), relief='flat',
                                          highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=14, pady=8)
        txt.insert('end', '{:>30} {:>12} {:>10} {:>10}\n'.format(
            'Reaction', 'Growth', 'Relative', 'Lethal?'))
        txt.insert('end', '─' * 65 + '\n')
        for r in sorted(results, key=lambda x: x['growth_rate']):
            lethal = 'LETHAL' if r['lethal'] else '·'
            txt.insert('end', '{:>30} {:>12.4f} {:>10.1%} {:>10}\n'.format(
                r['knocked_out'][:30], r['growth_rate'],
                r['relative_growth'], lethal))
        txt.config(state='disabled')
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=8)

    def _cons_run_envelope_dialog(self):
        """Production envelope dialog."""
        if not _ensure_cobra():
            messagebox.showwarning('VIREON', self._t('cobra_not_installed'))
            return
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            return
        model, msg = build_cobra_model_from_circuit(state)
        if model is None:
            messagebox.showerror('VIREON', msg)
            return
        # Get product reactions (EX_ that produce, i.e. lb >= 0)
        product_rxns = [r.id for r in model.reactions
                          if r.id.startswith('EX_') and r.lower_bound >= 0]
        if not product_rxns:
            messagebox.showinfo('VIREON', 'Нет реакций-продуктов'
                                  if self.lang == 'ru' else 'No product reactions')
            return
        # Ask user which product
        dlg = tk.Toplevel(self)
        dlg.title(self._t('envelope_title'))
        dlg.geometry('500x250')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text='' + self._t('envelope_title'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 13, 'bold')).pack(pady=10)
        tk.Label(dlg, text=self._t('envelope_product'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(anchor='w', padx=14)
        prod_var = tk.StringVar(value=product_rxns[0])
        ttk.Combobox(dlg, textvariable=prod_var, values=product_rxns,
                      state='readonly').pack(fill='x', padx=14, pady=4)

        def run_env():
            biosim_log('info', 'Computing production envelope')
            results, msg2 = production_envelope(model, prod_var.get(), n_steps=15)
            if results is None:
                messagebox.showerror('VIREON', msg2, parent=dlg)
                return
            # Plot
            plot_dlg = tk.Toplevel(dlg)
            plot_dlg.title(self._t('envelope_title'))
            plot_dlg.geometry('700x500')
            plot_dlg.configure(bg=biosim_theme('bg'))
            fig, ax = plt.subplots(figsize=(7, 4), facecolor='#f5f7fa')
            ax.set_facecolor('#ffffff')
            ax.tick_params(colors='#57606a')
            for sp in ax.spines.values(): sp.set_color('#d0d7de')
            xs = [p[0] for p in results]; ys = [p[1] for p in results]
            ax.plot(xs, ys, color='#8250df', lw=2, marker='o', markersize=5)
            ax.fill_between(xs, 0, ys, color='#8250df', alpha=0.2)
            ax.set_xlabel('Growth rate', color='#57606a')
            ax.set_ylabel('Max ' + prod_var.get() + ' flux', color='#57606a')
            ax.set_title('Production Envelope: ' + prod_var.get(), color='#1c2128')
            ax.grid(True, color='#eef1f5', lw=0.5)
            cv = FigureCanvasTkAgg(fig, master=plot_dlg)
            cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
            tk.Button(plot_dlg, text=self._t('close_btn'),
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       command=plot_dlg.destroy).pack(fill='x', padx=12, pady=6)
            biosim_log('success', 'Production envelope: ' + msg2)
            dlg.destroy()

        tk.Button(dlg, text='▶ ' + self._t('adv_run'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=run_env
                   ).pack(fill='x', padx=14, pady=10)
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=dlg.destroy).pack(fill='x', padx=14, pady=(0, 10))

    def _cons_find_dialog(self):
        """Find a node by name (Ctrl+F)."""
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            return
        dlg = tk.Toplevel(self)
        dlg.title(self._t('find_node'))
        dlg.geometry('420x200')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        try:
            px = self.winfo_rootx() + self.winfo_width() // 2 - 210
            py = self.winfo_rooty() + 100
            dlg.geometry('+{}+{}'.format(max(0, px), max(0, py)))
        except Exception as _exc:
            biosim_log('warn', '_cons_find_dialog: {}'.format(_exc))

        tk.Label(dlg, text='' + self._t('find_node'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 13, 'bold')).pack(pady=(12, 6))
        tk.Label(dlg, text=self._t('find_prompt'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack()

        q_var = tk.StringVar()
        ent = tk.Entry(dlg, textvariable=q_var,
                        bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                        relief='flat', font=('Arial', 12, 'bold'),
                        highlightthickness=2, highlightbackground=biosim_theme('border'),
                        highlightcolor='#0969da', justify='center')
        ent.pack(fill='x', padx=20, pady=8, ipady=4)
        ent.focus_set()

        status = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg='#1a7f37',
                            font=('Arial', 10, 'italic'))
        status.pack(pady=4)

        def find_now(event=None):
            q = q_var.get().strip().lower()
            if not q:
                return
            matches = [n for n in state['nodes'] if q in n['id'].lower()]
            if not matches:
                status.config(text=self._t('find_not_found'), fg='#cf222e')
                return
            status.config(text=self._t('find_found_n').format(len(matches)),
                            fg='#1a7f37')
            # Select matches
            self._cons_selected_nodes = set(n['id'] for n in matches)
            self._cons_refresh()
            biosim_log('info', 'Found {} nodes matching "{}"'.format(len(matches), q))

        ent.bind('<Return>', find_now)

        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=20, pady=8)
        tk.Button(btn_row, text='' + self._t('find_node'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                   command=find_now
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy
                   ).pack(side='right', padx=2)

    def _cons_open_snapshots(self):
        """Open snapshots manager."""
        dlg = tk.Toplevel(self)
        dlg.title(self._t('snapshot_title'))
        dlg.geometry('780x560')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('snapshot_title'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 8))

        # Snapshots list (scrollable)
        list_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        list_frame.pack(fill='both', expand=True, padx=14, pady=4)
        canv = tk.Canvas(list_frame, bg=biosim_theme('bg'), highlightthickness=0)
        sb = tk.Scrollbar(list_frame, orient='vertical', command=canv.yview)
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')
        inner = tk.Frame(canv, bg=biosim_theme('bg'))
        inner.bind('<Configure>',
                    lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=inner, anchor='nw', width=720)

        def refresh_list():
            for w in inner.winfo_children():
                w.destroy()
            snapshots = list_snapshots()
            if not snapshots:
                tk.Label(inner, text=self._t('snapshot_no_snapshots'),
                          bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                          font=('Arial', 11, 'italic')).pack(pady=20)
                return
            for snap in snapshots:
                card = tk.Frame(inner, bg=biosim_theme('panel'), highlightthickness=1,
                                  highlightbackground=biosim_theme('border'))
                card.pack(fill='x', padx=2, pady=4)
                # Title row
                head = tk.Frame(card, bg=biosim_theme('panel'))
                head.pack(fill='x', padx=10, pady=(6, 0))
                tk.Label(head, text='' + snap['name'],
                          bg=biosim_theme('panel'), fg='#8250df',
                          font=('Arial', 11, 'bold')).pack(side='left')
                tk.Label(head, text=snap['timestamp'][:19],
                          bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                          font=('Arial', 9, 'italic')).pack(side='right')
                # Meta
                tk.Label(card,
                          text='{} nodes · {} edges · {:.1f} KB'.format(
                              snap['n_nodes'], snap['n_edges'], snap['size_kb']),
                          bg=biosim_theme('panel'), fg=biosim_theme('text'),
                          font=('Courier', 9)).pack(anchor='w', padx=10, pady=2)
                # Buttons row
                btns = tk.Frame(card, bg=biosim_theme('panel'))
                btns.pack(fill='x', padx=10, pady=(2, 6))

                def make_load(fp):
                    return lambda: load_snap(fp)
                def make_del(fp):
                    return lambda: delete_snap(fp)

                tk.Button(btns, text='' + self._t('snapshot_load'),
                           bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                           font=('Arial', 9, 'bold'), cursor='hand2',
                           padx=10, pady=3,
                           command=make_load(snap['filepath'])
                           ).pack(side='left', padx=4)
                tk.Button(btns, text='' + self._t('snapshot_delete'),
                           bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                           font=('Arial', 9, 'bold'), cursor='hand2',
                           padx=10, pady=3,
                           command=make_del(snap['filepath'])
                           ).pack(side='left', padx=4)

        def load_snap(filepath):
            state, extra, msg = load_project_from_file(filepath)
            if state is None:
                messagebox.showerror('VIREON', msg, parent=dlg)
                return
            self._save_history('constructor')
            if 'constructor' in state:
                self.current_state['constructor'] = state['constructor']
            self._cons_refresh()
            biosim_log('success', 'Loaded snapshot: ' + filepath)
            messagebox.showinfo('VIREON', '' + self._t('snapshot_loaded'), parent=dlg)
            dlg.destroy()

        def delete_snap(filepath):
            if not messagebox.askokcancel('VIREON',
                self._t('snapshot_confirm_delete'), parent=dlg):
                return
            delete_snapshot(filepath)
            biosim_log('info', 'Deleted snapshot: ' + filepath)
            refresh_list()

        def save_new():
            # Custom name dialog
            name_dlg = tk.Toplevel(dlg)
            name_dlg.title(self._t('snapshot_save'))
            name_dlg.geometry('400x180')
            name_dlg.configure(bg=biosim_theme('bg'))
            name_dlg.transient(dlg)
            tk.Label(name_dlg, text=self._t('snapshot_name'),
                      bg=biosim_theme('bg'), fg=biosim_theme('text'), font=('Arial', 11)).pack(pady=10)
            n_var = tk.StringVar()
            ent = tk.Entry(name_dlg, textvariable=n_var,
                            bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                            relief='flat', font=('Arial', 11),
                            highlightthickness=2, highlightbackground=biosim_theme('border'),
                            highlightcolor='#8250df', justify='center')
            ent.pack(fill='x', padx=20, pady=4, ipady=4)
            ent.focus_set()
            def do_save():
                name = n_var.get().strip() or 'snapshot'
                fp, msg = save_snapshot(self.current_state, name,
                                          extra_data={'simulation_history':
                                                      getattr(self, '_simulation_history', [])})
                if fp:
                    biosim_log('success', 'Saved snapshot: ' + name)
                    name_dlg.destroy()
                    refresh_list()
                else:
                    messagebox.showerror('VIREON', msg, parent=name_dlg)

            ent.bind('<Return>', lambda e: do_save())
            btn_row2 = tk.Frame(name_dlg, bg=biosim_theme('bg'))
            btn_row2.pack(fill='x', padx=20, pady=10)
            tk.Button(btn_row2, text='OK', bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                       font=('Arial', 10, 'bold'), cursor='hand2', pady=4,
                       command=do_save
                       ).pack(side='left', fill='x', expand=True, padx=2)
            tk.Button(btn_row2, text='Cancel', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       font=('Arial', 10), cursor='hand2', pady=4,
                       command=name_dlg.destroy
                       ).pack(side='right', padx=2)

        # Initial fill
        refresh_list()

        # Bottom buttons
        bottom = tk.Frame(dlg, bg=biosim_theme('bg'))
        bottom.pack(fill='x', padx=14, pady=10)
        tk.Button(bottom, text=self._t('snapshot_save'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                   command=save_new
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(bottom, text='Refresh',
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                   command=refresh_list
                   ).pack(side='left', padx=2)
        tk.Button(bottom, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=6,
                   command=dlg.destroy
                   ).pack(side='right', padx=2)

    def _cons_export_canvas_image(self):
        """Export current canvas as high-DPI image."""
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return

        dlg = tk.Toplevel(self)
        dlg.title(self._t('export_image_title'))
        dlg.geometry('440x280')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text='' + self._t('export_image_title'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 14, 'bold')).pack(pady=(12, 8))

        # Format
        row1 = tk.Frame(dlg, bg=biosim_theme('bg')); row1.pack(fill='x', padx=14, pady=4)
        tk.Label(row1, text=self._t('export_image_format'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), width=14, anchor='w'
                  ).pack(side='left')
        fmt_var = tk.StringVar(value='png')
        ttk.Combobox(row1, textvariable=fmt_var,
                      values=['png', 'svg', 'pdf', 'ps'],
                      state='readonly', width=10).pack(side='left', padx=4)

        # Scale
        row2 = tk.Frame(dlg, bg=biosim_theme('bg')); row2.pack(fill='x', padx=14, pady=4)
        tk.Label(row2, text=self._t('export_image_scale'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), width=14, anchor='w'
                  ).pack(side='left')
        scale_var = tk.DoubleVar(value=2.0)
        tk.Scale(row2, from_=1.0, to=4.0, resolution=0.5,
                  orient='horizontal', variable=scale_var,
                  bg=biosim_theme('bg'), fg=biosim_theme('text'), highlightthickness=0,
                  troughcolor='#eef1f5', activebackground='#8250df',
                  length=200).pack(side='left', padx=4)

        tk.Label(dlg, text=self._t('export_image_dpi'),
                  bg=biosim_theme('bg'), fg='#0550ae',
                  font=('Arial', 9, 'italic')).pack(pady=4)

        status = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg='#1a7f37',
                            font=('Arial', 9, 'italic'))
        status.pack(pady=2)

        def do_export():
            from tkinter import filedialog
            fmt = fmt_var.get()
            filepath = filedialog.asksaveasfilename(
                defaultextension='.' + fmt,
                filetypes=[(fmt.upper() + ' files', '*.' + fmt),
                            ('All files', '*.*')])
            if not filepath:
                return
            status.config(text='Exporting...', fg='#9a6700')
            dlg.update()
            ok, msg = export_canvas_to_image(self.cons_canvas, filepath, fmt,
                                                scale=safe_float(scale_var.get(), 2.0, minimum=1, maximum=10))
            if ok:
                status.config(text='' + msg, fg='#1a7f37')
                biosim_log('success', 'Exported canvas: ' + filepath)
            else:
                status.config(text='' + msg, fg='#cf222e')
                biosim_log('error', 'Canvas export failed: ' + msg)

        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=10)
        tk.Button(btn_row, text='' + self._t('export_image_title'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                   command=do_export
                   ).pack(side='left', fill='x', expand=True, padx=2)
        tk.Button(btn_row, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=4,
                   command=dlg.destroy
                   ).pack(side='right', padx=2)

    def _cons_export_plotly(self):
        """Export simulation as interactive Plotly HTML."""
        state = self.current_state['constructor']
        if not state or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return
        biosim_log('info', 'Generating Plotly interactive plot...')
        t, y, ids = run_ode_simulation(state['nodes'], state['edges'], state['init'], t_end=100)
        if t is None:
            messagebox.showerror('VIREON', self._t('adv_failed'))
            return
        from tkinter import filedialog
        filepath = filedialog.asksaveasfilename(
            defaultextension='.html',
            filetypes=[('HTML files', '*.html')])
        if not filepath:
            return
        ok, msg = export_simulation_to_plotly_html(
            t, y, ids, filepath, title=state.get('name', 'VIREON Simulation'))
        if ok:
            messagebox.showinfo('VIREON', '' + msg + '\n\n' + filepath)
            biosim_log('success', 'Plotly export: ' + filepath)
            # Try to open in browser
            try:
                import webbrowser
                webbrowser.open('file://' + filepath)
            except Exception as _exc:
                biosim_log('warn', '_cons_export_plotly: {}'.format(_exc))
        else:
            messagebox.showerror('VIREON', msg)
            biosim_log('error', 'Plotly export failed: ' + msg)

