        # Suggested PDB IDs
        tk.Label(dlg, text=('Популярные: 1CRN (crambin), 1HHO (haemoglobin), 1AKE (kinase), 6LZG (SARS-CoV-2 spike)'
                              if self.lang == 'ru' else
                              'Popular: 1CRN (crambin), 1HHO (haemoglobin), 1AKE (kinase), 6LZG (SARS-CoV-2 spike)'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9, 'italic'), wraplength=480).pack(padx=14, pady=4)

        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                                font=('Arial', 10, 'italic'))
        status_lbl.pack(pady=4)

        def load_and_open():
            pdb_id = pdb_var.get().strip().upper()
            if len(pdb_id) != 4:
                status_lbl.config(text='PDB ID должен быть 4 символа' if self.lang == 'ru'
                                   else 'PDB ID must be 4 chars', fg='#cf222e')
                return
            status_lbl.config(text=self._t('pdb_loading'), fg='#9a6700')
            dlg.update()
            html, msg = fetch_pdb_structure_html(pdb_id)
            if html is None:
                status_lbl.config(text=msg, fg='#cf222e')
