    def _cons_run_advanced_sim(self, sim_type):
        """Run a simulation and show graph dialog."""
        state = self.current_state['constructor']
        if state is None or not state['nodes']:
            return
        t_end = 100

        dlg = tk.Toplevel(self)
        dlg.title(self._t('adv_simulation'))
        dlg.geometry('760x520')
        dlg.configure(bg=biosim_theme('bg'))
        type_label = {'ode': self._t('adv_sim_deterministic'),
                       'gillespie': self._t('adv_sim_stochastic'),
                       'tau_leap': self._t('adv_sim_tau_leap')}.get(sim_type, sim_type)
        tk.Label(dlg, text=type_label, bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 14, 'bold')).pack(pady=(10, 4))

        msg_lbl = tk.Label(dlg, text=self._t('adv_running'),
                            bg=biosim_theme('bg'), fg='#9a6700',
                            font=('Arial', 11, 'italic'))
        msg_lbl.pack()
        dlg.update()

        # Run simulation
        try:
            if sim_type == 'ode':
                t, y, ids = run_ode_simulation(state['nodes'], state['edges'], state['init'], t_end=t_end,
                                                events=state.get('events'))
            elif sim_type == 'gillespie':
                t, y, ids = run_gillespie_simulation(state['nodes'], state['edges'], state['init'], t_end=t_end)
            else:  # tau_leap
                t, y, ids = run_tau_leap_simulation(state['nodes'], state['edges'], state['init'], t_end=t_end)
        except Exception as ex:
            biosim_log('warn', '_cons_run_advanced_sim: {}'.format(ex))
            msg_lbl.config(text=self._t('adv_failed') + ': ' + str(ex)[:60], fg='#cf222e')
            return

        if t is None:
            msg_lbl.config(text=self._t('adv_failed'), fg='#cf222e')
            return
        msg_lbl.pack_forget()

        # Plot
        fig, ax = plt.subplots(figsize=(7, 4), facecolor='#f5f7fa')
        ax.set_facecolor('#ffffff')
        ax.tick_params(colors='#57606a')
        for sp in ax.spines.values():
            sp.set_color('#d0d7de')
        colors_list = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df',
                        '#bc4c00', '#0550ae', '#8250df', '#ff9b6e', '#57606a']
        # Identify output/reporter nodes — they get special treatment
        output_nodes = {n['id']: n for n in state['nodes']
                        if n.get('output_type') or n.get('icon') == 'output_reporter'}
        measurements = []  # collect output readings
        for i, nid in enumerate(ids):
            is_output = nid in output_nodes
            if is_output:
                # Reporters drawn as thick dashed lines (the measured signal)
                ax.plot(t, y[:, i], color='#1a7f37', lw=3.0, linestyle='--',
                         label='' + nid, alpha=1.0, zorder=10)
                # Compute measurement based on output type
                otype = output_nodes[nid].get('output_type', 'concentration')
                series = y[:, i]
                final_val = float(series[-1])
                peak_val = float(max(series))
                if otype == 'integral':
                    import numpy as _np
                    val = float(_np.trapz(series, t))
                    measurements.append((nid, 'Накопление/Integral', round(val, 2)))
                elif otype == 'rate':
                    rate = (series[-1] - series[-2]) / (t[-1] - t[-2]) if len(t) > 1 else 0
                    measurements.append((nid, 'Скорость/Rate', round(rate, 3)))
                elif otype == 'threshold':
                    thr = 0.5 * peak_val
                    crossed = 'ДА/YES' if peak_val > thr else 'НЕТ/NO'
                    measurements.append((nid, 'Порог/Threshold', crossed))
                else:  # fluorescence, concentration, ratio
                    measurements.append((nid, otype, round(final_val, 3)))
            else:
                ax.plot(t, y[:, i], color=colors_list[i % len(colors_list)], lw=1.6,
                         label=nid, alpha=0.9)
        ax.set_xlabel('time', color='#57606a')
        ax.set_ylabel('concentration', color='#57606a')
        ax.set_title(type_label, color='#1c2128')
        ax.legend(facecolor='#eef1f5', edgecolor='#d0d7de',
                   labelcolor='#1c2128', fontsize=8, ncol=2)
        ax.grid(True, color='#eef1f5', lw=0.5)
        cv = FigureCanvasTkAgg(fig, master=dlg)
        cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)

        # ── Checkboxes to show/hide each line ──
        toggle_frame = tk.LabelFrame(dlg, text=('Показать линии (галочка = видна)'
                                                 if self.lang == 'ru' else
                                                 'Show lines (checked = visible)'),
                                      bg=biosim_theme('panel'), fg='#0969da',
                                      font=('Arial', 9, 'bold'), relief='solid', bd=1)
        toggle_frame.pack(fill='x', padx=10, pady=(0, 4))
        toggle_inner = tk.Frame(toggle_frame, bg=biosim_theme('panel'))
        toggle_inner.pack(fill='x', padx=4, pady=4)
        # Map node id -> line object
        line_map = {}
        for line in ax.get_lines():
            line_map[line.get_label()] = line
        self._sim_line_vars = {}

        def redraw_lines():
            for nid_key, var in self._sim_line_vars.items():
                ln = line_map.get(nid_key)
                if ln is not None:
                    ln.set_visible(var.get())
            # Rebuild legend with only visible lines
            visible_lines = [ln for ln in ax.get_lines() if ln.get_visible()]
            visible_labels = [ln.get_label() for ln in visible_lines]
            if visible_lines:
                ax.legend(visible_lines, visible_labels, facecolor='#eef1f5',
                          edgecolor='#d0d7de', labelcolor='#1c2128', fontsize=8, ncol=2)
            cv.draw()

        # Create a checkbox per line (in a wrapping grid)
        col = 0; row = 0
        for nid in ids:
            var = tk.BooleanVar(value=True)
            self._sim_line_vars[nid] = var
            cb = tk.Checkbutton(toggle_inner, text=nid[:16], variable=var,
                                 bg=biosim_theme('panel'), fg=biosim_theme('text'), font=('Arial', 8),
                                 selectcolor='#eef1f5', activebackground='#ffffff',
                                 command=redraw_lines, anchor='w')
            cb.grid(row=row, column=col, sticky='w', padx=4)
            col += 1
            if col >= 4:  # 4 per row
                col = 0; row += 1

        # Show output/reporter measurements if any
        if measurements:
            is_ru = (self.lang == 'ru')
            mf = tk.Frame(dlg, bg=biosim_theme('panel'))
            mf.pack(fill='x', padx=10, pady=4)
            tk.Label(mf, text=('Показания выходов:' if is_ru else 'Output readings:'),
                      bg=biosim_theme('panel'), fg='#1a7f37', font=('Arial', 10, 'bold')).pack(anchor='w', padx=8, pady=2)
            for nid, mtype, val in measurements:
                tk.Label(mf, text='   {} ({}) = {}'.format(nid, mtype, val),
                          bg=biosim_theme('panel'), fg=biosim_theme('text'), font=('Courier', 9)).pack(anchor='w', padx=12)

        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11), cursor='hand2',
                   command=dlg.destroy).pack(fill='x', padx=12, pady=8)

    def _cons_show_steady_state(self):
        state = self.current_state['constructor']
        ss, ids = compute_steady_state(state['nodes'], state['edges'], state['init'])
        if ss is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        msg = self._t('adv_steady_get') + '\n' + '-' * 30 + '\n'
        for nid, val in zip(ids, ss):
            msg += '  {:>12} = {:.4f}\n'.format(nid[:12], val)
        self._show_text_dialog(self._t('adv_steady_get'), msg)

    def _cons_show_jacobian(self):
        state = self.current_state['constructor']
        J, ids = compute_jacobian_at_ss(state['nodes'], state['edges'], state['init'])
        if J is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        # Format as table
        msg = 'Jacobian J[i, j] = ∂f_i/∂y_j\n' + '-' * 50 + '\n\n'
        # Header
        msg += ' ' * 10
        for nid in ids:
            msg += '{:>10}'.format(nid[:9])
        msg += '\n'
        for i, nid in enumerate(ids):
            msg += '{:>10}'.format(nid[:9])
            for j in range(len(ids)):
                msg += '{:>10.3f}'.format(J[i, j])
            msg += '\n'
        self._show_text_dialog(self._t('adv_jacobian'), msg)

    def _cons_show_eigenvalues(self):
        state = self.current_state['constructor']
        eigs, J, ids = compute_eigenvalues(state['nodes'], state['edges'], state['init'])
        if eigs is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        # Format
        msg = self._t('adv_eigenvalues') + '\n' + '-' * 30 + '\n\n'
        all_real_negative = all(e.real < 0 for e in eigs)
        any_complex = any(abs(e.imag) > 1e-6 for e in eigs)
        for i, e in enumerate(eigs):
            if abs(e.imag) < 1e-6:
                msg += '  λ_{} = {:>10.4f}\n'.format(i + 1, e.real)
            else:
                msg += '  λ_{} = {:>10.4f}{:+10.4f}i\n'.format(i + 1, e.real, e.imag)
        msg += '\n'
        if all_real_negative and not any_complex:
            msg += '' + self._t('adv_eigenvalue_stable') + '\n'
        elif all_real_negative and any_complex:
            msg += '~ ' + self._t('adv_eigenvalue_oscillating') + '\n'
        else:
            msg += '' + self._t('adv_eigenvalue_unstable') + '\n'
        self._show_text_dialog(self._t('adv_eigenvalues'), msg)

    def _cons_param_scan_1d(self):
        """Interactive: pick node and parameter, then scan."""
        state = self.current_state['constructor']
        if not state['nodes']:
            return
        node_ids = [n['id'] for n in state['nodes']]
        # Dialog to pick node + param
        dlg = tk.Toplevel(self)
        dlg.title(self._t('adv_param_scan'))
        dlg.geometry('500x400')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text=self._t('adv_param_scan'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 13, 'bold')).pack(pady=8)
        # Node selector
        tk.Label(dlg, text=self._t('adv_pick_node'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 10)).pack(anchor='w', padx=12)
        node_var = tk.StringVar(value=node_ids[0])
        ttk.Combobox(dlg, textvariable=node_var, values=node_ids,
                      state='readonly', font=('Arial', 10)).pack(fill='x', padx=12)
        # Param selector
        tk.Label(dlg, text=self._t('adv_pick_param'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 10)).pack(anchor='w', padx=12, pady=(8, 0))
        param_var = tk.StringVar(value='production')
        ttk.Combobox(dlg, textvariable=param_var,
                      values=['production', 'degradation', 'initial'],
                      state='readonly', font=('Arial', 10)).pack(fill='x', padx=12)
        # Range
        row = tk.Frame(dlg, bg=biosim_theme('bg')); row.pack(fill='x', padx=12, pady=4)
        tk.Label(row, text=self._t('adv_range_min'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left')
        min_var = tk.DoubleVar(value=0.1)
        tk.Entry(row, textvariable=min_var, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'), relief='flat').pack(side='left', padx=4)
        tk.Label(row, text=self._t('adv_range_max'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left', padx=(8, 0))
        max_var = tk.DoubleVar(value=5.0)
        tk.Entry(row, textvariable=max_var, width=8, bg=biosim_theme('panel2'), fg=biosim_theme('text'), relief='flat').pack(side='left', padx=4)
        tk.Label(row, text=self._t('adv_steps'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(side='left', padx=(8, 0))
        steps_var = tk.IntVar(value=20)
        tk.Entry(row, textvariable=steps_var, width=4, bg=biosim_theme('panel2'), fg=biosim_theme('text'), relief='flat').pack(side='left', padx=4)

        def run_scan():
            nm = node_var.get()
            pm = param_var.get()
            mn = safe_float(min_var.get(), 0.0); mx = safe_float(max_var.get(), 1.0); st = safe_int(steps_var.get(), 10, minimum=2, maximum=100)
            results, pvals = parameter_scan_1d(state['nodes'], state['edges'], state['init'],
                                                  nm, pm, mn, mx, st)
            # Plot
            plot_dlg = tk.Toplevel(self)
            plot_dlg.title(self._t('adv_param_scan'))
            plot_dlg.geometry('700x500')
            plot_dlg.configure(bg=biosim_theme('bg'))
            tk.Label(plot_dlg,
                      text='{} ({})   {} '.format(nm, pm, self._t('adv_steady_get')),
                      bg=biosim_theme('bg'), fg='#0969da',
                      font=('Arial', 12, 'bold')).pack(pady=8)
            fig, ax = plt.subplots(figsize=(7, 4), facecolor='#f5f7fa')
            ax.set_facecolor('#ffffff')
            ax.tick_params(colors='#57606a')
            for sp in ax.spines.values(): sp.set_color('#d0d7de')
            # Collect series per node
            if results:
                ids_first = [k for k in results[0][1].keys()] if results[0][1] else node_ids
                colors_list = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df']
                for idx, target in enumerate(ids_first):
                    series = [(p, r[target]) for p, r in results if r and target in r]
                    if series:
                        xs = [p for p, _ in series]; ys = [v for _, v in series]
                        ax.plot(xs, ys, color=colors_list[idx % len(colors_list)],
                                 lw=1.8, label=target, marker='o', markersize=3)
            ax.set_xlabel(pm + ' of ' + nm, color='#57606a')
            ax.set_ylabel('steady-state concentration', color='#57606a')
            ax.legend(facecolor='#eef1f5', edgecolor='#d0d7de',
                       labelcolor='#1c2128', fontsize=9)
            ax.grid(True, color='#eef1f5', lw=0.5)
            cv = FigureCanvasTkAgg(fig, master=plot_dlg)
            cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
            tk.Button(plot_dlg, text=self._t('close_btn'),
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       command=plot_dlg.destroy).pack(fill='x', padx=12, pady=8)
            dlg.destroy()

        tk.Button(dlg, text=self._t('adv_run'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=run_scan).pack(fill='x', padx=12, pady=10)

    def _cons_param_scan_2d(self):
        """2D parameter scan as heatmap."""
        state = self.current_state['constructor']
        node_ids = [n['id'] for n in state['nodes']]
        if len(node_ids) < 2:
            messagebox.showinfo('VIREON', 'Нужно минимум 2 узла' if self.lang == 'ru' else 'Need at least 2 nodes')
            return

        dlg = tk.Toplevel(self)
        dlg.title(self._t('adv_param_scan_2d'))
        dlg.geometry('480x420')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text=self._t('adv_param_scan_2d'),
                  bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 13, 'bold')).pack(pady=8)

        tk.Label(dlg, text='Параметр A (X):' if self.lang == 'ru' else 'Parameter A (X):',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(anchor='w', padx=12)
        a_node = tk.StringVar(value=node_ids[0])
        ttk.Combobox(dlg, textvariable=a_node, values=node_ids,
                      state='readonly').pack(fill='x', padx=12)
        a_param = tk.StringVar(value='production')
        ttk.Combobox(dlg, textvariable=a_param, values=['production', 'degradation'],
                      state='readonly').pack(fill='x', padx=12, pady=2)

        tk.Label(dlg, text='Параметр B (Y):' if self.lang == 'ru' else 'Parameter B (Y):',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(anchor='w', padx=12, pady=(8, 0))
        b_node = tk.StringVar(value=node_ids[1] if len(node_ids) > 1 else node_ids[0])
        ttk.Combobox(dlg, textvariable=b_node, values=node_ids,
                      state='readonly').pack(fill='x', padx=12)
        b_param = tk.StringVar(value='production')
        ttk.Combobox(dlg, textvariable=b_param, values=['production', 'degradation'],
                      state='readonly').pack(fill='x', padx=12, pady=2)

        tk.Label(dlg, text='Целевой узел (цвет):' if self.lang == 'ru' else 'Target node (color):',
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim')).pack(anchor='w', padx=12, pady=(8, 0))
        target_var = tk.StringVar(value=node_ids[0])
        ttk.Combobox(dlg, textvariable=target_var, values=node_ids,
                      state='readonly').pack(fill='x', padx=12)

        def run_scan():
            mn = 0.1; mx = 5.0; st = 12  # smaller grid for speed
            grid, av, bv = parameter_scan_2d(state['nodes'], state['edges'], state['init'],
                                                a_node.get(), a_param.get(),
                                                b_node.get(), b_param.get(),
                                                mn, mx, mn, mx,
                                                target_var.get(), n_steps=st)
            plot_dlg = tk.Toplevel(self)
            plot_dlg.title(self._t('adv_param_scan_2d'))
            plot_dlg.geometry('640x540')
            plot_dlg.configure(bg=biosim_theme('bg'))
            fig, ax = plt.subplots(figsize=(6, 5), facecolor='#f5f7fa')
            ax.set_facecolor('#ffffff')
            im = ax.imshow(grid, origin='lower', cmap='viridis', aspect='auto',
                            extent=[bv[0], bv[-1], av[0], av[-1]])
            cb = plt.colorbar(im, ax=ax)
            cb.set_label(target_var.get(), color='#1c2128')
            cb.ax.yaxis.set_tick_params(color='#57606a')
            for tlbl in cb.ax.get_yticklabels():
                tlbl.set_color('#57606a')
            ax.set_xlabel(b_node.get() + ' ' + b_param.get(), color='#57606a')
            ax.set_ylabel(a_node.get() + ' ' + a_param.get(), color='#57606a')
            ax.tick_params(colors='#57606a')
            for sp in ax.spines.values(): sp.set_color('#d0d7de')
            cv = FigureCanvasTkAgg(fig, master=plot_dlg)
            cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
            tk.Button(plot_dlg, text=self._t('close_btn'),
                       bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                       command=plot_dlg.destroy).pack(fill='x', padx=12, pady=8)
            dlg.destroy()

        tk.Button(dlg, text=self._t('adv_run'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=run_scan).pack(fill='x', padx=12, pady=10)

    def _cons_show_stoich(self):
        state = self.current_state['constructor']
        N, ids = build_stoichiometry_matrix(state['nodes'], state['edges'])
        msg = 'Stoichiometry matrix N[species, reaction]\n' + '-' * 50 + '\n\n'
        msg += '{:>8}'.format('')
        for j in range(len(state['edges'])):
            msg += '{:>5}'.format('r' + str(j))
        msg += '\n'
        for i, nid in enumerate(ids):
            msg += '{:>8}'.format(nid[:7])
            for j in range(N.shape[1]):
                msg += '{:>5.0f}'.format(N[i, j])
            msg += '\n'
        self._show_text_dialog(self._t('adv_stoich_matrix'), msg)

    def _cons_show_centrality(self):
        state = self.current_state['constructor']
        c = compute_centrality(state['nodes'], state['edges'])
        msg = self._t('adv_centrality') + '\n' + '-' * 30 + '\n\n'
        msg += '{:>12} {:>8} {:>8} {:>8}\n'.format('node', 'in', 'out', 'total')
        for nid in sorted(c['total_degree'].keys(),
                           key=lambda x: -c['total_degree'][x]):
            msg += '{:>12} {:>8} {:>8} {:>8}\n'.format(
                nid[:11], c['in_degree'][nid], c['out_degree'][nid], c['total_degree'][nid])
        self._show_text_dialog(self._t('adv_centrality'), msg)

    def _cons_show_perturbation(self):
        state = self.current_state['constructor']
        results, ids = perturbation_knockouts(state['nodes'], state['edges'], state['init'])
        if results is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        msg = self._t('adv_perturbation') + '\n' + '-' * 50 + '\n\n'
        for ko_node, effects in results:
            msg += self._t('adv_node_ko') + ' ' + ko_node + '\n'
            if effects:
                for nid, (val, rel) in effects.items():
                    sign = '+' if rel > 0 else ''
                    msg += '  {:>10}: {:.3f} ({}{:.1%})\n'.format(nid[:10], val, sign, rel)
            else:
                msg += '  (нет эффекта)\n' if self.lang == 'ru' else '  (no effect)\n'
            msg += '\n'
        self._show_text_dialog(self._t('adv_perturbation'), msg)

    def _cons_show_sensitivity(self):
        state = self.current_state['constructor']
        sens, ids = sensitivity_analysis(state['nodes'], state['edges'], state['init'])
        if sens is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        # Aggregate
        msg = self._t('adv_sensitivity') + '\n' + '-' * 50 + '\n\n'
        msg += 'S(node, param target) = (∂SS_target / ∂param) · (param/SS_target)\n\n'
        for src, param, target, s in sorted(sens, key=lambda x: -abs(x[3]))[:30]:
            msg += '  {:>10} ({:>4}) {:>10}: {:>8.3f}\n'.format(
                src[:10], param[:4], target[:10], s)
        self._show_text_dialog(self._t('adv_sensitivity'), msg)

    def _cons_show_mca(self):
        """Metabolic Control Analysis — flux/concentration control coefficients."""
        state = self.current_state['constructor']
        results, ids = metabolic_control_analysis(state['nodes'], state['edges'], state['init'])
        if results is None or not results:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        ru = (self.lang == 'ru')
        title = 'Анализ метаболического контроля (MCA)' if ru else 'Metabolic Control Analysis (MCA)'
        msg = title + '\n' + '-' * 50 + '\n\n'
        msg += ('Коэффициент контроля C = (ΔX/X)/(Δp/p)\n'
                'Показывает насколько узел контролирует мишень.\n'
                'Близко к 1 — сильный контроль, к 0 — слабый.\n\n') if ru else (
                'Control coefficient C = (ΔX/X)/(Δp/p)\n'
                'How strongly each node controls a target.\n'
                'Near 1 = strong control, near 0 = weak.\n\n')
        header = ('   управляющий →  мишень :  коэффициент\n' if ru
                  else '   controller  →  target :  coefficient\n')
        msg += header + '  ' + '-' * 44 + '\n'
        for r in sorted(results, key=lambda x: -abs(x['control_coef']))[:30]:
            msg += '  {:>10} → {:>10} : {:>8.3f}\n'.format(
                r['param_node'][:10], r['target'][:10], r['control_coef'])
        # Also show elasticities
        el = elasticity_coefficients(state['nodes'], state['edges'], state['init'])
        if el:
            msg += '\n' + ('Эластичности (ε):' if ru else 'Elasticities (ε):') + '\n'
            for e in el[:15]:
                msg += '  {:>10} : {:>8.3f}\n'.format(e['node'][:10], e['elasticity'])
        self._show_text_dialog(title, msg)

    def _cons_show_conservation(self):
        """Show conserved moieties (conservation laws) in the network."""
        state = self.current_state['constructor']
        laws = conservation_analysis(state['nodes'], state['edges'])
        ru = (self.lang == 'ru')
        title = 'Законы сохранения' if ru else 'Conservation Laws'
        if not laws:
            msg = (title + '\n' + '-' * 50 + '\n\n' +
                   ('В этой сети не найдено сохраняющихся комбинаций.\n'
                    'Это нормально для сетей с производством и деградацией.\n'
                    'Законы сохранения появляются когда вещество только\n'
                    'превращается (напр. фермент ↔ комплекс).' if ru else
                    'No conserved moieties found in this network.\n'
                    'This is normal for networks with production/degradation.\n'
                    'Conservation laws appear when matter only converts\n'
                    '(e.g. enzyme ↔ complex).'))
        else:
            msg = title + '\n' + '-' * 50 + '\n\n'
            msg += ('Найдены сохраняющиеся комбинации:\n\n' if ru
                    else 'Conserved moieties found:\n\n')
            for i, law in enumerate(laws, 1):
                msg += f'  {i}. {law}\n'
        self._show_text_dialog(title, msg)

    def _cons_show_pops_rips(self):
        """Show PoPS/RiPS (polymerase/ribosome per second) for each gene."""
        state = self.current_state['constructor']
        ru = (self.lang == 'ru')
        nodes = state['nodes']; edges = state['edges']
        if not nodes:
            messagebox.showinfo('VIREON', self._t('adv_no_state'))
            return
        nodes_by_id = {n['id']: n for n in nodes}
        title = 'PoPS / RiPS (потоки)' if ru else 'PoPS / RiPS (fluxes)'
        msg = title + '\n' + '-' * 50 + '\n\n'
        msg += (('PoPS = поток полимеразы (активность промотора)\n'
                 'RiPS = поток рибосом (трансляция)\n'
                 'Стандартные единицы BioBrick для композиции частей.\n\n')
                if ru else
                ('PoPS = polymerase flux (promoter activity)\n'
                 'RiPS = ribosome flux (translation)\n'
                 'Standard BioBrick units for composing parts.\n\n'))
        msg += '{:>16} {:>10} {:>10}\n'.format(
            ('Ген' if ru else 'Gene'), 'PoPS', 'RiPS')
        msg += '  ' + '-' * 38 + '\n'
        for n in nodes:
            r = calculate_pops_rips(n, edges, nodes_by_id)
            msg += '{:>16} {:>10.3f} {:>10.3f}\n'.format(
                r['node'][:16], r['PoPS'], r['RiPS'])
        self._show_text_dialog(title, msg)

    def _cons_show_plasmid_compat(self):
        """Check plasmid compatibility (antibiotic markers + origins)."""
        ru = (self.lang == 'ru')
        # Simple dialog to pick markers and origins
        dlg = tk.Toplevel(self)
        dlg.title('Plasmid compatibility')
        dlg.geometry('480x520')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        tk.Label(dlg, text=('Совместимость плазмид' if ru else 'Plasmid Compatibility'),
                  bg=biosim_theme('bg'), fg='#0969da', font=('Arial', 13, 'bold')).pack(pady=(12, 4))
        tk.Label(dlg, text=('Отметьте плазмиды (маркер + origin):' if ru
                            else 'Check plasmids (marker + origin):'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9)).pack()

        # Build a few plasmid rows
        plasmid_rows = []
        marker_keys = list(ANTIBIOTIC_MARKERS.keys())
        ori_keys = list(ORI_GROUPS.keys())
        rows_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        rows_frame.pack(fill='x', padx=14, pady=8)
        for i in range(4):
            row = tk.Frame(rows_frame, bg=biosim_theme('bg'))
            row.pack(fill='x', pady=3)
            use_var = tk.BooleanVar(value=(i < 2))
            tk.Checkbutton(row, variable=use_var, bg=biosim_theme('bg')).pack(side='left')
            tk.Label(row, text=('Плазмида' if ru else 'Plasmid') + f' {i+1}:',
                      bg=biosim_theme('bg'), fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left')
            mvar = tk.StringVar(value=marker_keys[i % len(marker_keys)])
            ttk.Combobox(row, textvariable=mvar, values=marker_keys,
                         state='readonly', width=8).pack(side='left', padx=4)
            ovar = tk.StringVar(value=ori_keys[i % len(ori_keys)])
            ttk.Combobox(row, textvariable=ovar, values=ori_keys,
                         state='readonly', width=10).pack(side='left', padx=4)
            plasmid_rows.append((use_var, mvar, ovar))

        result_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg=biosim_theme('text'),
                               font=('Arial', 10), wraplength=440, justify='left')
        result_lbl.pack(fill='x', padx=14, pady=8)

        def check():
            markers = []; oris = []
            for use_var, mvar, ovar in plasmid_rows:
                if use_var.get():
                    markers.append(mvar.get()); oris.append(ovar.get())
            if len(markers) < 2:
                result_lbl.config(text=('Отметьте минимум 2 плазмиды' if ru
                                        else 'Check at least 2 plasmids'), fg='#9a6700')
                return
            r = check_plasmid_compatibility(markers, oris)
            if r['compatible']:
                result_lbl.config(text=('✓ Плазмиды СОВМЕСТИМЫ — могут сосуществовать '
                                        'в одной клетке.' if ru
                                        else '✓ Plasmids COMPATIBLE — can coexist '
                                        'in the same cell.'), fg='#1a7f37')
            else:
                txt = ('✗ НЕСОВМЕСТИМЫ:\n' if ru else '✗ INCOMPATIBLE:\n')
                txt += '\n'.join('• ' + w for w in r['warnings'])
                result_lbl.config(text=txt, fg='#cf222e')

        tk.Button(dlg, text=('▶ Проверить' if ru else '▶ Check'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                   relief='flat', font=('Arial', 10, 'bold'), cursor='hand2',
                   command=check).pack(fill='x', padx=14, pady=8)

    def _cons_show_monte_carlo(self):
        state = self.current_state['constructor']
        dist, ids = monte_carlo_random_params(state['nodes'], state['edges'], state['init'],
                                                n_samples=50, variation=0.3)
        if dist is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        # Plot histogram per node
        plot_dlg = tk.Toplevel(self)
        plot_dlg.title(self._t('adv_random_params'))
        plot_dlg.geometry('720x520')
        plot_dlg.configure(bg=biosim_theme('bg'))
        n_subplots = min(6, len(ids))
        fig, axes = plt.subplots(n_subplots, 1, figsize=(7, 1.5 * n_subplots),
                                   facecolor='#f5f7fa')
        if n_subplots == 1:
            axes = [axes]
        colors_list = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df', '#bc4c00']
        for i, nid in enumerate(ids[:n_subplots]):
            ax = axes[i]
            vals = dist[nid]
            ax.hist(vals, bins=15, color=colors_list[i % len(colors_list)], alpha=0.7)
            ax.set_facecolor('#ffffff')
            ax.tick_params(colors='#57606a', labelsize=8)
            for sp in ax.spines.values(): sp.set_color('#d0d7de')
            ax.set_ylabel(nid[:10], color='#1c2128', fontsize=9)
            ax.grid(True, color='#eef1f5', lw=0.5)
        axes[-1].set_xlabel('steady-state value', color='#57606a')
        fig.tight_layout()
        cv = FigureCanvasTkAgg(fig, master=plot_dlg)
        cv.get_tk_widget().pack(fill='both', expand=True, padx=10, pady=4)
        tk.Button(plot_dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   command=plot_dlg.destroy).pack(fill='x', padx=12, pady=6)

    def _cons_show_equations(self):
        state = self.current_state['constructor']
        text = generate_ode_equations_text(state['nodes'], state['edges'], lang=self.lang)
        self._show_text_dialog(self._t('adv_equations'), text)

    def _toggle_dock_info(self, info_frame, home_parent):
        """Dock/Undock the info panel. Tkinter can't reliably re-parent an
        existing widget, so undocking hides the docked panel and opens a
        floating window that mirrors the same info text; re-docking closes the
        float and restores the panel. Content stays in sync via _cons_refresh."""
        is_ru = (self.lang == 'ru')
        if getattr(self, '_info_docked', True):
            # UNDOCK: hide docked panel, open floating mirror window
            win = tk.Toplevel(self)
            win.title('Информация' if is_ru else 'Info')
            win.geometry('320x480')
            win.configure(bg=biosim_theme('bg'))
            self._info_float_win = win

            float_info = scrolledtext.ScrolledText(
                win, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                font=('Arial', 9), relief='flat', wrap='word',
                state='disabled', highlightthickness=0)
            float_info.pack(fill='both', expand=True, padx=6, pady=6)
            for tag, fg, fnt in [
                ('ttl', '#0969da', ('Arial', 10, 'bold')),
                ('ok', '#1a7f37', ('Arial', 9)),
                ('wrn', '#9a6700', ('Arial', 9)),
                ('bad', '#cf222e', ('Arial', 9)),
                ('nrm', '#1c2128', ('Arial', 9)),
                ('dim', '#57606a', ('Arial', 8)),
            ]:
                float_info.tag_config(tag, foreground=fg, font=fnt)
            # Copy current content across
            try:
                content = self.cons_info.get('1.0', 'end-1c')
                float_info.configure(state='normal')
                float_info.insert('1.0', content)
                float_info.configure(state='disabled')
            except Exception:
                pass
            # Redirect future info updates to the floating widget
            self._cons_info_docked_widget = self.cons_info
            self.cons_info = float_info
            # Hide the docked panel body (keep the dock button row visible)
            try:
                self._cons_info_docked_widget.pack_forget()
            except Exception:
                pass
            info_frame.config(
                text=('Информация (отделена)' if is_ru else 'Info (undocked)'))
            self._info_docked = False
            self._info_dock_btn.config(text=('⧈ Прикрепить' if is_ru else '⧈ Dock'))
            self._cons_refresh()

            win.protocol('WM_DELETE_WINDOW',
                         lambda: self._redock_info(info_frame, home_parent))
        else:
            self._redock_info(info_frame, home_parent)

    def _redock_info(self, info_frame, home_parent):
        """Restore the docked info panel and close the floating window."""
        is_ru = (self.lang == 'ru')
        # Restore the original docked widget as the active info target
        if getattr(self, '_cons_info_docked_widget', None) is not None:
            self.cons_info = self._cons_info_docked_widget
            try:
                self.cons_info.pack(fill='both', expand=True, padx=4, pady=4)
            except Exception:
                pass
        if getattr(self, '_info_float_win', None) is not None:
            try:
                self._info_float_win.destroy()
            except Exception:
                pass
            self._info_float_win = None
        try:
            info_frame.config(text=self._t('cons_info_title'))
        except Exception:
            pass
        self._info_docked = True
        try:
            self._info_dock_btn.config(text=('⧉ Отделить' if is_ru else '⧉ Undock'))
        except Exception:
            pass
        self._cons_refresh()

    def _cons_open_python_console(self):
        """Embedded Python console with access to the current model. Scientists
        can inspect/modify the circuit and run analyses programmatically, like
        TinkerCell's console. Variables available: state, nodes, edges, init,
        np, run_sim(), refresh()."""
        state = self.current_state['constructor']
        if state is None:
            return
        is_ru = (self.lang == 'ru')
        dlg = tk.Toplevel(self)
        dlg.title('Python-консоль' if is_ru else 'Python console')
        dlg.geometry('720x520')
        dlg.configure(bg='#0d1117')
        dlg.transient(self)

        header = ('# Доступно: state, nodes, edges, init, np\n'
                  '# Построить схему: add_part(key,x,y), add_edge(src,dst,type), '
                  'clear_canvas(), list_parts()\n'
                  '# Запуск/обновление: run_sim(), refresh()\n'
                  '# Части: promoter_strong/medium/weak/inducible, rbs_strong/weak, '
                  'cds_generic, terminator, binding_act, binding_rep\n'
                  '# После построения вызови refresh() чтобы увидеть узлы на холсте.\n'
                  if is_ru else
                  '# Available: state, nodes, edges, init, np\n'
                  '# Build a circuit: add_part(key,x,y), add_edge(src,dst,type), '
                  'clear_canvas(), list_parts()\n'
                  '# Run/redraw: run_sim(), refresh()\n'
                  '# Parts: promoter_strong/medium/weak/inducible, rbs_strong/weak, '
                  'cds_generic, terminator, binding_act, binding_rep\n'
                  '# After building, call refresh() to see nodes on the canvas.\n')

        out = tk.Text(dlg, wrap='word', bg='#0d1117', fg='#e6edf3',
                       insertbackground='#e6edf3', font=('Consolas', 10),
                       relief='flat', height=20)
        out.pack(fill='both', expand=True, padx=8, pady=(8, 4))
        out.insert('end', header)
        out.configure(state='disabled')

        input_row = tk.Frame(dlg, bg='#0d1117')
        input_row.pack(fill='x', padx=8, pady=(0, 8))
        tk.Label(input_row, text='>>>', bg='#0d1117', fg='#1a7f37',
                  font=('Consolas', 11, 'bold')).pack(side='top', anchor='w')
        # Multiline input so a whole script can be pasted and run at once.
        # Enter inserts a newline; the "Run" button (or Ctrl+Enter) executes.
        entry = tk.Text(input_row, bg='#161b22', fg='#e6edf3',
                        insertbackground='#e6edf3', font=('Consolas', 11),
                        relief='flat', highlightthickness=1, height=6,
                        highlightbackground='#30363d', wrap='none')
        entry.pack(side='top', fill='both', expand=True, padx=0, pady=(2, 0))
        entry.focus_set()

        history = []
        hist_idx = [0]

        def write(text, color='#e6edf3'):
            out.configure(state='normal')
            out.insert('end', text)
            out.see('end')
            out.configure(state='disabled')

        # Persistent namespace for the console session
        import numpy as _np
        def run_sim():
            t, y, ids = run_ode_simulation(state['nodes'], state['edges'],
                                            state['init'], t_end=100)
            if t is None:
                return 'simulation failed'
            final = {ids[i]: round(float(y[-1, i]), 4) for i in range(len(ids))}
            return 'final: ' + repr(final)

        # ── Builder helpers so pasted code can CREATE VISIBLE nodes on the
        #    canvas (not just poke the raw lists). Each returns the node id.
        def add_part(part_key, x=None, y=None, node_id=None, init=None,
                     production=None, degradation=None):
            """Add a catalog part (e.g. 'promoter_strong', 'cds_generic',
            'rbs_strong', 'terminator') as a real, drawn node. Optional
            node_id renames it; init/production/degradation override defaults.
            Returns the node's id."""
            pdata = CIRCUIT_PARTS_CATALOG.get(part_key)
            if not pdata:
                raise ValueError('unknown part_key: ' + repr(part_key)
                                 + '. Try promoter_strong / promoter_medium / '
                                 'promoter_weak / promoter_inducible / '
                                 'rbs_strong / rbs_weak / cds_generic / '
                                 'terminator / binding_act / binding_rep')
            existing = [n['id'] for n in state['nodes']]
            base = (node_id or ''.join(c for c in
                    pdata.get('name_en', part_key).split()[0][:6] if c.isalnum())
                    or 'X')
            nid = base; c = 1
            while nid in existing:
                nid = base + str(c); c += 1
            # simple auto-layout if x/y not given: lay parts left→right
            if x is None:
                x = 120 + 90 * len(state['nodes'])
            if y is None:
                y = 200
            node = {
                'id': nid, 'x': x, 'y': y, 'part_key': part_key,
                'icon': pdata['icon'], 'color': pdata['color'],
                'production': (pdata.get('production', 1.0) if production is None
                              else production),
                'degradation': (pdata.get('degradation', 0.1) if degradation is None
                               else degradation),
                'gene_symbol': None, 'sequence': None,
                'is_generic': pdata.get('is_generic', False),
                'is_knockout': pdata.get('is_knockout', False),
            }
            state['nodes'].append(node)
            state['init'][nid] = (pdata.get('initial', 0.5) if init is None else init)
            return nid

        def add_edge(src, dst, type='activation', strength=3.0, hill_n=2.0,
                     **kw):
            """Connect two nodes. type: 'activation' | 'repression' |
            'conversion' | 'transport' | 'catalysis' ... For a gene circuit
            use 'activation'/'repression'. Returns the edge dict."""
            e = {'from': src, 'to': dst, 'type': type,
                 'strength': float(strength), 'hill_n': float(hill_n)}
            e.update(kw)
            state['edges'].append(e)
            return e

        def clear_canvas():
            """Remove every node and edge from the current canvas."""
            state['nodes'].clear()
            state['edges'].clear()
            state['init'].clear()
            if state.get('chains'):
                state['chains'].clear()
            self._cons_refresh()
            return 'canvas cleared'

        def list_parts():
            """Print available catalog part keys you can pass to add_part()."""
            return sorted(CIRCUIT_PARTS_CATALOG.keys())

        ns = {
            'state': state,
            'nodes': state['nodes'],
            'edges': state['edges'],
            'init': state['init'],
            'np': _np,
            'run_sim': run_sim,
            'refresh': self._cons_refresh,
            'add_part': add_part,
            'add_edge': add_edge,
            'clear_canvas': clear_canvas,
            'list_parts': list_parts,
            'CIRCUIT_PARTS_CATALOG': CIRCUIT_PARTS_CATALOG,
            '__builtins__': __builtins__,
        }

        def execute(_=None):
            code = entry.get('1.0', 'end').strip()
            if not code:
                return 'break'
            history.append(code)
            hist_idx[0] = len(history)
            # echo (indent multi-line for readability)
            write('\n>>> ' + code.replace('\n', '\n... ') + '\n')
            entry.delete('1.0', 'end')
            try:
                # Whole-block paste: try eval for a single expression, else exec
                try:
                    result = eval(code, ns)
                    if result is not None:
                        write(repr(result) + '\n', '#79c0ff')
                except SyntaxError:
                    exec(code, ns)
                ns['nodes'] = state['nodes']
                ns['edges'] = state['edges']
            except Exception as ex:
                import traceback as _tb
                write(_tb.format_exc().splitlines()[-1] + '\n', '#ff7b72')
            # Auto-redraw the canvas after every command so nodes/edges the
            # code created appear immediately without a manual refresh() call.
            try:
                self._cons_refresh()
            except Exception:
                pass
            return 'break'

        # Ctrl+Enter (and Shift+Enter) run the whole block; plain Enter adds a
        # newline so multi-line scripts can be typed/pasted freely.
        entry.bind('<Control-Return>', execute)
        entry.bind('<Shift-Return>', execute)

        def hist_up(_):
            if history and hist_idx[0] > 0:
                hist_idx[0] -= 1
                entry.delete('1.0', 'end')
                entry.insert('1.0', history[hist_idx[0]])
            return 'break'
        def hist_down(_):
            if history and hist_idx[0] < len(history) - 1:
                hist_idx[0] += 1
                entry.delete('1.0', 'end')
                entry.insert('1.0', history[hist_idx[0]])
            return 'break'
        # history via Ctrl+Up / Ctrl+Down (plain arrows move the cursor in Text)
        entry.bind('<Control-Up>', hist_up)
        entry.bind('<Control-Down>', hist_down)

        tk.Button(dlg, text=('▶ Выполнить всё  (Ctrl+Enter)' if is_ru
                             else '▶ Run all  (Ctrl+Enter)'),
                   bg='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   command=execute).pack(pady=(0, 8))

    def _cons_open_live_sliders(self):
        """Real-time parameter sliders: drag a slider and the simulation graph
        updates live. Lets scientists explore how each parameter shapes the
        dynamics — the TinkerCell 'sliders' feature."""
        state = self.current_state['constructor']
        if state is None or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('add_gene_first'))
            return
        is_ru = (self.lang == 'ru')

        dlg = tk.Toplevel(self)
        dlg.title('Живые параметры' if is_ru else 'Live parameters')
        dlg.geometry('900x620')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        # Layout: left = sliders (scrollable), right = live graph
        left = tk.Frame(dlg, bg=biosim_theme('bg'), width=320)
        left.pack(side='left', fill='y', padx=(8, 4), pady=8)
        left.pack_propagate(False)
        right = tk.Frame(dlg, bg=biosim_theme('bg'))
        right.pack(side='right', fill='both', expand=True, padx=(4, 8), pady=8)

        tk.Label(left, text=('Параметры' if is_ru else 'Parameters'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 12, 'bold')).pack(anchor='w', pady=(0, 4))
        tk.Label(left, text=('Двигай ползунок — график меняется вживую'
                             if is_ru else 'Drag a slider — the graph updates live'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 8), wraplength=300, justify='left').pack(anchor='w', pady=(0, 6))

        # Scrollable slider area
        canv = tk.Canvas(left, bg=biosim_theme('bg'), highlightthickness=0, width=300)
        sb = tk.Scrollbar(left, orient='vertical', command=canv.yview)
        inner = tk.Frame(canv, bg=biosim_theme('bg'))
        inner.bind('<Configure>', lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=inner, anchor='nw')
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')

        # Graph on the right
        fig, ax = new_biosim_figure(figsize=(6, 4.6))
        graph_canvas = FigureCanvasTkAgg(fig, master=right)
        graph_canvas.get_tk_widget().pack(fill='both', expand=True)

        t_end_var = tk.IntVar(value=100)

        # A debounce token so rapid slider motion doesn't queue many redraws
        self._live_after_id = None

        def recompute(*_):
            # Debounce: schedule the actual recompute shortly after last move
            if self._live_after_id is not None:
                try:
                    dlg.after_cancel(self._live_after_id)
                except Exception:
                    pass
            self._live_after_id = dlg.after(60, do_recompute)

        def do_recompute():
            try:
                t, y, ids = run_ode_simulation(
                    state['nodes'], state['edges'], state['init'],
                    t_end=t_end_var.get(), events=state.get('events'))
                ax.clear()
                style_biosim_axes(ax)
                if t is not None:
                    for i, nid in enumerate(ids):
                        if i < 12:  # cap legend size
                            ax.plot(t, y[:, i], label=nid, linewidth=1.8)
                    ax.set_xlabel('время' if is_ru else 'time')
                    ax.set_ylabel('концентрация' if is_ru else 'concentration')
                    if len(ids) <= 12:
                        ax.legend(fontsize=7, loc='upper right')
                graph_canvas.draw()
            except Exception as ex:
                biosim_log('warn', 'live sliders: {}'.format(ex))

        def add_slider(label, getter, setter, lo, hi, res, color='#0969da'):
            row = tk.Frame(inner, bg=biosim_theme('bg'))
            row.pack(fill='x', pady=2)
            tk.Label(row, text=label, bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                      font=('Arial', 8), anchor='w').pack(anchor='w')
            var = tk.DoubleVar(value=getter())

            def on_move(v):
                setter(float(v))
                recompute()
            tk.Scale(row, from_=lo, to=hi, resolution=res, orient='horizontal',
                      variable=var, command=on_move, bg=biosim_theme('panel'),
                      fg=biosim_theme('text'), highlightthickness=0,
                      troughcolor='#eef1f5', activebackground=color,
                      length=270).pack(fill='x')

        # Build sliders for node parameters
        def make_node_getset(node, attr, default):
            return (lambda: float(node.get(attr, default)),
                    lambda v: node.__setitem__(attr, v))

        def make_init_getset(nid):
            return (lambda: float(state['init'].get(nid, 0.5)),
                    lambda v: state['init'].__setitem__(nid, v))

        tk.Label(inner, text=('— Узлы —' if is_ru else '— Nodes —'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 9, 'bold')).pack(anchor='w', pady=(4, 0))
        for node in state['nodes'][:20]:
            nid = node['id']
            g1, s1 = make_node_getset(node, 'production', 1.0)
            add_slider('{} · production'.format(nid[:12]), g1, s1, 0.0, 10.0, 0.1, '#1a7f37')
            g2, s2 = make_node_getset(node, 'degradation', 0.1)
            add_slider('{} · degradation'.format(nid[:12]), g2, s2, 0.0, 2.0, 0.01, '#cf222e')

        # Build sliders for edge parameters
        if state['edges']:
            tk.Label(inner, text=('— Связи —' if is_ru else '— Edges —'),
                      bg=biosim_theme('bg'), fg='#8250df',
                      font=('Arial', 9, 'bold')).pack(anchor='w', pady=(6, 0))
        for edge in state['edges'][:20]:
            lbl = '{}→{}'.format(edge.get('from', '?')[:6], edge.get('to', '?')[:6])
            rxn = edge.get('reaction', edge.get('type', ''))
            def mk(edge, attr, default):
                return (lambda: float(edge.get(attr, default)),
                        lambda v: edge.__setitem__(attr, v))
            if rxn in ('activation', 'repression') or edge.get('type') in ('activation', 'repression'):
                g, s = mk(edge, 'strength', 3.0)
                add_slider('{} · strength'.format(lbl), g, s, 0.0, 20.0, 0.1, '#8250df')
            elif rxn == 'catalysis':
                g, s = mk(edge, 'kcat', 1.0)
                add_slider('{} · kcat'.format(lbl), g, s, 0.0, 50.0, 0.1, '#9a6700')
                g2, s2 = mk(edge, 'km', 1.0)
                add_slider('{} · Km'.format(lbl), g2, s2, 0.01, 20.0, 0.01, '#0969da')
            else:
                g, s = mk(edge, 'k', 1.0)
                add_slider('{} · k'.format(lbl), g, s, 0.0, 10.0, 0.1, '#bc4c00')

        # Time control + apply-to-model note
        ctl = tk.Frame(right, bg=biosim_theme('bg'))
        ctl.pack(fill='x', pady=(4, 0))
        tk.Label(ctl, text=('Время симуляции:' if is_ru else 'Sim time:'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9)).pack(side='left')
        tk.Scale(ctl, from_=20, to=400, resolution=10, orient='horizontal',
                  variable=t_end_var, command=lambda v: recompute(),
                  bg=biosim_theme('panel'), fg=biosim_theme('text'),
                  highlightthickness=0, troughcolor='#eef1f5',
                  activebackground='#0969da', length=200).pack(side='left', padx=6)
        tk.Label(ctl, text=('Изменения сохраняются в модели' if is_ru
                             else 'Changes are saved to the model'),
                  bg=biosim_theme('bg'), fg='#1a7f37',
                  font=('Arial', 8, 'italic')).pack(side='right')

        def on_close():
            self._cons_refresh()  # reflect changed params on the canvas
            dlg.destroy()
        dlg.protocol('WM_DELETE_WINDOW', on_close)

        do_recompute()  # initial draw

    def _cons_open_text_mode(self):
        """Antimony text mode: edit the model as text and sync both ways.
        Schema → Text regenerates the Antimony script; Text → Schema parses it
        back and rebuilds the diagram. Lets scientists write models by hand."""
        state = self.current_state['constructor']
        if state is None:
            return
        is_ru = (self.lang == 'ru')
        dlg = tk.Toplevel(self)
        dlg.title('Antimony — текстовый режим' if is_ru else 'Antimony — text mode')
        dlg.geometry('640x600')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        tk.Label(dlg, text=('Текстовая модель Antimony' if is_ru
                            else 'Antimony text model'),
                  bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 13, 'bold')).pack(pady=(10, 2))
        tk.Label(dlg,
                  text=('Редактируй модель как текст. «Схема → Текст» переносит '
                        'текущую схему сюда; «Текст → Схема» строит схему из текста.'
                        if is_ru else
                        'Edit the model as text. "Schema → Text" brings the current '
                        'diagram here; "Text → Schema" rebuilds the diagram from text.'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9), wraplength=600, justify='left').pack(padx=14, pady=(0, 6))

        # Text area with scrollbar
        txt_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        txt_frame.pack(fill='both', expand=True, padx=14, pady=4)
        scroll = tk.Scrollbar(txt_frame)
        scroll.pack(side='right', fill='y')
        txt = tk.Text(txt_frame, wrap='none', bg='#0d1117', fg='#e6edf3',
                       insertbackground='#e6edf3', font=('Consolas', 11),
                       relief='flat', highlightthickness=1,
                       highlightbackground=biosim_theme('border'),
                       yscrollcommand=scroll.set)
        txt.pack(side='left', fill='both', expand=True)
        scroll.config(command=txt.yview)

        # Pre-fill with current schema as Antimony
        try:
            initial = export_to_antimony(state)
        except Exception as ex:
            initial = '// (export failed: {})'.format(ex)
        txt.insert('1.0', initial or '')

        status = tk.Label(dlg, text='', bg=biosim_theme('bg'),
                           fg='#1a7f37', font=('Arial', 9))
        status.pack(pady=(2, 0))

        def schema_to_text():
            try:
                s = export_to_antimony(self.current_state['constructor'])
                txt.delete('1.0', 'end')
                txt.insert('1.0', s or '')
                status.config(
                    text=('Схема перенесена в текст' if is_ru
                          else 'Schema copied to text'), fg='#1a7f37')
            except Exception as ex:
                status.config(text='Error: {}'.format(ex), fg='#cf222e')

        def text_to_schema():
            content = txt.get('1.0', 'end')
            try:
                new_state = import_from_antimony(content)
            except Exception as ex:
                status.config(text=('Ошибка разбора: {}'.format(ex) if is_ru
                                     else 'Parse error: {}'.format(ex)), fg='#cf222e')
                return
            if not new_state or not new_state.get('nodes'):
                status.config(text=('Не найдено ни одного вида/реакции'
                                     if is_ru else 'No species/reactions found'),
                              fg='#cf222e')
                return
            # Confirm — this replaces the current schema
            if not messagebox.askyesno(
                    'VIREON',
                    ('Построить схему из текста? Текущая схема будет заменена.'
                     if is_ru else
                     'Build schema from text? The current diagram will be replaced.')):
                return
            self._save_history('constructor')
            cur = self.current_state['constructor']
            # Preserve project name/description, swap nodes/edges/init
            cur['nodes'] = new_state['nodes']
            cur['edges'] = new_state['edges']
            cur['init'] = new_state.get('init', {})
            # Reset view so everything is visible
            self._cons_zoom_reset()
            self._cons_refresh()
            status.config(text=('Схема построена: {} видов, {} реакций'
                                 .format(len(new_state['nodes']), len(new_state['edges']))
                                 if is_ru else
                                 'Schema built: {} species, {} reactions'
                                 .format(len(new_state['nodes']), len(new_state['edges']))),
                          fg='#1a7f37')

        btn_row = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_row.pack(fill='x', padx=14, pady=10)
        tk.Button(btn_row, text=('⬇ Схема → Текст' if is_ru else '⬇ Schema → Text'),
                   bg='#0969da', highlightbackground='#0969da', fg='white',
                   relief='flat', font=('Arial', 10, 'bold'), cursor='hand2',
                   pady=5, command=schema_to_text
                   ).pack(side='left', fill='x', expand=True, padx=3)
        tk.Button(btn_row, text=('⬆ Текст → Схема' if is_ru else '⬆ Text → Schema'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                   relief='flat', font=('Arial', 10, 'bold'), cursor='hand2',
                   pady=5, command=text_to_schema
                   ).pack(side='left', fill='x', expand=True, padx=3)
        tk.Button(btn_row, text=self._t('cancel'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128',
                   fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10), cursor='hand2', pady=5,
                   command=dlg.destroy).pack(side='right', padx=3)

    def _cons_run_animation(self):
        """Animate concentrations by shading nodes over time."""
        state = self.current_state['constructor']
        if not state['nodes']:
            return
        t, y, ids = run_ode_simulation(state['nodes'], state['edges'], state['init'], t_end=100)
        if t is None:
            messagebox.showinfo('VIREON', self._t('adv_failed'))
            return
        # Animation state
        self._cons_anim_data = (t, y, ids)
        self._cons_anim_frame = 0
        self._cons_anim_running = True
        # Animate frame-by-frame on the existing canvas
        self._cons_animation_step()

    def _cons_animation_step(self):
        if not getattr(self, '_cons_anim_running', False):
            return
        t, y, ids = self._cons_anim_data
        frame = self._cons_anim_frame
        if frame >= len(t):
            self._cons_anim_running = False
            self._cons_refresh()
            return
        # Get concentrations at this frame
        concs = dict(zip(ids, y[frame]))
        # Max concentration for normalization
        max_c = max(0.1, max(concs.values()))
        state = self.current_state['constructor']
        # Modify node alpha/opacity by re-drawing with shaded color
        for n in state['nodes']:
            if n['id'] in concs:
                # Store original color, then update with darkness
                base_color = n.get('_orig_color') or n['color']
                n['_orig_color'] = base_color
                # Darkness factor: 0.3 (low) 1.0 (max)
                level = concs[n['id']] / max_c
                factor = 0.3 + 0.7 * min(1.0, level)
                n['color'] = self._scale_color(base_color, factor)
        self._cons_draw_diagram()
        # Show frame info
        self._cons_status_lbl.config(
            text='Frame {}/{} · t={:.1f}'.format(frame + 1, len(t), t[frame]))
        self._cons_anim_frame += 2  # skip frames for speed
        self.after(60, self._cons_animation_step)

    def _scale_color(self, hex_color, factor):
        """Scale RGB by factor (0..1)."""
        h = hex_color.lstrip('#')
        r = int(int(h[0:2], 16) * factor)
        g = int(int(h[2:4], 16) * factor)
        b = int(int(h[4:6], 16) * factor)
        return '#{:02x}{:02x}{:02x}'.format(r, g, b)

    def _show_text_dialog(self, title, text):
        """Helper: show text in a scrollable dialog."""
        dlg = tk.Toplevel(self)
        dlg.title(title)
        dlg.geometry('640x520')
        dlg.configure(bg=biosim_theme('bg'))
        tk.Label(dlg, text=title, bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 13, 'bold')).pack(pady=8)
        txt = scrolledtext.ScrolledText(dlg, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                          font=('Courier', 10), relief='flat',
                                          wrap='word', highlightthickness=0)
        txt.pack(fill='both', expand=True, padx=10, pady=4)
        txt.insert('1.0', text)
        txt.config(state='disabled')
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11), cursor='hand2',
                   command=dlg.destroy).pack(fill='x', padx=12, pady=8)

    def _cons_on_disease_selected(self, event=None):
        """When a disease is chosen, first ask WHERE to apply it (constructor
        only, or all four workspaces), then build a DETAILED cellular picture of
        the disease — genes, their proteins, and the regulatory cascades /
        influences between them — like what really happens in a patient's cell.
        """
        is_ru = (self.lang == 'ru')
        selected_label = self.cons_disease_combo.get()
        disease_key = 'none'
        for dkey, dlabel in self._cons_disease_options:
            if dlabel == selected_label:
                disease_key = dkey
                break
        if disease_key == 'none':
            return
        disease = DISEASE_DATABASE.get(disease_key, {})
        if not disease:
            return

        # ── Scope chooser dialog ──
        dlg = tk.Toplevel(self)
        dlg.title('Область применения болезни' if is_ru else 'Disease scope')
        dlg.geometry('460x260')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        tk.Label(dlg, text=(('Болезнь: ' if is_ru else 'Disease: ') + selected_label),
                 bg=biosim_theme('bg'), fg=biosim_theme('accent'),
                 font=('Helvetica', 13, 'bold'), wraplength=420).pack(pady=(16, 6))
        tk.Label(dlg, text=('Где построить детальную картину болезни?'
                            if is_ru else 'Where to build the detailed disease picture?'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text'),
                 font=('Helvetica', 10)).pack(pady=(0, 12))

        def _go(scope):
            dlg.destroy()
            self._cons_build_disease_detail(disease_key, disease, selected_label, scope)

        tk.Button(dlg, text=('🧬 Только конструктор' if is_ru else '🧬 Constructor only'),
                  bg=biosim_theme('accent'), fg=biosim_theme('accent_text'),
                  relief='flat', bd=0, highlightthickness=0,
                  font=('Helvetica', 11, 'bold'), cursor='hand2', pady=8,
                  command=lambda: _go('constructor')).pack(fill='x', padx=24, pady=4)
        tk.Button(dlg, text=('🔬 Все разделы (конструктор, метаболизм, CRISPR, мол.био)'
                             if is_ru else '🔬 All workspaces (constructor, metabolism, CRISPR, MolBio)'),
                  bg=biosim_theme('accent2'), fg=biosim_theme('accent2_text'),
                  relief='flat', bd=0, highlightthickness=0,
                  font=('Helvetica', 10, 'bold'), cursor='hand2', pady=8,
                  wraplength=380,
                  command=lambda: _go('all')).pack(fill='x', padx=24, pady=4)
        tk.Button(dlg, text=('Отмена' if is_ru else 'Cancel'),
                  bg=biosim_theme('btn_bg'), fg=biosim_theme('btn_text'),
                  relief='flat', bd=0, highlightthickness=0,
                  font=('Helvetica', 10), cursor='hand2',
                  command=dlg.destroy).pack(fill='x', padx=24, pady=(10, 4))

    def _cons_build_disease_detail(self, disease_key, disease, selected_label, scope):
        """Build the detailed disease picture on the constructor canvas: each
        gene becomes a construct (promoter→RBS→CDS→terminator) PLUS its protein
        node, and regulatory influences between them are drawn as edges
        (mutated genes drive overexpression targets, etc.). Sequences and extra
        gene relations are pulled from NCBI in the background. When scope='all',
        the disease context is also recorded for the other workspaces.
        """
        is_ru = (self.lang == 'ru')
        state = self.current_state['constructor']
        if state is None:
            return
        self._save_history('constructor')

        # Gather the biology of the disease from the database.
        ther = disease.get('therapeutic_genes', []) or []
        mut = disease.get('mutated_genes', []) or []
        over = disease.get('overexpression_dangerous', []) or []
        under = disease.get('underexpression_dangerous', []) or []
        # Unique ordered gene list (cap for a readable canvas).
        genes = []
        for g in (mut + ther + over + under):
            if g and g not in genes:
                genes.append(g)
        genes = genes[:6]
        if not genes:
            self.toast(('Нет данных о генах для этой болезни.'
                        if is_ru else 'No gene data for this disease.'),
                       level='info', duration=2500)
            return

        existing_ids = [n['id'] for n in state['nodes']]
        def uid(base):
            nid = base; k = 1
            while nid in existing_ids:
                nid = base + '_' + str(k); k += 1
            existing_ids.append(nid)
            return nid

        def add_node(nid, x, y, pk, gene=None, ko=False):
            pdata = CIRCUIT_PARTS_CATALOG.get(pk, {})
            node = {'id': nid, 'x': x, 'y': y, 'part_key': pk,
                    'icon': pdata.get('icon', 'cds'),
                    'color': pdata.get('color', '#0891b2'),
                    'production': pdata.get('production', 1.0),
                    'degradation': pdata.get('degradation', 0.1),
                    'gene_symbol': gene, 'sequence': None,
                    'is_generic': pk == 'cds_generic', 'is_knockout': ko}
            state['nodes'].append(node)
            state['init'][nid] = pdata.get('initial', 0.5)
            return nid

        protein_of = {}   # gene -> protein node id
        base_x = 150
        row_gap = 120
        start_y = 110
        for gi, gene in enumerate(genes):
            y = start_y + gi * row_gap
            is_mut = gene in mut
            # DNA construct: promoter → RBS → CDS → terminator
            x = base_x
            prom = uid('P_' + gene);  add_node(prom, x, y, 'promoter_medium'); x += 70
            rbs = uid('RBS_' + gene); add_node(rbs, x, y, 'rbs_strong');       x += 70
            cds = uid(gene);          add_node(cds, x, y, 'cds_generic', gene=gene, ko=is_mut); x += 70
            term = uid('T_' + gene);  add_node(term, x, y, 'terminator');      x += 90
            # Protein product node (separate, not on the DNA strand)
            prot = uid(gene + '_prot')
            add_node(prot, x + 20, y - 36, 'protein_generic', gene=gene)
            protein_of[gene] = prot
            # expression edge CDS → protein (production)
            state['edges'].append({'from': cds, 'to': prot, 'type': 'activation',
                                   'reaction': 'protein_production',
                                   'strength': 3.0, 'hill_n': 2})

        # Regulatory influences between proteins: mutated/overexpressed genes
        # drive their dangerous targets (activation), underexpressed → repression.
        for g in mut + over:
            if g in protein_of:
                for tgt in over:
                    if tgt in protein_of and tgt != g:
                        state['edges'].append({'from': protein_of[g], 'to': protein_of[tgt],
                                               'type': 'activation', 'reaction': 'activation',
                                               'strength': 2.5, 'hill_n': 2})
        for g in under:
            if g in protein_of:
                for src in mut:
                    if src in protein_of and src != g:
                        state['edges'].append({'from': protein_of[src], 'to': protein_of[g],
                                               'type': 'repression', 'reaction': 'repression',
                                               'strength': 2.5, 'hill_n': 2})

        self._cons_refresh()
        scope_txt = ('во всех разделах' if (scope == 'all' and is_ru)
                     else 'in all workspaces' if scope == 'all'
                     else 'в конструкторе' if is_ru else 'in constructor')
        self.toast(('Построена детальная картина болезни «{}» {} — загружаю данные из NCBI…'
                    .format(selected_label, scope_txt) if is_ru
                    else 'Built detailed disease picture "{}" {} — fetching NCBI data…'
                    .format(selected_label, scope_txt)),
                   level='info', duration=3500)

        # Record disease context for other workspaces when scope='all'.
        if scope == 'all':
            self._active_disease_context = {
                'key': disease_key, 'label': selected_label,
                'genes': genes, 'mutated': mut, 'therapeutic': ther,
                'over': over, 'under': under,
            }

        # Background: pull real DNA sequences + gene descriptions from NCBI,
        # then (for scope='all') distribute them to the other workspaces.
        def _fetch():
            gene_seqs = {}
            for gene in genes:
                try:
                    seq = ncbi_gene_sequence(gene)
                except Exception:
                    seq = ''
                if seq:
                    gene_seqs[gene] = seq
                    for n in state['nodes']:
                        if n.get('gene_symbol') == gene and n.get('part_key') == 'cds_generic':
                            n['sequence'] = seq
            try:
                self.after(0, self._cons_refresh)
            except Exception:
                pass
            if scope == 'all':
                self.after(0, lambda: self._apply_disease_to_all(
                    disease_key, disease, selected_label, genes, gene_seqs))
            try:
                self.after(0, lambda: self.toast(
                    ('Данные болезни загружены из NCBI' if is_ru
                     else 'Disease data loaded from NCBI'),
                    level='success', duration=2500))
            except Exception:
                pass
        try:
            import threading
            threading.Thread(target=_fetch, daemon=True).start()
        except Exception:
            pass

    def _apply_disease_to_all(self, disease_key, disease, label, genes, gene_seqs):
        """Distribute a disease's biology across CRISPR, metabolism and MolBio
        so every workspace reflects the same patient. Called after NCBI fetch
        when the user chose 'all workspaces'."""
        is_ru = (self.lang == 'ru')
        applied = []

        # ── CRISPR: load the concatenated disease-gene sequences & scan guides ──
        try:
            combined = ''.join(gene_seqs.get(g, '') for g in genes)
            if combined:
                cst = self.current_state.get('crispr')
                if cst is not None:
                    cst['sequence'] = combined
                    cst['name'] = (label + ' (гены болезни)') if is_ru else (label + ' (disease genes)')
                    cst['targets'] = []
                    cst['selected_target'] = None
                    try:
                        self._crispr_render_sequence()
                        self._crispr_scan()
                    except Exception:
                        pass
                    applied.append('CRISPR')
        except Exception as _exc:
            biosim_log('warn', '_apply_disease_to_all crispr: {}'.format(_exc))

        # ── Metabolism: ONLY for metabolic diseases, build the affected pathway
        # and mark what is disrupted. Non-metabolic diseases (cancer, hemophilia,
        # etc.) do NOT touch metabolism — that would be scientifically meaningless.
        # Map: disease key → (pathway key, short note on the disruption).
        METABOLIC_DISEASES = {
            'diabetes_type1': ('glycolysis',
                               'Диабет 1 типа: нет инсулина → глюкоза не усваивается клетками',
                               'Type 1 diabetes: no insulin → glucose not taken up by cells'),
            'diabetes_type2': ('glycolysis',
                               'Диабет 2 типа: инсулинорезистентность → нарушен путь глюкозы',
                               'Type 2 diabetes: insulin resistance → impaired glucose pathway'),
        }
        try:
            if disease_key in METABOLIC_DISEASES:
                pw_key, note_ru, note_en = METABOLIC_DISEASES[disease_key]
                model = preset_model_from_pathway(pw_key)
                if isinstance(model, dict):
                    model['disease_context'] = {
                        'key': disease_key, 'label': label,
                        'disruption': (note_ru if is_ru else note_en),
                        'genes': genes}
                    model['name'] = (label + ' — нарушенный путь' if is_ru
                                     else label + ' — affected pathway')
                    self.current_state['metabolic'] = model
                    try:
                        self._metab_select('model', 'Species')
                    except Exception:
                        pass
                    applied.append(('метаболизм' if is_ru else 'metabolism'))
            # Non-metabolic diseases: metabolism is intentionally left untouched.
        except Exception as _exc:
            biosim_log('warn', '_apply_disease_to_all metab: {}'.format(_exc))

        # ── MolBio: hand the first gene sequence to the MolBio workspace.
        # If MolBio is open, load it now; otherwise STORE it as pending so it
        # loads automatically the next time MolBio is opened (previously a
        # closed MolBio meant the sequence was lost and the window looked empty).
        try:
            first_seq = next((gene_seqs[g] for g in genes if g in gene_seqs), '')
            if first_seq:
                app = self.master
                # remember disease + sequence for MolBio regardless of open state
                try:
                    app._molbio_pending_sequence = first_seq
                    app._molbio_pending_name = label
                except Exception:
                    pass
                mw = getattr(app, '_molbio_window', None)
                loaded = False
                if mw is not None:
                    try:
                        if mw.winfo_exists() and hasattr(mw, 'load_external_sequence'):
                            mw.load_external_sequence(first_seq)
                            loaded = True
                    except Exception:
                        loaded = False
                # counts as applied either way (pending or loaded)
                applied.append('MolBio')
        except Exception:
            pass

        if applied:
            self.toast((('Болезнь применена в: ' if is_ru else 'Disease applied in: ')
                        + ', '.join(str(a) for a in applied)),
                       level='success', duration=3500)
        else:
            self.toast(('Не удалось применить болезнь в других разделах '
                        '(нужны последовательности из интернета).' if is_ru else
                        'Could not apply disease elsewhere (needs online sequences).'),
                       level='warn', duration=3500)

    def _cons_run_ode(self):
        """Deterministic ODE time-course of the constructor circuit.

        This is what the main "Run simulation" button now does: integrate the
        circuit's ODE system and plot concentrations over time (the deterministic
        analysis), NOT the disease-effect simulation.
        """
        is_ru = (self.lang == 'ru')
        state = self.current_state['constructor']
        if state is None or not state.get('nodes'):
            messagebox.showinfo('VIREON',
                'Сначала постройте схему.' if is_ru else 'Build a circuit first.')
            return
        nodes = state['nodes']
        edges = state.get('edges', [])
        try:
            res = simulate_circuit(nodes, edges, state.get('init', {}),
                                   t_end=100, n_points=400)
            t, sol = res if isinstance(res, tuple) else (None, res)
        except Exception as _exc:
            biosim_log('warn', '_cons_run_ode: {}'.format(_exc))
            t, sol = None, None
        if t is None or sol is None:
            messagebox.showinfo('VIREON',
                'Симуляция не удалась.' if is_ru else 'Simulation failed.')
            return

        # Plot in a dialog
        dlg = tk.Toplevel(self)
        dlg.title('Детерминистическая симуляция (ODE)' if is_ru
                  else 'Deterministic simulation (ODE)')
        dlg.geometry('760x560')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        tk.Label(dlg, text=('▶ Детерминистическая симуляция — ODE' if is_ru
                            else '▶ Deterministic simulation — ODE'),
                 bg=biosim_theme('bg'), fg=biosim_theme('accent'),
                 font=('Helvetica', 14, 'bold')).pack(pady=(12, 4))
        try:
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            fig = Figure(figsize=(7, 4.2), dpi=100)
            fig.patch.set_facecolor(biosim_theme('plot_bg'))
            ax = fig.add_subplot(111)
            ax.set_facecolor(biosim_theme('plot_bg'))
            palette = ['#0891b2', '#0d9488', '#cf222e', '#9a6700', '#8250df',
                       '#bc4c00', '#0550ae', '#1a7f37']
            for i, n in enumerate(nodes):
                try:
                    col = sol[:, i] if hasattr(sol, 'shape') else [row[i] for row in sol]
                    ax.plot(t, col, color=palette[i % len(palette)], lw=2,
                            label=str(n['id'])[:12])
                except Exception:
                    pass
            ax.set_xlabel('t', color=biosim_theme('text_dim'))
            ax.set_ylabel(('концентрация' if is_ru else 'concentration'),
                          color=biosim_theme('text_dim'))
            ax.tick_params(colors=biosim_theme('text_dim'))
            for sp in ax.spines.values():
                sp.set_color(biosim_theme('spine'))
            ax.grid(True, color=biosim_theme('grid'), lw=0.5)
            if len(nodes) <= 12:
                ax.legend(fontsize=8, facecolor=biosim_theme('panel2'),
                          edgecolor=biosim_theme('border'),
                          labelcolor=biosim_theme('text'))
            fig.tight_layout()
            cv = FigureCanvasTkAgg(fig, master=dlg)
            cv.draw()
            cv.get_tk_widget().pack(fill='both', expand=True, padx=12, pady=6)
        except Exception as _exc:
            tk.Label(dlg, text='matplotlib error: {}'.format(_exc),
                     bg=biosim_theme('bg'), fg=biosim_theme('danger')).pack()
        tk.Button(dlg, text=('Закрыть' if is_ru else 'Close'),
                  bg=biosim_theme('btn_bg'), fg=biosim_theme('btn_text'),
                  relief='flat', bd=0, highlightthickness=0,
                  font=('Helvetica', 11), cursor='hand2',
                  command=dlg.destroy).pack(fill='x', padx=12, pady=8)

    def _cons_simulate(self):
        """Run disease/organism simulation: show therapeutic effect, side effects."""
        state = self.current_state['constructor']
        if state is None or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('add_gene_first'))
            return
        # Get selected disease
        selected_label = self.cons_disease_combo.get()
        disease_key = 'none'
        for dkey, dlabel in self._cons_disease_options:
            if dlabel == selected_label:
                disease_key = dkey
                break
        # Run simulation
        result = simulate_disease_effect(state, disease_key)
        # Record in history
        import datetime
        if not hasattr(self, '_simulation_history'):
            self._simulation_history = []
        self._simulation_history.append({
            'timestamp': datetime.datetime.now().isoformat(),
            'disease': disease_key,
            'disease_label': selected_label,
            'therapeutic_score': result.get('therapeutic_score', 0),
            'side_effects': result.get('side_effects', []),
            'produced_proteins': result.get('produced_proteins', []),
            'n_nodes': len(state['nodes']),
            'n_edges': len(state['edges']),
        })
        # Limit history to last 100
        if len(self._simulation_history) > 100:
            self._simulation_history = self._simulation_history[-100:]
        biosim_log('success', 'Simulation run for: ' + selected_label)
        # Show in dialog window
        self._cons_show_sim_results(result, disease_key)

    def _cons_show_sim_results(self, result, disease_key):
        """Display simulation results in a styled dialog."""
        dlg = tk.Toplevel(self)
        dlg.title(self._t('disease_sim_title'))
        dlg.geometry('640x680')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)

        # Title
        title_lbl = self._t('disease_sim_title')
        tk.Label(dlg, text=title_lbl, bg=biosim_theme('bg'), fg='#8250df',
                  font=('Arial', 15, 'bold')).pack(pady=(12, 4))

        # Disease name big
        disease_name = result['disease_name_ru'] if self.lang == 'ru' else result['disease_name_en']
        tk.Label(dlg, text=disease_name, bg=biosim_theme('bg'), fg='#cf222e',
                  font=('Arial', 13, 'bold')).pack(pady=(0, 8))

        # Score bar
        score = result['therapeutic_score']
        if score >= 70:
            score_color = '#1a7f37'
            score_label = self._t('sim_help_strong')
        elif score >= 40:
            score_color = '#0969da'
            score_label = self._t('sim_help_moderate')
        elif score >= 10:
            score_color = '#9a6700'
            score_label = self._t('sim_help_weak')
        elif score >= 0:
            score_color = '#57606a'
            score_label = self._t('sim_no_effect')
        else:
            score_color = '#cf222e'
            score_label = self._t('sim_harmful')

        score_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        score_frame.pack(fill='x', padx=20, pady=(4, 8))
        tk.Label(score_frame, text=self._t('therapeutic_score'),
                  bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 10)).pack(side='left')
        tk.Label(score_frame, text=' {}/100'.format(score),
                  bg=biosim_theme('bg'), fg=score_color,
                  font=('Arial', 18, 'bold')).pack(side='left')
        tk.Label(score_frame, text='  ' + score_label,
                  bg=biosim_theme('bg'), fg=score_color,
                  font=('Arial', 11, 'italic')).pack(side='left', padx=8)

        # Visual score bar
        bar_canvas = tk.Canvas(dlg, bg=biosim_theme('bg'), highlightthickness=0, height=20)
        bar_canvas.pack(fill='x', padx=20, pady=(0, 8))
        # Background bar
        bar_canvas.create_rectangle(0, 4, 600, 16, fill='#eef1f5', outline='#d0d7de')
        # Fill bar based on score
        fill_w = max(0, min(600, int(600 * (score + 50) / 150)))
        bar_canvas.create_rectangle(0, 4, fill_w, 16, fill=score_color, outline='')
        # Zero line marker
        zero_x = int(600 * 50 / 150)
        bar_canvas.create_line(zero_x, 0, zero_x, 20, fill='#57606a', width=1)
        bar_canvas.create_text(zero_x, 18, text='0', fill='#57606a',
                                font=('Arial', 7), anchor='n')
        bar_canvas.create_text(0, 18, text='-50', fill='#57606a',
                                font=('Arial', 7), anchor='nw')
        bar_canvas.create_text(600, 18, text='+100', fill='#57606a',
                                font=('Arial', 7), anchor='ne')

        # Scrollable text area for details
        details_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        details_frame.pack(fill='both', expand=True, padx=12, pady=4)
        details = scrolledtext.ScrolledText(details_frame, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                                              font=('Arial', 10), relief='flat',
                                              wrap='word', state='normal',
                                              highlightthickness=0)
        details.pack(fill='both', expand=True)

        # Configure tags
        details.tag_config('header', foreground='#8250df', font=('Arial', 11, 'bold'))
        details.tag_config('subheader', foreground='#0969da', font=('Arial', 10, 'bold'))
        details.tag_config('ok', foreground='#1a7f37', font=('Arial', 10))
        details.tag_config('warn', foreground='#9a6700', font=('Arial', 10))
        details.tag_config('bad', foreground='#cf222e', font=('Arial', 10))
        details.tag_config('nrm', foreground=biosim_theme('text'), font=('Arial', 10))
        details.tag_config('dim', foreground=biosim_theme('text_dim'), font=('Arial', 9, 'italic'))

        # Disease info
        details.insert('end', self._t('disease_target') + '\n', 'subheader')
        details.insert('end', '  ' + disease_name + '\n', 'nrm')
        disease = DISEASE_DATABASE.get(disease_key, {})
        cause = disease.get('cause_ru' if self.lang == 'ru' else 'cause_en', '')
        if cause:
            details.insert('end', '\n' + self._t('disease_cause') + '\n', 'subheader')
            details.insert('end', '  ' + cause + '\n', 'dim')

        # Produced proteins
        details.insert('end', '\n' + self._t('produced_proteins') + '\n', 'subheader')
        if result['produced_proteins']:
            for gname, level in result['produced_proteins']:
                level_color = 'ok' if level > 0.5 else 'dim'
                details.insert('end', '  · {} уровень {:.2f}\n'.format(gname, level)
                                if self.lang == 'ru' else
                                '  · {} level {:.2f}\n'.format(gname, level), level_color)
        else:
            details.insert('end', '  ' + self._t('no_proteins_produced') + '\n', 'dim')

        # Direct effects
        effects_key = 'direct_effects_ru' if self.lang == 'ru' else 'direct_effects_en'
        if result.get(effects_key):
            details.insert('end', '\n' + self._t('direct_effect') + '\n', 'subheader')
            for eff in result[effects_key]:
                details.insert('end', '  ' + eff + '\n', 'nrm')

        # Warnings
        if result.get('warnings'):
            details.insert('end', '\n' + self._t('warnings_lbl_sim') + '\n', 'subheader')
            for w in result['warnings']:
                msg = w.get('msg_ru' if self.lang == 'ru' else 'msg_en',
                             w.get('msg', ''))
                tag = 'bad' if w.get('severity') == 'high' else 'warn'
                details.insert('end', '  ' + msg + '\n', tag)

        # Side effects
        if result.get('side_effects'):
            details.insert('end', '\n' + self._t('side_effects_lbl') + '\n', 'subheader')
            for se in result['side_effects']:
                msg = se.get('msg_ru' if self.lang == 'ru' else 'msg_en',
                              se.get('msg', ''))
                details.insert('end', '  · ' + msg + '\n', 'warn')

        details.config(state='disabled')

        # Close button
        tk.Button(dlg, text=self._t('close_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 11, 'bold'), cursor='hand2', pady=6,
                   command=dlg.destroy
                   ).pack(fill='x', padx=12, pady=10)

    def _build_circuit_tab(self):
        """TinkerCell-style layout: parts catalog tree (left top),
        reactions catalog (left bottom), canvas (center), info+sim (right)."""
        f = tk.Frame(self.content, bg=biosim_theme('bg'))

        # ── LEFT panel: parts catalog (top) + reactions catalog (bottom) ──
        left = tk.Frame(f, bg=biosim_theme('bg'), width=240)
        left.pack(side='left', fill='y', padx=(0, 4)); left.pack_propagate(False)

        # Parts catalog (top half)
