    def _build_circuit_parts_tree(self):
        """Render the parts catalog as a tree (TinkerCell-style)."""
        for w in self._circuit_parts_tree_frame.winfo_children():
            w.destroy()
        # Named parts with published characterisation come first: when a real
        # measured option exists there is no reason to reach for a placeholder.
        kind_titles = [
            ('promoter', 'Промоторы с измеренной силой',
             'Promoters with measured strength',
             'сила относительно J23100 = 1.0', 'strength relative to J23100 = 1.0'),
            ('rbs', 'RBS с измеренной силой', 'RBS with measured strength',
             'сила относительно B0034 = 1.0', 'strength relative to B0034 = 1.0'),
            ('terminator', 'Терминаторы (эффективность)',
             'Terminators (efficiency)',
             'доля обрыва транскрипции', 'fraction of transcription stopped'),
        ]
        for kind, ttl_ru, ttl_en, sub_ru, sub_en in kind_titles:
            meas = characterised_parts_by_kind(kind)
            if not meas:
                continue
            tk.Label(self._circuit_parts_tree_frame,
                     text='▼ ' + (ttl_ru if self.lang == 'ru' else ttl_en),
                     bg=biosim_theme('panel'), fg='#1a7f37',
                     font=('Arial', 9, 'bold'), anchor='w'
                     ).pack(fill='x', padx=2, pady=(4, 1))
            tk.Label(self._circuit_parts_tree_frame,
                     text='   ' + (sub_ru if self.lang == 'ru' else sub_en),
                     bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                     font=('Arial', 8, 'italic'), anchor='w'
                     ).pack(fill='x', padx=4)
            for pkey, pdata in meas:
                nm = pdata.get('name_ru' if self.lang == 'ru' else 'name_en', pkey)
                st = pdata.get('strength', 0)
                shade = ('#1a7f37' if st >= 0.6 else
                         '#9a6700' if st >= 0.2 else '#cf222e')
                tk.Button(self._circuit_parts_tree_frame,
                          text='   {}  {:.2f}'.format(nm[:20], st),
                          bg=biosim_theme('panel'), highlightbackground='#1c2128',
                          fg=shade, relief='solid', bd=1, font=('Arial', 8),
                          cursor='hand2', anchor='w',
                          command=lambda k=pkey: self._circuit_place_characterised(k)
                          ).pack(fill='x', padx=2, pady=1)

        for family_name, family_color, subgroups in CIRCUIT_FAMILY_TREE:
            # Family header (large, colored)
            family_label_key = 'family_' + family_name.lower().replace(' ', '_').replace('/', '_')
            family_display = self._t(family_label_key) if self.lang == 'ru' else family_name
            tk.Label(self._circuit_parts_tree_frame,
                      text='▼ ' + family_display,
                      bg=biosim_theme('panel'), fg=family_color,
                      font=('Arial', 9, 'bold'), anchor='w'
                      ).pack(fill='x', padx=2, pady=(4, 1))
            for sub_name, part_keys in subgroups:
                # Subgroup header (small grey)
                sub_label_key = 'sub_' + sub_name.lower().replace(' ', '_').replace('/', '_')
                sub_display = self._t(sub_label_key) if self.lang == 'ru' else sub_name
                tk.Label(self._circuit_parts_tree_frame,
                          text='   ' + sub_display,
                          bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                          font=('Arial', 8, 'italic'), anchor='w'
                          ).pack(fill='x', padx=4, pady=0)
                # Parts in subgroup
                for pkey in part_keys:
                    part_data = CIRCUIT_PARTS_CATALOG.get(pkey)
                    if not part_data:
                        continue
                    name_key = 'name_ru' if self.lang == 'ru' else 'name_en'
                    pname = part_data.get(name_key, pkey)
                    btn = tk.Button(self._circuit_parts_tree_frame,
                                     text='   ' + self._part_icon_char(part_data['icon']) + ' ' + pname[:24],
                                     bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=part_data['color'], relief='solid', bd=1,
                                     font=('Arial', 8), cursor='hand2', anchor='w',
                                     command=lambda k=pkey: self._circuit_select_part(k))
                    btn.pack(fill='x', padx=2, pady=1)

    def _build_circuit_reactions_list(self):
        """Render the reactions catalog at bottom-left."""
        for w in self._circuit_rxn_frame.winfo_children():
            w.destroy()
        for rkey, rdata in CIRCUIT_REACTIONS.items():
            name_key = 'name_ru' if self.lang == 'ru' else 'name_en'
            rname = rdata.get(name_key, rkey)
            btn = tk.Button(self._circuit_rxn_frame,
                             text='  ' + self._reaction_icon_char(rdata['arrow']) + ' ' + rname,
                             bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=rdata['color'], relief='solid', bd=1,
                             font=('Arial', 9, 'bold'), cursor='hand2', anchor='w',
                             command=lambda k=rkey: self._circuit_select_reaction(k))
            btn.pack(fill='x', padx=2, pady=1)

    def _part_icon_char(self, icon_type):
        """Unicode character representing a part type (for catalog buttons)."""
        return {
            'promoter': '▶',
            'rbs': '○',
            'cds': '▭',
            'terminator': '⊥',
            'protein_circle': '●',
            'protein_square': '■',
            'protein_membrane': '◖',
            'small_mol': '◆',
            'cell': '',
            'membrane': '═',
            'binding_site': '▤',
            'mrna': '∿',
            'receptor': 'Y',
            'enzyme_diamond': '◆',
            'empty_diamond': '◇',
            'input_signal': '',
            'output_reporter': '',
        }.get(icon_type, '?')

    def _reaction_icon_char(self, arrow_type):
        """Unicode character for reaction arrow."""
        return {
            'solid_arrow': '',
            't_bar': '⊣',
            't_bar_dashed': '⊣',
            'knockout_x': '∅',
            'dashed_arrow': '',
            'dashed_circle': '○',
            'open_arrow': '▷',
            'cross_arrow': '',
            'thick_arrow': '',
            'double_arrow': '',
            'split_arrow': '⋎',
            'p_arrow': '+P',
            'p_arrow_open': '-P',
            'p_cycle': '⟲',
            'multi_arrow': '',
        }.get(arrow_type, '')

    def _circuit_set_tool(self, tool):
        """Set the active tool (select/connect/delete) and update button styles."""
        self._circuit_tool = tool
        self._circuit_connect_source = None
        # Update button styles
        for tkey, (btn, color) in self._circuit_tool_buttons.items():
            if tkey == tool:
                btn.config(bg=color, fg='#f5f7fa')
            else:
                btn.config(bg=biosim_theme('panel2'), fg=color)
        # Status hint
        hints = {
            'select': self._t('canvas_hint') if self._circuit_selected_part is None
                      else self._t('click_then_drop'),
            'connect': self._t('connecting_mode'),
            'delete': ('Кликни элемент чтобы удалить' if self.lang == 'ru'
                       else 'Click element to delete'),
        }
        self._circuit_status_lbl.config(text=hints.get(tool, ''))
        # Change cursor
        cursors = {'select': 'arrow', 'connect': 'crosshair', 'delete': 'pirate'}
        try:
            self.circuit_canvas.config(cursor=cursors.get(tool, 'arrow'))
        except Exception as _exc:
            biosim_log('warn', '_circuit_set_tool: {}'.format(_exc))

    def _circuit_select_part(self, part_key):
        """User clicked a part in the catalog — arm placement."""
        self._circuit_selected_part = part_key
        self._circuit_selected_reaction = None
        self._circuit_set_tool('select')
        part_data = CIRCUIT_PARTS_CATALOG.get(part_key, {})
        name = part_data.get('name_ru' if self.lang == 'ru' else 'name_en', part_key)
        msg = ('Кликни на холсте чтобы поставить: ' if self.lang == 'ru'
               else 'Click canvas to place: ') + name
        # Say where this part's numbers come from. A conventional value looks
        # exactly like a measured one on screen, which is how an invented
        # figure ends up driving a simulation unnoticed.
        ru, en, colour = part_provenance(part_data)
        if part_data.get('source'):
            msg += '  ·  ' + (ru if self.lang == 'ru' else en)
        self._circuit_status_lbl.config(text=msg,
                                        fg=colour if part_data.get('source')
                                        else biosim_theme('text'))
        # Change cursor to indicate placement mode
        try:
            self.circuit_canvas.config(cursor='plus')
        except Exception as _exc:
            biosim_log('warn', '_circuit_select_part: {}'.format(_exc))

    def _circuit_place_characterised(self, part_key):
        """Arm a named, measured part for placement.

        The measured relative strength is carried straight into the node, so
        the simulation runs on the published figure rather than on a round
        number chosen for looks.
        """
        pdata = CHARACTERISED_PARTS.get(part_key, {})
        strength = float(pdata.get('strength', 1.0))
        kind = pdata.get('kind', 'promoter')
        entry = {
            'name_ru': pdata.get('name_ru', part_key),
            'name_en': pdata.get('name_en', part_key),
            'desc_ru': pdata.get('note_ru', ''),
            'desc_en': pdata.get('note_en', ''),
            'source': 'measured',
        }
        if kind == 'rbs':
            entry.update({'family': 'Genes/RBS', 'icon': 'rbs',
                          'color': '#1a7f37',
                          'translation_rate': round(strength, 3)})
        elif kind == 'terminator':
            entry.update({'family': 'Genes/Terminator', 'icon': 'terminator',
                          'color': '#1a7f37',
                          'termination_efficiency': round(strength, 3)})
        else:
            # promoter: scale to the catalogue's units (strong promoter = 5.0)
            entry.update({'family': 'Genes/Promoters', 'icon': 'promoter',
                          'color': '#1a7f37',
                          'production': round(strength * 5.0, 3),
                          'leakage': round(0.02 + 0.08 * strength, 4)})
        CIRCUIT_PARTS_CATALOG[part_key] = entry
        self._circuit_select_part(part_key)

    def _circuit_select_reaction(self, rxn_key):
        """User clicked a reaction type — switch to connect mode."""
        self._circuit_selected_reaction = rxn_key
        self._circuit_selected_part = None
        self._circuit_set_tool('connect')
        rxn_data = CIRCUIT_REACTIONS.get(rxn_key, {})
        name = rxn_data.get('name_ru' if self.lang == 'ru' else 'name_en', rxn_key)
        msg = ('Связь: ' + name + '. Кликни источник, потом цель.' if self.lang == 'ru'
               else 'Connection: ' + name + '. Click source, then target.')
        self._circuit_status_lbl.config(text=msg)

    def _circuit_load_preset_from_combo(self):
        """Load preset based on combo selection."""
        sel_name = self._circuit_preset_var.get()
        for k, v in GENE_CIRCUIT_PRESETS.items():
            if v['name'] == sel_name:
                self._load_circuit_preset(k)
                break

    def _circuit_canvas_motion(self, event):
        """Update cursor based on hover state."""
        pass  # placeholder for hover effects

    def _circuit_style_ax(self):
        self.circuit_ax.set_facecolor('#ffffff')
        self.circuit_ax.tick_params(colors='#57606a')
        for sp in self.circuit_ax.spines.values():
            sp.set_color('#d0d7de')
        self.circuit_ax.set_xlabel('Time', color='#57606a')
        self.circuit_ax.set_ylabel('Protein', color='#57606a')

    def _load_circuit_preset(self, key):
        preset = GENE_CIRCUIT_PRESETS.get(key)
        if not preset:
            return
        if self.current_state['circuit'] is not None:
            self._save_history('circuit')
        # Deep-copy nodes and assign default icon/color if missing
        nodes = []
        for n in preset['nodes']:
            n_copy = dict(n)
            if 'icon' not in n_copy:
                n_copy['icon'] = 'protein_circle'  # default
            if 'color' not in n_copy:
                # Color by node id (first letter)
                colors = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df', '#bc4c00']
                idx = (ord(n['id'][0].upper()) - 65) % len(colors)
                n_copy['color'] = colors[idx]
            nodes.append(n_copy)
        self.current_state['circuit'] = {
            'name': preset['name'], 'description': preset['description'],
            'nodes': nodes,
            'edges': [dict(e) for e in preset['edges']],
            'init': dict(preset['init']),
        }
        self._circuit_refresh()

    def _circuit_refresh(self):
        state = self.current_state['circuit']
        if state is None:
            return
        info = [(state['name'] + '\n', 'ttl'),
                ('-' * 30 + '\n', 'dim'),
                (state['description'] + '\n\n', 'nrm'),
                (self._t('placed_items') + ' {}\n'.format(len(state['nodes'])), 'ok'),
                (self._t('placed_connections') + ' {}\n\n'.format(len(state['edges'])), 'ok')]
        if state['nodes']:
            # Group by family
            by_family = {}
            for n in state['nodes']:
                pk = n.get('part_key', '')
                pdata = CIRCUIT_PARTS_CATALOG.get(pk, {})
                family = pdata.get('family', 'Other')
                family_top = family.split('/')[0]
                if family_top not in by_family:
                    by_family[family_top] = []
                by_family[family_top].append(n)
            for fam, nlist in by_family.items():
                info.append((fam + ': ' + str(len(nlist)) + '\n', 'ttl'))
                for n in nlist:
                    info.append(('  · {}\n'.format(n['id'][:18]), 'nrm'))
            info.append(('\n', 'nrm'))
        if state['edges']:
            info.append(('Connections:\n' if self.lang == 'en' else 'Связи:\n', 'ttl'))
            for e in state['edges']:
                rxn = e.get('reaction', e['type'])
                arrow = '->' if e['type'] == 'activation' else '-|'
                tag = 'act' if e['type'] == 'activation' else 'rep'
                info.append(('  {} {} {} [{}]\n'.format(
                    e['from'][:8], arrow, e['to'][:8], rxn[:10]), tag))
        self._set_text(self.circuit_info, info)
        self._circuit_draw_diagram()

    def _circuit_draw_diagram(self):
        """Draw cartoon-style diagram (TinkerCell-like)."""
        c = self.circuit_canvas
        c.delete('all')
        state = self.current_state['circuit']
        if state is None:
            return
        nodes = state['nodes']
        edges = state['edges']
        w = c.winfo_width() or 600
        h = c.winfo_height() or 380
        pos = {n['id']: (n['x'], n['y']) for n in nodes}

        # Draw edges first (under nodes)
        for e in edges:
            if e['from'] not in pos or e['to'] not in pos:
                continue
            x1, y1 = pos[e['from']]
            x2, y2 = pos[e['to']]
            # Get reaction style
            rxn_key = e.get('reaction', e['type'])
            rxn_data = CIRCUIT_REACTIONS.get(rxn_key, CIRCUIT_REACTIONS.get(e['type'], {}))
            color = rxn_data.get('color', '#1a7f37' if e['type'] == 'activation' else '#cf222e')
            arrow_style = rxn_data.get('arrow', 'solid_arrow')

            if e['from'] == e['to']:
                # Self-loop
                c.create_oval(x1 + 28, y1 - 30, x1 + 70, y1 + 10,
                                outline=color, width=2)
                continue
            # Compute endpoints on circle boundary
            dx_e = x2 - x1; dy_e = y2 - y1
            d = max(1, math.sqrt(dx_e * dx_e + dy_e * dy_e))
            ux = dx_e / d; uy = dy_e / d
            r = 28
            sx = x1 + ux * r; sy = y1 + uy * r
            ex = x2 - ux * r; ey = y2 - uy * r

            # Draw line based on arrow style
            if arrow_style in ('dashed_arrow', 'dashed_circle'):
                c.create_line(sx, sy, ex, ey, fill=color, width=2, dash=(5, 3))
            elif arrow_style == 't_bar':
                c.create_line(sx, sy, ex, ey, fill=color, width=2, dash=(4, 3))
            else:
                c.create_line(sx, sy, ex, ey, fill=color, width=2)

            # Draw arrowhead based on style
            ang = math.atan2(uy, ux)
            if arrow_style == 't_bar':
                # Perpendicular bar
                px = -uy; py = ux
                c.create_line(ex - px * 10, ey - py * 10,
                                ex + px * 10, ey + py * 10,
                                fill=color, width=3)
            elif arrow_style == 'cross_arrow':
                # X mark
                c.create_line(ex - 6, ey - 6, ex + 6, ey + 6, fill=color, width=2)
                c.create_line(ex - 6, ey + 6, ex + 6, ey - 6, fill=color, width=2)
            elif arrow_style == 'open_arrow':
                # Open V-arrow (not filled)
                ax_pt = ex - 12 * math.cos(ang - 0.4)
                ay_pt = ey - 12 * math.sin(ang - 0.4)
                bx_pt = ex - 12 * math.cos(ang + 0.4)
                by_pt = ey - 12 * math.sin(ang + 0.4)
                c.create_line(ax_pt, ay_pt, ex, ey, fill=color, width=2)
                c.create_line(bx_pt, by_pt, ex, ey, fill=color, width=2)
            elif arrow_style == 'dashed_circle':
                # Small open circle at end (catalysis indicator)
                c.create_oval(ex - 5, ey - 5, ex + 5, ey + 5,
                               outline=color, width=2)
            else:
                # Standard filled triangle
                ax_pt = ex - 10 * math.cos(ang - 0.4)
                ay_pt = ey - 10 * math.sin(ang - 0.4)
                bx_pt = ex - 10 * math.cos(ang + 0.4)
                by_pt = ey - 10 * math.sin(ang + 0.4)
                c.create_polygon(ex, ey, ax_pt, ay_pt, bx_pt, by_pt,
                                   fill=color, outline=color)

        # Draw nodes as cartoon icons
        for n in nodes:
            x, y = n['x'], n['y']
            icon = n.get('icon', 'protein_circle')
            color = n.get('color', '#0969da')
            self._circuit_draw_icon(c, x, y, icon, color, n['id'])

        # Empty canvas hint
        if not nodes:
            c.create_text(w // 2, h // 2,
                           text=self._t('canvas_hint'),
                           fill='#484f58', font=('Arial', 12, 'italic'))

        # Legend at bottom
        c.create_text(10, h - 40, text=self._t('activation_legend'), fill='#1a7f37',
                        font=('Arial', 9), anchor='w')
        c.create_text(10, h - 22, text=self._t('repression_legend'), fill='#cf222e',
                        font=('Arial', 9), anchor='w')

    def _circuit_draw_icon(self, c, x, y, icon_type, color, label, size_factor=1.0):
        """Draw a cartoon icon for a part type.
        size_factor: 1.0 = default, 0.7 = small, 1.5 = large"""
        # Scale all dimensions
        s = size_factor
        dark = self._darken_hex(color, 0.7)
        light = self._lighten_hex(color, 1.3)

        # DNA backbone baseline: y offset where the part sits ON the strand.
        # Every DNA part draws a short black segment here; placed next to each
        # other these segments merge into one continuous strand (TinkerCell).
        bb = biosim_theme('text')                 # strand colour (theme-aware)
        base_y = y + int(16 * s)                  # strand line a bit below centre
        seg = int(30 * s)                         # half-length of each part's segment
        name_y = base_y + int(16 * s)             # labels sit BELOW the strand, far
        name_font = ('Helvetica', max(8, int(9 * s)))

        if icon_type == 'promoter':
            # Built-in strand segment underneath
            c.create_line(x - seg, base_y, x + seg, base_y, fill=bb, width=max(2, int(3*s)))
            # Bent arrow (SBOL promoter) rising from the strand
            c.create_line(x - int(16*s), base_y, x - int(16*s), base_y - int(26*s),
                          fill=bb, width=max(2, int(3*s)))
            c.create_line(x - int(16*s), base_y - int(26*s), x + int(14*s), base_y - int(26*s),
                          fill=bb, width=max(2, int(3*s)))
            c.create_polygon(x + int(14*s), base_y - int(31*s), x + int(14*s), base_y - int(21*s),
                              x + int(24*s), base_y - int(26*s),
                              fill=bb, outline=bb)
            # name below, plain black, no box
            c.create_text(x, name_y, text=label[:12], fill=bb, font=name_font)

        elif icon_type == 'rbs':
            c.create_line(x - seg, base_y, x + seg, base_y, fill=bb, width=max(2, int(3*s)))
            # half-dome sitting on the strand
            c.create_arc(x - int(14*s), base_y - int(26*s), x + int(14*s), base_y + int(2*s),
                          start=0, extent=180,
                          fill=color, outline=bb, width=max(1, int(2*s)))
            c.create_text(x, name_y, text=label[:12], fill=bb, font=name_font)

        elif icon_type == 'cds':
            c.create_line(x - seg, base_y, x + seg, base_y, fill=bb, width=max(2, int(3*s)))
            # arrow-pentagon sitting on the strand
            top = base_y - int(24*s)
            pts = [x - int(22*s), top, x + int(12*s), top,
                    x + int(24*s), base_y - int(12*s), x + int(12*s), base_y,
                    x - int(22*s), base_y]
            c.create_polygon(pts, fill=color, outline=bb, width=max(1, int(2*s)))
            c.create_text(x - int(4*s), base_y - int(12*s), text=label[:8], fill='#ffffff',
                           font=('Helvetica', max(8, int(9*s)), 'bold'))
            c.create_text(x, name_y, text=label[:12], fill=bb, font=name_font)

        elif icon_type == 'terminator':
            c.create_line(x - seg, base_y, x + seg, base_y, fill=bb, width=max(2, int(3*s)))
            # T rising from the strand (keep its red but readable in both themes)
            tcol = color if color.lower() not in ('#1c2128', '#000000') else biosim_theme('danger')
            c.create_line(x, base_y, x, base_y - int(26*s), fill=tcol, width=max(2, int(4*s)))
            c.create_line(x - int(13*s), base_y - int(26*s), x + int(13*s), base_y - int(26*s),
                           fill=tcol, width=max(2, int(4*s)))
            c.create_text(x, name_y, text=label[:12], fill=bb, font=name_font)

        elif icon_type == 'protein_circle':
            r = int(25 * s)
            c.create_oval(x - r - 1, y - r + 3, x + r + 5, y + r + 3,
                            fill='#f5f7fa', outline='')
            c.create_oval(x - r, y - r, x + r, y + r,
                            fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_oval(x - int(18*s), y - int(22*s), x - int(5*s), y - int(10*s),
                            fill=light, outline='')
            c.create_text(x, y, text=label[:6], fill='#f5f7fa',
                           font=('Arial', max(8, int(9*s)), 'bold'))

        elif icon_type == 'protein_square':
            r = int(25 * s)
            c.create_rectangle(x - r, y - int(22*s), x + r, y + int(22*s),
                                fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_rectangle(x - int(22*s), y - int(19*s), x - int(8*s), y - int(12*s),
                                fill=light, outline='')
            c.create_text(x, y + 2, text=label[:6], fill='#f5f7fa',
                           font=('Arial', max(8, int(9*s)), 'bold'))

        elif icon_type == 'protein_membrane':
            r = int(25 * s)
            c.create_arc(x - r, y - r, x + r, y + r, start=0, extent=180,
                          fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_text(x, y - int(8*s), text=label[:6], fill='#f5f7fa',
                           font=('Arial', max(8, int(9*s)), 'bold'))

        elif icon_type == 'small_mol':
            r = int(22 * s)
            pts = [x, y - r, x + r, y, x, y + r, x - r, y]
            c.create_polygon(pts, fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_polygon(x - int(14*s), y - int(4*s), x - int(4*s), y - int(14*s),
                              x - int(8*s), y, fill=light, outline='')
            c.create_text(x, y, text=label[:6], fill='#f5f7fa',
                           font=('Arial', max(8, int(9*s)), 'bold'))

        elif icon_type == 'cell':
            # Big hexagon (compartment) — already drawn by _cons_draw_cartoon for cells
            r = int(35 * s)
            pts = []
            for i in range(6):
                a = math.pi / 6 + i * math.pi / 3
                pts.extend([x + r * math.cos(a), y + r * math.sin(a)])
            c.create_polygon(pts, fill='', outline=color, width=max(2, int(3*s)), dash=(8, 4))
            c.create_text(x, y - r - 10, text=label[:10], fill=color,
                           font=('Arial', max(8, int(9*s)), 'bold'))

        elif icon_type == 'binding_site':
            # Operator / binding site: small striped box sitting on the strand.
            bb2 = biosim_theme('text')
            base_y2 = y + int(16 * s)
            c.create_line(x - int(30*s), base_y2, x + int(30*s), base_y2,
                          fill=bb2, width=max(2, int(3*s)))
            w_box = int(24 * s)
            h_box = int(12 * s)
            c.create_rectangle(x - w_box, base_y2 - int(24*s), x + w_box, base_y2,
                                fill=color, outline=bb2, width=max(1, int(2*s)))
            for sx in range(-w_box + 5, w_box - 5, 6):
                c.create_line(x + sx, base_y2 - int(22*s), x + sx, base_y2 - int(2*s),
                                fill='#ffffff', width=1)
            c.create_text(x, base_y2 + int(16 * s), text=label[:12], fill=bb2,
                           font=('Helvetica', max(8, int(9*s))))

        elif icon_type == 'mrna':
            # Wavy line (mRNA = wavy line)
            wn = 6
            pts = []
            for i in range(wn * 2 + 1):
                px = x - int(20*s) + i * int(40*s) / (wn * 2)
                py = y + (int(6*s) if i % 2 else -int(6*s))
                pts.append(px); pts.append(py)
            c.create_line(*pts, fill=color, width=max(2, int(3*s)), smooth=True)
            c.create_text(x, y + int(18*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'receptor':
            # Y-shape (receptor with extracellular domain)
            c.create_line(x, y - int(15*s), x, y + int(15*s), fill=color, width=max(2, int(3*s)))
            c.create_line(x, y - int(15*s), x - int(12*s), y - int(25*s), fill=color, width=max(2, int(3*s)))
            c.create_line(x, y - int(15*s), x + int(12*s), y - int(25*s), fill=color, width=max(2, int(3*s)))
            # Membrane disk
            c.create_oval(x - int(18*s), y + int(8*s), x + int(18*s), y + int(20*s),
                            fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_text(x, y + int(30*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'enzyme_diamond':
            # Yellow diamond with "E" mark
            r = int(20*s)
            pts = [x, y - r, x + r, y, x, y + r, x - r, y]
            c.create_polygon(pts, fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_text(x, y, text='E', fill='#f5f7fa',
                           font=('Arial', max(10, int(12*s)), 'bold'))
            c.create_text(x, y + int(22*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'empty_diamond':
            # Gray dashed diamond (placeholder)
            r = int(20*s)
            pts = [x, y - r, x + r, y, x, y + r, x - r, y]
            c.create_polygon(pts, fill='', outline=color, width=max(2, int(2*s)))
            c.create_text(x, y, text='?', fill=color,
                           font=('Arial', max(11, int(13*s)), 'bold'))
            c.create_text(x, y + int(22*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'input_signal':
            # Pentagon arrow shape (input)
            r = int(22 * s)
            pts = [x - r, y - r, x + int(r/2), y - r, x + r, y,
                    x + int(r/2), y + r, x - r, y + r]
            c.create_polygon(pts, fill=color, outline=dark, width=max(1, int(2*s)))
            # Use up arrow inside
            c.create_text(x - int(4*s), y, text='', fill='#f5f7fa',
                           font=('Arial', max(11, int(13*s)), 'bold'))
            c.create_text(x, y + int(20*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'output_reporter':
            # Display/monitor shape (output measurement)
            r = int(20 * s)
            # Rounded rectangle (a "screen")
            c.create_rectangle(x - r, y - int(r*0.7), x + r, y + int(r*0.7),
                                fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_text(x, y, text='', fill='#f5f7fa',
                           font=('Arial', max(10, int(12*s)), 'bold'))
            c.create_text(x, y + int(18*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'membrane':
            c.create_line(x - int(30*s), y - 2, x + int(30*s), y - 2,
                           fill=color, width=max(2, int(3*s)))
            c.create_line(x - int(30*s), y + 4, x + int(30*s), y + 4,
                           fill=color, width=max(2, int(3*s)))
            c.create_text(x, y + int(16*s), text=label[:8], fill=color,
                           font=('Arial', max(7, int(8*s)), 'bold'))

        elif icon_type == 'knockout':
            # Knockout marker: a circle with a diagonal slash (∅ "no entry").
            # Theme-aware stroke so it stays visible on the dark (Graphite) bg.
            ko_stroke = biosim_theme('text')      # near-black on light, near-white on dark
            ko_fill = biosim_theme('panel')       # white on light, graphite on dark
            r = int(22 * s)
            c.create_oval(x - r, y - r, x + r, y + r,
                            fill=ko_fill, outline=ko_stroke, width=max(3, int(4*s)))
            # Diagonal slash
            d = int(r * 0.72)
            c.create_line(x - d, y - d, x + d, y + d,
                            fill=ko_stroke, width=max(3, int(4*s)))
            c.create_text(x, y + int(30*s), text=label[:10] or 'KO', fill=ko_stroke,
                           font=('Helvetica', max(8, int(9*s))))

        else:
            r = int(25 * s)
            c.create_oval(x - r, y - r, x + r, y + r,
                            fill=color, outline=dark, width=max(1, int(2*s)))
            c.create_text(x, y, text=label[:6], fill='#f5f7fa',
                           font=('Arial', max(8, int(9*s)), 'bold'))




    def _circuit_suggest_template(self):
        """Offer a starter circuit for a therapeutic approach.

        `suggest_gene_circuit` held a set of worked templates (gene therapy,
        CRISPR delivery, CAR-T, inducible therapeutic cell, oncolytic virus)
        that the interface never exposed, so a user starting a new circuit had
        to assemble every standard layout from scratch.
        """
        is_ru = (self.lang == 'ru')
        d = tk.Toplevel(self)
        d.title('Готовые схемы' if is_ru else 'Circuit templates')
        d.geometry('600x520')
        d.configure(bg=biosim_theme('bg'))
        d.transient(self)

        tk.Label(d, text=('С чего начать схему' if is_ru
                          else 'Starting points for a circuit'),
                 bg=biosim_theme('bg'), fg='#8250df',
                 font=('Arial', 14, 'bold')).pack(pady=(10, 2))
        tk.Label(d, text=('Выберите подход — детали подставятся в конструктор, '
                          'дальше их можно менять' if is_ru else
                          'Pick an approach — the parts load into the builder '
                          'and can be changed afterwards'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 9), wraplength=540).pack(pady=(0, 8))

        holder = tk.Frame(d, bg=biosim_theme('bg'))
        holder.pack(fill='both', expand=True, padx=10, pady=4)
        cv = tk.Canvas(holder, bg=biosim_theme('bg'), highlightthickness=0)
        sb = tk.Scrollbar(holder, orient='vertical', command=cv.yview)
        cv.configure(yscrollcommand=sb.set)
        cv.pack(side='left', fill='both', expand=True)
        sb.pack(side='right', fill='y')
        inner = tk.Frame(cv, bg=biosim_theme('bg'))
        inner.bind('<Configure>',
                   lambda e: cv.configure(scrollregion=cv.bbox('all')))
        cv.create_window((0, 0), window=inner, anchor='nw', width=550)

        approaches = ['gene_therapy', 'crispr', 'car_t', 'cell_therapy',
                      'oncolytic']

        def apply_template(tpl):
            # current_state['circuit'] starts as None, and setdefault happily
            # hands that None straight back, so assigning into it failed.
            if not isinstance(self.current_state.get('circuit'), dict):
                self.current_state['circuit'] = {
                    'name': '', 'description': '', 'nodes': [], 'edges': [],
                    'init': {}}
            state = self.current_state['circuit']
            try:
                self._save_history('circuit')
            except Exception as exc:
                biosim_log('warn', 'apply_template history: {}'.format(exc))
            nodes, x = [], 90
            used = set()
            for i, part in enumerate(tpl.get('parts', [])):
                nid = part.split('(')[0].strip()[:18] or 'part{}'.format(i)
                while nid in used:                 # ids must stay unique
                    nid = nid[:16] + str(i)
                used.add(nid)
                nodes.append({'id': nid, 'type': 'gene',
                              'x': x, 'y': 150 + (i % 2) * 90,
                              'production': 1.0, 'degradation': 0.1,
                              'label': part})
                x += 130
            # The engine keys edges 'from'/'to'. Using 'source'/'target' here
            # loaded the parts but silently dropped every connection, so the
            # template arrived on the canvas as a row of unwired nodes.
            edges = [{'from': nodes[i]['id'], 'to': nodes[i + 1]['id'],
                      'type': 'activation', 'strength': 1.0}
                     for i in range(len(nodes) - 1)]
            state['name'] = tpl.get('name_ru' if is_ru else 'name_en', 'Template')
            state['description'] = tpl.get('desc_ru' if is_ru else 'desc_en', '')
            state['nodes'] = nodes
            state['edges'] = edges
            state['init'] = {n['id']: 0.0 for n in nodes}
            d.destroy()
            try:
                self._switch_tab('circuit')
            except Exception as exc:
                biosim_log('warn', 'apply_template switch: {}'.format(exc))
            try:
                self._circuit_refresh()
            except Exception as exc:
                biosim_log('warn', 'apply_template refresh: {}'.format(exc))

        for key in approaches:
            try:
                tpl = suggest_gene_circuit(key)
            except Exception as exc:
                biosim_log('warn', 'suggest_gene_circuit {}: {}'.format(key, exc))
                continue
            if not tpl:
                continue
            card = tk.Frame(inner, bg=biosim_theme('panel'), relief='solid', bd=1)
            card.pack(fill='x', pady=4)
            tk.Label(card, text=tpl.get('name_ru' if is_ru else 'name_en', key),
                     bg=biosim_theme('panel'), fg=biosim_theme('text'),
                     font=('Arial', 11, 'bold')).pack(anchor='w', padx=10,
                                                      pady=(6, 0))
            tk.Label(card, text=tpl.get('desc_ru' if is_ru else 'desc_en', ''),
                     bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                     font=('Arial', 9), wraplength=500,
                     justify='left').pack(anchor='w', padx=10)
            tk.Label(card, text='  →  '.join(tpl.get('parts', [])),
                     bg=biosim_theme('panel'), fg='#0969da',
                     font=('Courier', 8), wraplength=500,
                     justify='left').pack(anchor='w', padx=10, pady=(2, 2))
            tk.Button(card, text=('Загрузить в конструктор' if is_ru
                                  else 'Load into builder'),
                      bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                      relief='flat', font=('Arial', 9, 'bold'), cursor='hand2',
                      command=lambda t=tpl: apply_template(t)
                      ).pack(anchor='e', padx=10, pady=(0, 8))

    def _plasmid_open_digest(self):
        """Restriction digest of the current plasmid with a gel view.

        `restriction_digest_custom` was written but unreachable, so the plasmid
        section could draw a map without ever answering the practical question:
        what fragments come out, and will they separate on a gel.
        """
        is_ru = (self.lang == 'ru')
        state = self.current_state.get('plasmid') or {}
        seq = (state.get('sequence') or '').upper()
        if len(seq) < 30:
            Toast(self, 'Сначала загрузите плазмиду' if is_ru
                  else 'Load a plasmid first')
            return

        common = {
            'EcoRI': 'GAATTC', 'BamHI': 'GGATCC', 'HindIII': 'AAGCTT',
            'XhoI': 'CTCGAG', 'NotI': 'GCGGCCGC', 'PstI': 'CTGCAG',
            'SalI': 'GTCGAC', 'XbaI': 'TCTAGA', 'SpeI': 'ACTAGT',
            'KpnI': 'GGTACC', 'SacI': 'GAGCTC', 'NcoI': 'CCATGG',
            'NdeI': 'CATATG', 'BglII': 'AGATCT', 'SmaI': 'CCCGGG',
        }

        win = tk.Toplevel(self)
        win.title('Рестрикционный анализ' if is_ru else 'Restriction digest')
        win.geometry('820x620')
        win.configure(bg=biosim_theme('bg'))
        win.transient(self)

        tk.Label(win, text=('Рестрикционный анализ' if is_ru
                            else 'Restriction digest'),
                 bg=biosim_theme('bg'), fg='#0969da',
                 font=('Arial', 14, 'bold')).pack(pady=(10, 0))
        tk.Label(win, text='{} п.н.'.format(len(seq)), bg=biosim_theme('bg'),
                 fg=biosim_theme('text_dim'), font=('Arial', 9)).pack()

        pick = tk.Frame(win, bg=biosim_theme('bg'))
        pick.pack(fill='x', padx=12, pady=6)
        tk.Label(pick, text=('Ферменты:' if is_ru else 'Enzymes:'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text'),
                 font=('Arial', 10, 'bold')).pack(anchor='w')
        grid = tk.Frame(pick, bg=biosim_theme('bg'))
        grid.pack(fill='x')
        chosen = {}
        for i, (name, site) in enumerate(sorted(common.items())):
            n_sites = seq.count(site)
            v = tk.BooleanVar(value=False)
            chosen[name] = v
            cb = tk.Checkbutton(
                grid, text='{} ({}) ×{}'.format(name, site, n_sites),
                variable=v, bg=biosim_theme('bg'),
                fg=biosim_theme('text') if n_sites else biosim_theme('text_dim'),
                selectcolor=biosim_theme('panel2'), font=('Courier', 9),
                anchor='w', state='normal' if n_sites else 'disabled')
            cb.grid(row=i // 3, column=i % 3, sticky='w', padx=4)

        canvas = tk.Canvas(win, bg=biosim_theme('panel'), height=210,
                           highlightthickness=0)
        canvas.pack(fill='x', padx=12, pady=6)
        out = scrolledtext.ScrolledText(win, bg=biosim_theme('panel'),
                                        fg=biosim_theme('text'),
                                        font=('Courier', 10), relief='flat',
                                        height=8)
        out.pack(fill='both', expand=True, padx=12, pady=(0, 10))

        def run():
            sites = {n: common[n] for n, v in chosen.items() if v.get()}
            out.config(state='normal')
            out.delete('1.0', 'end')
            canvas.delete('all')
            if not sites:
                out.insert('end', 'Выберите хотя бы один фермент.\n' if is_ru
                           else 'Pick at least one enzyme.\n')
                out.config(state='disabled')
                return
            try:
                res = restriction_digest_custom(seq, sites)
            except Exception as exc:
                biosim_log('error', 'restriction digest: {}'.format(exc))
                out.insert('end', 'Ошибка: {}\n'.format(exc))
                out.config(state='disabled')
                return

            frags = res.get('fragments', []) if isinstance(res, dict) else []
            cuts = res.get('cuts', []) if isinstance(res, dict) else []
            lengths = []
            for fr in frags:
                lengths.append(fr.get('length', len(fr.get('sequence', ''))
                                      if isinstance(fr, dict) else 0)
                               if isinstance(fr, dict) else len(fr))

            out.insert('end', ('Разрезов: {} · фрагментов: {}\n\n'
                               .format(len(cuts), len(frags)) if is_ru else
                               'Cuts: {} · fragments: {}\n\n'
                               .format(len(cuts), len(frags))))
            for c in cuts:
                out.insert('end', '  {} @ {} п.н.\n'.format(
                    c.get('enzyme', '?'), c.get('position', 0)))
            out.insert('end', '\n' + ('Фрагменты (п.н.): ' if is_ru
                                      else 'Fragments (bp): ')
                       + ', '.join(str(l) for l in sorted(lengths, reverse=True))
                       + '\n')

            # ── gel view: fragments migrate by log of length ──────────
            W = canvas.winfo_width() or 780
            top, bottom = 24, 186
            canvas.create_text(W // 2, 10, text=('Электрофорез (агароза)' if is_ru
                                                 else 'Agarose gel'),
                               fill=biosim_theme('text_dim'), font=('Arial', 9))
            ladder = [10000, 5000, 3000, 2000, 1500, 1000, 750, 500, 250, 100]
            lo, hi = math.log10(80), math.log10(12000)

            def ypos(bp):
                bp = max(80, min(12000, bp))
                frac = (math.log10(bp) - lo) / (hi - lo)
                return bottom - frac * (bottom - top)

            for b in ladder:
                y = ypos(b)
                canvas.create_line(60, y, 130, y, fill='#8250df', width=3)
                canvas.create_text(52, y, text=str(b), anchor='e',
                                   fill=biosim_theme('text_dim'),
                                   font=('Arial', 7))
            canvas.create_text(95, bottom + 14, text=('маркер' if is_ru
                                                      else 'ladder'),
                               fill=biosim_theme('text_dim'), font=('Arial', 8))
            lane_x1, lane_x2 = 190, 330
            seen = {}
            for l in lengths:
                seen[l] = seen.get(l, 0) + 1
            for l, count in seen.items():
                y = ypos(l)
                width = 3 + min(5, count * 2)
                canvas.create_line(lane_x1, y, lane_x2, y, fill='#1a7f37',
                                   width=width)
                canvas.create_text(lane_x2 + 8, y, anchor='w',
                                   text='{} п.н.{}'.format(
                                       l, ' ×{}'.format(count) if count > 1 else ''),
                                   fill=biosim_theme('text'), font=('Arial', 8))
            canvas.create_text((lane_x1 + lane_x2) // 2, bottom + 14,
                               text=('образец' if is_ru else 'sample'),
                               fill=biosim_theme('text_dim'), font=('Arial', 8))

            close = [l for l in sorted(set(lengths)) if l > 0]
            warn = []
            for a, b in zip(close, close[1:]):
                if b - a < max(50, a * 0.1):
                    warn.append((a, b))
            if warn:
                out.insert('end', '\n' + ('На геле не разделятся: ' if is_ru
                                          else 'Will not separate on a gel: ')
                           + '; '.join('{} и {}'.format(a, b) for a, b in warn)
                           + '\n')
            out.config(state='disabled')

        tk.Button(pick, text=('Резать' if is_ru else 'Digest'), bg='#1a7f37',
                  highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 10, 'bold'), cursor='hand2', padx=16,
                  command=run).pack(anchor='w', pady=6)

    def _circuit_canvas_click(self, event):
        """Pick up the node under the cursor so it can be dragged.

        This handler was bound to <Button-1> but never defined, so opening the
        gene-circuit tab raised AttributeError and the tab failed to build.
        """
        state = self.current_state.get('circuit') or {}
        nodes = state.get('nodes') or []
        self._circuit_drag_node = None
        self._circuit_drag_offset = (0, 0)
        hit_radius = 32
        best, best_d = None, None
        for n in nodes:
            dx = event.x - n.get('x', 0)
            dy = event.y - n.get('y', 0)
            d = (dx * dx + dy * dy) ** 0.5
            if d <= hit_radius and (best_d is None or d < best_d):
                best, best_d = n, d
        if best is None:
            return
        self._circuit_drag_node = best['id']
        self._circuit_drag_offset = (event.x - best.get('x', 0),
                                     event.y - best.get('y', 0))
        try:
            self._circuit_select_node(best['id'])
        except Exception as exc:
            biosim_log('info', '_circuit_canvas_click select: {}'.format(exc))

    def _circuit_canvas_drag(self, event):
        if self._circuit_drag_node is None:
            return
        state = self.current_state['circuit']
        ox, oy = self._circuit_drag_offset
        for n in state['nodes']:
            if n['id'] == self._circuit_drag_node:
                n['x'] = event.x - ox
                n['y'] = event.y - oy
                break
        self._circuit_draw_diagram()

    def _circuit_canvas_release(self, event):
        if self._circuit_drag_node is not None:
            self._save_history('circuit')
        self._circuit_drag_node = None

    def _circuit_clear(self):
        if not messagebox.askyesno('VIREON', self._t('clear_confirm')):
            return
        self._save_history('circuit')
        self.current_state['circuit'] = {'name': 'Empty', 'description': '',
                                          'nodes': [], 'edges': [], 'init': {}}
        self._circuit_refresh()

    def _circuit_simulate(self):
        state = self.current_state['circuit']
        if state is None or not state['nodes']:
            messagebox.showinfo('VIREON', self._t('add_gene_first'))
            return
        t_end = safe_int(self.circuit_tend.get(), 100)
        t, sol = simulate_circuit(state['nodes'], state['edges'], state['init'], t_end=t_end)
        if t is None:
            messagebox.showinfo('VIREON', self._t('sim_failed'))
            return
        self.circuit_ax.clear()
        self._circuit_style_ax()
        colors = ['#0969da', '#1a7f37', '#cf222e', '#9a6700', '#8250df',
                   '#bc4c00', '#0550ae', '#8250df']
        for i, n in enumerate(state['nodes']):
            self.circuit_ax.plot(t, sol[:, i], color=colors[i % len(colors)],
                                  lw=2, label=n['id'])
        self.circuit_ax.grid(True, color='#eef1f5', lw=0.5)
        self.circuit_ax.legend(facecolor='#eef1f5', edgecolor='#d0d7de',
                                labelcolor='#1c2128', fontsize=9)
        self.circuit_ax.set_title(state['name'], color='#57606a', fontsize=10)
        self.circuit_cv.draw()
        info_extra = [('\n' + self._t('final_values') + '\n', 'ttl')]
        for i, n in enumerate(state['nodes']):
            final = float(sol[-1, i])
            info_extra.append(('  {}: {:.3f}\n'.format(n['id'], final),
                                'ok' if final > 0.5 else 'dim'))
        n_pts = sol.shape[0]
        last_third = sol[n_pts * 2 // 3:]
        max_amp = max(float(np.max(last_third[:, i]) - np.min(last_third[:, i]))
                       for i in range(sol.shape[1]))
        if max_amp > 0.3:
            info_extra.append(('\n' + self._t('oscillations').format(max_amp) + '\n', 'ok'))
        else:
            info_extra.append(('\n' + self._t('steady_state') + '\n', 'dim'))
        self.circuit_info.config(state='normal')
        for txt, tag in info_extra:
            self.circuit_info.insert('end', txt, tag)
        self.circuit_info.config(state='disabled')

