    def _plasmid_render_parts_library(self):
        """Render the scrollable parts library grouped by category."""
        for w in self._plasmid_parts_scroll_frame.winfo_children():
            w.destroy()
        # Combine builtin + custom parts
        all_parts = dict(PLASMID_PARTS)
        all_parts.update(self._custom_genes)
        # Group by type
        categories = {
            'promoter': self._t('category_promoter'),
            'rbs': self._t('category_rbs'),
            'gene': self._t('category_gene'),
            'signal': self._t('category_signal'),
            'regulator': self._t('category_regulator'),
            'terminator': self._t('category_terminator'),
            'origin': self._t('category_origin'),
            'resistance': self._t('category_resistance'),
            'tag': self._t('category_tag'),
        }
        for cat_type, cat_label in categories.items():
            cat_parts = [(k, p) for k, p in all_parts.items() if p['type'] == cat_type]
            if not cat_parts:
                continue
            tk.Label(self._plasmid_parts_scroll_frame, text=cat_label,
                      bg=biosim_theme('panel'), fg='#0969da',
                      font=('Arial', 9, 'bold'), anchor='w'
                      ).pack(fill='x', padx=2, pady=(6, 2), anchor='w')
            for pkey, pdata in cat_parts:
                color = pdata.get('color', '#1a7f37')
                btn_text = '{} ({}bp)'.format(pdata['name'], pdata['length'])
                if pdata.get('strength', 0) > 0:
                    btn_text += ' [{}]'.format(pdata['strength'])
                btn = tk.Button(self._plasmid_parts_scroll_frame,
                                 text=btn_text,
                                 bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=color, relief='solid', bd=1,
                                 font=('Arial', 8), cursor='hand2', anchor='w',
                                 command=lambda k=pkey: self._plasmid_add_part(k))
                btn.pack(fill='x', padx=2, pady=1)
                # Tooltip via label below (compact desc)
                desc = pdata.get('desc_ru' if self.lang == 'ru' else 'desc_en', '')
                if desc:
                    tk.Label(self._plasmid_parts_scroll_frame, text='  ' + desc[:38],
                              bg=biosim_theme('panel'), fg='#6a737d',
                              font=('Arial', 7, 'italic'), anchor='w'
                              ).pack(fill='x', padx=2, pady=0, anchor='w')
        self._plasmid_parts_canvas.update_idletasks()
        self._plasmid_parts_canvas.configure(
            scrollregion=self._plasmid_parts_canvas.bbox('all'))

    def _plasmid_add_part(self, part_key):
        """Add a part to the current plasmid."""
        state = self.current_state['plasmid']
        self._save_history('plasmid')
        # Find next free instance_id
        existing_ids = [p['instance_id'] for p in state['parts']]
        new_id = max(existing_ids) + 1 if existing_ids else 0
        state['parts'].append({'part_key': part_key, 'instance_id': new_id})
        self._plasmid_refresh()

    def _plasmid_remove_part(self, instance_id):
        state = self.current_state['plasmid']
        self._save_history('plasmid')
        state['parts'] = [p for p in state['parts'] if p['instance_id'] != instance_id]
        self._plasmid_refresh()

    def _plasmid_move_part(self, instance_id, direction):
        state = self.current_state['plasmid']
        idx = next((i for i, p in enumerate(state['parts'])
                     if p['instance_id'] == instance_id), -1)
        if idx < 0:
            return
        new_idx = idx + direction
        if 0 <= new_idx < len(state['parts']):
            self._save_history('plasmid')
            state['parts'][idx], state['parts'][new_idx] = (
                state['parts'][new_idx], state['parts'][idx])
            self._plasmid_refresh()

    def _plasmid_load_template(self, tkey):
        tmpl = PLASMID_TEMPLATES.get(tkey)
        if not tmpl:
            return
        self._save_history('plasmid')
        self.current_state['plasmid'] = {
            'name': tmpl['name'],
            'parts': [dict(p) for p in tmpl['parts']],
            'host': tmpl['host'],
            'description': tmpl.get('description', ''),
        }
        self.plasmid_host_var.set(tmpl['host'])
        self._plasmid_refresh()

    def _plasmid_host_changed(self):
        state = self.current_state['plasmid']
        state['host'] = self.plasmid_host_var.get()
        self._plasmid_refresh()

    def _plasmid_refresh(self):
        """Re-draw plasmid map + assembly + info."""
        self._plasmid_draw_map()
        self._plasmid_draw_assembly()
        self._plasmid_update_info()

    def _plasmid_draw_map(self):
        """Dispatcher: draw either circular or linear SBOL view."""
        mode = getattr(self, 'plasmid_view_mode', None)
        if mode is None or mode.get() == 'circle':
            self._plasmid_draw_map_circle()
        else:
            self._plasmid_draw_map_linear_sbol()

    def _plasmid_draw_map_linear_sbol(self):
        """Draw linear SBOL-style horizontal view (like biomolecula image).
        Each part has its own iconic shape: promoter=arrow, RBS=semicircle,
        gene=arrow-box, terminator=T-bar, etc."""
        c = self.plasmid_canvas
        c.delete('all')
        w = c.winfo_width() or 600
        h = c.winfo_height() or 380

        state = self.current_state['plasmid']
        parts = state['parts']
        metrics = calculate_plasmid_metrics(parts, state.get('host', 'E_coli_DH5a'))

        # Title at top
        c.create_text(w // 2, 18, text=state.get('name', '?'),
                       fill='#0969da', font=('Arial', 13, 'bold'))
        c.create_text(w // 2, 38, text='{} bp · {} {}'.format(
                       metrics['total_bp'], metrics['n_parts'],
                       'частей' if self.lang == 'ru' else 'parts'),
                       fill='#57606a', font=('Arial', 9))

        if not parts:
            c.create_text(w // 2, h // 2, text=self._t('no_parts'),
                           fill='#484f58', font=('Arial', 10, 'italic'))
            return

        all_parts_data = dict(PLASMID_PARTS)
        all_parts_data.update(self._custom_genes)

        # DNA backbone line (horizontal)
        y_center = h // 2
        margin = 30
        backbone_y = y_center

        # Calculate widths
        total_len = sum(all_parts_data.get(p['part_key'], {}).get('length', 100) for p in parts)
        if total_len == 0:
            total_len = 1
        usable_w = w - 2 * margin
        # Min part width to be visible
        min_part_w = 50

        # Draw DNA backbone first
        c.create_line(margin - 5, backbone_y, w - margin + 5, backbone_y,
                       fill='#484f58', width=2)
        # Cap ends (small circles for "this is a fragment of plasmid")
        c.create_oval(margin - 10, backbone_y - 4, margin - 3, backbone_y + 4,
                       fill='#484f58', outline='#484f58')
        c.create_oval(w - margin + 3, backbone_y - 4, w - margin + 10, backbone_y + 4,
                       fill='#484f58', outline='#484f58')

        x = margin
        for p in parts:
            part_data = all_parts_data.get(p['part_key'])
            if not part_data:
                continue
            length_bp = part_data['length']
            # Proportional width but with minimum
            part_w = max(min_part_w, int((length_bp / total_len) * usable_w * 0.85))
            if x + part_w > w - margin:
                part_w = w - margin - x
                if part_w < 20:
                    break
            ptype = part_data['type']
            color = part_data.get('color', '#1a7f37')
            dark = self._darken_hex(color, 0.65)

            # Draw SBOL-like shape based on type
            self._draw_sbol_part(c, ptype, x, backbone_y, part_w, color, dark,
                                  part_data['name'], length_bp, p['instance_id'])
            x += part_w + 2

        # Legend at bottom
        legend_y = h - 18
        c.create_text(10, legend_y, anchor='w',
                       text=self._t('sbol_legend'),
                       fill='#57606a', font=('Arial', 9, 'italic'))
        # Click hint
        c.create_text(w - 10, legend_y, anchor='e',
                       text=('Клик удалить' if self.lang == 'ru' else 'Click to remove'),
                       fill='#57606a', font=('Arial', 8, 'italic'))

    def _draw_sbol_part(self, c, ptype, x, y_center, width, color, dark, name, length, inst_id):
        """Draw a single SBOL part with its iconic shape."""
        h_main = 36  # main shape height
        y_top = y_center - h_main // 2
        y_bot = y_center + h_main // 2
        cx = x + width // 2

        if ptype == 'promoter':
            # Bent arrow: horizontal line + 90° turn + arrowhead
            arrow_x_end = x + width - 8
            arrow_y_top = y_top - 8
            # vertical part of arrow (goes up from baseline)
            c.create_line(x + 6, y_center, x + 6, arrow_y_top + 4,
                           fill=color, width=3)
            # Horizontal part with arrow
            c.create_line(x + 6, arrow_y_top + 4, arrow_x_end, arrow_y_top + 4,
                           fill=color, width=3, arrow='last',
                           arrowshape=(10, 12, 5))
            # Label below baseline
            c.create_text(cx, y_center + 18, text=name[:10],
                           fill=color, font=('Arial', 9, 'bold'))
            c.create_text(cx, y_center + 32, text='{}bp'.format(length),
                           fill='#57606a', font=('Arial', 7))
        elif ptype == 'rbs':
            # Semicircle above baseline
            r = min(width // 2, 14)
            c.create_arc(cx - r, y_center - r * 2, cx + r, y_center,
                          start=0, extent=180, fill=color, outline=dark, width=2)
            c.create_text(cx, y_center + 14, text=name[:8],
                           fill=color, font=('Arial', 8, 'bold'))
        elif ptype == 'gene':
            # Big arrow-shaped block (like CDS in SBOL)
            arrow_head = min(14, width // 3)
            pts = [
                x, y_top,
                x + width - arrow_head, y_top,
                x + width, y_center,
                x + width - arrow_head, y_bot,
                x, y_bot,
            ]
            c.create_polygon(pts, fill=color, outline=dark, width=2)
            # Inner highlight
            hl_color = self._lighten_hex(color, 1.3)
            c.create_polygon([x + 2, y_top + 2,
                                x + width - arrow_head - 2, y_top + 2,
                                x + width - arrow_head - 2, y_top + 6,
                                x + 2, y_top + 6],
                               fill=hl_color, outline='')
            # Name
            c.create_text(cx - arrow_head // 2, y_center, text=name[:12],
                           fill='#f5f7fa', font=('Arial', 9, 'bold'))
            # Length below
            c.create_text(cx, y_bot + 12, text='{}bp'.format(length),
                           fill='#57606a', font=('Arial', 7))
        elif ptype == 'terminator':
            # T-bar (stem + horizontal bar on top)
            stem_x = cx
            stem_top = y_center - 18
            c.create_line(stem_x, y_center, stem_x, stem_top,
                           fill=color, width=3)
            # Top bar (horizontal)
            c.create_line(stem_x - 10, stem_top, stem_x + 10, stem_top,
                           fill=color, width=4)
            c.create_text(cx, y_center + 14, text=name[:8],
                           fill=color, font=('Arial', 8, 'bold'))
        elif ptype == 'origin':
            # Half-circle below baseline (replication bubble)
            r = min(width // 2 - 2, 16)
            c.create_arc(cx - r, y_center - r // 3, cx + r, y_center + r * 2,
                          start=180, extent=180, fill=color, outline=dark, width=2)
            # Wavy line inside (suggesting DNA replication)
            c.create_line(cx - r // 2, y_center + r // 2, cx, y_center + r // 4,
                           cx + r // 2, y_center + r // 2,
                           fill='white', width=1, smooth=True)
            c.create_text(cx, y_center + 30, text=name[:10],
                           fill=color, font=('Arial', 8, 'bold'))
        elif ptype == 'resistance':
            # Trapezoid (like a wedge) — looks like an enzyme that "protects"
            pts = [
                x + 4, y_top + 4,
                x + width - 4, y_top + 4,
                x + width - 8, y_bot - 4,
                x + 8, y_bot - 4,
            ]
            c.create_polygon(pts, fill=color, outline=dark, width=2)
            c.create_text(cx, y_center, text=name[:10],
                           fill='#f5f7fa', font=('Arial', 8, 'bold'))
        elif ptype == 'tag':
            # Small flag shape
            pts = [
                x + 2, y_center - 8,
                x + width - 8, y_center - 8,
                x + width, y_center,
                x + width - 8, y_center + 8,
                x + 2, y_center + 8,
            ]
            c.create_polygon(pts, fill=color, outline=dark, width=2)
            c.create_text(cx - 2, y_center, text=name[:10],
                           fill='#f5f7fa', font=('Arial', 8, 'bold'))
        elif ptype == 'signal':
            # Diamond (rotated square)
            pts = [
                cx, y_top + 4,
                x + width - 4, y_center,
                cx, y_bot - 4,
                x + 4, y_center,
            ]
            c.create_polygon(pts, fill=color, outline=dark, width=2)
            c.create_text(cx, y_center + 18, text=name[:8],
                           fill=color, font=('Arial', 7, 'bold'))
        elif ptype == 'regulator':
            # Hexagon
            pts = [
                x + 6, y_top + 4,
                x + width - 6, y_top + 4,
                x + width, y_center,
                x + width - 6, y_bot - 4,
                x + 6, y_bot - 4,
                x, y_center,
            ]
            c.create_polygon(pts, fill=color, outline=dark, width=2)
            c.create_text(cx, y_center, text=name[:10],
                           fill='#f5f7fa', font=('Arial', 8, 'bold'))
        else:
            # Generic block
            c.create_rectangle(x + 2, y_top, x + width - 2, y_bot,
                                fill=color, outline=dark, width=2)
            c.create_text(cx, y_center, text=name[:10],
                           fill='#f5f7fa', font=('Arial', 9, 'bold'))

        # Small button above each part for removal
        rm_x = x + width - 8
        rm_y = y_top - 12
        c.create_text(rm_x, rm_y, text='',
                       fill='#cf222e', font=('Arial', 10, 'bold'),
                       tags=('lin_rm_' + str(inst_id),))
        c.tag_bind('lin_rm_' + str(inst_id), '<Button-1>',
                    lambda e, i=inst_id: self._plasmid_remove_part(i))

    def _lighten_hex(self, hex_color, factor):
        """Lighten a hex color by factor."""
        h = hex_color.lstrip('#')
        r = min(255, int(int(h[0:2], 16) * factor))
        g = min(255, int(int(h[2:4], 16) * factor))
        b = min(255, int(int(h[4:6], 16) * factor))
        return '#{:02x}{:02x}{:02x}'.format(r, g, b)

    def _plasmid_draw_map_circle(self):
        """Draw circular plasmid map with parts as colored arcs."""
        c = self.plasmid_canvas
        c.delete('all')
        w = c.winfo_width() or 500
        h = c.winfo_height() or 380
        cx = w // 2
        cy = h // 2
        radius = min(w, h) // 2 - 40

        state = self.current_state['plasmid']
        parts = state['parts']
        # Background circle
        c.create_oval(cx - radius - 4, cy - radius - 4,
                       cx + radius + 4, cy + radius + 4,
                       outline='#eef1f5', width=1)
        c.create_oval(cx - radius, cy - radius,
                       cx + radius, cy + radius,
                       outline='#d0d7de', width=2)

        # Plasmid name in center
        c.create_text(cx, cy - 10, text=state.get('name', '?'),
                       fill='#0969da', font=('Arial', 14, 'bold'))
        metrics = calculate_plasmid_metrics(parts, state.get('host', 'E_coli_DH5a'))
        c.create_text(cx, cy + 14, text='{} bp'.format(metrics['total_bp']),
                       fill='#57606a', font=('Arial', 11))
        c.create_text(cx, cy + 32, text='{} parts'.format(metrics['n_parts']),
                       fill='#57606a', font=('Arial', 9))

        if not parts:
            c.create_text(cx, cy + 60, text=self._t('no_parts'),
                           fill='#484f58', font=('Arial', 10, 'italic'))
            return

        # Draw parts as arc segments (each proportional to its length)
        all_parts_data = dict(PLASMID_PARTS)
        all_parts_data.update(self._custom_genes)

        # Calculate total length to apportion arc
        total_len = sum(all_parts_data.get(p['part_key'], {}).get('length', 100) for p in parts)
        if total_len == 0:
            total_len = 1

        # Each arc starts at angle and spans proportional to length
        start_angle = 90  # 12 o'clock
        for p in parts:
            part_data = all_parts_data.get(p['part_key'])
            if not part_data:
                continue
            length_bp = part_data['length']
            arc_span = -360 * (length_bp / total_len)  # negative for clockwise
            color = part_data.get('color', '#1a7f37')

            # Inner arc fill (thick band)
            c.create_arc(cx - radius, cy - radius,
                          cx + radius, cy + radius,
                          start=start_angle, extent=arc_span,
                          fill=color, outline=color,
                          width=14, style='arc')

            # Label at midpoint of arc
            mid_angle = math.radians(start_angle + arc_span / 2)
            label_r = radius + 24
            lx = cx + label_r * math.cos(mid_angle)
            ly = cy - label_r * math.sin(mid_angle)
            # Small tick from arc to label
            tx = cx + (radius + 8) * math.cos(mid_angle)
            ty = cy - (radius + 8) * math.sin(mid_angle)
            ix = cx + (radius - 2) * math.cos(mid_angle)
            iy = cy - (radius - 2) * math.sin(mid_angle)
            c.create_line(ix, iy, tx, ty, fill=color, width=1)
            c.create_text(lx, ly, text=part_data['name'][:14], fill=color,
                           font=('Arial', 9, 'bold'))

            start_angle += arc_span

    def _plasmid_draw_assembly(self):
        """Draw the linear assembly view (horizontal blocks)."""
        c = self._plasmid_asm_canvas
        c.delete('all')
        state = self.current_state['plasmid']
        parts = state['parts']
        all_parts_data = dict(PLASMID_PARTS)
        all_parts_data.update(self._custom_genes)

        if not parts:
            c.create_text(150, 60, text=self._t('no_parts'),
                           fill='#484f58', font=('Arial', 10, 'italic'), anchor='w')
            c.configure(scrollregion=(0, 0, 300, 120))
            return

        block_w = 110
        block_h = 70
        gap = 8
        x = 4
        y_block = 6
        for p in parts:
            part_data = all_parts_data.get(p['part_key'])
            if not part_data:
                continue
            color = part_data.get('color', '#1a7f37')
            # Block background
            c.create_rectangle(x, y_block, x + block_w, y_block + block_h,
                                fill=color, outline=color)
            # Inner shadow
            dark = self._darken_hex(color, 0.7)
            c.create_rectangle(x, y_block + block_h - 6, x + block_w, y_block + block_h,
                                fill=dark, outline='')
            # Part name
            c.create_text(x + block_w // 2, y_block + 16, text=part_data['name'][:14],
                           fill='#f5f7fa', font=('Arial', 9, 'bold'))
            # Length
            c.create_text(x + block_w // 2, y_block + 34, text='{}bp'.format(part_data['length']),
                           fill='#f5f7fa', font=('Arial', 8))
            # Type
            c.create_text(x + block_w // 2, y_block + 50, text=part_data['type'],
                           fill='#f5f7fa', font=('Arial', 8, 'italic'))

            # Controls below
            inst_id = p['instance_id']
            c.create_text(x + 12, y_block + block_h + 12, text='',
                           fill='#1a7f37', font=('Arial', 12, 'bold'),
                           tags=('mvup_' + str(inst_id),))
            c.tag_bind('mvup_' + str(inst_id), '<Button-1>',
                        lambda e, i=inst_id: self._plasmid_move_part(i, -1))
            c.create_text(x + 40, y_block + block_h + 12, text='',
                           fill='#1a7f37', font=('Arial', 12, 'bold'),
                           tags=('mvdown_' + str(inst_id),))
            c.tag_bind('mvdown_' + str(inst_id), '<Button-1>',
                        lambda e, i=inst_id: self._plasmid_move_part(i, 1))
            c.create_text(x + 80, y_block + block_h + 12, text='',
                           fill='#cf222e', font=('Arial', 11, 'bold'),
                           tags=('rm_' + str(inst_id),))
            c.tag_bind('rm_' + str(inst_id), '<Button-1>',
                        lambda e, i=inst_id: self._plasmid_remove_part(i))

            # Connector arrow
            if p != parts[-1]:
                c.create_line(x + block_w, y_block + block_h // 2,
                                x + block_w + gap, y_block + block_h // 2,
                                fill='#57606a', width=2, arrow='last')
            x += block_w + gap

        c.configure(scrollregion=(0, 0, x + 20, 120))

    def _plasmid_update_info(self):
        """Update info panel with metrics."""
        state = self.current_state['plasmid']
        metrics = calculate_plasmid_metrics(state['parts'], state.get('host', 'E_coli_DH5a'))
        host = PLASMID_HOSTS.get(state.get('host', 'E_coli_DH5a'), {})
        host_name = host.get('name_ru' if self.lang == 'ru' else 'name', '?')

        lines = [(state['name'] + '\n', 'ttl'),
                  ('-' * 24 + '\n', 'dim'),
                  (state.get('description', '') + '\n\n', 'nrm'),
                  (self._t('plasmid_host') + ' ' + host_name + '\n\n', 'nrm'),
                  (self._t('total_length') + ' {} bp\n'.format(metrics['total_bp']), 'nrm'),
                  (self._t('copies_per_cell') + ' {}\n'.format(metrics['copies_per_cell']),
                   'ok' if metrics['copies_per_cell'] > 10 else 'wrn'),
                  (self._t('expression_score') + ' {}\n\n'.format(metrics['expression_score']),
                   'ok' if metrics['expression_score'] > 50 else 'wrn')]
        if metrics['errors']:
            lines.append((self._t('plasmid_errors') + '\n', 'bad'))
            for err in metrics['errors']:
                lines.append(('  ! ' + err + '\n', 'bad'))
        else:
            lines.append((self._t('plasmid_ok') + '\n', 'ok'))
        self._set_text(self.plasmid_info, lines)

    def _plasmid_simulate(self):
        """Run expression simulation and show detailed results."""
        state = self.current_state['plasmid']
        metrics = calculate_plasmid_metrics(state['parts'], state.get('host', 'E_coli_DH5a'))
        host = PLASMID_HOSTS.get(state.get('host', 'E_coli_DH5a'), {})

        # Predicted protein (arbitrary units)
        predicted = metrics['expression_score'] * metrics['copies_per_cell'] / 100.0
        # Replication time (minutes) — inverse of growth rate
        rep_time = 60.0 / max(0.1, host.get('growth_rate', 1.0))

        host_name = host.get('name_ru' if self.lang == 'ru' else 'name', '?')

        lines = [
            (self._t('expression_result') + '\n', 'ttl'),
            ('-' * 24 + '\n', 'dim'),
            (self._t('plasmid_host') + ' ' + host_name + '\n\n', 'nrm'),
            (self._t('total_length') + ' {} bp\n'.format(metrics['total_bp']), 'nrm'),
            (self._t('copies_per_cell') + ' {}\n'.format(metrics['copies_per_cell']), 'nrm'),
            (self._t('expression_score') + ' {}\n'.format(metrics['expression_score']), 'nrm'),
            ('\n', 'nrm'),
            (self._t('predicted_protein') + ' {:.1f} a.u.\n'.format(predicted),
             'ok' if predicted > 50 else 'wrn'),
            (self._t('replication_time') + ' {:.0f} min\n'.format(rep_time), 'nrm'),
            (self._t('host_growth') + ' {:.1f}x\n'.format(host.get('growth_rate', 1.0)), 'nrm'),
        ]
        if metrics['errors']:
            lines.append(('\n' + self._t('plasmid_errors') + '\n', 'bad'))
            for err in metrics['errors']:
                lines.append(('  ! ' + err + '\n', 'bad'))
        else:
            lines.append(('\n' + self._t('plasmid_ok') + '\n', 'ok'))
        self._set_text(self.plasmid_info, lines)

    def _plasmid_open_custom_gene_dialog(self):
        """Dialog to add a custom gene by name or sequence."""
        dlg = tk.Toplevel(self)
        dlg.title(self._t('custom_gene_dlg'))
        dlg.geometry('500x420')
        dlg.configure(bg=biosim_theme('bg'))
        dlg.transient(self)
        dlg.grab_set()

        tk.Label(dlg, text=self._t('custom_gene_dlg'),
                  font=('Arial', 13, 'bold'), bg=biosim_theme('bg'), fg='#8250df'
                  ).pack(pady=8)

        # Name
        tk.Label(dlg, text=self._t('gene_name_field'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(anchor='w', padx=16)
        name_var = tk.StringVar()
        tk.Entry(dlg, textvariable=name_var, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                  insertbackground='#1c2128', relief='flat', font=('Arial', 11),
                  highlightthickness=1, highlightbackground=biosim_theme('border')
                  ).pack(fill='x', padx=16, pady=(2, 8), ipady=4)

        # Sequence
        tk.Label(dlg, text=self._t('gene_seq_field'), bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 10)).pack(anchor='w', padx=16)
        seq_text = tk.Text(dlg, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                            insertbackground='#1c2128', relief='flat',
                            font=('Courier', 9), height=8,
                            highlightthickness=1, highlightbackground=biosim_theme('border'))
        seq_text.pack(fill='x', padx=16, pady=(2, 4))

        # Status
        status_lbl = tk.Label(dlg, text='', bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                                font=('Arial', 9, 'italic'))
        status_lbl.pack(anchor='w', padx=16)

        def fetch_ncbi():
            gene_name = name_var.get().strip() or seq_text.get('1.0', 'end').strip().split()[0]
            if not gene_name:
                status_lbl.config(text='Enter a gene name first', fg='#cf222e')
                return
            status_lbl.config(text='Loading from NCBI...', fg='#9a6700')
            dlg.update()
            seq, info = fetch_gene_sequence_ncbi(gene_name)
            if seq:
                seq_text.delete('1.0', 'end')
                seq_text.insert('1.0', seq[:5000])
                if not name_var.get():
                    name_var.set(gene_name)
                status_lbl.config(text='Loaded {} bp'.format(len(seq)), fg='#1a7f37')
            else:
                status_lbl.config(text='Could not fetch ' + gene_name, fg='#cf222e')

        def create():
            name = name_var.get().strip()
            raw_seq = seq_text.get('1.0', 'end').strip()
            if not name or not raw_seq:
                status_lbl.config(text='Need name and sequence', fg='#cf222e')
                return
            # Clean sequence (remove whitespace, FASTA headers)
            cleaned = ''
            for line in raw_seq.split('\n'):
                if line.startswith('>'):
                    continue
                cleaned += ''.join(c for c in line if c.isalpha())
            if not cleaned:
                status_lbl.config(text='No valid sequence', fg='#cf222e')
                return
            # Detect protein
            if is_protein_sequence(cleaned):
                dna = back_translate_protein(cleaned)
                length = len(dna)
            else:
                length = len(cleaned)
            # Create a unique part key
            part_key = 'custom_' + ''.join(c if c.isalnum() else '_' for c in name)
            count = 0
            base_key = part_key
            while part_key in self._custom_genes or part_key in PLASMID_PARTS:
                count += 1
                part_key = base_key + '_' + str(count)
            self._custom_genes[part_key] = {
                'type': 'gene', 'name': name[:20], 'length': length,
                'strength': 100, 'color': '#8250df',
                'desc_ru': 'Свой ген ({} нт)'.format(length),
                'desc_en': 'Custom gene ({} bp)'.format(length),
                'sequence': cleaned[:5000],  # store first 5kb
            }
            self._plasmid_render_parts_library()
            status_lbl.config(text=self._t('gene_added').format(name), fg='#1a7f37')
            self.after(800, dlg.destroy)

        # Buttons
        btn_frame = tk.Frame(dlg, bg=biosim_theme('bg'))
        btn_frame.pack(fill='x', padx=16, pady=10)
        tk.Button(btn_frame, text=self._t('fetch_from_ncbi_btn'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'), relief='solid', bd=1,
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   pady=4, command=fetch_ncbi
                   ).pack(side='left', padx=(0, 4))
        tk.Button(btn_frame, text=self._t('create_gene'),
                   bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                   font=('Arial', 10, 'bold'), cursor='hand2',
                   pady=4, command=create
                   ).pack(side='left', padx=4)
        tk.Button(btn_frame, text='Cancel', bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                   relief='solid', bd=1, font=('Arial', 10), cursor='hand2',
                   pady=4, command=dlg.destroy
                   ).pack(side='right')

    def _darken_hex(self, hex_color, factor):
        """Darken a hex color by factor (0.0-1.0)."""
        h = hex_color.lstrip('#')
        r = int(int(h[0:2], 16) * factor)
        g = int(int(h[2:4], 16) * factor)
        b = int(int(h[4:6], 16) * factor)
        return '#{:02x}{:02x}{:02x}'.format(r, g, b)

    # ── METABOLIC ENGINEERING TAB ──
    def _build_metabolic_tab(self):
        """COPASI-style metabolic workspace.

        Three panels:
          LEFT   — model/task tree (Compartments, Species, Reactions,
                   Global Quantities, Events | Time Course, Steady State,
                   Stoichiometry/EFM, MCA, Sensitivities, Optimization, FBA)
          CENTER — editor/settings for the selected node
          RIGHT  — results (plot + text)
        The old organism/product selection is preserved as loadable presets.
        """
        is_ru = (self.lang == 'ru')
        f = tk.Frame(self.content, bg=biosim_theme('bg'))

        # ── State: a full COPASI-style model, plus legacy keys for links ──
        model = new_metabolic_model('New model' if not is_ru else 'Новая модель')
        self.current_state['metabolic'] = model
        self._metab_selected = ('model', 'Reactions')  # (group, item)

        # ── LEFT: transfer hub + tree ──
        left = tk.Frame(f, bg=biosim_theme('bg'), width=250)
        left.pack(side='left', fill='y', padx=(0, 4)); left.pack_propagate(False)

        mlb = self._make_transfer_hub(left, 'metabolic')
        if mlb:
            mlb.pack(fill='x', pady=(0, 4))

        # Preset loader (keeps old organism→product + pathway models)
        preset_btn = tk.Button(
            left, text=('📂 Загрузить модель ▾' if is_ru else '📂 Load model ▾'),
            bg='#9a6700', highlightbackground='#9a6700', fg='white',
            relief='flat', font=('Arial', 9, 'bold'), cursor='hand2', pady=4,
            command=self._metab_open_preset_menu)
