            ('Species', '⬡', 'Метаболиты', 'Species', 'species'),
            ('Reactions', '⇌', 'Реакции', 'Reactions', 'reactions'),
            ('Global', '𝑘', 'Глобальные величины', 'Global Quantities', 'global_quantities'),
            ('Events', '⚡', 'События', 'Events', 'events'),
