            ('EFM', '⊞', 'Стехиометрия / EFM', 'Stoichiometry / EFM'),
            ('MCA', '🎛', 'Контрольный анализ (MCA)', 'Metabolic Control Analysis'),
            ('Sensitivity', '📈', 'Чувствительность', 'Sensitivities'),
            ('ParamScan', '🔎', 'Скан параметра', 'Parameter Scan'),
            ('Moieties', '♻', 'Законы сохранения', 'Moieties'),
            ('Bifurcation', '🌿', 'Бифуркации', 'Bifurcation'),
            ('MonteCarlo', '🎲', 'Монте-Карло', 'Monte Carlo'),
            ('TCSens', '📉', 'Чувствит. траектории', 'Time-Course Sensitivities'),
