    def _metab_add_global(self):
        self._save_history('metabolic')
        model = self._metab_model()
        i = len(model['global_quantities']) + 1
        gid = 'k{}'.format(i)
        while gid in model['global_quantities']:
            i += 1; gid = 'k{}'.format(i)
        model['global_quantities'][gid] = {'name': gid, 'value': 1.0,
                                           'type': 'fixed', 'expression': ''}
        self._metab_select('model', 'Global')

    def _metab_del_global(self, gid):
        self._save_history('metabolic')
        self._metab_model()['global_quantities'].pop(gid, None)
        self._metab_select('model', 'Global')

    def _metab_panel_events(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        bar = tk.Frame(parent, bg=biosim_theme('bg')); bar.pack(fill='x', pady=(0, 4))
        tk.Button(bar, text=('+ Событие' if is_ru else '+ Event'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                  relief='flat', font=('Arial', 9, 'bold'), cursor='hand2',
                  command=self._metab_add_event).pack(side='left', padx=2)
        tk.Label(bar, text=('Когда условие → присвоить значение (напр. A>5 → B=0)'
                            if is_ru else 'When condition → assign (e.g. A>5 → B=0)'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 8)).pack(side='left', padx=6)
        inner = self._metab_scroll_area(parent)
        if not model['events']:
            tk.Label(inner, text=('Нет событий.' if is_ru else 'No events.'),
                     bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                     font=('Arial', 10, 'italic')).pack(pady=20)
        for i, ev in enumerate(model['events']):
            row = tk.Frame(inner, bg=biosim_theme('panel'), relief='solid', bd=1)
            row.pack(fill='x', pady=2, padx=2)
            trig_v = tk.StringVar(value=ev.get('trigger', ''))
            asn = ev.get('assignments', [])
            asn_str = '; '.join('{}={}'.format(t, e) for t, e in asn)
            asn_v = tk.StringVar(value=asn_str)
            tk.Label(row, text=('Когда:' if is_ru else 'When:'), bg=biosim_theme('panel'),
                     fg=biosim_theme('text'), font=('Arial', 8)).pack(side='left', padx=4)
            tk.Entry(row, textvariable=trig_v, width=16, font=('Arial', 9),
                     relief='solid', bd=1).pack(side='left', padx=2)
            tk.Label(row, text='→', bg=biosim_theme('panel'), fg='#8250df',
                     font=('Arial', 10, 'bold')).pack(side='left')
            tk.Entry(row, textvariable=asn_v, width=18, font=('Arial', 9),
                     relief='solid', bd=1).pack(side='left', padx=2)
            def save_e(i=i, trig_v=trig_v, asn_v=asn_v):
                assigns = []
                for part in asn_v.get().split(';'):
                    if '=' in part:
                        t, e = part.split('=', 1)
                        assigns.append((t.strip(), e.strip()))
                model['events'][i] = {'trigger': trig_v.get().strip(), 'assignments': assigns}
            tk.Button(row, text='💾', bg=biosim_theme('panel'), relief='flat',
                      cursor='hand2', command=save_e).pack(side='left', padx=2)
            tk.Button(row, text='✕', fg='#cf222e', bg=biosim_theme('panel'),
                      relief='flat', font=('Arial', 9, 'bold'), cursor='hand2',
                      command=lambda i=i: self._metab_del_event(i)).pack(side='left', padx=2)

    def _metab_add_event(self):
        self._save_history('metabolic')
        self._metab_model()['events'].append({'trigger': '', 'assignments': []})
        self._metab_select('model', 'Events')

    def _metab_del_event(self, i):
        self._save_history('metabolic')
        evs = self._metab_model()['events']
        if 0 <= i < len(evs):
            evs.pop(i)
        self._metab_select('model', 'Events')

    # ══════════════════════════════════════════════════════════════
    # TASK PANELS (wrap existing + new engines)
