    def _metab_show_result_text(self, lines):
        w = getattr(self, 'metab_info', None)
        if w is None:
            return
        self._set_text(w, lines)

    def _metab_plot_timecourse(self, res):
        """Draw a small multi-species line plot on the results canvas."""
        c = getattr(self, '_metab_result_canvas', None)
        if c is None or res.get('error'):
            return
        c.delete('all'); c.update_idletasks()
        W = c.winfo_width() or 290; H = c.winfo_height() or 180
        pad_l, pad_b, pad_t, pad_r = 30, 20, 14, 8
        t = res['time']; conc = res['concentrations']; sp = res['species']
        if not t:
            return
        tmax = max(t) or 1.0
        vmax = max((max(conc[s]) for s in sp), default=1.0) or 1.0
        plot_w = W - pad_l - pad_r
        plot_h = H - pad_b - pad_t
        colors = ['#0969da', '#1a7f37', '#cf222e', '#8250df', '#9a6700',
                  '#0550ae', '#d1242f', '#116329', '#953800', '#6639ba']
        # gridlines (4 horizontal, 4 vertical) with value ticks
        for gi in range(5):
            gy = pad_t + plot_h * gi / 4
            c.create_line(pad_l, gy, W - pad_r, gy, fill='#eaeef2')
            val = vmax * (1 - gi / 4)
            c.create_text(pad_l - 3, gy, text='{:.1f}'.format(val), anchor='e',
                          fill='#8b949e', font=('Arial', 6))
        for gi in range(5):
            gx = pad_l + plot_w * gi / 4
            c.create_line(gx, pad_t, gx, H - pad_b, fill='#f2f4f7')
            c.create_text(gx, H - pad_b + 3, text='{:.0f}'.format(tmax * gi / 4),
                          anchor='n', fill='#8b949e', font=('Arial', 6))
        # axes
        c.create_line(pad_l, H - pad_b, W - pad_r, H - pad_b, fill='#adbac7', width=1)
        c.create_line(pad_l, pad_t, pad_l, H - pad_b, fill='#adbac7', width=1)
        # curves
        for i, s in enumerate(sp):
            col = colors[i % len(colors)]
            pts = []
            for k in range(len(t)):
                x = pad_l + (t[k] / tmax) * plot_w
                y = (H - pad_b) - (conc[s][k] / vmax) * plot_h
                pts.extend([x, y])
            if len(pts) >= 4:
                c.create_line(*pts, fill=col, width=2, smooth=True)
        # compact legend top-right
        lx = pad_l + 4; ly = pad_t + 1
        for i, s in enumerate(sp[:8]):
            col = colors[i % len(colors)]
            c.create_line(lx, ly + 4, lx + 10, ly + 4, fill=col, width=2)
            c.create_text(lx + 13, ly + 4, text=s[:6], anchor='w',
                          fill='#57606a', font=('Arial', 7))
            lx += 52
            if lx > W - 46:
                lx = pad_l + 4; ly += 11

    def _metab_panel_timecourse(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        info = tk.Label(parent, text=(
            'Симуляция во времени с выбором метода:\n'
            '• Детерминированный (ODE/RK4) — точный, учитывает объёмы, события, формулы.\n'
            '• Стохастический (Гиллеспи) — случайные события, для малых чисел молекул.\n'
            '• Гибридный (tau-leap) — приближённая стохастика, быстрее.'
            if is_ru else
            'Time-course simulation with a method choice:\n'
            '• Deterministic (ODE/RK4) — exact, honours volumes, events, formulas.\n'
            '• Stochastic (Gillespie) — random events, for low molecule counts.\n'
            '• Hybrid (tau-leap) — approximate stochastic, faster.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w')
        info.pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(parent, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        tk.Label(ctl, text=('Время:' if is_ru else 'Duration:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        tmax_v = tk.StringVar(value='20')
        tk.Entry(ctl, textvariable=tmax_v, width=6, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2, pady=6)
        tk.Label(ctl, text=('Метод:' if is_ru else 'Method:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(10, 2))
        methods = [('det', 'Детерминированный (ODE/RK4)' if is_ru else 'Deterministic (ODE/RK4)'),
                   ('stoch', 'Стохастический (Гиллеспи)' if is_ru else 'Stochastic (Gillespie)'),
                   ('hybrid', 'Гибридный (tau-leap)' if is_ru else 'Hybrid (tau-leap)')]
        method_labels = [m[1] for m in methods]
        method_v = tk.StringVar(value=method_labels[0])
        ttk.Combobox(ctl, textvariable=method_v, state='readonly', width=26,
                     values=method_labels, font=('Arial', 8)).pack(side='left', padx=2)

        def run():
            try:
                tmax = float(tmax_v.get() or 20)
            except ValueError:
                tmax = 20.0
            mkey = 'det'
            for k, lbl in methods:
                if lbl == method_v.get():
                    mkey = k
                    break
            if mkey == 'det':
                res = simulate_metabolic_model(model, t_max=tmax, n_points=200)
                if res.get('error'):
                    self._metab_show_result_text([(res['error'] + '\n', 'bad')])
                    return
                self._metab_plot_timecourse(res)
                lines = [(('Финальные концентрации (ODE)\n' if is_ru
                           else 'Final concentrations (ODE)\n'), 'ttl')]
                for s, v in res['final'].items():
                    lines.append(('  {:<14} {:.4f}\n'.format(s, v), 'nrm'))
                self._metab_show_result_text(lines)
                self._metab_last_timecourse = res
            else:
                # Stochastic / hybrid go through the circuit adapter + engine
                nodes, edges, init = self._metab_model_to_circuit(model)
                if not nodes:
                    self._metab_show_result_text([(('Модель пуста\n' if is_ru else 'Empty model\n'), 'bad')])
                    return
                try:
                    if mkey == 'stoch':
                        out = run_gillespie_simulation(nodes, edges, init, t_end=tmax)
                    else:
                        out = run_tau_leap_simulation(nodes, edges, init, t_end=tmax)
                except Exception as exc:
                    self._metab_show_result_text([('{}\n'.format(exc), 'bad')])
                    return
                res = self._metab_normalize_stochastic(out)
                if res.get('error'):
                    self._metab_show_result_text([(res['error'] + '\n', 'bad')])
                    return
                self._metab_plot_timecourse(res)
                label = 'Гиллеспи' if (mkey == 'stoch' and is_ru) else \
                        'Gillespie' if mkey == 'stoch' else \
                        ('tau-leap')
                lines = [('Финальные значения ({})\n'.format(label) if is_ru
                          else 'Final values ({})\n'.format(label), 'ttl')]
                for s, v in res['final'].items():
                    lines.append(('  {:<14} {:.3f}\n'.format(s, v), 'nrm'))
                self._metab_show_result_text(lines)
                self._metab_last_timecourse = res

        tk.Button(parent, text=('▶ Запустить симуляцию' if is_ru else '▶ Run simulation'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)
        tk.Button(parent, text=('📊 Открыть полный график' if is_ru else '📊 Open full plot'),
                  bg=biosim_theme('panel'), highlightbackground='#0969da', fg='#0969da',
                  relief='solid', bd=1, font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                  command=self._metab_open_full_plot).pack(fill='x')

    def _metab_normalize_stochastic(self, out):
        """Normalize a Gillespie/tau-leap result into the timecourse shape
        {time, species, concentrations, final} used by the plotter.

        The engines return a tuple (t_array, Y_array, node_ids).
        """
        try:
            import numpy as _np
            if isinstance(out, tuple) and len(out) == 3:
                t_arr, Y_arr, ids = out
                if t_arr is None or Y_arr is None or ids is None or len(t_arr) == 0:
                    return {'error': 'stochastic engine returned no trajectory'}
                Y_arr = _np.asarray(Y_arr)
                conc = {ids[i]: Y_arr[:, i].tolist() for i in range(len(ids))}
                return {
                    'error': None,
                    'time': list(_np.asarray(t_arr).tolist()),
                    'species': list(ids),
                    'concentrations': conc,
                    'final': {ids[i]: round(float(Y_arr[-1, i]), 3) for i in range(len(ids))},
                }
        except Exception as exc:
            return {'error': 'stochastic parse: {}'.format(exc)}
        return {'error': 'unexpected stochastic result'}

    def _metab_open_full_plot(self):
        res = getattr(self, '_metab_last_timecourse', None)
        is_ru = (self.lang == 'ru')
        if not res:
            Toast.show(self, 'Сначала запустите симуляцию' if is_ru else 'Run a simulation first')
            return
        try:
            import matplotlib.pyplot as plt
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        except Exception:
            Toast.show(self, 'matplotlib недоступен' if is_ru else 'matplotlib unavailable')
            return
        win = tk.Toplevel(self); win.title('Time course'); win.geometry('760x520')
        win.configure(bg=biosim_theme('bg'))
        fig, ax = new_biosim_figure(figsize=(7, 4.4))
        for s in res['species']:
            ax.plot(res['time'], res['concentrations'][s], label=s, linewidth=1.8)
        ax.set_xlabel('time'); ax.set_ylabel('concentration')
        ax.legend(fontsize=7, ncol=2)
        style_biosim_axes(ax)
        canvas = FigureCanvasTkAgg(fig, master=win)
        canvas.draw(); canvas.get_tk_widget().pack(fill='both', expand=True, padx=6, pady=6)

    def _metab_panel_steadystate(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Долгое интегрирование до dX/dt ≈ 0. Показывает стационарные\n'
            'концентрации и остаточную невязку (сошлось ли).'
            if is_ru else
            'Long integration until dX/dt ≈ 0. Reports steady-state\n'
            'concentrations and the residual (whether it converged).'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            res = model_steady_state(model, t_max=500)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')])
                return
            conv = res['converged']
            lines = [(('Стационарное состояние\n' if is_ru else 'Steady state\n'), 'ttl'),
                     (('Сошлось: ' if is_ru else 'Converged: ') +
                      ('да' if conv and is_ru else 'yes' if conv else ('нет' if is_ru else 'no')) +
                      '  (невязка {:.2e})\n\n'.format(res['residual']),
                      'ok' if conv else 'wrn')]
            for s, v in res['steady_state'].items():
                lines.append(('  {:<14} {:.4f}\n'.format(s, v), 'nrm'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Найти стационар' if is_ru else '▶ Find steady state'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_efm(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Стехиометрическая матрица N и элементарные моды потоков (EFM):\n'
            'минимальные наборы реакций, работающие в стационаре (N·v=0).\n'
            'Это то, чего не было в старой вкладке.'
            if is_ru else
            'Stoichiometry matrix N and Elementary Flux Modes (EFM):\n'
            'minimal reaction sets that run at steady state (N·v=0).\n'
            'This is genuinely new versus the old tab.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run_stoich():
            st = model_stoichiometry_matrix(model)
            lines = [(('Стехиометрическая матрица\n' if is_ru else 'Stoichiometry matrix\n'), 'ttl'),
                     ('  {} × {}\n\n'.format(len(st['species']), len(st['reactions'])), 'dim')]
            # header
            hdr = '        ' + ' '.join('{:>5}'.format(r[:5]) for r in st['reactions'])
            lines.append((hdr + '\n', 'dim'))
            for i, sp in enumerate(st['species']):
                rowvals = ' '.join('{:>5.1f}'.format(st['matrix'][i][j])
                                   for j in range(len(st['reactions'])))
                lines.append(('  {:<6} {}\n'.format(sp[:6], rowvals), 'nrm'))
            self._metab_show_result_text(lines)

        def run_efm():
            efm = elementary_flux_modes(model)
            if efm.get('error'):
                self._metab_show_result_text([(efm['error'] + '\n', 'bad')])
                return
            modes = efm.get('modes', [])
            lines = [(('Элементарные моды потоков\n' if is_ru else 'Elementary flux modes\n'), 'ttl'),
                     ('  ' + ('найдено мод: ' if is_ru else 'modes found: ') +
                      '{}   (null dim {})\n\n'.format(len(modes), efm.get('null_dim', 0)), 'dim')]
            if not modes:
                lines.append((('Нет нетривиальных мод (линейная цепочка без циклов).\n'
                               if is_ru else
                               'No non-trivial modes (linear chain, no cycles).\n'), 'wrn'))
            for i, m in enumerate(modes):
                lines.append(('  ' + ('Мода' if is_ru else 'Mode') + ' {}: '.format(i + 1), 'ok'))
                lines.append((' → '.join(m['reactions']) + '\n', 'nrm'))
            self._metab_show_result_text(lines)

        tk.Button(parent, text=('▶ Стехиометрия N' if is_ru else '▶ Stoichiometry N'),
                  bg=biosim_theme('panel'), highlightbackground='#0969da', fg='#0969da',
                  relief='solid', bd=1, font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                  command=run_stoich).pack(fill='x', pady=4)
        tk.Button(parent, text=('▶ Элементарные моды (EFM)' if is_ru else '▶ Elementary flux modes'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run_efm).pack(fill='x', pady=4)

