    def _metab_run_mca(self):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        nodes, edges, init = self._metab_model_to_circuit(model)
        if not nodes:
            self._metab_show_result_text([(('Модель пуста\n' if is_ru else 'Model is empty\n'), 'bad')])
            return
        try:
            results, ids = metabolic_control_analysis(nodes, edges, init)
        except Exception as exc:
            self._metab_show_result_text([('MCA: {}\n'.format(exc), 'bad')])
            return
        if not results:
            self._metab_show_result_text([(('MCA не сошёлся (нет стационара).\n'
                                            if is_ru else
                                            'MCA did not converge (no steady state).\n'), 'wrn')])
            return
        # Sort by absolute control coefficient, strongest first
        results_sorted = sorted(results, key=lambda r: abs(r['control_coef']), reverse=True)
        lines = [(('Контрольные коэффициенты потока\n' if is_ru else 'Flux control coefficients\n'), 'ttl'),
                 (('  реакция → метаболит : коэффициент\n\n' if is_ru
                   else '  reaction → metabolite : coefficient\n\n'), 'dim')]
        for r in results_sorted[:24]:
            tag = 'ok' if abs(r['control_coef']) > 0.3 else 'nrm'
            lines.append(('  {:<8}→{:<8} {:+.3f}\n'.format(
                str(r['param_node'])[:8], str(r['target'])[:8], r['control_coef']), tag))
        self._metab_show_result_text(lines)

    def _metab_panel_sensitivity(self, parent):
        is_ru = (self.lang == 'ru')
        tk.Label(parent, text=(
            'Анализ чувствительности: как сильно параметры влияют на\n'
            'стационарные концентрации.'
            if is_ru else
            'Sensitivity analysis: how strongly parameters affect\n'
            'steady-state concentrations.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            model = self._metab_model()
            nodes, edges, init = self._metab_model_to_circuit(model)
            if not nodes:
                self._metab_show_result_text([(('Модель пуста\n' if is_ru else 'Empty model\n'), 'bad')])
                return
            try:
                sens, ids = sensitivity_analysis(nodes, edges, init)
            except Exception as exc:
                self._metab_show_result_text([('{}\n'.format(exc), 'bad')])
                return
            if not sens:
                self._metab_show_result_text([(('Нет данных (нет стационара).\n'
                                                if is_ru else
                                                'No data (no steady state).\n'), 'wrn')])
                return
            # sens = list of (node, param, target, value); rank by |value|
            sens_sorted = sorted(sens, key=lambda t: abs(t[3]), reverse=True)
            lines = [(('Чувствительность (top-24)\n' if is_ru else 'Sensitivities (top-24)\n'), 'ttl'),
                     (('  параметр → метаболит : значение\n\n' if is_ru
                       else '  parameter → metabolite : value\n\n'), 'dim')]
            for node, param, target, val in sens_sorted[:24]:
                tag = 'ok' if abs(val) > 0.5 else 'nrm'
                lines.append(('  {:<6}.{:<10}→{:<7} {:+.3f}\n'.format(
                    str(node)[:6], str(param)[:10], str(target)[:7], val), tag))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Анализ чувствительности' if is_ru else '▶ Run sensitivities'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_paramscan(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Скан параметра: как меняется стационарное состояние при\n'
            'изменении параметра реакции в заданном диапазоне.'
            if is_ru else
            'Parameter scan: how the steady state changes as a reaction\n'
            'parameter varies over a range.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(parent, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        # pick which reaction's V to scan
        rxn_ids = [r.get('id', 'R{}'.format(i + 1)) for i, r in enumerate(model['reactions'])]
        tk.Label(ctl, text=('Реакция:' if is_ru else 'Reaction:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        rxn_v = tk.StringVar(value=rxn_ids[0] if rxn_ids else '')
        ttk.Combobox(ctl, textvariable=rxn_v, values=rxn_ids, state='readonly',
                     width=8, font=('Arial', 8)).pack(side='left', padx=2)
        tk.Label(ctl, text='V:', bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(8, 2))
        pmin_v = tk.StringVar(value='0.1'); pmax_v = tk.StringVar(value='5.0')
        tk.Entry(ctl, textvariable=pmin_v, width=5, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=1)
        tk.Label(ctl, text='—', bg=biosim_theme('panel'), fg='#57606a').pack(side='left')
        tk.Entry(ctl, textvariable=pmax_v, width=5, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=1)

        def run():
            nodes, edges, init = self._metab_model_to_circuit(model)
            if not nodes or not rxn_v.get():
                self._metab_show_result_text([(('Модель пуста\n' if is_ru else 'Empty model\n'), 'bad')])
                return
            # map reaction → its product node, scan the edge's kcat via node production proxy
            try:
                pmin = float(pmin_v.get() or 0.1); pmax = float(pmax_v.get() or 5.0)
            except ValueError:
                pmin, pmax = 0.1, 5.0
            # scan the substrate node's production as a proxy for reaction rate V
            idx = rxn_ids.index(rxn_v.get()) if rxn_v.get() in rxn_ids else 0
            rxn = model['reactions'][idx]
            subs = list(rxn.get('substrates', {}).keys())
            scan_node = subs[0] if subs else (nodes[0]['id'])
            try:
                results, pvals = parameter_scan_1d(nodes, edges, init, scan_node,
                                                   'production', pmin, pmax, n_steps=20)
            except Exception as exc:
                self._metab_show_result_text([('{}\n'.format(exc), 'bad')]); return
            self._metab_plot_scan(results, pvals)
            lines = [(('Скан параметра V реакции {}\n'.format(rxn_v.get()) if is_ru
                       else 'Scan of reaction {} V\n'.format(rxn_v.get())), 'ttl'),
                     ('  {} → {}  ({} точек)\n\n'.format(pmin, pmax, len(pvals))
                      if is_ru else '  {} → {}  ({} points)\n\n'.format(pmin, pmax, len(pvals)), 'dim')]
            for pv, ss in results[::max(1, len(results) // 10)]:
                if ss:
                    key = list(ss.keys())[-1]
                    lines.append(('  V={:<5.2f} → {}={:.3f}\n'.format(pv, key[:8], ss[key]), 'nrm'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Запустить скан' if is_ru else '▶ Run scan'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_plot_scan(self, results, pvals):
        """Plot steady-state vs scanned parameter on the results canvas."""
        c = getattr(self, '_metab_result_canvas', None)
        if c is None or not results:
            return
        c.delete('all'); c.update_idletasks()
        W = c.winfo_width() or 290; H = c.winfo_height() or 180
        pad_l, pad_b, pad_t, pad_r = 30, 20, 14, 8
        plot_w = W - pad_l - pad_r; plot_h = H - pad_b - pad_t
        # collect species that have data
        valid = [(pv, ss) for pv, ss in results if ss]
        if not valid:
            return
        species = list(valid[0][1].keys())
        pmin, pmax = min(pvals), max(pvals)
        prange = (pmax - pmin) or 1.0
        vmax = max((max(ss.values()) for _, ss in valid), default=1.0) or 1.0
        colors = ['#0969da', '#1a7f37', '#cf222e', '#8250df', '#9a6700', '#0550ae']
        c.create_line(pad_l, H - pad_b, W - pad_r, H - pad_b, fill='#adbac7')
        c.create_line(pad_l, pad_t, pad_l, H - pad_b, fill='#adbac7')
        for si, s in enumerate(species[:6]):
            col = colors[si % len(colors)]
            pts = []
            for pv, ss in valid:
                x = pad_l + (pv - pmin) / prange * plot_w
                y = (H - pad_b) - (ss.get(s, 0) / vmax) * plot_h
                pts.extend([x, y])
            if len(pts) >= 4:
                c.create_line(*pts, fill=col, width=2, smooth=True)
        c.create_text(W // 2, H - 4, text='parameter', fill='#8b949e', font=('Arial', 7))

