    def _metab_panel_bifurcation(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Бифуркации: как качественно меняется поведение системы при\n'
            'изменении параметра (появление/исчезновение стационаров,\n'
            'рождение колебаний). Ищет все устойчивые состояния.'
            if is_ru else
            'Bifurcation: how system behaviour changes qualitatively as a\n'
            'parameter varies (steady states appearing/vanishing, oscillations).\n'
            'Finds all stable states.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(parent, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        sp_ids = list(model['species'].keys())
        tk.Label(ctl, text=('Параметр (вид):' if is_ru else 'Parameter (species):'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        node_v = tk.StringVar(value=sp_ids[0] if sp_ids else '')
        ttk.Combobox(ctl, textvariable=node_v, values=sp_ids, state='readonly',
                     width=10, font=('Arial', 8)).pack(side='left', padx=2)
        pmin_v = tk.StringVar(value='0.1'); pmax_v = tk.StringVar(value='3.0')
        tk.Entry(ctl, textvariable=pmin_v, width=5, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2)
        tk.Label(ctl, text='—', bg=biosim_theme('panel'), fg='#57606a').pack(side='left')
        tk.Entry(ctl, textvariable=pmax_v, width=5, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=1)

        def run():
            nodes, edges, init = self._metab_model_to_circuit(model)
            if not nodes:
                self._metab_show_result_text([(('Модель пуста\n' if is_ru else 'Empty model\n'), 'bad')])
                return
            try:
                pmin = float(pmin_v.get() or 0.1); pmax = float(pmax_v.get() or 3.0)
            except ValueError:
                pmin, pmax = 0.1, 3.0
            state = {'nodes': nodes, 'edges': edges, 'init': init}
            try:
                res = bifurcation_analysis(state, node_v.get(), 'production',
                                           pmin, pmax, n_steps=30)
            except Exception as exc:
                self._metab_show_result_text([('{}\n'.format(exc), 'bad')]); return
            # engine returns (results_dict, p_values)
            results, pvals = res if isinstance(res, tuple) else (res, [])
            lines = [(('Бифуркационная диаграмма\n' if is_ru else 'Bifurcation diagram\n'), 'ttl'),
                     ('  ' + ('параметр: ' if is_ru else 'parameter: ') + node_v.get() +
                      '\n  {} → {}  ({} точек)\n\n'.format(pmin, pmax, len(pvals)), 'dim')]
            if isinstance(results, dict):
                # count multistability: nodes that show >1 distinct steady state
                multi = 0
                for tn, series in results.items():
                    distinct = set()
                    for pt in series:
                        if isinstance(pt, (list, tuple, set)):
                            distinct.update(round(float(x), 2) for x in pt)
                        else:
                            try:
                                distinct.add(round(float(pt), 2))
                            except (TypeError, ValueError):
                                pass
                    if len(distinct) > len(pvals) * 0.6:
                        multi += 1
                    lines.append(('  {:<12} диапазон значений: {}\n'.format(tn[:12], len(distinct))
                                  if is_ru else
                                  '  {:<12} value spread: {}\n'.format(tn[:12], len(distinct)), 'nrm'))
                if multi:
                    lines.append((('\n⚠ Возможна мультистабильность/бифуркация!\n'
                                   if is_ru else '\n⚠ Possible multistability/bifurcation!\n'), 'wrn'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Построить бифуркации' if is_ru else '▶ Run bifurcation'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_montecarlo(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Монте-Карло: случайно варьирует параметры и показывает разброс\n'
            'стационарных концентраций (среднее ± СКО). Оценивает,\n'
            'насколько система устойчива к неопределённости параметров.'
            if is_ru else
            'Monte Carlo: randomly varies parameters and shows the spread of\n'
            'steady-state concentrations (mean ± SD). Assesses robustness to\n'
            'parameter uncertainty.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(parent, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        tk.Label(ctl, text=('Выборок:' if is_ru else 'Samples:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        n_v = tk.StringVar(value='100')
        tk.Entry(ctl, textvariable=n_v, width=6, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2)
        tk.Label(ctl, text=('Разброс:' if is_ru else 'Variation:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(8, 2))
        var_v = tk.StringVar(value='0.5')
        tk.Entry(ctl, textvariable=var_v, width=5, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2)

        def run():
            import numpy as _np
            nodes, edges, init = self._metab_model_to_circuit(model)
            if not nodes:
                self._metab_show_result_text([(('Модель пуста\n' if is_ru else 'Empty model\n'), 'bad')])
                return
            try:
                n = int(float(n_v.get() or 100)); var = float(var_v.get() or 0.5)
            except ValueError:
                n, var = 100, 0.5
            try:
                dists, ids = monte_carlo_random_params(nodes, edges, init,
                                                       n_samples=n, variation=var)
            except Exception as exc:
                self._metab_show_result_text([('{}\n'.format(exc), 'bad')]); return
            lines = [(('Монте-Карло ({} выборок)\n'.format(n) if is_ru
                       else 'Monte Carlo ({} samples)\n'.format(n)), 'ttl'),
                     (('  метаболит: среднее ± СКО\n\n' if is_ru
                       else '  metabolite: mean ± SD\n\n'), 'dim')]
            for nid in ids:
                vals = dists.get(nid, [])
                if vals:
                    mean = _np.mean(vals); sd = _np.std(vals)
                    cv = (sd / mean * 100) if mean else 0
                    tag = 'wrn' if cv > 50 else 'ok'
                    lines.append(('  {:<12} {:.3f} ± {:.3f}  (CV {:.0f}%)\n'.format(
                        nid[:12], mean, sd, cv), tag))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Запустить Монте-Карло' if is_ru else '▶ Run Monte Carlo'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)


    def _metab_panel_tcsens(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Чувствительность траектории: как весь ход концентраций во времени\n'
            'реагирует на малое изменение параметра V каждой реакции.'
            if is_ru else
            'Time-course sensitivities: how the whole concentration trajectory\n'
            'responds to a small change in each reaction\'s V.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            res = timecourse_sensitivities(model, t_max=20, n_points=80)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')]); return
            sens = res.get('sensitivities', {})
            lines = [(('Чувствительность траектории\n' if is_ru
                       else 'Time-course sensitivities\n'), 'ttl'),
                     (('  |dX/dp| усреднённая по времени, по реакциям\n\n' if is_ru
                       else '  |dX/dp| time-averaged, per reaction\n\n'), 'dim')]
            import numpy as _np
            for rid, spmap in list(sens.items())[:12]:
                # rank species by mean abs sensitivity for this reaction
                scored = sorted(spmap.items(),
                                key=lambda kv: -_np.mean(_np.abs(kv[1])))[:1]
                for sp, arr in scored:
                    lines.append(('  {:<6} → {:<10} {:.3f}\n'.format(
                        rid[:6], sp[:10], float(_np.mean(_np.abs(arr)))), 'nrm'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Чувствительность траектории' if is_ru
                                else '▶ Run time-course sensitivities'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_crosssection(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Сечение Пуанкаре: фиксирует состояние системы каждый раз, когда\n'
            'выбранный метаболит пересекает порог. Выявляет периодические\n'
            'колебания и оценивает их период.'
            if is_ru else
            'Poincaré cross-section: records the system state each time the\n'
            'chosen metabolite crosses a threshold. Reveals periodic\n'
            'oscillations and estimates their period.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(parent, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        sp_ids = list(model['species'].keys())
        tk.Label(ctl, text=('Метаболит:' if is_ru else 'Species:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        sp_v = tk.StringVar(value=sp_ids[-1] if sp_ids else '')
        ttk.Combobox(ctl, textvariable=sp_v, values=sp_ids, state='readonly',
                     width=12, font=('Arial', 8)).pack(side='left', padx=2)
        tk.Label(ctl, text=('Время:' if is_ru else 'Time:'), bg=biosim_theme('panel'),
                 fg=biosim_theme('text'), font=('Arial', 9)).pack(side='left', padx=(8, 2))
        tmax_v = tk.StringVar(value='100')
        tk.Entry(ctl, textvariable=tmax_v, width=6, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2)

        def run():
            try:
                tmax = float(tmax_v.get() or 100)
            except ValueError:
                tmax = 100.0
            res = cross_section(model, sp_v.get(), t_max=tmax, n_points=2000)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')]); return
            lines = [(('Сечение Пуанкаре: {}\n'.format(sp_v.get()) if is_ru
                       else 'Cross section: {}\n'.format(sp_v.get())), 'ttl'),
                     ('  ' + ('порог: ' if is_ru else 'threshold: ') +
                      '{:.3f}\n'.format(res['threshold']), 'dim'),
                     ('  ' + ('пересечений: ' if is_ru else 'crossings: ') +
                      '{}\n'.format(res['n_crossings']), 'nrm')]
            if res['period']:
                lines.append(('  ' + ('период колебаний ≈ ' if is_ru else 'period ≈ ') +
                              '{:.3f}\n'.format(res['period']), 'ok'))
            else:
                lines.append((('  Нет устойчивых колебаний (не осциллятор).\n'
                               if is_ru else '  No sustained oscillations (not an oscillator).\n'), 'wrn'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Построить сечение' if is_ru else '▶ Run cross section'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_lyapunov(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Показатель Ляпунова: измеряет чувствительность к начальным\n'
            'условиям. λ > 0 — хаос; λ < 0 — устойчивость; λ ≈ 0 — периодика.'
            if is_ru else
            'Lyapunov exponent: measures sensitivity to initial conditions.\n'
            'λ > 0 — chaos; λ < 0 — stable; λ ≈ 0 — periodic.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            res = lyapunov_exponent(model, t_max=60, n_points=800)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')]); return
            lam = res['lyapunov']
            tag = 'bad' if lam > 0.01 else ('ok' if lam < -0.01 else 'wrn')
            lines = [(('Показатель Ляпунова\n' if is_ru else 'Lyapunov exponent\n'), 'ttl'),
                     ('  λ = {:.5f}\n'.format(lam), 'big'),
                     ('  ' + res['interpretation'] + '\n', tag)]
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Вычислить λ' if is_ru else '▶ Compute λ'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_lna(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Линейное приближение шума (LNA): оценивает внутренний шум\n'
            '(дисперсию и CV) концентраций около стационара через уравнение\n'
            'Ляпунова. Показывает, какие метаболиты самые «шумные».'
            if is_ru else
            'Linear Noise Approximation (LNA): estimates intrinsic noise\n'
            '(variance and CV) of concentrations near steady state via the\n'
            'Lyapunov equation. Shows which metabolites are noisiest.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            res = linear_noise_approximation(model)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')]); return
            noise = res.get('noise', {})
            lines = [(('Внутренний шум (LNA)\n' if is_ru else 'Intrinsic noise (LNA)\n'), 'ttl'),
                     (('  метаболит: среднее, дисперсия, CV\n\n' if is_ru
                       else '  metabolite: mean, variance, CV\n\n'), 'dim')]
            ranked = sorted(noise.items(), key=lambda kv: -kv[1]['cv'])
            for sp, st in ranked:
                tag = 'wrn' if st['cv'] > 0.5 else 'nrm'
                lines.append(('  {:<10} μ={:.3f} σ²={:.3f} CV={:.2f}\n'.format(
                    sp[:10], st['mean'], st['variance'], st['cv']), tag))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Вычислить шум (LNA)' if is_ru else '▶ Compute noise (LNA)'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_paramest(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Оценка параметров: подбирает V реакций так, чтобы модель совпала\n'
            'с экспериментальными данными (минимум суммы квадратов ошибок).\n'
            'Демо-режим: генерирует «данные» из текущей модели с шумом и\n'
            'проверяет, что фиттинг восстанавливает параметры.'
            if is_ru else
            'Parameter estimation: fits reaction V so the model matches\n'
            'experimental data (least squares). Demo mode: generates noisy\n'
            '"data" from the current model and checks the fit recovers it.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            import numpy as _np
            if not model['reactions']:
                self._metab_show_result_text([(('Нет реакций\n' if is_ru else 'No reactions\n'), 'bad')]); return
            # Build synthetic noisy data from current model
            base = simulate_metabolic_model(model, t_max=15, n_points=60)
            if base.get('error'):
                self._metab_show_result_text([(base['error'] + '\n', 'bad')]); return
            target_sp = base['species'][-1]
            rng = _np.random.default_rng(0)
            data = {target_sp: []}
            tgrid = base['time']
            for frac in (0.25, 0.5, 0.75, 1.0):
                k = int(frac * (len(tgrid) - 1))
                val = base['concentrations'][target_sp][k] * (1 + rng.normal(0, 0.03))
                data[target_sp].append((tgrid[k], val))
            # fit V of first 2 reactions
            specs = [(i, 'V', 0.1, 5.0) for i in range(min(2, len(model['reactions'])))
                     if 'V' in model['reactions'][i].get('params', {})]
            if not specs:
                self._metab_show_result_text([(('Реакции без параметра V.\n'
                                                if is_ru else 'Reactions have no V parameter.\n'), 'wrn')]); return
            res = parameter_estimation(model, data, specs, max_iter=30)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')]); return
            lines = [(('Оценка параметров (фиттинг)\n' if is_ru else 'Parameter estimation\n'), 'ttl'),
                     ('  ' + ('целевая функция (SSE): ' if is_ru else 'objective (SSE): ') +
                      '{:.5f}\n\n'.format(res['objective']), 'dim')]
            for pk, pv in res['fitted_params'].items():
                lines.append(('  {:<12} = {:.4f}\n'.format(pk, pv), 'ok'))
            lines.append((('\n(данные сгенерированы из модели + 3% шум)\n'
                           if is_ru else '\n(data generated from model + 3% noise)\n'), 'dim'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Подобрать параметры' if is_ru else '▶ Estimate parameters'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)
        tk.Label(parent, text=(
            'Для реальных данных используйте формат CSV: время, значение —\n'
            'загрузка данных появится в следующих версиях.'
            if is_ru else
            'For real data use CSV: time, value — data import lands in a\n'
            'future version.'),
            bg=biosim_theme('bg'), fg='#57606a', font=('Arial', 8, 'italic'),
            justify='left').pack(fill='x', pady=(4, 0))

    def _metab_panel_timescale(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Разделение временных масштабов: собственные значения якобиана в\n'
            'стационаре дают быстрые и медленные моды (τ = 1/|Re λ|).\n'
            'Большое отношение масштабов = жёсткая (stiff) система.'
            if is_ru else
            'Time scale separation: Jacobian eigenvalues at steady state give\n'
            'fast and slow modes (τ = 1/|Re λ|). A large ratio means a stiff\n'
            'system.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            res = time_scale_separation(model)
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')]); return
            modes = res.get('modes', [])
            lines = [(('Разделение временных масштабов\n' if is_ru
                       else 'Time scale separation\n'), 'ttl'),
                     ('  ' + ('отношение жёсткости: ' if is_ru else 'stiffness ratio: ') +
                      '{:.1f}'.format(res['stiffness_ratio']) +
                      ('  (жёсткая!)' if res['stiff'] and is_ru else '  (stiff!)' if res['stiff'] else '') +
                      '\n\n', 'wrn' if res['stiff'] else 'dim')]
            for m in modes[:12]:
                ts = m['time_scale']
                ts_str = '{:.3f}'.format(ts) if ts is not None else '∞'
                osc = ' ⟳' if m['oscillatory'] else ''
                tag = 'ok' if (ts is not None and ts < 1) else 'nrm'
                lines.append(('  τ={:<8} (Re λ={:+.3f}){}\n'.format(
                    ts_str, m['eigenvalue_real'], osc), tag))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Анализ масштабов' if is_ru else '▶ Analyze time scales'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_optimization(self, parent):
        is_ru = (self.lang == 'ru')
        tk.Label(parent, text=(
            'Оптимизация уровней ферментов: подобрать концентрации ферментов,\n'
            'дающие максимум конечного продукта (существующий движок).'
            if is_ru else
            'Enzyme-level optimization: find enzyme concentrations that\n'
            'maximize final product (existing engine).'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def run():
            model = self._metab_model()
            # Build enzyme chain from reactions carrying a kinetic-enzyme key
            norm = []
            for r in model['reactions']:
                e = r.get('enzyme', '')
                for cand in (e, e.lower(), e.upper()):
                    if cand and cand in METABOLIC_ENZYMES_KINETIC:
                        norm.append(cand)
                        break
            if not norm:
                self._metab_show_result_text([(('Нет кинетических ферментов в модели.\n'
                                                'Загрузите путь (напр. гликолиз) для оптимизации.\n'
                                                if is_ru else
                                                'No kinetic enzymes in model.\n'
                                                'Load a pathway (e.g. glycolysis) to optimize.\n'), 'wrn')])
                return
            try:
                res = optimize_enzyme_levels(norm, substrate_amount=10.0)
            except Exception as exc:
                self._metab_show_result_text([('{}\n'.format(exc), 'bad')])
                return
            if res.get('error'):
                self._metab_show_result_text([(res['error'] + '\n', 'bad')])
                return
            lines = [(('Оптимальные уровни ферментов\n' if is_ru else 'Optimal enzyme levels\n'), 'ttl'),
                     ('  ' + ('продукт: ' if is_ru else 'product: ') +
                      '{:.3f}\n\n'.format(res.get('best_product', 0)), 'big')]
            for e, lvl in (res.get('best_levels') or {}).items():
                lines.append(('  {:<14} {:.2f}\n'.format(e, lvl), 'nrm'))
            self._metab_show_result_text(lines)
        tk.Button(parent, text=('▶ Оптимизировать' if is_ru else '▶ Optimize'),
                  bg='#1a7f37', highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)

    def _metab_panel_fba(self, parent):
        is_ru = (self.lang == 'ru')
        model = self._metab_model()
        tk.Label(parent, text=(
            'Методы баланса потоков (нужна библиотека cobra):\n'
            '• FBA — оптимальные потоки через сеть.\n'
            '• FVA — диапазоны потоков при оптимальном росте.\n'
            '• pFBA — экономная FBA (минимум суммарного потока).\n'
            '• OptKnock — какие нокауты усилят целевой продукт.\n'
            '• Динамическая FBA — рост во времени по мере расхода субстрата.'
            if is_ru else
            'Flux balance methods (requires the cobra library):\n'
            '• FBA — optimal fluxes through the network.\n'
            '• FVA — flux ranges at optimal growth.\n'
            '• pFBA — parsimonious FBA (minimal total flux).\n'
            '• OptKnock — which knockouts boost the target product.\n'
            '• Dynamic FBA — growth over time as substrate is consumed.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
            font=('Arial', 9), justify='left', anchor='w').pack(fill='x', pady=(0, 8))

        def build_cm():
            cm, info = build_cobra_model_from_metabolic(model)
            return cm, info

        def run_fba():
            cm, info = build_cm()
            if cm is None:
                self._metab_show_result_text([(info + '\n', 'bad')]); return
            sol, fluxes, msg = run_fba_on_model(cm)
            if fluxes is None:
                self._metab_show_result_text([(msg + '\n', 'bad')]); return
            active = sorted(fluxes.items(), key=lambda kv: -abs(kv[1]))[:20]
            lines = [(('FBA — оптимальные потоки\n' if is_ru else 'FBA — optimal fluxes\n'), 'ttl'),
                     ('  ' + msg + '\n\n', 'dim')]
            for rid, v in active:
                if abs(v) > 1e-6:
                    lines.append(('  {:<12} {:+.3f}\n'.format(str(rid)[:12], v), 'nrm'))
            self._metab_show_result_text(lines)

        def run_fva():
            cm, info = build_cm()
            if cm is None:
                self._metab_show_result_text([(info + '\n', 'bad')]); return
            res, msg = run_flux_variability_analysis(cm)
            if res is None:
                self._metab_show_result_text([(msg + '\n', 'bad')]); return
            lines = [(('FVA — диапазоны потоков\n' if is_ru else 'FVA — flux ranges\n'), 'ttl'),
                     ('  ' + msg + '\n\n', 'dim')]
            for rid, (mn, mx) in list(res.items())[:20]:
                lines.append(('  {:<10} [{:+.2f}, {:+.2f}]\n'.format(str(rid)[:10], mn, mx), 'nrm'))
            self._metab_show_result_text(lines)

        def run_pfba():
            cm, info = build_cm()
            if cm is None:
                self._metab_show_result_text([(info + '\n', 'bad')]); return
            res, msg = run_parsimonious_fba(cm)
            if res is None:
                self._metab_show_result_text([(msg + '\n', 'bad')]); return
            lines = [(('pFBA — экономная FBA\n' if is_ru else 'pFBA — parsimonious FBA\n'), 'ttl'),
                     ('  ' + ('целевая функция: ' if is_ru else 'objective: ') +
                      '{:.3f}\n'.format(res.get('objective_value', 0)), 'big'),
                     ('  ' + ('суммарный поток: ' if is_ru else 'total flux: ') +
                      '{:.2f}\n\n'.format(res.get('total_flux', 0)), 'dim')]
            for rid, v in res.get('top_active', [])[:16]:
                if abs(v) > 1e-6:
                    lines.append(('  {:<12} {:+.3f}\n'.format(str(rid)[:12], v), 'nrm'))
            self._metab_show_result_text(lines)

        def run_optknock():
            cm, info = build_cm()
            if cm is None:
                self._metab_show_result_text([(info + '\n', 'bad')]); return
            # target = last reaction (product-forming) by default
            target = cm.reactions[-1].id if len(cm.reactions) else None
            if not target:
                self._metab_show_result_text([(('Нет реакций\n' if is_ru else 'No reactions\n'), 'bad')]); return
            try:
                res = optknock_suggest(cm, target, max_knockouts=2)
            except Exception as exc:
                self._metab_show_result_text([('OptKnock: {}\n'.format(exc), 'bad')]); return
            if not res or (isinstance(res, dict) and res.get('error')):
                self._metab_show_result_text([(('OptKnock не дал результата\n'
                                                if is_ru else 'OptKnock found nothing\n'), 'wrn')]); return
            lines = [(('OptKnock — предлагаемые нокауты\n' if is_ru
                       else 'OptKnock — suggested knockouts\n'), 'ttl'),
                     ('  ' + ('цель: ' if is_ru else 'target: ') + str(target) + '\n\n', 'dim')]
            suggestions = res.get('suggestions', res) if isinstance(res, dict) else res
            if isinstance(suggestions, list):
                for s in suggestions[:8]:
                    lines.append(('  • {}\n'.format(s), 'ok'))
            self._metab_show_result_text(lines)

        def run_dfba():
            cm, info = build_cm()
            if cm is None:
                self._metab_show_result_text([(info + '\n', 'bad')]); return
            # substrate = first fixed species' exchange; biomass = objective
            fixed = [sid for sid, sp in model['species'].items() if sp.get('type') == 'fixed']
            if not fixed:
                self._metab_show_result_text([(('Нужен фиксированный субстрат (тип fixed).\n'
                                                if is_ru else 'Need a fixed substrate species.\n'), 'wrn')]); return
            sub_rxn = 'EX_' + fixed[0]
            biomass = cm.objective_expression if hasattr(cm, 'objective_expression') else None
            biomass_rxn = cm.reactions[-1].id
            try:
                out = dynamic_fba(cm, sub_rxn, biomass_rxn)
            except Exception as exc:
                self._metab_show_result_text([('dFBA: {}\n'.format(exc), 'bad')]); return
            traj = out[0] if isinstance(out, tuple) else out
            if not traj:
                self._metab_show_result_text([(('Динамическая FBA: нет данных\n'
                                                if is_ru else 'Dynamic FBA: no data\n'), 'wrn')]); return
            lines = [(('Динамическая FBA (время, биомасса, субстрат)\n' if is_ru
                       else 'Dynamic FBA (time, biomass, substrate)\n'), 'ttl')]
            for row in (traj if isinstance(traj, list) else [])[:20]:
                try:
                    t, bio, sub = row
                    lines.append(('  t={:<5.1f} bio={:<7.3f} sub={:.3f}\n'.format(t, bio, sub), 'nrm'))
                except Exception:
                    pass
            self._metab_show_result_text(lines)

        grid = tk.Frame(parent, bg=biosim_theme('bg')); grid.pack(fill='x', pady=4)
        for txt_ru, txt_en, cmd, color in [
            ('▶ FBA', '▶ FBA', run_fba, '#1a7f37'),
            ('▶ FVA', '▶ FVA', run_fva, '#0969da'),
            ('▶ pFBA', '▶ pFBA', run_pfba, '#0969da'),
            ('▶ OptKnock', '▶ OptKnock', run_optknock, '#8250df'),
            ('▶ Динамическая FBA', '▶ Dynamic FBA', run_dfba, '#9a6700'),
        ]:
            tk.Button(grid, text=(txt_ru if is_ru else txt_en),
                      bg=color, highlightbackground=color, fg='white', relief='flat',
                      font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                      command=cmd).pack(fill='x', pady=2)

        # Legacy organism→product analysis (knockout screen + organism comparison)
        has_op = bool(model.get('product') and model.get('organism') in METABOLIC_ORGANISMS
                      and model.get('product') in METABOLIC_PRODUCTS)
        if has_op:
            def run_legacy():
                st = self.current_state['metabolic']
                st.setdefault('added_enzymes', [])
                st.setdefault('knocked_out', [])
                self._metab_open_analysis()
            tk.Button(parent, text=('▶ Нокаут-скрин + сравнение организмов'
                                    if is_ru else '▶ Knockout screen + organism comparison'),
                      bg=biosim_theme('panel'), highlightbackground='#1a7f37', fg='#1a7f37',
                      relief='solid', bd=1, font=('Arial', 10, 'bold'), cursor='hand2', pady=6,
                      command=run_legacy).pack(fill='x', pady=(8, 2))

    def _metab_model_to_circuit(self, model):
        """Adapt a COPASI-style metabolic model into (nodes, edges, init) so the
        existing circuit-based analysis engines (MCA, sensitivity) can run on it.
        Each species → a node; each reaction → an edge substrate→product.

        Nodes get a small nonzero production so the MCA/sensitivity engines
        (which perturb 'production') have something to vary; fixed species get
        a larger source term to act as a constant input.
        """
        nodes = []
        init = {}
        for sid, sp in model.get('species', {}).items():
            is_fixed = sp.get('type') == 'fixed'
            nodes.append({'id': sid, 'part_key': 'molecule',
                          'production': 1.0 if is_fixed else 0.2,
                          'degradation': 0.1})
            init[sid] = float(sp.get('initial', 0.0))
        edges = []
        for rxn in model.get('reactions', []):
            subs = list(rxn.get('substrates', {}).keys())
            prods = list(rxn.get('products', {}).keys())
            if subs and prods:
                params = rxn.get('params', {})
                k = params.get('V', params.get('k', params.get('Vf', 1.0)))
                # Engines (ODE / Gillespie / tau-leap) expect 'from'/'to' plus
                # 'type', 'k'/'rate', 'kcat', 'km'.
                edges.append({'from': subs[0], 'to': prods[0],
                              'type': 'catalysis', 'reaction': 'catalysis',
                              'k': k, 'rate': k,
                              'kcat': params.get('V', 1.0), 'km': params.get('Km', 1.0),
                              'strength': 3.0, 'hill_n': 2})
        return nodes, edges, init








    def _metab_open_analysis(self):
        """Flux balance analysis plus a single-knockout screen.

        Both engines existed in the code but nothing in the interface ever
        called them, so the metabolic section could show a yield number
        without ever telling the user which reaction was limiting it or which
        single change would help most.
        """
        is_ru = (self.lang == 'ru')
        state = self.current_state['metabolic']
        org_key = state.get('organism')
        prod_key = state.get('product')
        org = METABOLIC_ORGANISMS.get(org_key)
        prod = METABOLIC_PRODUCTS.get(prod_key)
        if not org or not prod:
            Toast(self, 'Сначала выберите организм и продукт' if is_ru
                  else 'Pick an organism and a product first')
            return

        win = tk.Toplevel(self)
        win.title(('Анализ путей: FBA и скрининг нокаутов' if is_ru
                   else 'Pathway analysis: FBA and knockout screen'))
        win.geometry('860x680')
        win.configure(bg=biosim_theme('bg'))
        win.transient(self)

        prod_name = prod.get('name_ru' if is_ru else 'name', prod_key)
        org_name = org.get('name_ru' if is_ru else 'name', org_key)
        tk.Label(win, text='{} → {}'.format(org_name, prod_name),
                 bg=biosim_theme('bg'), fg='#8250df',
                 font=('Arial', 14, 'bold')).pack(pady=(10, 2))

        nb = ttk.Notebook(win)
        nb.pack(fill='both', expand=True, padx=8, pady=8)

        # ── build a reaction network from the product's pathway ─────
        chain = prod.get('pathway', [])
        added = list(state.get('added_enzymes', []))
        ko = set(state.get('knocked_out', []))
        reactions = []
        for i in range(len(chain) - 1):
            reactions.append({
                'name': '{} → {}'.format(chain[i], chain[i + 1]),
                'substrates': {chain[i]: 1.0},
                'products': {chain[i + 1]: 1.0},
                'max_flux': 10.0,
            })
        # competing drains that pull carbon away from the target
        if chain:
            reactions.append({
                'name': ('Биомасса (рост)' if is_ru else 'Biomass (growth)'),
                'substrates': {chain[0]: 1.0}, 'products': {'Biomass': 1.0},
                'max_flux': 4.0,
            })
            reactions.append({
                'name': ('Побочный сток' if is_ru else 'By-product drain'),
                'substrates': {chain[0]: 1.0}, 'products': {'Byproduct': 1.0},
                'max_flux': 2.5,
            })
        # enzymes the user added widen the target route
        boost = 1.0 + 0.25 * len(added)
        for r in reactions:
            if 'Biomass' not in r['products'] and 'Byproduct' not in r['products']:
                r['max_flux'] *= boost

        # ── FBA page ────────────────────────────────────────────────
        p_fba = tk.Frame(nb, bg=biosim_theme('bg'))
        nb.add(p_fba, text='FBA')
        txt = scrolledtext.ScrolledText(p_fba, bg=biosim_theme('panel'),
                                        fg=biosim_theme('text'),
                                        font=('Courier', 10), relief='flat')
        txt.pack(fill='both', expand=True, padx=4, pady=4)
        txt.tag_config('h', foreground='#0969da', font=('Arial', 11, 'bold'))
        txt.tag_config('ok', foreground='#1a7f37')
        txt.tag_config('bad', foreground='#cf222e')
        txt.tag_config('dim', foreground='#57606a', font=('Arial', 9))

        objective = reactions[-3]['name'] if len(reactions) >= 3 else (
            reactions[0]['name'] if reactions else '')
        try:
            fba = metabolic_flux_balance(reactions, objective)
        except Exception as exc:
            biosim_log('error', 'FBA: {}'.format(exc))
            fba = {'error': str(exc)}

        txt.insert('end', ('Баланс потоков (FBA)\n' if is_ru
                           else 'Flux balance analysis\n'), 'h')
        txt.insert('end', ('Углерод распределяется между целевым путём, ростом '
                           'и побочными стоками. Ограничивающая реакция — та, '
                           'что работает на максимуме.\n\n' if is_ru else
                           'Carbon is split between the target route, growth and '
                           'by-product drains. The limiting reaction is the one '
                           'running at its ceiling.\n\n'), 'dim')
        if fba.get('error'):
            txt.insert('end', 'Ошибка: {}\n'.format(fba['error']), 'bad')
        else:
            fluxes = fba.get('fluxes', fba) or {}
            if isinstance(fluxes, dict):
                items = [(k, v) for k, v in fluxes.items()
                         if isinstance(v, (int, float))]
                items.sort(key=lambda kv: -kv[1])
                for name, val in items:
                    cap = next((r['max_flux'] for r in reactions
                                if r['name'] == name), None)
                    at_cap = (cap is not None and val >= cap * 0.98)
                    txt.insert('end', '  {:<34} {:6.2f}{}\n'.format(
                        name[:34], val,
                        ('  ← предел' if is_ru else '  ← at limit') if at_cap else ''),
                        'bad' if at_cap else 'ok')
        txt.insert('end', ('\nМодель упрощённая (пропорциональное распределение). '
                           'Для полноценной FBA нужна COBRApy и модель генома.\n'
                           if is_ru else
                           '\nSimplified model (proportional allocation). A full '
                           'FBA needs COBRApy and a genome-scale model.\n'), 'dim')
        txt.config(state='disabled')

        # ── knockout screen ─────────────────────────────────────────
        p_ko = tk.Frame(nb, bg=biosim_theme('bg'))
        nb.add(p_ko, text=('Скрининг нокаутов' if is_ru else 'Knockout screen'))

        base = calculate_metabolic_flux(org_key, prod_key, added, list(ko))
        base_yield = base['yield_g_per_g'] if base else 0.0

        rows = []
        for ekey, enz in METABOLIC_ENZYMES.items():
            if ekey in ko:
                continue
            trial = calculate_metabolic_flux(org_key, prod_key, added,
                                             list(ko) + [ekey])
            if not trial:
                continue
            delta = trial['yield_g_per_g'] - base_yield
            if abs(delta) > 1e-9:
                rows.append((ekey, enz, trial['yield_g_per_g'], delta))
        rows.sort(key=lambda r: -r[3])

        head = tk.Frame(p_ko, bg=biosim_theme('bg'))
        head.pack(fill='x', padx=6, pady=(6, 2))
        tk.Label(head, text=('Что будет, если выключить один ген' if is_ru
                             else 'What happens if one gene is switched off'),
                 bg=biosim_theme('bg'), fg='#0969da',
                 font=('Arial', 11, 'bold')).pack(anchor='w')
        tk.Label(head, text=('Базовый выход: {:.3f} г/г. Ниже — как изменится '
                             'выход при нокауте каждого фермента.'
                             .format(base_yield) if is_ru else
                             'Baseline yield: {:.3f} g/g. Below, how the yield '
                             'shifts if each enzyme is knocked out.'
                             .format(base_yield)),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 9), wraplength=800,
                 justify='left').pack(anchor='w')

        kt = scrolledtext.ScrolledText(p_ko, bg=biosim_theme('panel'),
                                       fg=biosim_theme('text'),
                                       font=('Courier', 10), relief='flat')
        kt.pack(fill='both', expand=True, padx=4, pady=4)
        kt.tag_config('good', foreground='#1a7f37', font=('Courier', 10, 'bold'))
        kt.tag_config('bad', foreground='#cf222e')
        kt.tag_config('h', foreground='#0969da', font=('Arial', 10, 'bold'))
        kt.tag_config('dim', foreground='#57606a', font=('Arial', 9))

        if not rows:
            kt.insert('end', ('Ни один одиночный нокаут не меняет выход в этой '
                              'конфигурации.\n' if is_ru else
                              'No single knockout changes the yield in this '
                              'configuration.\n'), 'dim')
        else:
            helpful = [r for r in rows if r[3] > 0]
            harmful = [r for r in rows if r[3] < 0]
            if helpful:
                kt.insert('end', ('Повышают выход\n' if is_ru
                                  else 'Increase the yield\n'), 'h')
                for ekey, enz, y, d in helpful[:12]:
                    kt.insert('end', '  {:<8} {:<30} {:.3f}  ({:+.3f})\n'.format(
                        ekey, (enz.get('full') or enz.get('name', ''))[:30], y, d),
                        'good')
                kt.insert('end', ('  Такие гены отводят углерод от цели — их '
                                  'отключение перенаправляет поток.\n\n' if is_ru
                                  else '  These genes divert carbon away from the '
                                  'target; removing them redirects flux.\n\n'), 'dim')
            if harmful:
                kt.insert('end', ('Снижают выход\n' if is_ru
                                  else 'Reduce the yield\n'), 'h')
                for ekey, enz, y, d in harmful[-12:]:
                    kt.insert('end', '  {:<8} {:<30} {:.3f}  ({:+.3f})\n'.format(
                        ekey, (enz.get('full') or enz.get('name', ''))[:30], y, d),
                        'bad')
                kt.insert('end', ('  Эти нужны самому пути — выключать нельзя.\n'
                                  if is_ru else
                                  '  These are part of the route itself — do not '
                                  'remove them.\n'), 'dim')
        kt.config(state='disabled')

        # ── organism comparison ─────────────────────────────────────
        p_cmp = tk.Frame(nb, bg=biosim_theme('bg'))
        nb.add(p_cmp, text=('Сравнение организмов' if is_ru
                            else 'Organism comparison'))
        ct = scrolledtext.ScrolledText(p_cmp, bg=biosim_theme('panel'),
                                       fg=biosim_theme('text'),
                                       font=('Courier', 10), relief='flat')
        ct.pack(fill='both', expand=True, padx=4, pady=4)
        ct.tag_config('h', foreground='#0969da', font=('Arial', 10, 'bold'))
        ct.tag_config('best', foreground='#1a7f37', font=('Courier', 10, 'bold'))
        ct.tag_config('dim', foreground='#57606a', font=('Arial', 9))
        ct.insert('end', ('Один и тот же путь в разных хозяевах\n' if is_ru
                          else 'The same route in different hosts\n'), 'h')
        comp = []
        for okey, odata in METABOLIC_ORGANISMS.items():
            r = calculate_metabolic_flux(okey, prod_key, added, list(ko))
            if r:
                comp.append((okey, odata, r))
        comp.sort(key=lambda c: -c[2]['yield_g_per_g'])
        for i, (okey, odata, r) in enumerate(comp):
            nm = odata.get('name_ru' if is_ru else 'name', okey)
            native = prod_key in [p for p in odata.get('native_products', [])]
            ct.insert('end', '  {:<24} выход {:.3f} г/г · скорость {:.2f} г/ч{}\n'
                      .format(nm[:24], r['yield_g_per_g'], r['rate_g_per_h'],
                              '  ← лучший' if i == 0 else ''),
                      'best' if i == 0 else None)
            if r.get('missing_enzymes'):
                ct.insert('end', '      не хватает: {}\n'.format(
                    ', '.join(r['missing_enzymes'][:6])), 'dim')
        ct.config(state='disabled')




    # ── SYNTHETIC ORGANISM TAB ──
    def _build_organism_tab(self):
        """Synthetic organism workspace: resource-budget module composer
        (chassis + module library on the left, results notebook on the
        right) plus a time-resolved whole-cell model (genes, chromosome,
        processes, environment, and simulation tasks) as additional tabs in
        the same results notebook.
        """
        is_ru = (self.lang == 'ru')
        f = tk.Frame(self.content, bg=biosim_theme('bg'))
        modules, chassis_dict, gene_cats = get_organism_task_modules()

        self._org_chassis = tk.StringVar(value='ecoli')
        # Create a variable for every module up front. Building them lazily as
        # categories were expanded meant a module in a collapsed category had
        # no state yet, so selections made programmatically (or restored from a
        # saved design) could silently go missing.
        self._org_tasks = {k: tk.BooleanVar(value=False)
                           for k in all_organism_modules()}
        self._org_search = tk.StringVar()
        self._org_cat_open = {c: (c in ('metabolism', 'immunity'))
                              for c in ORGANISM_MODULE_CATEGORIES}
        self._org_removed_cats = {}

        if not isinstance(self.current_state.get('organism_wholecell'), dict):
            self.current_state['organism_wholecell'] = new_whole_cell_model(
                'Новая клетка' if is_ru else 'New cell')
        self.current_state['organism_wholecell']['chassis'] = self._org_chassis.get()

        # ── LEFT: chassis + module library ──────────────────────────
        left = tk.Frame(f, bg=biosim_theme('bg'), width=330)
        left.pack(side='left', fill='y', padx=(0, 4))
        left.pack_propagate(False)

        hub = self._make_transfer_hub(left, 'organism')
        if hub:
            hub.pack(fill='x', pady=(0, 4))

        ch_frame = tk.LabelFrame(left, text=('Шасси (базовая клетка)' if is_ru
                                             else 'Chassis (base cell)'),
                                 bg=biosim_theme('panel'), fg='#1a7f37',
                                 font=('Arial', 11, 'bold'), relief='flat')
        ch_frame.pack(fill='x', pady=(0, 6))
        names = []
        self._org_chassis_keys = []
        for ck, cdata in chassis_dict.items():
            self._org_chassis_keys.append(ck)
            names.append(cdata['name_ru'] if is_ru else cdata['name_en'])
        self._org_chassis_combo = ttk.Combobox(ch_frame, values=names,
                                               state='readonly',
                                               font=('Arial', 10))
        self._org_chassis_combo.current(self._org_chassis_keys.index('ecoli'))
        self._org_chassis_combo.pack(fill='x', padx=6, pady=(6, 4))

        def chassis_changed(_e=None):
            i = self._org_chassis_combo.current()
            if i >= 0:
                self._org_chassis.set(self._org_chassis_keys[i])
            self.current_state['organism_wholecell']['chassis'] = self._org_chassis.get()
            self._org_update()
        self._org_chassis_combo.bind('<<ComboboxSelected>>', chassis_changed)

        self._org_chassis_info = tk.Label(
            ch_frame, text='', bg=biosim_theme('panel'),
            fg=biosim_theme('text_dim'), font=('Arial', 8), anchor='w',
            wraplength=300, justify='left')
        self._org_chassis_info.pack(fill='x', padx=8, pady=(0, 6))

        tk.Button(left, text=('📤 Экспорт клетки ▾' if is_ru
                              else '📤 Export cell ▾'),
                  bg='#0969da', highlightbackground='#0969da', fg='white',
                  relief='flat', font=('Arial', 9, 'bold'), cursor='hand2',
                  pady=4, command=self._wc_open_export_menu
                  ).pack(fill='x', pady=(0, 6))

        # ── module library ──
        lib = tk.LabelFrame(left, text=('Библиотека модулей' if is_ru
                                        else 'Module library'),
                            bg=biosim_theme('panel'), fg='#8250df',
                            font=('Arial', 11, 'bold'), relief='flat')
        lib.pack(fill='both', expand=True, pady=(0, 4))

        srow = tk.Frame(lib, bg=biosim_theme('panel'))
        srow.pack(fill='x', padx=6, pady=(4, 2))
        ent = tk.Entry(srow, textvariable=self._org_search,
                       bg=biosim_theme('bg'), fg=biosim_theme('text'),
                       font=('Arial', 9), relief='solid', bd=1)
        ent.pack(side='left', fill='x', expand=True)
        ent.bind('<KeyRelease>', lambda e: self._org_build_module_tree())
        tk.Label(srow, text=('поиск' if is_ru else 'search'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                 font=('Arial', 8)).pack(side='left', padx=4)

        holder = tk.Frame(lib, bg=biosim_theme('panel'))
        holder.pack(fill='both', expand=True, padx=2, pady=2)
        # Real ttk.Treeview like the Metabolism "Model & Tasks" list: keyboard
        # navigable (Up/Down move, Enter/Space toggles a module or opens/closes
        # a category), categories are collapsible parent rows and modules are
        # children with a ✓/☐ prefix showing whether they're selected.
        self._org_tree = ttk.Treeview(holder, show='tree', selectmode='browse')
        osb = ttk.Scrollbar(holder, orient='vertical', command=self._org_tree.yview)
        self._org_tree.configure(yscrollcommand=osb.set)
        self._org_tree.pack(side='left', fill='both', expand=True)
        osb.pack(side='right', fill='y')
        self._org_tree.bind('<<TreeviewSelect>>', self._org_tree_on_select)
        self._org_tree.bind('<Return>', self._org_tree_activate)
        self._org_tree.bind('<space>', self._org_tree_activate)
        self._org_tree.bind('<Double-Button-1>', self._org_tree_activate)
        # maps tree row iid -> ('cat', cat_key) or ('mod', module_key)
        self._org_tree_rowmap = {}

        btnrow = tk.Frame(left, bg=biosim_theme('bg'))
        btnrow.pack(fill='x', pady=(0, 4))
        tk.Button(btnrow, text=('+ Свой модуль' if is_ru else '+ Custom module'),
                  bg=biosim_theme('panel'), highlightbackground='#d4a72c',
                  fg='#9a6700', relief='solid', bd=1, font=('Arial', 9, 'bold'),
                  cursor='hand2', command=self._org_add_custom_dialog
                  ).pack(side='left', padx=2)
        tk.Button(btnrow, text=('Очистить' if is_ru else 'Clear'),
                  bg=biosim_theme('panel'), highlightbackground='#1c2128',
                  fg=biosim_theme('text_dim'), relief='solid', bd=1,
                  font=('Arial', 9), cursor='hand2',
                  command=self._org_clear_all).pack(side='left', padx=2)

        # ── RIGHT: results ──────────────────────────────────────────
        right = tk.Frame(f, bg=biosim_theme('bg'))
        right.pack(side='left', fill='both', expand=True)

        tk.Label(right, text=('Синтетический организм' if is_ru
                              else 'Synthetic Organism'),
                 bg=biosim_theme('bg'), fg='#1a7f37',
                 font=('Arial', 15, 'bold')).pack(pady=(4, 0))
        self._org_status = tk.Label(right, text='', bg=biosim_theme('bg'),
                                    font=('Arial', 12, 'bold'))
        self._org_status.pack(pady=(2, 4))

        self._org_nb = ttk.Notebook(right)
        self._org_nb.pack(fill='both', expand=True, padx=6, pady=(0, 6))

        self._org_pages = {}
        for key, title_ru, title_en in [
                ('overview', 'Обзор', 'Overview'),
                ('resources', 'Ресурсы', 'Resources'),
                ('growth', 'Рост и продукция', 'Growth & output'),
                ('genome', 'Геном', 'Genome'),
                ('fba', 'Потоки (FBA)', 'Fluxes (FBA)'),
                ('advice', 'Советы', 'Advice')]:
            page = tk.Frame(self._org_nb, bg=biosim_theme('bg'))
            self._org_nb.add(page, text=(title_ru if is_ru else title_en))
            self._org_pages[key] = page

        self._org_chart_canvas = {'growth': None, 'res': None}

        # ── whole-cell model + analysis, collapsed into two tree-driven tabs
        #    (same left-tree navigation as the Metabolism tab). Instead of nine
        #    separate notebook tabs, "Модель" holds Genes/Chromosome/Processes/
        #    Environment and "Анализ" holds the five simulation tasks; a tree on
        #    the left of each picks which panel shows in the center.
        self._wc_model_items = [
            ('wc_genes', '🧬', 'Гены', 'Genes', self._wc_panel_genes),
            ('wc_chromosome', '➰', 'Хромосома', 'Chromosome', self._wc_panel_chromosome),
            ('wc_processes', '⚙', 'Процессы', 'Processes', self._wc_panel_processes),
            ('wc_environment', '🌡', 'Окружение', 'Environment', self._wc_panel_environment),
        ]
        self._wc_analysis_items = [
            ('wc_timecourse', '⏱', 'Симуляция во времени', 'Time Course', self._wc_panel_timecourse),
            ('wc_division', '➗', 'Деление клетки', 'Cell Division', self._wc_panel_division),
            ('wc_stochastic', '🎲', 'Стохастика (шум)', 'Stochastic', self._wc_panel_stochastic),
            ('wc_montecarlo', '🎯', 'Монте-Карло', 'Monte Carlo', self._wc_panel_montecarlo),
            ('wc_sensitivity', '📈', 'Чувствительность', 'Sensitivity', self._wc_panel_sensitivity),
        ]
        self._wc_panel_builders = {k: b for k, _, _, _, b
                                   in self._wc_model_items + self._wc_analysis_items}

        model_tab = tk.Frame(self._org_nb, bg=biosim_theme('bg'))
        self._org_nb.add(model_tab, text=('🧬 Модель' if is_ru else '🧬 Model'))
        self._wc_build_tree_tab(model_tab, 'model', self._wc_model_items,
                                'МОДЕЛЬ' if is_ru else 'MODEL')

        analysis_tab = tk.Frame(self._org_nb, bg=biosim_theme('bg'))
        self._org_nb.add(analysis_tab, text=('📊 Анализ' if is_ru else '📊 Analysis'))
        self._wc_build_tree_tab(analysis_tab, 'analysis', self._wc_analysis_items,
                                'АНАЛИЗ' if is_ru else 'ANALYSIS')

        self._org_build_module_tree()
        f.after(200, self._org_update)
        return f

    def _wc_build_tree_tab(self, parent, group, items, heading):
        """Build one collapsed tab: a keyboard-navigable tree on the left
        (Up/Down to move, Enter to open, same feel as the Metabolism tab) and
        an editor panel on the right that shows the selected item's panel."""
        is_ru = (self.lang == 'ru')
        left = tk.Frame(parent, bg=biosim_theme('bg'), width=210)
        left.pack(side='left', fill='y', padx=(0, 4)); left.pack_propagate(False)
        tree = ttk.Treeview(left, show='tree', selectmode='browse')
        tree.pack(fill='both', expand=True)
        root_node = tree.insert('', 'end', iid='hdr', text='▾  ' + heading, open=True)
        for key, icon, ru, en, _b in items:
            tree.insert(root_node, 'end', iid=key,
                        text=' {}  {}'.format(icon, ru if is_ru else en))

        editor = tk.Frame(parent, bg=biosim_theme('bg'))
        editor.pack(side='left', fill='both', expand=True, padx=4)
        title = tk.Label(editor, text='', bg=biosim_theme('bg'), fg='#0969da',
                         font=('Arial', 13, 'bold'), anchor='w')
        title.pack(fill='x', pady=(0, 4))
        body = tk.Frame(editor, bg=biosim_theme('bg'))
        body.pack(fill='both', expand=True)

        if not hasattr(self, '_wc_tabs'):
            self._wc_tabs = {}
        self._wc_tabs[group] = {'tree': tree, 'title': title, 'body': body,
                                'items': items}

        def on_select(_e=None):
            self._wc_tree_show(group, tree.focus())
        tree.bind('<<TreeviewSelect>>', on_select)
        # Enter opens/refreshes the focused item (keyboard-friendly like asked)
        tree.bind('<Return>', lambda e: self._wc_tree_show(group, tree.focus()))
        # Up/Down already move selection in ttk.Treeview; ensure focus works
        tree.bind('<Double-Button-1>', lambda e: self._wc_tree_show(group, tree.focus()))

        # open the first item by default
        first = items[0][0]
        self.after(60, lambda: (tree.selection_set(first), tree.focus(first),
                                self._wc_tree_show(group, first)))

    def _wc_tree_show(self, group, key):
        """Render the panel for `key` into the group's editor body."""
        tab = getattr(self, '_wc_tabs', {}).get(group)
        if not tab or not key or key == 'hdr':
            return
        body = tab['body']
        if not body.winfo_exists():
            return
        for w in body.winfo_children():
            w.destroy()
        # title from items
        label = key
        for k, icon, ru, en, _b in tab['items']:
            if k == key:
                label = (ru if self.lang == 'ru' else en)
                break
        tab['title'].config(text=label)
        builder = self._wc_panel_builders.get(key)
        if builder:
            builder(body)

    def _org_wc_refresh_page(self, key):
        """Rebuild one whole-cell panel in place after a model mutation
        (add/delete/import a gene, pull growth). Finds which collapsed tab the
        key belongs to and, if that panel is the one currently shown, redraws
        it."""
        for group, tab in getattr(self, '_wc_tabs', {}).items():
            tree = tab['tree']
            if tree.exists(key) and tree.focus() == key:
                self._wc_tree_show(group, key)
                return

    def _wc_set_info(self, widget, text, tag='nrm'):
        if widget is None or not widget.winfo_exists():
            return
        widget.config(state='normal')
        widget.delete('1.0', 'end')
        widget.insert('end', text, tag)
        widget.config(state='disabled')

    def _wc_build_result_area(self, parent):
        """Small chart canvas + scrollable text panel, used at the bottom of
        each whole-cell simulation task tab. Each tab gets its own pair so
        results from different tasks don't overwrite each other."""
        canvas = tk.Canvas(parent, bg=biosim_theme('panel'), height=190,
                          relief='solid', bd=1, highlightthickness=0)
        canvas.pack(fill='x', pady=(8, 4))
        info = scrolledtext.ScrolledText(
            parent, height=8, bg=biosim_theme('bg'), fg=biosim_theme('text'),
            font=('Arial', 9), relief='flat', wrap='word', state='disabled',
            highlightthickness=0)
        info.pack(fill='both', expand=True, pady=(0, 4))
        for tag, fg, fnt in [
                ('ttl', '#0969da', ('Arial', 10, 'bold')),
                ('big', '#1a7f37', ('Arial', 14, 'bold')),
                ('wrn', '#9a6700', ('Arial', 9)),
                ('nrm', '#1c2128', ('Arial', 9)),
                ('dim', '#57606a', ('Arial', 8))]:
            info.tag_config(tag, foreground=fg, font=fnt)
        return canvas, info

