    def _wc_import_growth_from_metabolism(self):
        """Этап 5: подтянуть growth_rate выбранного в Метаболизме организма
        (биологическая константа, не требует запуска FBA) и масштабировать
        ресурсные пулы whole-cell модели относительно него."""
        is_ru = (self.lang == 'ru')
        model = self.current_state.get('organism_wholecell')
        metab_state = self.current_state.get('metabolic') or {}
        org_key = metab_state.get('organism')
        org = METABOLIC_ORGANISMS.get(org_key) if org_key else None
        if not isinstance(model, dict) or not org:
            self.toast(
                ('Сначала выберите организм во вкладке Метаболизм' if is_ru else
                 'Pick an organism in the Metabolism tab first'),
                level='warn', duration=2500)
            return
        ref = METABOLIC_ORGANISMS.get('E_coli_K12', {}).get('growth_rate', 1.0) or 1.0
        ratio = max(0.01, float(org.get('growth_rate', 1.0)) / ref)
        proc = model.setdefault('processes', {
            'ribosomes': 20000, 'rna_polymerase': 3000, 'stochastic': False})
        proc['ribosomes'] = round(WC_RIBOSOME_REF_COUNT * ratio)
        proc['rna_polymerase'] = round(WC_RNAP_REF_COUNT * ratio)
        self._org_wc_refresh_page('wc_processes')
        org_name = org.get('name_ru' if is_ru else 'name', org_key)
        self.toast(
            ('Организм «{}» (×{:.2f} от E. coli) — рибосомы {}, РНКП {}'
             .format(org_name, ratio, proc['ribosomes'], proc['rna_polymerase'])
             if is_ru else
             '"{}" organism (×{:.2f} vs E. coli) — ribosomes {}, RNAP {}'
             .format(org_name, ratio, proc['ribosomes'], proc['rna_polymerase'])),
            level='success', duration=3000)

