    def _wc_panel_timecourse(self, editor):
        """Этап 2+3: кинетика транскрипции/трансляции/деградации по каждому
        гену с учётом общего лимита рибосом/РНК-полимеразы (модули делят
        один ресурс, поэтому добавление гена реально сказывается на всех
        остальных)."""
        is_ru = (self.lang == 'ru')
        model = self.current_state.get('organism_wholecell')
        if not isinstance(model, dict):
            return
        desc = tk.Label(
            editor,
            text=('Кинетика экспрессии каждого гена, с общим лимитом ресурсов:\n'
                  'мРНК = транскрипция (сила промотора, делится между генами '
                  'через общий пул РНК-полимеразы) − деградация (т1/2)\n'
                  'Белок = трансляция (сила RBS × мРНК, делится через общий '
                  'пул рибосом) − деградация (т1/2)\n'
                  'Если суммарный спрос генов превышает пул — каждый ген '
                  'получает свою долю пропорционально (fair-share).' if is_ru else
                  'Expression kinetics per gene, with a shared resource limit:\n'
                  'mRNA = transcription (promoter strength, shared across a '
                  'common RNA-polymerase pool) − degradation (t1/2)\n'
                  'Protein = translation (RBS strength × mRNA, shared across '
                  'a common ribosome pool) − degradation (t1/2)\n'
                  'If total gene demand exceeds the pool, every gene gets a '
                  'proportional fair share.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9),
            justify='left', anchor='w')
        desc.pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(editor, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        tk.Label(ctl, text=('Время, мин:' if is_ru else 'Duration, min:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        tmax_v = tk.StringVar(value='60')
        tk.Entry(ctl, textvariable=tmax_v, width=6, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2, pady=6)

        def run():
            if not model.get('genes'):
                self._wc_set_info(info, (
                    'Сначала добавьте хотя бы один ген (вкладка «Гены»).'
                    if is_ru else
                    'Add at least one gene first (the "Genes" tab).'), 'wrn')
                return
            try:
                tmax = float(tmax_v.get() or 60)
            except ValueError:
                tmax = 60.0
            res = simulate_whole_cell_timecourse(model, t_max=tmax, n_points=200)
            if res.get('error'):
                self._wc_set_info(info, res['error'], 'wrn')
                return
            self._wc_plot_timecourse(canvas, res)
            head = ('Финальные значения (t={:.0f} мин)\n'.format(tmax) if is_ru
                    else 'Final values (t={:.0f} min)\n'.format(tmax))
            body_lines = ['  {:<22} {:.3f}'.format(s, v)
                         for s, v in res['final'].items()]
            scale = res.get('resource_scale', {})
            tag = 'nrm'
            tail = ''
            if scale:
                tx_s = scale.get('transcription', 1.0)
                tl_s = scale.get('translation', 1.0)
                if tx_s < 0.999 or tl_s < 0.999:
                    tag = 'wrn'
                    tail = ('\n\n⚠ Ресурсы в дефиците: транскрипция {:.0%}, '
                            'трансляция {:.0%} от максимума'.format(tx_s, tl_s)
                            if is_ru else
                            '\n\n⚠ Resources are scarce: transcription {:.0%}, '
                            'translation {:.0%} of maximum'.format(tx_s, tl_s))
                else:
                    tail = ('\n\nРесурсов достаточно (нет конкуренции)' if is_ru
                            else '\n\nResources are ample (no competition)')
            self._wc_set_info(info, head + '\n'.join(body_lines) + tail, tag)
            model['last_result'] = res

        tk.Button(editor, text=('▶ Запустить симуляцию' if is_ru
                                else '▶ Run simulation'),
                  bg='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)
        canvas, info = self._wc_build_result_area(editor)

    def _wc_panel_division(self, editor):
        """Этап 3: рост массы + репликация хромосомы + деление клетки."""
        is_ru = (self.lang == 'ru')
        model = self.current_state.get('organism_wholecell')
        if not isinstance(model, dict):
            return
        desc = tk.Label(
            editor,
            text=('Масса клетки растёт вместе с синтезом белка (та же '
                  'ресурс-лимитированная кинетика, что и в Time Course). '
                  'Когда масса удваивается И хромосома полностью '
                  'реплицирована — клетка делится: молекулы распределяются '
                  'пополам между дочерними клетками.' if is_ru else
                  "Cell mass grows together with protein synthesis (same "
                  "resource-limited kinetics as Time Course). Once mass "
                  "doubles AND the chromosome is fully replicated, the cell "
                  "divides: molecules are split in half between daughter "
                  "cells."),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9),
            justify='left', anchor='w', wraplength=380)
        desc.pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(editor, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        tk.Label(ctl, text=('Время, мин:' if is_ru else 'Duration, min:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        tmax_v = tk.StringVar(value='200')
        tk.Entry(ctl, textvariable=tmax_v, width=6, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2, pady=6)

        def run():
            if not model.get('genes'):
                self._wc_set_info(info, (
                    'Сначала добавьте хотя бы один ген (вкладка «Гены»).'
                    if is_ru else
                    'Add at least one gene first (the "Genes" tab).'), 'wrn')
                return
            try:
                tmax = float(tmax_v.get() or 200)
            except ValueError:
                tmax = 200.0
            res = simulate_whole_cell_growth(model, t_max=tmax, n_points=300)
            if res.get('error'):
                self._wc_set_info(info, res['error'], 'wrn')
                return
            mass_res = {
                'error': None, 'time': res['time'],
                'species': ['mass' if not is_ru else 'масса'],
                'concentrations': {('mass' if not is_ru else 'масса'): res['mass']},
            }
            self._wc_plot_timecourse(canvas, mass_res)
            events = res['division_events']
            n_div = len(events)
            lines = [('Делений за {:.0f} мин: {}\n'.format(tmax, n_div) if is_ru
                      else 'Divisions in {:.0f} min: {}\n'.format(tmax, n_div))]
            if events:
                times_str = ', '.join('{:.1f}'.format(x) for x in events[:10])
                lines.append(('Моменты деления (мин): {}\n'.format(times_str)
                              if is_ru else
                              'Division times (min): {}\n'.format(times_str)))
                if n_div >= 2:
                    gaps = [events[i + 1] - events[i] for i in range(n_div - 1)]
                    avg_gap = sum(gaps) / len(gaps)
                    lines.append(('Средний период деления: {:.1f} мин\n'
                                  .format(avg_gap) if is_ru else
                                  'Average division period: {:.1f} min\n'
                                  .format(avg_gap)))
            lines.append(('Финальная масса: {:.3f} (у.е.)'.format(res['mass'][-1])
                          if is_ru else
                          'Final mass: {:.3f} (a.u.)'.format(res['mass'][-1])))
            self._wc_set_info(info, ''.join(lines), 'nrm')
            model['last_result'] = res

        tk.Button(editor, text=('▶ Запустить симуляцию' if is_ru
                                else '▶ Run simulation'),
                  bg='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)
        canvas, info = self._wc_build_result_area(editor)

