    def _wc_panel_montecarlo(self, editor):
        """Этап 4: Monte Carlo по популяции — много независимых
        стохастических клеток, разброс финальных значений (шум между
        клетками)."""
        is_ru = (self.lang == 'ru')
        model = self.current_state.get('organism_wholecell')
        if not isinstance(model, dict):
            return
        desc = tk.Label(
            editor,
            text=('Запускает много независимых стохастических клеток и '
                  'считает разброс финальных значений — коэффициент '
                  'вариации (CV) показывает, насколько сильно экспрессия '
                  'гена «дрожит» от клетки к клетке в популяции.' if is_ru else
                  'Runs many independent stochastic cells and measures the '
                  'spread of final values — the coefficient of variation '
                  '(CV) shows how much a gene\'s expression "jitters" from '
                  'cell to cell across a population.'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9),
            justify='left', anchor='w', wraplength=380)
        desc.pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(editor, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        tk.Label(ctl, text=('Время, мин:' if is_ru else 'Duration, min:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        tmax_v = tk.StringVar(value='60')
        tk.Entry(ctl, textvariable=tmax_v, width=6, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2, pady=6)
        tk.Label(ctl, text=('Клеток:' if is_ru else 'Cells:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(10, 2))
        runs_v = tk.StringVar(value='20')
        tk.Entry(ctl, textvariable=runs_v, width=5, font=('Arial', 9),
                 relief='solid', bd=1).pack(side='left', padx=2, pady=6)

        def run():
            if not model.get('genes'):
                self._wc_set_info(info, (
                    'Сначала добавьте хотя бы один ген (вкладка «Гены»).'
                    if is_ru else
                    'Add at least one gene first (the "Genes" tab).'), 'wrn')
                return
            try:
                tmax = float(tmax_v.get() or 60)
            except ValueError:
                tmax = 60.0
            try:
                n_runs = max(2, min(100, int(runs_v.get() or 20)))
            except ValueError:
                n_runs = 20
            res = simulate_whole_cell_montecarlo(model, t_max=tmax, n_runs=n_runs)
            if res.get('error'):
                self._wc_set_info(info, res['error'], 'wrn')
                return
            labels = list(res['stats'].keys())
            cv_values = [res['stats'][k]['cv'] * 100 for k in labels]
            self._wc_plot_bars(canvas, labels, cv_values, '{:.0f}%')
            head = ('Разброс по {} клеткам (t={:.0f} мин)\n'
                    .format(res['n_runs'], tmax) if is_ru else
                    'Spread across {} cells (t={:.0f} min)\n'
                    .format(res['n_runs'], tmax))
            body_lines = []
            for k, s in res['stats'].items():
                body_lines.append('  {:<20} μ={:<9} σ={:<9} CV={:.0%}'
                                  .format(k, s['mean'], s['std'], s['cv']))
            tail = ''
            if res.get('truncated_any'):
                tail = ('\n\n⚠ Часть прогонов достигла предела событий.'
                        if is_ru else
                        '\n\n⚠ Some runs hit the event limit.')
            self._wc_set_info(info, head + '\n'.join(body_lines) + tail,
                              'wrn' if res.get('truncated_any') else 'nrm')
            model['last_result'] = res

        tk.Button(editor, text=('▶ Запустить симуляцию' if is_ru
                                else '▶ Run simulation'),
                  bg='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)
        canvas, info = self._wc_build_result_area(editor)

    def _wc_panel_sensitivity(self, editor):
        """Этап 4: скан силы промотора/RBS одного гена → влияние на скорость
        роста (средний период деления)."""
        is_ru = (self.lang == 'ru')
        model = self.current_state.get('organism_wholecell')
        if not isinstance(model, dict):
            return
        desc = tk.Label(
            editor,
            text=('Меняет силу промотора или RBS выбранного гена от 0 до 1 '
                  'и смотрит, как это сказывается на скорости деления '
                  'клетки (при неизменных остальных генах и ресурсах).'
                  if is_ru else
                  "Scans the selected gene's promoter or RBS strength from "
                  '0 to 1 and shows the effect on cell division speed '
                  '(other genes and resources held fixed).'),
            bg=biosim_theme('bg'), fg=biosim_theme('text_dim'), font=('Arial', 9),
            justify='left', anchor='w', wraplength=380)
        desc.pack(fill='x', pady=(0, 8))

        ctl = tk.Frame(editor, bg=biosim_theme('panel'), relief='solid', bd=1)
        ctl.pack(fill='x', pady=4)
        tk.Label(ctl, text=('Ген:' if is_ru else 'Gene:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(8, 2), pady=6)
        gene_ids = list(model.get('genes', {}).keys())
        gene_names = [model['genes'][gid].get('name', gid) for gid in gene_ids]
        gene_v = tk.StringVar(value=gene_names[0] if gene_names else '')
        ttk.Combobox(ctl, textvariable=gene_v, state='readonly', width=12,
                     values=gene_names, font=('Arial', 9)).pack(side='left', padx=2)
        tk.Label(ctl, text=('Параметр:' if is_ru else 'Parameter:'),
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left', padx=(10, 2))
        param_opts = [('promoter_strength', 'Промотор' if is_ru else 'Promoter'),
                     ('rbs_strength', 'RBS')]
        param_labels = [p[1] for p in param_opts]
        param_v = tk.StringVar(value=param_labels[0])
        ttk.Combobox(ctl, textvariable=param_v, state='readonly', width=10,
                     values=param_labels, font=('Arial', 9)).pack(side='left', padx=2)

        def run():
            if not gene_ids:
                self._wc_set_info(info, (
                    'Сначала добавьте хотя бы один ген (вкладка «Гены»).'
                    if is_ru else
                    'Add at least one gene first (the "Genes" tab).'), 'wrn')
                return
            gi = gene_names.index(gene_v.get()) if gene_v.get() in gene_names else 0
            gene_id = gene_ids[gi]
            param_key = 'promoter_strength'
            for k, lbl in param_opts:
                if lbl == param_v.get():
                    param_key = k
                    break
            res = simulate_whole_cell_sensitivity(model, gene_id, param=param_key)
            if res.get('error'):
                self._wc_set_info(info, res['error'], 'wrn')
                return
            xs = [r['value'] for r in res['results']]
            ys_div = [r['n_divisions'] for r in res['results']]
            self._wc_plot_xy(canvas, xs, ys_div,
                             ('Делений за окно' if is_ru else 'Divisions in window'))
            gname = model['genes'][gene_id].get('name', gene_id)
            plabel = dict(param_opts)[param_key]
            head = ('Скан «{}»: {}\n'.format(gname, plabel) if is_ru
                    else 'Scan "{}": {}\n'.format(gname, plabel))
            body_lines = []
            for r in res['results']:
                period_str = ('{:.1f}'.format(r['avg_division_period'])
                              if r['avg_division_period'] is not None else '—')
                body_lines.append(
                    '  {}={:<5} делений={:<3} период≈{}'.format(
                        plabel, r['value'], r['n_divisions'], period_str)
                    if is_ru else
                    '  {}={:<5} divisions={:<3} period≈{}'.format(
                        plabel, r['value'], r['n_divisions'], period_str))
            self._wc_set_info(info, head + '\n'.join(body_lines), 'nrm')
            model['last_result'] = res

        tk.Button(editor, text=('▶ Запустить скан' if is_ru else '▶ Run scan'),
                  bg='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 11, 'bold'), cursor='hand2', pady=8,
                  command=run).pack(fill='x', pady=8)
        canvas, info = self._wc_build_result_area(editor)

    def _wc_plot_bars(self, canvas, labels, values, value_fmt='{:.0f}'):
        """Small vertical bar chart on the whole-cell results canvas — used
        for Monte Carlo's per-gene CV%."""
        c = canvas
        if c is None:
            return
        c.delete('all'); c.update_idletasks()
        W = c.winfo_width() or 290; H = c.winfo_height() or 180
        pad_l, pad_b, pad_t, pad_r = 30, 28, 14, 8
        if not labels:
            return
        vmax = max(values) if values else 1.0
        vmax = vmax if vmax > 1e-9 else 1.0
        plot_w = W - pad_l - pad_r
        plot_h = H - pad_b - pad_t
        colors = ['#0969da', '#1a7f37', '#cf222e', '#8250df', '#9a6700',
                  '#0550ae', '#d1242f', '#116329', '#953800', '#6639ba']
        n = len(labels)
        slot = plot_w / n
        bar_w = max(6, slot * 0.6)
        c.create_line(pad_l, H - pad_b, W - pad_r, H - pad_b, fill='#adbac7', width=1)
        c.create_line(pad_l, pad_t, pad_l, H - pad_b, fill='#adbac7', width=1)
        for i, (lbl, val) in enumerate(zip(labels, values)):
            x0 = pad_l + i * slot + (slot - bar_w) / 2
            x1 = x0 + bar_w
            bar_h = (val / vmax) * plot_h
            y0 = H - pad_b - bar_h
            y1 = H - pad_b
            col = colors[i % len(colors)]
            c.create_rectangle(x0, y0, x1, y1, fill=col, outline='')
            c.create_text((x0 + x1) / 2, y0 - 6, text=value_fmt.format(val),
                          fill='#57606a', font=('Arial', 7))
            c.create_text((x0 + x1) / 2, H - pad_b + 4, text=lbl[:8], anchor='n',
                          fill='#57606a', font=('Arial', 6))

    def _wc_plot_xy(self, canvas, xs, ys, series_label=''):
        """Small connected-scatter plot (parameter scan) on the whole-cell
        results canvas. None values in ys are skipped (not drawn)."""
        c = canvas
        if c is None or not xs:
            return
        c.delete('all'); c.update_idletasks()
        W = c.winfo_width() or 290; H = c.winfo_height() or 180
        pad_l, pad_b, pad_t, pad_r = 34, 20, 14, 8
        clean = [(x, y) for x, y in zip(xs, ys) if y is not None]
        if not clean:
            c.create_text(W / 2, H / 2,
                          text='(no data)', fill='#8b949e', font=('Arial', 8))
            return
        xmin, xmax = min(xs), max(xs)
        xmax = xmax if xmax > xmin else xmin + 1.0
        ymax = max(y for _, y in clean) or 1.0
        plot_w = W - pad_l - pad_r
        plot_h = H - pad_b - pad_t
        for gi in range(5):
            gy = pad_t + plot_h * gi / 4
            c.create_line(pad_l, gy, W - pad_r, gy, fill='#eaeef2')
            val = ymax * (1 - gi / 4)
            c.create_text(pad_l - 3, gy, text='{:.0f}'.format(val), anchor='e',
                          fill='#8b949e', font=('Arial', 6))
        c.create_line(pad_l, H - pad_b, W - pad_r, H - pad_b, fill='#adbac7', width=1)
        c.create_line(pad_l, pad_t, pad_l, H - pad_b, fill='#adbac7', width=1)
        pts = []
        for x, y in clean:
            px = pad_l + ((x - xmin) / (xmax - xmin)) * plot_w
            py = (H - pad_b) - (y / ymax) * plot_h
            pts.append((px, py))
            c.create_oval(px - 3, py - 3, px + 3, py + 3, fill='#0969da', outline='')
        if len(pts) >= 2:
            flat = [v for p in pts for v in p]
            c.create_line(*flat, fill='#0969da', width=2)
        for gi in range(5):
            gx = pad_l + plot_w * gi / 4
            xv = xmin + (xmax - xmin) * gi / 4
            c.create_text(gx, H - pad_b + 3, text='{:.2f}'.format(xv), anchor='n',
                          fill='#8b949e', font=('Arial', 6))
        if series_label:
            c.create_text(pad_l + 4, pad_t + 1, text=series_label, anchor='nw',
                          fill='#57606a', font=('Arial', 7))

    def _wc_open_export_menu(self):
        """Этап 5: экспорт whole-cell модели — CSV генов или Antimony
        (тот же формат, что и экспорт метаболической модели)."""
        is_ru = (self.lang == 'ru')
        menu = tk.Menu(self, tearoff=0)
        menu.add_command(
            label=('CSV генов — файл' if is_ru else 'Genes CSV — file'),
            command=lambda: self._wc_export('csv', to_file=True))
        menu.add_separator()
        menu.add_command(
            label=('Antimony (.txt) — файл' if is_ru else 'Antimony (.txt) — file'),
            command=lambda: self._wc_export('antimony', to_file=True))
        menu.add_command(
            label=('Antimony — просмотр' if is_ru else 'Antimony — preview'),
            command=lambda: self._wc_export('antimony', to_file=False))
        try:
            menu.tk_popup(self.winfo_pointerx(), self.winfo_pointery())
        finally:
            menu.grab_release()

    def _wc_export(self, fmt, to_file=True):
        is_ru = (self.lang == 'ru')
        model = self.current_state.get('organism_wholecell')
        if not isinstance(model, dict) or not model.get('genes'):
            self.toast(('Модель пуста — добавьте гены' if is_ru
                       else 'Model is empty — add genes first'),
                      level='warn', duration=2500)
            return
        if fmt == 'csv':
            text = whole_cell_genes_to_csv(model)
            ext, filetypes = '.csv', [('CSV', '*.csv'), ('All', '*.*')]
        else:
            text = whole_cell_model_to_antimony(model)
            ext, filetypes = '.txt', [('Antimony', '*.txt'), ('All', '*.*')]
        if to_file:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension=ext, filetypes=filetypes,
                initialfile=(model.get('name', 'cell') + ext))
            if path:
                with open(path, 'w', encoding='utf-8') as fh:
                    fh.write(text)
                self.toast(('Сохранено: ' if is_ru else 'Saved: ') + path,
                          level='success', duration=2500)
        else:
            self._metab_show_text_window('Antimony', text)

    def _wc_plot_timecourse(self, canvas, res):
        """Draw a small multi-series line plot on the whole-cell results
        canvas. Same drawing approach as _metab_plot_timecourse, pointed at
        the whole-cell canvas instead."""
        c = canvas
        if c is None or res.get('error'):
            return
        c.delete('all'); c.update_idletasks()
        W = c.winfo_width() or 290; H = c.winfo_height() or 180
        pad_l, pad_b, pad_t, pad_r = 30, 20, 14, 8
        t = res['time']; conc = res['concentrations']; sp = res['species']
        if not t:
            return
        tmax = max(t) or 1.0
        vmax = max((max(conc[s]) for s in sp), default=1.0) or 1.0
        plot_w = W - pad_l - pad_r
        plot_h = H - pad_b - pad_t
        colors = ['#0969da', '#1a7f37', '#cf222e', '#8250df', '#9a6700',
                  '#0550ae', '#d1242f', '#116329', '#953800', '#6639ba']
        for gi in range(5):
            gy = pad_t + plot_h * gi / 4
            c.create_line(pad_l, gy, W - pad_r, gy, fill='#eaeef2')
            val = vmax * (1 - gi / 4)
            c.create_text(pad_l - 3, gy, text='{:.1f}'.format(val), anchor='e',
                          fill='#8b949e', font=('Arial', 6))
        for gi in range(5):
            gx = pad_l + plot_w * gi / 4
            c.create_line(gx, pad_t, gx, H - pad_b, fill='#f2f4f7')
            c.create_text(gx, H - pad_b + 3, text='{:.0f}'.format(tmax * gi / 4),
                          anchor='n', fill='#8b949e', font=('Arial', 6))
        c.create_line(pad_l, H - pad_b, W - pad_r, H - pad_b, fill='#adbac7', width=1)
        c.create_line(pad_l, pad_t, pad_l, H - pad_b, fill='#adbac7', width=1)
        for i, s in enumerate(sp):
            col = colors[i % len(colors)]
            pts = []
            for k in range(len(t)):
                x = pad_l + (t[k] / tmax) * plot_w
                y = (H - pad_b) - (conc[s][k] / vmax) * plot_h
                pts.extend([x, y])
            if len(pts) >= 4:
                c.create_line(*pts, fill=col, width=2, smooth=True)
        lx = pad_l + 4; ly = pad_t + 1
        for i, s in enumerate(sp[:8]):
            col = colors[i % len(colors)]
            c.create_line(lx, ly + 4, lx + 10, ly + 4, fill=col, width=2)
            c.create_text(lx + 13, ly + 4, text=s[:10], anchor='w',
                          fill='#57606a', font=('Arial', 7))
            lx += 66
            if lx > W - 60:
                lx = pad_l + 4; ly += 11

    def _wc_simple_form(self, editor, target_dict, fields):
        """Generic editable form: (key, label) list -> Entry bound to
        target_dict[key], saved on button press."""
        is_ru = (self.lang == 'ru')
        entries = {}
        for key, label in fields:
            row = tk.Frame(editor, bg=biosim_theme('bg'))
            row.pack(fill='x', padx=6, pady=4)
            tk.Label(row, text=label, bg=biosim_theme('bg'),
                     fg=biosim_theme('text'), font=('Arial', 9),
                     width=26, anchor='w').pack(side='left')
            e = tk.Entry(row, font=('Arial', 9))
            e.insert(0, str(target_dict.get(key, '')))
            e.pack(side='left', fill='x', expand=True)
            entries[key] = e

        def do_save():
            for key, e in entries.items():
                raw = e.get().strip()
                old = target_dict.get(key)
                if isinstance(old, (int, float)) and not isinstance(old, bool):
                    try:
                        val = float(raw)
                        raw = int(val) if isinstance(old, int) and val == int(val) else val
                    except ValueError:
                        continue
                target_dict[key] = raw
            self.toast(('Сохранено' if is_ru else 'Saved'),
                       level='success', duration=1500)

        tk.Button(editor, text=('💾 Сохранить' if is_ru else '💾 Save'),
                  bg='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 9, 'bold'), cursor='hand2',
                  command=do_save).pack(anchor='w', padx=6, pady=10)

    def _org_clear_all(self):
        for v in self._org_tasks.values():
            v.set(False)
        self._org_update()

    def _org_build_module_tree(self):
        """Populate the module library as a ttk.Treeview (like the Metabolism
        Model & Tasks list). Categories are collapsible parent rows; each
        module is a child whose text is prefixed ✓ (selected) or ☐ (not).
        Up/Down navigate, Enter/Space toggles a module or opens/closes a
        category, matching the keyboard flow the user asked for."""
        tree = getattr(self, '_org_tree', None)
        if tree is None or not tree.winfo_exists():
            return
        is_ru = (self.lang == 'ru')
        # remember which category rows were open, keyed by category key
        prev_open = {}
        for iid, (kind, key) in getattr(self, '_org_tree_rowmap', {}).items():
            if kind == 'cat' and tree.exists(iid):
                prev_open[key] = tree.item(iid, 'open')
        for row in tree.get_children(''):
            tree.delete(row)
        self._org_tree_rowmap = {}

        query = (self._org_search.get() or '').strip().lower()
        by_cat = modules_by_category()

        for cat_key, cat in ORGANISM_MODULE_CATEGORIES.items():
            items = by_cat.get(cat_key, [])
            if query:
                items = [(k, m) for k, m in items
                         if query in (m['name_ru'] + m['name_en'] + k
                                      + m['desc_ru'] + m['desc_en']).lower()
                         or any(query in g.lower() for g in m['genes'])]
            if not items:
                continue
            n_sel = sum(1 for k, _ in items
                        if k in self._org_tasks and self._org_tasks[k].get())
            cat_name = cat['name_ru'] if is_ru else cat['name_en']
            cat_label = '{}  ({}{})'.format(
                cat_name, len(items),
                '' if not n_sel else (', выбрано {}'.format(n_sel) if is_ru
                                      else ', {} selected'.format(n_sel)))
            open_now = prev_open.get(
                cat_key, self._org_cat_open.get(cat_key, False) or bool(query))
            cat_iid = 'orgcat::' + cat_key
            tree.insert('', 'end', iid=cat_iid, text=cat_label, open=open_now)
            self._org_tree_rowmap[cat_iid] = ('cat', cat_key)
            for mkey, m in items:
                if mkey not in self._org_tasks:
                    self._org_tasks[mkey] = tk.BooleanVar(value=False)
                name = m['name_ru'] if is_ru else m['name_en']
                if m.get('custom'):
                    name += ' *'
                check = '✓' if self._org_tasks[mkey].get() else '☐'
                mod_label = '{}  {}  · {} ген., {:.0%}'.format(
                    check, name, len(m['genes']), m['burden'])
                mod_iid = 'orgmod::' + mkey
                tree.insert(cat_iid, 'end', iid=mod_iid, text=mod_label)
                self._org_tree_rowmap[mod_iid] = ('mod', mkey)

    def _org_tree_on_select(self, _evt=None):
        """Show the selected module's description/warning in the status line
        (cheap feedback without opening anything)."""
        tree = getattr(self, '_org_tree', None)
        if not tree:
            return
        iid = tree.focus()
        info = self._org_tree_rowmap.get(iid)
        if not info or info[0] != 'mod':
            return
        is_ru = (self.lang == 'ru')
        modules, _, _ = get_organism_task_modules()
        m = modules.get(info[1])
        if not m:
            return
        desc = m['desc_ru'] if is_ru else m['desc_en']
        note = (m.get('note_ru') if is_ru else m.get('note_en')) or ''
        status = getattr(self, '_org_status', None)
        if status is not None and status.winfo_exists():
            txt = desc + (('  ⚠ ' + note) if note else '')
            status.config(text=txt[:90], fg=('#9a6700' if note else biosim_theme('text_dim')))

    def _org_tree_activate(self, _evt=None):
        """Enter/Space/double-click: toggle a module's selection, or open/close
        a category."""
        tree = getattr(self, '_org_tree', None)
        if not tree:
            return 'break'
        iid = tree.focus()
        info = self._org_tree_rowmap.get(iid)
        if not info:
            return 'break'
        kind, key = info
        if kind == 'cat':
            tree.item(iid, open=not tree.item(iid, 'open'))
            return 'break'
        # module: flip its BooleanVar, update the ✓/☐ prefix in place, recompute
        var = self._org_tasks.get(key)
        if var is None:
            self._org_tasks[key] = var = tk.BooleanVar(value=False)
        var.set(not var.get())
        cur = tree.item(iid, 'text')
        new = ('✓' + cur[1:]) if var.get() else ('☐' + cur[1:])
        tree.item(iid, text=new)
        self._org_update()
        return 'break'

    def _org_add_custom_dialog(self):
        """Let the user define a module that is not in the library."""
        is_ru = (self.lang == 'ru')
        d = tk.Toplevel(self)
        d.title('Свой модуль' if is_ru else 'Custom module')
        d.geometry('460x430')
        d.configure(bg=biosim_theme('bg'))
        d.transient(self)

        tk.Label(d, text=('Свой модуль организма' if is_ru
                          else 'Custom organism module'),
                 bg=biosim_theme('bg'), fg='#9a6700',
                 font=('Arial', 13, 'bold')).pack(pady=(10, 2))
        tk.Label(d, text=('Задайте всё вручную — модуль будет считаться '
                          'наравне со встроенными' if is_ru else
                          'Define it by hand — it is treated exactly like a '
                          'built-in module'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 9), wraplength=420).pack(pady=(0, 8))

        fields = {}
        for key, lbl, default in [
                ('name', 'Название' if is_ru else 'Name', ''),
                ('genes', 'Гены через запятую' if is_ru else 'Genes, comma-separated', ''),
                ('desc', 'Описание' if is_ru else 'Description', '')]:
            row = tk.Frame(d, bg=biosim_theme('bg'))
            row.pack(fill='x', padx=16, pady=3)
            tk.Label(row, text=lbl, bg=biosim_theme('bg'),
                     fg=biosim_theme('text'), font=('Arial', 9),
                     width=22, anchor='w').pack(side='left')
            e = tk.Entry(row, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                         font=('Arial', 9), relief='solid', bd=1)
            e.insert(0, default)
            e.pack(side='left', fill='x', expand=True)
            fields[key] = e

        row = tk.Frame(d, bg=biosim_theme('bg'))
        row.pack(fill='x', padx=16, pady=3)
        tk.Label(row, text=('Категория' if is_ru else 'Category'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text'),
                 font=('Arial', 9), width=22, anchor='w').pack(side='left')
        cat_keys = list(ORGANISM_MODULE_CATEGORIES.keys())
        cat_names = [ORGANISM_MODULE_CATEGORIES[c]['name_ru' if is_ru else 'name_en']
                     for c in cat_keys]
        cat_cb = ttk.Combobox(row, values=cat_names, state='readonly',
                              font=('Arial', 9))
        cat_cb.current(cat_keys.index('custom'))
        cat_cb.pack(side='left', fill='x', expand=True)

        brow = tk.Frame(d, bg=biosim_theme('bg'))
        brow.pack(fill='x', padx=16, pady=6)
        tk.Label(brow, text=('Нагрузка на клетку' if is_ru else 'Burden on the cell'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text'),
                 font=('Arial', 9), width=22, anchor='w').pack(side='left')
        burden = tk.DoubleVar(value=0.15)
        tk.Scale(brow, from_=0.01, to=0.6, resolution=0.01, orient='horizontal',
                 variable=burden, bg=biosim_theme('bg'), fg=biosim_theme('text'),
                 highlightthickness=0, troughcolor=biosim_theme('panel2')
                 ).pack(side='left', fill='x', expand=True)

        tk.Label(d, text=('Дополнительно (необязательно): что модуль даёт '
                          'другим и с чем конфликтует' if is_ru else
                          'Optional: what it provides to others, what it conflicts with'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 8, 'italic'), wraplength=420).pack(pady=(4, 0))
        for key, lbl in [('provides', 'Даёт (ключи через запятую)' if is_ru
                          else 'Provides (keys, comma-separated)'),
                         ('requires', 'Требует' if is_ru else 'Requires'),
                         ('conflicts', 'Конфликтует с' if is_ru else 'Conflicts with')]:
            row = tk.Frame(d, bg=biosim_theme('bg'))
            row.pack(fill='x', padx=16, pady=2)
            tk.Label(row, text=lbl, bg=biosim_theme('bg'),
                     fg=biosim_theme('text_dim'), font=('Arial', 8),
                     width=26, anchor='w').pack(side='left')
            e = tk.Entry(row, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                         font=('Arial', 9), relief='solid', bd=1)
            e.pack(side='left', fill='x', expand=True)
            fields[key] = e

        err = tk.Label(d, text='', bg=biosim_theme('bg'), fg='#cf222e',
                       font=('Arial', 9), wraplength=420)
        err.pack(pady=(4, 0))

        def save():
            name = fields['name'].get().strip()
            genes = [g.strip() for g in fields['genes'].get().split(',') if g.strip()]
            if not name:
                err.config(text=('Введите название' if is_ru else 'Enter a name'))
                return
            if not genes:
                err.config(text=('Укажите хотя бы один ген' if is_ru
                                 else 'List at least one gene'))
                return
            ci = cat_cb.current()
            cat = cat_keys[ci] if ci >= 0 else 'custom'
            key = name.lower().replace(' ', '_')[:30]
            try:
                add_custom_organism_module(
                    key, name, name, genes, burden.get(),
                    fields['desc'].get().strip(), fields['desc'].get().strip(),
                    category=cat,
                    requires=[x.strip() for x in fields['requires'].get().split(',') if x.strip()],
                    conflicts=[x.strip() for x in fields['conflicts'].get().split(',') if x.strip()],
                    provides=[x.strip() for x in fields['provides'].get().split(',') if x.strip()])
            except Exception as exc:
                biosim_log('error', 'custom module: {}'.format(exc))
                err.config(text=str(exc))
                return
            self._org_cat_open[cat] = True
            self._org_build_module_tree()
            self._org_update()
            d.destroy()

        tk.Button(d, text=('Добавить' if is_ru else 'Add'), bg='#1a7f37',
                  highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 10, 'bold'), cursor='hand2', padx=16,
                  command=save).pack(pady=8)

    def _org_update(self):
        """Recompute the design and refresh every results page.

        Guarded against a stale, already-scheduled `after()` callback firing
        after the tab was rebuilt or closed (widgets destroyed) — bail out
        quietly instead of raising a TclError from a background callback the
        user never sees a report from.
        """
        status_w = getattr(self, '_org_status', None)
        if status_w is None or not status_w.winfo_exists():
            return
        is_ru = (self.lang == 'ru')
        chassis = self._org_chassis.get()
        tasks = [k for k, v in self._org_tasks.items() if v.get()]
        removed = [c for c, v in self._org_removed_cats.items() if v.get()] \
            if self._org_removed_cats else []
        design = design_synthetic_organism(chassis, tasks, removed)
        self._org_last_design = design
        if design.get('error'):
            self._org_status.config(text=design['error'], fg='#cf222e')
            return

        cd = ORGANISM_CHASSIS.get(chassis, {})
        traits = cd.get('traits', {})
        self._org_chassis_info.config(
            text='{}\n{} генов · {} кб · секреция: {} · гликозилирование: {} · {}'
            .format(cd.get('notes_ru' if is_ru else 'notes_en', ''),
                    cd.get('base_genes', 0), cd.get('genome_kb', 0),
                    traits.get('secretion', '—'),
                    'да' if traits.get('glycosylation') else 'нет',
                    traits.get('temp_range', '')))

        if design['viable']:
            worst = max(design['load'].values()) if design['load'] else 0
            if worst > 0.8:
                self._org_status.config(
                    text=('⚠ Жизнеспособен, но на пределе' if is_ru
                          else '⚠ Viable, but at the limit'), fg='#bc4c00')
            else:
                self._org_status.config(
                    text=('✓ Организм жизнеспособен' if is_ru
                          else '✓ Organism is viable'), fg='#1a7f37')
        else:
            self._org_status.config(
                text=('✗ Организм НЕ выживет' if is_ru
                      else '✗ Organism will NOT survive'), fg='#cf222e')

        self._org_build_module_tree()
        self._org_fill_overview(design)
        self._org_draw_resources(design)
        self._org_draw_growth(design)
        self._org_fill_genome(design)
        self._org_fill_fba(design)
        self._org_fill_advice(design)

    def _org_page(self, key):
        page = self._org_pages[key]
        for w in page.winfo_children():
            w.destroy()
        return page

    def _org_fill_overview(self, design):
        is_ru = (self.lang == 'ru')
        page = self._org_page('overview')
        txt = scrolledtext.ScrolledText(page, bg=biosim_theme('panel'),
                                        fg=biosim_theme('text'),
                                        font=('Arial', 9), relief='flat',
                                        state='normal')
        txt.pack(fill='both', expand=True, padx=4, pady=4)
        txt.tag_config('h', foreground='#1a7f37', font=('Arial', 11, 'bold'))
        txt.tag_config('w', foreground='#cf222e', font=('Arial', 9, 'bold'))
        txt.tag_config('g', foreground='#1a7f37', font=('Arial', 9))
        txt.tag_config('dim', foreground='#57606a', font=('Arial', 9))

        txt.insert('end', (design['chassis_ru'] if is_ru else design['chassis'])
                   + '\n', 'h')
        txt.insert('end', 'Генов всего: {} (эссенциальных {} + задачи {})\n'
                   .format(design['total_genes'], design['essential_genes'],
                           design['task_genes']))
        txt.insert('end', 'Нагрузка: {:.0%} · скорость роста: {}\n'
                   .format(design['burden'], design['growth_rate']))
        txt.insert('end', 'Биобезопасность: {}\n'.format(design['containment_ru']),
                   'g' if design['containment_layers'] >= 2 else 'w')

        if design['tasks']:
            txt.insert('end', '\nМодули ({}):\n'.format(len(design['tasks'])), 'h')
            by_cat = {}
            for m in design['tasks']:
                by_cat.setdefault(m.get('category', 'custom'), []).append(m)
            for cat_key, mods in by_cat.items():
                cat = ORGANISM_MODULE_CATEGORIES.get(cat_key, {})
                txt.insert('end', '  {}\n'.format(
                    cat.get('name_ru' if is_ru else 'name_en', cat_key)), 'dim')
                for m in mods:
                    txt.insert('end', '    • {} — {} ген., {:.0%}\n'.format(
                        m['name_ru'] if is_ru else m['name_en'],
                        len(m['genes']), m['burden']))
        else:
            txt.insert('end', '\nМодули не выбраны — слева отметьте нужные.\n'
                       if is_ru else
                       '\nNo modules selected — tick some on the left.\n', 'dim')

        if design['synergies']:
            txt.insert('end', '\nСинергии:\n', 'h')
            for s in design['synergies']:
                txt.insert('end', '  ✓ ' + s + '\n', 'g')
        if design['warnings']:
            txt.insert('end', '\nПроблемы:\n', 'h')
            for w in design['warnings']:
                txt.insert('end', '  ⚠ ' + w + '\n', 'w')
        txt.config(state='disabled')

    def _org_draw_resources(self, design):
        """Which pool is actually limiting — the question a designer asks."""
        is_ru = (self.lang == 'ru')
        page = self._org_page('resources')
        try:
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            fig, ax = new_biosim_figure(figsize=(6.4, 3.4))
            keys = list(design['load'].keys())
            labels = [RESOURCE_LABELS[k][0 if is_ru else 1] for k in keys]
            vals = [design['load'][k] * 100 for k in keys]
            colours = ['#cf222e' if v > 100 else '#bc4c00' if v > 80
                       else '#1a7f37' for v in vals]
            ypos = list(range(len(keys)))
            ax.barh(ypos, vals, color=colours, height=0.55)
            ax.axvline(100, color='#cf222e', lw=1.2, ls='--')
            ax.set_yticks(ypos)
            ax.set_yticklabels(labels, fontsize=9)
            ax.invert_yaxis()
            ax.set_xlim(0, max(130, max(vals) * 1.1 if vals else 130))
            for y, v in zip(ypos, vals):
                ax.text(v + 2, y, '{:.0f}%'.format(v), va='center', fontsize=8,
                        color='#1c2128')
            style_biosim_axes(
                ax, title=('Использование ресурсов клетки' if is_ru
                           else 'Cell resource usage'),
                xlabel=('% от доступного (100% = предел)' if is_ru
                        else '% of what is available (100% = limit)'),
                ylabel='')
            fig.tight_layout()
            c = FigureCanvasTkAgg(fig, master=page)
            c.draw()
            c.get_tk_widget().pack(fill='both', expand=True)
            self._org_chart_canvas['res'] = c
        except Exception as exc:
            biosim_log('warn', '_org_draw_resources: {}'.format(exc))
            tk.Label(page, text=str(exc), bg=biosim_theme('bg'),
                     fg='#cf222e').pack()

    def _org_draw_growth(self, design):
        is_ru = (self.lang == 'ru')
        page = self._org_page('growth')
        try:
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            traj = simulate_organism_growth(design, hours=24)
            prod = organism_production_forecast(design, hours=24)
            fig, ax = new_biosim_figure(figsize=(6.4, 3.4))
            ts = [p[0] for p in traj]
            pop = [p[1] for p in traj]
            colour = '#1a7f37' if design.get('viable') else '#cf222e'
            ax.plot(ts, pop, color=colour, linewidth=2,
                    label=('Плотность клеток' if is_ru else 'Cell density'))
            ax.fill_between(ts, pop, 0, color=colour, alpha=0.15)
            pv = [p[1] for p in prod]
            if max(pv) > 0:
                ax2 = ax.twinx()
                ax2.plot([p[0] for p in prod], pv, color='#8250df',
                         linewidth=2, ls='--',
                         label=('Продукт' if is_ru else 'Product'))
                ax2.set_ylabel(('Продукт, усл. ед.' if is_ru
                                else 'Product, a.u.'), color='#8250df')
                ax2.tick_params(axis='y', colors='#8250df')
            style_biosim_axes(
                ax, title=('Рост популяции и накопление продукта' if is_ru
                           else 'Population growth and product accumulation'),
                xlabel=('Часы' if is_ru else 'Hours'),
                ylabel=('Плотность' if is_ru else 'Density'))
            ax.legend(loc='upper left', fontsize=8)
            fig.tight_layout()
            c = FigureCanvasTkAgg(fig, master=page)
            c.draw()
            c.get_tk_widget().pack(fill='both', expand=True)
            self._org_chart_canvas['growth'] = c
        except Exception as exc:
            biosim_log('warn', '_org_draw_growth: {}'.format(exc))
            tk.Label(page, text=str(exc), bg=biosim_theme('bg'),
                     fg='#cf222e').pack()

    def _org_fill_genome(self, design):
        """Essential systems plus every gene the design pulls in."""
        is_ru = (self.lang == 'ru')
        page = self._org_page('genome')
        txt = scrolledtext.ScrolledText(page, bg=biosim_theme('panel'),
                                        fg=biosim_theme('text'),
                                        font=('Courier', 9), relief='flat')
        txt.pack(fill='both', expand=True, padx=4, pady=4)
        txt.tag_config('h', foreground='#0969da', font=('Arial', 10, 'bold'))
        txt.tag_config('dim', foreground='#57606a', font=('Arial', 8))
        txt.insert('end', ('Эссенциальные системы (без них клетка не живёт)\n'
                           if is_ru else
                           'Essential systems (the cell dies without these)\n'), 'h')
        for ck, cat in MINIMAL_GENE_CATEGORIES.items():
            txt.insert('end', '\n{} — {} ген.\n'.format(
                cat['name_ru'] if is_ru else cat['name_en'], len(cat['genes'])))
            why = cat.get('why_ru' if is_ru else 'why_en', '')
            if why:
                txt.insert('end', '  {}\n'.format(why), 'dim')
            txt.insert('end', '  ' + ', '.join(cat['genes'][:14])
                       + ('...' if len(cat['genes']) > 14 else '') + '\n')
        if design['tasks']:
            txt.insert('end', ('\n\nГены добавленных модулей\n' if is_ru
                               else '\n\nGenes from added modules\n'), 'h')
            for m in design['tasks']:
                txt.insert('end', '\n{}\n  {}\n'.format(
                    m['name_ru'] if is_ru else m['name_en'],
                    ', '.join(m['genes'])))
        txt.config(state='disabled')

    def _org_fill_fba(self, design):
        """Constraint-based analysis of the designed organism.

        The resource model on the other tabs answers "does this fit in the
        cell". This one answers a different question: given real stoichiometry,
        what flux can the network actually sustain, what limits it, and how
        much product can be pushed out before growth collapses.
        """
        is_ru = (self.lang == 'ru')
        page = self._org_page('fba')

        top = tk.Frame(page, bg=biosim_theme('bg'))
        top.pack(fill='x', padx=6, pady=(6, 2))
        tk.Label(top, text=('Анализ баланса потоков (FBA)' if is_ru
                            else 'Flux balance analysis'),
                 bg=biosim_theme('bg'), fg='#0969da',
                 font=('Arial', 12, 'bold')).pack(anchor='w')
        tk.Label(top, text=('Здесь работает настоящая стехиометрия: 30+ реакций '
                            'гликолиза, пентозофосфатного пути, цикла Кребса, '
                            'дыхания и брожения. Модель сокращённая, не '
                            'полногеномная — результаты читайте как порядок '
                            'величины, а не как предсказание.' if is_ru else
                            'Real stoichiometry here: 30+ reactions covering '
                            'glycolysis, pentose phosphate, TCA, respiration and '
                            'fermentation. This is a reduced core model, not a '
                            'genome-scale one — read the numbers as an order of '
                            'magnitude, not a prediction.'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                 font=('Arial', 9), wraplength=560,
                 justify='left').pack(anchor='w', pady=(2, 4))

        ctl = tk.Frame(page, bg=biosim_theme('bg'))
        ctl.pack(fill='x', padx=6, pady=2)
        if not hasattr(self, '_org_fba_aerobic'):
            self._org_fba_aerobic = tk.BooleanVar(value=True)
            self._org_fba_uptake = tk.StringVar(value='10')
        tk.Label(ctl, text=('Глюкоза, ммоль/гСВ/ч:' if is_ru
                            else 'Glucose, mmol/gDW/h:'),
                 bg=biosim_theme('bg'), fg=biosim_theme('text'),
                 font=('Arial', 9)).pack(side='left')
        tk.Entry(ctl, textvariable=self._org_fba_uptake, width=6,
                 bg=biosim_theme('panel'), fg=biosim_theme('text'),
                 relief='solid', bd=1).pack(side='left', padx=4)
        tk.Checkbutton(ctl, text=('с кислородом' if is_ru else 'aerobic'),
                       variable=self._org_fba_aerobic, bg=biosim_theme('bg'),
                       fg=biosim_theme('text'), selectcolor=biosim_theme('panel2'),
                       font=('Arial', 9)).pack(side='left', padx=8)

        out = scrolledtext.ScrolledText(page, bg=biosim_theme('panel'),
                                        fg=biosim_theme('text'),
                                        font=('Courier', 9), relief='flat')
        out.pack(fill='both', expand=True, padx=6, pady=6)
        out.tag_config('h', foreground='#0969da', font=('Arial', 10, 'bold'))
        out.tag_config('ok', foreground='#1a7f37')
        out.tag_config('bad', foreground='#cf222e')
        out.tag_config('warn', foreground='#bc4c00')
        out.tag_config('dim', foreground='#57606a', font=('Arial', 8))

        def run_fba():
            out.config(state='normal')
            out.delete('1.0', 'end')
            if not _ensure_cobra():
                out.insert('end', ('Библиотека cobra не установлена.\n\n' if is_ru
                                   else 'The cobra library is not installed.\n\n'), 'bad')
                out.insert('end', ('Установите её в Терминале:\n'
                                   '    pip3 install cobra\n\n'
                                   'Остальные вкладки работают и без неё.\n'
                                   if is_ru else
                                   'Install it in a terminal:\n'
                                   '    pip3 install cobra\n\n'
                                   'The other tabs work without it.\n'))
                out.config(state='disabled')
                return
            try:
                uptake = float(self._org_fba_uptake.get())
            except Exception as exc:
                biosim_log('warn', 'fba uptake: {}'.format(exc))
                uptake = 10.0
            model, info = build_cobra_model_from_organism(
                design, substrate_uptake=uptake,
                aerobic=self._org_fba_aerobic.get())
            if model is None:
                out.insert('end', str(info.get('error', 'ошибка')) + '\n', 'bad')
                out.config(state='disabled')
                return

            out.insert('end', ('Сеть: {} реакций, {} метаболитов\n'
                               .format(info['reactions'], info['metabolites'])), 'h')
            out.insert('end', ('Шасси: {} · глюкоза {:.1f} · кислород {:.1f}\n'
                               'Поддержание жизни: {} ммоль АТФ/гСВ/ч'
                               .format(info['chassis'], info['uptake'],
                                       info['o2_max'], info['maintenance'])))
            if info['module_atp_drain']:
                out.insert('end', ' + {} на немета­болические модули'
                           .format(info['module_atp_drain']))
            out.insert('end', '\n\n')

            sol = model.optimize()
            if sol.status != 'optimal':
                out.insert('end', ('Решения нет (статус {}). Обычно это значит, '
                                   'что клетке не хватает энергии на поддержание '
                                   'жизни при такой нагрузке.\n'
                                   .format(sol.status)), 'bad')
                out.config(state='disabled')
                return
            growth = sol.objective_value
            dt = (0.693 / growth) if growth > 1e-6 else None
            out.insert('end', ('Рост: {:.3f} 1/ч'.format(growth)), 'h')
            if dt:
                out.insert('end', '   (удвоение за {:.1f} ч)'.format(dt))
            out.insert('end', '\n', 'ok' if growth > 0.1 else 'bad')
            if growth < 1e-6:
                out.insert('end', ('Клетка не растёт: весь бюджет уходит на '
                                   'поддержание и модули.\n' if is_ru else
                                   'No growth: the entire budget goes to '
                                   'maintenance and modules.\n'), 'bad')

            # ── where the carbon goes ──────────────────────────────
            out.insert('end', ('\nКуда уходит углерод\n' if is_ru
                               else '\nWhere the carbon goes\n'), 'h')
            for rid in ['EX_biomass', 'EX_co2', 'EX_ac', 'EX_etoh', 'EX_lac',
                        'EX_for'] + info['product_reactions']:
                try:
                    f = sol.fluxes[rid]
                except Exception as exc:
                    # reaction absent from this design - expected, not a failure
                    biosim_log('info', 'flux lookup {}: {}'.format(rid, exc))
                    continue
                if abs(f) > 1e-4:
                    nm = model.reactions.get_by_id(rid).name
                    out.insert('end', '  {:<26} {:8.3f}\n'.format(nm[:26], f))

            # ── what is limiting ───────────────────────────────────
            out.insert('end', ('\nЧто ограничивает\n' if is_ru
                               else '\nWhat is limiting\n'), 'h')
            limits = []
            for r in model.reactions:
                f = sol.fluxes[r.id]
                if r.upper_bound < 999 and abs(f - r.upper_bound) < 1e-6 and abs(f) > 1e-6:
                    limits.append((r.name, f, 'верхний предел'))
                elif r.lower_bound > 0 and abs(f - r.lower_bound) < 1e-6:
                    limits.append((r.name, f, 'обязательный минимум'))
            if limits:
                for nm, f, kind in limits[:8]:
                    out.insert('end', '  {:<26} {:7.2f}  {}\n'
                               .format(nm[:26], f, kind), 'warn')
            else:
                out.insert('end', ('  Явных упоров нет\n' if is_ru
                                   else '  Nothing is pinned\n'), 'dim')

            # ── essential reactions ────────────────────────────────
            try:
                ess = find_essential_reactions(model, threshold=0.01)
            except Exception as exc:
                biosim_log('warn', 'find_essential_reactions: {}'.format(exc))
                ess = None
            if ess and ess.get('n_tested'):
                names = ess['essential']
                out.insert('end', ('\nНезаменимые реакции: {} из {}\n'
                                   .format(len(names), ess['n_tested'])
                                   if is_ru else
                                   '\nEssential reactions: {} of {}\n'
                                   .format(len(names), ess['n_tested'])), 'h')
                if names:
                    out.insert('end', ('  Выключение любой останавливает рост:\n'
                                       if is_ru else
                                       '  Knocking out any of these stops growth:\n'),
                               'dim')
                    for rid, nm in names[:10]:
                        out.insert('end', '  {:<12} {}\n'.format(rid, nm[:40]), 'bad')
                    if len(names) > 10:
                        out.insert('end', '  ... и ещё {}\n'.format(len(names) - 10),
                                   'dim')
                if ess.get('reduced'):
                    out.insert('end', ('\n  Сильно замедляют рост (но не убивают):\n'
                                       if is_ru else
                                       '\n  Slow growth badly without killing:\n'),
                               'dim')
                    for rid, nm, pct in ess['reduced'][:6]:
                        out.insert('end', '  {:<12} {:<34} {}% от нормы\n'
                                   .format(rid, nm[:34], pct), 'warn')

            # ── production envelope ────────────────────────────────
            prods = info['product_reactions']
            if prods and growth > 1e-6:
                out.insert('end', ('\nСколько продукта можно снять\n' if is_ru
                                   else '\nHow much product is available\n'), 'h')
                out.insert('end', ('  Чем больше продукта, тем медленнее рост — '
                                   'это и есть главный компромисс биотехнологии.\n'
                                   if is_ru else
                                   '  More product means slower growth — the '
                                   'central trade-off of bioprocessing.\n'), 'dim')
                for ex in prods:
                    try:
                        nm = model.reactions.get_by_id(ex).name
                    except Exception as exc:
                        biosim_log('info', 'name lookup {}: {}'.format(ex, exc))
                        nm = ex
                    out.insert('end', '  {}\n'.format(nm))
                    for frac in (0.0, 0.5, 0.8):
                        try:
                            with model as t:
                                t.reactions.get_by_id('EX_biomass').lower_bound = \
                                    growth * frac
                                t.objective = ex
                                v = t.slim_optimize()
                        except Exception as exc:
                            biosim_log('warn', 'envelope: {}'.format(exc))
                            v = None
                        out.insert('end', '     рост {:3.0f}% от максимума  →  '
                                   'продукт {:.2f}\n'.format(frac * 100, v or 0))

            # ── flux variability: how rigid is the design ──────────
            try:
                fva = run_flux_variability_analysis(model, fraction_of_optimum=0.95)
            except Exception as exc:
                biosim_log('warn', 'FVA: {}'.format(exc))
                fva = None
            if fva is not None:
                rigid, flexible = 0, 0
                try:
                    for rid in fva.index:
                        span = float(fva.loc[rid, 'maximum']) - float(fva.loc[rid, 'minimum'])
                        if span < 1e-6:
                            rigid += 1
                        elif span > 1.0:
                            flexible += 1
                    out.insert('end', ('\nЗапас прочности\n' if is_ru
                                       else '\nFlexibility\n'), 'h')
                    out.insert('end', ('  Жёстко заданных реакций: {} · '
                                       'с запасом: {}\n'.format(rigid, flexible)))
                    out.insert('end', ('  Чем больше жёстких, тем хрупче схема: '
                                       'любое отклонение сразу бьёт по росту.\n'
                                       if is_ru else
                                       '  The more rigid reactions, the more '
                                       'brittle the design.\n'), 'dim')
                except Exception as exc:
                    biosim_log('warn', 'FVA summary: {}'.format(exc))

            out.insert('end', ('\n\nМодель сокращённая. Для количественных выводов '
                               'нужна полногеномная модель — кнопка ниже скачает '
                               'её с BiGG.\n' if is_ru else
                               '\n\nReduced model. For quantitative claims use a '
                               'genome-scale model — the button below downloads '
                               'one from BiGG.\n'), 'dim')
            out.config(state='disabled')

        def get_bigg():
            out.config(state='normal')
            out.insert('end', ('\nЗагрузка модели с BiGG...\n' if is_ru
                               else '\nDownloading from BiGG...\n'))
            out.config(state='disabled')
            out.update()

            def worker():
                model, msg = download_bigg_model('e_coli_core')
                def done():
                    out.config(state='normal')
                    if model is None:
                        out.insert('end', '  {}\n'.format(msg), 'bad')
                    else:
                        out.insert('end', '  e_coli_core {} — {} реакций, '
                                   '{} метаболитов, {} генов\n'.format(
                                       msg, len(model.reactions),
                                       len(model.metabolites), len(model.genes)), 'ok')
                        try:
                            g = model.slim_optimize()
                            out.insert('end', '  Рост по опубликованной модели: '
                                       '{:.3f} 1/ч\n'.format(g or 0), 'ok')
                            out.insert('end', ('  Сравните с числом выше — так '
                                               'видно, насколько сокращённая сеть '
                                               'огрубляет ответ.\n' if is_ru else
                                               '  Compare with the figure above.\n'),
                                       'dim')
                        except Exception as exc:
                            biosim_log('warn', 'bigg optimize: {}'.format(exc))
                    out.config(state='disabled')
                try:
                    self.after(0, done)
                except Exception as exc:
                    biosim_log('warn', 'bigg callback: {}'.format(exc))

            threading.Thread(target=worker, daemon=True).start()

        brow = tk.Frame(page, bg=biosim_theme('bg'))
        brow.pack(fill='x', padx=6, pady=(0, 6))
        tk.Button(brow, text=('▶ Рассчитать потоки' if is_ru
                              else '▶ Run FBA'), bg='#1a7f37',
                  highlightbackground='#1a7f37', fg='white', relief='flat',
                  font=('Arial', 10, 'bold'), cursor='hand2', padx=12,
                  command=run_fba).pack(side='left')
        tk.Button(brow, text=('Скачать полногеномную модель' if is_ru
                              else 'Download genome-scale model'),
                  bg=biosim_theme('panel'), highlightbackground='#8250df',
                  fg='#8250df', relief='solid', bd=1, font=('Arial', 9),
                  cursor='hand2', command=get_bigg).pack(side='left', padx=6)

    def _org_fill_advice(self, design):
        is_ru = (self.lang == 'ru')
        page = self._org_page('advice')
        tips = suggest_organism_fixes(design, 'ru' if is_ru else 'en')
        txt = scrolledtext.ScrolledText(page, bg=biosim_theme('panel'),
                                        fg=biosim_theme('text'),
                                        font=('Arial', 10), relief='flat')
        txt.pack(fill='both', expand=True, padx=4, pady=4)
        txt.tag_config('h', foreground='#0969da', font=('Arial', 11, 'bold'))
        txt.tag_config('ok', foreground='#1a7f37', font=('Arial', 10))
        if not tips:
            txt.insert('end', ('Конструкция сбалансирована — критических '
                               'замечаний нет.\n' if is_ru else
                               'The design is balanced — nothing critical.\n'), 'ok')
        else:
            txt.insert('end', ('Что стоит изменить\n\n' if is_ru
                               else 'What to change\n\n'), 'h')
            for t in tips:
                txt.insert('end', '• ' + t + '\n\n')
        txt.config(state='disabled')


    # ── CRISPR TAB ──
    def _build_crispr_tab(self):
        f = tk.Frame(self.content, bg=biosim_theme('bg'))
        self.current_state['crispr'] = {
            'name': 'Empty', 'sequence': '', 'info': {},
            'enzyme': 'SpCas9', 'targets': [], 'selected_target': None, 'edits': [],
            'organism': 'human',
        }
        left = tk.Frame(f, bg=biosim_theme('bg'), width=320)
        left.pack(side='left', fill='y', padx=(0, 4)); left.pack_propagate(False)

        # ── Transfer/Sync hub (CRISPR ↔ all sections) ──
        lb = self._make_transfer_hub(left, 'crispr')
        if lb:
            lb.pack(fill='x', pady=(0, 4))

        # ── Organism selector (affects CRISPR behavior: genome, best Cas,
        #    HDR/NHEJ efficiency, delivery) ──
        org_frame = tk.LabelFrame(left, text=('Организм' if self.lang == 'ru' else 'Organism'),
                                   bg=biosim_theme('panel'), fg='#0969da',
                                   font=('Arial', 11, 'bold'), relief='flat')
        org_frame.pack(fill='x', pady=(0, 4))
        self.crispr_organism = tk.StringVar(value='human')
        org_names = {k: (v['name_ru'] if self.lang == 'ru' else v['name_en'])
                     for k, v in ORGANISMS.items()}
        self.crispr_org_combo = ttk.Combobox(org_frame,
                                               values=[org_names[k] for k in ORGANISMS.keys()],
                                               state='readonly', font=('Arial', 10))
        self.crispr_org_combo.pack(fill='x', padx=4, pady=4)
        self.crispr_org_combo.current(0)
        self._crispr_org_keys = list(ORGANISMS.keys())
        self.crispr_org_combo.bind('<<ComboboxSelected>>',
                                    lambda e: self._crispr_organism_changed())
        self.crispr_org_info = tk.Label(org_frame, text='', bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                                         font=('Arial', 8), wraplength=290, justify='left')
        self.crispr_org_info.pack(anchor='w', padx=4, pady=(0, 4))
        tk.Button(org_frame, text=('Профиль организма' if self.lang == 'ru'
                                    else 'Organism profile'),
                   bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                   relief='solid', bd=1, font=('Arial', 9, 'bold'), cursor='hand2',
                   pady=3, command=self._crispr_show_organism_profile).pack(fill='x', padx=4, pady=(0, 4))

        input_frame = tk.LabelFrame(left, text=self._t('load_gene'), bg=biosim_theme('panel'),
                                      fg='#cf222e', font=('Arial', 11, 'bold'), relief='flat')
        input_frame.pack(fill='x', pady=(0, 4))
        tk.Label(input_frame, text=self._t('gene_input_lbl'),
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9)).pack(anchor='w', padx=4, pady=(4, 0))
        self.crispr_gene_name = tk.StringVar(value='BRCA1')
        tk.Entry(input_frame, textvariable=self.crispr_gene_name,
                  bg=biosim_theme('panel2'), fg=biosim_theme('text'), insertbackground='#1c2128',
                  relief='flat', font=('Arial', 10),
                  highlightthickness=1, highlightbackground=biosim_theme('border')
                  ).pack(fill='x', padx=4, pady=2, ipady=3)
        tk.Button(input_frame, text=self._t('fetch_ncbi'), bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                   relief='solid', bd=1, font=('Arial', 10, 'bold'), cursor='hand2',
                   pady=4, command=self._crispr_fetch_gene).pack(fill='x', padx=4, pady=2)
        tk.Label(input_frame, text=self._t('paste_seq_lbl'),
                  bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9)).pack(anchor='w', padx=4, pady=(8, 0))
        self.crispr_seq_input = tk.Text(input_frame, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                                          insertbackground='#1c2128', relief='flat',
                                          font=('Courier', 9), height=4,
                                          highlightthickness=1, highlightbackground=biosim_theme('border'),
                                          wrap='word')
        self.crispr_seq_input.pack(fill='x', padx=4, pady=2)
        tk.Button(input_frame, text=self._t('use_seq'), bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                   relief='flat', font=('Arial', 10, 'bold'), cursor='hand2',
                   pady=4, command=self._crispr_use_pasted_seq).pack(fill='x', padx=4, pady=2)

