        def _center_wheel(e):
            try:
                delta = -1 * int(e.delta / 120) if e.delta else 0
                if delta == 0 and getattr(e, 'num', None) in (4, 5):
                    delta = -1 if e.num == 4 else 1
                center_canvas.yview_scroll(delta, 'units')
            except Exception:
                pass
        center_canvas.bind('<MouseWheel>', _center_wheel)
        center_canvas.bind('<Button-4>', _center_wheel)
        center_canvas.bind('<Button-5>', _center_wheel)
