    def _set_seq_view(self, segments):
        self.crispr_seq_view.config(state='normal')
        self.crispr_seq_view.delete('1.0', 'end')
        for txt, tag in segments:
            self.crispr_seq_view.insert('end', txt, tag)
        self.crispr_seq_view.config(state='disabled')

    def _crispr_enzyme_changed(self):
        enz = self.crispr_enzyme.get()
        if enz in CRISPR_ENZYMES:
            self.crispr_enz_desc.config(text=CRISPR_ENZYMES[enz]['description'])
            self.current_state['crispr']['enzyme'] = enz

    def _crispr_fetch_gene(self):
        gene = self.crispr_gene_name.get().strip()
        if not gene:
            return
        self._set_text(self.crispr_info, [(self._t('fetching').format(gene) + '\n', 'wrn')])
        self.update()
        def worker():
            seq, info = fetch_gene_sequence_ncbi(gene)
            def done():
                if not seq:
                    self._set_text(self.crispr_info, [
                        (self._t('fetch_failed').format(gene) + '\n', 'bad'),
                        (self._t('try_paste') + '\n', 'dim')])
                    return
                self._save_history('crispr')
                self.current_state['crispr'] = {
                    'name': gene, 'sequence': seq, 'original': seq,
                    'info': info or {}, 'enzyme': self.crispr_enzyme.get(),
                    'targets': [], 'selected_target': None, 'edits': [],
                }
                self._crispr_refresh()
                self._set_text(self.crispr_info, [
                    (self._t('loaded') + gene + '\n', 'ttl'),
                    ('-' * 26 + '\n', 'dim'),
                    (self._t('length') + ' {} bp\n'.format(len(seq)), 'nrm'),
                    (self._t('gc_content') + ' {}%\n'.format(gc_content(seq)), 'nrm'),
                    ('\n' + self._t('click_scan') + '\n', 'wrn')])
            self.after(0, done)
        threading.Thread(target=worker, daemon=True).start()

    def _crispr_use_pasted_seq(self):
        raw = self.crispr_seq_input.get('1.0', 'end').strip()
        if not raw:
            return
        cleaned = ''
        for line in raw.split('\n'):
            if line.startswith('>'):
                continue
            cleaned += ''.join(c for c in line if c.isalpha())
        if not cleaned:
            return
        if is_protein_sequence(cleaned):
            dna = back_translate_protein(cleaned)
            info_text = ('Белок ({} ак) -> ДНК ({} нт)' if self.lang == 'ru'
                         else 'Protein ({} aa) -> DNA ({} bp)').format(len(cleaned), len(dna))
            sequence = dna
            name = 'Белок' if self.lang == 'ru' else 'Custom protein'
        else:
            sequence = cleaned.upper()
            name = 'ДНК' if self.lang == 'ru' else 'Custom DNA'
            info_text = ('ДНК ({} нт)' if self.lang == 'ru'
                         else 'DNA ({} bp)').format(len(sequence))
        self._save_history('crispr')
        self.current_state['crispr'] = {
            'name': name, 'sequence': sequence, 'original': sequence,
            'info': {'note': info_text}, 'enzyme': self.crispr_enzyme.get(),
            'targets': [], 'selected_target': None, 'edits': [],
        }
        self._crispr_refresh()
        self._set_text(self.crispr_info, [
            (name + '\n', 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (info_text + '\n', 'nrm'),
            (self._t('gc_content') + ' {}%\n\n'.format(gc_content(sequence)), 'nrm'),
            (self._t('click_scan') + '\n', 'wrn')])

    def _crispr_compute_guide_scores(self, target, seq, enzyme):
        """Attach the full CRISPOR score bundle to a guide target (in place).

        Stores everything the results table shows: MIT/Hsu specificity,
        Doench 2014 on-target, CRISPRScan/Moreno-Mateos, Bae out-of-frame,
        plus the worst off-target. Cached on the target dict so the map and
        the info panel can reuse it without recomputing.
        """
        if target.get('_scored'):
            return target
        guide = target['guide']
        # 30-mer (Doench) and 35-mer (CRISPRScan) context around the guide
        ctx30 = self._crispr_guide_context(target, seq)
        ctx35 = self._crispr_guide_context_n(target, seq, up=6, down=6)
        # cut-centred window for the Bae out-of-frame score
        try:
            cut_offset = CRISPR_ENZYMES.get(enzyme, {}).get('cut_offset', -3)
            cut_pos = target['position'] + len(guide) + cut_offset
            cw_start = max(0, cut_pos - 30)
            cw_end = min(len(seq), cut_pos + 30)
            cut_ctx = seq[cw_start:cw_end]
        except Exception:
            cut_ctx = ctx30
        try:
            bundle = score_guide_full(guide, context30=ctx30, context35=ctx35,
                                      full_sequence=seq, cut_context=cut_ctx,
                                      enzyme=enzyme)
        except Exception as exc:
            biosim_log('warn', '_crispr_compute_guide_scores: {}'.format(exc))
            bundle = {'doench': None, 'crisprscan': None, 'oof': None,
                      'mit_spec': None, 'cfd_spec': None, 'worst_ot': None}
        target['scores'] = bundle
        # off-target mismatch counts (0/1/2/3), searched in the loaded sequence
        try:
            ot = calc_off_targets(guide, seq, max_mismatches=3)
        except Exception:
            ot = {'count_0mm': 0, 'count_1mm': 0, 'count_2mm': 0, 'count_3mm': 0}
        target['offtargets'] = ot
        target['_scored'] = True
        return target

    def _crispr_scan(self):
        state = self.current_state['crispr']
        if not state.get('sequence'):
            return
        enz = self.crispr_enzyme.get()
        seq = state['sequence']
        targets = find_crispr_targets(seq, enzyme=enz, max_sites=200)
        state['targets'] = targets
        state['enzyme'] = enz
        # Compute the full CRISPOR score bundle for every guide up-front, so the
        # table shows real specificity/efficiency numbers, not just a heuristic.
        for t in targets:
            self._crispr_compute_guide_scores(t, seq, enz)
        self._crispr_fill_table(targets)
        # update the count label in the top action bar
        lbl = getattr(self, 'crispr_count_lbl', None)
        if lbl is not None:
            lbl.config(text=('{} гайдов'.format(len(targets)) if self.lang == 'ru'
                             else '{} guides'.format(len(targets))))
        good = 0
        for t in targets:
            sc = t.get('scores') or {}
            spec = sc.get('mit_spec')
            if spec is not None and spec >= 70:
                good += 1
        self._set_text(self.crispr_info, [
            (self._t('scan_complete') + '\n', 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (self._t('enzyme_lbl') + ' ' + enz + '\n', 'nrm'),
            (self._t('total_targets') + ' {}\n'.format(len(targets)), 'ok'),
            ((('Специфичных (MIT ≥ 70): ' if self.lang == 'ru'
               else 'Specific (MIT ≥ 70): ') + '{}\n\n'.format(good)),
             'ok' if good > 0 else 'wrn'),
            (('Таблица показывает все скоры CRISPOR:\n'
              'специфичность (off-target), эффективность реза\n'
              '(Doench / CRISPRScan) и сдвиг рамки (OOF).\n\n'
              if self.lang == 'ru' else
              'The table shows every CRISPOR score: specificity\n'
              '(off-target), cutting efficiency (Doench / CRISPRScan)\n'
              'and out-of-frame (OOF).\n\n'), 'nrm'),
            (self._t('select_target') + '\n', 'nrm')])
        self._crispr_render_sequence()
        self._crispr_draw_guide_map()

