    def _crispr_batch_run(self):
        """Kick off the batch design on a worker thread so the UI stays live."""
        is_ru = (self.lang == 'ru')
        raw = self._crispr_batch_input.get('1.0', 'end')
        records = parse_fasta_multi(raw)
        if not records:
            messagebox.showinfo('VIREON',
                ('Введите хотя бы одну последовательность.' if is_ru
                 else 'Enter at least one sequence.'))
            return
        enzyme = self._crispr_batch_enzyme.get() or 'SpCas9'
        try:
            top_n = int(self._crispr_batch_topn.get())
        except Exception:
            top_n = 3
        ri = self._crispr_batch_rank.current()
        rank_by = self._crispr_batch_rank_keys[ri] if ri >= 0 else 'mit_spec'
        self._crispr_batch_run_btn.config(state='disabled')
        self._crispr_batch_status.config(
            text=('Обработка… 0 / {}'.format(len(records)) if is_ru
                  else 'Processing… 0 / {}'.format(len(records))))

        def _progress(done, total, name):
            def _upd():
                if not self._crispr_batch_status.winfo_exists():
                    return
                self._crispr_batch_status.config(
                    text=('Обработка… {} / {}  {}'.format(done, total, name)
                          if is_ru else
                          'Processing… {} / {}  {}'.format(done, total, name)))
            try:
                self.after(0, _upd)
            except Exception:
                pass

        def worker():
            try:
                res = batch_design_guides(records, enzyme=enzyme, top_n=top_n,
                                          rank_by=rank_by, progress=_progress)
            except Exception as exc:
                biosim_log('error', 'batch worker: {}'.format(exc))
                res = {'error': str(exc), 'results': []}

            def _done():
                self._crispr_batch_results = res
                self._crispr_batch_fill(res)
                self._crispr_batch_run_btn.config(state='normal')
                n = res.get('n_with_guides', 0)
                tot = res.get('n_sequences', 0)
                self._crispr_batch_status.config(
                    text=('Готово: гайды для {} из {} последовательностей'.format(n, tot)
                          if is_ru else
                          'Done: guides for {} of {} sequences'.format(n, tot)))
            try:
                self.after(0, _done)
            except Exception:
                pass

        threading.Thread(target=worker, daemon=True).start()

    def _crispr_batch_fill(self, res):
        """Populate the batch results table from a batch_design_guides result."""
        tbl = getattr(self, '_crispr_batch_table', None)
        if tbl is None:
            return
        for iid in tbl.get_children():
            tbl.delete(iid)

        def fmt(v):
            return '{:.0f}'.format(v) if v is not None else '—'

        for r in res.get('results', []):
            name = r['name']
            if not r['guides']:
                tbl.insert('', 'end', values=(
                    name, '—', ('(нет гайдов)' if self.lang == 'ru'
                                else '(no guides)'), '', '', '', '', '',
                    '', '', '', ''), tags=('bad',))
                continue
            for g in r['guides']:
                spec = g.get('mit_spec')
                band_val = spec if spec is not None else 0
                if band_val >= 70:
                    tag = 'good'
                elif band_val >= 50:
                    tag = 'mid'
                else:
                    tag = 'bad'
                tags = (tag, 'best') if g['rank'] == 1 else (tag,)
                tbl.insert('', 'end', values=(
                    name if g['rank'] == 1 else '',
                    g['rank'], g['guide'], g['pam'], g['strand'],
                    g['position'], fmt(g.get('mit_spec')), fmt(g.get('cfd_spec')),
                    fmt(g.get('doench')), fmt(g.get('crisprscan')),
                    fmt(g.get('oof')), '{:.0f}'.format(g.get('gc', 0))),
                    tags=tags)

    def _crispr_batch_export(self):
        """Export the batch results as a tab-separated table."""
        is_ru = (self.lang == 'ru')
        res = getattr(self, '_crispr_batch_results', None)
        if not res or not res.get('results'):
            messagebox.showinfo('VIREON',
                ('Сначала запустите пакетный дизайн.' if is_ru
                 else 'Run the batch design first.'))
            return
        header = ['sequence', 'rank', 'guide', 'pam', 'strand', 'position',
                  'specificity_MIT', 'specificity_CFD', 'doench2014',
                  'crisprscan', 'oof', 'gc',
                  'off_0mm', 'off_1mm', 'off_2mm', 'off_3mm']
        lines = ['\t'.join(header)]

        def s(v):
            return '' if v is None else '{:.0f}'.format(v)

        for r in res['results']:
            for g in r['guides']:
                lines.append('\t'.join([
                    r['name'], str(g['rank']), g['guide'], g['pam'],
                    g['strand'], str(g['position']),
                    s(g.get('mit_spec')), s(g.get('cfd_spec')),
                    s(g.get('doench')), s(g.get('crisprscan')), s(g.get('oof')),
                    '{:.0f}'.format(g.get('gc', 0)),
                    str(g.get('off_0mm', 0)), str(g.get('off_1mm', 0)),
                    str(g.get('off_2mm', 0)), str(g.get('off_3mm', 0))]))
        text = '\n'.join(lines)
        try:
            self._metab_show_text_window(
                ('Экспорт batch-гайдов' if is_ru else 'Batch guide export'), text)
        except Exception as _exc:
            biosim_log('warn', '_crispr_batch_export window: {}'.format(_exc))
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension='.tsv',
                filetypes=[('TSV', '*.tsv'), ('Text', '*.txt'), ('All', '*.*')],
                title=('Сохранить batch-гайды' if is_ru else 'Save batch guides'))
            if path:
                with open(path, 'w', encoding='utf-8') as fh:
                    fh.write(text)
                messagebox.showinfo('VIREON',
                    ('Сохранено: {}'.format(path) if is_ru
                     else 'Saved: {}'.format(path)))
        except Exception as _exc:
            biosim_log('warn', '_crispr_batch_export save: {}'.format(_exc))

    def _crispr_export_guides(self):
        """Export all scored guides as a tab-separated table (CRISPOR-style),
        shown in a copyable window and offered as a file save."""
        state = self.current_state.get('crispr', {})
        targets = state.get('targets', [])
        is_ru = (self.lang == 'ru')
        if not targets:
            messagebox.showinfo('VIREON',
                ('Сначала найдите гайды (кнопка «Найти гайды»).' if is_ru
                 else 'Find guides first (the "Find guides" button).'))
            return
        seq = state.get('sequence', '')
        enz = state.get('enzyme', 'SpCas9')
        header = ['#', 'strand', 'position', 'guide', 'pam', 'gc',
                  'specificity_MIT', 'specificity_CFD', 'doench2014',
                  'crisprscan', 'oof', 'off_0mm', 'off_1mm', 'off_2mm', 'off_3mm']
        lines = ['\t'.join(header)]
        for i, t in enumerate(targets):
            if not t.get('_scored') and seq:
                try:
                    self._crispr_compute_guide_scores(t, seq, enz)
                except Exception:
                    pass
            sc = t.get('scores') or {}
            ot = t.get('offtargets') or {}

            def s(v):
                return '' if v is None else '{:.0f}'.format(v)

            row = [str(i + 1), t.get('strand', ''), str(t.get('position', '')),
                   t.get('guide', ''), t.get('pam', ''),
                   '{:.0f}'.format(t.get('gc', 0)),
                   s(sc.get('mit_spec')), s(sc.get('cfd_spec')),
                   s(sc.get('doench')),
                   s(sc.get('crisprscan')), s(sc.get('oof')),
                   str(ot.get('count_0mm', 0)), str(ot.get('count_1mm', 0)),
                   str(ot.get('count_2mm', 0)), str(ot.get('count_3mm', 0))]
            lines.append('\t'.join(row))
        text = '\n'.join(lines)
        # show in a copyable window (reuses the metabolic text-window helper)
        try:
            self._metab_show_text_window(
                ('Экспорт гайдов CRISPR' if is_ru else 'CRISPR guide export'),
                text)
        except Exception as _exc:
            biosim_log('warn', '_crispr_export_guides window: {}'.format(_exc))
        # also offer to save to a .tsv file
        try:
            from tkinter import filedialog
            path = filedialog.asksaveasfilename(
                defaultextension='.tsv',
                filetypes=[('TSV', '*.tsv'), ('Text', '*.txt'), ('All', '*.*')],
                title=('Сохранить гайды' if is_ru else 'Save guides'))
            if path:
                with open(path, 'w', encoding='utf-8') as fh:
                    fh.write(text)
                messagebox.showinfo('VIREON',
                    ('Сохранено: {}'.format(path) if is_ru
                     else 'Saved: {}'.format(path)))
        except Exception as _exc:
            biosim_log('warn', '_crispr_export_guides save: {}'.format(_exc))

    def _crispr_fill_table(self, targets):
        """(Re)populate the CRISPOR-style results table from a list of scored
        guide targets. Colour-codes each row by MIT specificity. Honours the
        5' nucleotide filter (all / G- / GG- / A-) from the action bar."""
        tbl = getattr(self, 'crispr_table', None)
        if tbl is None:
            return
        for iid in tbl.get_children():
            tbl.delete(iid)
        self._crispr_row_index = {}
        prefix = 'all'
        pv = getattr(self, 'crispr_prefix_filter', None)
        if pv is not None:
            try:
                prefix = pv.get()
            except Exception:
                prefix = 'all'
        shown = 0
        for i, t in enumerate(targets):
            guide = t.get('guide', '')
            # 5' filter: guide must start with the required base(s)
            if prefix == 'G' and not guide.startswith('G'):
                continue
            if prefix == 'GG' and not guide.startswith('GG'):
                continue
            if prefix == 'A' and not guide.startswith('A'):
                continue
            sc = t.get('scores') or {}
            ot = t.get('offtargets') or {}
            spec = sc.get('mit_spec')
            doench = sc.get('doench')
            cscan = sc.get('crisprscan')
            oof = sc.get('oof')
            # quality band + mark from specificity (fall back to base score)
            band_val = spec if spec is not None else t.get('score', 0)
            if band_val >= 70:
                mark, tag = '●', 'good'
            elif band_val >= 50:
                mark, tag = '◐', 'mid'
            else:
                mark, tag = '○', 'bad'

            def fmt(v):
                return '{:.0f}'.format(v) if v is not None else '—'

            ot_str = '{}·{}·{}·{}'.format(
                ot.get('count_0mm', 0), ot.get('count_1mm', 0),
                ot.get('count_2mm', 0), ot.get('count_3mm', 0))
            values = (mark, i + 1, t['strand'], t['guide'][:20], t['pam'],
                      fmt(spec), fmt(doench), fmt(cscan), fmt(oof),
                      '{:.0f}'.format(t['gc']), ot_str)
            iid = tbl.insert('', 'end', values=values, tags=(tag,))
            self._crispr_row_index[iid] = i
            shown += 1
        # reflect the filter in the count label
        lbl = getattr(self, 'crispr_count_lbl', None)
        if lbl is not None:
            total = len(targets)
            if shown != total:
                lbl.config(text=('{} из {} гайдов'.format(shown, total)
                                 if self.lang == 'ru'
                                 else '{} of {} guides'.format(shown, total)))
            else:
                lbl.config(text=('{} гайдов'.format(total) if self.lang == 'ru'
                                 else '{} guides'.format(total)))

    def _crispr_draw_guide_map(self):
        """Guide map drawn to genome-browser conventions (IGV / Benchling /
        CRISPOR / SnapGene):

          * coordinate ruler with round tick values (1/2/5 x 10^n)
          * double-stranded DNA axis, 5'->3' on top, 3'->5' below
          * guides packed into LANES so overlapping guides never sit on top of
            one another (this is the standard genome-browser track layout)
          * each guide is an arrow pointing in its strand direction, PAM drawn
            as a separate block at the 3' end
          * predicted cut site marked with a wedge on the DNA axis
          * colour graded by on-target score (green / amber / red)
          * GC-content profile as a filled area with a 50% reference line
          * nucleotide letters shown automatically when zoomed in far enough
          * legend, and a readout for the currently selected guide

        The canvas height is recomputed from the number of lanes actually
        needed, so nothing is ever clipped.
        """
        cv = getattr(self, 'crispr_map_canvas', None)
        if cv is None:
            return
        cv.delete('all')
        is_ru = (self.lang == 'ru')
        state = self.current_state['crispr']
        seq = (state.get('sequence') or '').upper()
        targets = state.get('targets') or []
        n = len(seq)

        cv.update_idletasks()
        W = cv.winfo_width() or 660
        if W < 50:
            W = 660

        if n == 0:
            cv.configure(height=90)
            cv.create_text(W // 2, 45,
                           text=('Загрузите последовательность, чтобы увидеть карту'
                                 if is_ru else 'Load a sequence to see the map'),
                           fill=biosim_theme('text_dim'), font=('Arial', 10))
            return

        selected = state.get('selected_target')
        margin_l, margin_r = 44, 16
        usable = max(60, W - margin_l - margin_r)
        bp_per_px = n / float(usable)

        def xpos(p):
            return margin_l + usable * (min(max(p, 0), n) / float(n))

        # ── enzyme geometry (needed for the cut site) ────────────────────
        enz_name = state.get('enzyme') or 'SpCas9'
        enz = CRISPR_ENZYMES.get(enz_name, CRISPR_ENZYMES.get('SpCas9', {}))
        cut_offset = enz.get('cut_offset', -3)

        # ── colour grading (CRISPOR convention) ─────────────────────────
        def score_color(s):
            if s >= 70:
                return '#1a7f37'
            if s >= 50:
                return '#9a6700'
            return '#cf222e'

        # ── lane packing: guides that overlap go on separate rows ────────
        # Sort by score so the best guides take the lanes closest to the DNA.
        MAX_LANES = 6
        MIN_GAP_PX = 4

        def pack(items):
            lane_ends = []
            placed, overflow = [], 0
            for t in items:
                gl = len(t.get('guide') or '') or enz.get('guide_len', 20)
                pl = len(t.get('pam') or '') or 3
                p = t.get('position', 0)
                if t.get('strand', '+') == '+':
                    a, b = xpos(p), xpos(p + gl + pl)
                else:
                    a, b = xpos(max(0, p - pl)), xpos(p + gl)
                if b - a < 7:
                    b = a + 7
                slot = None
                for li in range(len(lane_ends)):
                    if a >= lane_ends[li] + MIN_GAP_PX:
                        slot = li
                        break
                if slot is None:
                    if len(lane_ends) >= MAX_LANES:
                        overflow += 1
                        continue
                    lane_ends.append(b)
                    slot = len(lane_ends) - 1
                else:
                    lane_ends[slot] = b
                placed.append((t, slot, a, b))
            return placed, len(lane_ends), overflow

        plus = [t for t in targets if t.get('strand', '+') == '+']
        minus = [t for t in targets if t.get('strand', '+') != '+']
        plus_packed, plus_lanes, plus_over = pack(plus)
        minus_packed, minus_lanes, minus_over = pack(minus)

        # ── vertical layout, computed from the lanes we actually need ────
        LANE_H = 13
        y_ruler = 22
        top_block = max(1, plus_lanes) * LANE_H
        y_dna1 = y_ruler + 12 + top_block
        y_dna2 = y_dna1 + 7
        bottom_block = max(1, minus_lanes) * LANE_H
        y_seq = y_dna2 + 12 + bottom_block
        show_letters = (usable / float(n)) >= 6.5
        y_gc_top = y_seq + (24 if show_letters else 2)
        GC_H = 26
        y_gc_base = y_gc_top + GC_H
        y_legend = y_gc_base + 18
        y_readout = y_legend + 16
        total_h = int(y_readout + 12)
        cv.configure(height=total_h)

        # ── coordinate ruler with round values ──────────────────────────
        def nice_step(span, want=8):
            raw = span / float(max(1, want))
            if raw <= 0:
                return 1
            mag = 10 ** int(math.floor(math.log10(raw)))
            for m in (1, 2, 5):
                if raw <= m * mag:
                    return int(m * mag) or 1
            return int(10 * mag) or 1

        step = nice_step(n)
        cv.create_line(margin_l, y_ruler, margin_l + usable, y_ruler,
                       fill=biosim_theme('border'), width=1)
        pos = 0
        while pos <= n:
            x = xpos(pos)
            cv.create_line(x, y_ruler - 5, x, y_ruler,
                           fill=biosim_theme('text_dim'))
            cv.create_text(x, y_ruler - 12, text=str(pos),
                           fill=biosim_theme('text_dim'), font=('Arial', 7))
            pos += step
        # minor ticks
        minor = max(1, step // 5)
        pos = 0
        while pos <= n:
            if pos % step:
                x = xpos(pos)
                cv.create_line(x, y_ruler - 2, x, y_ruler,
                               fill=biosim_theme('border'))
            pos += minor
        cv.create_text(margin_l + usable, y_ruler + 8, anchor='e',
                       text='{} bp'.format(n),
                       fill=biosim_theme('text_dim'), font=('Arial', 7))

        # ── double-stranded DNA axis ────────────────────────────────────
        cv.create_rectangle(margin_l, y_dna1 - 1, margin_l + usable, y_dna1 + 1,
                            fill=biosim_theme('text'), outline='')
        cv.create_rectangle(margin_l, y_dna2 - 1, margin_l + usable, y_dna2 + 1,
                            fill=biosim_theme('text_dim'), outline='')
        cv.create_text(margin_l - 6, y_dna1, text="5'", anchor='e',
                       fill=biosim_theme('text_dim'), font=('Arial', 7))
        cv.create_text(margin_l - 6, y_dna2, text="3'", anchor='e',
                       fill=biosim_theme('text_dim'), font=('Arial', 7))

        def same_target(a, b):
            return (a and b and a.get('position') == b.get('position')
                    and a.get('strand') == b.get('strand'))

        # ── draw one guide as an arrow + PAM block ──────────────────────
        def guide_quality(t):
            """Colour band value for a guide: prefer MIT specificity (matches
            the results table), fall back to the base heuristic score."""
            sc = t.get('scores') or {}
            v = sc.get('mit_spec')
            if v is None:
                v = t.get('score', 0)
            return v

        def draw_guide(t, lane, a, b, strand):
            score = guide_quality(t)
            col = score_color(score)
            gl = len(t.get('guide') or '') or enz.get('guide_len', 20)
            pl = len(t.get('pam') or '') or 3
            p = t.get('position', 0)
            is_sel = same_target(t, selected)
            h = 9
            if strand == '+':
                yc = y_dna1 - 10 - lane * LANE_H
                gx1, gx2 = xpos(p), xpos(p + gl)
                px1, px2 = xpos(p + gl), xpos(p + gl + pl)
            else:
                yc = y_dna2 + 10 + lane * LANE_H
                gx1, gx2 = xpos(p), xpos(p + gl)
                px1, px2 = xpos(max(0, p - pl)), xpos(p)
            if gx2 - gx1 < 6:
                gx2 = gx1 + 6
            if px2 - px1 < 3:
                if strand == '+':
                    px2 = px1 + 3
                else:
                    px1 = px2 - 3
            yt, yb = yc - h / 2.0, yc + h / 2.0
            head = min(7, max(3, (gx2 - gx1) * 0.28))
            tag = 'guide:{}:{}'.format(p, strand)
            if strand == '+':
                pts = [gx1, yt, gx2 - head, yt, gx2, yc, gx2 - head, yb, gx1, yb]
            else:
                pts = [gx2, yt, gx1 + head, yt, gx1, yc, gx1 + head, yb, gx2, yb]
            cv.create_polygon(pts, fill=col, outline=col, tags=(tag, 'guide'))
            cv.create_rectangle(px1, yt + 1, px2, yb - 1,
                                fill='#8250df', outline='#8250df',
                                tags=(tag, 'guide'))
            if is_sel:
                mid = (gx1 + gx2) / 2.0
                cv.create_line(mid, yb if strand == '+' else yt,
                               mid, y_dna1 if strand == '+' else y_dna2,
                               fill=col, width=1, dash=(1, 2))
                x0 = min(gx1, px1) - 3
                x1_ = max(gx2, px2) + 3
                cv.create_rectangle(x0, yt - 3, x1_, yb + 3,
                                    outline='#0969da', width=2)
            # predicted cut site on the DNA axis
            if strand == '+':
                cut_bp = p + gl + cut_offset
            else:
                cut_bp = p - cut_offset
            cx = xpos(cut_bp)
            if is_sel:
                cv.create_polygon(cx, y_dna1 - 6, cx - 4, y_dna1 - 1,
                                  cx + 4, y_dna1 - 1,
                                  fill='#0969da', outline='#0969da')
                cv.create_polygon(cx, y_dna2 + 6, cx - 4, y_dna2 + 1,
                                  cx + 4, y_dna2 + 1,
                                  fill='#0969da', outline='#0969da')
                cv.create_line(cx, y_ruler, cx, y_gc_base,
                               fill='#0969da', width=1, dash=(3, 3))
            elif score >= 70:
                # only strong guides get a cut tick, otherwise the axis
                # turns into visual noise
                cv.create_line(cx, y_dna1 - 4, cx, y_dna2 + 4,
                               fill='#57606a', width=1)

        for t, lane, a, b in plus_packed:
            draw_guide(t, lane, a, b, '+')
        for t, lane, a, b in minus_packed:
            draw_guide(t, lane, a, b, '-')

        # click a guide to select it
        def on_click(event):
            item = cv.find_closest(cv.canvasx(event.x), cv.canvasy(event.y))
            if not item:
                return
            for tg in cv.gettags(item[0]):
                if tg.startswith('guide:'):
                    _, sp, ss = tg.split(':')
                    for t in targets:
                        if (str(t.get('position')) == sp
                                and t.get('strand') == ss):
                            self.current_state['crispr']['selected_target'] = t
                            try:
                                if not t.get('_scored'):
                                    self._crispr_compute_guide_scores(
                                        t, seq, state.get('enzyme', 'SpCas9'))
                                self._crispr_show_target_info(t)
                            except Exception as exc:
                                biosim_log('warn', 'guide select: {}'.format(exc))
                            self._crispr_draw_guide_map()
                            return
        cv.bind('<Button-1>', on_click)

        if plus_over or minus_over:
            cv.create_text(margin_l + usable, y_dna1 - 4, anchor='se',
                           text=('+{} гайдов скрыто (наложение)'
                                 if is_ru else '+{} guides hidden (overlap)'
                                 ).format(plus_over + minus_over),
                           fill=biosim_theme('text_dim'), font=('Arial', 7))

        # ── nucleotide letters (both strands) when zoomed in ────────────
        if show_letters:
            base_col = {'A': '#cf222e', 'T': '#1a7f37',
                        'C': '#0969da', 'G': '#bc4c00'}
            comp = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G', 'N': 'N'}
            for i in range(0, n, 1):
                ch = seq[i]
                x = xpos(i + 0.5)
                # top strand 5'->3'
                cv.create_text(x, y_seq, text=ch, font=('Courier', 7),
                               fill=base_col.get(ch, biosim_theme('text_dim')))
                # bottom (complementary) strand 3'->5', dimmer
                cv.create_text(x, y_seq + 9,
                               text=comp.get(ch, 'N'), font=('Courier', 7),
                               fill=biosim_theme('text_dim'))

        # ── GC-content profile ──────────────────────────────────────────
        win = max(10, n // 50)
        gc_pts = []
        stepi = max(1, win // 3)
        for i in range(0, max(1, n - win + 1), stepi):
            seg = seq[i:i + win]
            if not seg:
                continue
            gc = (seg.count('G') + seg.count('C')) / float(len(seg))
            gc_pts.append((xpos(i + win / 2.0),
                           y_gc_base - gc * GC_H, gc))
        if len(gc_pts) > 1:
            poly = [margin_l, y_gc_base]
            for gx, gy, _ in gc_pts:
                poly.extend([gx, gy])
            poly.extend([margin_l + usable, y_gc_base])
            cv.create_polygon(poly, fill='#e8dcc0', outline='')
            flat = []
            for gx, gy, _ in gc_pts:
                flat.extend([gx, gy])
            cv.create_line(flat, fill='#9a6700', width=1, smooth=True)
            y50 = y_gc_base - 0.5 * GC_H
            cv.create_line(margin_l, y50, margin_l + usable, y50,
                           fill=biosim_theme('border'), dash=(2, 3))
            cv.create_text(margin_l - 6, y50, anchor='e', text='50%',
                           fill=biosim_theme('text_dim'), font=('Arial', 6))
            cv.create_text(margin_l - 6, y_gc_base - GC_H, anchor='e',
                           text='GC', fill='#9a6700', font=('Arial', 7, 'bold'))
        cv.create_line(margin_l, y_gc_base, margin_l + usable, y_gc_base,
                       fill=biosim_theme('border'))

        # ── legend ──────────────────────────────────────────────────────
        lx = margin_l
        legend = [
            ('#1a7f37', ('скор ≥70' if is_ru else 'score ≥70')),
            ('#9a6700', '50–69'),
            ('#cf222e', ('<50' if is_ru else '<50')),
            ('#8250df', 'PAM'),
        ]
        for col, label in legend:
            cv.create_rectangle(lx, y_legend - 4, lx + 9, y_legend + 4,
                                fill=col, outline=col)
            cv.create_text(lx + 12, y_legend, text=label, anchor='w',
                           fill=biosim_theme('text_dim'), font=('Arial', 7))
            lx += 12 + len(label) * 5.4 + 14
        cv.create_polygon(lx, y_legend + 4, lx + 4, y_legend - 3,
                          lx + 8, y_legend + 4,
                          fill='#57606a', outline='#57606a')
        cut_lbl = ('разрез' if is_ru else 'cut site')
        cv.create_text(lx + 12, y_legend, text=cut_lbl, anchor='w',
                       fill=biosim_theme('text_dim'), font=('Arial', 7))
        cv.create_text(margin_l + usable, y_legend, anchor='e',
                       text=('→ цепь +     ← цепь −' if is_ru
                             else '→ + strand     ← − strand'),
                       fill=biosim_theme('text_dim'), font=('Arial', 7))

        # ── readout for the selected guide ──────────────────────────────
        if selected:
            gl = len(selected.get('guide') or '')
            txt = ('Выбран: {} {} · поз. {}–{} · цепь {} · скор {:.0f} · GC {:.0f}%'
                   if is_ru else
                   'Selected: {} {} · pos {}–{} · strand {} · score {:.0f} · GC {:.0f}%')
            cv.create_text(margin_l, y_readout, anchor='w',
                           text=txt.format(selected.get('guide', ''),
                                           selected.get('pam', ''),
                                           selected.get('position', 0),
                                           selected.get('position', 0) + gl,
                                           selected.get('strand', '+'),
                                           selected.get('score', 0),
                                           selected.get('gc', 0)),
                           fill=biosim_theme('text'), font=('Courier', 8, 'bold'))
        else:
            cv.create_text(margin_l, y_readout, anchor='w',
                           text=('Найдено гайдов: {} · нажмите на стрелку, чтобы выбрать'
                                 if is_ru else
                                 'Guides found: {} · click an arrow to select'
                                 ).format(len(targets)),
                           fill=biosim_theme('text_dim'), font=('Arial', 8))

    def _crispr_get_selected_guide(self):
        """Helper: get currently selected guide target, or None with a message."""
        state = self.current_state['crispr']
        target = state.get('selected_target')
        if not target:
            self._set_text(self.crispr_info, [
                (('Сначала выберите гайд из списка кандидатов.\n'
                  if self.lang == 'ru' else
                  'Select a guide from the candidates list first.\n'), 'wrn'),
            ])
            return None
        return target

    def _crispr_organism_changed(self):
        """Update CRISPR state when organism changes — affects efficiency etc."""
        idx = self.crispr_org_combo.current()
        if idx < 0 or idx >= len(self._crispr_org_keys):
            return
        org_key = self._crispr_org_keys[idx]
        self.current_state['crispr']['organism'] = org_key
        org = get_organism(org_key)
        if not org:
            return
        is_ru = (self.lang == 'ru')
        crispr = org['crispr']
        # Short info line
        info = '{} · HDR {:.0f}% · NHEJ {:.0f}% · {}'.format(
            org['latin'],
            crispr['hdr_efficiency'] * 100,
            crispr['nhej_efficiency'] * 100,
            crispr['difficulty'])
        self.crispr_org_info.config(text=info)
        # Suggest best Cas for this organism
        if hasattr(self, 'crispr_enzyme_combo'):
            best = crispr['best_cas'][0]
            try:
                self.crispr_enzyme.set(best)
            except Exception as _exc:
                biosim_log('warn', '_crispr_organism_changed: {}'.format(_exc))


    def _crispr_show_organism_profile(self):
        """Show a deep profile of the selected organism."""
        org_key = self.current_state['crispr'].get('organism', 'human')
        org = get_organism(org_key)
        if not org:
            return
        is_ru = (self.lang == 'ru')
        win = tk.Toplevel(self)
        win.title('Профиль организма' if is_ru else 'Organism profile')
        win.geometry('600x680')
        win.configure(bg=biosim_theme('bg'))
        win.transient(self)

        # Header
        name = org['name_ru'] if is_ru else org['name_en']
        tk.Label(win, text=name, bg=biosim_theme('bg'), fg='#0969da',
                  font=('Arial', 16, 'bold')).pack(pady=(14, 0))
        tk.Label(win, text=org['latin'], bg=biosim_theme('bg'), fg=biosim_theme('text_dim'),
                  font=('Arial', 11, 'italic')).pack(pady=(0, 8))

        # Scrollable content
        canv = tk.Canvas(win, bg=biosim_theme('bg'), highlightthickness=0)
        sb = tk.Scrollbar(win, orient='vertical', command=canv.yview)
        canv.configure(yscrollcommand=sb.set)
        canv.pack(side='left', fill='both', expand=True, padx=(10, 0), pady=4)
        sb.pack(side='right', fill='y')
        inner = tk.Frame(canv, bg=biosim_theme('bg'))
        inner.bind('<Configure>', lambda e: canv.configure(scrollregion=canv.bbox('all')))
        canv.create_window((0, 0), window=inner, anchor='nw', width=560)

        def section(title, color):
            tk.Label(inner, text=title, bg=biosim_theme('bg'), fg=color,
                      font=('Arial', 12, 'bold')).pack(anchor='w', padx=8, pady=(10, 2))

        def row(label, value):
            rf = tk.Frame(inner, bg=biosim_theme('panel')); rf.pack(fill='x', padx=8, pady=1)
            tk.Label(rf, text=label, bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                      font=('Arial', 9), width=22, anchor='w').pack(side='left', padx=6, pady=3)
            tk.Label(rf, text=str(value), bg=biosim_theme('panel'), fg=biosim_theme('text'),
                      font=('Arial', 9, 'bold'), anchor='w').pack(side='left')

        # Genome section
        section('Геном' if is_ru else 'Genome', '#1a7f37')
        row('Размер генома:' if is_ru else 'Genome size:', '{:,} bp'.format(org['genome_size_bp']))
        row('Число генов:' if is_ru else 'Genes:', '{:,}'.format(org['n_genes']))
        row('Хромосомы:' if is_ru else 'Chromosomes:', org['chromosomes'])
        row('Плоидность:' if is_ru else 'Ploidy:', org['ploidy'])
        row('Тип генома:' if is_ru else 'Genome type:',
            ('кольцевой' if org['genome_type'] == 'circular' else 'линейный') if is_ru
            else org['genome_type'])
        row('Тип клетки:' if is_ru else 'Cell type:', org['cell_type'])
        row('Время удвоения:' if is_ru else 'Doubling time:', '{} ч'.format(org['doubling_time_h']))

        # CRISPR section
        section('CRISPR' if is_ru else 'CRISPR', '#cf222e')
        cr = org['crispr']
        row('Лучшие Cas:' if is_ru else 'Best Cas:', ', '.join(cr['best_cas']))
        row('HDR (точные правки):' if is_ru else 'HDR (precise):', '{:.0f}%'.format(cr['hdr_efficiency']*100))
        row('NHEJ (нокаут):' if is_ru else 'NHEJ (knockout):', '{:.0f}%'.format(cr['nhej_efficiency']*100))
        row('Время правки:' if is_ru else 'Edit time:', '{} дней'.format(cr['edit_time_days']))
        row('Сложность:' if is_ru else 'Difficulty:', cr['difficulty'])
        # Delivery methods
        dl = tk.Frame(inner, bg=biosim_theme('panel')); dl.pack(fill='x', padx=8, pady=1)
        tk.Label(dl, text=('Доставка:' if is_ru else 'Delivery:'), bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                  font=('Arial', 9), width=22, anchor='nw').pack(side='left', padx=6, pady=3)
        tk.Label(dl, text=', '.join(cr['delivery']), bg=biosim_theme('panel'), fg=biosim_theme('text'),
                  font=('Arial', 9), wraplength=320, justify='left').pack(side='left')
        # Notes
        tk.Label(inner, text=(cr['notes_ru'] if is_ru else cr['notes_en']),
                  bg=biosim_theme('bg'), fg='#9a6700', font=('Arial', 9, 'italic'),
                  wraplength=540, justify='left').pack(anchor='w', padx=10, pady=6)

        # Applications (non-medical). The medical "diseases" section was
        # removed from the CRISPR tab — organism selection still shapes CRISPR
        # behaviour (genome, best Cas, HDR/NHEJ, delivery), but the disease
        # workspace and its treatment/progression UI are no longer part of
        # this tab.
        apps = org.get('applications', [])
        if apps:
            section('Применения' if is_ru else 'Applications', '#8250df')
            for a in apps:
                card = tk.Frame(inner, bg=biosim_theme('panel'), relief='solid', bd=1)
                card.pack(fill='x', padx=8, pady=3)
                aname = a['name'] if is_ru else a.get('name_en', a['name'])
                tk.Label(card, text=aname, bg=biosim_theme('panel'), fg=biosim_theme('text'),
                          font=('Arial', 10, 'bold')).pack(anchor='w', padx=8, pady=(4, 0))
                tk.Label(card, text=a['product'], bg=biosim_theme('panel'), fg=biosim_theme('text_dim'),
                          font=('Arial', 9)).pack(anchor='w', padx=8, pady=(0, 4))

        # Key genes
        section('Ключевые гены' if is_ru else 'Key genes', '#0550ae')
        tk.Label(inner, text=', '.join(org['key_genes']), bg=biosim_theme('bg'), fg=biosim_theme('text'),
                  font=('Courier', 10), wraplength=540, justify='left').pack(anchor='w', padx=10, pady=4)

    def _crispr_score_efficiency(self):
        """Score on-target cutting efficiency of the selected guide (Doench-style)."""
        target = self._crispr_get_selected_guide()
        if not target:
            return
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        guide = target['guide']
        # Build 30-mer context if possible
        pos = target['position']
        context = seq[max(0, pos-4):pos+len(guide)+6] if seq else guide
        eff = doench_efficiency_score(context if len(context) >= 20 else guide)
        is_ru = (self.lang == 'ru')
        rating = ('Высокая' if eff >= 65 else 'Средняя' if eff >= 40 else 'Низкая') if is_ru \
            else ('High' if eff >= 65 else 'Medium' if eff >= 40 else 'Low')
        color = 'ok' if eff >= 65 else 'wrn' if eff >= 40 else 'bad'
        # Organism-specific efficiency
        org_key = state.get('organism', 'human')
        org = get_organism(org_key)
        org_eff = organism_crispr_efficiency(org_key, state.get('enzyme', 'SpCas9'), 'knockout')
        lines = [
            (('Эффективность реза\n' if is_ru else 'Cutting efficiency\n'), 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (('Гайд: ' if is_ru else 'Guide: '), 'nrm'),
            (guide + '\n', 'mono'),
            (('Оценка гайда: ' if is_ru else 'Guide score: '), 'nrm'),
            ('{:.0f}%  ({})\n\n'.format(eff, rating), color),
        ]
        if org and not org_eff.get('error'):
            org_name = org['name_ru'] if is_ru else org['name_en']
            lines += [
                (('Организм: ' if is_ru else 'Organism: '), 'nrm'),
                (org_name + '\n', 'ok'),
                (('Нокаут (NHEJ): ' if is_ru else 'Knockout (NHEJ): '), 'nrm'),
                ('{:.0f}%\n'.format(org_eff['efficiency']), 'nrm'),
                (('Время: ' if is_ru else 'Time: '), 'nrm'),
                ('{} {}\n'.format(org_eff['edit_time_days'], 'дней' if is_ru else 'days'), 'nrm'),
                (('Сложность: ' if is_ru else 'Difficulty: '), 'nrm'),
                (org_eff['difficulty'] + '\n\n', 'nrm'),
            ]
        lines += [
            (('Учитывает: GC-состав, позиционные предпочтения,\n'
              'гомополимеры, нуклеотид у PAM, организм.\n\n'
              if is_ru else
              'Considers: GC, position, homopolymers,\n'
              'PAM-proximal nt, organism.\n\n'), 'dim'),
            (('Чем выше — тем активнее рез in vivo.'
              if is_ru else
              'Higher = more active cutting in vivo.'), 'dim'),
        ]
        self._set_text(self.crispr_info, lines)

    def _crispr_design_donor(self):
        """Design an HDR donor template for the selected cut site."""
        target = self._crispr_get_selected_guide()
        if not target:
            return
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        if not seq:
            return
        guide = target['guide']
        cut_offset = CRISPR_ENZYMES[state['enzyme']]['cut_offset']
        cut_pos = target['position'] + len(guide) + cut_offset
        is_ru = (self.lang == 'ru')
        # Default: insert a small tag (FLAG epitope DNA) as example
        flag_tag = 'GATTACAAGGATGACGACGATAAG'  # DYKDDDDK
        result = design_hdr_donor(seq, cut_pos, edit_type='insertion',
                                   insert_seq=flag_tag, homology_arm_len=40)
        if result.get('error'):
            self._set_text(self.crispr_info, [(result['error'] + '\n', 'bad')])
            return
        donor = result['donor']
        self._set_text(self.crispr_info, [
            (('Донор HDR\n' if is_ru else 'HDR Donor\n'), 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (result['description'] + '\n\n', 'ok'),
            (('Длина донора: ' if is_ru else 'Donor length: '), 'nrm'),
            ('{} bp\n'.format(result['length']), 'nrm'),
            (('Плечи гомологии: ' if is_ru else 'Homology arms: '), 'nrm'),
            ('{} bp\n\n'.format(result['homology_arm_len']), 'nrm'),
            (('Левое плечо:\n' if is_ru else 'Left arm:\n'), 'nrm'),
            (result['left_arm'] + '\n\n', 'mono'),
            (('Вставка (FLAG-тег):\n' if is_ru else 'Insert (FLAG tag):\n'), 'nrm'),
            (flag_tag + '\n\n', 'mono'),
            (('Правое плечо:\n' if is_ru else 'Right arm:\n'), 'nrm'),
            (result['right_arm'] + '\n\n', 'mono'),
            (('💡 Это шаблон для точной вставки через HDR.\n'
              'Пример вставляет FLAG-тег; в реальности замените\n'
              'на нужную последовательность.'
              if is_ru else
              'This is a template for precise HDR insertion.\n'
              'Example inserts a FLAG tag; replace with your\n'
              'sequence of interest in practice.'), 'dim'),
        ])

    def _crispr_predict_indels(self):
        """Predict likely NHEJ repair outcomes for the selected cut."""
        target = self._crispr_get_selected_guide()
        if not target:
            return
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        guide = target['guide']
        pos = target['position']
        context = seq[max(0, pos-10):pos+len(guide)+10] if seq else guide
        outcomes = predict_indel_outcomes(guide, context)
        is_ru = (self.lang == 'ru')
        lines = [
            (('Предсказание правок (NHEJ)\n' if is_ru else 'Edit prediction (NHEJ)\n'), 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (('После реза клетка чинит разрыв.\n'
              'Вероятные исходы:\n\n'
              if is_ru else
              'After cutting, the cell repairs the break.\n'
              'Likely outcomes:\n\n'), 'nrm'),
        ]
        for o in outcomes:
            freq = o['frequency']
            color = 'ok' if freq >= 30 else 'wrn' if freq >= 15 else 'dim'
            lines.append(('~{}%  '.format(freq), color))
            lines.append((o['type'] + '\n', 'nrm'))
            lines.append(('   ' + o['description'] + '\n\n', 'dim'))
        lines.append((('💡 Делеции со сдвигом рамки обычно\n'
                       'выключают ген (нокаут).'
                       if is_ru else
                       'Frameshift deletions usually\n'
                       'knock out the gene.'), 'dim'))
        self._set_text(self.crispr_info, lines)

