    def _crispr_base_editor(self):
        """Apply a base editor (C→T or A→G) to the selected guide."""
        target = self._crispr_get_selected_guide()
        if not target:
            return
        is_ru = (self.lang == 'ru')
        guide = target['guide'][:20].ljust(20, 'N')
        # Try both editors and show results
        cbe = apply_base_editor(guide, 'CBE (C→T)')
        abe = apply_base_editor(guide, 'ABE (A→G)')
        lines = [
            (('Редакторы оснований\n' if is_ru else 'Base Editors\n'), 'ttl'),
            ('-' * 30 + '\n', 'dim'),
            (('Протоспейсер:\n' if is_ru else 'Protospacer:\n'), 'nrm'),
            (guide + '\n\n', 'mono'),
        ]
        for ed, res in [('CBE (C→T)', cbe), ('ABE (A→G)', abe)]:
            info = BASE_EDITORS[ed]
            name = info['name_ru'] if is_ru else info['name_en']
            lines.append((name + ':\n', 'nrm'))
            if res.get('n_edits', 0) > 0:
                lines.append((res['edited'] + '  ', 'mono'))
                lines.append(('({} '.format(res['n_edits']) +
                              ('замен' if is_ru else 'edits') + ', '
                              + ('окно ' if is_ru else 'window ') +
                              res['window'] + ')\n\n', 'ok'))
            else:
                lines.append((('нет целевых оснований в окне\n\n' if is_ru
                               else 'no target bases in window\n\n'), 'dim'))
        lines.append((('💡 Редакторы оснований меняют одну пару\n'
                       'без двунитевого разрыва — точнее и безопаснее\n'
                       'для точечных мутаций.'
                       if is_ru else
                       '💡 Base editors change one base pair without\n'
                       'a double-strand break — precise and safer\n'
                       'for point mutations.'), 'dim'))
        self._set_text(self.crispr_info, lines)

    def _crispr_prime_editing(self):
        """Design a prime editing pegRNA for the selected guide region."""
        target = self._crispr_get_selected_guide()
        if not target:
            return
        is_ru = (self.lang == 'ru')
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        if len(seq) < 30:
            self._set_text(self.crispr_info, [
                (('Нужна последовательность ≥30 нт для prime editing.\n' if is_ru
                  else 'Need ≥30 nt sequence for prime editing.\n'), 'bad')])
            return
        # Ask the user for the edit
        pos = simpledialog.askinteger('VIREON',
            ('Позиция для правки (1-{}):'.format(len(seq)) if is_ru
             else 'Edit position (1-{}):'.format(len(seq))),
            minvalue=1, maxvalue=len(seq))
        if not pos:
            return
        new_base = simpledialog.askstring('VIREON',
            ('Новое основание (A/T/G/C):' if is_ru else 'New base (A/T/G/C):'))
        if not new_base or new_base.upper() not in 'ATGC':
            return
        orig = seq[pos - 1]
        r = design_prime_editing(seq, pos - 1, orig, new_base.upper())
        if r.get('error'):
            self._set_text(self.crispr_info, [(r['error'] + '\n', 'bad')])
            return
        self._set_text(self.crispr_info, [
            (('Prime Editing — дизайн pegRNA\n' if is_ru
              else 'Prime Editing — pegRNA design\n'), 'ttl'),
            ('-' * 30 + '\n', 'dim'),
            (('Правка: ' if is_ru else 'Edit: ') + r['edit'] + '\n\n', 'ok'),
            (('Спейсер (направляющая):\n' if is_ru else 'Spacer (guide):\n'), 'nrm'),
            (r['spacer'] + '\n\n', 'mono'),
            (('PBS (сайт связывания праймера):\n' if is_ru else 'PBS (primer binding):\n'), 'nrm'),
            (r['pbs'] + '\n\n', 'mono'),
            (('RTT (шаблон обратной транскрипции):\n' if is_ru else 'RTT (RT template):\n'), 'nrm'),
            (r['rtt'] + '\n\n', 'mono'),
            (("3'-расширение pegRNA (RTT+PBS):\n" if is_ru else "pegRNA 3' extension (RTT+PBS):\n"), 'nrm'),
            (r['extension_3prime'] + '\n\n', 'mono'),
            (('💡 Prime editing делает точную правку без\n'
              'двунитевого разрыва и без донорной ДНК.\n'
              'Новейшая технология (2025).'
              if is_ru else
              '💡 Prime editing makes a precise edit without\n'
              'a double-strand break and without donor DNA.\n'
              'Newest technology (2025).'), 'dim'),
        ])

    def _crispr_regulation(self):
        """Score the selected guide for CRISPRi (repression) or CRISPRa."""
        target = self._crispr_get_selected_guide()
        if not target:
            return
        is_ru = (self.lang == 'ru')
        # Ask mode and distance from TSS
        mode = simpledialog.askstring('VIREON',
            ('Режим: CRISPRi (подавление) или CRISPRa (активация)?\n'
             'Введите i или a:' if is_ru
             else 'Mode: CRISPRi (repress) or CRISPRa (activate)?\nEnter i or a:'))
        if not mode:
            return
        mode_key = 'CRISPRi' if mode.lower().startswith('i') else 'CRISPRa'
        dist = simpledialog.askinteger('VIREON',
            ('Расстояние от старта транскрипции (TSS), нт\n'
             '(отрицательное = до старта):' if is_ru
             else 'Distance from TSS (nt)\n(negative = upstream):'))
        if dist is None:
            return
        r = design_crispri_crispra(target['guide'], dist, mode_key)
        reg = CRISPR_REGULATION[mode_key]
        score = r['score']
        tag = 'ok' if score >= 70 else ('wrn' if score >= 50 else 'bad')
        self._set_text(self.crispr_info, [
            ((reg['name_ru'] if is_ru else reg['name_en']) + '\n', 'ttl'),
            ('-' * 30 + '\n', 'dim'),
            (('Эффектор: ' if is_ru else 'Effector: ') + reg['effector'] + '\n', 'nrm'),
            ((reg['desc_ru'] if is_ru else reg['desc_en']) + '\n\n', 'dim'),
            (('Расстояние от TSS: ' if is_ru else 'Distance from TSS: '),  'nrm'),
            ('{} нт\n'.format(dist) if is_ru else '{} nt\n'.format(dist), 'nrm'),
            (('Оценка эффективности: ' if is_ru else 'Effectiveness score: '), 'nrm'),
            ('{:.0f}/100\n\n'.format(score), tag),
            (('💡 ' + (reg['optimal_window_ru'] if is_ru else reg['optimal_window_en'])), 'dim'),
        ])

    def _crispr_multiplex(self):
        """Design guides for editing multiple genes at once."""
        is_ru = (self.lang == 'ru')
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        if len(seq) < 40:
            self._set_text(self.crispr_info, [
                (('Загрузите последовательность ≥40 нт.\n' if is_ru
                  else 'Load a sequence ≥40 nt.\n'), 'bad')])
            return
        # Split the sequence into 2 halves as 2 "genes" for demo, or use full
        half = len(seq) // 2
        targets = [
            {'name': ('Ген 1' if is_ru else 'Gene 1'), 'sequence': seq[:half]},
            {'name': ('Ген 2' if is_ru else 'Gene 2'), 'sequence': seq[half:]},
        ]
        r = design_multiplexed_guides(targets, enzyme=state.get('enzyme', 'SpCas9'))
        lines = [
            (('Multiplex CRISPR — много генов\n' if is_ru
              else 'Multiplex CRISPR — many genes\n'), 'ttl'),
            ('-' * 30 + '\n', 'dim'),
            (('Целей: {} | спроектировано: {}\n\n'.format(r['n_targets'], r['n_designed'])
              if is_ru else
              'Targets: {} | designed: {}\n\n'.format(r['n_targets'], r['n_designed'])), 'ok'),
        ]
        for g in r['guides']:
            if g['guide']:
                lines.append((g['target'] + ':\n', 'nrm'))
                lines.append((g['guide'] + '  ', 'mono'))
                lines.append(('(s={:.0f})\n'.format(g['score']), 'dim'))
            else:
                lines.append((g['target'] + ': ' + ('нет гайда\n' if is_ru else 'no guide\n'), 'bad'))
        if r['warnings']:
            lines.append(('\n⚠ ' + ('Предупреждения:' if is_ru else 'Warnings:') + '\n', 'wrn'))
            for w in r['warnings']:
                lines.append(('  ' + w + '\n', 'wrn'))
        lines.append((('\n💡 Multiplex редактирует несколько генов\n'
                       'одновременно одной доставкой.'
                       if is_ru else
                       '\n💡 Multiplex edits several genes at once\n'
                       'in a single delivery.'), 'dim'))
        self._set_text(self.crispr_info, lines)

    def _crispr_target_selected(self, _event):
        tbl = getattr(self, 'crispr_table', None)
        if tbl is None:
            return
        sel = tbl.selection()
        if not sel:
            return
        idx = self._crispr_row_index.get(sel[0])
        if idx is None:
            return
        state = self.current_state['crispr']
        targets = state.get('targets', [])
        if idx >= len(targets):
            return
        state['selected_target'] = targets[idx]
        self._crispr_show_target_info(targets[idx])
        self._crispr_render_sequence()
        # Redraw the guide map so the selected guide is highlighted
        try:
            self._crispr_draw_guide_map()
        except Exception as _exc:
            biosim_log('warn', '_crispr_target_selected: {}'.format(_exc))

    def _crispr_guide_context(self, target, seq):
        """Return the 30-mer around a guide (4 nt upstream + 20 + PAM + 3),
        which is the window Doench and Moreno-Mateos are defined on."""
        try:
            guide = target['guide']
            pos = target.get('position', 0)
            glen = len(guide)
            if target.get('strand', '+') == '+':
                start = pos - 4
                end = pos + glen + len(target.get('pam', '')) + 3
                if start < 0 or end > len(seq):
                    return guide
                return seq[start:end]
            rc = reverse_complement(seq)
            rpos = len(seq) - pos - glen
            start = rpos - 4
            end = rpos + glen + len(target.get('pam', '')) + 3
            if start < 0 or end > len(rc):
                return guide
            return rc[start:end]
        except Exception as exc:
            biosim_log('warn', '_crispr_guide_context: {}'.format(exc))
            return target.get('guide', '')

    def _crispr_guide_context_n(self, target, seq, up=6, down=6):
        """Return the guide context with `up` nt of 5' flank and `down` nt of
        3' flank (after the PAM). With up=6, down=6 this yields the 35-mer that
        CRISPRScan/Moreno-Mateos is defined on (6 + 20 + 3 PAM + 6). Returns
        None if the full window doesn't fit (caller then falls back)."""
        try:
            guide = target['guide']
            pos = target.get('position', 0)
            glen = len(guide)
            pamlen = len(target.get('pam', ''))
            if target.get('strand', '+') == '+':
                start = pos - up
                end = pos + glen + pamlen + down
                if start < 0 or end > len(seq):
                    return None
                return seq[start:end]
            rc = reverse_complement(seq)
            rpos = len(seq) - pos - glen
            start = rpos - up
            end = rpos + glen + pamlen + down
            if start < 0 or end > len(rc):
                return None
            return rc[start:end]
        except Exception as exc:
            biosim_log('warn', '_crispr_guide_context_n: {}'.format(exc))
            return None

    def _crispr_show_target_info(self, target):
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        enz = state.get('enzyme', 'SpCas9')
        guide = target['guide']
        is_ru = (self.lang == 'ru')
        # Make sure the CRISPOR score bundle is available (it is, if the guide
        # came from the table; recompute defensively for undo/load snapshots).
        if not target.get('_scored') and seq:
            try:
                self._crispr_compute_guide_scores(target, seq, enz)
            except Exception as _exc:
                biosim_log('warn', '_crispr_show_target_info: {}'.format(_exc))
        sc = target.get('scores') or {}
        ot = target.get('offtargets') or calc_off_targets(guide, seq, max_mismatches=3)
        cut_offset = CRISPR_ENZYMES.get(enz, {}).get('cut_offset', -3)
        cut_pos = target['position'] + len(guide) + cut_offset

        def band(v, good, ok_):
            if v is None:
                return 'dim'
            return 'ok' if v >= good else ('wrn' if v >= ok_ else 'bad')

        info = [
            (self._t('selected_target') + '\n', 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (self._t('strand') + ' ' + target['strand'] + '\n', 'nrm'),
            (self._t('position') + ' {} bp\n'.format(target['position']), 'nrm'),
            (self._t('cut_site') + ' ~{} bp\n'.format(cut_pos), 'nrm'),
            ('\n' + self._t('guide_rna') + '\n', 'ttl'),
            ('  ' + guide + '\n', 'mono'),
            ('  PAM: ' + target['pam'] + '\n', 'mono'),
            ('  ' + self._t('gc_label') + ' {}%\n'.format(target['gc']),
             'ok' if 40 <= target['gc'] <= 60 else 'wrn'),
        ]

        # ── on-target efficiency (real CRISPOR models) ──
        doench = sc.get('doench')
        cscan = sc.get('crisprscan')
        oof = sc.get('oof')
        info.append(('\n' + ('Эффективность реза' if is_ru
                             else 'Cutting efficiency') + '\n', 'ttl'))
        if doench is not None:
            info.append(('  Doench 2014: {:.0f}/100\n'.format(doench),
                         band(doench, 60, 40)))
        if cscan is not None:
            info.append(('  CRISPRScan (T7): {:.0f}/100\n'.format(cscan),
                         band(cscan, 55, 35)))
            info.append((('    для гРНК, наработанной in vitro (T7)\n' if is_ru
                          else '    for in-vitro (T7) transcribed gRNA\n'), 'dim'))
        if oof is not None:
            info.append((('  Сдвиг рамки (нокаут): {:.0f}/100\n'.format(oof)
                          if is_ru else
                          '  Out-of-frame (knockout): {:.0f}/100\n'.format(oof)),
                         band(oof, 55, 40)))

        # ── specificity (MIT/Hsu + CFD Doench 2016) ──
        spec = sc.get('mit_spec')
        cfd_spec = sc.get('cfd_spec')
        worst = sc.get('worst_ot')
        info.append(('\n' + ('Специфичность' if is_ru else 'Specificity')
                     + '\n', 'ttl'))
        if spec is not None:
            info.append(('  MIT/Hsu: {:.0f}/100\n'.format(spec),
                         band(spec, 70, 50)))
        if cfd_spec is not None:
            info.append(('  CFD (Doench 2016): {:.0f}/100\n'.format(cfd_spec),
                         band(cfd_spec, 70, 50)))
        if spec is not None:
            if worst:
                info.append((('  Худший офф-таргет: {} ({} несовп., hit {:.1f})\n'
                              .format(worst['seq'], worst['mismatches'], worst['hit'])
                              if is_ru else
                              '  Worst off-target: {} ({} mm, hit {:.1f})\n'
                              .format(worst['seq'], worst['mismatches'], worst['hit'])),
                             'bad' if worst['hit'] > 5 else 'wrn'))
            else:
                info.append((('  Значимых офф-таргетов не найдено\n' if is_ru
                              else '  No significant off-targets found\n'), 'ok'))
            info.append((('    (поиск только по загруженной\n'
                          '     последовательности, не по геному)\n' if is_ru else
                          '    (searched within the loaded\n'
                          '     sequence only, not the genome)\n'), 'dim'))

        # ── off-target mismatch counts ──
        info.append(('\n' + self._t('off_targets') + '\n', 'ttl'))
        info.append(('  0 ' + self._t('mm') + ' {}\n'.format(ot['count_0mm']),
                     'bad' if ot['count_0mm'] > 0 else 'ok'))
        info.append(('  1 ' + self._t('mm') + ' {}\n'.format(ot['count_1mm']),
                     'wrn' if ot['count_1mm'] > 0 else 'ok'))
        info.append(('  2 ' + self._t('mm') + ' {}\n'.format(ot['count_2mm']), 'dim'))
        info.append(('  3 ' + self._t('mm') + ' {}\n'.format(ot['count_3mm']), 'dim'))

        # ── restriction sites near the cut (CRISPOR: useful for genotyping
        #    by loss of a restriction site after editing) ──
        try:
            win_start = max(0, cut_pos - 12)
            win_end = min(len(seq), cut_pos + 12)
            window = seq[win_start:win_end]
            rsites = find_restriction_sites(window, check_both_strands=True)
            if rsites:
                info.append(('\n' + ('Рестрикция у разреза' if is_ru
                                     else 'Restriction at cut') + '\n', 'ttl'))
                seen = set()
                for rs in rsites[:6]:
                    key = (rs['enzyme'], rs['position'])
                    if key in seen:
                        continue
                    seen.add(key)
                    abs_pos = win_start + rs['position']
                    info.append(('  {} @ {} bp ({})\n'.format(
                        rs['enzyme'], abs_pos, rs['site_seq']), 'mono'))
                info.append((('    редактирование может убрать сайт →\n'
                              '    удобно для проверки (RFLP)\n' if is_ru else
                              '    editing may destroy the site →\n'
                              '    handy for genotyping (RFLP)\n'), 'dim'))
        except Exception as _exc:
            biosim_log('warn', '_crispr restriction: {}'.format(_exc))

        if state['edits']:
            info.append(('\n' + self._t('edit_history') + '\n', 'ttl'))
            for e in state['edits']:
                info.append(('  ' + e + '\n', 'nrm'))
        self._set_text(self.crispr_info, info)

    def _crispr_render_sequence(self):
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        if not seq:
            self._set_seq_view([('No sequence.\n', 'normal')])
            return
        target = state.get('selected_target')
        segments = [("5' - ", 'header')]
        if target:
            pos = target['position']
            guide_len = len(target['guide'])
            pam_len = len(target['pam'])
            if target['strand'] == '+':
                guide_start = pos
                guide_end = pos + guide_len
                pam_start = guide_end
                pam_end = pam_start + pam_len
            else:
                guide_end = len(seq) - pos
                guide_start = guide_end - guide_len
                pam_end = guide_start
                pam_start = pam_end - pam_len
            ctx_start = max(0, min(guide_start, pam_start) - 60)
            ctx_end = min(len(seq), max(guide_end, pam_end) + 60)
            for i in range(ctx_start, ctx_end):
                ch = seq[i]
                if i > ctx_start and (i - ctx_start) % 60 == 0:
                    segments.append(('\n', 'normal'))
                if guide_start <= i < guide_end:
                    segments.append((ch, 'guide'))
                elif pam_start <= i < pam_end:
                    segments.append((ch, 'pam'))
                else:
                    segments.append((ch, 'normal'))
            segments.append(('\n\n' + (
                'Синий=guide, Красный=PAM\n' if self.lang == 'ru'
                else 'Blue=guide, Red=PAM\n'), 'header'))
        else:
            shown = seq[:500]
            for i, ch in enumerate(shown):
                if i > 0 and i % 60 == 0:
                    segments.append(('\n', 'normal'))
                segments.append((ch, 'normal'))
            if len(seq) > 500:
                segments.append(('\n... ({} bp)\n'.format(len(seq)), 'header'))
            else:
                segments.append(('\n', 'normal'))
        self._set_seq_view(segments)

    def _crispr_refresh(self):
        state = self.current_state['crispr']
        seq = state.get('sequence', '')
        enz = state.get('enzyme', 'SpCas9')
        targets = state.get('targets', [])
        # Ensure every target carries its CRISPOR score bundle (older saves /
        # undo snapshots may predate scoring — compute lazily here).
        if seq:
            for t in targets:
                if not t.get('_scored'):
                    try:
                        self._crispr_compute_guide_scores(t, seq, enz)
                    except Exception as _exc:
                        biosim_log('warn', '_crispr_refresh: {}'.format(_exc))
        self._crispr_fill_table(targets)
        self._crispr_render_sequence()

    def _crispr_apply_edit(self):
        state = self.current_state['crispr']
        target = state.get('selected_target')
        if not target:
            messagebox.showinfo('VIREON', self._t('select_guide_first'))
            return
        seq = state.get('sequence', '')
        if not seq:
            return
        self._save_history('crispr')
        edit_type = self.crispr_edit_type.get()
        insert_seq = self.crispr_insert_seq.get().strip()
        cut_offset = CRISPR_ENZYMES[state['enzyme']]['cut_offset']
        cut_pos = target['position'] + len(target['guide']) + cut_offset
        new_seq, msg = apply_crispr_edit(seq, cut_pos, edit_type, insert_seq, target['strand'])
        state['sequence'] = new_seq
        state['edits'].append('{}: {} at {}'.format(edit_type, msg, cut_pos))
        state['targets'] = find_crispr_targets(new_seq, enzyme=state['enzyme'], max_sites=200)
        state['selected_target'] = None
        self._crispr_refresh()
        self._set_text(self.crispr_info, [
            (self._t('edit_applied') + '\n', 'ttl'),
            ('-' * 26 + '\n', 'dim'),
            (msg + '\n', 'ok'),
            (self._t('new_length') + ' {} bp\n'.format(len(new_seq)), 'nrm'),
            (self._t('new_gc') + ' {}%\n\n'.format(gc_content(new_seq)), 'nrm'),
            (self._t('edit_history') + '\n', 'ttl'),
            *[('  ' + e + '\n', 'nrm') for e in state['edits']],
            ('\n' + self._t('rescan_hint') + '\n', 'wrn')])

    def _crispr_revert(self):
        state = self.current_state['crispr']
        if not state.get('original'):
            return
        if not messagebox.askyesno('VIREON', self._t('revert_confirm')):
            return
        self._save_history('crispr')
        state['sequence'] = state['original']
        state['edits'] = []
        state['targets'] = []
        state['selected_target'] = None
        self._crispr_refresh()
        self._set_text(self.crispr_info, [
            (self._t('reverted') + '\n', 'ttl'),
            (self._t('length') + ' {} bp\n'.format(len(state['sequence'])), 'nrm')])

    # ── HISTORY ──
    def _save_history(self, tab):
        import copy
        # Be robust if a tab key wasn't pre-initialized
        if tab not in self.history:
            self.history[tab] = []
        if tab not in self.future:
            self.future[tab] = []
        if self.current_state.get(tab) is not None:
            self.history[tab].append(copy.deepcopy(self.current_state[tab]))
            if len(self.history[tab]) > 50:
                self.history[tab] = self.history[tab][-50:]
        self.future[tab] = []

    def _on_back(self):
        tab = self.active_tab
        if not self.history[tab]:
            messagebox.showinfo('VIREON', self._t('nothing_undo'))
            return
        import copy
        if self.current_state[tab] is not None:
            self.future[tab].append(copy.deepcopy(self.current_state[tab]))
        self.current_state[tab] = self.history[tab].pop()
        self._refresh_active_tab()

    def _on_forward(self):
        tab = self.active_tab
        if not self.future[tab]:
            messagebox.showinfo('VIREON', self._t('nothing_redo'))
            return
        import copy
        if self.current_state[tab] is not None:
            self.history[tab].append(copy.deepcopy(self.current_state[tab]))
        self.current_state[tab] = self.future[tab].pop()
        self._refresh_active_tab()

    def _refresh_active_tab(self):
        if self.active_tab == 'constructor':
            self._cons_refresh()
        elif self.active_tab == 'crispr':
            self._crispr_refresh()
        elif self.active_tab == 'metabolic':
            self._metab_refresh()

    def _on_history(self):
        tab = self.active_tab
        win = tk.Toplevel(self)
        win.title(self._t('history_window') + tab)
        win.geometry('420x420')
        win.configure(bg=biosim_theme('bg'))
        tk.Label(win, text=self._t('history'), font=('Arial', 12, 'bold'),
                 bg=biosim_theme('bg'), fg='#0550ae').pack(pady=8)
        lb = tk.Listbox(win, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                         selectbackground='#0969da', font=('Arial', 10),
                         relief='flat', highlightthickness=0)
        lb.pack(fill='both', expand=True, padx=10, pady=4)
        items = list(reversed(self.history[tab]))
        for i, item in enumerate(items):
            label = '{}: {}'.format(i + 1, item.get('name', '?')[:30])
            lb.insert('end', label)
        if not items:
            lb.insert('end', self._t('empty_hist'))
        def restore():
            sel = lb.curselection()
            if not sel: return
            idx = sel[0]
            if idx < len(items):
                import copy
                self._save_history(tab)
                self.current_state[tab] = copy.deepcopy(items[idx])
                self._refresh_active_tab()
                win.destroy()
        tk.Button(win, text=self._t('restore'), bg='#1a7f37', highlightbackground='#1a7f37', fg='white',
                   relief='flat', font=('Arial', 11, 'bold'), cursor='hand2',
                   pady=6, command=restore).pack(fill='x', padx=10, pady=8)

    def _on_save(self):
        tab = self.active_tab
        state = self.current_state[tab]
        if state is None:
            return
        from datetime import datetime
        date_str = datetime.now().strftime('%Y-%m-%d_%H%M%S')
        name_safe = ''.join(c if c.isalnum() else '_' for c in state.get('name', tab)[:30])
        filename = '{}_{}_{}.json'.format(tab, name_safe, date_str)
        wrapped = {'tab': tab, 'saved_at': date_str, 'state': state}
        path = save_to_json(filename, wrapped)
        if path:
            messagebox.showinfo('VIREON', self._t('saved_to') + path)

    def _on_load(self):
        tab = self.active_tab
        files = list_saves(tab + '_')
        if not files:
            messagebox.showinfo('VIREON', self._t('no_saves') + tab)
            return
        win = tk.Toplevel(self)
        win.title(self._t('load_window'))
        win.geometry('500x420')
        win.configure(bg=biosim_theme('bg'))
        tk.Label(win, text=self._t('saved_files'), font=('Arial', 12, 'bold'),
                 bg=biosim_theme('bg'), fg='#9a6700').pack(pady=8)
        lb = tk.Listbox(win, bg=biosim_theme('panel2'), fg=biosim_theme('text'),
                         selectbackground='#0969da', font=('Arial', 10),
                         relief='flat', highlightthickness=0)
        lb.pack(fill='both', expand=True, padx=10, pady=4)
        for f in files:
            lb.insert('end', f)
        def do_load():
            sel = lb.curselection()
            if not sel: return
            fname = files[sel[0]]
            data = load_from_json(fname)
            if data and 'state' in data:
                self._save_history(tab)
                self.current_state[tab] = data['state']
                self._refresh_active_tab()
                win.destroy()
        tk.Button(win, text=self._t('load_btn'), bg=biosim_theme('panel'), highlightbackground='#1c2128', fg=biosim_theme('text'),
                   relief='solid', bd=1, font=('Arial', 11, 'bold'), cursor='hand2',
                   pady=6, command=do_load).pack(fill='x', padx=10, pady=8)

    def _set_text(self, widget, lines):
        widget.config(state='normal')
        widget.delete('1.0', 'end')
        for txt, tag in lines:
            widget.insert('end', txt, tag)
        widget.config(state='disabled')


