# Restriction enzymes (most common — full set added in Mol-3)
RESTRICTION_ENZYMES = {
    'EcoRI':    {'site': 'GAATTC', 'cut': 1,  'overhang': "5'", 'organism': 'E. coli'},
    'BamHI':    {'site': 'GGATCC', 'cut': 1,  'overhang': "5'", 'organism': 'B. amyloliquefaciens'},
    'HindIII':  {'site': 'AAGCTT', 'cut': 1,  'overhang': "5'", 'organism': 'H. influenzae'},
    'NotI':     {'site': 'GCGGCCGC', 'cut': 2, 'overhang': "5'", 'organism': 'N. otitidiscaviarum'},
    'XhoI':     {'site': 'CTCGAG', 'cut': 1,  'overhang': "5'", 'organism': 'X. holcicola'},
    'SalI':     {'site': 'GTCGAC', 'cut': 1,  'overhang': "5'", 'organism': 'S. albus'},
    'KpnI':     {'site': 'GGTACC', 'cut': 5,  'overhang': "3'", 'organism': 'K. pneumoniae'},
    'PstI':     {'site': 'CTGCAG', 'cut': 5,  'overhang': "3'", 'organism': 'P. stuartii'},
    'SmaI':     {'site': 'CCCGGG', 'cut': 3,  'overhang': 'blunt', 'organism': 'S. marcescens'},
    'EcoRV':    {'site': 'GATATC', 'cut': 3,  'overhang': 'blunt', 'organism': 'E. coli'},
    'NcoI':     {'site': 'CCATGG', 'cut': 1,  'overhang': "5'", 'organism': 'N. corallina'},
    'NdeI':     {'site': 'CATATG', 'cut': 2,  'overhang': "5'", 'organism': 'N. denitrificans'},
    'XbaI':     {'site': 'TCTAGA', 'cut': 1,  'overhang': "5'", 'organism': 'X. badrii'},
    'SpeI':     {'site': 'ACTAGT', 'cut': 1,  'overhang': "5'", 'organism': 'S. pneumoniae'},
    'BglII':    {'site': 'AGATCT', 'cut': 1,  'overhang': "5'", 'organism': 'B. globigii'},
    'AvrII':    {'site': 'CCTAGG', 'cut': 1,  'overhang': "5'", 'organism': 'A. variabilis'},
    'NheI':     {'site': 'GCTAGC', 'cut': 1,  'overhang': "5'", 'organism': 'N. heterostrophus'},
    'ApaI':     {'site': 'GGGCCC', 'cut': 5,  'overhang': "3'", 'organism': 'A. pulvinata'},
    'SacI':     {'site': 'GAGCTC', 'cut': 5,  'overhang': "3'", 'organism': 'S. achromogenes'},
    'BsaI':     {'site': 'GGTCTC', 'cut': 7,  'overhang': "5'", 'organism': 'B. stearothermophilus'},
}


def reverse_complement(seq):
    """Return reverse complement of DNA sequence."""
    comp = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G',
            'N': 'N', 'U': 'A',
            'a': 't', 't': 'a', 'g': 'c', 'c': 'g',
            'n': 'n', 'u': 'a',
            'R': 'Y', 'Y': 'R', 'S': 'S', 'W': 'W',
            'K': 'M', 'M': 'K', 'B': 'V', 'D': 'H',
            'H': 'D', 'V': 'B'}
    return ''.join(comp.get(c, c) for c in reversed(seq))


def transcribe_dna_to_rna(seq):
    """DNA RNA (T U)."""
    return seq.upper().replace('T', 'U')


def translate_dna(seq, frame=0, table=None):
    """Translate DNA sequence to amino acid sequence.
    
    frame: 0, 1, or 2 (offset from start)
    table: codon table dict (default GENETIC_CODE)
    
    Returns amino acid string with '*' for stop codons.
    """
    if table is None:
        table = GENETIC_CODE
    seq = seq.upper().replace('U', 'T')
    seq = seq[frame:]
    protein = []
    for i in range(0, len(seq) - 2, 3):
        codon = seq[i:i+3]
        if len(codon) < 3:
            break
        aa = table.get(codon, 'X')  # X for unknown
        protein.append(aa)
    return ''.join(protein)


def translate_six_frames(seq):
    """Translate in all 6 reading frames (3 forward + 3 reverse).
    Returns list of 6 amino acid strings.
    """
    forward = [translate_dna(seq, f) for f in (0, 1, 2)]
    rc = reverse_complement(seq)
    reverse = [translate_dna(rc, f) for f in (0, 1, 2)]
    return forward + reverse


def find_orfs(seq, min_length=30, both_strands=True):
    """Find Open Reading Frames in DNA sequence.
    
    Returns list of dicts:
        {start, end, frame, strand ('+' or '-'),
         length_nt, length_aa, sequence, protein}
    
    min_length: minimum ORF length in amino acids (default 30 AA = 90 nt)
    """
    seq = seq.upper().replace('U', 'T')
    orfs = []
    
    strands = [('+', seq)]
    if both_strands:
        strands.append(('-', reverse_complement(seq)))
    
    for strand, s in strands:
        for frame in (0, 1, 2):
            i = frame
            while i < len(s) - 2:
                codon = s[i:i+3]
                if codon == 'ATG':  # start codon
                    # Find stop codon in frame
                    start = i
                    end = -1
                    j = i
                    while j < len(s) - 2:
                        c = s[j:j+3]
                        if c in ('TAA', 'TAG', 'TGA'):
                            end = j + 3
                            break
                        j += 3
                    if end > 0:
                        length_nt = end - start
                        if length_nt // 3 - 1 >= min_length:  # excl stop
                            orf_seq = s[start:end]
                            protein = translate_dna(orf_seq, 0).rstrip('*')
                            orfs.append({
                                'start': start if strand == '+' else len(seq) - end,
                                'end': end if strand == '+' else len(seq) - start,
                                'frame': frame + 1 if strand == '+' else -(frame + 1),
                                'strand': strand,
                                'length_nt': length_nt,
                                'length_aa': len(protein),
                                'sequence': orf_seq,
                                'protein': protein,
                            })
                        i = end
                    else:
                        i += 3
                else:
                    i += 3
    
    # Sort by length descending
    orfs.sort(key=lambda o: -o['length_aa'])
    return orfs


def gc_content(seq):
    """GC content as percentage."""
    if not seq:
        return 0.0
    seq = seq.upper()
    gc = seq.count('G') + seq.count('C')
    return 100 * gc / len(seq)


def gc_content_sliding(seq, window=50, step=10):
    """Sliding window GC content. Returns list of (position, gc%)."""
    points = []
    if len(seq) < window:
        return [(0, gc_content(seq))]
    for i in range(0, len(seq) - window + 1, step):
        sub = seq[i:i+window]
        points.append((i + window // 2, gc_content(sub)))
    return points


def molecular_weight_dna(seq):
    """Molecular weight of double-stranded DNA in Da.

    Uses the standard approximation 650 Da per base pair (dsDNA).
    For single-stranded DNA, divide by ~2 (~325 Da/nt).
    """
    return len(seq) * 650.0


def molecular_weight_protein(protein):
    """Molecular weight of protein in Da (sum of AA MW minus water)."""
    total = 0
    for aa in protein:
        if aa in AA_PROPERTIES and aa != '*':
            total += AA_PROPERTIES[aa]['mw']
    # Subtract water for each peptide bond (n-1)
    if len(protein) > 1:
        total -= (len(protein) - 1) * 18.02
    return total


def detect_sequence_type(seq):
    """Detect if sequence is DNA, RNA, or protein."""
    if not seq:
        return 'dna'
    seq_u = seq.upper()
    chars = set(seq_u) - {'N', '*', '-', ' ', '\n'}
    dna_chars = set('ACGT')
    rna_chars = set('ACGU')
    protein_chars = set('ACDEFGHIKLMNPQRSTVWY')
    
    if chars <= dna_chars:
        return 'dna'
    if chars <= rna_chars and 'U' in chars:
        return 'rna'
    # If contains characters specific to protein (E, F, I, L, P, Q, etc.)
    protein_specific = chars - set('ACGTU')
    if protein_specific and protein_specific <= protein_chars:
        return 'protein'
    return 'dna'  # fallback



# ═══════════════════════════════════════════════════
# PRIMER DESIGN — Mol-2
# Tm calculation, GC, hairpins, primer-dimer detection
# ═══════════════════════════════════════════════════

# Nearest-neighbor thermodynamic parameters (SantaLucia 1998, unified)
# in kcal/mol — ΔH (enthalpy) and ΔS (entropy)
NN_PARAMS = {
    'AA': {'dH': -7.9, 'dS': -22.2}, 'TT': {'dH': -7.9, 'dS': -22.2},
    'AT': {'dH': -7.2, 'dS': -20.4}, 'TA': {'dH': -7.2, 'dS': -21.3},
    'CA': {'dH': -8.5, 'dS': -22.7}, 'TG': {'dH': -8.5, 'dS': -22.7},
    'GT': {'dH': -8.4, 'dS': -22.4}, 'AC': {'dH': -8.4, 'dS': -22.4},
    'CT': {'dH': -7.8, 'dS': -21.0}, 'AG': {'dH': -7.8, 'dS': -21.0},
    'GA': {'dH': -8.2, 'dS': -22.2}, 'TC': {'dH': -8.2, 'dS': -22.2},
    'CG': {'dH': -10.6, 'dS': -27.2}, 'GC': {'dH': -9.8, 'dS': -24.4},
    'GG': {'dH': -8.0, 'dS': -19.9}, 'CC': {'dH': -8.0, 'dS': -19.9},
}


def calculate_tm_wallace(seq):
    """Simple Wallace rule: 2*(A+T) + 4*(G+C). Good for primers <14 nt."""
    if not seq:
        return 0.0
    seq = seq.upper()
    at = seq.count('A') + seq.count('T') + seq.count('U')
    gc = seq.count('G') + seq.count('C')
    return 2 * at + 4 * gc


def calculate_tm_gc(seq, na_conc=0.05):
    """GC%-based Tm. Marmur 1962: Tm = 64.9 + 41*(GC-16.4)/N
    na_conc: monovalent salt concentration in M (default 50 mM)
    """
    if not seq or len(seq) < 8:
        return calculate_tm_wallace(seq)
    seq = seq.upper()
    n = len(seq)
    gc = seq.count('G') + seq.count('C')
    tm = 64.9 + 41 * (gc - 16.4) / n
    # Salt correction
    if na_conc > 0:
        tm += 16.6 * math.log10(na_conc / 0.05)
    return tm


def calculate_tm_nn(seq, na_conc=0.05, primer_conc=0.5e-6):
    """Nearest-neighbor Tm (most accurate).
    SantaLucia 1998 unified parameters.
    
    na_conc: salt in M (0.05 = 50 mM)
    primer_conc: primer concentration in M (0.5e-6 = 500 nM)
    """
    seq = seq.upper().replace('U', 'T')
    if len(seq) < 8:
        return calculate_tm_wallace(seq)
    
    # Sum ΔH and ΔS over neighbors
    dH = 0.0
    dS = 0.0
    for i in range(len(seq) - 1):
        pair = seq[i:i+2]
        if pair in NN_PARAMS:
            dH += NN_PARAMS[pair]['dH']
            dS += NN_PARAMS[pair]['dS']
    
    # Initiation corrections
    # GC initiation: ΔH=+0.1, ΔS=-2.8
    # AT initiation: ΔH=+2.3, ΔS=+4.1
    if seq[0] in 'AT':
        dH += 2.3; dS += 4.1
    else:
        dH += 0.1; dS -= 2.8
    if seq[-1] in 'AT':
        dH += 2.3; dS += 4.1
    else:
        dH += 0.1; dS -= 2.8
    
    # Tm = ΔH / (ΔS + R * ln(Ct/x)) - 273.15
    # x = 4 for non-self-complementary
    R = 1.987  # cal/(mol·K)
    if dS == 0:
        return 0.0
    try:
        tm_K = (dH * 1000) / (dS + R * math.log(primer_conc / 4))
        tm_C = tm_K - 273.15
        # Salt correction (SantaLucia 1998)
        tm_C += 16.6 * math.log10(na_conc / 1.0)
        return tm_C
    except Exception as _exc:
        biosim_log('warn', 'calculate_tm_nn: {}'.format(_exc))
        return calculate_tm_gc(seq, na_conc)


def find_hairpins(seq, min_stem=4, min_loop=3, max_loop=10):
    """Find potential hairpin structures in a primer.
    
    A hairpin forms when a sequence can fold back on itself —
    the 3' end pairs with the 5' end forming a stem and loop.
    
    Returns list of dicts:
        {start, end, stem_length, loop_length, dG_estimate}
    """
    seq = seq.upper()
    n = len(seq)
    hairpins = []
    rc = reverse_complement(seq)
    
    for i in range(n - min_stem - min_loop - min_stem + 1):
        for j in range(i + min_stem + min_loop, min(n, i + min_stem + max_loop + min_stem) + 1):
            for stem_len in range(min_stem, min(8, n - j + 1, j - i - min_loop) + 1):
                if i + stem_len + min_loop > j:
                    continue
                if j + stem_len > n:
                    continue
                # 5' arm: seq[i:i+stem_len]
                # 3' arm: seq[j:j+stem_len]
                # For hairpin: 5' arm reverse-complement should match 3' arm
                left = seq[i:i+stem_len]
                right = seq[j:j+stem_len]
                if reverse_complement(left) == right:
                    loop = j - (i + stem_len)
                    # Rough ΔG estimate: -2 kcal/mol per matched pair
                    dG = -2.0 * stem_len + 0.5 * loop
                    hairpins.append({
                        'start': i, 'end': j + stem_len,
                        'stem_length': stem_len,
                        'loop_length': loop,
                        'dG_estimate': dG,
                        'left': left, 'right': right,
                    })
    # Deduplicate, keep best per region
    if not hairpins:
        return []
    seen = set()
    unique = []
    for h in sorted(hairpins, key=lambda x: x['dG_estimate']):
        key = (h['start'], h['end'])
        if key not in seen:
            seen.add(key)
            unique.append(h)
    return unique[:5]


def find_dimers(seq1, seq2, min_match=4):
    """Find complementarity between two primers (primer-dimer).
    
    Returns list of dicts:
        {seq1_pos, seq2_pos, match_length, is_3_end, dG_estimate}
    
    is_3_end: True if matching includes 3' end (most problematic for PCR)
    """
    s1 = seq1.upper()
    s2 = seq2.upper()
    s2_rc = reverse_complement(s2)
    dimers = []
    
    for i in range(len(s1) - min_match + 1):
        for j in range(len(s2_rc) - min_match + 1):
            # Try extending match starting at (i, j)
            match_len = 0
            while (i + match_len < len(s1) and
                     j + match_len < len(s2_rc) and
                     s1[i + match_len] == s2_rc[j + match_len]):
                match_len += 1
            if match_len >= min_match:
                # Check if 3' end involved (last 5 bases)
                s1_3end = i + match_len >= len(s1) - 2
                s2_3end = j == 0  # s2_rc[0] corresponds to s2's 3' end
                is_3 = s1_3end or s2_3end
                dG = -2.0 * match_len  # rough estimate
                dimers.append({
                    'seq1_pos': i,
                    'seq2_pos': len(s2) - 1 - j - match_len + 1,
                    'match_length': match_len,
                    'is_3_end': is_3,
                    'dG_estimate': dG,
                    'matched_seq': s1[i:i+match_len],
                })
    # Deduplicate
    if not dimers:
        return []
    seen = set()
    unique = []
    for d in sorted(dimers, key=lambda x: x['dG_estimate']):
        key = (d['seq1_pos'], d['seq2_pos'], d['match_length'])
        if key not in seen:
            seen.add(key)
            unique.append(d)
    return unique[:5]


def check_3prime_clamp(seq, n_last=5):
    """Check 3' end for GC clamp.
    Ideal: 1-2 GC in last 5 bases. Too few = unstable. Too many = mispriming.
    Returns: dict with gc_count, status ('ok'/'weak'/'too_high')
    """
    if len(seq) < n_last:
        return {'gc_count': 0, 'status': 'too_short'}
    last = seq[-n_last:].upper()
    gc = last.count('G') + last.count('C')
    if gc == 0:
        status = 'weak'
    elif gc <= 2:
        status = 'ok'
    elif gc <= 3:
        status = 'acceptable'
    else:
        status = 'too_high'
    return {'gc_count': gc, 'last_bases': last, 'status': status}


def score_primer(seq, tm_target=60, na_conc=0.05):
    """Score a primer candidate. Higher = better.
    
    Returns dict with all properties + total score (0-100).
    """
    n = len(seq)
    if n < 15 or n > 35:
        return None
    
    tm = calculate_tm_nn(seq, na_conc=na_conc)
    gc = gc_content(seq)
    hairpins = find_hairpins(seq)
    self_dimers = find_dimers(seq, seq, min_match=4)
    clamp = check_3prime_clamp(seq)
    
    # Scoring
    score = 100.0
    
    # Length penalty (18-25 ideal)
    if 18 <= n <= 25:
        pass
    elif 15 <= n <= 30:
        score -= 5
    else:
        score -= 15
    
    # Tm deviation from target
    tm_diff = abs(tm - tm_target)
    if tm_diff > 5:
        score -= min(30, tm_diff * 2)
    elif tm_diff > 2:
        score -= tm_diff * 2
    
    # GC content (40-60% ideal)
    if 40 <= gc <= 60:
        pass
    elif 30 <= gc <= 70:
        score -= 10
    else:
        score -= 25
    
    # 3' clamp
    if clamp['status'] == 'too_high':
        score -= 15
    elif clamp['status'] == 'weak':
        score -= 10
    elif clamp['status'] == 'acceptable':
        score -= 5
    
    # Hairpins
    if hairpins:
        worst_dG = min(h['dG_estimate'] for h in hairpins)
        if worst_dG < -10:
            score -= 25
        elif worst_dG < -5:
            score -= 15
        else:
            score -= 5
    
    # Self-dimers
    if self_dimers:
        worst_3end = any(d['is_3_end'] and d['match_length'] >= 4
                            for d in self_dimers)
        if worst_3end:
            score -= 20
        else:
            score -= 5
    
    # Runs of same base (e.g., AAAAA)
    for base in 'ATGC':
        if base * 5 in seq.upper():
            score -= 15
            break
    
    score = max(0, min(100, score))
    
    return {
        'sequence': seq,
        'length': n,
        'tm': tm,
        'tm_wallace': calculate_tm_wallace(seq),
        'tm_gc': calculate_tm_gc(seq, na_conc=na_conc),
        'gc_content': gc,
        'hairpins': hairpins,
        'self_dimers': self_dimers,
        'clamp': clamp,
        'score': score,
    }


def design_primer_pair(template, target_start, target_end,
                          primer_length=(18, 25),
                          tm_range=(55, 65),
                          tm_diff_max=3.0,
                          gc_range=(40, 60),
                          na_conc=0.05):
    """Design forward and reverse primers to amplify target region.
    
    template: DNA sequence
    target_start, target_end: region to amplify (0-indexed)
    primer_length: (min, max) primer length
    tm_range: (min, max) acceptable Tm
    tm_diff_max: max difference between forward/reverse Tm
    
    Returns list of dicts (sorted by combined score):
        {'forward': {...}, 'reverse': {...}, 'product_length': N,
         'combined_score': float, 'tm_diff': float}
    """
    template = template.upper().replace('U', 'T')
    if target_end > len(template):
        target_end = len(template)
    if target_start < 0:
        target_start = 0
    
    # Search forward primers in region around target_start
    fw_candidates = []
    # Search window: 50 bp before target_start (for upstream) to target_start+50
    search_start_fw = max(0, target_start - 30)
    search_end_fw = min(len(template), target_start + 30)
    
    for start in range(search_start_fw, search_end_fw):
        for length in range(primer_length[0], primer_length[1] + 1):
            if start + length > len(template):
                continue
            primer = template[start:start+length]
            s = score_primer(primer, tm_target=sum(tm_range) / 2, na_conc=na_conc)
            if s is None:
                continue
            if not (tm_range[0] <= s['tm'] <= tm_range[1]):
                continue
            if not (gc_range[0] <= s['gc_content'] <= gc_range[1]):
                continue
            if s['score'] < 50:
                continue
            s['position'] = start
            fw_candidates.append(s)
    
    # Search reverse primers
    rv_candidates = []
    search_start_rv = max(0, target_end - 30)
    search_end_rv = min(len(template), target_end + 30)
    
    for end in range(search_start_rv, search_end_rv):
        for length in range(primer_length[0], primer_length[1] + 1):
            if end - length < 0 or end > len(template):
                continue
            # Reverse primer is reverse complement of template[end-length:end]
            template_region = template[end-length:end]
            primer = reverse_complement(template_region)
            s = score_primer(primer, tm_target=sum(tm_range) / 2, na_conc=na_conc)
            if s is None:
                continue
            if not (tm_range[0] <= s['tm'] <= tm_range[1]):
                continue
            if not (gc_range[0] <= s['gc_content'] <= gc_range[1]):
                continue
            if s['score'] < 50:
                continue
            s['position'] = end  # 3' end position on template
            rv_candidates.append(s)
    
    # Pair them up
    pairs = []
    # Sort candidates by score, take top 10 each
    fw_candidates.sort(key=lambda x: -x['score'])
    rv_candidates.sort(key=lambda x: -x['score'])
    
    for fw in fw_candidates[:15]:
        for rv in rv_candidates[:15]:
            # Check Tm difference
            tm_diff = abs(fw['tm'] - rv['tm'])
            if tm_diff > tm_diff_max:
                continue
            # Check product
            product_length = rv['position'] - fw['position']
            if product_length < 50 or product_length > 5000:
                continue
            # Check cross-dimers
            cross_dimers = find_dimers(fw['sequence'], rv['sequence'],
                                          min_match=4)
            # Score combined
            combined = (fw['score'] + rv['score']) / 2
            combined -= tm_diff * 2
            if cross_dimers:
                worst = any(d['is_3_end'] for d in cross_dimers)
                if worst:
                    combined -= 20
                else:
                    combined -= 5
            pairs.append({
                'forward': fw,
                'reverse': rv,
                'product_length': product_length,
                'tm_diff': tm_diff,
                'cross_dimers': cross_dimers,
                'combined_score': max(0, combined),
            })
    
    pairs.sort(key=lambda x: -x['combined_score'])
    return pairs[:10]


def format_sequence_blocks(seq, block_size=10, line_size=60, show_position=True):
    """Format sequence as readable blocks like NCBI display.
    Returns formatted string with position numbers.
    """
    lines = []
    seq = seq.upper()
    for i in range(0, len(seq), line_size):
        chunk = seq[i:i+line_size]
        blocks = [chunk[j:j+block_size] for j in range(0, len(chunk), block_size)]
        if show_position:
            lines.append('{:>6}  {}'.format(i + 1, ' '.join(blocks)))
        else:
            lines.append(' '.join(blocks))
    return '\n'.join(lines)


# ═══════════════════════════════════════════════════
# RESTRICTION & CLONING — Mol-3
# ═══════════════════════════════════════════════════

def find_restriction_sites(seq, enzymes=None, check_both_strands=True):
    """Find restriction sites in DNA sequence.
    
    enzymes: list of enzyme names or None (use all RESTRICTION_ENZYMES)
    
    Returns list of dicts:
        {enzyme, position, site_seq, strand, cut_position, overhang}
    """
    seq = seq.upper().replace('U', 'T')
    if enzymes is None:
        enzymes = list(RESTRICTION_ENZYMES.keys())
    
    sites = []
    for enz_name in enzymes:
        if enz_name not in RESTRICTION_ENZYMES:
            continue
        enz = RESTRICTION_ENZYMES[enz_name]
        site_pattern = enz['site'].upper()
        
        # Forward strand
        pos = 0
        while True:
            idx = seq.find(site_pattern, pos)
            if idx == -1:
                break
            sites.append({
                'enzyme': enz_name,
                'position': idx,
                'site_seq': site_pattern,
                'strand': '+',
                'cut_position': idx + enz['cut'],
                'overhang': enz['overhang'],
                'site_length': len(site_pattern),
            })
            pos = idx + 1
        
        # Reverse strand (look for reverse complement site)
        if check_both_strands:
            rc_pattern = reverse_complement(site_pattern)
            if rc_pattern != site_pattern:  # not palindromic
                pos = 0
                while True:
                    idx = seq.find(rc_pattern, pos)
                    if idx == -1:
                        break
                    sites.append({
                        'enzyme': enz_name,
                        'position': idx,
                        'site_seq': rc_pattern,
                        'strand': '-',
                        'cut_position': idx + (len(site_pattern) - enz['cut']),
                        'overhang': enz['overhang'],
                        'site_length': len(site_pattern),
                    })
                    pos = idx + 1
    
    sites.sort(key=lambda x: x['position'])
    return sites


def digest_sequence(seq, enzymes, is_circular=False):
    """Perform virtual restriction digest.
    
    enzymes: list of enzyme names (one or many for double-digest etc)
    is_circular: True for plasmids
    
    Returns list of fragments, each:
        {start, end, length, sequence, left_overhang, right_overhang}
    """
    seq = seq.upper().replace('U', 'T')
    sites = find_restriction_sites(seq, enzymes=enzymes, check_both_strands=False)
    
    if not sites:
        # No cuts — return whole sequence as one fragment
        return [{
            'start': 0, 'end': len(seq), 'length': len(seq),
            'sequence': seq, 'left_overhang': None,
            'right_overhang': None,
            'is_intact': True,
        }]
    
    # Get cut positions
    cut_positions = sorted(set(s['cut_position'] for s in sites))
    
    fragments = []
    if is_circular:
        # For circular: fragments between consecutive cuts (wrap around)
        for i in range(len(cut_positions)):
            start = cut_positions[i]
            end = cut_positions[(i + 1) % len(cut_positions)]
            if end > start:
                frag_seq = seq[start:end]
            else:
                # Wraps around
                frag_seq = seq[start:] + seq[:end]
            fragments.append({
                'start': start, 'end': end,
                'length': len(frag_seq),
                'sequence': frag_seq,
                'left_enzyme': next((s['enzyme'] for s in sites
                                       if s['cut_position'] == start), None),
                'right_enzyme': next((s['enzyme'] for s in sites
                                        if s['cut_position'] == end), None),
            })
    else:
        # Linear: fragments are seq[0:cut1], seq[cut1:cut2], ..., seq[cutN:end]
        prev = 0
        for cp in cut_positions:
            fragments.append({
                'start': prev, 'end': cp,
                'length': cp - prev,
                'sequence': seq[prev:cp],
                'left_enzyme': next((s['enzyme'] for s in sites
                                       if s['cut_position'] == prev), None) if prev > 0 else None,
                'right_enzyme': next((s['enzyme'] for s in sites
                                        if s['cut_position'] == cp), None),
            })
            prev = cp
        # Last fragment
        if prev < len(seq):
            fragments.append({
                'start': prev, 'end': len(seq),
                'length': len(seq) - prev,
                'sequence': seq[prev:],
                'left_enzyme': next((s['enzyme'] for s in sites
                                       if s['cut_position'] == prev), None),
                'right_enzyme': None,
            })
    
    # Sort by length descending (typical gel order: largest first)
    fragments_with_sort = list(fragments)
    fragments_with_sort.sort(key=lambda f: -f['length'])
    
    return fragments_with_sort


def gibson_assembly(fragments, overlap_min=15, overlap_max=40):
    """Simulate Gibson assembly — fragments joined by homologous overlaps.
    
    fragments: list of DNA sequences (strings)
    Returns dict:
        {assembled: str (or None if failed),
         overlaps: list of (frag_i, frag_j, overlap_seq, length),
         success: bool, message: str}
    """
    if len(fragments) < 2:
        return {'assembled': None, 'overlaps': [],
                 'success': False, 'message': 'Need at least 2 fragments'}
    
    overlaps = []
    
    # Find overlaps between consecutive fragments
    # Try ordering: pair 0-1, 1-2, ..., (n-1)-0 (circular)
    n = len(fragments)
    found_overlaps = []
    
    for i in range(n):
        frag_a = fragments[i].upper()
        frag_b = fragments[(i + 1) % n].upper()
        # Look for end of frag_a matching start of frag_b
        best_overlap = None
        best_length = 0
        for length in range(overlap_max, overlap_min - 1, -1):
            if length > len(frag_a) or length > len(frag_b):
                continue
            tail = frag_a[-length:]
            head = frag_b[:length]
            if tail == head:
                best_overlap = tail
                best_length = length
                break
        if best_overlap:
            found_overlaps.append({
                'frag_i': i,
                'frag_j': (i + 1) % n,
                'overlap_seq': best_overlap,
                'length': best_length,
            })
        else:
            return {
                'assembled': None,
                'overlaps': found_overlaps,
                'success': False,
                'message': 'No overlap found between fragments {} and {}'.format(
                    i, (i + 1) % n),
            }
    
    # Assemble: concatenate with overlaps removed (only count once)
    assembled = fragments[0].upper()
    for i in range(1, n):
        ov_len = found_overlaps[i - 1]['length']
        # Add next fragment skipping the overlap
        assembled += fragments[i].upper()[ov_len:]
    
    # If circular, last overlap also needs to be removed (already at end+start)
    if n > 1:
        last_ov = found_overlaps[-1]['length']
        # The last overlap is at end of last fragment AND start of first
        # For circular assembly, just verify and report
        pass
    
    return {
        'assembled': assembled,
        'overlaps': found_overlaps,
        'success': True,
        'message': 'Assembled {} bp from {} fragments'.format(
            len(assembled), n),
    }


def estimate_gel_migration(length_bp, gel_pct=1.0):
    """Estimate gel migration distance for a DNA fragment.
    
    Returns relative distance (0=well, 1=bottom of gel).
    Uses log-linear approximation typical of agarose gel.
    
    gel_pct: agarose percentage (0.5-2.0)
    """
    if length_bp <= 0:
        return 0
    # Reference: 1% gel, 1kb migrates to ~0.5 of gel length
    # Smaller fragments migrate further (closer to 1)
    # Empirical: distance ~ 1 - log10(bp) / log10(50000)
    # 100 bp ~0.6, 1000 bp ~0.4, 10000 bp ~0.15
    import math
    bp = max(50, min(50000, length_bp))
    distance = 1.0 - (math.log10(bp) / math.log10(50000)) * 1.1
    # Adjust for gel percentage (higher % = more separation of small)
    distance *= (1.0 + (gel_pct - 1.0) * 0.2)
    return max(0.05, min(0.95, distance))


