def blosum62_score(a, b):
    """Get BLOSUM62 score for pair of amino acids (symmetric)."""
    a, b = a.upper(), b.upper()
    if (a, b) in BLOSUM62:
        return BLOSUM62[(a, b)]
    if (b, a) in BLOSUM62:
        return BLOSUM62[(b, a)]
    return -4  # default mismatch


def needleman_wunsch(seq1, seq2, match=2, mismatch=-1, gap=-2, is_protein=False):
    """Global alignment via Needleman-Wunsch.
    
    Returns dict:
        aligned1, aligned2: aligned strings with '-' for gaps
        score: total alignment score
        identity: % identical positions
        similarity: % similar positions (for protein)
    """
    s1 = seq1.upper()
    s2 = seq2.upper()
    n, m = len(s1), len(s2)
    if n == 0 or m == 0:
        return None
    
    # Limit size for performance
    if n > 5000 or m > 5000:
        return None
    
    # Score function
    if is_protein:
        score_fn = lambda a, b: blosum62_score(a, b)
    else:
        score_fn = lambda a, b: match if a == b else mismatch
    
    # Initialize matrix
    F = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        F[i][0] = i * gap
    for j in range(m + 1):
        F[0][j] = j * gap
    
    # Fill
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            diag = F[i-1][j-1] + score_fn(s1[i-1], s2[j-1])
            up = F[i-1][j] + gap
            left = F[i][j-1] + gap
            F[i][j] = max(diag, up, left)
    
    # Traceback
    a1, a2 = [], []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0:
            diag = F[i-1][j-1] + score_fn(s1[i-1], s2[j-1])
            if F[i][j] == diag:
                a1.append(s1[i-1]); a2.append(s2[j-1])
                i -= 1; j -= 1
                continue
        if i > 0 and F[i][j] == F[i-1][j] + gap:
            a1.append(s1[i-1]); a2.append('-')
            i -= 1
        elif j > 0:
            a1.append('-'); a2.append(s2[j-1])
            j -= 1
        else:
            break
    
    a1 = ''.join(reversed(a1))
    a2 = ''.join(reversed(a2))
    
    # Identity / similarity
    identical = sum(1 for x, y in zip(a1, a2) if x == y and x != '-')
    similar = 0
    if is_protein:
        for x, y in zip(a1, a2):
            if x == '-' or y == '-':
                continue
            if x == y or blosum62_score(x, y) > 0:
                similar += 1
    else:
        similar = identical
    
    aln_len = len(a1)
    identity_pct = 100 * identical / aln_len if aln_len > 0 else 0
    similarity_pct = 100 * similar / aln_len if aln_len > 0 else 0
    
    return {
        'aligned1': a1,
        'aligned2': a2,
        'score': F[n][m],
        'identity': identity_pct,
        'similarity': similarity_pct,
        'length': aln_len,
        'matches': identical,
        'gaps': a1.count('-') + a2.count('-'),
    }


def smith_waterman(seq1, seq2, match=2, mismatch=-1, gap=-2, is_protein=False):
    """Local alignment via Smith-Waterman.
    
    Returns dict like needleman_wunsch + 'start1', 'start2', 'end1', 'end2'.
    """
    s1 = seq1.upper()
    s2 = seq2.upper()
    n, m = len(s1), len(s2)
    if n == 0 or m == 0 or n > 5000 or m > 5000:
        return None
    
    if is_protein:
        score_fn = lambda a, b: blosum62_score(a, b)
    else:
        score_fn = lambda a, b: match if a == b else mismatch
    
    F = [[0] * (m + 1) for _ in range(n + 1)]
    max_score = 0
    max_i, max_j = 0, 0
    
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            diag = F[i-1][j-1] + score_fn(s1[i-1], s2[j-1])
            up = F[i-1][j] + gap
            left = F[i][j-1] + gap
            F[i][j] = max(0, diag, up, left)
            if F[i][j] > max_score:
                max_score = F[i][j]
                max_i, max_j = i, j
    
    # Traceback from max
    a1, a2 = [], []
    i, j = max_i, max_j
    end1, end2 = i, j
    while i > 0 and j > 0 and F[i][j] > 0:
        diag = F[i-1][j-1] + score_fn(s1[i-1], s2[j-1])
        if F[i][j] == diag:
            a1.append(s1[i-1]); a2.append(s2[j-1])
            i -= 1; j -= 1
        elif F[i][j] == F[i-1][j] + gap:
            a1.append(s1[i-1]); a2.append('-')
            i -= 1
        elif F[i][j] == F[i][j-1] + gap:
            a1.append('-'); a2.append(s2[j-1])
            j -= 1
        else:
            break
    
    start1, start2 = i, j
    a1 = ''.join(reversed(a1))
    a2 = ''.join(reversed(a2))
    
    identical = sum(1 for x, y in zip(a1, a2) if x == y and x != '-')
    similar = 0
    if is_protein:
        for x, y in zip(a1, a2):
            if x == '-' or y == '-':
                continue
            if x == y or blosum62_score(x, y) > 0:
                similar += 1
    else:
        similar = identical
    
    aln_len = len(a1)
    return {
        'aligned1': a1,
        'aligned2': a2,
        'score': max_score,
        'identity': 100 * identical / aln_len if aln_len > 0 else 0,
        'similarity': 100 * similar / aln_len if aln_len > 0 else 0,
        'length': aln_len,
        'matches': identical,
        'gaps': a1.count('-') + a2.count('-'),
        'start1': start1, 'start2': start2,
        'end1': end1, 'end2': end2,
    }


def blast_like_search(query, database_seqs, word_size=11, max_results=10,
                        is_protein=False):
    """Simple BLAST-like search: find similar sequences in a database.
    
    database_seqs: list of dicts {name, sequence} or just list of strings
    
    Returns list of dicts:
        {name, score, identity, e_value_estimate, length, alignment}
    """
    if not query:
        return []
    
    # Normalize database
    if database_seqs and isinstance(database_seqs[0], str):
        db = [{'name': 'seq_' + str(i), 'sequence': s}
               for i, s in enumerate(database_seqs)]
    else:
        db = database_seqs
    
    query_u = query.upper()
    results = []
    
    # For each database sequence, find best local alignment
    for entry in db:
        seq = entry.get('sequence', '').upper()
        if not seq or len(seq) < word_size:
            continue
        
        # Quick word filter: does query have any word_size match?
        # (Simplified BLAST seeding)
        has_seed = False
        seed_word_size = min(word_size, len(query_u))
        for k in range(0, len(query_u) - seed_word_size + 1, max(1, seed_word_size // 2)):
            word = query_u[k:k+seed_word_size]
            if word in seq:
                has_seed = True
                break
        if not has_seed:
            continue
        
        # If seed found, do local alignment
        try:
            aln = smith_waterman(query_u, seq, is_protein=is_protein)
            if aln is None:
                continue
            # E-value estimate (simplified)
            # E ~ K * m * n * exp(-λ * S)
            m = len(query_u); n = len(seq)
            S = aln['score']
            import math
            e_value = max(1e-300, m * n * math.exp(-0.3 * S))
            
            results.append({
                'name': entry.get('name', '?'),
                'score': aln['score'],
                'identity': aln['identity'],
                'similarity': aln['similarity'],
                'length': aln['length'],
                'e_value': e_value,
                'alignment': aln,
                'description': entry.get('description', ''),
            })
        except Exception as _exc:
            biosim_log('warn', 'blast_like_search: {}'.format(_exc))
            continue
    
    results.sort(key=lambda r: -r['score'])
    return results[:max_results]


