def codon_optimize(protein_seq, organism='ecoli'):
    """Optimize codon usage for given organism.
    
    Returns optimized DNA sequence using the most frequent codon for each AA.
    """
    if organism not in CODON_USAGE:
        organism = 'ecoli'
    usage = CODON_USAGE[organism]
    
    # Build best-codon-per-AA dict
    best_codon = {}
    for codon, freq in usage.items():
        aa = GENETIC_CODE.get(codon)
        if aa is None or aa == '*':
            continue
        if aa not in best_codon or freq > best_codon[aa][1]:
            best_codon[aa] = (codon, freq)
    
    # Convert protein to DNA using best codons
    result = []
    for aa in protein_seq.upper():
        if aa == '*':
            # Use best stop codon
            best_stop = max(['TAA', 'TAG', 'TGA'], key=lambda c: usage.get(c, 0))
            result.append(best_stop)
        elif aa in best_codon:
            result.append(best_codon[aa][0])
        else:
            result.append('NNN')
    return ''.join(result)


def cai(dna_seq, organism='ecoli'):
    """Codon Adaptation Index — measure of how well-adapted the DNA is.
    
    CAI = 1 means perfect adaptation, 0.5+ is good.
    """
    if organism not in CODON_USAGE:
        organism = 'ecoli'
    usage = CODON_USAGE[organism]
    
    dna_seq = dna_seq.upper().replace('U', 'T')
    if len(dna_seq) % 3 != 0:
        dna_seq = dna_seq[:len(dna_seq) - (len(dna_seq) % 3)]
    if len(dna_seq) == 0:
        return 0.0
    
    # For each AA, find max codon freq (denominator)
    max_per_aa = {}
    for codon, freq in usage.items():
        aa = GENETIC_CODE.get(codon)
        if aa is None or aa == '*':
            continue
        if aa not in max_per_aa or freq > max_per_aa[aa]:
            max_per_aa[aa] = freq
    
    # Geometric mean of relative adaptiveness
    import math
    log_sum = 0
    n_codons = 0
    for i in range(0, len(dna_seq) - 2, 3):
        codon = dna_seq[i:i+3]
        aa = GENETIC_CODE.get(codon)
        if aa is None or aa == '*':
            continue
        w = usage.get(codon, 0)
        max_w = max_per_aa.get(aa, 1)
        if max_w > 0 and w > 0:
            log_sum += math.log(w / max_w)
            n_codons += 1
    
    if n_codons == 0:
        return 0.0
    return math.exp(log_sum / n_codons)


# Amino acid pKa values for pI calculation
AA_PKA = {
    'N_TERM': 9.69,    # N-terminus
    'C_TERM': 2.34,    # C-terminus
    'C': 8.33,         # Cys
    'D': 3.65,         # Asp
    'E': 4.25,         # Glu
    'H': 6.00,         # His
    'K': 10.53,        # Lys
    'R': 12.48,        # Arg
    'Y': 10.07,        # Tyr
}


def calculate_protein_pi(protein_seq):
    """Calculate isoelectric point (pI) of a protein.
    
    Uses Henderson-Hasselbalch and bisection method.
    """
    if not protein_seq:
        return 7.0
    seq = protein_seq.upper().replace('*', '')
    if not seq:
        return 7.0
    
    # Count residues
    n_C = seq.count('C')
    n_D = seq.count('D')
    n_E = seq.count('E')
    n_H = seq.count('H')
    n_K = seq.count('K')
    n_R = seq.count('R')
    n_Y = seq.count('Y')
    
    def net_charge(pH):
        # Positive groups (cationic at low pH)
        pos = (1 / (1 + 10 ** (pH - AA_PKA['N_TERM']))
                + n_H * (1 / (1 + 10 ** (pH - AA_PKA['H'])))
                + n_K * (1 / (1 + 10 ** (pH - AA_PKA['K'])))
                + n_R * (1 / (1 + 10 ** (pH - AA_PKA['R']))))
        # Negative groups (anionic at high pH)
        neg = (1 / (1 + 10 ** (AA_PKA['C_TERM'] - pH))
                + n_D * (1 / (1 + 10 ** (AA_PKA['D'] - pH)))
                + n_E * (1 / (1 + 10 ** (AA_PKA['E'] - pH)))
                + n_C * (1 / (1 + 10 ** (AA_PKA['C'] - pH)))
                + n_Y * (1 / (1 + 10 ** (AA_PKA['Y'] - pH))))
        return pos - neg
    
    # Bisection
    low, high = 0.0, 14.0
    for _ in range(50):
        mid = (low + high) / 2
        if net_charge(mid) > 0:
            low = mid
        else:
            high = mid
    return (low + high) / 2


def calculate_extinction_coefficient(protein_seq):
    """Calculate molar extinction coefficient at 280 nm (M^-1 cm^-1).
    
    Based on Tyr (1490), Trp (5500), and Cys disulfide (125).
    Returns (oxidized form, reduced form) tuple.
    """
    seq = protein_seq.upper().replace('*', '')
    n_W = seq.count('W')
    n_Y = seq.count('Y')
    n_C = seq.count('C')
    # Oxidized (assuming all Cys form disulfide bonds in pairs)
    e_oxidized = n_W * 5500 + n_Y * 1490 + (n_C // 2) * 125
    # Reduced (free Cys, no contribution)
    e_reduced = n_W * 5500 + n_Y * 1490
    return e_oxidized, e_reduced


def hydrophobicity_profile(protein_seq, window=9):
    """Kyte-Doolittle hydrophobicity profile (sliding window average).
    
    Returns list of (position, hydrophobicity_score).
    """
    seq = protein_seq.upper().replace('*', '')
    if len(seq) < window:
        return []
    points = []
    half = window // 2
    for i in range(len(seq)):
        # Window centered at i
        start = max(0, i - half)
        end = min(len(seq), i + half + 1)
        sub = seq[start:end]
        vals = [AA_PROPERTIES.get(aa, {'hydro': 0})['hydro']
                 for aa in sub if aa in AA_PROPERTIES]
        if vals:
            avg = sum(vals) / len(vals)
            points.append((i, avg))
    return points


def predict_rna_structure_nussinov(seq, min_loop=3):
    """Simple RNA secondary structure prediction via Nussinov algorithm.
    
    Maximizes number of base pairs. Watson-Crick + wobble pairs.
    
    Returns dict:
        {sequence: str, dot_bracket: str, pairs: [(i, j), ...], score: int}
    """
    seq = seq.upper().replace('T', 'U')
    n = len(seq)
    if n < min_loop + 2:
        return {
            'sequence': seq,
            'dot_bracket': '.' * n,
            'pairs': [],
            'score': 0,
        }
    
    # Limit size for performance
    if n > 500:
        return None
    
    # Valid pairs
    def can_pair(a, b):
        pairs = {('A','U'),('U','A'),('G','C'),('C','G'),
                  ('G','U'),('U','G')}  # Wobble allowed
        return (a, b) in pairs
    
    # DP: M[i][j] = max pairs in seq[i..j]
    M = [[0] * n for _ in range(n)]
    
    for length in range(min_loop + 1, n):
        for i in range(n - length):
            j = i + length
            # Option 1: j unpaired
            M[i][j] = M[i][j-1]
            # Option 2: j paired with some k in [i, j-min_loop-1]
            for k in range(i, j - min_loop):
                if can_pair(seq[k], seq[j]):
                    left = M[i][k-1] if k > i else 0
                    right = M[k+1][j-1] if k + 1 <= j - 1 else 0
                    score = left + right + 1
                    if score > M[i][j]:
                        M[i][j] = score
    
    # Traceback
    pairs = []
    def trace(i, j):
        if i >= j:
            return
        if M[i][j] == M[i][j-1]:
            trace(i, j - 1)
            return
        for k in range(i, j - min_loop):
            if can_pair(seq[k], seq[j]):
                left = M[i][k-1] if k > i else 0
                right = M[k+1][j-1] if k + 1 <= j - 1 else 0
                if M[i][j] == left + right + 1:
                    pairs.append((k, j))
                    if k > i: trace(i, k - 1)
                    if k + 1 <= j - 1: trace(k + 1, j - 1)
                    return
    
    trace(0, n - 1)
    
    # Build dot-bracket
    dot_bracket = ['.'] * n
    for (i, j) in pairs:
        dot_bracket[i] = '('
        dot_bracket[j] = ')'
    
    # ΔG estimate (very rough: -2 kcal/mol per pair)
    dG_estimate = -2.0 * len(pairs)
    
    return {
        'sequence': seq,
        'dot_bracket': ''.join(dot_bracket),
        'pairs': pairs,
        'score': len(pairs),
        'dG_estimate': dG_estimate,
    }


def try_esmfold(protein_seq, max_length=350):
    """Try to predict protein structure using ESMFold if PyTorch available.
    
    Returns dict {pdb_string, message, success} or None.
    Falls back gracefully if PyTorch / transformers / esm not installed.
    """
    if len(protein_seq) > max_length:
        return {
            'success': False,
            'message': 'Sequence too long ({} > {} aa)'.format(
                len(protein_seq), max_length),
            'pdb_string': None,
        }
    
    # Try to import torch
    try:
        import torch
    except ImportError as _exc:
        biosim_log('warn', 'try_esmfold: {}'.format(_exc))
        return {
            'success': False,
            'message': 'PyTorch not installed',
            'pdb_string': None,
        }
    
    # Try esm package
    try:
        # The ESMFold model is large (~1GB), not bundled
        # Just check if it's importable
        import esm  # noqa
        return {
            'success': False,
            'message': 'ESMFold model not bundled. Visit https://esmatlas.com/'
                        ' for online predictions of any sequence.',
            'pdb_string': None,
            'esm_available': True,
        }
    except ImportError as _exc:
        biosim_log('info', 'try_esmfold: {}'.format(_exc))
    
    return {
        'success': False,
        'message': 'ESMFold not available. Use ESMAtlas.com (online) for predictions.',
        'pdb_string': None,
    }

